const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 8":["כָּל הַמּוּמִין הַמְיֻחָדִין בָּאָדָם תִּשְׁעִים וְזֶהוּ פְּרָטָן. שְׁמוֹנָה בָּרֹאשׁ וְאֵלּוּ הֵן. מִי שֶׁאֶמְצַע קָדְקֳדוֹ שׁוֹקֵעַ לְמַטָּה כְּמוֹ שֶׁדְּחָקוֹ בְּיָדוֹ. מִי שֶׁאֶמְצַע קָדְקֳדוֹ עוֹלֶה לְמַעְלָה כְּמוֹ בֵּיצָה. מִי שֶׁפְּאַת רֹאשׁוֹ יוֹצֵא כְּנֶגֶד פָּנָיו כְּמוֹ מַקֶּבֶת. מִי שֶׁרֹאשׁוֹ יוֹצֵא מֵאֲחוֹרָיו כְּנֶגֶד עָרְפּוֹ. מִי שֶׁרֹאשׁוֹ רָחָב וְיוֹצֵא מִכָּאן וּמִכָּאן עַד שֶׁתִּמְצָא רֹאשׁוֹ עַל צַוָּארוֹ כְּמוֹ רֹאשׁ הַלֶּפֶת עַל הֶעָלִין שֶׁלּוֹ. הַקֵּרֵחַ שֶׁאֵין בְּכָל רֹאשׁוֹ שֵׂעָר כָּל עִקָּר. וְאִם יֵשׁ בּוֹ שִׁיטָה שֶׁל שֵׂעָר מֻקֶּפֶת מֵאֲחוֹרָיו מֵאֹזֶן לְאֹזֶן כָּשֵׁר. מִי שֶׁהָיָה הַשֵּׂעָר מַקִּיף מֵאֹזֶן לְאֹזֶן מִלְּפָנָיו בִּלְבַד וּשְׁאָר הָרֹאשׁ קֵרֵחַ הוּא הֲרֵי הוּא פָּסוּל. מִי שֶׁהָיָה הַשֵּׂעָר שֶׁלּוֹ מַקִּיף אֶת כָּל הָרֹאשׁ סָבִיב מִלְּפָנָיו וּמֵאַחֲרָיו וְאֵין שָׁם שֵׂעָר בְּאֶמְצַע גַּם זֶה קֵרֵחַ וּפָסוּל:","שְׁנַיִם בַּצַּוָּאר וְאֵלּוּ הֵם. מִי שֶׁצַּוָּארוֹ שׁוֹקֵעַ הַרְבֵּה עַד שֶׁנִּמְצָא רֹאשׁוֹ כְּאִלּוּ הוּא מֻנָּח עַל כְּתֵפָיו. מִי שֶׁצַּוָּארוֹ אָרֹךְ הַרְבֵּה עַד שֶׁנִּרְאֶה כְּשָׁמוּט מִבֵּין כְּתֵפָיו:","אַרְבָּעָה בָּאֹזֶן וְאֵלּוּ הֵן. מִי שֶׁשְּׁתֵּי אָזְנָיו קְטַנּוֹת הַרְבֵּה. מִי שֶׁשְּׁתֵּי אָזְנָיו נְפוּחוֹת דּוֹמוֹת לִסְפוֹג. מִי שֶׁאָזְנָיו מְדֻלְדָּלוֹת לְמַטָּה. מִי שֶׁאַחַת מֵאָזְנָיו מְשֻׁנָּה מֵחֲבֶרְתָּהּ בְּמַרְאֶהָ:","חֲמִשָּׁה בַּגְּבִינִים וְאֵלּוּ הֵן. מִי שֶׁאֵין לוֹ שֵׂעָר בִּגְבִינָיו וְהוּא (ויקרא כא כ) \"גִּבֵּן\" הָאָמוּר בַּתּוֹרָה. מִי שֶׁגְּבִינָיו שׁוֹכְבִין. מִי שֶׁאֵין לוֹ אֶלָּא גָּבִין אֶחָד. מִי שֶׁיֵּשׁ לוֹ גְּבִינִין יֶתֶר עַל שְׁנַיִם. מִי שֶׁאֶחָד מִגְּבִינָיו מְשֻׁנֶּה מֵחֲבֵרוֹ בֵּין שֶׁשְּׂעָרוֹ שֶׁל זֶה אָרֹךְ וּשְׂעָרוֹ שֶׁל זֶה קָצָר בֵּין שֶׁשְּׂעָרוֹ שֶׁל אֶחָד שָׁחֹר וּשְׂעָרוֹ הַשֵּׁנִי לָבָן אוֹ אָדֹם הוֹאִיל וְיֵשׁ בֵּינֵיהֶם שִׁנּוּי זֶה הֲרֵי זֶה פָּסוּל:","אַרְבָּעָה בְּרִיס הָעַיִן וְאֵלּוּ הֵן. מִי שֶׁאֵין לוֹ שֵׂעָר כְּלָל בְּרִיסֵי עֵינָיו. מִי שֶׁשְּׂעַר רִיסֵי עֵינָיו מְרֻבֶּה מְעֻבֶּה הַרְבֵּה. מִי שֶׁשְּׂעַר אֶחָד מֵרִיסֵי עֵינָיו מְשֻׁנֶּה מִשְּׂעַר רִיס אַחֵר כְּגוֹן שֶׁאֶחָד שָׁחֹר וְאֶחָד לָבָן אוֹ שֶׁאֶחָד נוֹשֵׁר וְהַשֵּׁנִי מְעֻבֶּה. מִי שֶׁעַפְעַפָּיו סְגוּרוֹת מְעַט וְאֵינָן נִפְתָּחוֹת הַרְבֵּה כִּשְׁאָר כָּל הָאָדָם:","אַחַד עָשָׂר בָּעֵינַיִם וְאֵלּוּ הֵן. מִי שֶׁהָיוּ שְׁתֵּי עֵינָיו לְמַעְלָה מִן הַמָּקוֹם הָרָאוּי לָהֶם קְרוֹבוֹת מִפַּדַּחְתּוֹ. מִי שֶׁהָיוּ שְׁתֵּי עֵינָיו לְמַטָּה מִמָּקוֹם הָרָאוּי לָהֶם. מִי שֶׁהָיוּ שְׁתֵּי עֵינָיו עֲגוּלוֹת וְאֵינָם נִמְשָׁכוֹת בָּאֹרֶךְ מְעַט מִשְּׁאָר הָעֵינַיִם. מִי שֶׁעֵינָיו מוּזָרוֹת וְהֵן יוֹצְאוֹת כְּעֵינֵי הַנָּמֵר וּכְמִי שֶׁהוּא מִסְתַּכֵּל בְּעֵת שֶׁכּוֹעֵס כַּעַס הַרְבֵּה. מִי שֶׁעֵינָיו גְּדוֹלוֹת הַרְבֵּה כְּשֶׁל עֵגֶל. מִי שֶׁעֵינָיו קְטַנּוֹת כְּשֶׁל אַוָּז. מִי שֶׁדְּמָעָיו זוֹלְפוֹת תָּמִיד. מִי שֶׁלַּחְלוּחִית נִמְשֶׁכֶת מֵרֹאשׁ עֵינוֹ מִכְּנֶגֶד הַחֹטֶם אוֹ מִזְּנַב עֵינוֹ מִצַּד צְדָעָיו. מִי שֶׁמְּקַבֵּץ רִיסֵי עֵינָיו וְעוֹצְמָן מְעַט בְּשָׁעָה שֶׁרוֹאֶה אוֹר אוֹ בְּשָׁעָה שֶׁהוּא רוֹצֶה לְדַקְדֵּק בִּרְאִיָּה. מִי שֶׁרְאִיַּת עֵינוֹ מְעֻרְבֶּבֶת עַד שֶׁרוֹאֶה אֶת הַחֶדֶר וְאֶת הָעֲלִיָּה כְּאַחַת. וְיִוָּדַע דָּבָר זֶה בְּעֵת שֶׁיְּדַבֵּר עִם חֲבֵרוֹ וְנִרְאֶה כְּאִלּוּ הוּא מִסְתַּכֵּל בְּאִישׁ אַחֵר. מִי שֶׁאַחַת מֵעֵינָיו מְשֻׁנָּה מֵחֲבֶרְתָּהּ בֵּין בִּמְקוֹמָהּ בֵּין בְּמַרְאֶהָ כְּגוֹן שֶׁהָיְתָה אַחַת שְׁחֹרָה וְאַחַת פְּתוּכָה אוֹ אַחַת קְטַנָּה וְאַחַת גְּדוֹלָה הוֹאִיל וְיֵשׁ בֵּין שְׁתֵּיהֶן שִׁנּוּי מִכָּל מָקוֹם פָּסוּל:","שִׁשָּׁה בַּחֹטֶם וְאֵלּוּ הֵן. מִי שֶׁעִקַּר חָטְמוֹ שׁוֹקֵעַ אַף עַל פִּי שֶׁאֵינוֹ כּוֹחֵל שְׁתֵּי עֵינָיו כְּאַחַת וְזֶה (ויקרא כא יח) \"חָרוּם\" הָאָמוּר בַּתּוֹרָה. מִי שֶׁאֶמְצַע חָטְמוֹ בּוֹלֵט לְמַעְלָה. מִי שֶׁעֹקֶץ חָטְמוֹ נוֹטֵף לְמַטָּה. מִי שֶׁחָטְמוֹ עָקֹם לְצַד אֶחָד. מִי שֶׁחָטְמוֹ גָּדוֹל מֵאֵיבָרָיו. מִי שֶׁחָטְמוֹ קָטָן מֵאֵיבָרָיו. וְכֵיצַד מְשַׁעֲרִין אוֹתוֹ. בְּאֶצְבַּע קְטַנָּה שֶׁעַל יָדוֹ. אִם הָיָה חָטְמוֹ גָּדוֹל מִמֶּנָּה אוֹ קָטָן מִמֶּנָּה הֲרֵי זֶה מוּם:","שְׁלֹשָׁה בַּשְּׂפָתַיִם וְאֵלּוּ הֵן. מִי שֶׁשְּׂפָתוֹ הָעֶלְיוֹנָה עוֹדֶפֶת עַל הַתַּחְתּוֹנָה. מִי שֶׁשְּׂפָתוֹ הַתַּחְתּוֹנָה עוֹדֶפֶת עַל הָעֶלְיוֹנָה. מִי שֶׁפִּיו רָפוּי וְרִירוֹ יוֹרֵד מִפִּיו:","שְׁלֹשָׁה בַּבֶּטֶן וְאֵלּוּ הֵן. מִי שֶׁכְּרֵסוֹ צָבָה [א.] מִי שֶׁטִּבּוּרוֹ יוֹצֵא וְאֵינוֹ שׁוֹקֵעַ כִּשְׁאָר בְּנֵי אָדָם. מִי שֶׁדָּדָיו שׁוֹכְבִין עַל בִּטְנוֹ כְּדָדֵי אִשָּׁה:","שְׁלֹשָׁה בַּגַּב וְאֵלּוּ הֵן. מִי שֶׁשִּׁדְרָתוֹ עֲקֻמָּה. מִי שֶׁיָּצָאתָה חֻלְיָא מִשִּׁדְרָתוֹ בֵּין שֶׁבָּלְטָה לַחוּץ אוֹ נִכְנְסָה לִפְנִים אוֹ נָטְתָה לַצְּדָדִין וְזֶהוּ בַּעַל חֲטוֹטֶרֶת. מִי שֶׁתָּפַח בָּשָׂר בְּגַבּוֹ וְנַעֲשָׂה כַּחֲטוֹטֶרֶת אַף עַל פִּי שֶׁלֹּא זָזָה חוּלְיָא מִמְּקוֹמָהּ הֲרֵי זֶה מוּם:","שִׁשָּׁה בַּיָּדַיִם וְאֵלּוּ הֵן. מִי שֶׁיֵּשׁ בְּיָדוֹ אֶצְבַּע יְתֵרָה בְּאֶצְבְּעוֹת יָדָיו אֲפִלּוּ הָיוּ שֵׁשׁ וְשֵׁשׁ. וְאִם חָתַךְ אֶת הַיְתֵרָה כָּשֵׁר. וְאִם הָיָה בָּהּ עֶצֶם אֲפִלּוּ חֲתָכָהּ פָּסוּל. מִי שֶׁחָסֵר אֶצְבַּע מִיָּדוֹ. מִי שֶׁשְּׁתֵּי אֶצְבְּעוֹת יָדָיו קְלוּטוֹת עַד לְמַטָּה מִן הַפֶּרֶק. וְאִם חֲתָכָן וְהִפְרִישָׁן עַד הַפֶּרֶק כָּשֵׁר. בְּאֵיזֶה פֶּרֶק אָמְרוּ בְּפֶרֶק רִאשׁוֹן הַסָּמוּךְ לְכַף הַיָּד. מִי שֶׁאֶצְבְּעוֹתָיו מֻרְכָּבוֹת זוֹ עַל גַּבֵּי זוֹ. מִי שֶׁפִּיקָה יוֹצֵאת מִגּוּדָלוֹ. מִי שֶׁהוּא אִטֵּר יַד יְמִינוֹ. וְאִם הָיָה שׁוֹלֵט בִּשְׁתֵּי יָדָיו כָּשֵׁר:","אַרְבָּעָה בְּאֵיבְרֵי הַזָּרַע וְאֵלּוּ הֵן. מִי שֶׁכִּיס הַבֵּיצִים גָּדוֹל וְאָרֹךְ עַד שֶׁמַּגִּיעַ לְאַרְכֻּבּוֹתָיו. מִי שֶׁהַגִּיד שֶׁלּוֹ אָרֹךְ עַד שֶׁמַּגִּיעַ לְאַרְכּוּבוֹתָיו. מִי שֶׁנִּמְרְחוּ אֲשָׁכָיו וְהֵם הַכִּיס שֶׁל בֵּיצִים. [מִי שֶׁרוּחַ בַּאֲשָׁכָיו] וְהוּא (ויקרא כא כ) \"מְרוֹחַ אָשֶׁךְ\" הָאָמוּר בַּתּוֹרָה:","חֲמִשָּׁה עָשָׂר בַּשּׁוֹקַיִם וּבָרַגְלַיִם וְאֵלּוּ הֵן. מִי שֶׁשּׁוֹקָיו עֲקֻמּוֹת עַד שֶׁמְּחַבֵּר רֶגֶל לְרֶגֶל וְאֵין אַרְכֻּבּוֹתָיו נוֹגְעוֹת זוֹ בְּזוֹ. מִי שֶׁפִּיקָתוֹ יוֹצֵאת וְהַפִּיקָה הִיא הָעֶצֶם הֶעָגל שֶׁלְּמַעְלָה מִן הֶעָקֵב מִצַּד פְּנִים וְהוּא דּוֹמֶה לְפִיקָה שֶׁטּוֹוֹת בָּהּ הַנָּשִׁים. מִי שֶׁעֲקֵבוֹ יוֹצֵא לַאֲחוֹרָיו עַד שֶׁנִּמְצָא הַשּׁוֹק כְּאִלּוּ הוּא בְּאֶמְצַע רַגְלוֹ עוֹמֵד. מִי שֶׁפַּרְסוֹתָיו רְחָבוֹת כְּשֶׁל אַוָּז אַף עַל פִּי שֶׁאֵינָן קְלוּטוֹת כְּשֶׁל אַוָּז. מִי שֶׁפִּיקָה יוֹצְאָה מִגּוּדָלוֹ. מִי שֶׁיֵּשׁ בְּרַגְלוֹ אֶצְבַּע יְתֵרָה אֲפִלּוּ שֵׁשׁ וְשֵׁשׁ. וְאִם חֲתָכָהּ כָּשֵׁר וְהוּא שֶׁלֹּא יִהְיֶה בָּהּ עֶצֶם. מִי שֶׁחָסֵר אַחַת מֵאֶצְבְּעוֹת רַגְלָיו. מִי שֶׁאֶצְבְּעוֹתָיו מֻרְכָּבוֹת זוֹ עַל גַּבֵּי זוֹ. מִי שֶׁהָיוּ אֶצְבְּעוֹת רַגְלָיו קְלוּטוֹת עַד לְמַטָּה מִן הַפֶּרֶק. וְאִם הָיוּ עַד הַפֶּרֶק אוֹ שֶׁחֲתָכָן וְהִפְרִישָׁן כָּשֵׁר. מִי שֶׁרַגְלוֹ כֻּלָּהּ שָׁוָה שֶׁנִּמְצָא רֹחַב פַּס אֶצְבְּעוֹתָיו כְּרֹחַב עֲקֵבוֹ וּכְאִלּוּ הִיא חֲתִיכָה שָׁוָה. מִי שֶׁרַגְלוֹ עֲקוּמָה דּוֹמָה לְמַגָּל שֶׁנִּמְצָא פַּס רַגְלוֹ שֶׁיֵּשׁ בּוֹ הָאֶצְבָּעוֹת עִם עֲקֵבוֹ כְּאִלּוּ הֵם שְׁנֵי רָאשֵׁי הַקֶּשֶׁת. מִי שֶׁרַגְלוֹ חֲלוּלָה וְהוּא שֶׁיִּהְיֶה אֶמְצָעָהּ גָּבוֹהַּ מֵעַל הָאָרֶץ וְנִמְצָא כְּשֶׁעוֹמֵד עוֹמֵד עַל עֲקֵבוֹ וְעַל אֶצְבְּעוֹת רַגְלָיו. הַמַּקִּישׁ בְּקַרְסֻלָּיו בְּעֵת שֶׁמְּהַלֵּךְ. מִי שֶׁמַּקִּישׁ בְּאַרְכֻּבּוֹתָיו בְּעֵת שֶׁמְּהַלֵּךְ. מִי שֶׁהוּא אִטֵּר בְּרֶגֶל יְמִינוֹ:","אַרְבָּעָה בְּכָל הַגּוּף וְאֵלּוּ הֵן. מִי שֶׁגּוּפוֹ גָּדוֹל מֵאֵיבָרָיו. מִי שֶׁגּוּפוֹ קָטָן מֵאֵיבָרָיו. הָאָרֹךְ בְּיוֹתֵר. הַנַּנָּס וְהוּא הַקָּצָר בְּיוֹתֵר עַד שֶׁיִּהְיוּ מֻפְלָגִין מִשְּׁאָר הָעָם:","שְׁמוֹנָה בְּעוֹר הַבָּשָׂר וְאֵלּוּ הֵן. הַכּוּשִׁי. הַלָּבָן בְּיוֹתֵר כְּמוֹ גְּבִינָה. הָאָדֹם כְּשָׁנִי. בַּעֲלֵי נְגָעִים טְהוֹרִים שֶׁנִּשְׁתַּנָּה הָעוֹר מֵחֲמַת עַצְמוֹ כְּמוֹ הַבֹּהַק. שֶׁנִּשְׁתַּנָּה הָעוֹר מֵחֲמַת דָּבָר אַחֵר כְּגוֹן צָרֶבֶת הַמִּכְוָה וְזֶה בִּכְלַל נְגָעִים טְהוֹרִין. מִי שֶׁהָיְתָה בְּעוֹר פָּנָיו שׁוּמָא שֶׁיֵּשׁ בָּהּ שֵׂעָר אַף עַל פִּי שֶׁאֵינָהּ כְּאִסָּר אֶלָּא כָּל שֶׁהוּא. מִי שֶׁהָיְתָה בְּעוֹר פָּנָיו שׁוּמָא כְּאִסָּר אוֹ יוֹתֵר. בַּעֲלֵי הַדִּלְדּוּלִין וְהוּא שֶׁיִּדַּלְדֵּל הָעוֹר וְהַבָּשָׂר אוֹ הַלַּחְלוּחִית שֶׁיֵּשׁ בָּעוֹר שֶׁנִּדַּלְדֵּל בְּאֵי זֶה מָקוֹם שֶׁיִּהְיֶה מִכָּל הַגּוּף הֲרֵי זֶה מוּם:","וְעוֹד יֵשׁ שָׁם בָּאָדָם אַרְבָּעָה מוּמִין אֲחֵרִים וְאֵלּוּ הֵן. הַחֵרֵשׁ. הַשּׁוֹטֶה. וְהַנִּכְפֶּה אֲפִלּוּ לְיָמִים רַבִּים. מִי שֶׁרוּחַ רָעָה מְבַעַתְּתוֹ תָּמִיד אוֹ בְּעִתִּים יְדוּעִים:","נִמְצְאוּ כָּל הַמּוּמִין הַפּוֹסְלִין בְּכֹהֲנִים מֵאָה וְאַרְבָּעִים וְזֶהוּ כְּלָלָם. שְׁמוֹנָה בָּרֹאשׁ. וּשְׁנַיִם בַּצַּוָּאר. וְתִשְׁעָה בָּאָזְנַיִם. וַחֲמִשָּׁה בַּגְּבִינִים. וְשִׁבְעָה בְּרִיס הָעַיִן. וְתִשְׁעָה עָשָׂר בָּעֵינַיִם. וְתִשְׁעָה בַּחֹטֶם. וְתִשְׁעָה בַּפֶּה. וּשְׁלֹשָׁה בַּבֶּטֶן. וּשְׁלֹשָׁה בַּגַּב. וְשִׁבְעָה בַּיָּדַיִם. וְשִׁשָּׁה עָשָׂר בְּאֵיבְרֵי הַזֶּרַע. וְעֶשְׂרִים בָּרַגְלַיִם. וּשְׁמוֹנָה בְּכָל הַגּוּף. וּשְׁמוֹנָה בְּעוֹר הַבָּשָׂר. וְשִׁבְעָה בְּכֹחַ הַגּוּף וְרֵיחוֹ. וּכְבָר נִפְרְטוּ כֻּלָּן אֶחָד אֶחָד. וְאֵלּוּ פָּסְלוּ מִפְּנֵי מַרְאִית הָעַיִן. מִי שֶׁנָּשְׁרוּ רִיסֵי עֵינָיו אַף עַל פִּי שֶׁנִּשְׁאַר הַשֵּׂעָר בְּעִקָּרָן. וּמִי שֶׁנִּטְּלוּ שִׁנָּיו:"],"Mishneh Torah, Appraisals and Devoted Property 1":["הָעֲרָכִים הֵם נֵדֶר מִכְּלַל נִדְרֵי הֶקְדֵּשׁ. שֶׁנֶּאֱמַר (ויקרא כז ב) \"אִישׁ כִּי יַפְלִא נֶדֶר בְּעֶרְכְּךָ נְפָשֹׁת לַה'\". לְפִיכָךְ חַיָּבִין עֲלֵיהֶן מִשּׁוּם (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\" וְ(דברים כג כב) \"לֹא תְאַחֵר לְשַׁלְּמוֹ\" וּמִשּׁוּם (במדבר ל ג) \"כְּכָל הַיֹּצֵא מִפִּיו יַעֲשֶׂה\":","מִצְוַת עֲשֵׂה לָדוּן בְּדִינֵי עֲרָכִין כַּאֲשֶׁר מְפֹרָשׁ בַּתּוֹרָה. וְאֶחָד הָאוֹמֵר עֶרְכִּי עָלַי. אוֹ הָאוֹמֵר עֵרֶךְ זֶה עָלַי. אוֹ עֵרֶךְ פְּלוֹנִי עָלַי. נוֹתֵן הָעֵרֶךְ לְפִי שְׁנֵי הַנֶּעֱרָךְ וְהוּא הַדָּבָר הַקָּצוּב שֶׁבַּתּוֹרָה לֹא פָּחוֹת וְלֹא יֶתֶר:","וְכַמָּה הוּא הָעֵרֶךְ. אִם הָיָה הַנֶּעֱרָךְ בֶּן שְׁלֹשִׁים יוֹם אוֹ פָּחוֹת אֵין לוֹ עֵרֶךְ וְהָאוֹמֵר עָלָיו עֵרֶךְ זֶה עָלַי הֲרֵי זֶה כְּאוֹמֵר עֵרֶךְ כְּלִי זֶה עָלַי וְאֵינוֹ חַיָּב כְּלוּם. הָיָה מִבֶּן אֶחָד וּשְׁלֹשִׁים יוֹם עַד בֶּן חָמֵשׁ שָׁנִים גְּמוּרוֹת עֵרֶךְ הַזָּכָר חֲמִשָּׁה שְׁקָלִים וְהַנְּקֵבָה שְׁלֹשָׁה שְׁקָלִים. מִשֶּׁנִּכְנַס בִּשְׁנַת שֵׁשׁ יוֹם אֶחָד עַד שֶׁיַּשְׁלִים שְׁנַת עֶשְׂרִים עֵרֶךְ הַזָּכָר עֶשְׂרִים שְׁקָלִים וְהַנְּקֵבָה עֲשָׂרָה שְׁקָלִים. מִשֶּׁיִּכָּנֵס בִּשְׁנַת אַחַת וְעֶשְׂרִים יוֹם עַד שֶׁיַּשְׁלִים שְׁנַת שִׁשִּׁים עֵרֶךְ הַזָּכָר חֲמִשִּׁים שְׁקָלִים וְהַנְּקֵבָה שְׁלֹשִׁים שְׁקָלִים. וּמִשֶּׁיִּכָּנֵס בִּשְׁנַת אַחַת וְשִׁשִּׁים יוֹם עַד יוֹם מוֹתוֹ אֲפִלּוּ חָיָה כַּמָּה שָׁנִים עֵרֶךְ הַזָּכָר חֲמִשָּׁה עָשָׂר שְׁקָלִים וְהַנְּקֵבָה עֲשָׂרָה שְׁקָלִים:","כָּל הַשָּׁנִים הָאֵלּוּ מֵעֵת לְעֵת מִיּוֹם הַלֵּדָה. וְכָל הַשְּׁקָלִים בְּשֶׁקֶל הַקֹּדֶשׁ וְהוּא מִשְׁקַל שְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים שְׂעוֹרָה מִכֶּסֶף טָהוֹר. וּכְבָר הוֹסִיפוּ עָלָיו וְעָשׂוּ אוֹתוֹ סֶלַע כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת שְׁקָלִים:","טֻמְטוּם וְאַנְדְּרוֹגִינוּס אֵין לָהֶם עֵרֶךְ שֶׁלֹּא קָצְבָה תּוֹרָה עֵרֶךְ אֶלָּא לְזָכָר וַדַּאי אוֹ לִנְקֵבָה וַדָּאִית. לְפִיכָךְ טֻמְטוּם וְאַנְדְּרוֹגִינוּס שֶׁאָמַר עֶרְכִּי עָלַי אוֹ שֶׁהֶעֱרִיכוֹ אַחֵר אֵינוֹ חַיָּב כְּלוּם:","הָעַכּוּ\"ם נֶעֱרָךְ אֲבָל אֵינוֹ מַעֲרִיךְ. כֵּיצַד. עַכּוּ\"ם שֶׁאָמַר עֶרְכִּי עָלַי אוֹ עֵרֶךְ יִשְׂרָאֵל זֶה עָלַי לֹא אָמַר כְּלוּם. וְיִשְׂרָאֵל שֶׁאָמַר עֵרֶךְ עַכּוּ\"ם זֶה עָלַי אוֹ עֵרֶךְ פְּלוֹנִי הָעַכּוּ\"ם עָלַי נוֹתֵן לְפִי שְׁנֵי הָעַכּוּ\"ם הַנֶּעֱרָךְ. וְכֵן הַמַּעֲרִיךְ אֶת הַחֵרֵשׁ וְאֶת הַשּׁוֹטֶה חַיָּב וְנוֹתֵן לְפִי שָׁנָיו:","הָעֶבֶד נֶעֱרָךְ וְעוֹרֵךְ כִּשְׁאָר יִשְׂרָאֵל. וְאִם יִפָּדֶה וְהָיָה לוֹ יִתֵּן עֵרֶךְ שֶׁנָּדַר:","אֶחָד הַמַּעֲרִיךְ אֶת הַיָּפֶה הַבָּרִיא וְאֶחָד הַמַּעֲרִיךְ אֶת הַכָּעוּר הַחוֹלֶה. אֲפִלּוּ הָיָה הַנֶּעֱרָךְ מֻכֶּה שְׁחִין אוֹ סוּמָא אוֹ גִּדֵּם וְיֵשׁ בּוֹ כָּל מוּם נוֹתֵן לְפִי שָׁנָיו כְּמוֹ שֶׁכָּתוּב בַּתּוֹרָה:","הַדָּמִים אֵינָן כַּעֲרָכִין. כֵּיצַד. הָאוֹמֵר דָּמַי עָלַי אוֹ דְּמֵי זֶה עָלַי אוֹ דְּמֵי פְּלוֹנִי עָלַי אֲפִלּוּ הָיָה אוֹתוֹ פְּלוֹנִי קָטָן בֶּן יוֹמוֹ אוֹ טֻמְטוּם וְאַנְדְּרוֹגִינוּס אוֹ עַכּוּ\"ם נוֹתֵן מַה שֶּׁהוּא שְׁוֵה דִּינָר אוֹ אֶלֶף כְּאִלּוּ הוּא עֶבֶד הַנִּמְכָּר בַּשּׁוּק:","וְהָעֲרָכִים כֻּלָּן וְהַדָּמִים הַכּל סְתָמָן לְבֶדֶק הַבַּיִת וְיִפְּלוּ הַכּל לַלִּשְׁכָּה שֶׁהָיְתָה בַּמִּקְדָּשׁ מוּכֶנֶת לְקָדְשֵׁי בֶּדֶק הַבַּיִת:","עַכּוּ\"ם שֶׁאָמַר דָּמַי עָלַי אוֹ דְּמֵי פְּלוֹנִי עָלַי נוֹתֵן כְּפִי נִדְרוֹ וְאֵינוֹ נוֹפֵל לַלִּשְׁכָּה שֶׁאֵין מְקַבְּלִין מִן הָעַכּוּ\"ם נְדָבָה אוֹ נֵדֶר לְחַזֵּק אֶת בֶּדֶק הַבַּיִת אוֹ בֶּדֶק יְרוּשָׁלַיִם שֶׁנֶּאֱמַר (עזרא ד ג) \"לֹא לָכֶם וָלָנוּ לִבְנוֹת בַּיִת\" וְגוֹ'. וְנֶאֱמַר (נחמיה ב כ) \"וְלָכֶם אֵין חֵלֶק וּצְדָקָה וְזִכָּרוֹן בִּירוּשָׁלָיִם\":","וּמַה יַּעֲשֶׂה בָּהֶן. יִבָּדֵק הָעַכּוּ\"ם עַל דַּעַת מִי נָדַר. אִם נָדַר עַל דַּעַת יִשְׂרָאֵל יוֹצִיאוּהוּ בֵּית דִּין בְּמַה שֶּׁיֵּרָאֶה לָהֶם חוּץ מִבֶּדֶק הַבַּיִת וּבֶדֶק יְרוּשָׁלַיִם. וְאִם אָמַר לַשָּׁמַיִם נָדַרְתִּי יִגָּנְזוּ:","הַגּוֹסֵס אֵין לוֹ לֹא עֵרֶךְ וְלֹא דָּמִים הוֹאִיל וְרֹב הַגּוֹסְסִין לְמִיתָה הֲרֵי הוּא כְּמֵת. וְכֵן מִי שֶׁנִּגְמַר דִּינוֹ בְּבֵית דִּין שֶׁל יִשְׂרָאֵל לְהָרְגוֹ עַל עֲבֵרָה שֶׁעָבַר וְהֶעֱרִיכוֹ אַחֵר אוֹ שֶׁהֶעֱרִיךְ עַצְמוֹ אוֹ שֶׁאָמַר דָּמַי עָלַי אוֹ שֶׁאָמַר אַחֵר דְּמֵי זֶה עָלַי אֵינוֹ חַיָּב כְּלוּם שֶׁזֶּה כְּמֵת הוּא וְהַמֵּת אֵין לוֹ עֵרֶךְ וְלֹא דָּמִים. וְעַל זֶה נֶאֱמַר (ויקרא כז כט) \"כָּל חֵרֶם אֲשֶׁר יָחֳרַם מִן הָאָדָם לֹא יִפָּדֶה\" כְּלוֹמַר אֵין לוֹ פִּדְיוֹן אֶלָּא הֲרֵי הוּא כְּמֵת:","זֶה הַיּוֹצֵא לֵהָרֵג שֶׁהֶעֱרִיךְ אֲחֵרִים אוֹ נָדַר דְּמֵיהֶם אוֹ הִזִּיק חַיָּב לְשַׁלֵּם וְגוֹבִין הַכּל מִנְּכָסָיו:","כֹּהֲנִים וּלְוִיִּים מַעֲרִיכִין וְנֶעֱרָכִין כִּשְׁאָר יִשְׂרָאֵל. וְקָטָן שֶׁהִגִּיעַ לְעוֹנַת נְדָרִים וְהֶעֱרִיךְ אוֹ נָדַר דָּמִים חַיָּב לְשַׁלֵּם שֶׁהֲרֵי נְדָרָיו קַיָּמִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת נְדָרִים:","הָעֲרָכִין הַקְּצוּבִין לְפִי הַשָּׁנִים הֵן שְׁנֵי הַנֶּעֱרָךְ וְלֹא שְׁנֵי הַמַּעֲרִיךְ. כֵּיצַד. בֶּן עֶשְׂרִים שֶׁאָמַר לְבֶן שִׁשִּׁים עֶרְכְּךָ עָלַי נוֹתֵן עֵרֶךְ בֶּן שִׁשִּׁים. וּבֶן שִׁשִּׁים שֶׁאָמַר לְבֶן עֶשְׂרִים עֶרְכְּךָ עָלַי נוֹתֵן עֵרֶךְ בֶּן עֶשְׂרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וְצָרִיךְ הַמַּעֲרִיךְ שֶׁיְּהֵא פִּיו וְלִבּוֹ שָׁוִין כִּשְׁאָר הַנְּדָרִים. וְנִשְׁאָלִין עַל הָעֲרָכִין וְעַל הַדָּמִים כְּדֶרֶךְ שֶׁנִּשְׁאָלִין עַל שְׁאָר נְדָרִים וְהֶקְדֵּשׁוֹת:","הָאוֹמֵר עֵרֶךְ אֵלּוּ עָלַי נוֹתֵן עֵרֶךְ כֻּלָּן כָּל אֶחָד וְאֶחָד לְפִי שָׁנָיו. וְאִם הָיָה עָנִי נוֹתֵן עַל יְדֵי כֻּלָּם עֵרֶךְ אֶחָד עָנִי. וְאִם הָיָה עָשִׁיר נוֹתֵן עַל יְדֵי כֻּלָּן עֵרֶךְ עָשִׁיר:","הָאוֹמֵר עֶרְכִּי עָלַי וְחָזַר וְאָמַר עֶרְכִּי עָלַי וְכֵן אִם אָמַר אֲפִלּוּ כַּמָּה פְּעָמִים חַיָּב עַל כָּל אַחַת וְאַחַת. אָמַר שְׁנֵי עֶרְכִּי עָלַי נוֹתֵן שְׁנֵי עֲרָכִין. וְכֵן אִם אָמַר אַרְבָּעָה אֲפִלּוּ אֶלֶף נוֹתֵן כַּמִּנְיָן שֶׁנָּדַר:","אָמַר הֲרֵי עָלַי עֵרֶךְ וְלֹא פֵּרֵשׁ עֵרֶךְ מִי אֶלָּא עֵרֶךְ סְתָם נוֹתֵן פָּחוּת שֶׁבַּעֲרָכִין שֶׁהוּא שְׁלֹשֶׁת שְׁקָלִים:","הָאוֹמֵר עֶרְכִּי עָלַי וּמֵת קֹדֶם שֶׁיַּעֲמֹד בְּדִין אֵין הַיּוֹרְשִׁין חַיָּבִין לִתֵּן. שֶׁנֶּאֱמַר (ויקרא כז ח) \"וְהֶעֱמִידוֹ לִפְנֵי הַכֹּהֵן וְהֶעֱרִיךְ אֹתוֹ הַכֹּהֵן\". עָמַד בַּדִּין וּמֵת יִתְּנוּ הַיּוֹרְשִׁין:","אֲבָל הָאוֹמֵר דָּמַי עָלַי אַף עַל פִּי שֶׁעָמַד בְּדִין וּמֵת קֹדֶם שֶׁיִּקְצְצוּ דָּמָיו וְיֹאמְרוּ הַדַּיָּנִין כַּמָּה יִשְׁוֶה אֵין הַיּוֹרְשִׁין חַיָּבִין לִתֵּן. וְאִם קָצְבוּ דָּמָיו וְאַחַר כָּךְ מֵת יִתְּנוּ הַיּוֹרְשִׁין:","וּמַה בֵּין עֲרָכִין לְדָמִים. שֶׁעֲרָכִין קְצוּבִין מִן הַתּוֹרָה וְהַדָּמִים אֵינָן קְצוּבִין. וְכֵן הָאוֹמֵר עֵרֶךְ פְּלוֹנִי עָלַי וּמֵת הָעוֹרֵךְ וְהַנֶּעֱרָךְ אַחַר שֶׁעָמַד הַנֶּעֱרָךְ בְּדִין חַיָּבִין הַיּוֹרְשִׁין לִתֵּן. מֵת הַנֶּעֱרָךְ קֹדֶם שֶׁעָמַד בְּדִין אַף עַל פִּי שֶׁהַמַּעֲרִיךְ קַיָּם הֲרֵי זֶה פָּטוּר. שֶׁאֵין עֵרֶךְ לְמֵת וְהַנֶּעֱרָךְ צָרִיךְ עֲמִידָה בְּדִין. אָמַר דְּמֵי פְּלוֹנִי עָלַי וְעָמַד בְּדִין וּמֵת קֹדֶם שֶׁיִּקְצְצוּ דָּמָיו הֲרֵי זֶה פָּטוּר שֶׁאֵין דָּמִים לַמֵּתִים:"],"Mishneh Torah, Blessings 3":["חֲמִשָּׁה מִינִין הֵן. הַחִטִּין וְהַשְּׂעוֹרִין וְהַכֻּסְּמִין וְשִׁבּלֶת שׁוּעָל וְשִׁיפּוֹן. הַכֻּסְּמִין מִמִּין הַחִטִּין וְשִׁבּלֶת שׁוּעָל וְשִׁיפּוֹן מִמִּין הַשְּׂעוֹרִים. וַחֲמִשָּׁה מִינִין הָאֵלּוּ כְּשֶׁהֵן שִׁבֳּלִים נִקְרָאִים תְּבוּאָה בְּכָל מָקוֹם. וְאַחַר שֶׁדָּשִׁין וְזוֹרִין אוֹתָן נִקְרָאִין דָּגָן. וּכְשֶׁטּוֹחֲנִין אוֹתָן וְלָשִׁין אֶת קִמְחָן וְאוֹפִין אוֹתָן נִקְרָאִין פַּת. וְהַפַּת הַנַּעֲשֶׂה מֵאֶחָד מֵהֶן הִיא הַנִּקְרֵאת פַּת בְּכָל מָקוֹם בְּלֹא לִוּוּי:","הָאוֹכֵל פַּת חַיָּב לְבָרֵךְ לְפָנֶיהָ בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ. וּלְאַחֲרֶיהָ אַרְבַּע בְּרָכוֹת. אָכַל דָּגָן שָׁלוּק כְּמוֹ שֶׁהוּא מְבָרֵךְ לְפָנָיו בּוֹרֵא פְּרִי הָאֲדָמָה. וּלְאַחֲרָיו בּוֹרֵא נְפָשׁוֹת רַבּוֹת. אָכַל קֶמַח מְבָרֵךְ לְפָנָיו שֶׁהַכּל וּלְאַחֲרָיו בּוֹרֵא נְפָשׁוֹת רַבּוֹת:","קֶמַח שֶׁל אֶחָד מֵחֲמֵשֶׁת הַמִּינִין שֶׁשְּׁלָקוּהוּ וְעֵרְבוּ בְּמַיִם אוֹ בִּשְׁאָר מַשְׁקִים אִם הָיָה עָבֶה כְּדֵי שֶׁיִּהְיֶה רָאוּי לַאֲכִילָה וּלְלָעֳסוֹ מְבָרֵךְ עָלָיו בַּתְּחִלָּה בּוֹרֵא מִינֵי מְזוֹנוֹת וּלְבַסּוֹף עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה. וְאִם הָיָה רַךְ כְּדֵי שֶׁיִּהְיֶה רָאוּי לִשְׁתִיָּה מְבָרֵךְ עָלָיו בַּתְּחִלָּה שֶׁהַכּל וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת רַבּוֹת:","קֶמַח שֶׁל אֶחָד מֵחֲמֵשֶׁת הַמִּינִין שֶׁבִּשְּׁלוֹ בִּקְדֵרָה בֵּין לְבַדּוֹ בֵּין שֶׁעֵרְבוֹ עִם דְּבָרִים אֲחֵרִים כְּגוֹן לְבִיבוֹת וְכַיּוֹצֵא בָּהֶן. וְכֵן הַדָּגָן שֶׁחִלְּקוֹ אוֹ כְּתָשׁוֹ וּבִשְּׁלוֹ בִּקְדֵרָה כְּגוֹן הָרִיפוֹת וְגֶרֶשׂ הַכַּרְמֶל וְכַיּוֹצֵא בָּהֶן וְכָל זֶה הוּא הַנִּקְרָא מַעֲשֵׂה קְדֵרָה. וְכֵן כָּל תַּבְשִׁיל שֶׁעֵרֵב בּוֹ מֵחֲמֵשֶׁת הַמִּינִין בֵּין קֶמַח בֵּין פַּת. בַּתְּחִלָּה מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי מְזוֹנוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַמִּין הַזֶּה חָשׁוּב אֶצְלוֹ וְלֹא הָיָה טְפֵלָה. אֲבָל אִם הָיָה אֶחָד מֵחֲמֵשֶׁת הַמִּינִין שֶׁעֵרֵב טְפֵלָה אֵינוֹ מְבָרֵךְ אֶלָּא עַל הָעִקָּר וּפוֹטֵר אֶת הַטְּפֵלָה. וְזֶה כְּלָל בִּבְרָכוֹת כָּל שֶׁהוּא עִקָּר וְעִמּוֹ טְפֵלָה מְבָרֵךְ עַל הָעִקָּר וּפוֹטֵר אֶת הַטְּפֵלָה בֵּין שֶׁהָיְתָה הַטְּפֵלָה מְעֹרֶבֶת עִם הָעִקָּר בֵּין שֶׁלֹּא הָיְתָה מְעֹרֶבֶת:","כֵּיצַד הִיא הַטְּפֵלָה הַמְעֹרֶבֶת. כְּגוֹן לֶפֶת אוֹ כְּרוּב שֶׁבִּשְּׁלוֹ וְעֵרֵב בּוֹ קֶמַח שֶׁל אֶחָד מֵחֲמֵשֶׁת הַמִּינִין כְּדֵי לְדַבְּקוֹ אֵינוֹ מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי מְזוֹנוֹת שֶׁהַלֶּפֶת הוּא הָעִקָּר וְקִמְחוֹ טְפֵלָה. שֶׁכָּל דָּבָר שֶׁמְּעָרְבִין אוֹתוֹ לְדַבֵּק אוֹ כְּדֵי לִתֵּן רֵיחַ אוֹ כְּדֵי לִצְבֹּעַ אֶת הַתַּבְשִׁיל הֲרֵי זוֹ טְפֵלָה. אֲבָל אִם עֵרֵב כְּדֵי לִתֵּן טַעַם בַּתַּעֲרוֹבוֹת הֲרֵי הוּא עִקָּר. לְפִיכָךְ מִינֵי דְּבַשׁ שֶׁמְּבַשְּׁלִין אוֹתָן וְנוֹתְנִין בָּהֶן חֵלֶב חִטָּה כְּדֵי לְדַבֵּק וְעוֹשִׂין מֵהֶן מִינֵי מְתִיקָה אֵינוֹ מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי מְזוֹנוֹת מִפְּנֵי שֶׁהַדְּבַשׁ הוּא הָעִקָּר:","כֵּיצַד הִיא הַטְּפֵלָה שֶׁאֵינָהּ מְעֹרֶבֶת. הֲרֵי שֶׁצָּרִיךְ לֶאֱכל דָּג מָלִיחַ וְאָכַל הַפַּת עִמּוֹ כְּדֵי שֶׁלֹּא יַזִּיק הַמֶּלַח גְּרוֹנוֹ וּלְשׁוֹנוֹ הֲרֵי זֶה מְבָרֵךְ עַל הַמָּלִיחַ וּפוֹטֵר אֶת הַפַּת מִפְּנֵי שֶׁהַפַּת טְפֵלָה לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַפַּת שֶׁפָּתַת אוֹתָהּ פִּתִּים וּבִשְׁלָהּ בִּקְדֵרָה אוֹ לָשָׁהּ בְּמָרָק. אִם יֵשׁ בַּפְּתִיתִין כְּזַיִת אוֹ שֶׁנִכָּר שֶׁהֵן פַּת וְלֹא נִשְׁתַּנָּה צוּרָתָהּ מְבָרֵךְ עָלֶיהָ בַּתְּחִלָּה הַמּוֹצִיא. וְאִם אֵין בָּהֶן כְּזַיִת אוֹ שֶׁעֻבְּרָה צוּרַת הַפַּת בַּבִּשּׁוּל מְבָרֵךְ עָלֶיהָ בַּתְּחִלָּה בּוֹרֵא מִינֵי מְזוֹנוֹת:","עִסָּה שֶׁנֶּאֱפֵית בַּקַּרְקַע כְּמוֹ שֶׁהָעַרְבִיִּים שׁוֹכְנֵי הַמִּדְבָּרוֹת אוֹפִים הוֹאִיל וְאֵין עָלֶיהָ צוּרַת פַּת מְבָרֵךְ עָלֶיהָ בַּתְּחִלָּה בּוֹרֵא מִינֵי מְזוֹנוֹת. וְאִם קָבַע מְזוֹנוֹ עָלֶיהָ מְבָרֵךְ הַמּוֹצִיא. וְכֵן עִסָּה שֶׁלָּשָׁהּ בִּדְבַשׁ אוֹ בְּשֶׁמֶן אוֹ בְּחָלָב אוֹ שֶׁעֵרֵב בָּהּ מִינֵי תַּבְלִין וַאֲפָאָהּ וְהִיא הַנִּקְרֵאת פַּת הַבָּאָה בְּכִסְנִין אַף עַל פִּי שֶׁהוּא פַּת מְבָרֵךְ עָלֶיהָ בּוֹרֵא מִינֵי מְזוֹנוֹת. וְאִם קָבַע סְעֻדָּתוֹ עָלֶיהָ מְבָרֵךְ הַמּוֹצִיא:","אֹרֶז שֶׁבִּשְּׁלוֹ אוֹ שֶׁעָשָׂה מִמֶּנּוּ פַּת בַּתְּחִלָּה מְבָרֵךְ עָלָיו בּוֹרֵא מִינֵי מְזוֹנוֹת וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת. וּבִלְבַד שֶׁלֹּא יְהֵא מְעֹרָב עִם דָּבָר אַחֵר אֶלָּא אֹרֶז לְבַדּוֹ. אֲבָל פַּת דֹּחַן אוֹ פַּת שֶׁל שְׁאָר מִינֵי קִטְנִית בַּתְּחִלָּה מְבָרֵךְ שֶׁהַכּל וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת רַבּוֹת:","כָּל שֶׁמְּבָרְכִין עָלָיו בַּתְּחִלָּה הַמּוֹצִיא מְבָרְכִין לְאַחֲרָיו בַּסּוֹף בִּרְכַּת הַמָּזוֹן כְּסִדְרָהּ אַרְבַּע בְּרָכוֹת. וְכָל שֶׁמְּבָרְכִין עָלָיו בַּתְּחִלָּה בּוֹרֵא מִינֵי מְזוֹנוֹת מְבָרְכִין בַּסּוֹף לְאַחֲרָיו בְּרָכָה אַחַת מֵעֵין שָׁלֹשׁ חוּץ מִן הָאֹרֶז:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאָכַל מִכְּזַיִת וּלְמַעְלָה אֲבָל אָכַל פָּחוֹת מִכְּזַיִת בֵּין מִן הַפַּת בֵּין מִשְּׁאָר אוֹכְלִין. וְהַשּׁוֹתֶה פָּחוֹת מֵרְבִיעִית בֵּין מִן הַיַּיִן בֵּין מִשְּׁאָר מַשְׁקִין. מְבָרֵךְ בַּתְּחִלָּה בְּרָכָה הָרְאוּיָה לְאוֹתוֹ הַמִּין וּלְבַסּוֹף אֵינוֹ מְבָרֵךְ כְּלָל:","וְזוֹ הִיא בְּרָכָה אַחַת מֵעֵין שָׁלֹשׁ. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה וְעַל אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה שֶׁרָצִיתָ וְשֶׁהִנְחַלְתָּ אֶת אֲבוֹתֵינוּ רַחֵם יְיָ׳‎ אֱלֹהֵינוּ עָלֵינוּ וְעַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ וְהַעֲלֵנוּ לְתוֹכָהּ וְשַׂמְּחֵנוּ בְּבִנְיָנָהּ וּנְבָרֶכְךָ עָלֶיהָ בִּקְדֻשָּׁה וּבְטָהֳרָה בָּרוּךְ אַתָּה יְיָ׳‎ עַל הָאָרֶץ וְעַל הַמִּחְיָה. וּבְשַׁבָּתוֹת וְיָמִים טוֹבִים אוֹמֵר בִּבְרָכָה זוֹ בִּכְלָלָהּ מֵעֵין קְדֻשַּׁת הַיּוֹם כְּדֶרֶךְ שֶׁמַּזְכִּיר בְּבִרְכַּת הַמָּזוֹן:"],"Mishneh Torah, Borrowing and Deposit 6":["שׁוֹמֵר חִנָּם שֶׁאָמַר הֲרֵינִי מְשַׁלֵּם וְאֵינִי נִשְׁבָּע אִם הַפִּקָּדוֹן דָּבָר שֶׁכָּל מִינוֹ שָׁוֶה וּמָצוּי בַּשּׁוּק לִקְנוֹת כְּמוֹתוֹ כְּגוֹן פֵּרוֹת אוֹ יְרִיעוֹת שֶׁל צֶמֶר וְשֶׁל פִּשְׁתָּן הַשָּׁווֹת בְּכָל עִנְיָנָם אוֹ קוֹרוֹת שֶׁאֵינָן מְצֻיָּרוֹת וְכָל כַּיּוֹצֵא בָּהֶן הֲרֵי זֶה מְשַׁלֵּם וְאֵינוֹ נִשְׁבָּע. אֲבָל אִם הָיָה פִּקְדוֹן בְּהֵמָה אוֹ בֶּגֶד מְצֻיָּר אוֹ כְּלִי מְתֻקָּן אוֹ דָּבָר שֶׁאֵינוֹ מוֹצֵא לִקְנוֹת כְּמוֹתוֹ בַּשּׁוּק חוֹשְׁשִׁין שֶׁמָּא עֵינָיו נָתַן בּוֹ וּמַשְׁבִּיעִין אוֹתוֹ בְּתַקָּנַת חֲכָמִים שְׁבוּעָה בִּנְקִיטַת חֵפֶץ שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְאַחַר כָּךְ מְשַׁלֵּם. וְהוּא הַדִּין לִשְׁאָר הַשּׁוֹמְרִין כְּגוֹן הַשּׁוֹאֵל שֶׁאָמַר מֵתָה אוֹ נִגְנְבָה וְשׁוֹמֵר שָׂכָר וְהַשּׂוֹכֵר שֶׁאָמַר נִגְנְבָה אוֹ שֶׁאָבְדָה אַף עַל פִּי שֶׁהֵן חַיָּבִין לְשַׁלֵּם מַשְׁבִּיעִין אוֹתָן שְׁבוּעָה שֶׁאֵינָהּ בִּרְשׁוּתָן וְאַחַר כָּךְ מְשַׁלְּמִין דְּמֵי הַבְּהֵמָה אוֹ הַחֵפֶץ שֶׁאָנוּ חוֹשְׁשִׁין לוֹ שֶׁמָּא עֵינָיו נָתַן בָּהּ. וְאִם אָמְרוּ הַבְּעָלִים יֶתֶר עַל זֶה הָיָה שָׁוֶה כּוֹלֵל בִּשְׁבוּעָתוֹ שֶׁאֵינָהּ שָׁוָה אֶלָּא כָּךְ וְכָךְ. נִמְצָא כָּל שׁוֹמֵר שֶׁנִּשְׁבַּע שְׁבוּעַת הַשּׁוֹמְרִין כּוֹלֵל בִּשְׁבוּעָתוֹ שְׁלֹשָׁה דְּבָרִים. שֶׁשָּׁמַר כְּדֶרֶךְ הַשּׁוֹמְרִין. וְשֶׁאֵרְעוֹ כָּךְ וְכָךְ וְאֵינוֹ בִּרְשׁוּתוֹ. וְשֶׁלֹּא שָׁלַח בּוֹ יָד קֹדֶם שֶׁאֵרְעוֹ הַמְאֹרָע הַפּוֹטֵר אוֹתוֹ. וְאִם רָצָה לְשַׁלֵּם נִשְׁבָּע שֶׁאֵינוֹ בִּרְשׁוּתוֹ וְכוֹלֵל בִּשְׁבוּעָתוֹ שֶׁכָּךְ וְכָךְ הָיָה שָׁוֶה:","יֵשׁ לַשּׁוֹמֵר לְהַתְנוֹת שֶׁאֵינוֹ שׁוֹמֵר כְּדֶרֶךְ הַשּׁוֹמְרִין אֶלָּא מָעוֹת אֵלּוּ שֶׁהִפְקִיד אֶצְלִי בְּזָוִית בֵּיתִי אֲנִי מַנִּיחַ אוֹתָן וְכַיּוֹצֵא בָּזֶה. טָעַן הַשּׁוֹמֵר שֶׁתְּנַאי הָיָה בֵּינֵינוּ וּבַעַל הַפִּקָּדוֹן אוֹמֵר לֹא הָיָה שָׁם תְּנַאי אַף עַל פִּי שֶׁהִפְקִיד אֶצְלוֹ בְּעֵדִים מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר שָׁמַרְתִּי כְּדֶרֶךְ הַשּׁוֹמְרִין וְנֶאֱנַסְתִּי נֶאֱמָן לוֹמַר שֶׁהָיָה בֵּינֵיהֶן תְּנַאי לְפִיכָךְ יִשָּׁבַע שֶׁלֹּא שָׁלַח יָד בּוֹ וְשֶׁאֵינוֹ בִּרְשׁוּתוֹ וְשֶׁהָיָה בֵּינֵיהֶן תְּנַאי:","שׁוֹמֵר חִנָּם שֶׁהֵבִיא רְאָיָה שֶׁלֹּא פָּשַׁע בָּהּ פָּטוּר מִשְּׁבוּעָה וְאֵין אוֹמְרִים שֶׁמָּא שָׁלַח בּוֹ יָד קֹדֶם שֶׁיֹּאבַד. וּבַעַל הַפִּקָּדוֹן שֶׁהֵבִיא רְאָיָה שֶׁפָּשַׁע הַשּׁוֹמֵר מְשַׁלֵּם. וְאִם טָעַן וְאָמַר תְּנַאי הָיָה בֵּינֵינוּ אֵינוֹ נֶאֱמָן שֶׁהֲרֵי יֵשׁ עֵדִים שֶׁפָּשַׁע:","הִפְקִיד אֵצֶל חֲבֵרוֹ בְּעֵדִים וּבָאוּ עֵדִים שֶׁזֶּה הַחֵפֶץ בְּפָנֵינוּ הִפְקִידוֹ אֶצְלוֹ אֵין הַשּׁוֹמֵר יָכוֹל לִטְעֹן וְלוֹמַר חָזַרְתִּי וּלְקַחְתִּיו מִמֶּנּוּ אוֹ נְתָנוֹ לִי בְּמַתָּנָה. לְפִיכָךְ אִם מֵת הַשּׁוֹמֵר מוֹצִיאִין הַפִּקָּדוֹן עַצְמוֹ מִן הַיְתוֹמִים בְּלֹא שְׁבוּעָה. וְלֹא עוֹד אֶלָּא מִי שֶׁבָּא וְאָמַר כָּךְ וְכָךְ הִפְקַדְתִּי אֵצֶל אֲבִיכֶם וְנָתַן סִימָנִין מֻבְהָקִין וְנִמְצָא הַפִּקָּדוֹן כְּמוֹ שֶׁאָמַר וְהָיָה יוֹדֵעַ הַדַּיָּן שֶׁלֹּא הָיָה הַמֵּת אָמוּד שֶׁזֶּה הַפִּקָּדוֹן שֶׁלּוֹ. יֵשׁ לוֹ לַדַּיָּן הַזֶּה לָתֵת הַפִּקָּדוֹן לְזֶה שֶׁנָּתַן סִימָנָיו. וְהוּא שֶׁלֹּא יִהְיֶה הַמַּפְקִיד רָגִיל לְהִכָּנֵס אֵצֶל זֶה שֶׁמֵּת אֲבָל אִם הָיָה רָגִיל לִכָּנֵס אֶצְלוֹ שֶׁמָּא שֶׁל אַחֵר הוּא וְהִכִּיר הַסִּימָנִין שֶׁלּוֹ. בָּאוּ עֵדִים וְהֵעִידוּ לַדַּיָּן שֶׁאֵין זֶה אָמוּד אֵין מוֹצִיאִין מִיַּד הַיְתוֹמִים בְּעֵדוּתָן שֶׁאֵין זֶה רְאָיָה בְּרוּרָה וְאֻמְדַּן דַּעְתָּן אֵינוֹ אֹמֶד דַּעְתּוֹ וְאֵין לוֹ לַדַּיָּן אֶלָּא מַה שֶּׁדַּעְתּוֹ סוֹמֶכֶת עָלָיו כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת סַנְהֶדְרִין. מַעֲשֶׂה בְּאֶחָד שֶׁהִפְקִיד שֻׁמְשְׁמִין אֵצֶל חֲבֵרוֹ בְּעֵדִים וּבָא לְתָבְעוֹ וְאָמַר לוֹ הֶחְזַרְתִּים. אָמַר לוֹ הַמַּפְקִיד וַהֲלֹא כָּךְ וְכָךְ הִיא מִדָּתָם וַהֲרֵי הֵם מֻנָּחִים אֶצְלְךָ בְּחָבִיתְךָ. אָמַר לוֹ שֶׁלְּךָ הֶחְזַרְתִּי לְךָ וְאֵלּוּ אֲחֵרִים הֵן. וְאָמְרוּ חֲכָמִים אֵין מוֹצִיאִין מִיָּדוֹ שֶׁמָּא אֵלּוּ הַשֻּׁמְשְׁמִין שֶׁל שׁוֹמֵר הֵן אֶלָּא יִשָּׁבַע הַשּׁוֹמֵר בִּנְקִיטַת חֵפֶץ שֶׁהֶחְזִיר כְּמוֹ שֶׁבֵּאַרְנוּ:","בַּעַל הַפִּקָּדוֹן שֶׁתָּבַע פִּקְדּוֹנוֹ וְנָתַן לוֹ הַשּׁוֹמֵר וְאָמַר הַמַּפְקִיד אֵין זֶה פִּקְדוֹנִי אֶלָּא אַחֵר הוּא אוֹ שָׁלֵם הָיָה וְאַתָּה שְׁבַרְתּוֹ אוֹ חָדָשׁ הָיָה וְנִשְׁתַּמַּשְׁתָּ בּוֹ. מֵאָה סְאִין הִפְקַדְתִּי אֶצְלְךָ וְאֵין אֵלּוּ אֶלָּא חֲמִשִּׁים וּבַעַל הַבַּיִת אוֹמֵר זֶהוּ שֶׁהִפְקַדְתָּ בְּעַצְמְךָ וּמַה שֶּׁנָּתַתָּ אַתָּה נוֹטֵל. הֲרֵי הַשּׁוֹמֵר נִשְׁבָּע הֶסֵּת כִּשְׁאָר כָּל הַנִּשְׁבָּעִין שֶׁאֵין כָּל שׁוֹמֵר נִשְׁבָּע שְׁבוּעַת הַשּׁוֹמְרִין הָאֲמוּרָה בַּתּוֹרָה אֶלָּא בִּזְמַן שֶׁמּוֹדֶה בְּעַצְמוֹ שֶׁל פִּקָּדוֹן כְּמוֹ שֶׁהַמַּפְקִיד אוֹמֵר וְטוֹעֵן שֶׁנִּגְנַב אוֹ מֵת אוֹ נִשְׁבָּה. כְּלָלוֹ שֶׁל דָּבָר טוֹעֵן לִפְטֹר עַצְמוֹ מִן הַתַּשְׁלוּמִין [נִשְׁבָּע שְׁבוּעַת שׁוֹמְרִין]. אֲבָל אִם אָמַר זֶהוּ שֶׁהִשְׁאַלְתַּנִי אוֹ שֶׁהִשְׂכַּרְתָּ לִי אוֹ שֶׁנָּטַלְתִּי שָׂכָר עַל שְׁמִירָתִי וְהַבְּעָלִים אוֹמְרִים אֵינוֹ זֶה אֶלָּא אַחֵר אוֹ נִשְׁתַּנָּה מִכְּמוֹת שֶׁהָיָה הַשּׂוֹכֵר נִשְׁבָּע הֶסֵּת אוֹ שְׁבוּעַת הַתּוֹרָה אִם הוֹדָה בְּמִקְצָת. כֵּיצַד. מֵאָה סְאָה הִפְקַדְתִּי אֶצְלְךָ וְהַשּׁוֹמֵר אוֹמֵר לֹא הִפְקַדְתָּ אֶצְלִי אֶלָּא חֲמִשִּׁים נִשְׁבָּע שְׁבוּעַת הַתּוֹרָה מִפְּנֵי שֶׁהוֹדָה בְּמִקְצָת לֹא מִשּׁוּם שְׁבוּעַת הַשּׁוֹמְרִין. מֵאָה כּוֹר שֶׁל חִטִּים הִפְקַדְתִּי אֶצְלְךָ וְהוּא אוֹמֵר לֹא הִפְקַדְתָּ אֶצְלִי אֶלָּא מֵאָה שֶׁל שְׂעוֹרִים נִשְׁבָּע הֶסֵּת כִּשְׁאָר כָּל הַנִּשְׁבָּעִין בְּטַעֲנָה כָּזוֹ:"],"Mishneh Torah, Creditor and Debtor 15":["הַמַּלְוֶה אֶת חֲבֵרוֹ בְּעֵדִים וְאָמַר אַל תִּפְרָעֵנִי אֶלָּא בְּעֵדִים בֵּין שֶׁאָמַר לוֹ בִּשְׁעַת הַלְוָאָה בֵּין שֶׁאָמַר לוֹ אַחַר שֶׁהִלְוָהוּ הֲרֵי זֶה צָרִיךְ לְפָרְעוֹ בְּעֵדִים מִפְּנֵי הַתְּנַאי. טָעַן הַלּוֶֹה וְאָמַר לוֹ וְכֵן עָשִׂיתִי וּפְרַעְתִּיךָ בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וְהָלְכוּ לָהֶם לִמְדִינַת הַיָּם אוֹ מֵתוּ הֲרֵי זֶה נֶאֱמָן וְנִשְׁבָּע שְׁבוּעַת הֶסֵּת וְנִפְטָר. וְכֵן אִם אָמַר אַל תִּפְרָעֵנִי אֶלָּא בִּפְנֵי תַּלְמִידֵי חֲכָמִים אוֹ בִּפְנֵי רוֹפְאִים וְאָמַר לוֹ בִּפְנֵיהֶם פְּרַעְתִּיךָ וְאוֹתָן הָעֵדִים שֶׁפְּרַעְתִּיךָ בִּפְנֵיהֶם מֵתוּ אוֹ הָלְכוּ לָהֶם לִמְדִינַת הַיָּם הֲרֵי זֶה נֶאֱמָן וְנִשְׁבָּע הֶסֵּת וְנִפְטָר. אֲבָל אִם אָמַר לוֹ אַל תִּפְרָעֵנִי אֶלָּא בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וְאָמַר לוֹ פְּרַעְתִּיךָ בִּפְנֵי אֲחֵרִים וּמֵתוּ אוֹ הָלְכוּ לָהֶם לִמְדִינַת הַיָּם אֵינוֹ נֶאֱמָן שֶׁמִּפְּנֵי טַעֲנָה זוֹ הִתְנָה עָלָיו וְאָמַר לוֹ אַל תִּפְרָעֵנִי אֶלָּא בִּפְנֵי רְאוּבֵן וְשִׁמְעוֹן שֶׁהֵם עוֹמְדִים עִמּוֹ כְּדֵי שֶׁלֹּא יִדְחֶה אוֹתוֹ וְיֹאמַר בִּפְנֵי אֲחֵרִים פָּרַעְתִּי וְהָלְכוּ לָהֶם:","יֵשׁ נֻסְחָאוֹת מִן הַגְּמָרָא שֶׁכָּתוּב בָּהֶן שֶׁהָאוֹמֵר לַחֲבֵרוֹ אַל תִּפְרָעֵנִי אֶלָּא בְּעֵדִים וְאָמַר לוֹ פְּרַעְתִּיךָ בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וְהָלְכוּ לִמְדִינַת הַיָּם אֵינוֹ נֶאֱמָן וְטָעוּת סְפָרִים הוּא וּלְפִיכָךְ טָעוּ הַמּוֹרִים עַל פִּי אוֹתָן הַסְּפָרִים וּכְבָר חָקַרְתִּי עַל הַנֻּסְחָאוֹת הַיְשָׁנוֹת וּמָצָאתִי בָּהֶן שֶׁהוּא נֶאֱמָן וְהִגִּיעַ לְיָדִי בְּמִצְרַיִם מִקְצָת גְּמָרָא יְשָׁנָה כָּתוּב עַל הַגְּוִילִים כְּמוֹ שֶׁהָיוּ כּוֹתְבִין קֹדֶם לַזְּמַן הַזֶּה בְּקָרוֹב חֲמֵשׁ מֵאוֹת שָׁנָה וּשְׁתֵּי נֻסְחָאוֹת מָצָאתִי מִן הַגְּוִילִים בַּהֲלָכָה זוֹ וּבִשְׁתֵּיהֶם כָּתוּב וְאִם אָמַר פָּרַעְתִּי בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וְהָלְכוּ לָהֶן לִמְדִינַת הַיָּם נֶאֱמָן. וּמִפְּנֵי טָעוּת זוֹ שֶׁאֵרַע לְמִקְצָת הַסְּפָרִים הוֹרוּ מִקְצָת גְּאוֹנִים שֶׁאִם אָמַר לוֹ אַל תִּפְרָעֵנִי אֶלָּא בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וּפְרָעוֹ בִּפְנֵי אֲחֵרִים שֶׁאֵינוֹ נֶאֱמָן אַף עַל פִּי שֶׁהֵבִיא עֵדִים שֶׁפָּרְעוּ בִּפְנֵיהֶם וְגַם זוֹ טָעוּת גְּדוֹלָה וְהַדִּין הָאֱמֶת שֶׁאִם בָּאוּ עֵדִים שֶׁפָּרְעוּ בִּפְנֵיהֶם נִפְטָר וְאֵין כָּאן מְקוֹם חֲשָׁשׁ. גַּם הַהוֹרָאָה הַזֹּאת עַל פִּי סִפְרֵיהֶן שֶׁכָּתוּב בָּהֶן בְּאוֹתוֹ שֶׁאָמַר לַחֲבֵרוֹ פְּרָעֵנִי בִּפְנֵי עֵדִים שֶׁשָּׁנוּ הֲלָכוֹת וְהָלַךְ וּפְרָעוֹ בִּפְנֵי עֵדִים וְטָעוּת סְפָרִים הוּא וּמָצָאתִי בַּגְּוִילִים כָּתוּב אָזַל פַּרְעֵיהּ בֵּינֵיהּ לְבֵין דִּילֵיהּ אַף עַל פִּי שֶׁהַסְּפָרִים מֻגָּהִין כְּמוֹ שֶׁבֵּאַרְנוּ כָּךְ יֵרָאֶה מִדִּין הַגְּמָרָא. וְעוֹד דְּבָרִים שֶׁל דַּעַת הֵן וְכִי מֶה הָיָה לוֹ לַעֲשׂוֹת אָמַר לוֹ אַל תִּפְרָעֵנִי אֶלָּא בְּעֵדִים פְּרָעוֹ בְּעֵדִים וְכִי יֵשׁ לוֹ לֶאֱסֹר אֶת הָעֵדִים בְּבֵית הַסֹּהַר כָּל יְמֵיהֶם שֶׁלֹּא יֵלְכוּ וְעוֹד אִם מֵתוּ מַה יַּעֲשֶׂה נִמְצָא זֶה פּוֹרֵעַ פַּעַם אַחַר פַּעַם לְעוֹלָם עַד שֶׁיָּבִיא עֵדִים אִם כֵּן נַעֲשֵׂית עֵדוּת זוֹ עֵדוּת בִּשְׁטָר וְנִמְצָא זֶה כֵּיוָן שֶׁאָמַר אַל תִּפְרָעֵנִי אֶלָּא בְּעֵדִים נַעֲשֵׂית מִלְוֶה בִּשְׁטָר וְאֵין מִי שֶׁעָלָה עַל לִבּוֹ זֶה. אֲבָל וַדַּאי אִם אָמַר בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי הוּא הִפְסִיד עַל עַצְמוֹ שֶׁפָּרַע בִּפְנֵי אֲחֵרִים וְהָלְכוּ לָהֶם. אֲבָל אִם בָּאוּ וְהֵעִידוּ שֶׁפְּרָעוֹ אֵין כָּאן בֵּית מֵחוֹשׁ וְכָזֶה רָאוּי לָדוּן וּלְהוֹרוֹת:","הִתְנָה הַמַּלְוֶה עַל הַלּוֶֹה שֶׁיִּהְיֶה נֶאֱמָן בְּכָל עֵת שֶׁיֹּאמַר שֶׁלֹּא פְּרָעוֹ הֲרֵי זֶה נוֹטֵל בְּלֹא שְׁבוּעָה אַף עַל פִּי שֶׁטָּעַן שֶׁפְּרָעוֹ. וְאִם הֵבִיא עֵדִים שֶׁפְּרָעוֹ אֵינוֹ נוֹטֵל כְּלוּם:","הִתְנָה עָלָיו שֶׁיִּהְיֶה הַמַּלְוֶה נֶאֱמָן כִּשְׁנֵי עֵדִים אַף עַל פִּי שֶׁהֵבִיא עֵדִים שֶׁפְּרָעוֹ הֲרֵי זֶה גּוֹבֶה מִמֶּנּוּ בְּלֹא שְׁבוּעָה שֶׁהֲרֵי הֶאֱמִינוֹ כִּשְׁנֵי עֵדִים. וַאֲפִלּוּ הֵבִיא מֵאָה עֵדִים (שֶׁפְּרָעוֹ הֲרֵי גּוֹבֶה מִמֶּנּוּ בְּלֹא שְׁבוּעָה וַאֲפִלּוּ הֵבִיא מֵאָה עֵדִים) שֶׁפְּרָעוֹ בִּפְנֵיהֶם שֶׁהַשְּׁנַיִם כְּמֵאָה. אֲבָל אִם אָמַר לוֹ הֲרֵי אַתָּה נֶאֱמָן עָלַי כִּשְׁלֹשָׁה הוֹאִיל וְיָרַד לְמִנְיָן אִם פְּרָעוֹ בִּפְנֵי אַרְבָּעָה הֲרֵי זֶה פָּרוּעַ. זֶה שֶׁהֶאֱמִין הַמַּלְוֶה כִּשְׁנֵי עֵדִים מַה תִּהְיֶה תַּקָּנָתוֹ כְּשֶׁיִּפָּרַע יִקְרַע הַשְּׁטָר אוֹ יָעִיד זֶה הַמַּלְוֶה עַל עַצְמוֹ שֶׁבִּטֵּל כָּל שְׁטָר שֶׁיֵּשׁ לוֹ עַל פְּלוֹנִי. אוֹ יָעִיד עַל עַצְמוֹ שֶׁלֹּא בִּפְנֵי הַלּוֶֹה שֶׁקִּבֵּל כָּל חוֹב שֶׁיֵּשׁ לוֹ אֵצֶל פְּלוֹנִי:","הֲרֵי שֶׁפְּרָעוֹ וְטָעַן הַמַּלְוֶה שֶׁלֹּא נִפְרַע וּפְרָעוֹ פַּעַם שְׁנִיָּה מִפְּנֵי הַתְּנַאי הֲרֵי הַלּוֶֹה חוֹזֵר וְתוֹבֵעַ אֶת הַמַּלְוֶה בְּדִין וְאוֹמֵר לוֹ כָּךְ וְכָךְ אַתָּה חַיָּב לִי מִפְּנֵי שֶׁפְּרָעְתִּיךָ שְׁתֵּי פְּעָמִים. אִם הוֹדָה יְשַׁלֵּם וְאִם כָּפַר יִשָּׁבַע שְׁבוּעַת הֶסֵּת עַל כָּךְ שֶׁלֹּא פְּרָעוֹ אֶלָּא פַּעַם אַחַת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִתְנָה הַלּוֶֹה שֶׁיִּהְיֶה נֶאֱמָן בְּכָל עֵת שֶׁיֹּאמַר פָּרַעְתִּי אֵינוֹ גּוֹבֶה בִּשְׁטָר זֶה לֹא מִן הַיּוֹרֵשׁ וְלֹא מִן הַלּוֹקֵחַ. וַאֲפִלּוּ אָמַר לוֶֹה לֹא פָּרַעְתִּי אֵין הַמַּלְוֶה טוֹרֵף בִּשְׁטָר זֶה מִן הַלָּקוֹחוֹת שֶׁמָּא עָשׂוּ קְנוּנְיָא עַל נְכָסָיו שֶׁל זֶה. טָעַן הַלּוֶֹה בִּשְׁטָר זֶה וְאָמַר פָּרַעְתִּי מִקְצָתוֹ וְהַמַּלְוֶה אוֹמֵר לֹא פָּרַע כְּלוּם מְשַׁלֵּם הַמִּקְצָת שֶׁהוֹדָה בּוֹ וְנִשְׁבָּע שְׁבוּעַת הֶסֵּת שֶׁהֲרֵי הֶאֱמִינוֹ. וְאִם הִתְנָה עָלָיו שֶׁיִּהְיֶה נֶאֱמָן בְּלֹא שְׁבוּעַת הֶסֵּת אֵינוֹ נִשְׁבָּע:","הִתְנָה הַמַּלְוֶה שֶׁיִּהְיֶה גּוֹבֶה בְּלֹא שְׁבוּעָה הֲרֵי זֶה גּוֹבֶה מִמֶּנּוּ בְּלֹא שְׁבוּעָה. אֲבָל אִם בָּא לִגְבּוֹת מִיּוֹרְשָׁיו יִשָּׁבַע וְאַחַר כָּךְ יִגְבֶּה. וְאִם הִתְנָה שֶׁיִּגְבֶּה אַף מִן הַיּוֹרֵשׁ בְּלֹא שְׁבוּעָה גּוֹבֶה בְּלֹא שְׁבוּעָה. וְכֵן אִם הִתְנָה שֶׁיִּגְבֶּה מִן הָעִידִית גּוֹבֶה מִן הָעִידִית אַף מִן הַיּוֹרְשִׁין. שֶׁכָּל תְּנַאי שֶׁבְּמָמוֹן קַיָּם. בָּא לִגְבּוֹת מִן הַלּוֹקֵחַ לֹא יִטְרֹף אֶלָּא בִּשְׁבוּעָה שֶׁאֵין זֶה מַתְנֶה לְאַבֵּד מָמוֹן חֲבֵרוֹ:"],"Mishneh Torah, Creditor and Debtor 26":["הַמַּלְוֶה אֶת חֲבֵרוֹ בִּשְׁטָר וְאַחַר שֶׁהֵעִידוּ הָעֵדִים בַּשְּׁטָר בָּא עָרֵב וְעָרַב אֶת הַלּוֶֹה אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ וְנִשְׁתַּעְבֵּד לְשַׁלֵּם כְּמוֹ שֶׁבֵּאַרְנוּ כְּשֶׁיָּבוֹא הַמַּלְוֶה לְהִפָּרַע מִנִּכְסֵי הֶעָרֵב הַזֶּה אֵינוֹ טוֹרֵף מִנְּכָסִים מְשֻׁעְבָּדִים. הָיָה הֶעָרֵב בְּגוּפוֹ שֶׁל שְׁטָר קֹדֶם חֲתִימַת הָעֵדִים אִם כָּתְבוּ פְּלוֹנִי עָרֵב שֶׁהֲרֵי אֵינוֹ מְעֹרָב עִם הַלּוֶֹה בַּמִּלְוֶה אֵינוֹ גּוֹבֶה מִמֶּנּוּ מִן הַמְשֻׁעְבָּדִים. אֲבָל אִם כָּתוּב בַּשְּׁטָר פְּלוֹנִי לָוָה מִפְּלוֹנִי כָּךְ וְכָךְ וּפְלוֹנִי עָרֵב שֶׁהֲרֵי עֵרְבוֹ לוֶֹה עִם עָרֵב בַּשְּׁטָר וְקָנוּ מִיָּדוֹ שֶׁל עָרֵב וְאַחַר כָּךְ חָתְמוּ עֵדִים בַּשְּׁטָר הֲרֵי זֶה נִפְרָע מִנִּכְסֵי עָרֵב הַמְשֻׁעְבָּדִים:","מַלְוֶה שֶׁתָּבַע אֶת הַלּוֶֹה וְלֹא מָצָא לוֹ נְכָסִים אֵינוֹ יָכוֹל לְהִפָּרַע מִן הֶעָרֵב עַד אַחַר שְׁלֹשִׁים יוֹם מִיּוֹם שֶׁנִּתְחַיֵּב הֶעָרֵב לְשַׁלֵּם. לֹא יִהְיֶה כֹּחַ זֶה פָּחוֹת מִן הַלּוֶֹה עַצְמוֹ. וְכָזֶה הוֹרוּ הַמּוֹרִים. וְאִם הִתְנָה עִמּוֹ הַכּל לְפִי הַתְּנַאי:","מַלְוֶה שֶׁבָּא לִתְבֹּעַ אֶת הַלּוֶֹה וְלֹא מָצָא לוֹ נְכָסִים אֵינוֹ יָכוֹל לִדְחוֹתוֹ וְלוֹמַר לֵךְ אֵצֶל הַקַּבְּלָן הֲרֵי יֵשׁ לְךָ לִתְבֹּעַ אוֹתוֹ תְּחִלָּה אֶלָּא תּוֹבֵעַ כָּל מִי שֶׁרָצָה תְּחִלָּה. וְאִם נָשָׂא הַקַּבְּלָן הַמָּעוֹת מִיַּד הַמַּלְוֶה וּנְתָנוֹ בְּיַד הַלּוֶֹה אֵין לַמַּלְוֶה בְּיַד הַלּוֶֹה כְּלוּם. הָיָה הַלּוֶֹה בִּמְדִינָה אַחֶרֶת שֶׁאֵינוֹ יָכוֹל לְהוֹדִיעוֹ וְלֹא לֵילֵךְ אֵלָיו אוֹ שֶׁמֵּת הַלּוֶֹה וְהִנִּיחַ יְתוֹמִים קְטַנִּים שֶׁאֵין בֵּית דִּין נִזְקָקִין לְנִכְסֵיהֶן הֲרֵי זֶה תּוֹבֵעַ אֶת הֶעָרֵב תְּחִלָּה שֶׁהֲרֵי אֵין הַלּוֶֹה מָצוּי:","מַלְוֶה שֶׁתָּבַע אֶת הַלּוֶֹה וּמְצָאוֹ שֶׁהוּא עָנִי אֵינוֹ יָכוֹל לְהִפָּרַע מִן הֶעָרֵב עַד שֶׁיִּשָּׁבַע הַלּוֶֹה בְּתַקָּנַת אַחֲרוֹנִים שֶׁאֵין לוֹ כְּלוּם שֶׁמָּא יַעֲשׂוּ קְנוּנְיָא עַל נְכָסָיו שֶׁל עָרֵב:","מִי שֶׁהָיָה עָרֵב לַחֲבֵרוֹ בְּמִלְוֶה עַל פֶּה וּבָא הַמַּלְוֶה לִתְבֹּעַ אֶת הֶעָרֵב וַהֲרֵי הַלּוֶֹה בִּמְדִינַת הַיָּם. אוֹמֵר לוֹ הֶעָרֵב הָבֵא רְאָיָה שֶׁלֹּא פְּרָעֲךָ הַלּוֶֹה וַאֲנִי אֲשַׁלֵּם לְךָ:","עָרֵב שֶׁקָּדַם וְנָתַן לְבַעַל חוֹב אֶת חוֹבוֹ הֲרֵי זֶה חוֹזֵר וְגוֹבֶה מִן הַלּוֶֹה כָּל מַה שֶּׁפָּרַע עַל יָדוֹ אַף עַל פִּי שֶׁהָיְתָה מִלְוֶה עַל פֶּה אוֹ בְּלֹא עֵדִים כְּלָל. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁאָמַר לוֹ הַלּוֶֹה בְּעֵת שֶׁנַּעֲשָׂה לוֹ עָרֵב עָרְבֵנִי וְשַׁלֵּם. אֲבָל אִם עָמַד בִּרְשׁוּת עַצְמוֹ וְנַעֲשָׂה לוֹ עָרֵב אוֹ קַבְּלָן אוֹ שֶׁאָמַר לוֹ הַלּוֶֹה עָרְבֵנִי וְלֹא הִרְשָׁהוּ שֶׁיִּתֵּן וְיִפְרַע הַחוֹב אֵין הַלּוֶֹה חַיָּב לְשַׁלֵּם לוֹ כְּלוּם. וְכֵן הַפּוֹרֵעַ שְׁטַר חוֹבוֹ שֶׁל חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ אֲפִלּוּ הָיָה הַחוֹב עַל הַמַּשְׁכּוֹן אֵין הַלּוֶֹה חַיָּב כְּלוּם וְנוֹטֵל מַשְׁכּוֹנוֹ בְּחִנָּם וַהֲרֵי אִבֵּד זֶה הַנּוֹתֵן אֶת מְעוֹתָיו שֶׁמָּא הָיָה הַלּוֶֹה מְפַיֵּס אֶת הַמַּלְוֶה וּמוֹחֵל לוֹ. מֵת הַלּוֶֹה וְקָדַם הֶעָרֵב וּפָרַע הַחוֹב קֹדֶם שֶׁיּוֹדִיעַ אֶת הַיּוֹרְשִׁים אִם נוֹדַע לָנוּ שֶׁלֹּא פָּרַע הַלּוֶֹה שְׁטַר חוֹבוֹ קֹדֶם שֶׁיָּמוּת כְּגוֹן שֶׁהוֹדָה בּוֹ קֹדֶם אוֹ שֶׁנִּדּוּהוּ וּמֵת בְּנִדּוּיוֹ אוֹ שֶׁלֹּא הִגִּיעַ זְמַן הַמִּלְוֶה לְהִגָּבוֹת הֲרֵי זֶה חוֹזֵר וְגוֹבֶה מִן הַיּוֹרְשִׁין כָּל מַה שֶּׁפָּרַע. הָיָה הַמַּלְוֶה עַכּוּ\"ם אֵין הַיּוֹרְשִׁין חַיָּבִין לְשַׁלֵּם שֶׁמָּא אֲבִיהֶן נָתַן לְיַד הֶעָרֵב כָּל הַחוֹב שֶׁהָיָה עָלָיו מִפְּנֵי שֶׁהָעַכּוּ\"ם תּוֹבֵעַ אֶת הֶעָרֵב תְּחִלָּה וּלְפִיכָךְ פָּרַע זֶה מִדַּעְתּוֹ קֹדֶם שֶׁיּוֹדִיעַ הַיְתוֹמִים. אֲבָל אִם הוֹדִיעָן שֶׁהָעַכּוּ\"ם תּוֹבֵעַ אוֹתוֹ וַהֲרֵי הוּא נוֹתֵן חַיָּבִין לְשַׁלֵּם:","כָּל עָרֵב שֶׁבָּא לִטּל מַה שֶּׁפָּרַע בֵּין שֶׁבָּא לְהִפָּרַע מִיּוֹרְשֵׁי לוֶֹה בֵּין מִלֹּוֶה עַצְמוֹ הֲרֵי זֶה צָרִיךְ לְהָבִיא רְאָיָה שֶׁפָּרַע. וְאֵין מְצִיאַת שְׁטַר הַחוֹב שֶׁעָלָיו בְּיַד הֶעָרֵב רְאָיָה שֶׁמָּא נָפַל הַשְּׁטָר מִיַּד הַמַּלְוֶה וְלֹא פָּרַע זֶה כְּלוּם:","הָאוֹמֵר לַחֲבֵרוֹ עָרַבְתָּ לִי וְהוּא אוֹמֵר לֹא עָרַבְתִּי. אוֹ שֶׁאָמַר הֶעָרֵב לַלּוֶֹה אַתָּה הִרְשֵׁיתַנִי לַעֲרֹב אוֹתְךָ וְלִתֵּן וְהוּא אוֹמֵר מִדַּעְתְּךָ עָרַבְתָּ אוֹ לֹא עָרַבְתָּ כְּלָל. אוֹ שֶׁאָמַר הֶעָרֵב פָּרַעְתִּי הַמִּלְוֶה בְּפָנֶיךָ וְהַלָּה אוֹמֵר לֹא פָּרַעְתָּ. אוֹ שֶׁאָמַר לוֹ כֵּן פָּרַעְתָּ וְנָתַתִּי לְךָ מַה שֶּׁפָּרַעְתָּ. אוֹ שֶׁאָמַר הַמַּלְוֶה עָרַבְתָּ לִי מָאתַיִם וְהוּא אוֹמֵר לֹא עָרַבְתִּי אֶלָּא מָנֶה. מִכָּל אֵלּוּ הַטְּעָנוֹת וְכַיּוֹצֵא בָּהֶן הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. אוֹ יִשָּׁבַע הַנִּתְבָּע שְׁבוּעַת הֶסֵּת אוֹ שְׁבוּעַת הַתּוֹרָה אִם הוֹדָה בְּמִקְצָת כִּשְׁאָר כָּל טַעֲנַת הַמָּמוֹן:","עֶבֶד אוֹ אֵשֶׁת אִישׁ שֶׁלָּווּ אוֹ שֶׁעָרְבוּ אֶת אֲחֵרִים וְנִתְחַיְּבוּ לְשַׁלֵּם. כְּשֶׁיִּשְׁתַּחְרֵר הָעֶבֶד וְתִתְגָּרֵשׁ הָאִשָּׁה אוֹ תִּתְאַלְמֵן יְשַׁלְּמוּ:","קָטָן שֶׁלָּוָה חַיָּב לְשַׁלֵּם כְּשֶׁיַּגְדִּיל וְאֵין כּוֹתְבִין עָלָיו שְׁטָר אֶלָּא הֲרֵי הִיא מִלְוֶה עַל פֶּה אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ שֶׁאֵין קִנְיָן מִיַּד הַקָּטָן כְּלוּם:","קָטָן שֶׁעָרַב אֶת אֲחֵרִים הוֹרוּ הַגְּאוֹנִים שֶׁאֵינוֹ חַיָּב לְשַׁלֵּם כְּלוּם אַף כְּשֶׁיַּגְדִּיל וְזֶה שֶׁנָּתַן אֶת מְעוֹתָיו עַל פִּי הַקָּטָן אִבֵּד אֶת מְעוֹתָיו שֶׁאֵין לְקָטָן דַּעַת כְּדֵי לְשַׁעְבֵּד עַצְמוֹ בְּדָבָר שֶׁאֵינוֹ חַיָּב בּוֹ וְלֹא בְּעַרְבָנוּת וְלֹא בְּכָל כַּיּוֹצֵא בָּזֶה. וְדִין אֱמֶת הוּא וְכֵן רָאוּי לָדוּן:","הָאִשָּׁה שֶׁלָּוְתָה בִּשְׁטָר אוֹ עָרְבָה בִּשְׁטָר וְנִשֵּׂאת חַיֶּבֶת לְשַׁלֵּם אַחַר שֶׁנִּשֵּׂאת. וְאִם הָיְתָה מִלְוֶה עַל פֶּה אֵינָהּ מְשַׁלֶּמֶת עַד שֶׁתִּתְגָּרֵשׁ אוֹ שֶׁתִּתְאַלְמֵן שֶׁרְשׁוּת בַּעַל כִּרְשׁוּת לוֹקֵחַ הוּא כְּמוֹ שֶׁבֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת. וְאִם הָיוּ אוֹתָן מְעוֹת הַהַלְוָאָה עַצְמָן קַיָּמִין יַחְזִירוּ אוֹתָן לַמַּלְוֶה:"],"Mishneh Torah, Daily Offerings and Additional Offerings 3":["מִצְוַת עֲשֵׂה לְהַקְטִיר הַקְּטֹרֶת עַל מִזְבַּח הַזָּהָב שֶׁבַּהֵיכָל פַּעֲמַיִם בְּכָל יוֹם בַּבֹּקֶר וּבֵין הָעַרְבַּיִם שֶׁנֶּאֱמַר (שמות ל ז) \"וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים\". לֹא הִקְטִירוּ בַּבֹּקֶר יַקְטִירוּ בֵּין הָעַרְבַּיִם אֲפִלּוּ הָיוּ מְזִידִין. וְאֵין מְחַנְּכִין מִזְבַּח הַזָּהָב אֶלָּא בִּקְטֹרֶת שֶׁל בֵּין הָעַרְבַּיִם:","כַּמָּה מַקְטִירִין מִמֶּנָּה בְּכָל יוֹם. מִשְׁקַל מֵאָה דִּינָרִין. חֲמִשִּׁים בַּבֹּקֶר וַחֲמִשִּׁים בֵּין הָעַרְבַּיִם. מִזְבֵּחַ שֶׁנֶּעֱקַר מַקְטִירִין הַקְּטֹרֶת בִּמְקוֹמוֹ. וּקְטֹרֶת שֶׁפָּקְעָה מֵעַל הַמִּזְבֵּחַ אֲפִלּוּ קְרָטִין שֶׁבָּהּ אֵין מַחֲזִירִין אוֹתָן:","בְּעֵת שֶׁמַּקְטִירִין הַקְּטֹרֶת בַּהֵיכָל בְּכָל יוֹם פּוֹרְשִׁין כָּל הָעָם מִן הַהֵיכָל וּמִבֵּין הָאוּלָם וְלַמִּזְבֵּחַ לֹא יִהְיֶה שָׁם אָדָם עַד שֶׁיֵּצֵא זֶה שֶׁהִקְטִיר הַקְּטֹרֶת. וְכֵן בְּשָׁעָה שֶׁיִּכָּנֵס בְּדַם חַטָּאוֹת הַנַּעֲשׂוֹת בִּפְנִים פּוֹרְשִׁים הַכּל מִבֵּין הָאוּלָם וְלַמִּזְבֵּחַ עַד שֶׁיֵּצֵא שֶׁנֶּאֱמַר (ויקרא טז יז) \"וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבֹאוֹ לְכַפֵּר בַּקֹּדֶשׁ\" וְגוֹ' בִּנְיַן אָב לְכָל כַּפָּרָה שֶׁבַּקֹּדֶשׁ שֶׁלֹּא יְהֵא שָׁם אָדָם:","כֵּיצַד סֵדֶר הַקְטָרַת הַקְּטֹרֶת בְּכָל יוֹם. מִי שֶׁזָּכָה בְּדִשּׁוּן הַמִּזְבֵּחַ הַפְּנִימִי נִכְנַס בִּכְלִי קֹדֶשׁ וְטֶנִי הָיָה שְׁמוֹ וְשֶׁל זָהָב הָיָה וּמַחֲזִיק קַבַּיִם וָחֵצִי. מַנִּיחַ הַטֶּנִי בָּאָרֶץ לְפָנָיו וְחוֹפֵן בְּיָדָיו הָאֵפֶר וְהַפֶּחָם שֶׁבְּתוֹךְ הַמִּזְבֵּחַ וְנוֹתֵן לְתוֹךְ הַטֶּנִי. וּבָאַחֲרוֹנָה מְכַבֵּד אֶת הַשְּׁאָר לְתוֹכוֹ וּמַנִּיחוֹ שָׁם בַּהֵיכָל וְיוֹצֵא. וּמִי שֶׁזָּכָה בַּקְּטֹרֶת נוֹטֵל כְּלִי מָלֵא קְטֹרֶת גָּדוּשׁ. וְכִסּוּי הָיָה לוֹ וּבָזָךְ הָיָה שְׁמוֹ וְנוֹתֵן הַבָּזָךְ בְּתוֹךְ כְּלִי אַחֵר וְכַף הָיָה שְׁמוֹ. וּמְכַסֶּה אֶת הַכַּף בְּבֶגֶד קָטָן וְאוֹחֵז הַכַּף בְּיָדוֹ וְנִכְנַס עִמּוֹ אֶחָד בַּמַּחְתָּה שֶׁל אֵשׁ בְּיָדוֹ:","וְכֵיצַד חוֹתֶה. זֶה שֶׁזָּכָה בְּמַחְתָּה לוֹקֵחַ מַחְתָּה שֶׁל כֶּסֶף וְעוֹלֶה לְרֹאשׁ הַמִּזְבֵּחַ וּמְפַנֶּה אֶת הַגֶּחָלִים אֵילָךְ וְאֵילָךְ. וְנוֹטֵל מִן הַגֶּחָלִים שֶׁנִּתְאַכְּלוּ בְּמַעֲרָכָה שְׁנִיָּה. וְיוֹרֵד וּמְעָרָן לְתוֹךְ מַחְתָּה שֶׁל זָהָב. אִם נִתְפַּזְּרוּ מִן הַגֶּחָלִים כְּמוֹ קַב אוֹ פָּחוֹת מְכַבְּדָן לָאַמָּה. וּבְשַׁבָּת כּוֹפֶה עֲלֵיהֶן הַפְּסַכְתֵּר. וְאִם נִתְפַּזֵּר יֶתֶר עַל קַב חוֹזֵר וְחוֹתֶה:","שְׁלֹשָׁה דְּבָרִים הָיָה הַפְּסַכְתֵּר מְשַׁמֵּשׁ. כּוֹפִין אוֹתוֹ עַל הַגֶּחָלִים. וְעַל הַשֶּׁרֶץ בְּשַׁבָּת. וּמוֹרִידִין בּוֹ אֶת הַדֶּשֶׁן מֵעַל הַמִּזְבֵּחַ:","וּמַקְדִּים לִפְנֵיהֶם זֶה שֶׁדִּשֵּׁן הַמִּזְבֵּחַ הַפְּנִימִי וְנוֹטֵל הַטֶּנִי שֶׁבּוֹ דִּשׁוּן הַמִּזְבֵּחַ וּמִשְׁתַּחֲוֶה וְיוֹצֵא. וְזֶה שֶׁבְּיָדוֹ הַמַּחְתָּה צוֹבֵר אֶת הַגֶּחָלִים עַל גַּבֵּי הַמִּזְבֵּחַ הַפְּנִימִי וּמְרַדְּדָן בְּשׁוּלֵי הַמַּחְתָּה וּמִשְׁתַּחֲוֶה וְיוֹצֵא. וְזֶה שֶׁבְּיָדוֹ הַכַּף נוֹטֵל אֶת הַבָּזָךְ מִתּוֹךְ הַכַּף וְנוֹתְנוֹ לְאוֹהֲבוֹ אוֹ לִקְרוֹבוֹ וְרוֹאֶה אִם נִתְפַּזֵּר מִן הַקְּטֹרֶת מְעַט בְּכַף אוֹהֲבוֹ אוֹ קְרוֹבוֹ נוֹתֵן לוֹ לְתוֹךְ חָפְנָיו זֶה שֶׁנִּתְפַּזֵּר עִם הַקְּטֹרֶת שֶׁבַּבָּזָךְ וּמִשְׁתַּחֲוֶה וְיוֹצֵא:","וְאוֹמְרִין לָזֶה הַמַּקְטִיר הִזָּהֵר שֶׁלֹּא תַּתְחִיל מִלְּפָנֶיךָ שֶׁלֹּא תִּכָּוֶה. וּמַתְחִיל וּמַשְׁלִיךְ הַקְּטֹרֶת עַל הָאֵשׁ בְּנַחַת כְּמִי שֶׁמְּרַקֵּד סלֶת עַד שֶׁתִּתְרַדֵּד עַל כָּל הָאֵשׁ:","וְאֵין הַמַּקְטִיר מַקְטִיר עַד שֶׁהַמְמֻנֶּה אוֹמֵר לוֹ הַקְטֵר. וְאִם כֹּהֵן גָּדוֹל הוּא אוֹמֵר לוֹ הַמְמֻנֶּה אִישִׁי כֹּהֵן גָּדוֹל הַקְטֵר. וְאַחַר שֶׁאוֹמֵר יִפְרְשׁוּ כָּל הָעָם וְיַקְטִיר הַמַּקְטִיר וְיִשְׁתַּחֲוֶה וְיֵצֵא:","דִּשׁוּן הַמְּנוֹרָה וַהֲטָבַת הַנֵּרוֹת בַּבֹּקֶר וּבֵין הָעַרְבַּיִם מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (שמות כז כא) \"יַעֲרֹךְ אֹתוֹ אַהֲרֹן וּבָנָיו\". וְהַדְלָקַת הַנֵּרוֹת דּוֹחָה אֶת הַשַּׁבָּת וְאֶת הַטֻּמְאָה כְּקָרְבָּנוֹת שֶׁקָּבוּעַ לָהֶן זְמַן שֶׁנֶּאֱמַר (שמות כז כ) (ויקרא כד ב) \"לְהַעֲלֹת נֵר תָּמִיד\":","וְכַמָּה שֶׁמֶן הוּא נוֹתֵן לְכָל נֵר. חֲצִי לוֹג שֶׁמֶן שֶׁנֶּאֱמַר (שמות כז כא) (ויקרא כד ג) \"מֵעֶרֶב עַד בֹּקֶר\" תֵּן לוֹ כַּמִּדָּה שֶׁיִּהְיֶה דּוֹלֵק מֵעֶרֶב עַד בֹּקֶר. וְאֵין מְחַנְּכִין אֶת הַמְּנוֹרָה אֶלָּא בְּהַדְלָקַת שִׁבְעָה נֵרוֹתֶיהָ בֵּין הָעַרְבַּיִם:","מַהוּ דִּשׁוּן הַמְּנוֹרָה. כָּל נֵר שֶׁכָּבָה מֵסִיר הַפְּתִילָה וְכָל הַשֶּׁמֶן שֶׁבַּנֵּר וּמְקַנְּחוֹ וְנוֹתֵן בּוֹ פְּתִילָה אַחֶרֶת וְשֶׁמֶן אַחֵר בְּמִדָּה וְהוּא חֲצִי לוֹג. וְזֶה שֶׁהֵסִיר מַשְׁלִיכוֹ בִּמְקוֹם הַדֶּשֶׁן אֵצֶל הַמִּזְבֵּחַ עִם דִּשׁוּן הַמִּזְבֵּחַ הַפְּנִימִי וְהַחִיצוֹן וּמַדְלִיק נֵר שֶׁכָּבָה. וְהַדְלָקַת הַנֵּרוֹת הִיא הֲטָבָתָם. וְנֵר שֶׁמְּצָאוֹ שֶׁלֹּא כָּבָה מְתַקְּנוֹ:","נֵר מַעֲרָבִי שֶׁכָּבָה אֵין מַדְלִיקִין אוֹתוֹ אַחַר דִּשּׁוּנוֹ אֶלָּא מִמִּזְבַּח הַחִיצוֹן. אֲבָל שְׁאָר הַנֵּרוֹת כָּל נֵר שֶׁכָּבָה מֵהֶן מַדְלִיקוֹ מִנֵּר חֲבֵרוֹ:","וְכֵיצַד מַדְלִיקוֹ. מוֹשֵׁךְ הַפְּתִילָה עַד שֶׁמַּדְלִיקָהּ וּמַחֲזִירָהּ. לְפִי שֶׁהַנֵּרוֹת קְבוּעִים בַּמְּנוֹרָה וְאֵינוֹ יָכוֹל לְהַדְלִיק בְּנֵר אַחֵר מִשּׁוּם בִּזָּיוֹן:","כָּל הַפְּתִילוֹת שֶׁאָסוּר לְהַדְלִיק בָּהֶן בְּשַׁבָּת אָסוּר לְהַדְלִיק בָּהֶן בַּמִּקְדָּשׁ בַּמְּנוֹרָה שֶׁנֶּאֱמַר (שמות כז כ) (ויקרא כד ב) \"לְהַעֲלֹת נֵר תָּמִיד\" שֶׁתְּהֵא שַׁלְהֶבֶת עוֹלָה מֵאֵלֶיהָ:","לֹא הָיָה מֵטִיב כָּל הַנֵּרוֹת בְּפַעַם אַחַת אֶלָּא מֵטִיב חֲמִשָּׁה נֵרוֹת וּמַפְסִיק וְעוֹשִׂין עֲבוֹדָה אַחֶרֶת וְאַחַר כָּךְ נִכְנָס וּמֵטִיב הַשְּׁנַיִם. כְּדֵי לְהַרְגִּישׁ אֶת כָּל הָעֲזָרָה:","כָּל נֵר שֶׁכָּבָה מַדְלִיקִין אוֹתוֹ מִנֵּר אַחֵר מֵהֶן כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵיצַד סֵדֶר הַהֲטָבָה. זֶה שֶׁזָּכָה בְּדִשׁוּן הַמְּנוֹרָה נִכְנָס וּכְלִי בְּיָדוֹ וְכוּז שְׁמוֹ וְשֶׁל זָהָב הָיָה דּוֹמֶה לְקִיתוֹן גָּדוֹל. מְדַשֵּׁן בּוֹ אֶת הַפְּתִילוֹת שֶׁכָּבוּ וְאֶת הַשֶּׁמֶן הַנִּשְׁאָר בַּנֵּר וְמֵטִיב חֲמִשָּׁה נֵרוֹת וּמַנִּיחַ הַכּוּז שָׁם לִפְנֵי הַמְּנוֹרָה עַל מַעֲלָה שְׁנִיָּה מִשָּׁלֹשׁ מַעֲלוֹת שֶׁלְּפָנֶיהָ וְיוֹצֵא. וְאַחַר כָּךְ נִכְנָס וּמֵטִיב שְׁנֵי הַנֵּרוֹת וְנוֹטֵל הַכּוּז בְּיָדוֹ וּמִשְׁתַּחֲוֶה וְיוֹצֵא:","חֲבִיתֵי כֹּהֵן גָּדוֹל מִצְוַת עֲשֵׂה לְהַקְרִיבָן בְּכָל יוֹם מֶחֱצָה בַּבֹּקֶר עִם תָּמִיד שֶׁל שַׁחַר וּמֶחֱצָה בֵּין הָעַרְבַּיִם עִם תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְלִישָׁתָן וַאֲפִיָּתָן דּוֹחִין אֶת הַשַּׁבָּת וְאֶת הַטֻּמְאָה כְּכָל קָרְבָּן שֶׁקָּבוּעַ לוֹ זְמַן שֶׁנֶּאֱמַר (ויקרא ו יד) \"תֻּפִינֵי\" שֶׁתְּהֵא נָאָה וְלֹא תֵּאָפֶה מִבָּעֶרֶב. וְעוֹד אִם תֵּאָפֶה מִבָּעֶרֶב תִּפָּסֵל בְּלִינָה שֶׁהַמַּרְחֶשֶׁת מִכְּלֵי הַקֹּדֶשׁ הִיא כְּמוֹ שֶׁבֵּאַרְנוּ:","טְחִינַת סָלְתָּן וְהֶרְקֵדָן בַּחוּץ וְאֵינָן דּוֹחִין אֶת הַשַּׁבָּת:","כֹּהֵן שֶׁהִקְרִיב מֶחֱצָה בְּשַׁחֲרִית וּמֵת אוֹ נִטְמָא אוֹ נוֹלַד לוֹ מוּם וּמִנּוּ כֹּהֵן אַחֵר תַּחְתָּיו לֹא יָבִיא חֲצִי עִשָּׂרוֹן מִבֵּיתוֹ וְלֹא חֲצִי עִשָּׂרוֹן שֶׁל רִאשׁוֹן. אֶלָּא מֵבִיא עִשָּׂרוֹן שָׁלֵם וְחוֹצֵהוּ וּמַקְרִיב מֶחֱצָה וּמֶחֱצָה אָבֵד:","נִמְצְאוּ שְׁנֵי חֲצָאִים קְרֵבִין וּשְׁנֵי חֲצָאִין אוֹבְדִין. וְאֵלּוּ שְׁנֵי הַחֲצָאִין הָאוֹבְדִים מַנִּיחִין אוֹתָן עַד שֶׁתְּעֻבַּר צוּרָתָן וְיוֹצְאִין לְבֵית הַשְּׂרֵפָה. וְכֵן אִם אָבַד אוֹ נִטְמָא הַחֵצִי שֶׁל בֵּין הָעַרְבַּיִם. וְהֵיכָן שׂוֹרְפִין אוֹתָן, בָּעֲזָרָה:","מֵת כֹּהֵן גָּדוֹל בְּשַׁחֲרִית אַחַר שֶׁהִקְרִיב חֲצִי הָעִשָּׂרוֹן וְלֹא מִנּוּ כֹּהֵן אַחֵר מְבִיאִין הַיּוֹרְשִׁין עִשָּׂרוֹן שָׁלֵם עֲבוּר כַּפָּרָתוֹ וְעוֹשִׂין אוֹתוֹ חֲבִיתִין וּשְׁלֵמָה הָיְתָה קְרֵבָה. מֵת כֹּהֵן גָּדוֹל קֹדֶם שֶׁיַּקְרִיבוֹ בַּבֹּקֶר וְלֹא מִנּוּ כֹּהֵן אַחֵר מַקְרִיבִין אוֹתוֹ עִשָּׂרוֹן שָׁלֵם בַּבֹּקֶר וְעִשָּׂרוֹן שָׁלֵם בֵּין הָעַרְבַּיִם. וְאֵין כּוֹפְלִין שַׁמְנָהּ וּלְבוֹנָתָהּ אַף עַל פִּי שֶׁנִּכְפְּלָה הַסּלֶת. אֶלָּא מַפְרִישִׁין לָהֶם שְׁלֹשָׁה לוֹגֵי שֶׁמֶן וְקֹמֶץ לְבוֹנָה. לוֹג וּמֶחֱצָה שֶׁמֶן וַחֲצִי קֹמֶץ לְבוֹנָה לְעִשָּׂרוֹן שֶׁל בֹּקֶר וְלוֹג וּמֶחֱצָה שֶׁמֶן וַחֲצִי קֹמֶץ לְבוֹנָה לְעִשָּׂרוֹן שֶׁל בֵּין הָעַרְבַּיִם:"],"Mishneh Torah, Damages to Property 14":["הַמַּדְלִיק בְּתוֹךְ שְׂדֵה חֲבִרוֹ וְעָבְרָה הַדְּלֵקָה [וְהִזִּיקָה] חַיָּב לְשַׁלֵּם נֵזֶק שָׁלֵם שֶׁנֶּאֱמַר (שמות כב ה) \"כִּי תֵצֵא אֵשׁ וּמָצְאָה קֹצִים וְנֶאֱכַל גָּדִישׁ אוֹ הַקָּמָה\" וְגוֹ' שַׁלֵּם יְשַׁלֵּם הַמַּבְעִר וְגוֹ'. וְהַבְּעֵרָה מֵאֲבוֹת נְזִיקִין הִיא:","הִדְלִיק בְּתוֹךְ רְשׁוּתוֹ צָרִיךְ לְהַרְחִיק מִסּוֹף הַמֵּצַר כְּדֵי שֶׁלֹּא תַּעֲבֹר הַדְּלֵקָה לִשְׂדֵה חֲבֵרוֹ. וְכַמָּה שִׁעוּר הַהַרְחָקָה הַכּל לְפִי גֹּבַהּ הַדְּלֵקָה. וְאִם לֹא הִרְחִיק כָּרָאוּי וְעָבְרָה הָאֵשׁ וְהִזִּיקָה חַיָּב לְשַׁלֵּם נֵזֶק שָׁלֵם. הִרְחִיק כָּרָאוּי וְעָבְרָה וְהִזִּיקָה פָּטוּר שֶׁזּוֹ מַכָּה בִּידֵי שָׁמַיִם הִיא. וְכֵן אִם עָבְרָה נָהָר אוֹ שְׁלוּלִית שֶׁיֵּשׁ בָּהֶן מַיִם וְרָחְבָּן שְׁמוֹנֶה אַמּוֹת פָּטוּר:","עָבְרָה גָּדֵר אוֹמְדִין גֹּבַהּ הַגָּדֵר וְגֹבַהּ הַדְּלֵקָה וְהָעֵצִים אוֹ הַקּוֹצִים הַמְּצוּיִין שָׁם אִם אֵינָהּ רְאוּיָה לַעֲבֹר פָּטוּר וְאִם רְאוּיָה לַעֲבֹר חַיָּב. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֵשׁ הַקּוֹדַחַת. אֲבָל אִם הָיָה לָהּ לַהַב גָּדוֹל הָעוֹלֶה וְנִכְפָּף מִגֹּבַהּ עֲלִיַּת הַלַּהַב וְהָיוּ עֵצִים מְצוּיִין שָׁם אֵין לָהּ אֹמֶד אֶלָּא אֲפִלּוּ עָבְרָה אֶלֶף אַמָּה חַיָּב:","נָפְלָה דְּלֵקָה בַּחֲצֵרוֹ וְנָפַל גָּדֵר שֶׁלֹּא מֵחֲמַת הַדְּלֵקָה וְעָבְרָה הַדְּלֵקָה בְּחָצֵר אַחֶרֶת. אִם הָיָה יָכוֹל לִגְדֹּר הַגָּדֵר שֶׁנָּפַל וְלֹא גְּדָרוֹ חַיָּב. לְמָה הַדָּבָר דּוֹמֶה לְשׁוֹרוֹ שֶׁיָּצָא וְהִזִּיק שֶׁהָיָה לוֹ לְשָׁמְרוֹ וְלֹא שְׁמָרוֹ:","הַשּׁוֹלֵחַ אֶת הַבְּעֵרָה בְּיַד חֵרֵשׁ שׁוֹטֶה וְקָטָן פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמָּסַר לָהֶן גַּחֶלֶת וְלִבּוּהָ שֶׁדֶּרֶךְ הַגַּחֶלֶת לְהִכָּבוֹת מֵאֵלֶיהָ קֹדֶם שֶׁתַּעֲבֹר וְתַדְלִיק. אֲבָל אִם מָסַר לָהֶן שַׁלְהֶבֶת חַיָּב שֶׁהֲרֵי מַעֲשָׂיו גָּרְמוּ:","שָׁלַח אֶת הַבְּעֵרָה בְּיַד פִּקֵּחַ זֶה הַפִּקֵּחַ שֶׁהִבְעִיר חַיָּב לְשַׁלֵּם וְהַשּׁוֹלֵחַ פָּטוּר. וְכֵן אִם הִנִּיחַ שׁוֹמֵר לִשְׁמֹר הַבְּעֵרָה הַשּׁוֹמֵר חַיָּב:","אֶחָד הֵבִיא אֶת הָאוּר וְאֶחָד הֵבִיא אֶת הָעֵצִים הַמֵּבִיא אֶת הָעֵצִים חַיָּב. אֶחָד הֵבִיא אֶת הָעֵצִים וְאֶחָד הֵבִיא אֶת הָאוּר הַמֵּבִיא אֶת הָאוּר חַיָּב. בָּא אַחֵר וְלִבָּהּ הַמְלַבֶּה חַיָּב. לִבַּתּוּ רוּחַ שֶׁאֵינָהּ מְצוּיָה תָּמִיד הֲרֵי כֻּלָּן פְּטוּרִין. לִבָּה וְלִבַּתּוּ הָרוּחַ חַיָּב שֶׁהֲרֵי הוּא גָּרַם וְכָל הַגּוֹרֵם לְהַזִּיק מְשַׁלֵּם נֵזֶק שָׁלֵם מִן הַיָּפֶה שֶׁבַּנְּכָסִים כִּשְׁאָר כָּל הַמַּזִּיקִין:","אֵשׁ שֶׁיָּצְאָה וְאָכְלָה עֵצִים אוֹ אֲבָנִים אוֹ עָפָר חַיָּב לְשַׁלֵּם שֶׁנֶּאֱמַר (שמות כב ה) \"וּמָצְאָה קֹצִים\" כוּ' (שמות כב ה) \"אוֹ הַשָּׂדֶה\". אָכְלָה גָּדִישׁ וְכַיּוֹצֵא בּוֹ וְהָיוּ כֵּלִים טְמוּנִים בְּתוֹךְ הַגָּדִישׁ אִם הָיוּ כְּגוֹן מוֹרִיגִים וּכְלֵי בָּקָר וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים שֶׁדֶּרֶךְ אַנְשֵׁי הַשָּׂדֶה לְטָמְנָם בַּגָּדִישׁ חַיָּב לְשַׁלֵּם. הָיוּ בְּגָדִים וּכְלֵי זְכוּכִית וְכַיּוֹצֵא בָּהֶן פָּטוּר עַל הַכֵּלִים:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמַדְלִיק בְּתוֹךְ שְׂדֵה חֲבֵרוֹ. אֲבָל בְּמַדְלִיק בְּתוֹךְ שֶׁלּוֹ וְעָבְרָה לִשְׂדֵה חֲבֵרוֹ פָּטוּר עַל כָּל הַכֵּלִים הַטְּמוּנִים בַּגָּדִישׁ אֲבָל מְשַׁלֵּם הוּא שִׁעוּר מְקוֹם הַכֵּלִים וְרוֹאִין אוֹתוֹ כְּאִלּוּ הוּא מָלֵא גָּדִישׁ שֶׁל חִטִּים אוֹ שֶׁל שְׂעוֹרִים:","הַמַּדְלִיק בְּתוֹךְ שְׂדֵה חֲבֵרוֹ וְיָצְאָה הָאֵשׁ וְנֶאֱכַל הַגָּדִישׁ וְהָיָה גְּדִי כָּפוּת לוֹ וְעֶבֶד סָמוּךְ לוֹ וְנִשְׂרַף עִמּוֹ חַיָּב. שֶׁכֵּן דֶּרֶךְ בְּנֵי אָדָם לַעֲשׂוֹת בְּגָדִישׁ. הָיָה עֶבֶד כָּפוּת לוֹ וּגְדִי סָמוּךְ לוֹ וְנִשְׂרַף עִמּוֹ פָּטוּר:","הַמַּשְׁאִיל מָקוֹם לַחֲבֵרוֹ וְהִגְדִּישׁ בּוֹ וְהִטְמִין בּוֹ כֵּלִים וְהִדְלִיק הַמַּשְׁאִיל וְשָׂרַף הַגָּדִישׁ אֵינוֹ מְשַׁלֵּם אֶלָּא דְּמֵי גָּדִישׁ בִּלְבַד. הִשְׁאִילוֹ מָקוֹם לְהַגְדִּישׁ חִטִּים וְהִגְדִּישׁ שְׂעוֹרִים אוֹ לְהַגְדִּישׁ שְׂעוֹרִים וְהִגְדִּישׁ חִטִּים אוֹ שֶׁהִגְדִּישׁ חִטִּים וְחִפָּם בִּשְׂעוֹרִים אוֹ שֶׁהִגְדִּישׁ שְׂעוֹרִים וְחִפָּם בְּחִטִּים אֵינוֹ מְשַׁלֵּם לוֹ אֶלָּא דְּמֵי שְׂעוֹרִים בִּלְבַד:","הַמַּדְלִיק אֶת הַבִּירָה שֶׁל חֲבֵרוֹ מְשַׁלֵּם כָּל מַה שֶּׁבְּתוֹכָהּ. שֶׁכֵּן דֶּרֶךְ בְּנֵי אָדָם לְהַנִּיחַ כָּל כְּלֵיהֶם וְכָל חֶפְצֵיהֶם בַּבָּתִּים. וְכָל שֶׁיִּטְעֹן בַּעַל הַבַּיִת הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל. וּשְׁבוּעָה זוֹ מִדִּבְרֵי סוֹפְרִים כְּמוֹ שֶׁיִּתְבָּאֵר. וּבִלְבַד שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶן אוֹ שֶׁהוּא לָמוּד לִהְיוֹת אוֹתָן הַדְּבָרִים שֶׁטָּעַן פִּקָּדוֹן אֶצְלוֹ:","גָּמָל שֶׁהוּא טָעוּן פִּשְׁתָּן וְעוֹבֵר בִּרְשׁוּת הָרַבִּים וְנִכְנַס פִּשְׁתָּנוֹ לְתוֹךְ הַחֲנוּת וְדָלְקָה בְּנֵרוֹ שֶׁל חֶנְוָנִי וְהִדְלִיק אֶת כָּל הַבִּירָה בַּעַל הַגָּמָל חַיָּב מִפְּנֵי שֶׁהִרְבָּה בְּמַשּׂאוֹי בֵּין שֶׁעָמְדָה הַבְּהֵמָה בֵּין שֶׁלֹּא עָמְדָה. הִנִּיחַ הַחֶנְוָנִי נֵרוֹ מִבַּחוּץ הַחֶנְוָנִי חַיָּב אַף בִּדְמֵי פִּשְׁתָּן מִפְּנֵי שֶׁהִנִּיחַ נֵרוֹ מִבַּחוּץ. וַאֲפִלּוּ נֵר חֲנֻכָּה הָיָה לוֹ לֵישֵׁב וְלִשְׁמֹר:","הַכּוֹפֵף קָמָתוֹ שֶׁל חֲבֵרוֹ לִפְנֵי הָאֵשׁ עַד שֶׁתִּדְלַק אִם אֵין הָאֵשׁ מַגַּעַת לָהּ אֶלָּא בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. וְהַטּוֹמֵן קָמָתוֹ שֶׁל חֲבֵרוֹ בְּעָפָר אוֹ בְּתֶבֶן וְעָבְרָה הָאֵשׁ וְאָכְלָה אוֹתָהּ הֲרֵי הַטּוֹמֵן פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם מִפְּנֵי שֶׁהַמַּדְלִיק אֶת הָאֵשׁ פָּטוּר עַל הַטָּמוּן:","אֵשׁ שֶׁעָבְרָה וְהִזִּיקָה אֶת הָאָדָם וְחָבְלָה בּוֹ הֲרֵי הַמַּבְעִיר חַיָּב בִּנְזָקָיו וּבְשִׁבְתּוֹ וּבְרִפּוּיוֹ וּבְצַעֲרוֹ וּבְבָשְׁתּוֹ כְּאִלּוּ הִזִּיקוֹ בְּיָדוֹ. שֶׁאַף עַל פִּי שֶׁאִשּׁוֹ מָמוֹנוֹ הוּא הֲרֵי הוּא כְּמוֹ שֶׁהִזִּיקָה בְּחִצָיו. אֲבָל אִם הִזִּיקָה בְּהֶמְתּוֹ אוֹ בּוֹרוֹ אֶת הָאָדָם אֵינוֹ חַיָּב אֶלָּא בְּנֵזֶק בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל תּוֹלְדוֹת הָאֵשׁ הֲרֵי הֵן כְּאֵשׁ. כֵּיצַד. הִנִּיחַ אֶבֶן אוֹ סַכִּין אוֹ מַשָּׂא בְּרֹאשׁ גַּגּוֹ וְנָפְלוּ בְּרוּחַ מְצוּיָה וְהִזִּיקוּ חַיָּב לְשַׁלֵּם נֵזֶק שָׁלֵם שֶׁכָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן תּוֹלְדוֹת הַבְּעֵרָה הֵן. וְאִם נָפְלוּ בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה וְהִזִּיקוּ פָּטוּר: סְלִיקוּ לְהוּ הִלְכוֹת נִזְקֵי מָמוֹן בְּסַ\"ד"],"Mishneh Torah, Defilement by Leprosy 12":["צָרַעַת בְּגָדִים כִּגְרִיס, כְּצָרַעַת אָדָם. אֲבָל פָּחוֹת מִכִּגְרִיס טָהוֹר. וּשְׁלֹשָׁה סִימָנֵי טֻמְאָה יֵשׁ בָּהֶן. יְרַקְרַק אֲדַמְדַּם וְהַפִּשְׂיוֹן. וּשְׁלָשְׁתָּן מְפֹרָשִׁין בַּתּוֹרָה. יְרַקְרַק הוּא הַיָּרֹק שֶׁבַּיְרֻקִּין שֶׁהוּא יָרֹק הַרְבֵּה כִּכְנַף הַטַּוָּס וּכְהוּצֵי הַדֶּקֶל. וַאֲדַמְדַּם הוּא אָדֹם שֶׁבָּאֲדֻמִּים שֶׁהוּא אָדֹם הַרְבֵּה כִּזְהוֹרִית יָפָה. וּשְׁנֵי מַרְאוֹת אֵלּוּ מִצְטָרְפִין זֶה עִם זֶה בְּמַרְאֶה יְרַקְרַק אוֹ אֲדַמְדַּם מַסְגִּירִין אֶת הַבֶּגֶד. וְאִם עָמַד בְּמַרְאֶה זֶה שְׁנֵי שָׁבוּעוֹת מַחְלִיטִין וְשׂוֹרְפִין וְכֵן אִם פָּשָׂה מַחְלִיטִין וְשׂוֹרְפִין. כֵּיצַד. בֶּגֶד שֶׁנִּרְאֶה בּוֹ נֶגַע יְרַקְרַק אוֹ אֲדַמְדַּם מַסְגִּירוֹ שִׁבְעַת יָמִים וּבַשְּׁבִיעִי רוֹאֶה אִם פָּשָׂה מַחְלִיטוֹ וְשׂוֹרֵף אֶת כָּל הַבֶּגֶד. וְאִם עָמַד בְּמַרְאֵהוּ וְלֹא פָּשָׂה אוֹ שֶׁפָּשָׂה וְכֵהָה מִשְּׁנֵי הַמַּרְאוֹת שֶׁהֻסְגַּר בָּהֶן אוֹ שֶׁהוֹסִיף הַמַּרְאֶה לְהַאֲדִים וּלְהוֹרִיק וְלֹא פָּשָׂה יְכַבֵּס מְקוֹם הַנֶּגַע וְיַסְגִּיר שִׁבְעַת יָמִים שֵׁנִית וּבְסוֹף שָׁבוּעַ שֵׁנִי שֶׁהוּא יוֹם שְׁלֹשָׁה עָשָׂר רוֹאֶה. אִם כֵּהָה לְמַרְאֶה שְׁלִישִׁית הֲרֵי זֶה טָעוּן כִּבּוּס וְטָהוֹר. וְאִם נִשְׁתַּנָּה הַנֶּגַע מִמַּה שֶּׁהָיָה כְּגוֹן שֶׁהָיָה יְרַקְרַק וְנַעֲשָׂה אֲדַמְדַּם אוֹ אֲדַמְדַּם וְנַעֲשָׂה יְרַקְרַק קוֹרֵעַ מְקוֹם הַנֶּגַע וְשׂוֹרֵף מַה שֶּׁקָּרַע וְתוֹפֵר מַטְלִית בַּמָּקוֹם שֶׁקָּרַע וּפוֹטֵר שְׁאָר הַבֶּגֶד וּמְכַבְּסוֹ כֻּלּוֹ כִּבּוּס שֵׁנִי וּמַטְבִּילוֹ, וְטָהֵר. וְאִם עָמַד בַּמַּרְאֶה שֶׁהֻסְגַּר בּוֹ בַּתְּחִלָּה יַחְלִיטוֹ וְיִשְׂרֹף אֶת כֻּלּוֹ:","נֶגַע שֶׁהָיָה יְרַקְרַק וּפָשָׂה אֲדַמְדַּם אוֹ שֶׁהָיָה אֲדַמְדַּם וּפָשָׂה יְרַקְרַק הֲרֵי זֶה פִּשְׂיוֹן:","נֶגַע שֶׁהָיָה בְּאֶמְצָעוֹ מָקוֹם נָקִי בְּלֹא נֶגַע וּפָשָׂה לוֹ הַנֶּגַע אֵינוֹ פִּשְׂיוֹן עַד שֶׁיִּפְשֶׂה לַחוּץ. שֶׁאֵין פִּשְׂיוֹן הַנֶּגַע לְתוֹכוֹ פִּשְׂיוֹן בֵּין בְּאָדָם בֵּין בִּבְגָדִים וּבָתִּים:","הַפִּשְׂיוֹן הַסָּמוּךְ בַּבְּגָדִים כָּל שֶׁהוּא וְהָרָחוֹק אוֹ הַחוֹזֵר כִּגְרִיס. כֵּיצַד. בֶּגֶד שֶׁהֻסְגַּר וְנוֹלַד בּוֹ נֶגַע אַחֵר כִּגְרִיס רָחוֹק מִן הַנֶּגַע שֶׁהֻסְגַּר בּוֹ הֲרֵי זֶה פִּשְׂיוֹן וְיִשָּׂרֵף. וְאִם הָיָה פָּחוֹת מִכִּגְרִיס אֵין מַשְׁגִּיחִין בּוֹ. וְכֵן בֶּגֶד שֶׁקָּרַע מִמֶּנּוּ הַנֶּגַע בְּסוֹף שָׁבוּעַ שֵׁנִי כְּמוֹ שֶׁבֵּאַרְנוּ וְחָזַר בּוֹ נֶגַע כִּגְרִיס יִשָּׂרֵף. וְכֵן בֶּגֶד שֶׁפָּשָׂה בּוֹ הַנֶּגַע אַחַר שֶׁנִּפְטַר יִשָּׂרֵף:","מִי שֶׁמְּכַבֵּס אֶת הַנֶּגַע בְּשָׁבוּעַ רִאשׁוֹן כְּמוֹ שֶׁבֵּאַרְנוּ צָרִיךְ לְכַבֵּס מְעַט מִן הַבֶּגֶד שֶׁחוּצָה לוֹ שֶׁנֶּאֱמַר (ויקרא יג נד) \"אֵת אֲשֶׁר בּוֹ הַנָּגַע\". וְכָל נִגְעֵי בְּגָדִים שֶׁמְּכַבְּסִין אוֹתָן מַעֲבִירִין עֲלֵיהֶן שִׁבְעָה סַמְמָנִין שֶׁמַּעֲבִירִין עַל הַכֶּתֶם כְּדֶרֶךְ שֶׁמַּעֲבִירִין עַל הַכְּתָמִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן נִדָּה:","בֶּגֶד שֶׁקָּרַע מִמֶּנּוּ מְקוֹם הַנֶּגַע וְתָפַר מַטְלִית כְּמוֹ שֶׁבֵּאַרְנוּ וְחָזַר נֶגַע כִּגְרִיס עַל הַבֶּגֶד. מַתִּיר אֶת הַמַּטְלִית וּמַצִּילָהּ וְשׂוֹרֵף שְׁאָר הַבֶּגֶד. חָזַר הַנֶּגַע עַל הַמַּטְלִית שׂוֹרֵף אֶת הַכּל:","הַטּוֹלֶה מִן הַמֻּסְגָּר בְּטָהוֹר וְחָזַר נֶגַע עַל הַבֶּגֶד שׂוֹרֵף אֶת הַמַּטְלִית. חָזַר עַל הַמַּטְלִית הַבֶּגֶד הָרִאשׁוֹן הַמֻּסְגָּר יִשָּׂרֵף וְהַמַּטְלִית תְּשַׁמֵּשׁ אֶת הַבֶּגֶד שֶׁהִיא תְּפוּרָה בּוֹ בְּסִימָנִין. אִם עָמַד בְּעֵינָיו שְׁנֵי שָׁבוּעוֹת אוֹ פָּשָׂה שׂוֹרְפִין הַכּל:","בֶּגֶד שֶׁבָּא כֻּלּוֹ בַּתְּחִלָּה יְרַקְרַק אוֹ אֲדַמְדַּם מַסְגִּירוֹ שָׁבוּעַ אַחַר שָׁבוּעַ. אִם עָמַד בּוֹ שְׁנֵי שָׁבוּעוֹת יִשָּׂרֵף. אֲבָל בֶּגֶד שֶׁהִסְגִּירוֹ וּפָשָׂה הַנֶּגַע בְּכֻלּוֹ וְנַעֲשָׂה יְרַקְרַק אוֹ אֲדַמְדַּם אוֹ שֶׁפְּטָרוֹ וְאַחַר שֶׁפְּטָרוֹ בָּא כֻּלּוֹ יְרַקְרַק אוֹ אֲדַמְדַּם הֲרֵי זֶה טָהוֹר. כִּבֵּס וּפָשָׂה יִשָּׂרֵף:","בֶּגֶד שֶׁמּוֹכִין יוֹצְאִין עַל פָּנָיו מִן הָאָרִיג כְּגוֹן סָגוֹס שֶׁל צֶמֶר וְנִרְאָה בּוֹ נֶגַע אֵינוֹ מִתְטַמֵּא עַד שֶׁיֵּרָאֶה הַנֶּגַע בַּמּוֹכִין וּבָאָרִיג עַצְמוֹ. וְזֶה שֶׁנֶּאֱמַר בַּבְּגָדִים (ויקרא יג נה) \"בְּקָרַחְתּוֹ אוֹ בְגַבַּחְתּוֹ\" קָרַחְתּוֹ אֵלּוּ הַשְּׁחָקִים גַּבַּחְתּוֹ אֵלּוּ הַחֲדָשִׁים:","הַבְּגָדִים הַצְּבוּעִים אֵינָן מִטַּמְּאִין בִּנְגָעִים בֵּין שֶׁצְּבוּעִין בִּידֵי אָדָם בֵּין שֶׁצְּבוּעִין בִּידֵי שָׁמַיִם עַד שֶׁיְּהוּ לְבָנִים. בֶּגֶד שֶׁשִּׁתְיוֹ צָבוּעַ וְעֶרְבוֹ לָבָן עֶרְבוֹ צָבוּעַ וְשִׁתְיוֹ לָבָן הַכּל הוֹלֵךְ אַחַר הַנִּרְאֶה. פָּחוֹת מִשָּׁלֹשׁ אֶצְבָּעוֹת עַל שָׁלֹשׁ אֶצְבָּעוֹת מִן הָאָרִיג אֵינוֹ מִטַּמֵּא בִּנְגָעִים:","בֶּגֶד שֶׁאָרַג בּוֹ פָּחוֹת מִשָּׁלֹשׁ עַל שָׁלֹשׁ וְנִרְאָה בּוֹ נֶגַע וְאַחַר כָּךְ הִשְׁלִימוֹ לְשָׁלֹשׁ עַל שָׁלֹשׁ טָהוֹר:","הַתּוֹפֵר מַטְלִיּוֹת שֶׁאֵין בְּכָל אַחַת מֵהֶן שָׁלֹשׁ עַל שָׁלֹשׁ וְעָשָׂה מֵהֶן בֶּגֶד הֲרֵי זֶה מִטַּמֵּא בִּנְגָעִים שֶׁהַתָּפוּר כְּאָרוּג וְכֻלּוֹ בֶּגֶד אֶחָד הוּא:","בֶּגֶד שֶׁהוּא מַטְלִיּוֹת מַטְלִיּוֹת מֵהֶן צְבוּעִין וּמֵהֶן לְבָנִים וְנִרְאָה נֶגַע בַּלָּבָן שֶׁבּוֹ מַסְגִּירִין אוֹתוֹ אִם עָמַד שְׁנֵי שָׁבוּעוֹת נִטְמָא כֻּלּוֹ וְיִשָּׂרֵף. וְכֵן אִם פָּשָׂה הַנֶּגַע בְּמַטְלִית לְבָנָה אַחֶרֶת הֲרֵי זֶה פִּשְׂיוֹן אַף עַל פִּי שֶׁיֵּשׁ בֵּינֵיהֶם צָבוּעַ. הָיָה כֻּלּוֹ צָבוּעַ וּבוֹ פַּס אֶחָד לָבָן אֲפִלּוּ כִּגְרִיס וְנִרְאָה בּוֹ נֶגַע יַסְגִּיר שֶׁאִם עָמַד בְּעֵינָיו וְלֹא הוֹסִיף וְלֹא כֵּהָה שְׁנֵי שָׁבוּעוֹת יִשָּׂרֵף:"],"Mishneh Torah, Defilement by Leprosy 9":["הַכּל מִתְטַמְּאִין בִּנְגָעִים אֲפִלּוּ קָטָן בֶּן יוֹמוֹ וְהָעֲבָדִים אֲבָל לֹא עַכּוּ\"ם וְלֹא גֵּר תּוֹשָׁב. וְהַכּל כְּשֵׁרִין לִרְאוֹת אֶת הַנְּגָעִים. וְכָל הַנְּגָעִים אָדָם רוֹאֶה אוֹתָן חוּץ מִנִּגְעֵי עַצְמוֹ:","אַף עַל פִּי שֶׁהַכּל כְּשֵׁרִין לִרְאוֹת נְגָעִים הַטֻּמְאָה וְהַטָּהֳרָה תְּלוּיָה בְּכֹהֵן. כֵּיצַד. כֹּהֵן שֶׁאֵינוֹ יוֹדֵעַ לִרְאוֹת הֶחָכָם רוֹאֵהוּ וְאוֹמֵר לוֹ אֱמֹר טָמֵא וְהַכֹּהֵן אוֹמֵר טָמֵא. אֱמֹר טָהוֹר וְהַכֹּהֵן אוֹמֵר טָהוֹר. הַסְגִּירוֹ וְהוּא מַסְגִּירוֹ. שֶׁנֶּאֱמַר (דברים כא ה) \"וְעַל פִּיהֶם יִהְיֶה כָּל רִיב וְכָל נֶגַע\". וַאֲפִלּוּ הָיָה הַכֹּהֵן קָטָן אוֹ שׁוֹטֶה הֶחָכָם אוֹמֵר לוֹ וְהוּא מַחְלִיט אוֹ פּוֹטֵר אוֹ סוֹגֵר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַכֹּהֵן סוֹמֵךְ עַל דִּבְרֵי הֶחָכָם. אֲבָל אִם הָיָה הַכֹּהֵן רוֹאֶה וְסוֹמֵךְ עַל עַצְמוֹ אָסוּר לוֹ לִרְאוֹת נֶגַע מִכָּל נְגָעִים עַד שֶׁיּוֹרֶנּוּ רַבּוֹ וְיִהְיֶה בָּקִי בְּכָל הַנְּגָעִים וּבִשְׁמוֹתֵיהֶן בְּנִגְעֵי אָדָם כֻּלָּם וּבְנִגְעֵי בְּגָדִים וּבְנִגְעֵי בָּתִּים:","כֹּהֵן שֶׁטִּמֵּא אֶת הַטָּהוֹר אוֹ טִהֵר אֶת הַטָּמֵא לֹא עָשָׂה כְּלוּם שֶׁנֶּאֱמַר (ויקרא יג מד) \"טָמֵא הוּא\" (ויקרא יג מד) \"וְטִמְּאוֹ הַכֹּהֵן\" (ויקרא יג לז) \"טָהוֹר הוּא\" (ויקרא יג לז) \"וְטִהֲרוֹ הַכֹּהֵן\". וּמְצֹרָע שֶׁנִּרְפָּא בֵּין מִתּוֹךְ הֶסְגֵּר בֵּין מִתּוֹךְ הֶחְלֵט אֲפִלּוּ אַחַר כַּמָּה שָׁנִים הֲרֵי זֶה בְּטֻמְאָתוֹ עַד שֶׁיֹּאמַר לוֹ כֹּהֵן טָהוֹר אַתָּה:","אֵין הַכֹּהֵן רַשַּׁאי לְטַמֵּא אֶת הַטָּמֵא עַד שֶׁיִּהְיוּ עֵינָיו בִּמְקוֹם הַנֶּגַע בְּעוֹר הַבָּשָׂר שֶׁחוּצָה לוֹ. וְכֹהֵן שֶׁרָאָה הַנֶּגַע בַּתְּחִלָּה הוּא שֶׁרוֹאֵהוּ בְּסוֹף שָׁבוּעַ רִאשׁוֹן וּבְסוֹף שָׁבוּעַ שֵׁנִי וְהוּא שֶׁמַּסְגִּירוֹ אוֹ מַחְלִיטוֹ אוֹ פּוֹטְרוֹ. מֵת הַכֹּהֵן שֶׁרָאָהוּ תְּחִלָּה אוֹ שֶׁחָלָה רוֹאֵהוּ כֹּהֵן אַחֵר וְאֵין הַשֵּׁנִי יָכוֹל לְטַמְּאוֹ בְּפִשְׂיוֹן שֶׁאֵין יוֹדֵעַ אִם פָּשָׂה אִם לֹא פָּשָׂה אֶלָּא רִאשׁוֹן. וְנֶאֱמָן כֹּהֵן לוֹמַר נֶגַע זֶה פָּשָׂה וְנֶגַע זֶה לֹא פָּשָׂה. וְשֵׂעָר לָבָן זֶה קָדַם אֶת הַבַּהֶרֶת אוֹ בַּהֶרֶת זוֹ קָדְמָה אֶת שֵׂעָר לָבָן:","חָלָל פָּסוּל לִרְאִיַּת נְגָעִים שֶׁנֶּאֱמַר (ויקרא יג ב) \"אֶחָד מִבָּנָיו הַכֹּהֲנִים\" בִּכְהֻנָּתָם. אֲבָל בַּעֲלֵי מוּמִין כְּשֵׁרִים לִרְאִיַּת נְגָעִים וּבִלְבַד שֶׁלֹּא יִהְיֶה סוּמָא וַאֲפִלּוּ בְּאַחַת מֵעֵינָיו. וַאֲפִלּוּ כֹּהֵן שֶׁכָּהָה מְאוֹר עֵינָיו לֹא יִרְאֶה אֶת הַנְּגָעִים שֶׁנֶּאֱמַר (ויקרא יג יב) \"לְכָל מַרְאֵה עֵינֵי הַכֹּהֵן\":","אֵין רוֹאִין אֶת הַנְּגָעִים אֶלָּא בַּיּוֹם בֵּין לְהַסְגִּיר בֵּין לְהַחְלִיט בֵּין לִפְטֹר. שֶׁהֲרֵי בְּכָל הָעִנְיָן הוּא אוֹמֵר בַּיּוֹם וּבַיּוֹם. וְאֵין רוֹאִין לֹא בְּשַׁחֲרִית וְלֹא בֵּין הָעַרְבַּיִם וְלֹא בְּתוֹךְ הַבַּיִת וְלֹא בַּיּוֹם הַמְעֻנָּן לְפִי שֶׁכֵּהָה נִרְאֵית עַזָּה. וְלֹא בַּצָּהֳרַיִם לְפִי שֶׁעַזָּה נִרְאֵית כֵּהָה. אֵימָתַי רוֹאִין אוֹתָן בְּשָׁעָה רְבִיעִית וּבַחֲמִישִׁית וּבַשְּׁמִינִית וּבַתְּשִׁיעִית. בֵּין נִגְעֵי אָדָם בֵּין נִגְעֵי בְּגָדִים וּבָתִּים:","בְּכָל יוֹם רוֹאִין אֶת הַנְּגָעִים חוּץ מִשַּׁבָּת וְיוֹם טוֹב. חָל יוֹם שְׁבִיעִי שֶׁלּוֹ לִהְיוֹת בְּשַׁבָּת אוֹ בְּיוֹם טוֹב מַעֲבִירִין לַאֲחוֹרָיו. וְיֵשׁ בַּדָּבָר לְהָקֵל וּלְהַחְמִיר. שֶׁאֶפְשָׁר שֶׁיִּהְיֶה בְּיוֹם שַׁבָּת זֶה שֶׁהוּא יוֹם הָרָאוּי לִרְאוֹת טָמֵא וּלְמָחָר יֵלְכוּ לָהֶן סִימָנֵי טֻמְאָה. וְאֶפְשָׁר שֶׁיִּהְיֶה טָהוֹר וּלְמָחָר יִוָּלְדוּ לוֹ סִימָנֵי טֻמְאָה. וְאֵין דָּנִין אוֹתוֹ אֶלָּא בִּשְׁעַת רְאִיָּתוֹ לְאַחַר הַשַּׁבָּת:","חָתָן שֶׁנִּרְאָה בּוֹ נֶגַע נוֹתְנִין לוֹ כָּל שִׁבְעַת יְמֵי הַמִּשְׁתֶּה. וְכֵן אִם נִרְאָה בִּבְגָדָיו אוֹ בְּבֵיתוֹ אֵין רוֹאִין אוֹתָן עַד לְאַחַר הַמִּשְׁתֶּה. וְכֵן בָּרֶגֶל נוֹתְנִין לוֹ כָּל יְמוֹת הָרֶגֶל שֶׁנֶּאֱמַר (ויקרא יד לו) \"וְצִוָּה הַכֹּהֵן וּפִנּוּ אֶת הַבַּיִת\" וְגוֹ' אִם הִמְתִּינָה תּוֹרָה לִדְבַר הָרְשׁוּת שֶׁלֹּא יִטַּמְּאוּ כֵּלָיו קַל וָחֹמֶר לִדְבַר מִצְוָה:","אֵין מַסְגִּירִין וְלֹא מַחְלִיטִין וְלֹא פּוֹטְרִין אֶלָּא בַּיּוֹם שֶׁיִּרְאֶה בּוֹ בַּתְּחִלָּה אוֹ בַּשְּׁבִיעִי אוֹ בְּיוֹם שְׁלֹשָׁה עָשָׂר בִּנְגָעִים שֶׁמַּסְגִּירִין בָּהֶן שְׁנֵי שָׁבוּעוֹת. מִפְּנֵי שֶׁיּוֹם שְׁבִיעִי עוֹלֶה לְמִנְיַן שָׁבוּעַ רִאשׁוֹן וּלְמִנְיַן שָׁבוּעַ שֵׁנִי בְּכָל הַנְּגָעִים בֵּין בְּנִגְעֵי אָדָם בֵּין בְּנִגְעֵי בָּתִּים וּבְגָדִים:","אֵין מַסְגִּירִין בְּתוֹךְ יְמֵי הֶסְגֵּר וְלֹא מַחְלִיטִין בְּתוֹךְ יְמֵי הֶסְגֵּר אִם נוֹלַד לוֹ סִימַן הֶחְלֵט. וְלֹא מַחְלִיטִין הַמֻּחְלָט אִם נוֹלַד לוֹ נֶגַע אַחֵר. וְלֹא מַסְגִּירִין אוֹתוֹ בְּתוֹךְ יְמֵי חִלּוּטוֹ אִם נוֹלַד לוֹ נֶגַע אַחֵר שֶׁרָאוּי לְהֶסְגֵּר. אֲבָל אִם הָיוּ בּוֹ שְׁנֵי נְגָעִים וְרָאָה זֶה וְחָזַר וְרָאָה זֶה הֲרֵי זֶה מֻתָּר לוֹמַר לוֹ הֲרֵי אַתָּה מֻסְגָּר בָּזֶה וּמֻחְלָט בָּזֶה אוֹ מֻחְלָט בָּזֶה וּמֻסְגָּר בָּזֶה בֵּין בַּתְּחִלָּה בֵּין בַּסּוֹף בֵּין בְּסוֹף שָׁבוּעַ רִאשׁוֹן בֵּין בְּסוֹף שָׁבוּעַ שֵׁנִי. וְאֵין רוֹאִין שְׁנֵי נְגָעִים כְּאַחַת בֵּין בִּשְׁנֵי אֲנָשִׁים בֵּין בְּאִישׁ אֶחָד שֶׁנֶּאֱמַר (ויקרא יג ג) \"וְרָאָה הַכֹּהֵן אֶת הַנֶּגַע\":","נָגוּעַ שֶׁבָּא לַכֹּהֵן לַרְאוֹתוֹ לֹא יֹאמַר לוֹ לֵךְ וְשׁוּב אֶלָּא נִזְקָק לוֹ מִיָּד. בָּאוּ לְפָנָיו שְׁנַיִם רוֹאֶה אֶת הָרִאשׁוֹן מַסְגִּירוֹ אוֹ פּוֹטְרוֹ אוֹ מַחְלִיטוֹ וְחוֹזֵר וְרוֹאֶה אֶת הַשֵּׁנִי:","אֵין הַכֹּהֵן זָקוּק לְבַקֵּשׁ תַּחַת אַצִּילֵי יָדָיו שֶׁל נָגוּעַ אוֹ בֵּין פְּחָדָיו אוֹ בְּתוֹךְ הַקְּמָטִים שֶׁמָּא שָׁם נֶגַע שֶׁנֶּאֱמַר (ויקרא יג יב) \"לְכָל מַרְאֵה עֵינֵי הַכֹּהֵן\". וְכֵן בְּהוֹפֵךְ כֻּלּוֹ לָבָן. וְכֵיצַד יַעֲמֹד לִפְנֵי הַכֹּהֵן. אִם אִישׁ הוּא נִרְאֶה עָרֹם וְעוֹמֵד כְּעוֹדֵר וּכְמוֹסֵק זֵיתִים. וְאִם אִשָּׁה הִיא נִרְאֵית עֲרֻמָּה וְיוֹשֶׁבֶת כְּעוֹרֶכֶת וּכְמֵינִיקָה אֶת בְּנָהּ וּכְאוֹרֶגֶת בְּעוֹמְדִים שֶׁמַּגְבַּהַת יָדָהּ הַיְמָנִית עַד שֶׁיִּגָּלֶה בֵּית הַשֶּׁחִי. אִם הָיָה הַנֶּגַע נִרְאֶה בָּהֶן בִּזְמַן שֶׁהֵן עוֹמְדִין הֲרֵי זֶה טָמֵא וְאִם אֵינוֹ נִרְאָה בָּהֶן כְּשֶׁהֵן עוֹמְדִין כָּךְ אֵין נִזְקָקִין לוֹ. וּכְשֵׁם שֶׁהָאָדָם נִרְאֶה לְנִגְעוֹ כָּךְ הוּא נִרְאֶה לְתִגְלַחְתּוֹ שֶׁאִם לֹא יֵרָאֶה שֵׂעָר בְּכָל בְּשָׂרוֹ כְּשֶׁיַּעֲמֹד עָרֹם כְּעוֹדֵר וּכְמוֹסֵק אוֹ כְּשֶׁתֵּשֵׁב הָאִשָּׁה כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי זוֹ תִּגְלַחַת כְּשֵׁרָה וְאֵין כֹּהֵן זָקוּק לְחַפֵּשׂ בִּשְׁאָר מְקוֹמוֹת שֶׁמָּא נִשְׁאַר בָּהֶן שֵׂעָר אַף עַל פִּי שֶׁהוּא צָרִיךְ לְגַלֵּחַ הַכּל כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Defilement by a Corpse 2":["הַנֵּפֶל אַף עַל פִּי שֶׁעֲדַיִן לֹא נִתְקַשְּׁרוּ אֵיבָרָיו בְּגִידִין מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל כְּאָדָם גָּדוֹל שֶׁמֵּת שֶׁנֶּאֱמַר (במדבר יט יא) \"הַנֹּגֵעַ בְּמֵת לְכָל נֶפֶשׁ אָדָם\". וְכֵן כְּזַיִת מִבְּשַׂר הַמֵּת בֵּין לַח בֵּין יָבֵשׁ כְּחֶרֶשׂ מְטַמֵּא כְּמֵת שָׁלֵם. וְהַנֶּצֶל בַּבָּשָׂר מְטַמֵּא בִּכְזַיִת. אֵיזֶהוּ נֶצֶל זֶה הַבָּשָׂר שֶׁנִּמּוֹחַ וְנַעֲשֶׂה לֵחָה סְרוּחָה. וְהוּא שֶׁתִּקְרשׁ אוֹתָהּ הַלֵּחָה הַנִּמְצֵאת מִן הַמֵּת שֶׁאִם קָרְשָׁה בְּיָדוּעַ שֶׁהוּא מִבְּשָׂרוֹ וְאִם לֹא קָרְשָׁה אֵינָהּ מְטַמְּאָה שֶׁמָּא כִּיחוֹ וְנִיעוֹ הוּא:","אַף עַל פִּי שֶׁהַשִּׁעוּרִין כֻּלָּם הֲלָכָה לְמשֶׁה מִסִּינַי הֵן אָמְרוּ חֲכָמִים תְּחִלַּת בְּרִיָּתוֹ שֶׁל אָדָם כְּזַיִת וּלְפִיכָךְ שִׁעוּר טֻמְאַת בְּשָׂרוֹ כְּזַיִת:","אֵיבָר שֶׁנֶּחְתַּךְ מִן הָאָדָם הַחַי הֲרֵי הוּא כְּמֵת שָׁלֵם מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל אֲפִלּוּ אֵיבָר קָטָן שֶׁל קָטָן בֶּן יוֹמוֹ שֶׁהָאֵיבָרִים אֵין לָהֶם שִׁעוּר שֶׁנֶּאֱמַר (במדבר יט טז) \"כּל אֲשֶׁר יִגַּע עַל פְּנֵי הַשָּׂדֶה בַּחֲלַל חֶרֶב\" וְהַדָּבָר יָדוּעַ שֶׁדִּין חֲלַל חֶרֶב כְּדִין חֲלַל אֶבֶן אוֹ חֲלַל שְׁאָר דְּבָרִים מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁלֹּא בָּא זֶה אֶלָּא לְטַמֵּא נוֹגֵעַ בְּאֵיבָר שֶׁפְּלָטַתּוּ הַחֶרֶב. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הָאֵיבָר שָׁלֵם כִּבְרִיָּתוֹ בָּשָׂר וְגִידִים וַעֲצָמוֹת שֶׁנֶּאֱמַר (במדבר יט טז) \"אוֹ בְעֶצֶם אָדָם\" עֶצֶם שֶׁהוּא כְּאָדָם מַה אָדָם בָּשָׂר וְגִידִים וַעֲצָמוֹת אַף אֵיבָר מִן הַחַי עַד שֶׁיִּהְיֶה כִּבְרִיָּתוֹ בָּשָׂר וְגִידִים וַעֲצָמוֹת. אֲבָל הַכֻּלְיָא וְהַלָּשׁוֹן וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁהֵן אֵיבָר בִּפְנֵי עַצְמָן הוֹאִיל וְאֵין בָּהֶן עֶצֶם הֲרֵי הֵן כִּשְׁאָר הַבָּשָׂר. חָסַר מִן הָעֶצֶם שֶׁל אֵיבָר כָּל שֶׁהוּא הֲרֵי הָאֵיבָר כֻּלּוֹ טָהוֹר. חָסַר מִבְּשָׂרוֹ אִם נִשְׁאַר עָלָיו בָּשָׂר שֶׁרָאוּי לַעֲלוֹת בּוֹ אֲרוּכָה בְּחַי וְיִתְרַפֵּא וְיִשָּׁלֵם. הֲרֵי זֶה מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל. וְאִם לָאו מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וְאֵינוֹ מְטַמֵּא בְּאֹהֶל. וּבָשָׂר הַפּוֹרֵשׁ מִן הַחַי טָהוֹר. וְכֵן עֶצֶם בְּלֹא בָּשָׂר הַפּוֹרֵשׁ מִן הַחַי טָהוֹר:","אֵיבָר הַפּוֹרֵשׁ מִן הַמֵּת מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל כְּמֵת וְהוּא שֶׁיִּהְיֶה שָׁלֵם כִּבְרִיָּתוֹ בָּשָׂר וְגִידִים וַעֲצָמוֹת. חָסַר עַצְמוֹ אִם נִשְׁאַר עָלָיו בָּשָׂר כְּזַיִת מְטַמֵּא כְּמֵת שָׁלֵם. חָסַר הַבָּשָׂר וְלֹא חָסַר הָעֶצֶם אִם נִשְׁאַר עָלָיו כְּדֵי לַעֲלוֹת אֲרוּכָה בְּחַי מְטַמֵּא כְּמֵת שָׁלֵם וְאִם לָאו הֲרֵי הוּא כִּשְׁאָר עַצְמוֹת הַמֵּתִים שֶׁאֵין עֲלֵיהֶן הַבָּשָׂר:","מֹחַ שֶׁבְּתוֹךְ הָעֶצֶם הֲרֵי הוּא מַעֲלֶה אֲרוּכָה מִבַּחוּץ. לְפִיכָךְ קוּלִית הַמֵּת וְהוּא עֶצֶם הַסָּתוּם מִשְּׁנֵי קְצוֹתָיו אִם יֵשׁ בְּתוֹכָהּ מֹחַ כְּדֵי לַעֲלוֹת אֲרוּכָה הֲרֵי זֶה כְּמֵת שָׁלֵם. הָיָה בָּהּ מֹחַ הַמִּתְנַדְנֵד אִם יֵשׁ בּוֹ כְּזַיִת הֲרֵי זֶה מְטַמֵּא בְּאֹהֶל אַף עַל פִּי שֶׁהָעֶצֶם סָתוּם מִכָּל צְדָדָיו טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת כְּמוֹ שֶׁיִּתְבָּאֵר שֶׁהַמֹּחַ כְּבָשָׂר לְכָל דָּבָר:","הָאֵיבָר וְהַבָּשָׂר הַמְדֻלְדָּלִים בָּאָדָם אַף עַל פִּי שֶׁאֵין יְכוֹלִין לַחְזֹר וְלִחְיוֹת טְהוֹרִים. מֵת הָאָדָם הֲרֵי הַבָּשָׂר טָהוֹר וְהָאֵיבָר מְטַמֵּא מִשּׁוּם אֵיבָר מִן הַחַי וְאֵינוֹ מְטַמֵּא מִשּׁוּם אֵיבָר מִן הַמֵּת. מַה בֵּין אֵיבָר מִן הַחַי לְאֵיבָר מִן הַמֵּת. אֵיבָר מִן הַחַי בָּשָׂר הַפּוֹרֵשׁ מִמֶּנּוּ וְעֶצֶם הַפּוֹרֵשׁ מִמֶּנּוּ טְהוֹרִים וְאֵיבָר מִן הַמֵּת בָּשָׂר הַפּוֹרֵשׁ מִמֶּנּוּ וְעֶצֶם הַפּוֹרֵשׁ מִמֶּנּוּ כִּמְפֹרָשִׁים מִן הַמֵּת הַשָּׁלֵם וּמְטַמְּאִין בְּשִׁעוּרָן:","וּבֵין אֵיבָר מִן הַחַי בֵּין אֵיבָר מִן הַמֵּת אֵין לָהֶן שִׁעוּר. אָמְרוּ חֲכָמִים מָאתַיִם שְׁמוֹנָה וְאַרְבָּעִים אֵיבָרִים יֵשׁ בָּאִישׁ כָּל אֶחָד וְאֶחָד מֵהֶן בָּשָׂר וְגִידִים וְעֶצֶם וְאֵין הַשִּׁנַּיִם מִן הַמִּנְיָן. וּבְאִשָּׁה מָאתַיִם וְאֶחָד וַחֲמִשִּׁים. כָּל אֵיבָר מֵהֶן שֶׁפֵּרֵשׁ כִּבְרִיָּתוֹ בֵּין מִן הַחַי בֵּין מִן הַמֵּת מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל חוּץ מִשְּׁלֹשָׁה אֵיבָרִים יְתֵרוֹת שֶׁבָּאִשָּׁה שֶׁאֵינָן מְטַמְּאִין בְּאֹהֶל. וְכֵן אֶצְבַּע יְתֵרָה שֶׁיֵּשׁ בָּהּ עֶצֶם וְאֵין בָּהּ צִפֹּרֶן אִם נִסְפֶּרֶת עַל גַּב הַיָּד עוֹלָה לְמִנְיַן רֹב הָאֵיבָרִים וְאִם אֵינָהּ נִסְפֶּרֶת עַל גַּב הַיָּד מְטַמְּאָה בְּמַגָּע וּבְמַשָּׂא וְאֵינָהּ מְטַמְּאָה בְּאֹהֶל וְטֻמְאָתָהּ מִדִּבְרֵי סוֹפְרִים. וְאִם הָיָה בָּהּ צִפֹּרֶן הֲרֵי הִיא כִּשְׁאָר הָאֵיבָרִים. וּמִפְּנֵי מָה גָּזְרוּ טֻמְאָה עַל אֶצְבַּע שֶׁאֵינָהּ נִסְפֶּרֶת גְּזֵרָה מִשּׁוּם הַנִּסְפֶּרֶת. וְלָמָּה לֹא טִמְּאוּהָ בְּאֹהֶל עָשׂוּ לָהּ הֶכֵּר כְּדֵי לְהוֹדִיעַ שֶׁטֻּמְאָתָהּ מִדִּבְרֵיהֶם מִשּׁוּם גְּזֵרָה כְּדֵי שֶׁלֹּא יִשְׂרְפוּ עַל טֻמְאָתָהּ תְּרוּמָה וְקָדָשִׁים:","עַצְמוֹת הַמֵּת שֶׁאֵין עֲלֵיהֶם בָּשָׂר אִם נִכֶּרֶת בָּהֶן צוּרַת עֲצָמוֹת הֲרֵי אֵלּוּ מְטַמְּאִין בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל כְּמֵת שָׁלֵם שֶׁאֲנִי קוֹרֵא בָּהֶם (במדבר יט טז) \"עֶצֶם אָדָם\". וְאֵלּוּ הֵן הָעֲצָמוֹת שֶׁהֵן מְטַמְּאִין כְּמֵת. הַשִּׁדְרָה וְהַגֻּלְגּלֶת וְרֹב בִּנְיָנוֹ וְרֹב מִנְיָנוֹ. הַשִּׁדְרָה כֵּיצַד. שִׁדְרָה שֶׁהִיא שְׁלֵמָה הֲרֵי הִיא כְּמֵת שָׁלֵם וְאִם חָסְרָה אֲפִלּוּ חֻלְיָא אַחַת מִשְּׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת הֲרֵי הִיא כִּשְׁאָר הָעֲצָמוֹת. הַגֻּלְגּלֶת כֵּיצַד. גֻּלְגּלֶת שֶׁהִיא שְׁלֵמָה הֲרֵי הִיא כְּמֵת וְאִם חָסְרָה כְּסֶלַע הֲרֵי הִיא כִּשְׁאָר הָעֲצָמוֹת. הָיוּ בָּהּ נְקָבִים קְטַנִּים כֻּלָּם מִצְטָרְפִין לִכְסֶלַע. כָּל בִּנְיָנוֹ שֶׁל אָדָם הוּא שְׁתֵּי הַשּׁוֹקַיִם וְהַיְרֵכַיִם וְהַצְּלָעוֹת וְהַשִּׁדְרָה. וְרֹב בִּנְיָנוֹ שֶׁל מֵת הֲרֵי הוּא כְּמֵת שָׁלֵם. כֵּיצַד. כְּגוֹן שְׁתֵּי שׁוֹקָיו וְיָרֵךְ אַחַת אִם חָסֵר רֹב בִּנְיָנוֹ כָּל שֶׁהוּא הֲרֵי הֵן כִּשְׁאָר הָעֲצָמוֹת. רֹב מִנְיָנוֹ כֵּיצַד. רֹב מִנְיַן עֲצָמוֹת כְּגוֹן שֶׁהָיוּ קכ\"ה עֶצֶם הֲרֵי אֵלּוּ כְּמֵת שָׁלֵם. הָיוּ קכ\"ד הֲרֵי הֵן כִּשְׁאָר הָעֲצָמוֹת. אַף עַל פִּי שֶׁהָיָה אָדָם זֶה יָתֵר בְּאֵיבָרָיו אוֹ חָסֵר בְּאֵיבָרָיו אֵין מַשְׁגִּיחִין בּוֹ אֶלָּא עַל מִנְיַן רֹב כָּל אָדָם אֶלָּא אִם כֵּן הָיְתָה אֶצְבַּע שֶׁיֵּשׁ בָּהּ צִפֹּרֶן אוֹ שֶׁהָיְתָה נִסְפֶּרֶת עַל גַּב הַיָּד שֶׁהִיא עוֹלָה לְמִנְיָן כְּמוֹ שֶׁבֵּאַרְנוּ:","שְׁאָר עַצְמוֹת הַמֵּת שֶׁאֵין בָּהֶן רֹב מִנְיַן וְלֹא רֹב בִּנְיָן וְלֹא שִׁדְרָה שְׁלֵמָה וְלֹא גֻּלְגּלֶת שְׁלֵמָה אִם הָיָה בָּהֶן רֹבַע הַקַּב הֲרֵי אֵלּוּ מְטַמְּאִים כְּמֵת בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל. הָיוּ פָּחוֹת מֵרֹבַע אֲפִלּוּ עֶצֶם כִּשְׂעוֹרָה מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וְאֵינוֹ מְטַמֵּא בְּאֹהֶל:","הָיָה עֶצֶם אֶחָד אֲפִלּוּ יֵשׁ בּוֹ רֹבַע הֲרֵי זֶה מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וְאֵינוֹ מְטַמֵּא בְּאֹהֶל. טֻמְאַת עֶצֶם אֶחָד הֲלָכָה מִפִּי הַשְּׁמוּעָה לְפִי שֶׁנֶּאֱמַר (במדבר יט יח) \"כָּל הַנּוֹגֵעַ בַּעֶצֶם\" לָמְדוּ מִפִּי הַשְּׁמוּעָה אֲפִלּוּ עֶצֶם כִּשְׂעוֹרָה מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא. וּלְפִי שֶׁטֻּמְאָתוֹ הֲלָכָה הֲרֵי הוּא דִּין תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים:","מֵת שֶׁהִרְקִיבוּ עַצְמוֹתָיו בַּקֶּבֶר וְנַעֲשׂוּ רֶקֶב. מְלֹא חָפְנַיִם מֵאוֹתוֹ רֶקֶב מְטַמֵּא בְּמַשָּׂא וּבְאֹהֶל כְּמֵת וְאֵינוֹ מְטַמֵּא בְּמַגָּע לְפִי שֶׁאִי אֶפְשָׁר לִגַּע בְּכֻלּוֹ שֶׁהֲרֵי אֵינוֹ גּוּף אֶחָד. וַאֲפִלּוּ גִּבְּלוֹ בְּמַיִם אֵינוֹ חִבּוּר:","דַּם הַמֵּת מְטַמֵּא כְּמֵת בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל. שֶׁנֶּאֱמַר (במדבר יט יג) \"בְּנֶפֶשׁ הָאָדָם\" וְנֶאֱמַר (דברים יב כג) \"כִּי הַדָּם הוּא הַנָּפֶשׁ\". וְכַמָּה שִׁעוּרוֹ רְבִיעִית. אֲפִלּוּ תַּמְצִית הַדָּם כָּל זְמַן שֶׁיֵּשׁ בּוֹ אַדְמוּמִית מְטַמֵּא בְּאֹהֶל הַמֵּת:","דַּם הַחַי אֲפִלּוּ דַּם נְחִירָה הֲרֵי זֶה טָהוֹר כָּל זְמַן שֶׁהוּא חַי. נִתְעָרֵב הַדָּם שֶׁיָּצָא מִמֶּנּוּ בָּאַחֲרוֹנָה סָמוּךְ לַמִּיתָה עִם הַדָּם שֶׁיָּצָא מִמֶּנּוּ אַחַר שֶׁמֵּת וְכָל הַתַּעֲרוֹבוֹת רְבִיעִית וְאֵין יָדוּעַ כַּמָּה יָצָא מֵחַיִּים וְכַמָּה יָצָא אַחַר מִיתָה. אֲפִלּוּ חֲצִי רְבִיעִית מֵחַיִּים וְחֶצְיָהּ אַחַר מִיתָה הֲרֵי זֶה נִקְרָא דַּם תְּבוּסָה וּמְטַמֵּא בְּמַשָּׂא וּבְמַגָּע וּבְאֹהֶל. אֶלָּא שֶׁטֻּמְאָתוֹ מִדִּבְרֵי סוֹפְרִים:","הָרוּג שֶׁהָיָה מֻטָּל עַל הַמִּטָּה וְדָמוֹ מְנַטֵּף כְּשֶׁהוּא חַי וְיוֹרֵד לְגֻמָּא וּמֵת וַהֲרֵי הַדָּם מְנַטֵּף אַחַר מוֹתוֹ וְיוֹרֵד לְאוֹתָהּ גֻּמָּא. הֲרֵי כָּל הַדָּם שֶׁבָּהּ טָהוֹר שֶׁטִּפָּה טִפָּה רִאשׁוֹנָה רִאשׁוֹנָה בָּטְלָה כְּדָם שֶׁיָּצָא מֵחַיִּים. יָצָא מִמֶּנּוּ רְבִיעִית דָּם בִּלְבַד וְסָפֵק כֻּלָּהּ מֵחַיִּים סָפֵק כֻּלָּהּ לְאַחַר מִיתָה הֲרֵי זוֹ סְפֵק טְמֵאָה כִּשְׁאָר הַסְּפֵקוֹת וְהַנּוֹגֵעַ בָּהּ בִּרְשׁוּת הַיָּחִיד טָמֵא בִּרְשׁוּת הָרַבִּים טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","הַקֶּבֶר כָּל זְמַן שֶׁהַטֻּמְאָה בְּתוֹכוֹ מְטַמֵּא בְּמַגָּע וּבְאֹהֶל כְּמֵת דִּין תּוֹרָה. שֶׁנֶּאֱמַר (במדבר יט טז) \"אוֹ בְמֵת אוֹ בְעֶצֶם אָדָם אוֹ בְקָבֶר\". וְאֶחָד הַנּוֹגֵעַ בְּגַגּוֹ שֶׁל קֶבֶר אוֹ הַנּוֹגֵעַ בִּכְתָלָיו. וְהוּא שֶׁיִּהְיֶה בָּנוּי וְסָתוּם וְאַחַר כָּךְ יִהְיֶה כֻּלּוֹ מְטַמֵּא בְּמַגָּע וּבְאֹהֶל. אֲבָל הַמַּעֲמִיד כֵּלִים אוֹ אֲבָנִים וְכַיּוֹצֵא בָּהֶן בְּצִדֵּי הַמֵּת וְכִסָּה עָלָיו מִלְּמַעְלָה בְּכֵלִים אוֹ בַּאֲבָנִים וְכַיּוֹצֵא בָּהֶן זֶה הַכִּסּוּי הַמֻּטָּל מִלְּמַעְלָה נִקְרָא גּוֹלֵל וְאֵלּוּ הַצְּדָדִין הַמַּעֲמִידִין אֶת הַגּוֹלֵל שֶׁהוּא נִשְׁעָן עֲלֵיהֶן נִקְרָאִין דּוֹפֵק. וּשְׁנֵיהֶם הַגּוֹלֵל אוֹ הַדּוֹפֵק מְטַמְּאִין בְּמַגָּע וּבְאֹהֶל כְּקֶבֶר וְטֻמְאָתָן מִדִּבְרֵי סוֹפְרִים וְאֵינָן מְטַמְּאִין בְּמַשָּׂא. לְפִיכָךְ אִם גָּרַר הַגּוֹלֵל בַּחֲבָלִים עַד שֶׁכִּסָּה בּוֹ אֶת הַמֵּת. אוֹ גְּרָרוֹ אוֹ שְׁמָטוֹ מֵעַל הַמֵּת. אוֹ שֶׁגָּרַר הַדּוֹפֵק עַד שֶׁהֶעֱמִיד עָלָיו הַגּוֹלֵל אוֹ שְׁמָטוֹ בַּחֲבָלִים מִתַּחַת הַגּוֹלֵל הֲרֵי זֶה טָהוֹר. וּדְבָרִים שֶׁסּוֹמְכִין אֶת הַדּוֹפֵק וְהֵם הַנִּקְרָאִין דּוֹפֵק דּוֹפְקִין הֲרֵי הֵן טְהוֹרִין:","שָׂדֶה שֶׁנֶּחְרַשׁ בָּהּ קֶבֶר וְאָבְדוּ עַצְמוֹת הַמֵּת בַּעֲפָרָהּ הִיא הַנִּקְרֵאת בֵּית הַפְּרָס. וַעֲפָרָהּ מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא שֶׁמָּא יֵשׁ בָּהּ עֶצֶם כִּשְׂעוֹרָה. וְאֵינָהּ מְטַמְּאָה בְּאֹהֶל. וְכֵן כָּל אַרְצוֹת הָעַכּוּ\"ם עֲפָרָן מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא מִפְּנֵי הָעֲצָמוֹת שֶׁאֵין נִזְהָרִין בָּהֶן. וְטֻמְאַת בֵּית הַפְּרָס וְאֶרֶץ הָעַכּוּ\"ם מִדִּבְרֵי סוֹפְרִים כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Defilement by a Corpse 8":["שָׂדֶה שֶׁאָבַד קֶבֶר בְּתוֹכָהּ עֲפָרָהּ מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא כְּבֵית הַפְּרָס שֶׁמָּא נִדּוֹשׁ הַקֶּבֶר בָּהּ וְיִהְיוּ עֲצָמוֹת כִּשְׂעוֹרָה בְּתוֹךְ עֲפָרָהּ. וְכָל הַשָּׂדֶה כֻּלָּהּ הַמַּאֲהִיל עָלֶיהָ נִטְמָא. וְאִם הֶעֱמִיד בְּתוֹכָהּ אֹהֶל נִטְמָא כָּל מַה שֶּׁיֵּשׁ בָּאֹהֶל שֶׁמָּא הָאֹהֶל שֶׁהֶעֱמִיד בְּאוֹתָהּ שָׂדֶה עַל הַקֶּבֶר הוּא מַאֲהִיל:","בָּנָה בַּיִת וַעֲלִיָּה עַל גַּבָּיו אִם הָיָה פִּתְחָהּ שֶׁל עֲלִיָּה כְּנֶגֶד פִּתְחָהּ שֶׁל בַּיִת הָעֲלִיָּה טְהוֹרָה שֶׁאֲפִילוּ [הָיָה] הַקֶּבֶר תַּחַת מַשְׁקוֹף הַבַּיִת הָעֲלִיָּה טְהוֹרָה שֶׁהֲרֵי הוּא אֹהֶל עַל גַּבֵּי אֹהֶל כְּמוֹ שֶׁיִּתְבָּאֵר. וְאִם לֹא הָיָה מְכֻוָּן אַף הָעֲלִיָּה טְמֵאָה שֶׁמָּא אַסְקֻפַּת עֲלִיָּה עַל הַקֶּבֶר וַהֲרֵי הָעֲלִיָּה מַאֲהִילָה עַל הַקֶּבֶר:","וְשָׂדֶה זוֹ מֻתָּר לִזְרֹעַ בְּתוֹכָהּ כָּל זֶרַע לְפִי שֶׁאֵין שָׁרְשֵׁי זְרָעִים מַגִּיעִים עַד לַקֶּבֶר. אֲבָל אֵין נוֹטְעִין בְּתוֹכָהּ אִילָנֵי מַאֲכָל מִפְּנֵי שֶׁהַשָּׁרָשִׁים מַגִּיעִין עַד לַמֵּת. הַתְּלוּלִיּוֹת הַקְּרוֹבוֹת לָעִיר הַסְּמוּכָה לְבֵית הַקְּבָרוֹת אוֹ לְדֶרֶךְ בֵּית הַקְּבָרוֹת אֶחָד חֲדָשׁוֹת וְאֶחָד יְשָׁנוֹת הֲרֵי אֵלּוּ בְּחֶזְקַת טֻמְאָה מִפְּנֵי שֶׁהַנָּשִׁים קוֹבְרוֹת שָׁם אֶת הַנְּפָלִים וּמֻכֵּי שְׁחִין קוֹבְרִין שָׁם אֵיבְרֵיהֶן. אֲבָל הָרְחוֹקוֹת הַחֲדָשׁוֹת טְהוֹרוֹת וְהַיְשָׁנוֹת טְמֵאוֹת שֶׁמָּא הָיוּ קְרוֹבוֹת מֵעִיר שֶׁחָרְבָה אוֹ מִדֶּרֶךְ שֶׁאָבְדָה. וְאֵי זֶהוּ תֵּל קָרוֹב כָּל שֶׁאֵין שָׁם תֵּל אַחֵר קָרוֹב יוֹתֵר מִמֶּנּוּ. וְיָשָׁן שֶׁאֵין אָדָם זוֹכְרוֹ:","שְׂדֵה בּוֹכִים וְהוּא הַמָּקוֹם הַקָּרוֹב לְבֵית הַקְּבָרוֹת שֶׁהַנָּשִׁים יוֹשְׁבוֹת שָׁם וּבוֹכוֹת. אַף עַל פִּי שֶׁעֲפָרָהּ טָהוֹר שֶׁהֲרֵי לֹא הֻחְזְקָה שָׁם טֻמְאָה אֵין נוֹטְעִין אוֹתוֹ וְאֵין זוֹרְעִין אוֹתוֹ. שֶׁלֹּא לְהַרְגִּיל רֶגֶל אָדָם לְשָׁם שֶׁמָּא יֵשׁ שָׁם טֻמְאָה מִפְּנֵי שֶׁהוּא קָרוֹב לְבֵית הַקְּבָרוֹת כְּבָר נִתְיָאֲשׁוּ בְּעָלָיו מִמֶּנּוּ לְפִיכָךְ אֶפְשָׁר שֶׁיָּבוֹא אָדָם וְיִקְבֹּר בּוֹ מִפְּנֵי זֶה חָשְׁשׁוּ לוֹ. וְעוֹשִׂין מֵעֲפַר מָקוֹם זֶה תַּנּוּרִים לַקֹּדֶשׁ שֶׁהֲרֵי לֹא הֻחְזְקָה שָׁם טֻמְאָה:","קֶבֶר הַנִּמְצָא מֻתָּר לְפַנּוֹתוֹ וְאִם פִּנָּהוּ מְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָיָה עַד שֶׁיִּבָּדֵק כְּמוֹ שֶׁיִּתְבָּאֵר. וְקֶבֶר הַיָּדוּעַ אָסוּר לְפַנּוֹתוֹ וְאִם פִּנָּהוּ מְקוֹמוֹ טָהוֹר וּמֻתָּר בַּהֲנָיָה:","קֶבֶר שֶׁהוּא מַזִּיק אֶת הָרַבִּים מְפַנִּין אוֹתוֹ וּמְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָיָה:","הַפּוֹגֵעַ בְּמֵת מִצְוָה אִם מְצָאוֹ בְּתוֹךְ הַתְּחוּם מְבִיאוֹ לְבֵית הַקְּבָרוֹת. מְצָאוֹ חוּץ לַתְּחוּם אֲפִלּוּ בְּתוֹךְ שְׂדֵה כַּרְכּוֹם קָנָה מְקוֹמוֹ וְיִקָּבֵר בַּמָּקוֹם שֶׁנִּמְצָא. מְצָאוֹ עַל הַמֵּצַר מְסַלְּקוֹ לַצְּדָדִין. שְׂדֵה בּוּר מִצַּד זֶה וּשְׂדֵה נִיר מִצַּד זֶה קוֹבְרוֹ בִּשְׂדֵה בּוּר. שְׂדֵה נִיר וּשְׂדֵה זֶרַע קוֹבְרוֹ בִּשְׂדֵה נִיר. שְׂדֵה זֶרַע וּשְׂדֵה כֶּרֶם קוֹבְרוֹ בִּשְׂדֵה זֶרַע. שְׂדֵה אִילָן וּשְׂדֵה כֶּרֶם קוֹבְרוֹ בִּשְׂדֵה כֶּרֶם מִפְּנֵי אֹהֶל הַטֻּמְאָה. הָיוּ שְׁנֵיהֶן שָׁוִין קוֹבְרוֹ לְאֵי זֶה צַד שֶׁיִּרְצֶה:","קֶבֶר הַנִּמְצָא מְטַמֵּא לְמַפְרֵעַ. וְאִם בָּא אַחֵר וְאָמַר בָּרִי לִי שֶׁלֹּא הָיָה כָּאן קֶבֶר אֲפִלּוּ קֹדֶם לְעֶשְׂרִים שָׁנָה אֵינוֹ מְטַמֵּא אֶלָּא מִשְּׁעַת מְצִיאָה וְאֵילָךְ:","כָּל הַמּוֹצֵא קֶבֶר אוֹ מֵת אוֹ דָּבָר שֶׁמְּטַמֵּא בְּאֹהֶל מִן הַמֵּת. חַיָּב לְצַיֵּן עָלָיו כְּדֵי שֶׁלֹּא יִהְיֶה תַּקָּלָה לַאֲחֵרִים. וּבְחֻלּוֹ שֶׁל מוֹעֵד הָיוּ יוֹצְאִין מִבֵּית דִּין לְצַיֵּן עַל הַקְּבָרוֹת. אֵין מְצַיְּנִין עַל כְּזַיִת מְצֻמְצָם מִן הַמֵּת לְפִי שֶׁסּוֹפוֹ יֶחְסַר בָּאָרֶץ. וּבַמֶּה מְצַיְּנִין, בְּסִיד. מְמַחֶה וְשׁוֹפֵךְ עַל מְקוֹם הַטֻּמְאָה. אֵין מַעֲמִידִין אֶת הַצִּיּוּן עַל גַּבֵּי הַטֻּמְאָה אֶלָּא יְהִי עוֹדֵף מִכָּאן וּמִכָּאן בְּצִדֵּי הַטֻּמְאָה שֶׁלֹּא לְהַפְסִיד אֶת הַטָּהֳרוֹת. וְאֵין מַרְחִיקִין אֶת הַצִּיּוּן מִמְּקוֹם הַטֻּמְאָה שֶׁלֹּא לְהַפְסִיד אֶת אֶרֶץ יִשְׂרָאֵל. וְאֵין מְצַיְּנִין עַל הַוַּדָּאוֹת שֶׁהֲרֵי הֵן יְדוּעִין לַכּל אֶלָּא עַל הַסְּפֵקוֹת. כְּגוֹן שָׂדֶה שֶׁאָבַד בָּהּ קֶבֶר וְהַסְּכָכוֹת וְהַפְּרָעוֹת:","מָצָא שָׂדֶה מְצֻיֶּנֶת וְאֵין יָדוּעַ מַה טִּיבָהּ. אִם אֵין בָּהּ אִילָנוֹת בְּיָדוּעַ שֶׁאָבַד בָּהּ קֶבֶר. יֵשׁ בָּהּ אִילָנוֹת בְּיָדוּעַ שֶׁנֶּחְרַשׁ בָּהּ קֶבֶר כְּמוֹ שֶׁיִּתְבָּאֵר:","מָצָא אֶבֶן מְצֻיֶּנֶת תַּחְתֶּיהָ טָמֵא. הָיוּ שְׁתַּיִם אִם יֵשׁ סִיד בֵּינֵיהֶם בֵּינֵיהֶם טָמֵא. וְאִם אֵין סִיד בֵּינֵיהֶן אֶלָּא עַל רָאשֵׁיהֶן אִם יֵשׁ חֶרֶשׂ בֵּינֵיהֶן טָהוֹר שֶׁאֵין זֶה אֶלָּא בִּנְיָן. וְאִם אֵין חֶרֶשׂ בֵּינֵיהֶן וְהָיָה הַסִּיד מְרֻדָּד עַל רָאשֵׁיהֶן מִכָּאן וּמִכָּאן הֲרֵי זֶה צִיּוּן וְטָמֵא. מָצָא מֵצָר אֶחָד מְצֻיָּן. הוּא טָמֵא וְכָל הַשָּׂדֶה טְהוֹרָה. וְכֵן שְׁנִיָּה וְכֵן שְׁלִישִׁית. מָצָא אַרְבָּעָה מְצָרֶיהָ מְצֻיָּנִין. הֵן טְהוֹרִין וְכָל הַשָּׂדֶה כֻּלָּהּ טְמֵאָה שֶׁאֵין מַרְחִיקִין הַצִּיּוּן מִמְּקוֹם הַטֻּמְאָה:"],"Mishneh Torah, Defilement of Foods 4":["כַּמָּה שִׁעוּר אֳכָלִין לְטֻמְאָה. לְטֻמְאַת עַצְמָן כָּל שֶׁהֵן אֲפִלּוּ שֻׁמְשֹׁם אוֹ חַרְדָּל מִתְטַמֵּא שֶׁנֶּאֱמַר (ויקרא יא לד) \"מִכָּל הָאֹכֶל אֲשֶׁר יֵאָכֵל\", כָּל שֶׁהוּא. וְאֵין אֹכֶל טָמֵא מְטַמֵּא אֹכֶל אַחֵר אוֹ מַשְׁקִין אוֹ יָדַיִם עַד שֶׁיִּהְיֶה בּוֹ כְּבֵיצָה בְּלֹא קְלִפָּתָהּ. וְכֵן הָאוֹכֵל אֳכָלִין טְמֵאִים אֵינוֹ נִפְסָל עַד שֶׁיֹּאכַל כְּבֵיצָה וּמֶחֱצָה וְזֶהוּ חֲצִי פְּרָס:","הַמַּשְׁקִין מִתְטַמְּאִין כָּל שֶׁהֵן וּמְטַמְּאִין בְּכָל שֶׁהֵן. אֲפִלּוּ טִפַּת מַשְׁקִין טְמֵאִים כְּחַרְדָּל שֶׁנָּגְעָה בָּאֳכָלִין אוֹ בְּכֵלִים אוֹ בְּמַשְׁקִין אֲחֵרִים נִטְמְאוּ. וְאַף עַל פִּי כֵן אֵין הַשּׁוֹתֶה מַשְׁקִין טְמֵאִין נִפְסָל עַד שֶׁיִּשְׁתֶּה רְבִיעִית כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל הַמַּשְׁקִין מִצְטָרְפִין לִפְסל אֶת הַגְּוִיָּה לִרְבִיעִית. וְכָל הָאֳכָלִין מִצְטָרְפִין לִכְבֵיצָה לְטַמֵּא טֻמְאַת אֳכָלִים. וּלְכַחֲצִי פְּרָס לִפְסל אֶת הַגְּוִיָּה. אֲפִלּוּ חִטָּה עִם קֶמַח עִם בָּצֵק עִם תְּאֵנָה וּבָשָׂר וְכַיּוֹצֵא בְּאֵלּוּ הַכּל מִצְטָרֵף:","הָעוֹר הַמְחֻבָּר בַּבָּשָׂר וְהַמָּרָק וְהַתַּבְלִין וְהָאָלָל אַף עַל פִּי שֶׁמִּקְצָתוֹ חָשַׁב עָלָיו וּמִקְצָתוֹ לֹא חָשַׁב עָלָיו. מִקְצָתוֹ פְּלָטַתּוּ חַיָּה וּמִקְצָתוֹ פְּלָטַתּוּ סַכִּין. וְהָעֲצָמוֹת הַמְחֻבָּרוֹת בַּבָּשָׂר. וְהַגִּידִים וְהַמְּקוֹמוֹת הָרַכִּים מִן הַקַּרְנַיִם וּמִן הַטְּלָפַיִם וְהַכְּנָפַיִם וְהַנּוֹצָה. וְהַמְּקוֹמוֹת הָרַכִּים מִן הַצִּפָּרְנַיִם וּמִן הַחַרְטֹם הַמֻּבְלָעִין בַּבָּשָׂר. כָּל אֶחָד מֵאֵלּוּ מִתְטַמְּאִין וּמְטַמְּאִין וּמִצְטָרְפִין לִכְבֵיצָה אוֹ לְכַחֲצִי פְּרָס:","כְּבֵיצָה אֳכָלִין טְמֵאִים שֶׁהִנִּיחָן בַּחַמָּה וְנִתְמַעֲטוּ אֵינָן מְטַמְּאִים. וְכֵן כְּזַיִת מִן הַמֵּת אוֹ מִן הַנְּבֵלָה וְכַעֲדָשָׁה מִן הַשֶּׁרֶץ שֶׁהִנִּיחָן בַּחַמָּה וְנִתְמַעֲטוּ טְהוֹרִין:","כְּזַיִת חֵלֶב וְדָם וְנוֹתָר וּפִגּוּל שֶׁהִנִּיחָן בַּחַמָּה וְנִתְמַעֲטוּ אֵין חַיָּבִין עֲלֵיהֶן כָּרֵת. הִנִּיחָן בַּגְּשָׁמִים וְנִתְפְּחוּ חָזְרוּ לִכְמוֹת שֶׁהָיוּ. בֵּין לְטֻמְאָה חֲמוּרָה בֵּין לְטֻמְאָה קַלָּה בֵּין לְאִסּוּר:","עֲלֵי בְּצָלִים וּבְנֵי בְּצָלִים שֶׁהֵן חֲלוּלִין אִם יֵשׁ בָּהֶם רִיר מִשְׁתַּעֲרִין כְּמוֹת שֶׁהֵן. וְאִם הָיוּ חֲלוּלִין וְרֵיקָנִים מְמַעֵךְ אֶת חֲלָלָן:","פַּת סֻפְגָּנִין מִשְׁתַּעֶרֶת כְּמוֹת שֶׁהִיא וְאִם יֵשׁ בָּהּ חָלָל מְמַעֵךְ אֶת חֲלָלָהּ:","בְּשַׂר הָעֵגֶל שֶׁנִּתְפַּח וּבְשַׂר זְקֵנָה שֶׁנִּתְמַעֲטָה מִשְׁתַּעֲרִין כְּמוֹת שֶׁהֵן:","הָאֱגוֹז וְהַתְּמָרִים וְהַשָּׁקֵד הַמִּתְקַרְקְשִׁים מִשְׁתַּעֲרִין כְּמוֹת שֶׁהֵן:","כָּל שֶׁטֻּמְאָתוֹ וְשִׁעוּרוֹ שָׁוִין מִצְטָרְפִין זֶה עִם זֶה. הָיוּ טֻמְאָתָן שָׁוִין אֲבָל לֹא שִׁעוּרָן. שִׁעוּרָן אֲבָל לֹא טֻמְאָתָן אֵין מִצְטָרְפִין וַאֲפִלּוּ לְטַמֵּא כַּקַּל שֶׁבִּשְׁנֵיהֶן. כֵּיצַד טֻמְאָתוֹ וְלֹא שִׁעוּרוֹ. כְּגוֹן בְּשַׂר הַמֵּת וְרֶקֶב שֶׁלּוֹ. שִׁעוּרוֹ וְלֹא טֻמְאָתוֹ כְּגוֹן בְּשַׂר הַמֵּת וּבְשַׂר הַנְּבֵלָה. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם לֹא הָיוּ שָׁוִים לֹא בְּשִׁעוּר וְלֹא בְּטֻמְאָה כְּגוֹן בְּשַׂר נְבֵלָה וּבְשַׂר הַשֶּׁרֶץ שֶׁאֵין מִצְטָרְפִין:","אֳכָלִין טְמֵאִים שִׁעוּרָם שָׁוֶה שֶׁכָּל אֹכֶל טָמֵא אֵינוֹ מְטַמֵּא אֶלָּא כְּבֵיצָה. וְטֻמְאָתָם שָׁוָה שֶׁכָּל אֹכֶל טָמֵא אֵינוֹ מְטַמֵּא אֶלָּא בְּמַגָּע וְאֵינוֹ מְטַמֵּא לֹא אָדָם וְלֹא כֵּלִים. לְפִיכָךְ מִצְטָרְפִין לְטַמֵּא כַּקַּל שֶׁבִּשְׁנֵיהֶן. כֵּיצַד. כַּחֲצִי בֵּיצָה אֹכֶל רִאשׁוֹן וְכַחֲצִי בֵּיצָה אֹכֶל שֵׁנִי שֶׁבְּלָלָן זֶה בָּזֶה הֲרֵי זֶה שֵׁנִי וְאִם נָגַע בִּתְרוּמָה פְּסָלָהּ. כַּחֲצִי בֵּיצָה אֹכֶל שֵׁנִי וְכַחֲצִי בֵּיצָה אֹכֶל שְׁלִישִׁי שֶׁבְּלָלָן הֲרֵי זֶה שְׁלִישִׁי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה אֲפִלּוּ חֲצִי בֵּיצָה אֹכֶל רִאשׁוֹן וַחֲצִי בֵּיצָה אֹכֶל רְבִיעִי שֶׁל קֹדֶשׁ שֶׁבְּלָלָן זֶה בָּזֶה הֲרֵי הַכּל רְבִיעִי:","כְּבֵיצָה אֹכֶל רִאשׁוֹן וּכְבֵיצָה אֹכֶל שֵׁנִי שֶׁבְּלָלָן זֶה בָּזֶה הַכּל רִאשׁוֹן. חִלְּקָן כָּל אֶחָד מֵהֶן שֵׁנִי. נָפַל זֶה לְעַצְמוֹ וְזֶה לְעַצְמוֹ עַל כִּכָּר שֶׁל תְּרוּמָה פְּסָלוּהוּ. נָפְלוּ שְׁנֵיהֶן כְּאֶחָד עֲשָׂאוּהוּ שֵׁנִי:","כְּבֵיצָה אֹכֶל שֵׁנִי וּכְבֵיצָה אֹכֶל שְׁלִישִׁי שֶׁבְּלָלָן זֶה בָּזֶה הֲרֵי הַכּל שֵׁנִי. חִלְּקָן כָּל אֶחָד מֵהֶן שְׁלִישִׁי. נָפַל זֶה לְעַצְמוֹ [וְזֶה לְעַצְמוֹ] עַל כִּכָּר שֶׁל תְּרוּמָה לֹא פְּסָלוּהוּ. נָפְלוּ שְׁנֵיהֶן כְּאֶחָד פְּסָלוּהוּ מִפְּנֵי שֶׁעֲשָׂאוּהוּ שְׁלִישִׁי:","כְּבֵיצָה אֹכֶל רִאשׁוֹן וּכְבֵיצָה אֹכֶל שְׁלִישִׁי שֶׁבְּלָלָן זֶה בָּזֶה רִאשׁוֹן. חִלְּקָן זֶה שֵׁנִי וְזֶה שֵׁנִי. שֶׁהַשְּׁלִישִׁי שֶׁנָּגַע בָּרִאשׁוֹן נַעֲשָׂה שֵׁנִי:","כִּשְׁתֵּי בֵּיצִים אֹכֶל רִאשׁוֹן וְכִשְׁתֵּי בֵּיצִים אֹכֶל שֵׁנִי שֶׁבְּלָלָן הַכּל רִאשׁוֹן. חִלְּקָן לִשְׁנַיִם כָּל אֶחָד מֵהֶן רִאשׁוֹן. חִלְּקָן לִשְׁלֹשָׁה חֲלָקִים אוֹ לְאַרְבָּעָה כָּל אֶחָד מֵהֶן שֵׁנִי. וְכֵן כִּשְׁתֵּי בֵּיצִים אֹכֶל שֵׁנִי וְכִשְׁתֵּי בֵּיצִים אֹכֶל שְׁלִישִׁי שֶׁבְּלָלָן הַכּל שֵׁנִי. חִלְּקָן לִשְׁנַיִם כָּל אֶחָד מֵהֶן שֵׁנִי. לִשְׁלֹשָׁה וּלְאַרְבָּעָה הֲרֵי כָּל אֶחָד מֵהֶן שְׁלִישִׁי:"],"Mishneh Torah, Diverse Species 6":["הַזּוֹרֵעַ יָרָק אוֹ תְּבוּאָה בַּכֶּרֶם אוֹ הַמְקַיְּמוֹ עַד שֶׁהוֹסִיף בְּמָאתַיִם הֲרֵי זֶה מְקַדֵּשׁ מִן הַגְּפָנִים שֶׁסְּבִיבוֹתָיו שֵׁשׁ עֶשְׂרֵה אַמָּה לְכָל רוּחַ. עֲגֻלּוֹת וְלֹא מְרֻבָּעוֹת. וְרוֹאִין כָּל הָעִגּוּל שֶׁרָחְבּוֹ שְׁתַּיִם וּשְׁלֹשִׁים אַמָּה כְּאִלּוּ הוּא כֻּלּוֹ מָלֵא יָרָק. וְכָל גֶּפֶן שֶׁתִּהְיֶה בְּתוֹךְ עִגּוּל זֶה נִתְקַדְּשָׁה עִם הַיָּרָק וְכָל שֶׁחוּץ לָעִגּוּל אֵינָן מִתְקַדְּשׁוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה בֵּין שִׂפְתֵי הָעִגּוּל הַזֶּה וּבֵין שׁוּרוֹת הַגְּפָנִים שֶׁחוּצָה לוֹ יוֹתֵר עַל אַרְבַּע אַמּוֹת. אֲבָל אִם הָיָה בֵּינֵיהֶם אַרְבַּע אַמּוֹת מְצֻמְצָמוֹת אוֹ פָּחוֹת רוֹאִין אֶת הָעִגּוּל כְּאִלּוּ הִגִּיעַ לַשּׁוּרָה הַסְּמוּכָה לוֹ וּכְאִלּוּ רֹחַב הָעִגּוּל אַרְבָּעִים אַמָּה וְרוֹאִין כָּל גֶּפֶן שֶׁתִּפּל בְּתוֹךְ עִגּוּל זֶה שֶׁל אַרְבָּעִים אַמָּה הֲרֵי הִיא מִתְקַדֶּשֶׁת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּזוֹרֵעַ אוֹ מְקַיֵּם תּוֹךְ הַכֶּרֶם. אֲבָל הַזּוֹרֵעַ חוּץ לַכֶּרֶם וְסָמוּךְ לוֹ הֲרֵי זֶה מְקַדֵּשׁ שְׁתֵּי שׁוּרוֹת שֶׁל גְּפָנִים הַסְּמוּכוֹת לַזֶּרַע בְּאֹרֶךְ כָּל הַזֶּרַע וְיֶתֶר אַרְבַּע אַמּוֹת חוּץ לַזֶּרַע וּמִתְקַדֵּשׁ מִן הַזֶּרַע רֹחַב אַרְבַּע אַמּוֹת בְּאֹרֶךְ כָּל הַשּׁוּרָה שֶׁל כֶּרֶם. וְאִם זָרַע בְּצַד גֶּפֶן יְחִידִית אֵינוֹ מְקַדֵּשׁ מִן הַזֶּרַע אֶלָּא שִׁשָּׁה טְפָחִים לְכָל רוּחַ:","יַלְדָּה פָּחוֹת מִטֶּפַח אֵינָהּ מְקַדֶּשֶׁת אֶת הַזְּרָעִים. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת יוֹצְאָה זָנָב. אֲבָל אִם הָיָה כָּל הַכֶּרֶם כֵּן הֲרֵי זֶה מְקַדֵּשׁ:","שְׁתֵּי גִּנּוֹת זוֹ עַל גַּב זוֹ הַתַּחְתּוֹנָה עֲשׂוּיָה כֶּרֶם זוֹרֵעַ אֶת הָעֶלְיוֹנָה עַד שֶׁהוּא מַגִּיעַ לַאֲוִיר עֲשָׂרָה טְפָחִים קָרוֹב לַכֶּרֶם. שֶׁאֲוִיר עֲשָׂרָה טְפָחִים סָמוּךְ לַכֶּרֶם אוֹ לְגֶפֶן יְחִידִית אָסוּר לִזְרֹעַ בּוֹ זְרָעִים. וְאִם הָיְתָה הָעֶלְיוֹנָה עֲשׂוּיָה כֶּרֶם הֲרֵי זֶה זוֹרֵעַ אֶת הַתַּחְתּוֹנָה עַד שֶׁהוּא מַגִּיעַ לְמַטָּה מִשְּׁלֹשָׁה טְפָחִים מֵעִקַּר הַגְּפָנִים:","מִי שֶׁהָיְתָה שָׂדֵהוּ זְרוּעָה יָרָק אוֹ תְּבוּאָה וְנִמְלַךְ לִטַּע בָּהּ גְּפָנִים הוֹפֵךְ אֶת הַזְּרָעִים בְּמַחְרֵשָׁה וְאַחַר כָּךְ נוֹטֵעַ וְלֹא יִטַּע וְאַחַר כָּךְ יַהֲפֹךְ. הָיְתָה נְטוּעָה גְּפָנִים וְנִמְלַךְ לִזְרֹעַ בָּהּ זְרָעִים מְשָׁרֵשׁ אֶת הַגְּפָנִים וְאַחַר כָּךְ זוֹרֵעַ אֶת הַזְּרָעִים. וְאִם רָצָה לָקֹץ אֶת הַגְּפָנִים עַד שֶׁלֹּא יִשָּׁאֵר מֵהֶן אֶלָּא פָּחוֹת מִטֶּפַח סָמוּךְ לָאָרֶץ הֲרֵי זֶה מֻתָּר לִזְרֹעַ וְאַחַר כָּךְ יַחֲזֹר וִישָׁרֵשׁ אֶת הַנִּשְׁאָר בָּאָרֶץ מִן הַגְּפָנִים:","הַמַּבְרִיךְ אֶת הַגֶּפֶן בָּאָרֶץ אֲפִלּוּ הִבְרִיכָהּ בְּתוֹךְ הַדְּלַעַת שֶׁיָּבְשָׁה וְנַעֲשֵׂית כְּסִילוֹן אוֹ בְּתוֹךְ סִילוֹן שֶׁל חֶרֶשׂ אִם הָיָה הֶעָפָר עַל גַּבָּהּ שְׁלֹשָׁה טְפָחִים אוֹ יוֹתֵר הֲרֵי זֶה מֻתָּר לִזְרֹעַ עַל גַּבָּהּ. וְאִם הָיָה עַל גַּבָּהּ פָּחוֹת מִזֶּה אָסוּר לִזְרֹעַ עַל גַּבָּהּ וּמֻתָּר לִזְרֹעַ בְּצִדָּהּ:","הִבְרִיכָהּ בַּסֶּלַע אַף עַל פִּי שֶׁאֵין עָפָר עַל גַּבָּהּ אֶלָּא שָׁלֹשׁ אֶצְבָּעוֹת מֻתָּר לְהָבִיא זֶרַע עָלֶיהָ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵין עִקַּר הַגֶּפֶן נִרְאֶה. אֲבָל אִם נִרְאֶה צָרִיךְ לְהַרְחִיק שִׁשָּׁה טְפָחִים לְכָל רוּחַ וְאַחַר כָּךְ יִזְרַע כְּמוֹ שֶׁמַּרְחִיק מִכָּל גֶּפֶן יְחִידִית שֶׁלֹּא הֻבְרְכָה כְּמוֹ שֶׁיִּתְבָּאֵר:","הַמַּבְרִיךְ שָׁלֹשׁ גְּפָנִים וְעִקְּרֵיהֶם נִרְאִין. אִם יֵשׁ בֵּינֵיהֶן מֵאַרְבַּע אַמּוֹת עַד שְׁמוֹנֶה הֲרֵי אֵלּוּ מִצְטָרְפִין לִשְׁאָר גְּפָנִים הָעוֹמְדוֹת וּכְאִלּוּ לֹא הִבְרִיכָן. וְאִם לָאו אֵינָם מִצְטָרְפוֹת:","הָיוּ פָּחוֹת מִשָּׁלֹשׁ אֵין מִצְטָרְפִין אֶלָּא מַרְחִיק מֵהֶן שִׁשָּׁה טְפָחִים לְכָל רוּחַ וְזוֹרֵעַ:","כָּל הַזּוֹרֵעַ תַּחַת הַשָּׂרִיגִים וְהֶעָלִין הַיּוֹצְאִין מִן הַגֶּפֶן הֲרֵי זֶה קִדֵּשׁ וְאַף עַל פִּי שֶׁהַזֶּרַע רָחוֹק מֵעִקַּר הַגֶּפֶן כַּמָּה אַמּוֹת:","הִדְלָה אֶת הַגֶּפֶן עַל מִקְצָת אַפִּיפְיָרוֹת לֹא יִזְרַע תַּחַת מוֹתַר הָאַפִּיפְיָרוֹת. וְאַף עַל פִּי שֶׁאֵין עֲלֵיהֶן לֹא עָלִין וְלֹא שָׂרִיגִים. וְאִם זָרַע הוֹאִיל וְאֵין הַזֶּרַע תַּחַת סְכַךְ הַגֶּפֶן הֲרֵי זֶה מֻתָּר. וְכֵן אִם הִדְלָה הַגֶּפֶן עַל מִקְצָת בַּדֵּי אִילָן שֶׁאֵינוֹ עוֹשֶׂה פֵּרוֹת כְּגוֹן הָאֶרֶז וְהַבְּרוֹשׁ. אֲבָל אִם הִדְלָה עַל מִקְצָת אִילַן מַאֲכָל הֲרֵי זֶה מֻתָּר לִזְרֹעַ תַּחַת בַּדֵּי הָאִילָן שֶׁלֹּא נִמְשְׁכוּ עֲלֵיהֶן שָׂרִיגֵי הַגֶּפֶן שֶׁאֵין אָדָם מְבַטֵּל אִילַן מַאֲכָל וְעוֹשֶׂה אַפִּיפְיָרוֹת לְגֶפֶן. וְאִם נִמְשְׁכוּ הַשָּׂרִיגִים אַחַר שֶׁזָּרַע וְסִכְּכוֹ עַל הַזֶּרַע הֲרֵי זֶה מַחֲזִירָם לְמָקוֹם אַחֵר:","הַזּוֹרֵעַ תַּחַת מוֹתַר הָאַפִּיפְיָרוֹת אוֹ תַּחַת מוֹתַר אִילָן שֶׁאֵינוֹ עוֹשֶׂה פֵּרוֹת וְנִמְשְׁכוּ שָׂרִיגֵי הַגֶּפֶן וְסִכְּכוּ עַל הַזְּרָעִים הֲרֵי זֶה אָסוּר לְקַיְּמוֹ אוֹ לְהַחֲזִיר הַשָּׂרִיגִים אֶלָּא כֵּיצַד עוֹשֶׂה. עוֹקֵר הַזֶּרַע:","קָנִים הַיּוֹצְאִין מִן הֶעָרִיס וְחָס עֲלֵיהֶן לְפָסְקָן כְּדֵי שֶׁלֹּא יַשְׁחִית הָאַפִּיפְיָרוֹת הֲרֵי זֶה מֻתָּר לִזְרֹעַ תַּחְתֵּיהֶן. וְאִם הִנִּיחָם כְּדֵי שֶׁיְּהַלְּכוּ עֲלֵיהֶן הַשָּׂרִיגִים וְהֶעָלִין הַיּוֹצְאִין הֲרֵי זֶה אָסוּר לִזְרֹעַ תַּחְתֵּיהֶן:","פֶּרַח הַיּוֹצֵא מִן הֶעָרִיס אוֹ מִן הַדָּלִית רוֹאִין אוֹתוֹ כְּאִלּוּ מִשְׁקלֶת תְּלוּיָה בּוֹ עַד הָאָרֶץ וְאָסוּר לִזְרֹעַ תַּחְתָּיו. וְכֵן הַמּוֹתֵחַ זְמוֹרָה מֵאִילָן לְאִילָן אָסוּר לִזְרֹעַ תַּחְתֶּיהָ:","קָשַׁר חֶבֶל אוֹ גֶּמִי בִּזְמוֹרָה וְקָשַׁר הָרֹאשׁ אֶחָד בְּאִילָן הֲרֵי זֶה מֻתָּר לִזְרֹעַ תַּחַת הַחֶבֶל. וְאִם מָתַח חֲבָל זֶה כְּדֵי שֶׁיְּהַלְּכוּ עָלָיו הַשָּׂרִיגִים וְהֶעָלִים הֲרֵי הוּא כָּאַפִּיפְיָרוֹת וְאָסוּר לִזְרֹעַ תַּחְתָּיו:"],"Mishneh Torah, Divorce 5":["זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (דברים כד א) ״‎וְנָתַן בְּיָדָהּ״‎ אֵין עִנְיַן הַכָּתוּב אֶלָּא שֶׁיַּגִּיעַ הַגֵּט לָהּ. וְאֶחָד יָדָהּ אוֹ חֵיקָהּ אוֹ חֲצֵרָהּ אוֹ שְׁלוּחָהּ שֶׁעָשְׂתָה יָדוֹ כְּיָדָהּ הַכּל אֶחָד הוּא. וְאֶחָד חֲצֵרָהּ הַקְּנוּיָה לָהּ אוֹ חֲצֵרָהּ הַמֻּשְׂכֶּרֶת לָהּ אוֹ שְׁאוּלָה לָהּ הַכּל רְשׁוּתָהּ הוּא. וּמִשֶּׁיַגִּיעַ גֵּט לִרְשׁוּתָהּ נִתְגָּרְשָׁה:","הַזּוֹרֵק גֵּט לְאִשְׁתּוֹ לְתוֹךְ חֲצֵרָהּ. אִם הָיְתָה עוֹמֶדֶת שָׁם בְּצַד חֲצֵרָהּ נִתְגָּרְשָׁה. וְאִם לָאו לֹא נִתְגָּרְשָׁה עַד שֶׁתַּעֲמֹד בְּצַד חֲצֵרָהּ וְאַף עַל פִּי שֶׁהִיא חָצֵר שֶׁיִּשְׁתַּמֵּר הַגֵּט בְּתוֹכָהּ. שֶׁחוֹב הִיא לָהּ הַגֵּרוּשִׁין וְאֵין חָבִין לָאָדָם אֶלָּא בְּפָנָיו:","הָיְתָה עוֹמֶדֶת בְּרֹאשׁ הַגַּג שֶׁלָּהּ וְהוּא מִלְּמַטָּה בַּחֲצֵרוֹ וּזְרָקוֹ לָהּ לְמַעְלָה כֵּיוָן שֶׁהִגִּיעַ לַאֲוִיר מְחִצּוֹת הַמַּעֲקֶה אוֹ לְפָחוֹת מִשְּׁלֹשָׁה טְפָחִים סָמוּךְ לַגַּג נִתְגָּרְשָׁה וּבִלְבַד שֶׁיָּנוּחַ. אֲבָל אִם נִמְחַק אוֹ נִשְׂרַף קֹדֶם שֶׁיַּגִּיעַ לָהּ אַף עַל פִּי שֶׁנִּמְחַק לְאַחַר שֶׁהִגִּיעַ לַאֲוִיר מְחִצּוֹת אוֹ אַחַר שֶׁהִגִּיעַ לְפָחוֹת מִשְּׁלֹשָׁה טְפָחִים סָמוּךְ לַגַּג כְּגוֹן שֶׁנָּשְׁבָה הָרוּחַ וְהֶעֱלַתְהוּ וְנִמְחַק אוֹ נִשְׂרַף הוֹאִיל וְאֵינוֹ הוֹלֵךְ לָנוּחַ אֵינוֹ גֵּט וְלֹא נִתְגָּרְשָׁה:","הָיָה הַגַּג שֶׁלּוֹ וְהוּא מִלְּמַעְלָה בּוֹ וְהִיא מִלְּמַטָּה בֶּחָצֵר שֶׁלָּהּ וְזָרַק לָהּ גִּטָּהּ. כֵּיוָן שֶׁיָּצָא הַגֵּט מִמְּחִצּוֹת הַגַּג וְהִגִּיעַ לִמְחִצּוֹת מְקוֹמָהּ שֶׁהִיא עוֹמֶדֶת בּוֹ נִתְגָּרְשָׁה:","זְרָקוֹ לִרְשׁוּתָהּ לְתוֹךְ הָאֵשׁ וְנִשְׂרַף אוֹ לְתוֹךְ הַמַּיִם [וְנִמְחַק אוֹ] נֶאֱבַד אֵינוֹ גֵּט. אֲבָל אִם הִגִּיעַ לִרְשׁוּתָהּ [וְנָח] וְאַחַר כָּךְ בָּא הָאֵשׁ וּשְׂרָפַתְהוּ הֲרֵי זֶה גֵּט:","זְרָקוֹ עַל גַּבֵּי קָנֶה אוֹ רֹמַח הַנְּעוּצִים בִּרְשׁוּתָהּ אֵינוֹ גֵּט עַד שֶׁיָּנוּחַ בְּמָקוֹם הַמִּשְׁתַּמֵּר בּוֹ. שְׁתֵּי חֲצֵרוֹת זוֹ לְפָנִים מִזּוֹ הַפְּנִימִית שֶׁלָּהּ וְהַחִיצוֹנָה שֶׁלּוֹ וְכָתְלֵי הַחִיצוֹנָה גְּבוֹהוֹת עַל הַפְּנִימִית כֵּיוָן שֶׁזָּרַק הַגֵּט לְתוֹךְ אֲוִיר הַחִיצוֹנָה נִתְגָּרְשָׁה. שֶׁהַפְּנִימִית בְּכָתְלֵי הַחִיצוֹנָה מִשְׁתַּמֶּרֶת מַה שֶּׁאֵין כֵּן בְּקֻפּוֹת:","כֵּיצַד. שְׁתֵּי קֻפּוֹת זוֹ לְפָנִים מִזּוֹ הַפְּנִימִית שֶׁלָּהּ וְהַחִיצוֹנָה שֶׁלּוֹ וְזָרַק לָהּ גִּטָּהּ בְּתוֹכָן אֲפִלּוּ הִגִּיעַ לַאֲוִיר הַפְּנִימִית אֵינָהּ מְגֹרֶשֶׁת עַד שֶׁיָּנוּחַ עַל צַד הַקֻּפָּה הַפְּנִימִית. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיְתָה מֻטָּה עַל צִדָּהּ וְאֵין לָהּ שׁוּלַיִם אֲבָל יֵשׁ לָהּ שׁוּלַיִם אֲפִלּוּ נָח בְּקַרְקָעִיתָהּ אֵינָהּ מְגֹרֶשֶׁת שֶׁכְּלִי הָאִשָּׁה בִּרְשׁוּת הַבַּעַל אֵינוֹ קוֹנֶה לָהּ הַגֵּט אֶלָּא אִם כֵּן אֵינוֹ מַקְפִּיד עַל מְקוֹמוֹ:","זָרַק לָהּ גִּטָּהּ וְהִיא בְּתוֹךְ בֵּיתוֹ אוֹ בְּתוֹךְ חֲצֵרוֹ אֵינָהּ מְגֹרֶשֶׁת עַד שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ אוֹ לִכְלִי מִן הַכֵּלִים שֶׁלָּהּ שֶׁאֵין הַבַּעַל מַקְפִּיד עַל מְקוֹמוֹ כְּגוֹן צְלוֹחִית אוֹ קְפִיפָה קְטַנָּה אוֹ כַּיּוֹצֵא בָּהֶן. וְכֵן אִם הִגִּיעַ לַמִּטָּה שֶׁלָּהּ שֶׁהִיא יוֹשֶׁבֶת עָלֶיהָ וְהָיְתָה גְּבוֹהָה עֲשָׂרָה טְפָחִים הֲרֵי זוֹ מְגֹרֶשֶׁת שֶׁהֲרֵי חָלְקָה רְשׁוּת לְעַצְמָהּ וְאֵין הַבַּעַל מַקְפִּיד עַל מְקוֹם כִּרְעֵי הַמִּטָּה:","הִשְׁאִיל לָהּ הַבַּעַל מָקוֹם בַּחֲצֵרוֹ וְלֹא יִחֲדוֹ [לָהּ] וְזָרַק לָהּ גֵּט וְהִגִּיעַ לְאַרְבַּע אַמּוֹת שֶׁלָּהּ שֶׁהִיא עוֹמֶדֶת בָּהֶן הֲרֵי זוֹ מְגֹרֶשֶׁת. נִתְגַּלְגֵּל וְנָפַל עַל גַּבֵּי קוֹרָה אוֹ עַל גַּבֵּי סֶלַע רָחוֹק מִמֶּנָּה. אִם הַמָּקוֹם שֶׁנָּפַל עָלָיו אֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת וְאֵינוֹ גָּבוֹהַּ עֲשָׂרָה וְאֵין לוֹ שָׁם לְוַוי הֲרֵי זֶה לֹא חָלַק רְשׁוּת לְעַצְמוֹ וּכְאִלּוּ הוּא וְהִיא בְּמָקוֹם אֶחָד. וְאִם יֵשׁ שָׁם אֶחָד מִשְּׁלֹשָׁה דְּבָרִים אֵלּוּ חָלַק רְשׁוּת לְעַצְמוֹ וּמָקוֹם אֶחָד הִשְׁאִיל לָהּ שְׁנֵי מְקוֹמוֹת לֹא הִשְׁאִיל לָהּ וְאֵינָהּ מְגֹרֶשֶׁת עַד שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ:","זָרַק לָהּ גִּטָּהּ לִרְשׁוּתָהּ וְעָבַר בְּתוֹךְ רְשׁוּתָהּ שֶׁהִיא עוֹמֶדֶת בָּהּ וְנָפַל חוּץ לִרְשׁוּתָהּ אַף עַל פִּי שֶׁעָבַר בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לָאָרֶץ אֵינָהּ מְגֹרֶשֶׁת עַד שֶׁיָּנוּחַ בִּרְשׁוּתָהּ:","הָיְתָה עוֹמֶדֶת עַל גַּגָּהּ (זוֹ) וּזְרָקוֹ לָהּ וְנָפַל בְּגַג אַחֵר סָמוּךְ לוֹ. אִם יְכוֹלָה לִפְשֹׁט יָדָהּ וְלִטְּלוֹ הֲרֵי זוֹ מְגֹרֶשֶׁת שֶׁאַף עַל פִּי שֶׁדִּיּוּרִין חֲלוּקִין לְמַעְלָה כְּשֵׁם שֶׁהֵן חֲלוּקִין לְמַטָּה אֵין בְּנֵי אָדָם מַקְפִּידִין עַל מָקוֹם כַּיּוֹצֵא בָּזֶה:","הָיְתָה יָדָהּ קַטַפְרֵס וְזָרַק הַגֵּט עַל יָדָהּ וְנָפַל לָאָרֶץ. אִם נָפַל לְתוֹךְ אַרְבַּע אַמּוֹת שֶׁלָּהּ וְנָח הֲרֵי זוֹ מְגֹרֶשֶׁת. נָפַל לְתוֹךְ הַיָּם אוֹ לְתוֹךְ הָאֵשׁ אֵינָהּ מְגֹרֶשֶׁת. וְהוּא שֶׁהָיְתָה עוֹמֶדֶת עַל גַּבֵּי הַמַּיִם אוֹ סָמוּךְ לָאֵשׁ שֶׁמִּתְּחִלַּת נְפִילָתוֹ לְאִבּוּד הָיָה עוֹמֵד:","זְרָקוֹ לָהּ בִּרְשׁוּת הָרַבִּים אוֹ בִּרְשׁוּת שֶׁאֵינָהּ שֶׁל שְׁנֵיהֶם קָרוֹב לוֹ אֵינָהּ מְגֹרֶשֶׁת. הָיָה הַגֵּט מֶחֱצָה לְמֶחֱצָה וּמִמֶּחֱצָה לְמֶחֱצָה עַד שֶׁיִּהְיֶה קָרוֹב לָהּ הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת. הָיָה קָרוֹב לָהּ כְּדֵי שֶׁתָּשׁוּחַ וְתִטְּלֶנּוּ הֲרֵי זֶה פָּסוּל עַד שֶׁיַּגִּיעַ גֵּט לְיָדָהּ וְאַחַר כָּךְ תִּנָּשֵׂא בּוֹ לְכַתְּחִלָּה:","כֵּיצַד הוּא קָרוֹב לוֹ. הָיָה הוּא יָכוֹל לְשָׁמְרוֹ וְהִיא אֵינָהּ יְכוֹלָה לְשָׁמְרוֹ זֶה הוּא קָרוֹב לוֹ שְׁנֵיהֶם יְכוֹלִים לְשָׁמְרוֹ אוֹ שֶׁשְּׁנֵיהֶם אֵין יְכוֹלִין לְשָׁמְרוֹ זֶה הוּא מֶחֱצָה לְמֶחֱצָה:","בָּא הוּא תְּחִלָּה וְעָמַד וְאַחַר כָּךְ עָמְדָה הִיא כְּנֶגְדּוֹ וּזְרָקוֹ לָהּ. אִם הָיָה הַגֵּט בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁלּוֹ אֵינָהּ מְגֹרֶשֶׁת אַף עַל פִּי שֶׁאִם תָּשׁוּחַ תִּטְּלֶנּוּ. עָמְדָה הִיא תְּחִלָּה וּבָא הוּא וְעָמַד כְּנֶגְדָּהּ וּזְרָקוֹ לָהּ אַף עַל פִּי שֶׁהוּא מֶחֱצָה לְמֶחֱצָה הוֹאִיל וְהוּא לְתוֹךְ אַרְבַּע אַמּוֹת שֶׁלָּהּ הֲרֵי זֶה גֵּט פָּסוּל עַד שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ:","זָרַק הַגֵּט לְיָדָהּ וְהָיָה קָשׁוּר בִּמְשִׁיחָה וּקְצָת הַמְּשִׁיחָה בְּיָדוֹ. אִם יָכוֹל לְנַתְּקוֹ וְלַהֲבִיאוֹ אֶצְלוֹ אֵינָהּ מְגֹרֶשֶׁת עַד שֶׁתִּפְסֹק הַמְּשִׁיחָה. וְאִם אֵינוֹ יָכוֹל לְנַתְּקוֹ הֲרֵי זוֹ מְגֹרֶשֶׁת:","נָתַן הַגֵּט בְּיַד עַבְדָּהּ וְהוּא נֵעוֹר וְהִיא מְשַׁמַּרְתּוֹ. אִם הָיָה כָּפוּת הֲרֵי זֶה גֵּט וּכְאִלּוּ הִגִּיעַ לַחֲצֵרָהּ שֶׁהִיא עוֹמֶדֶת בְּצִדָּהּ. וְאִם אֵינוֹ כָּפוּת אֵינוֹ גֵּט. נְתָנוֹ בְּיַד הָעֶבֶד וְהוּא יָשֵׁן וְהִיא מְשַׁמַּרְתּוֹ הֲרֵי זֶה פָּסוּל. וְאִם הָיָה כָּפוּת הֲרֵי זוֹ מְגֹרֶשֶׁת:","כָּתַב הַגֵּט וּנְתָנוֹ בְּיַד עַבְדּוֹ וְכָתַב לָהּ שְׁטָר מַתָּנָה עָלָיו כֵּיוָן שֶׁזָּכְתָה בָּעֶבֶד זָכְתָה בַּגֵּט וְנִתְגָּרְשָׁה אִם הָיָה כָּפוּת. וְאִם אֵינוֹ כָּפוּת וְנֵעוֹר קָנְתָה הָעֶבֶד וְאֵינָהּ מְגֹרֶשֶׁת עַד שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ. וְכֵן אִם נָתַן הַגֵּט בַּחֲצֵרוֹ וּמוֹכֵר לָהּ הֶחָצֵר אוֹ נְתָנוֹ לָהּ כֵּיוָן שֶׁקָּנְתָה הֶחָצֵר בִּשְׁטָר אוֹ בְּכֶסֶף אוֹ בַּחֲזָקָה נִתְגָּרְשָׁה:"],"Mishneh Torah, Eruvin 8":["אֵין מַנִּיחִין שְׁנֵי עֵרוּבִין אֶחָד בַּמִּזְרָח וְאֶחָד בַּמַּעֲרָב כְּדֵי שֶׁיְּהַלֵּךְ בְּמִקְצָת הַיּוֹם עַל אֶחָד מִשְׁנִי הָעֵרוּבִין וּבִשְׁאָר הַיּוֹם עַל הָעֵרוּב הַשֵּׁנִי. שֶׁאֵין מְעָרְבִין שְׁנֵי עֵרוּבִין לְיוֹם אֶחָד. טָעָה וְעֵרֵב לִשְׁתֵּי רוּחוֹת כִּמְדֻמֶּה הוּא שֶׁמְּעָרְבִין לִשְׁתֵּי רוּחוֹת. אוֹ שֶׁאָמַר לִשְׁנַיִם צְאוּ וְעָרְבוּ עָלַי אֶחָד עֵרֵב עָלָיו לַצָּפוֹן וְאֶחָד עֵרֵב עָלָיו לַדָּרוֹם מְהַלֵּךְ כְּרַגְלֵי שְׁנֵיהֶם:","כֵּיצַד מְהַלֵּךְ כְּרַגְלֵי שְׁנֵיהֶם. שֶׁאֵינוֹ יָכוֹל לְהַלֵּךְ אֶלָּא בְּמָקוֹם שֶׁיֵּשׁ לִשְׁנֵיהֶם לְהַלֵּךְ בּוֹ. נָתַן הָאֶחָד עֵרוּב בְּרִחוּק אֶלֶף אַמָּה לְרוּחַ מִזְרָח וְהִנִּיחַ הַשֵּׁנִי מֵהֶן עֵרוּבוֹ בְּרִחוּק חֲמֵשׁ מֵאוֹת אַמָּה לְרוּחַ מַעֲרָב. אֵין זֶה שֶׁעֵרְבוּ עָלָיו מְהַלֵּךְ בַּמַּעֲרָב אֶלָּא אֶלֶף אַמָּה כְּרַגְלֵי מִי שֶׁעֵרֵב עָלָיו בַּמִּזְרָח. וְלֹא יְהַלֵּךְ בַּמִּזְרָח אֶלָּא אֶלֶף וַחֲמֵשׁ מֵאוֹת אַמָּה כְּרַגְלֵי מִי שֶׁעֵרֵב עָלָיו בַּמַּעֲרָב. לְפִיכָךְ אִם עֵרֵב אוֹ עֵרְבוּ עָלָיו שְׁנֵי עֵרוּבִין אֵלּוּ אֶחָד בְּרִחוּק אַלְפַּיִם אַמָּה לַמִּזְרָח וְאֶחָד בְּרִחוּק אַלְפַּיִם אַמָּה לַמַּעֲרָב הֲרֵי זֶה לֹא יָזוּז מִמְּקוֹמוֹ:","מְעָרֵב אָדָם שְׁנֵי עֵרוּבִין בִּשְׁתֵּי רוּחוֹת וּמַתְנֶה וְאוֹמֵר אִם אֵרַע לִי דְּבַר מִצְוָה אוֹ נִלְחַצְתִּי לְמָחָר וְנִצְרַכְתִּי לְרוּחַ זוֹ זֶה הָעֵרוּב הוּא שֶׁאֲנִי סוֹמֵךְ עָלָיו וְהָעֵרוּב שֶׁבָּרוּחַ הַשֵּׁנִית אֵינוֹ כְּלוּם. וְאִם נִצְרַכְתִּי לְרוּחַ זוֹ הַשֵּׁנִית זֶה הָעֵרוּב הוּא שֶׁאֲנִי סוֹמֵךְ עָלָיו וְשֶׁבָּרוּחַ הָרִאשׁוֹנָה אֵינוֹ כְּלוּם. וְאִם נִצְרַכְתִּי לִשְׁתֵּי הָרוּחוֹת יֵשׁ לִי לִסְמֹךְ עַל אֵיזֶה עֵרוּב שֶׁאֶרְצֶה וּלְאֵיזֶה שֶׁאֶרְצֶה אֵלֵךְ. וְאִם לֹא אֵרַע לִי דָּבָר וְלֹא נִצְרַכְתִּי לְרוּחַ מֵהֶן אֵין שְׁנֵי הָעֵרוּבִין הָאֵלּוּ עֵרוּב וְאֵינִי סוֹמֵךְ עַל אֶחָד מֵהֶן אֶלָּא הֲרֵינִי כִּבְנֵי עִירִי שֶׁיֵּשׁ לוֹ אַלְפַּיִם אַמָּה לְכָל רוּחַ מִחוּץ לַחוֹמָה:","כְּשֵׁם שֶׁאָסוּר לָצֵאת חוּץ לַתְּחוּם בְּשַׁבָּת כָּךְ אָסוּר לָצֵאת בְּיוֹם טוֹב וּבְיוֹם הַכִּפּוּרִים. וּכְשֵׁם שֶׁהַמּוֹצִיא מֵרְשׁוּת לִרְשׁוּת בְּשַׁבָּת חַיָּב כָּךְ הַמּוֹצִיא מֵרְשׁוּת לִרְשׁוּת בְּיוֹם הַכִּפּוּרִים חַיָּב. אֲבָל בְּיוֹם טוֹב מֻתָּר לְהוֹצִיא מֵרְשׁוּת לִרְשׁוּת. לְפִיכָךְ מְעָרְבִין עֵרוּבֵי חֲצֵרוֹת וּמִשְׁתַּתְּפִין בַּמְּבוֹאוֹת לְיוֹם הַכִּפּוּרִים כְּשַׁבָּת. וּמְעָרְבִין עֵרוּבֵי תְּחוּמִין לְיוֹם הַכִּפּוּרִים וּלְיָמִים טוֹבִים כְּדֶרֶךְ שֶׁמְּעָרְבִין לְשַׁבָּת:","יוֹם טוֹב שֶׁחָל לִהְיוֹת סָמוּךְ לְשַׁבָּת בֵּין מִלְּפָנֶיהָ בֵּין מִלְּאַחֲרֶיהָ אוֹ שְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת יֵשׁ לוֹ לְעָרֵב שְׁנֵי עֵרוּבִין לִשְׁתֵּי רוּחוֹת וְסוֹמֵךְ עַל אֵי זֶה מֵהֶן שֶׁיִּרְצֶה לַיּוֹם הָרִאשׁוֹן וְעַל הָעֵרוּב שֶׁבָּרוּחַ הַשְּׁנִיָּה לַיּוֹם הַשֵּׁנִי. אוֹ מְעָרֵב עֵרוּב אֶחָד לְרוּחַ אַחַת וְסוֹמֵךְ עָלָיו לְאֶחָד מִשְּׁנֵי יָמִים וּבַיּוֹם הַשֵּׁנִי יִהְיֶה כִּבְנֵי הָעִיר וּכְאִלּוּ לֹא עָשָׂה עֵרוּב וְיֵשׁ לוֹ אַלְפַּיִם אַמָּה לְכָל רוּחַ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת אֲבָל בִּשְׁנֵי יָמִים טוֹבִים שֶׁל רֹאשׁ הַשָּׁנָה הֲרֵי הֵן כְּיוֹם אֶחָד וְאֵינוֹ מְעָרֵב לִשְׁנֵי יָמִים אֶלָּא לְרוּחַ אַחַת:","וְכֵן מַתְנֶה אָדָם עַל עֵרוּבוֹ וְאוֹמֵר עֵרוּבִי לְשַׁבָּת זוֹ אֲבָל לֹא לְשַׁבָּת אַחֶרֶת. אוֹ לְשַׁבָּת אַחֶרֶת אֲבָל לֹא לְשַׁבָּת זוֹ. לְשַׁבָּתוֹת וְלֹא לְיָמִים טוֹבִים לְיָמִים טוֹבִים וְלֹא לְשַׁבָּתוֹת:","אָמַר לַחֲמִשָּׁה הֲרֵינִי מְעָרֵב עַל אֵיזֶה מִכֶּם שֶׁאֶרְצֶה רָצִיתִי אֵלֵךְ לֹא רָצִיתִי לֹא אֵלֵךְ. אַף עַל פִּי שֶׁרָצָה מִשֶּׁחָשְׁכָה יֵלֵךְ. דָּבָר שֶׁהוּא מִדִּבְרֵי סוֹפְרִים יֵשׁ בּוֹ בְּרֵרָה. וְכֵן הַמְעָרֵב לְשַׁבָּתוֹת שֶׁל כָּל הַשָּׁנָה וְאָמַר רָצִיתִי אֵלֵךְ לֹא רָצִיתִי לֹא אֵלֵךְ אֶלָּא אֶהְיֶה כִּבְנֵי עִירִי כָּל שַׁבָּת שֶׁיִּרְצֶה יֵלֵךְ אַף עַל פִּי שֶׁרָצָה מִשֶּׁתֶּחְשַׁךְ:","הַמְעָרֵב לִשְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת אוֹ לְשַׁבָּת וְיוֹם טוֹב אַף עַל פִּי שֶׁהוּא עֵרוּב אֶחָד לְרוּחַ אַחַת לִשְׁנֵי הַיָּמִים צָרִיךְ שֶׁיִּהְיֶה הָעֵרוּב בִּמְקוֹמוֹ מָצוּי בְּלַיִל הָרִאשׁוֹן וּבְלֵיל שֵׁנִי כָּל בֵּין הַשְּׁמָשׁוֹת. כֵּיצַד הוּא עוֹשֶׂה. מוֹלִיכוֹ בְּעֶרֶב יוֹם טוֹב אוֹ בְּעֶרֶב שַׁבָּת וּמַחְשִׁיךְ עָלָיו וְנוֹטְלוֹ בְּיָדוֹ וּבָא לוֹ אִם הָיָה לֵיל יוֹם טוֹב. וּלְמָחָר מוֹלִיכוֹ לְאוֹתוֹ מָקוֹם וּמַנִּיחוֹ שָׁם עַד שֶׁתֶּחְשַׁךְ וְאוֹכְלוֹ אִם הָיָה לֵיל שַׁבָּת אוֹ מְבִיאוֹ אִם הָיָה לֵיל יוֹם טוֹב. מִפְּנֵי שֶׁהֵן שְׁתֵּי קְדֻשּׁוֹת וְאֵינָן כְּיוֹם אֶחָד כְּדֵי שֶׁנֹּאמַר מִלֵּיל רִאשׁוֹן קָנָה הָעֵרוּב לִשְׁנֵי יָמִים:","נֶאֱכַל הָעֵרוּב בָּרִאשׁוֹן קָנָה הָעֵרוּב לָרִאשׁוֹן וְאֵין לוֹ עֵרוּב לַשֵּׁנִי. עֵרֵב בְּרַגְלָיו בָּרִאשׁוֹן צָרִיךְ לְעָרֵב בְּרַגְלָיו בַּשֵּׁנִי וְהוּא שֶׁיֵּלֵךְ וְיַעֲמֹד בְּאוֹתוֹ מָקוֹם וְיַחֲשֹׁב בְּלִבּוֹ שֶׁיִּקְנֶה שָׁם שְׁבִיתָה. עֵרֵב בְּפַת בָּרִאשׁוֹן אִם רָצָה לְעָרֵב בְּרַגְלָיו בַּשֵּׁנִי הֲרֵי זֶה עֵרוּב. וְאִם רָצָה לְעָרֵב בְּפַת צָרִיךְ לְעָרֵב בְּאוֹתָהּ הַפַּת עַצְמָהּ שֶׁעֵרֵב בָּהּ בָּרִאשׁוֹן:","יוֹם הַכִּפּוּרִים שֶׁחָל לִהְיוֹת עֶרֶב שַׁבָּת אוֹ לְאַחַר שַׁבָּת בִּזְמַן שֶׁמְּקַדְּשִׁין עַל פִּי הָרְאִיָּה יֵרָאֶה לִי שֶׁהֵן כְּיוֹם אֶחָד וּקְדֻשָּׁה אַחַת הֵם:","זֶה שֶׁאָמַרְנוּ שֶׁיֵּשׁ לוֹ לְעָרֵב שְׁנֵי עֵרוּבִין בִּשְׁתֵּי רוּחוֹת לִשְׁנֵי הַיָּמִים וְהוּא שֶׁיִּהְיֶה אֶפְשָׁר לוֹ לְהַגִּיעַ לְכָל אֶחָד מִשְּׁנֵי הָעֵרוּבִין בַּיּוֹם הָרִאשׁוֹן. אֲבָל אִם אִי אֶפְשָׁר לוֹ לְהַגִּיעַ לָעֵרוּב שֶׁל יוֹם הַשֵּׁנִי בַּיּוֹם הָרִאשׁוֹן אֵין עֵרוּב הַשֵּׁנִי עֵרוּב. שֶׁהָעֵרוּב מִצְוָתוֹ שֶׁיִּהְיֶה בַּסְּעֻדָּה הָרְאוּיָה מִבְּעוֹד יוֹם וְזֶה הוֹאִיל וְאֵינוֹ יָכוֹל לְהַגִּיעַ לְזֶה הָעֵרוּב בַּיּוֹם הָרִאשׁוֹן הֲרֵי זוֹ אֵינָהּ רְאוּיָה מִבְּעוֹד יוֹם:","כֵּיצַד. הֲרֵי שֶׁהִנִּיחַ עֵרוּבוֹ בְּרִחוּק אַלְפַּיִם אַמָּה מִבֵּיתוֹ לְרוּחַ מִזְרָח וְסָמַךְ עָלָיו לְיוֹם רִאשׁוֹן וְהִנִּיחַ עֵרוּב שֵׁנִי בְּרִחוּק אַמָּה אַחַת אוֹ מֵאָה אוֹ אֶלֶף בְּרוּחַ מַעֲרָב וְסָמַךְ עָלָיו לְיוֹם שֵׁנִי אֵין זֶה הַשֵּׁנִי עֵרוּב. שֶׁהֲרֵי בַּיּוֹם הָרִאשׁוֹן אֵין זֶה הָעֵרוּב הַשֵּׁנִי רָאוּי לוֹ מִבְּעוֹד יוֹם לְפִי שֶׁאֵינוֹ יָכוֹל לְהַגִּיעַ אֵלָיו שֶׁהֲרֵי לֹא נִשְׁאַר לוֹ בְּרוּחַ מַעֲרָב כְּלוּם:","אֲבָל אִם הִנִּיחַ עֵרוּבוֹ בְּרִחוּק אֶלֶף וַחֲמֵשׁ מֵאוֹת אַמָּה מִבֵּיתוֹ בְּרוּחַ מִזְרָח וְסָמַךְ עָלָיו לְיוֹם רִאשׁוֹן וְהִנִּיחַ עֵרוּב שֵׁנִי רָחוֹק מִבֵּיתוֹ לְרוּחַ מַעֲרָב בְּתוֹךְ חֲמֵשׁ מֵאוֹת אַמָּה וְסָמַךְ עָלָיו לְיוֹם שֵׁנִי הֲרֵי זֶה עֵרוּב. שֶׁהֲרֵי אֶפְשָׁר לוֹ שֶׁיַּגִּיעַ לוֹ בַּיּוֹם הָרִאשׁוֹן:","יוֹם טוֹב שֶׁחָל לִהְיוֹת בְּעֶרֶב שַׁבָּת אֵינוֹ עוֹשֶׂה עֵרוּב בְּיוֹם טוֹב לֹא עֵרוּבֵי חֲצֵרוֹת וְלֹא עֵרוּבֵי תְּחוּמִין אֶלָּא מְעָרֵב הוּא בְּיוֹם חֲמִישִׁי שֶׁהוּא עֶרֶב יוֹם טוֹב. וְאִם חָלוּ שְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת בַּחֲמִישִׁי וְעֶרֶב שַׁבָּת מֵעֶרֶב מִיּוֹם רְבִיעִי עֵרוּבֵי תְּחוּמִין וְעֵרוּבֵי חֲצֵרוֹת. וְאִם שָׁכַח וְלֹא עֵרֵב הֲרֵי זֶה מְעָרֵב עֵרוּבֵי חֲצֵרוֹת בַּחֲמִישִׁי וּבְעֶרֶב שַׁבָּת וּמַתְנֶה אֲבָל לֹא עֵרוּבֵי תְּחוּמִין:","כֵּיצַד מַתְנֶה. אוֹמֵר בַּחֲמִישִׁי אִם הַיּוֹם יוֹם טוֹב אֵין בִּדְבָרַי כְּלוּם וְאִם לָאו הֲרֵי זֶה עֵרוּב. וּלְמָחָר חוֹזֵר וּמְעָרֵב וְאוֹמֵר אִם הַיּוֹם יוֹם טוֹב כְּבָר עֵרַבְתִּי מֵאֶמֶשׁ וְאֵין בִּדְבָרַי הַיּוֹם כְּלוּם וְאִם אֶמֶשׁ הָיָה יוֹם טוֹב הֲרֵי זֶה עֵרוּב. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת אֲבָל בִּשְׁנֵי יָמִים טוֹבִים שֶׁל רֹאשׁ הַשָּׁנָה הֲרֵי הֵן כְּיוֹם אֶחָד וְאֵינוֹ מְעָרֵב לָהֶן אֶלָּא מֵעֶרֶב יוֹם טוֹב: סָלִיק הִלְכוֹת ערוּבִין"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 12":["מִצְוַת עֲשֵׂה לִפְדּוֹת כָּל אדָם מִיִּשְׂרָאֵל פֶּטֶר חֲמוֹר בְּשֶׂה. וְאִם לֹא רָצָה לִפְדּוֹתוֹ מִצְוַת עֲשֵׂה לְעָרְפוֹ שֶׁנֶּאֱמַר (שמות לד כ) \"וּפֶטֶר חֲמוֹר תִּפְדֶּה בְשֶׂה וְאִם לֹא תִפְדֶּה וַעֲרַפְתּוֹ\". וּשְׁתֵּי מִצְוֹת אֵלּוּ נוֹהֲגוֹת בְּכָל מָקוֹם וּבְכָל זְמַן. וּמִצְוַת פְּדִיָּה קוֹדֶמֶת לְמִצְוַת עֲרִיפָה:","הַשֶּׂה שֶׁפּוֹדִין בּוֹ נוֹתְנוֹ לַכֹּהֵן שֶׁנֶּאֱמַר (במדבר יח טו) \"כָּל פֶּטֶר רֶחֶם\" וְגוֹ':","(במדבר יח טו) \"וְאֵת בְּכוֹר הַבְּהֵמָה הַטְּמֵאָה תִּפְדֶּה\" בְּהֵמָה טְמֵאָה הָאֲמוּרָה כָּאן הִיא הַחֲמוֹר בִּלְבַד:","פֶּטֶר חֲמוֹר אָסוּר בַּהֲנָאָה עַד שֶׁיִּפָּדֶה. וְאִם מְכָרוֹ קֹדֶם פִּדְיוֹן דָּמָיו אֲסוּרִים. וְאִם מֵת קֹדֶם פִּדְיוֹן אוֹ שֶׁעֲרָפוֹ יִקָּבֵר. מִפְּנֵי שֶׁהוּא אָסוּר בַּהֲנָאָה אַף לְאַחַר עֲרִיפָה הוֹאִיל וְלֹא נִפְדָּה. לְפִיכָךְ אִם לֹא פָּדָהוּ וְנָתַן פֶּטֶר הַחֲמוֹר בְּעַצְמוֹ לַכֹּהֵן. אָסוּר לַכֹּהֵן לְהִשְׁתַּמֵּשׁ בּוֹ עַד שֶׁיִּפְדֵּהוּ בְּשֶׂה. וְיִקַּח הַשֶּׂה לְעַצְמוֹ אוֹ יַעַרְפֶנּוּ וְיִקָּבֵר. וְהַכֹּהֲנִים חֲשׁוּדִים עַל דָּבָר זֶה לְפִיכָךְ אָסוּר לְיִשְׂרָאֵל לִתֵּן פֶּטֶר חֲמוֹר לַכֹּהֵן אֶלָּא אִם כֵּן פָּדָהוּ הַכֹּהֵן בְּפָנָיו:","הִפְרִישׁ פִּדְיוֹן פֶּטֶר חֲמוֹר וּמֵת הַשֶּׂה קֹדֶם שֶׁיִּתְּנֶנּוּ לַכֹּהֵן אֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ. וְיִתֵּן הַנְּבֵלָה לַכֹּהֵן לֵהָנוֹת בָּהּ. מֵת פֶּטֶר הַחֲמוֹר אַחַר שֶׁפָּדָהוּ. יִתֵּן הַטָּלֶה לַכֹּהֵן וּמֻתָּר בְּהֲנָיָתוֹ שֶׁכְּבָר נִפְדָּה:","מֵאֵימָתַי חַיָּב לִפְדּוֹתוֹ מִשֶּׁיִּוָּלֵד וְעַד שְׁלֹשִׁים יוֹם. וּמֵאַחַר שְׁלֹשִׁים יוֹם אִם רָצָה לְעָרְפוֹ עוֹרְפוֹ. אִם רָצָה לִפְדּוֹתוֹ פּוֹדֶה וְאֵין כָּאן אֶלָּא מִצְוַת עִכּוּב בִּלְבַד:","לֹא רָצָה לִפְדּוֹתוֹ עוֹרְפוֹ בְּקוֹפִיץ מֵאֲחוֹרָיו שֶׁנֶּאֱמַר (שמות יג יג) (שמות לד כ) \"וְאִם לֹא תִפְדֶּה וַעֲרַפְתּוֹ\". וְאֵין מְמִיתִין אוֹתוֹ לֹא בְּמַקֵּל וְלֹא בְּקָנֶה וְלֹא בְּקֹרְדוֹם וְלֹא בִּמְגֵרָה אֶלָּא בְּקוֹפִיץ. וְלֹא יַכְנִיסֶנּוּ לְחֶדֶר וְיִנְעל הַדֶּלֶת בְּפָנָיו עַד שֶׁיָּמוּת שֶׁנֶּאֱמַר וַעֲרַפְתּוֹ:","אֵין פּוֹדִין לֹא בְּעֵגֶל וְלֹא בְּחַיָּה וְלֹא בְּשֶׂה שָׁחוּט וְלֹא בִּטְרֵפָה וְלֹא בְּכִלְאַיִם וְלֹא בִּכְוִי. שֶׁנֶּאֱמַר (שמות יג יג) (שמות לד כ) \"תִּפְדֶּה בְּשֶׂה\" וְאֵין קָרוּי שֶׂה אֶלָּא כְּבָשִׂים וְעִזִּים חַיִּים בִּלְבַד:","אֵין פּוֹדִין בְּשֶׂה הַדּוֹמֶה [לְמִין] לְאַחֵר. וְאִם פָּדָה פָּדוּי. וּפוֹדִין בְּבֶן פְּקוּעָה. אֲבָל לֹא בִּפְסוּלֵי הַמֻּקְדָּשִׁין שֶׁהֲרֵי נֶאֱמַר בָּהֶן (דברים יב טו) (דברים טו כב) \"כַּצְּבִי וְכָאַיָּל\". מָה צְבִי וְאַיָּל אֵין פּוֹדִין בּוֹ אַף פְּסוּלֵי הַמֻּקְדָּשִׁין אֵין פּוֹדִין בָּהֶם:","פּוֹדִין בְּשֶׂה בֵּין זְכָרִים בֵּין נְקֵבוֹת בֵּין תְּמִימִים בֵּין בַּעֲלֵי מוּמִים בֵּין קְטַנִּים בֵּין גְּדוֹלִים:","שֶׂה שֶׁלְּקָחוֹ מִדְּמֵי שְׁבִיעִית אֵין פּוֹדִין בּוֹ אֶת הַוַּדַּאי. אֲבָל פּוֹדִין בּוֹ אֶת הַסָּפֵק. אִם אֵין לוֹ שֶׂה לִפְדּוֹתוֹ פּוֹדֵהוּ בְּשָׁוְיוֹ וְנוֹתֵן דָּמָיו לַכֹּהֵן. לֹא אָמְרָה תּוֹרָה שֶׂה לְהַחְמִיר עָלָיו אֶלָּא לְהָקֵל עָלָיו. שֶׁאִם הָיָה לוֹ פֶּטֶר חֲמוֹר שֶׁשָּׁוֶה עֶשֶׂר סְלָעִים יֵשׁ לוֹ לִפְדּוֹתוֹ בְּשֶׂה שְׁוֵה דִּינָר. וְלֹא יִהְיֶה זֶה חָמוּר מִן הַהֶקְדֵּשׁ שֶׁנִּפְדֶּה בְּכֶסֶף בְּשָׁוְיוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ דְּמֵי פֶּטֶר חֲמוֹר מִשְּׁלֹשָׁה זוּזִים וּלְמַעְלָה. אֲבָל אִם הָיוּ דָּמָיו פָּחוֹת מִשְׁלֹשָׁה זוּזִים אֵין פּוֹדִין אוֹתוֹ אֶלָּא בְּשֶׂה אוֹ בִּשְׁלֹשָׁה זוּזִים. וְעַיִן יָפָה לֹא יִפְחֹת מִסֶּלַע. וְעַיִן רָעָה בַּחֲצִי סֶלַע. וּבֵינוֹנִית בִּשְׁלֹשָׁה זוּזִים:","והַפּוֹדֶה פֶּטֶר חֲמוֹר שֶׁל חֲבֵרוֹ הֲרֵי זֶה פָּדוּי. וְהַחֲמוֹר לִבְעָלָיו:","כֹּהֲנִים וּלְוִיִּם פְּטוּרִין מִפֶּטֶר חֲמוֹר שֶׁנֶּאֱמַר (במדבר יח טו) \"בְּכוֹר הָאָדָם וְאֵת בְּכוֹר הַבְּהֵמָה הַטְּמֵאָה תִּפְדֶּה\". כָּל שֶׁיֶּשְׁנוֹ בִּבְכוֹר אָדָם יֶשְׁנוֹ בִּבְכוֹר בְּהֵמָה טְמֵאָה. וְהַפָּטוּר מִבְּכוֹר אָדָם פָּטוּר מִבְּכוֹר בְּהֵמָה טְמֵאָה:","הַלּוֹקֵחַ עֻבַּר חֲמוֹרוֹ שֶׁל עַכּוּ\"ם אוֹ הַמּוֹכֵר עֻבַּר חֲמוֹרוֹ לְעַכּוּ\"ם אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי הֲרֵי זֶה פָּטוּר מִן הַבְּכוֹרָה. וְאֵין קוֹנְסִין אוֹתוֹ עַל דָּבָר זֶה. הָיָה הָעַכּוּ\"ם שֻׁתָּף בָּאֵם אוֹ בַּבְּכוֹר אֲפִלּוּ לֹא הָיָה לוֹ אֶלָּא אֶחָד מֵאֶלֶף בּוֹ הֲרֵי זֶה פָּטוּר. הָיָה לוֹ בּוֹ אוֹ בְּאִמּוֹ אֵיבָר אֶחָד כְּגוֹן יָדוֹ אוֹ רַגְלוֹ אֲפִלּוּ אָזְנוֹ כָּל שֶׁאִלּוּ יֵחָתֵךְ יִהְיֶה בַּעַל מוּם הֲרֵי זֶה פָּטוּר מִן הַבְּכוֹרָה. וְאִם כְּשֶׁיֵּחָתֵךְ חֵלֶק הָעַכּוּ\"ם לֹא יִהְיֶה בַּעַל מוּם לַמִּזְבֵּחַ הֲרֵי זֶה חַיָּב. וְכֵן הַמְקַבֵּל חֲמוֹר מִן הָעַכּוּ\"ם לִהְיוֹת מְטַפֵּל בָּהּ וְהַוָּלָד בֵּינֵיהֶם אוֹ עַכּוּ\"ם שֶׁקִּבֵּל מִיִּשְׂרָאֵל הַכּל פָּטוּר מִן הַבְּכוֹרָה שֶׁנֶּאֱמַר (שמות יג ב) \"פֶּטֶר רֶחֶם בִּבְנֵי יִשְׂרָאֵל בָּאָדָם וּבַבְּהֵמָה\" עַד שֶׁיִּהְיֶה הַכּל בְּיִשְׂרָאֵל:","גֵּר שֶׁנִּתְגַּיֵּר וְאֵין יָדוּעַ אִם עַד שֶׁלֹּא נִתְגַּיֵּר יָלְדָה חֲמוֹרוֹ אוֹ אַחַר שֶׁנִּתְגַּיֵּר הֲרֵי זֶה חַיָּב לַעֲרֹף אוֹ לִפְדּוֹת. וְאִם פָּדָה בְּשֶׂה הַשֶּׂה שֶׁל גֵּר שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","עַכּוּ\"ם שֶׁהִפְרִישׁ פֶּטֶר חֲמוֹר מוֹדִיעִין אוֹתוֹ שֶׁאֵינוֹ חַיָּב וַהֲרֵי הוּא מֻתָּר בְּגִזָּה וַעֲבוֹדָה:","פָּרָה שֶׁיָּלְדָה כְּמִין חֲמוֹר אוֹ חֲמוֹר שֶׁיָּלְדָה כְּמִין סוּס פָּטוּר שֶׁנֶּאֱמַר (שמות לד כ) \"וּפֶטֶר חֲמוֹר תִּפְדֶּה בְשֶׂה\" וּפֶטֶר חֲמוֹר שְׁתֵּי פְּעָמִים עַד שֶׁיִּהְיֶה הַיּוֹלֵד חֲמוֹר וְהַנּוֹלָד חֲמוֹר. וְאִם יֵשׁ בּוֹ מִקְצָת סִימָנֵי חֲמוֹר חַיָּב בִּבְכוֹרָה:","חֲמוֹרוֹ שֶׁלֹּא בִּכְּרָה וְיָלְדָה שְׁנֵי זְכָרִים נוֹתֵן טָלֶה לַכֹּהֵן. יָלְדָה זָכָר וּנְקֵבָה מַפְרִישׁ טָלֶה אֶחָד כְּדֵי לְהַפְקִיעַ קְדֻשָּׁה מִמֶּנּוּ עַד שֶׁיִּהְיֶה מֻתָּר בַּהֲנָיָה. שֶׁמָּא הַזָּכָר נוֹלָד תְּחִלָּה. וְטָלֶה זֶה שֶׁהִפְרִישׁ לַבְּעָלִים וְאֵינוֹ לַכֹּהֵן שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","שְׁתֵּי חֲמוֹרָיו שֶׁלֹּא בִּכְּרוּ וְיָלְדוּ שְׁנֵי זְכָרִים נוֹתֵן שְׁנֵי טְלָאִים לַכֹּהֵן. זָכָר וּנְקֵבָה אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה נוֹתֵן טָלֶה אֶחָד לַכֹּהֵן:","יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר אוֹ שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת אֵין כָּאן לַכֹּהֵן כְּלוּם. וְאֵינוֹ צָרִיךְ לְהַפְרִישׁ טָלֶה לְעַצְמוֹ לְפִי שֶׁיֵּשׁ כָּאן סְפֵקוֹת הַרְבֵּה שֶׁמָּא הָאַחַת יָלְדָה זָכָר וְהַשְּׁנִיָּה יָלְדָה שְׁתֵּי נְקֵבוֹת. אוֹ שֶׁמָּא זוֹ יָלְדָה נְקֵבָה וְהָאַחֶרֶת זָכָר וְאַחֲרָיו נְקֵבָה אוֹ נְקֵבָה וְאַחֲרֶיהָ זָכָר. וְכֵן סְפֵקוֹת הַרְבֵּה יֵשׁ בִּשְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת. אַחַת בִּכְּרָה וְאַחַת שֶׁלֹּא בִּכְּרָה וְיָלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ נוֹתֵן טָלֶה אֶחָד לַכֹּהֵן. זָכָר וּנְקֵבָה מַפְרִישׁ טָלֶה אֶחָד לְעַצְמוֹ וְאֵינוֹ נוֹתְנוֹ לַכֹּהֵן מִפְּנֵי שֶׁהוּא סָפֵק וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","וְכֵן הַלּוֹקֵחַ חֲמוֹר מִן הָעַכּוּ\"ם וְאֵין יָדוּעַ אִם בִּכְּרָה אוֹ לֹא בִּכְּרָה וְיָלְדָה זָכָר פּוֹדֶה אוֹתוֹ בְּשֶׂה וְהוּא לַבְּעָלִים. מִפְּנֵי שֶׁהוּא סָפֵק:","מִי שֶׁהָיוּ לוֹ עֲשָׂרָה טְלָאִים כָּל אֶחָד מֵהֶן הִפְרִישׁוֹ עַל סְפֵק פֶּטֶר חֲמוֹר הֲרֵי הֵן כְּחֻלִּין לְכָל דָּבָר וּמִתְעַשְּׂרִין כִּשְׁאָר הַבְּהֵמָה. וּמַפְרֵשׁ אֶחָד מֵהֶן מַעֲשֵׂר וְהַשְּׁאָר שֶׁלּוֹ כְּשֶׁהָיוּ:","יִשְׂרָאֵל שֶׁהָיוּ לוֹ עֲשָׂרָה פִּטְרֵי חֲמוֹרִים וַדָּאִין בְּתוֹךְ בֵּיתוֹ שֶׁנָּפְלוּ לוֹ מִבֵּית אֲבִי אִמּוֹ כֹּהֵן וְאוֹתוֹ אֲבִי אִמּוֹ הַכֹּהֵן נָפְלוֹ לוֹ מִבֵּית אֲבִי אִמּוֹ יִשְׂרָאֵל הֲרֵי זֶה מַפְרִישׁ עֲלֵיהֶן עֲשָׂרָה שֵׂיִין וְהֵן שֶׁלּוֹ וְחַיָּבִין בְּמַעֲשֵׂר: סְלִיקוּ לְהוּ הִלְכוֹת בִּכּוּרִים בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Firstlings 4":["בֶהֱמַת הַשֻּׁתָּפִין חַיֶּבֶת בִּבְכוֹרָה. לֹא נֶאֱמַר (דברים יב יז) (דברים יד כג) \"בְּקָרְךָ וְצֹאנֶךָ\" אֶלָּא לְמַעֵט שֻׁתָּפוּת הַנָּכְרִי שֶׁאִם הָיָה שֻׁתָּף בַּפָּרָה אוֹ בָּעֻבָּר אֲפִלּוּ הָיָה לַנָּכְרִי אֶחָד מֵאֶלֶף בָּאֵם אוֹ בַּוָּלָד הֲרֵי זֶה פָּטוּר מִן הַבְּכוֹרָה. הָיָה לוֹ בְּאֶחָד מִשְּׁנֵיהֶם אֵיבָר אֶחָד כְּגוֹן יָד אוֹ רֶגֶל. רוֹאִין כָּל שֶׁאִלּוּ יֵחָתֵךְ וְהָיָה בַּעַל מוּם הֲרֵי זֶה פָּטוּר. וְאִם אֶפְשָׁר שֶׁיֵּחָתֵךְ אֵיבַר הַנָּכְרִי וְלֹא יִפָּסֵל. הֲרֵי זֶה חַיָּב בִּבְכוֹרָה:","הַלּוֹקֵחַ עֻבַּר פָּרָתוֹ שֶׁל נָכְרִי. אוֹ הַמּוֹכֵר עֻבַּר פָּרָתוֹ לְנָכְרִי. אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי הֲרֵי זֶה פָּטוּר מִן הַבְּכוֹרָה. וְאֵין קוֹנְסִין אוֹתוֹ עַל דָּבָר זֶה:","הַמְקַבֵּל בְּהֵמָה מִן הַנָּכְרִי לִהְיוֹת מְטַפֵּל בָּהּ וְהַוְּלָדוֹת בֵּינֵיהֶם. אוֹ נָכְרִי שֶׁקִּבֵּל מִיִּשְׂרָאֵל כָּזֶה. הֲרֵי אֵלּוּ פְּטוּרִים מִן הַבְּכוֹרָה שֶׁנֶּאֱמַר (שמות יג ב) \"פֶּטֶר כָּל רֶחֶם בִּבְנֵי יִשְׂרָאֵל\" עַד שֶׁיִּהְיֶה הַכּל מִיִּשְׂרָאֵל:","הַמְקַבֵּל צֹאן מִן הַנָּכְרִי בְּמָמוֹן קָצוּב וּפָסַק עִמּוֹ שֶׁיִּהְיֶה הַשָּׂכָר בֵּינֵיהֶם וְאִם פִּחֲתוּ פִּחֲתוּ לְיִשְׂרָאֵל. אַף עַל פִּי שֶׁבִּרְשׁוּת יִשְׂרָאֵל הֵם וַהֲרֵי הֵם כְּקִנְיָנוֹ הוֹאִיל וְאִם לֹא יִמְצָא הַנָּכְרִי אֶצְלוֹ מָמוֹן אַחֵר לִגְבּוֹת מִמֶּנּוּ יִגְבֶּה מִן הַבְּהֵמוֹת הָאֵלּוּ וּמִוַּלְדוֹתֵיהֶן נַעֲשָׂה כְּמוֹ שֶׁיֵּשׁ לוֹ אַחֲרָיוּת עֲלֵיהֶן וְעַל וַלְדוֹתֵיהֶן וַהֲרֵי יַד הַנָּכְרִי בְּאֶמְצַע וּפְטוּרִין מִן הַבְּכוֹרָה הֵם וּוַלְדוֹתֵיהֶן. אֲבָל וַלְדֵי וְלָדוֹת חַיָּבִין שֶׁהֲרֵי שֶׁל יִשְׂרָאֵל הֵם וְאֵין לַנָּכְרִי רְשׁוּת עֲלֵיהֶן:","יִשְׂרָאֵל שֶׁנָּתַן מָעוֹת לְנָכְרִי וְקָנָה לוֹ בָּהֶן בְּהֵמָה מִנָּכְרִי בְּדִינֵיהֶן אַף עַל פִּי שֶׁלֹּא מָשַׁךְ קָנָה וְחַיֶּבֶת בִּבְכוֹרָה. וְכֵן אִם קָנָה הַנָּכְרִי מִיִּשְׂרָאֵל בְּדִינֵיהֶם וְנָתַן מָעוֹת אַף עַל פִּי שֶׁלֹּא מָשַׁךְ קָנָה וּפְטוּרָה מִבְּכוֹרָה:","גֵּר שֶׁנִּתְגַּיֵּר וְאֵין יָדוּעַ אִם עַד שֶׁלֹּא נִתְגַּיֵּר יָלְדָה פָּרָתוֹ אוֹ אַחַר שֶׁנִּתְגַּיֵּר הֲרֵי זֶה בְּכוֹר מִסָּפֵק:","הַלּוֹקֵחַ בְּהֵמָה מִן הַנָּכְרִי וְאֵין יָדוּעַ אִם בִּכְּרָה אוֹ לֹא בִּכְּרָה וְיָלְדָה אֶצְלוֹ הֲרֵי זֶה סְפֵק בְּכוֹר וְיֵאָכֵל בְּמוּמוֹ לַבְּעָלִים וְאֵינוֹ לַכֹּהֵן שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","לָקַח בְּהֵמָה מֵינִיקָה מִן הַנָּכְרִי אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא בְּנָהּ שֶׁל אַחֶרֶת הִיא מֵינִיקָה אֶלָּא הֲרֵי זוֹ בְּחֶזְקַת שֶׁיָּלְדָה. וַאֲפִלּוּ הָיָה זֶה שֶׁמֵּינִיקָה כְּמוֹ מִין אַחֵר וַאֲפִלּוּ כְּמִין חֲזִיר הֲרֵי זוֹ פְּטוּרָה מִן הַבְּכוֹרָה. וְכֵן בְּהֵמָה שֶׁהִיא חוֹלֶבֶת פְּטוּרָה מִן הַבְּכוֹרָה שֶׁרֹב הַבְּהֵמוֹת אֵינָן חוֹלְבוֹת אֶלָּא אִם כֵּן כְּבָר יָלְדוּ:","הַלּוֹקֵחַ בְּהֵמָה מִיִּשְׂרָאֵל הֲרֵי זוֹ בְּחֶזְקַת שֶׁבִּכְּרָה עַד שֶׁיּוֹדִיעוֹ הַמּוֹכֵר שֶׁעֲדַיִן לֹא יָלְדָה. שֶׁאֵין הַיִּשְׂרָאֵל שׁוֹתֵק וְגוֹרֵם לוֹ לֶאֱכל קָדָשִׁים בַּחוּץ וַדַּאי שֶׁבִּכְּרָה וּלְפִיכָךְ מְכָרָהּ סְתָם:","בְּהֵמָה דַּקָּה שֶׁהִפִּילָה עֻבָּר שֶׁעֲדַיִן לֹא נִתְבָּאֵר צוּרָתוֹ הַרְבֵּה וְנִכֶּרֶת לַכּל וְזֶהוּ הַנִּקְרָא טִנּוּף. אִם אָמְרוּ הָרוֹעִים עֻבָּר הוּא אֶלָּא שֶׁנִּפְסְדָה צוּרָתוֹ הֲרֵי זוֹ פְּטוּרָה מִן הַבְּכוֹרָה וְצָרִיךְ לְהַרְאוֹתוֹ לְרוֹעֶה חָכָם. לְפִיכָךְ הַלּוֹקֵחַ בְּהֵמָה מִן הַנָּכְרִי אֲפִלּוּ הָיְתָה קְטַנָּה וְיָלְדָה אֶצְלוֹ בְּתוֹךְ שְׁנָתָהּ הֲרֵי זֶה סְפֵק בְּכוֹר שֶׁמָּא טִנּוּף הִפִּילָה בִּרְשׁוּת הַנָּכְרִי. וְכֵן בְּהֵמָה גַּסָּה שֶׁהִפִּילָה שִׁלְיָא הֲרֵי זוֹ סִימָן וָלָד שֶׁאֵין שִׁלְיָא בְּלֹא וָלָד וְנִפְטְרָה מִן הַבְּכוֹרָה. וּמֻתָּר לְהַשְׁלִיךְ אוֹתָהּ הַשִּׁלְיָא לַכְּלָבִים שֶׁאֵין מִתְקַדֵּשׁ בִּבְכוֹרָה אֶלָּא זָכָר וְחֶזְקַת הַנּוֹלָדִים מֶחֱצָה זְכָרִים וּמֶחֱצָה נְקֵבוֹת. וּכְבָר בֵּאַרְנוּ שֶׁהַזָּכָר שֶׁאֵין בּוֹ מִקְצָת סִימָנֵי אִמּוֹ אֵינוֹ מִתְקַדֵּשׁ בִּבְכוֹרָה וְנִמְצָא מִעוּט הַנּוֹלָדִים הֵן הַמִּתְקַדְּשִׁין בִּבְכוֹרָה וְאֵין חוֹשְׁשִׁין לְמִעוּט. אֲבָל בֶּהֱמַת קָדָשִׁים שֶׁהִפִּילָה שִׁלְיָא תִּקָּבֵר [שֶׁהַנְּקֵבוֹת בָּהּ כִּזְכָרִים]:","בְּהֵמָה גַּסָּה שֶׁהִפִּילָה חֲרָרַת דָּם הֲרֵי זוֹ נִפְטְרָה מִן הַבְּכוֹרָה שֶׁחֶזְקָתָהּ שֶׁהַוָּלָד בְּתוֹכָהּ וְרָבָה עָלָיו הַדָּם וְהִפְסִידוֹ וּבִטְּלוֹ. וְקוֹבְרִין חֲרָרָה זוֹ כְּמוֹ נֵפֶל מְבַכֶּרֶת אַף עַל פִּי שֶׁאֵין חֲרָרָה זוֹ קְדוֹשָׁה. וְלָמָּה קוֹבְרִין אוֹתָהּ כְּדֵי לְפַרְסֵם הַדָּבָר שֶׁנִּפְטְרָה מִן הַבְּכוֹרָה:","כְּבָר בֵּאַרְנוּ בְּעִנְיַן נִדָּה שֶׁהַוָּלָד בָּאָדָם נִגְמָר לְאַרְבָּעִים יוֹם וְהַמַּפֶּלֶת לְפָחוֹת מֵאַרְבָּעִים אֵינוֹ וָלָד. אֲבָל וְלַד בְּהֵמָה לֹא עָמְדוּ חֲכָמִים עַל מִנְיַן הַיָּמִים שֶׁיִּגָּמֵר בּוֹ. אֲבָל אָמְרוּ שֶׁהַמַּפֶּלֶת טִנּוּף אֵינָהּ מִתְעַבֶּרֶת אַחֲרָיו וְלֹא מְקַבֶּלֶת וָלָד אַחֵר לְפָחוֹת מִשְּׁלֹשִׁים יוֹם:","בְּהֵמָה שֶׁיָּצְאָה מְלֵאָה וּבָאָה רֵיקָנִית הַבָּא אַחַר כֵּן בְּכוֹר מִסָּפֵק שֶׁמָּא דָּבָר שֶׁאֵינוֹ פּוֹטֵר בִּבְכוֹרָה הִפִּילָה. וְאֵין לְנִפְלֵי בְּהֵמָה פְּטִירַת רֶחֶם עַד שֶׁיַּעֲגִילוּ רֹאשׁ כְּפִיקָה שֶׁל עֵרֶב:","מַבְכֶּרֶת הַמַּקְשָׁה לֵילֵד מְחַתֵּךְ אֵיבָר וּמַשְׁלִיךְ לַכְּלָבִים וְהַבָּא אַחֲרָיו בְּכוֹר. יָצָא רֻבּוֹ הֲרֵי זֶה יִקָּבֵר וְנִפְטְרָה מִן הַבְּכוֹרָה. וְאִם חָתַךְ אֵיבָר וְהִנִּיחוֹ אֵיבָר וְהִנִּיחוֹ עַד שֶׁהִשְׁלִים רֻבּוֹ הֲרֵי כָּל הָאֵיבָרִים צְרִיכִין קְבוּרָה. וְנִפְטְרָה מִן הַבְּכוֹרָה כֵּיוָן שֶׁיָּצָא רֻבּוֹ בֵּין שָׁלֵם בֵּין מְחֻתָּךְ וַהֲרֵי הוּא לְפָנֵינוּ נִתְקַדֵּשׁ לְמַפְרֵעַ:","יָצָא שְׁלִישׁ וּמְכָרוֹ לְנָכְרִי וְחָזַר וְיָצָא שְׁלִישׁ אַחֵר. נִתְקַדֵּשׁ לְמַפְרֵעַ וְנִפְטְרָה מִן הַבְּכוֹרָה. יָצָא שְׁלִישׁ דֶּרֶךְ דֹּפֶן וּשְׁנֵי שְׁלִישִׁים דֶּרֶךְ רֶחֶם אֵינוֹ קָדוֹשׁ שְׁהָרֹב הָרִאשׁוֹן לֹא יָצָא דֶּרֶךְ רֶחֶם וּלְמַפְרֵעַ הוּא מִתְקַדֵּשׁ:","יָצָא מִעוּט אֵיבָר גָּדוֹל וַהֲרֵי זֶה הַיּוֹצֵא רֻבּוֹ שֶׁל עֻבָּר נִפְטַר מִן הַבְּכוֹרָה וְיִקָּבֵר הַיּוֹצֵא. יָצָא חֲצִי הָעֻבָּר וְהוּא רֻבּוֹ שֶׁל אֵיבָר הַיּוֹצֵא הֲרֵי זֶה סָפֵק אִם נִפְטְרָה מִן הַבְּכוֹרָה אוֹ לֹא נִפְטְרָה לְפִיכָךְ הַבָּא אַחֲרָיו סְפֵק בְּכוֹר:","בְּכוֹר שֶׁכְּרָכוֹ בְּסִיב וְהוֹצִיאוֹ וְלֹא נָגַע בָּרֶחֶם אוֹ שֶׁכְּרָכוֹ בְּשִׁלְיַת בְּהֵמָה אַחֶרֶת אוֹ שֶׁנִּכְרְכָה עָלָיו אֲחוֹתוֹ וְיָצָא הוֹאִיל וְלֹא נָגַע בָּרֶחֶם מִכָּל מָקוֹם הֲרֵי זֶה סְפֵק בְּכוֹר:","הִדְבִּיק שְׁנֵי רְחָמִים זֶה לָזֶה וְיָצָא מִזֶּה וְנִכְנַס לָזֶה הֲרֵי זֶה סָפֵק אִם נִפְטְרָה מִן הַבְּכוֹרָה הַבְּהֵמָה שֶׁנִּכְנַס בָּהּ הַבְּכוֹר שֶׁהֲרֵי פֶּטֶר רֶחֶם אוֹ לֹא נִפְטְרָה עַד שֶׁיִּפְטֹר רַחְמָהּ וְלָדָהּ:","נִפְתְּחוּ כָּתְלֵי בֵּית הָרֶחֶם וְיָצָא הֲרֵי זֶה סָפֵק אִם נְגִיעַת רֶחֶם מְקַדֶּשֶׁת אוֹ אֲוִירוֹ:","נֶעֶקְרוּ כָּתְלֵי בֵּית הָרֶחֶם [וְנִתְלוּ] בְּצַוָּארוֹ הֲרֵי זֶה סָפֵק אִם בִּמְקוֹמוֹ מְקַדֵּשׁ אוֹ מְקַדֵּשׁ אַף חוּץ לִמְקוֹמוֹ:","נִגְמְמוּ כָּתְלֵי בֵּית הָרֶחֶם אֵינוֹ קָדוֹשׁ. נִפְרַץ מִקְצָתוֹ וְעוֹמֵד מְרֻבֶּה עַל הַפָּרוּץ וְיָצָא דֶּרֶךְ הַפָּרוּץ. אוֹ שֶׁהָיָה הַפָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד וְיָצָא דֶּרֶךְ הָעוֹמֵד הֲרֵי זֶה סְפֵק בְּכוֹר:"],"Mishneh Torah, Forbidden Foods 16":["כָּל הַשִּׁעוּרִים הָאֵלּוּ שְׁנָּתְנוּ חֲכָמִים לְדָבָר הָאָסוּר שֶׁנִּתְעָרֵב בְּמִינוֹ הַמֻּתָּר בְּשֶׁלֹּא הָיָה הַדָּבָר הָאָסוּר מְחַמֵּץ אוֹ מְתַבֵּל. אוֹ דָּבָר חָשׁוּב שֶׁהוּא עוֹמֵד כְּמוֹת שֶׁהוּא וְלֹא נִתְעָרֵב וְנִדְמָע בְּדָבָר הַמֻּתָּר. אֲבָל אִם הָיָה מְחַמֵּץ אוֹ מְתַבֵּל אוֹ דָּבָר חָשׁוּב אוֹסֵר בְּכָל שֶׁהוּא:","כֵּיצַד. שְׂאוֹר שֶׁל חִטִּין שֶׁל תְּרוּמָה שֶׁנָּפַל לְתוֹךְ עִסַּת חִטִּין שֶׁל חֻלִּין וְיֵשׁ בּוֹ כְּדֵי לְחַמֵּץ הֲרֵי הָעִסָּה כֻּלָּהּ מְדֻמָּע. וְכֵן תַּבְלִין שֶׁל תְּרוּמָה שֶׁנָּפְלוּ לִקְדֵרַת חֻלִּין וְיֵשׁ בָּהֶן כְּדֵי לְתַבֵּל וְהֵן מִמִּין הַחֻלִּין הַכּל מְדֻמָּע. וְאַף עַל פִּי שֶׁהַשְּׂאוֹר אוֹ הַתַּבְלִין אֶחָד מֵאֶלֶף. וְכֵן שְׂאוֹר שֶׁל כִּלְאֵי הַכֶּרֶם לְתוֹךְ הָעִסָּה אוֹ תַּבְלִין שֶׁל עָרְלָה לְתוֹךְ הַקְּדֵרָה הַכּל אָסוּר בַּהֲנָיָה:","דָּבָר חָשׁוּב שֶׁהוּא אוֹסֵר בְּמִינוֹ בְּכָל שֶׁהוּא שִׁבְעָה דְּבָרִים וְאֵלּוּ הֵן. אֱגוֹזֵי פֶּרֶךְ. וְרִמּוֹנֵי בְּדַן. וְחָבִיּוֹת סְתוּמוֹת. וַחֲלַפוֹת תְּרָדִין. וְקִלְחֵי כְּרוּב. וּדְלַעַת יְוָנִית. וְכִכָּרוֹת שֶׁל בַּעַל הַבַּיִת:","כֵּיצַד. רִמּוֹן אֶחָד מֵרִמּוֹנֵי בְּדַן שֶׁהָיָה עָרְלָה וְנִתְעָרֵב בְּכַמָּה אֲלָפִים רִמּוֹנִים הַכּל אָסוּר בַּהֲנָיָה. וְכֵן חָבִית סְתוּמָה שֶׁל יֵין עָרְלָה אוֹ שֶׁל כִּלְאֵי הַכֶּרֶם שֶׁנִּתְעָרְבָה בְּכַמָּה אֲלָפִים חָבִיּוֹת סְתוּמוֹת הַכּל אֲסוּרִים בַּהֲנָיָה. וְכֵן שְׁאָר הַשִּׁבְעָה דְּבָרִים:","וְכֵן חֲתִיכָה שֶׁל נְבֵלָה אוֹ שֶׁל בְּשַׂר בְּהֵמָה אוֹ חַיָּה אוֹ עוֹף אוֹ דָּג הַטְּמֵאִין שֶׁנִּתְעָרְבָה בְּכַמָּה אֲלָפִים חֲתִיכוֹת הַכּל אָסוּר עַד שֶׁיַּגְבִּיהַּ אוֹתָהּ חֲתִיכָה. וְאַחַר כָּךְ יְשַׁעֵר הַשְּׁאָר בְּשִׁשִּׁים. שֶׁאִם לֹא הִגְבִּיהָהּ הֲרֵי הַדָּבָר הָאָסוּר עוֹמֵד וְלֹא נִשְׁתַּנָּה וְהַחֲתִיכָה חֲשׁוּבָה אֶצְלוֹ שֶׁהֲרֵי מִתְכַּבֵּד בָּהּ לִפְנֵי הָאוֹרְחִין:","וְהוּא הַדִּין בַּחֲתִיכָה שֶׁל בָּשָׂר בְּחָלָב אוֹ שֶׁל חֻלִּין שֶׁנִּשְׁחֲטוּ בָּעֲזָרָה שֶׁהֲרֵי הֵן אֲסוּרִים מִדִּבְרֵיהֶן בַּהֲנָיָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת שְׁחִיטָה אוֹסְרִין בְּכָל שֶׁהֵן עַד שֶׁיַּגְבִּיהַּ אוֹתָן. וְכֵן גִּיד הַנָּשֶׁה שֶׁנִּתְבַּשֵּׁל עִם הַגִּידִין אוֹ עִם הַבָּשָׂר בִּזְמַן שֶׁמַּכִּירוֹ מַגְבִּיהוֹ וְהַשְּׁאָר מֻתָּר שֶׁאֵין בַּגִּידִים בְּנוֹתֵן טַעַם. וְאִם אֵינוֹ מַכִּירוֹ הַכּל אָסוּר מִפְּנֵי שֶׁהוּא בְּרִיָּה בִּפְנֵי עַצְמוֹ הֲרֵי הוּא חָשׁוּב וְאוֹסֵר בְּכָל שֶׁהוּא:","וְכֵן כָּל בַּעֲלֵי חַיִּים חֲשׁוּבִין הֵן וְאֵינָם בְּטֵלִין. לְפִיכָךְ שׁוֹר הַנִּסְקָל שֶׁנִּתְעָרֵב בְּאֶלֶף שְׁוָרִים וְעֶגְלָה עֲרוּפָה בְּאֶלֶף עֶגְלוֹת. אוֹ צִפּוֹר מְצֹרָע הַשְּׁחוּטָה בְּאֶלֶף צִפֳּרִים אוֹ פֶּטֶר חֲמוֹר בְּאֶלֶף חֲמוֹרִים כֻּלָּן אֲסוּרִין בַּהֲנָיָה. אֲבָל שְׁאָר הַדְּבָרִים אַף עַל פִּי שֶׁדַּרְכָּן לִמָּנוֹת הֲרֵי אֵלּוּ עוֹלִין בְּשִׁעוּרָן:","כֵּיצַד. אֲגֻדָּה שֶׁל יָרָק מִכִּלְאֵי הַכֶּרֶם שֶׁנִּתְעָרְבָה בְּמָאתַיִם אֲגֻדּוֹת. אוֹ אֶתְרוֹג שֶׁל עָרְלָה שֶׁנִּתְעָרֵב בְּמָאתַיִם אֶתְרוֹגִים. הַכּל מֻתָּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","יֵרָאֶה לִי שֶׁכָּל דָּבָר שֶׁהוּא חָשׁוּב אֵצֶל בְּנֵי מָקוֹם מִן הַמְּקוֹמוֹת. כְּגוֹן אֱגוֹזֵי פֶּרֶךְ וְרִמּוֹנֵי בְּדַן בְּאֶרֶץ יִשְׂרָאֵל בְּאוֹתָן הַזְּמַנִּים. שֶׁהוּא אוֹסֵר בְּכָל שֶׁהוּא לְפִי חֲשִׁיבוּתוֹ בְּאוֹתוֹ מָקוֹם וּבְאוֹתוֹ זְמַן. וְלֹא הֻזְכְּרוּ אֵלּוּ אֶלָּא לְפִי שֶׁהֵן אוֹסְרִין כָּל שֶׁהֵן בְּכָל מָקוֹם. וְהוּא הַדִּין לְכָל כַּיּוֹצֵא בָּהֶן בִּשְׁאָר מְקוֹמוֹת. וְדָבָר בָּרוּר הוּא שֶׁכָּל אִסּוּרִין הָאֵלּוּ מִדִּבְרֵיהֶם:","נָפַל רִמּוֹן אֶחָד מִן הַתַּעֲרֹבֶת הַזֹּאת לִשְׁנֵי רִמּוֹנִים אֲחֵרִים מֵרִמּוֹנֵי בְּדַן. וְנָפַל מִן הַשְּׁלֹשָׁה רִמּוֹן אֶחָד לְרִמּוֹנִים אֲחֵרִים. הֲרֵי אֵלּוּ הָאֲחֵרִים מֻתָּרִין שֶׁהֲרֵי הָרִמּוֹן שֶׁל תַּעֲרֹבֶת הָרִאשׁוֹנָה בָּטֵל בְּרֹב. וְאִם נָפַל מִן הַתַּעֲרֹבֶת הָרִאשׁוֹנָה רִמּוֹן לְאֶלֶף כֻּלָּן אֲסוּרִין. לֹא נֶאֱמַר בָּטֵל בְּרֹב אֶלָּא לְהַתִּיר סְפֵק סְפֵקָן שֶׁאִם יִפּל מִן הַתַּעֲרֹבֶת הַשְּׁנִיָּה לְמָקוֹם אַחֵר אֵינוֹ אוֹסֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נִתְפַּצְּעוּ אֱגוֹזִים אֵלּוּ שֶׁנֶּאֶסְרוּ כֻּלָּן מִפְּנֵי אֱגוֹז עָרְלָה שֶׁבֵּינֵיהֶן אוֹ נִתְפָּרְרוּ הָרִמּוֹנִים וְנִתְפַּתְּחוּ הֶחָבִיּוֹת וְנִתְחַתְּכוּ הַדְּלוּעִין וְנִתְפָּרְסוּ הַכִּכָּרוֹת אַחַר שֶׁנֶּאֶסְרוּ הֲרֵי אֵלּוּ יַעֲלוּ בְּאֶחָד וּמָאתַיִם. וְהוּא הַדִּין לַחֲתִיכַת נְבֵלָה שֶׁנִּדּוֹכָה בְּכָל הַחֲתִיכוֹת וְנַעֲשָׂה הַכּל כְּמוֹת שֶׁהִיא עוֹלֶה בְּשִׁשִּׁים:","וְאָסוּר לִפְצֹעַ הָאֱגוֹזִים וּלְפָרֵר הָרִמּוֹנִים וְלִפְתֹּחַ הֶחָבִיּוֹת אַחַר שֶׁנֶּאֶסְרוּ כְּדֵי שֶׁיַּעֲלוּ בְּאֶחָד וּמָאתַיִם שֶׁאֵין מְבַטְּלִין אִסּוּר לְכַתְּחִלָּה. וְאִם עָשָׂה כֵּן קוֹנְסִין אוֹתוֹ וְאוֹסְרִין עָלָיו כְּמוֹ שֶׁבֵּאַרְנוּ:","שְׂאוֹר שֶׁל כִּלְאֵי הַכֶּרֶם וְשֶׁל תְּרוּמָה שֶׁנָּפְלוּ לְתוֹךְ הָעִסָּה לֹא בָּזֶה כְּדֵי לְחַמֵּץ וְלֹא בָּזֶה כְּדֵי לְחַמֵּץ וּבִשְׁנֵיהֶם כְּשֶׁיִּצְטָרְפוּ יֵשׁ בָּהֶם כְּדֵי לְחַמֵּץ. אוֹתָהּ עִסָּה אֲסוּרָה לְיִשְׂרָאֵל וּמֻתֶּרֶת לַכֹּהֲנִים. וְכֵן תַּבְלִין שֶׁל תְּרוּמָה וְשֶׁל כִּלְאֵי הַכֶּרֶם שֶׁנָּפְלוּ לְתוֹךְ הַקְּדֵרָה. וְלֹא בְּאֶחָד מֵהֶן כְּדֵי לְתַבֵּל וּבִשְׁנֵיהֶם כְּדֵי לְתַבֵּל. אוֹתָהּ קְדֵרָה אֲסוּרָה לְיִשְׂרָאֵל שֶׁהֲרֵי דָּבָר הָאָסוּר לָהֶם תִּבְּלָה. וּמֻתֶּרֶת לַכֹּהֲנִים:","תַּבְלִין שֶׁהֵם שְׁנַיִם אוֹ שְׁלֹשָׁה שֵׁמוֹת מִמִּין אֶחָד אוֹ שְׁלֹשָׁה מִינִין מִשֵּׁם אֶחָד מִצְטָרְפִין לְתַבֵּל וְלֶאֱסֹר וְכֵן לְחַמֵּץ. כֵּיצַד. שְׂאוֹר שֶׁל חִטִּין וּשְׂאוֹר שֶׁל שְׂעוֹרִים הוֹאִיל וְשֵׁם שְׂאוֹר אֶחָד הוּא אֵינָן כְּמִין וְשֶׁאֵינוֹ מִינוֹ. אֶלָּא הֲרֵי הֵן כְּמִין אֶחָד וּמִצְטָרֵף לְשַׁעֵר בָּהֶן כְּדֵי לְחַמֵּץ בְּעִסָּה שֶׁל חִטִּין אִם הָיָה טַעַם שְׁנֵיהֶם טַעַם חִטִּין. אוֹ כְּדֵי לְחַמֵּץ בְּעִסָּה שֶׁל שְׂעוֹרִין אִם הָיָה טַעַם שְׁנֵיהֶם טַעַם שְׂעוֹרִים:","שְׁלֹשָׁה שֵׁמוֹת מִמִּין אֶחָד כֵּיצַד. כְּגוֹן כַּרְפַּס שֶׁל נְהָרוֹת וְכַרְפַּס שֶׁל אֲפָר וְכַרְפַּס שֶׁל גִּנָּה אַף עַל פִּי שֶׁכָּל אֶחָד מֵהֶן שֵׁם בִּפְנֵי עַצְמוֹ הוֹאִיל וְהֵם מִין אֶחָד מִצְטָרְפִין לְתַבֵּל:","עִסָּה מְחֻמֶּצֶת שֶׁנָּפַל לְתוֹכָהּ שְׂאוֹר שֶׁל תְּרוּמָה אוֹ שְׂאוֹר שֶׁל כִּלְאֵי הַכֶּרֶם. וְכֵן קְדֵרָה מְתֻבֶּלֶת שֶׁנָּפְלוּ לְתוֹכָהּ תַּבְלִין שֶׁל תְּרוּמָה אוֹ שֶׁל עָרְלָה וְשֶׁל כִּלְאֵי הַכֶּרֶם. אִם יֵשׁ בַּשְּׂאוֹר כְּדֵי לְחַמֵּץ אִלּוּ הָיְתָה הָעִסָּה מַצָּה. וּבַתַּבְלִין כְּדֵי לְתַבֵּל הַקְּדֵרָה אִלּוּ הָיְתָה תְּפֵלָה הֲרֵי הַכּל אָסוּר. וְאִם אֵין בָּהֶם כְּדֵי לְתַבֵּל וּלְחַמֵּץ יַעֲלוּ בְּשִׁעוּרָן. תְּרוּמָה בְּאֶחָד וּמֵאָה וְעָרְלָה וְכִלְאֵי הַכֶּרֶם בְּאֶחָד וּמָאתַיִם:","הַתְּרוּמָה מַעְלָה אֶת הָעָרְלָה וְאֶת כִּלְאֵי הַכֶּרֶם. כֵּיצַד. סְאָה תְּרוּמָה שֶׁנָּפְלָה לְתִשְׁעָה וְתִשְׁעִים חֻלִּין וְאַחַר כָּךְ נָפַל לַכֹּל חֲצִי סְאָה שֶׁל עָרְלָה אוֹ שֶׁל כִּלְאֵי הַכֶּרֶם אֵין כָּאן אִסּוּר עָרְלָה וְלֹא אִסּוּר כִּלְאֵי הַכֶּרֶם. שֶׁהֲרֵי עָלָה בְּאֶחָד וּמָאתַיִם. וְאַף עַל פִּי שֶׁמִּקְצָת הַמָּאתַיִם תְּרוּמָה:","וְכֵן הָעָרְלָה וְכִלְאֵי הַכֶּרֶם מַעֲלִין אֶת הַתְּרוּמָה. כֵּיצַד. מֵאָה סְאָה שֶׁל עָרְלָה אוֹ שֶׁל כִּלְאֵי הַכֶּרֶם שֶׁנָּפְלוּ לְתוֹךְ עֶשְׂרִים אֶלֶף שֶׁל חֻלִּין נַעֲשֵׂית כָּל הַתַּעֲרֹבֶת עֶשְׂרִים אֶלֶף וּמֵאָה. וְאַחַר כָּךְ נָפַל לְכָל מֵאָה סְאָה סְאָה שֶׁל תְּרוּמָה הֲרֵי הַכּל מֻתָּר וְתַעֲלֶה הַתְּרוּמָה בְּאֶחָד וּמֵאָה. וְאַף עַל פִּי שֶׁמִּקְצָת הַמֵּאָה הַמַּעֲלִין אוֹתָהּ עָרְלָה אוֹ כִּלְאֵי הַכֶּרֶם:","וְכֵן הָעָרְלָה מַעֲלָה אֶת כִּלְאֵי הַכֶּרֶם. וְכִלְאֵי הַכֶּרֶם אֶת הָעָרְלָה. וְכִלְאֵי הַכֶּרֶם אֶת כִּלְאֵי הַכֶּרֶם. וְהָעָרְלָה אֶת הָעָרְלָה. כֵּיצַד. מָאתַיִם סְאָה שֶׁל עָרְלָה אוֹ שֶׁל כִּלְאֵי הַכֶּרֶם שֶׁנָּפְלוּ לְאַרְבָּעִים אֶלֶף חֻלִּין. וְאַחַר כָּךְ נָפַל לְכָל מָאתַיִם סְאָה וּסְאָה שֶׁל עָרְלָה אוֹ שֶׁל כִּלְאֵי הַכֶּרֶם הַכּל מֻתָּר. שֶׁכֵּיוָן שֶׁבָּטֵל הָאִסּוּר שֶׁנָּפַל תְּחִלָּה נַעֲשָׂה הַכּל כְּחֻלִּין הַמֻּתָּרִין:","בֶּגֶד שֶׁצְּבָעוֹ בִּקְלִפֵּי עָרְלָה יִשָּׂרֵף. נִתְעָרֵב בַּאֲחֵרִים יַעֲלֶה בְּאֶחָד וּמָאתַיִם. וְכֵן תַּבְשִׁיל שֶׁבִּשְּׁלוֹ בִּקְלִפֵּי עָרְלָה וּפַת שֶׁאֲפָאָהּ בִּקְלִפֵּי עָרְלָה אוֹ בְּכִלְאֵי הַכֶּרֶם יִשָּׂרֵף הַתַּבְשִׁיל וְהַפַּת. שֶׁהֲרֵי הֲנָיָתוֹ נִכֶּרֶת בָּהֶן. נִתְעָרְבוּ בַּאֲחֵרִים יַעֲלוּ בְּאֶחָד וּמָאתַיִם:","וְכֵן בֶּגֶד שֶׁאָרַג בּוֹ מְלֹא הַסִּיט שֶׁצְּבָעוֹ בָּעָרְלָה וְאֵין יָדוּעַ אֵי זֶה הוּא יַעֲלֶה בְּאֶחָד וּמָאתַיִם. נִתְעָרְבוּ סַמָּנֵי עָרְלָה בְּסַמָּנֵי הֶתֵּר יַעֲלוּ בְּאֶחָד וּמָאתַיִם. מֵי צֶבַע בְּמֵי צֶבַע יִבָּטֵל בְּרֹב:","תַּנּוּר שֶׁהִסִּיקוֹ בִּקְלִפֵּי עָרְלָה וּבְכִלְאֵי הַכֶּרֶם בֵּין חָדָשׁ בֵּין יָשָׁן יוּצַן. וְאַחַר כָּךְ יָחֵם אוֹתוֹ בַּעֲצֵי הֶתֵּר. וְאִם בִּשֵּׁל בּוֹ קֹדֶם שֶׁיּוּצַן בֵּין פַּת בֵּין תַּבְשִׁיל הֲרֵי זֶה אָסוּר בַּהֲנָיָה. יֵשׁ שֶׁבַח עֲצֵי אִסּוּר בְּפַת אוֹ בְּתַבְשִׁיל. גָּרַף אֶת כָּל הָאֵשׁ וְאַחַר כָּךְ בִּשֵּׁל אוֹ אָפָה בְּחֻמּוֹ שֶׁל תַּנּוּר הֲרֵי זֶה מֻתָּר שֶׁהֲרֵי עֲצֵי אִסּוּר הָלְכוּ לָהֶן:","קְעָרוֹת וְכוֹסוֹת וּקְדֵרוֹת וּצְלוֹחִיּוֹת שֶׁבִּשְּׁלָן הַיּוֹצֵר בִּקְלִפֵּי עָרְלָה הֲרֵי אֵלּוּ אֲסוּרִין בַּהֲנָאָה. שֶׁהֲרֵי דָּבָר הָאָסוּר בַּהֲנָאָה עָשָׂה אוֹתָן חָדָשׁ:","פַּת שֶׁבִּשְּׁלָהּ עַל גַּבֵּי גֶּחָלִים שֶׁל עֲצֵי עָרְלָה מֻתֶּרֶת. כֵּיוָן שֶׁנַּעֲשׂוּ גֶּחָלִים הָלַךְ אִסּוּרָן אַף עַל פִּי שֶׁהֵן בּוֹעֲרוֹת. קְדֵרָה שֶׁבִּשֵּׁל אוֹתָהּ בִּקְלִפֵּי עָרְלָה אוֹ בְּכִלְאֵי הַכֶּרֶם וּבַעֲצֵי הֶתֵּר הֲרֵי הַתַּבְשִׁיל אָסוּר. וְאַף עַל פִּי שֶׁזֶּה וְזֶה גּוֹרֵם. שֶׁבְּשָׁעָה שֶׁנִּתְבַּשְּׁלָה מֵחֲמַת עֲצֵי אִסּוּר עֲדַיִן לֹא בָּאוּ עֲצֵי הַהֶתֵּר וְנִמְצָא מִקְצָת הַבִּשּׁוּל בַּעֲצֵי הֶתֵּר וּמִקְצָתוֹ בְּאִסּוּר:","נְטִיעָה שֶׁל עָרְלָה שֶׁנִּתְעָרְבָה בִּנְטִיעוֹת. וְכֵן עֲרוּגָה שֶׁל כִּלְאֵי הַכֶּרֶם בַּעֲרוּגוֹת. הֲרֵי זֶה לוֹקֵט לְכַתְּחִלָּה מִן הַכּל. וְאִם הָיְתָה נְטִיעָה בְּמָאתַיִם נְטִיעוֹת וַעֲרוּגָה בְּמָאתַיִם עֲרוּגוֹת הֲרֵי כָּל הַנִּלְקָט מֻתָּר. וְאִם הָיוּ בְּפָחוֹת מִזֶּה כָּל הַנִּלְקָט אָסוּר. וְלָמָּה הִתִּירוּ לוֹ לִלְקֹט לְכַתְּחִלָּה וְהָיָה מִן הַדִּין שֶׁאוֹסְרִין לוֹ הַכּל עַד שֶׁיִּטְרַח וְיוֹצִיא הַנְּטִיעָה וְהָעֲרוּגָה הָאֲסוּרָה. שֶׁהַדָּבָר חֲזָקָה שֶׁאֵין אָדָם אוֹסֵר כַּרְמוֹ בִּנְטִיעָה אַחַת וְאִלּוּ הָיָה יוֹדְעָהּ הָיָה מוֹצִיאָהּ:","הַמַּעֲמִיד גְּבִינָה בִּשְׂרַף פַּגֵּי עָרְלָה. אוֹ בְּקֵיבַת תִּקְרֹבֶת עַכּוּ\"ם. אוֹ בְּחֹמֶץ יַיִן שֶׁל עַכּוּ\"ם. הֲרֵי זוֹ אֲסוּרָה בַּהֲנָיָה אַף עַל פִּי שֶׁהוּא מִין בְּשֶׁאֵינוֹ מִינוֹ וְאַף עַל פִּי שֶׁהוּא כָּל שֶׁהוּא. שֶׁהֲרֵי הַדָּבָר הָאָסוּר הוּא הַנִּכָּר וְהוּא שֶׁעָשָׂה אוֹתָהּ גְּבִינָה:","הָעָרְלָה וְכִלְאֵי הַכֶּרֶם דִּין הַפֵּרוֹת שֶׁלָּהֶן שֶׁיִּשָּׂרְפוּ. וְהַמַּשְׁקִין שֶׁלָּהֶן יִקָּבְרוּ מִפְּנֵי שֶׁאִי אֶפְשָׁר לִשְׂרֹף הַמַּשְׁקִין:","יַיִן שֶׁנִּתְנַסֵּךְ לְעַכּוּ\"ם שֶׁנִּתְעָרֵב עִם הַיַּיִן הַכּל אָסוּר בַּהֲנָיָה בְּכָל שֶׁהוּא כְּמוֹ שֶׁאָמַרְנוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהוּרַק הַיַּיִן הַמֻּתָּר עַל טִפָּה שֶׁל יֵין נֶסֶךְ. אֲבָל אִם עֵרָה יֵין נֶסֶךְ מִצִּלְצוּל קָטָן לְתוֹךְ הַבּוֹר שֶׁל יַיִן. אֲפִלּוּ עֵרָה כָּל הַיּוֹם כֻּלּוֹ רִאשׁוֹן רִאשׁוֹן בָּטֵל. עֵרָה מִן הֶחָבִית בֵּין שֶׁעֵרָה מִן הַמֻּתָּר לָאָסוּר אוֹ מִן הָאָסוּר לַמֻּתָּר הַכּל אָסוּר מִפְּנֵי שֶׁהָעַמּוּד הַיּוֹרֵד מִפִּי הֶחָבִית גָּדוֹל:","נִתְעָרֵב סְתָם יֵינָם בַּיַּיִן הֲרֵי זֶה אָסוּר בְּכָל שֶׁהוּא בִּשְׁתִיָּה וְיִמָּכֵר כֻּלּוֹ לְעַכּוּ\"ם. וְלוֹקֵחַ דְּמֵי הַיַּיִן הָאָסוּר שֶׁבּוֹ וּמַשְׁלִיכוֹ לְיָם הַמֶּלַח וְיֵהָנֶה בִּשְׁאָר הַמָּעוֹת. וְכֵן אִם נִתְעָרְבָה חָבִית שֶׁל יֵין נֶסֶךְ בֵּין הֶחָבִיּוֹת הַכּל אֲסוּרִין בִּשְׁתִיָּה וּמֻתָּרִין בַּהֲנָיָה. וְיוֹלִיךְ דְּמֵי אוֹתָהּ חָבִית לְיָם הַמֶּלַח כְּשֶׁיִּמְכֹּר הַכּל לְעַכּוּ\"ם. וְכֵן בְּחָבִית שֶׁל סְתָם יֵינָם:","מַיִם שֶׁנִּתְעָרְבוּ בְּיַיִן אוֹ יַיִן בְּמַיִם בְּנוֹתֵן טַעַם מִפְּנֵי שֶׁהֵן מִין בְּשֶׁאֵינוֹ מִינוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנָּפַל הַמַּשְׁקֶה הַמֻּתָּר לְתוֹךְ הַמַּשְׁקֶה הָאָסוּר. אֲבָל אִם נָפַל הַמַּשְׁקֶה הָאָסוּר לְתוֹךְ הַמַּשְׁקֶה הַמֻּתָּר רִאשׁוֹן רִאשׁוֹן בָּטֵל. וְהוּא שֶׁיּוּרַק מִצִּלְצוּל קָטָן שֶׁהָיָה מֵרִיק וְיוֹרֵד מְעַט מְעַט. וְהֵיאַךְ יִהְיוּ הַמַּיִם אֲסוּרִים כְּגוֹן שֶׁהָיוּ נֶעֱבָדִין אוֹ תִּקְרֹבֶת עַכּוּ\"ם:","בּוֹר שֶׁל יַיִן שֶׁנָּפַל לְתוֹכוֹ קִיתוֹן שֶׁל מַיִם תְּחִלָּה וְאַחַר כָּךְ נָפַל לְתוֹכוֹ יֵין נֶסֶךְ. רוֹאִים אֶת יֵין הַהֶתֵּר כְּאִלּוּ אֵינוֹ וְהַמַּיִם שֶׁנָּפְלוּ מְשַׁעֲרִין בָּהֶן עִם יֵין נֶסֶךְ. אִם רְאוּיִין לְבַטֵּל טַעַם אוֹתוֹ יֵין נֶסֶךְ הֲרֵי הַמַּיִם רָבִין עָלָיו וּמְבַטְּלִין אוֹתוֹ וְיִהְיֶה הַכּל מֻתָּר:","יֵין נֶסֶךְ שֶׁנָּפַל עַל הָעֲנָבִים יְדִיחֵם וְהֵן מֻתָּרוֹת בַּאֲכִילָה. וְאִם הָיוּ מְבֻקָּעוֹת בֵּין שֶׁהָיָה הַיַּיִן יָשָׁן בֵּין שֶׁהָיָה חָדָשׁ אִם נוֹתֵן טַעַם בָּעֲנָבִים הֲרֵי אֵלּוּ אֲסוּרוֹת בַּהֲנָיָה. וְאִם לָאו הֲרֵי אֵלּוּ מֻתָּרוֹת בַּאֲכִילָה:","נָפַל עַל גַּבֵּי תְּאֵנִים הֲרֵי אֵלּוּ מֻתָּרוֹת מִפְּנֵי שֶׁהַיַּיִן פּוֹגֵם בְּטַעַם הַתְּאֵנִים:","יֵין נֶסֶךְ שֶׁנָּפַל עַל הַחִטִּים הֲרֵי אֵלּוּ אֲסוּרוֹת בַּאֲכִילָה וּמֻתָּרוֹת בַּהֲנָיָה. וְלֹא יִמְכְּרֵם לְעַכּוּ\"ם שֶׁמָּא יַחֲזֹר וְיִמְכְּרֵם לְיִשְׂרָאֵל. אֶלָּא כֵּיצַד עוֹשֶׂה. טוֹחֵן אוֹתָן וְעוֹשֶׂה מֵהֶן פַּת וּמוֹכְרָהּ לְעַכּוּ\"ם שֶׁלֹּא בִּפְנֵי יִשְׂרָאֵל כְּדֵי שֶׁלֹּא יִקְּחוּ אוֹתָהּ יִשְׂרָאֵל מִן הָעַכּוּ\"ם שֶׁהֲרֵי פַּת עַכּוּ\"ם אֲסוּרָה כְּמוֹ שֶׁיִּתְבָּאֵר. וְלָמָּה אֵין בּוֹדְקִין אֶת הַחִטִּים בְּנוֹתֵן טַעַם מִפְּנֵי שֶׁהֵן שׁוֹאֲבוֹת וְהַיַּיִן נִבְלָע בָּהֶן:","יֵין נֶסֶךְ שֶׁהֶחֱמִיץ וְנָפַל לְתוֹךְ חֹמֶץ שֵׁכָר אוֹסֵר בְּכָל שֶׁהוּא מִפְּנֵי שֶׁהוּא בְּמִינוֹ שֶׁשְּׁנֵיהֶן חֹמֶץ הֵן. וְיַיִן שֶׁנִּתְעָרֵב עִם הַחֹמֶץ בֵּין שֶׁנָּפַל חֹמֶץ לַיַּיִן בֵּין שֶׁנָּפַל יַיִן לַחֹמֶץ מְשַׁעֲרִין אוֹתוֹ בְּנוֹתֵן טַעַם:"],"Mishneh Torah, Forbidden Intercourse 11":["כָּל שֶׁאָמַרְנוּ בְּנִדָּה וְזָבָה וְיוֹלֶדֶת הוּא דִּין תּוֹרָה. וּכְמִשְׁפָּטִים אֵלּוּ הָיוּ עוֹשִׂין כְּשֶׁהָיוּ בֵּית דִּין הַגָּדוֹל מְצוּיִין וְהָיוּ שָׁם חֲכָמִים גְּדוֹלִים שֶׁמַּכִּירִים הַדָּמִים וְאִם נוֹלַד לָהֶם סָפֵק בִּרְאִיּוֹת אוֹ בִּימֵי נִדָּה וְזִיבָה יַעֲלוּ לְבֵית דִּין וְיִשְׁאֲלוּ כְּמוֹ שֶׁהִבְטִיחָה תּוֹרָה עֲלֵיהֶן שֶׁנֶּאֱמַר (דברים יז ח) \"כִּי יִפָּלֵא מִמְּךָ דָּבָר לַמִּשְׁפָּט בֵּין דָּם לְדָם בֵּין דִּין לְדִין\", בֵּין דַּם נִדָּה לְדַם זִיבָה. וּבְאוֹתָן הַיָּמִים הָיוּ בְּנוֹת יִשְׂרָאֵל נִזְהָרוֹת מִדָּבָר זֶה וּמְשַׁמְּרוֹת וִסְתוֹתֵיהֶן וְסוֹפְרוֹת תָּמִיד יְמֵי הַנִּדָּה וִימֵי הַזִּיבָה:","וְטֹרַח גָּדוֹל יֵשׁ בְּמִנְיַן הַיָּמִים וּפְעָמִים רַבּוֹת יָבוֹאוּ לִידֵי סָפֵק. שֶׁאֲפִלּוּ רָאֲתָה הַבַּת דָּם בְּיוֹם הַלֵּדָה מֵאוֹתוֹ הַיּוֹם מַתְחִילִין לִמְנוֹת לָהּ יְמֵי נִדָּה וִימֵי זִיבָה כְּמוֹ שֶׁבֵּאַרְנוּ. וּלְפִיכָךְ לֹא תִּטָּמֵא הַבַּת בְּזִיבָה אֶלָּא בַּת עֲשָׂרָה יָמִים שֶׁאִם רָאֲתָה בַּיּוֹם שֶׁנּוֹלְדָה הֲרֵי זוֹ נִדָּה שִׁבְעַת יָמִים וּשְׁלֹשֶׁת יָמִים סָמוּךְ לְנִדָּתָהּ הֲרֵי עֲשָׂרָה יָמִים. הִנֵּה לָמַדְתָּ שֶׁמִּתְּחִלַּת רְאִיָּה מַתְחֶלֶת לִמְנוֹת יְמֵי נִדָּה וִימֵי זִיבָה כָּל יָמֶיהָ וַאֲפִלּוּ רָאֲתָה וְהִיא קְטַנָּה:","וּבִימֵי חַכְמֵי הַגְּמָרָא נִסְתַּפֵּק הַדָּבָר הַרְבֵּה בִּרְאִיַּת הַדָּמִים וְנִתְקַלְקְלוּ הַוְּסָתוֹת. לְפִי שֶׁלֹּא הָיָה כֹּחַ בְּכָל הַנָּשִׁים לִמְנוֹת יְמֵי נִדָּה וִימֵי זִיבָה. לְפִיכָךְ הֶחְמִירוּ חֲכָמִים בְּדָבָר זֶה וְגָזְרוּ שֶׁיְּהוּ כָּל יְמֵי הָאִשָּׁה כִּימֵי זִיבָתָהּ וְיִהְיֶה כָּל דָּם שֶׁתִּרְאֶה סְפֵק דַּם זִיבוּת:","וְעוֹד הֶחֱמִירוּ בְּנוֹת יִשְׂרָאֵל עַל עַצְמָן חֻמְרָא יְתֵרָה עַל זֶה. וְנָהֲגוּ כֻּלָּם בְּכָל מָקוֹם שֶׁיֵּשׁ יִשְׂרָאֵל שֶׁכָּל בַּת יִשְׂרָאֵל שֶׁרוֹאָה דָּם אֲפִלּוּ לֹא רָאֲתָה אֶלָּא טִפָּה כְּחַרְדָּל בִּלְבַד וּפָסַק הַדָּם סוֹפֶרֶת לָהּ שִׁבְעָה יָמִים נְקִיִּים וַאֲפִלּוּ רָאֲתָה בְּעֵת נִדָּתָהּ. בֵּין שֶׁרָאֲתָה יוֹם אֶחָד אוֹ שְׁנַיִם אוֹ הַשִּׁבְעָה כֻּלָּן אוֹ יֶתֶר מִשֶּׁיִּפְסֹק הַדָּם סוֹפֶרֶת שִׁבְעַת יָמִים נְקִיִּים כְּזָבָה גְּדוֹלָה וְטוֹבֶלֶת בְּלֵיל שְׁמִינִי אַף עַל פִּי שֶׁהִיא סְפֵק זָבָה, אוֹ בְּיוֹם שְׁמִינִי אִם הָיָה שָׁם דֹּחַק כְּמוֹ שֶׁאָמַרְנוּ. וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לְבַעְלָהּ:","וְכֵן כָּל הַיּוֹלֶדֶת בַּזְּמַן הַזֶּה הֲרֵי הִיא כְּיוֹלֶדֶת בְּזוֹב וּצְרִיכָה שִׁבְעַת יָמִים נְקִיִּים כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִנְהָג פָּשׁוּט בְּשִׁנְעָר וּבְאֶרֶץ הַצְּבִי וּבִסְפָרַד וּבַמַּעֲרָב שֶׁאִם רָאֲתָה דָּם בְּתוֹךְ יְמֵי מְלֹאת אַף עַל פִּי שֶׁרָאֲתָה אַחַר שֶׁסָּפְרָה שִׁבְעַת יָמִים נְקִיִּים וְטָבְלָה הֲרֵי זוֹ סוֹפֶרֶת שִׁבְעַת יָמִים נְקִיִּים אַחַר שֶׁיִּפְסֹק הַדָּם וְאֵין נוֹתְנִין לָהּ יְמֵי טֹהַר כְּלָל. אֶלָּא כָּל דָּם שֶׁתִּרְאֶה הָאִשָּׁה בֵּין דַּם קֹשִׁי בֵּין דַּם טֹהַר הַכּל טָמֵא וְסוֹפֶרֶת שִׁבְעַת יָמִים נְקִיִּים אַחַר שֶׁיִּפְסֹק הַדָּם:","וְדִין זֶה בִּימֵי הַגְּאוֹנִים נִתְחַדֵּשׁ וְהֵם גָּזְרוּ שֶׁלֹּא יִהְיֶה שָׁם דַּם טֹהַר כְּלָל. שֶׁזֶּה שֶׁהֶחְמִירוּ עַל עַצְמָן בִּימֵי חַכְמֵי הַגְּמָרָא אֵינוֹ אֶלָּא בְּרוֹאָה דָּם שֶׁהוּא טָמֵא שֶׁיּוֹשֶׁבֶת עָלָיו שִׁבְעָה נְקִיִּים. אֲבָל דָּם שֶׁתִּרְאֶה בִּימֵי טֹהַר אַחַר סְפִירָה וּטְבִילָה אֵין לָחוּשׁ לוֹ שֶׁאֵין יְמֵי טֹהַר רְאוּיִין לֹא לְנִדָּה וְלֹא לְזִיבָה כְּמוֹ שֶׁבֵּאַרְנוּ:","וְשָׁמַעְנוּ שֶׁבְּצָרְפַת בּוֹעֲלִים עַל דַּם טֹהַר כְּדִין הַגְּמָרָא עַד הַיּוֹם אַחַר סְפִירָה וּטְבִילָה מִטֻּמְאַת יוֹלֶדֶת בְּזוֹב וְדָבָר זֶה תָּלוּי בַּמִּנְהָג:","וְכֵן דִּין דַּם בְּתוּלִים בַּזְּמַן הַזֶּה שֶׁאֲפִלּוּ הָיְתָה קְטַנָּה שֶׁלֹּא הִגִּיעַ זְמַנָּה לִרְאוֹת וְלֹא רָאֲתָה דָּם מִיָּמֶיהָ בּוֹעֵל בְּעִילַת מִצְוָה וּפוֹרֵשׁ. וְכָל זְמַן שֶׁתִּרְאֶה הַדָּם מֵחֲמַת הַמַּכָּה הֲרֵי הִיא טְמֵאָה. וְאַחַר שֶׁיִּפְסֹק הַדָּם סוֹפֶרֶת שִׁבְעָה יָמִים נְקִיִּים:","יֶתֶר עַל זֶה כָּל בַּת שֶׁתְּבָעוּהָ לְהִנָּשֵׂא וְרָצְתָה שׁוֹהָה שִׁבְעַת יָמִים נְקִיִּים מֵאַחַר שֶׁרָצְתָה וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לְהִבָּעֵל. שֶׁמָּא מֵחִמּוּדָהּ לְאִישׁ רָאֲתָה דָּם טִפָּה אַחַת וְלֹא הִרְגִּישָׁה בָּהּ. בֵּין שֶׁהָיְתָה הָאִשָּׁה גְּדוֹלָה בֵּין שֶׁהָיְתָה קְטַנָּה צְרִיכָה לֵישֵׁב שִׁבְעָה נְקִיִּים מֵאַחַר שֶׁרָצְתָה וְאַחַר כָּךְ תִּטְבּל וְתִבָּעֵל:","וְכָל הַדְּבָרִים הָאֵלּוּ חֻמְרָא יְתֵרָה שֶׁנָּהֲגוּ בָּהּ בְּנוֹת יִשְׂרָאֵל מִימֵי חַכְמֵי הַגְּמָרָא וְאֵין לָסוּר מִמֶּנָּה לְעוֹלָם. לְפִיכָךְ כָּל אִשָּׁה שֶׁרָצְתָה כְּשֶׁתְּבָעוּהָ לְהִנָּשֵׂא לֹא תִּנָּשֵׂא עַד שֶׁתִּסְפֹּר וְתִטְבּל וְאִם נִשֵּׂאת לְתַלְמִיד חָכָם מֻתֶּרֶת לְהִנָּשֵׂא מִיָּד וְתִסְפֹּר מֵאַחַר שֶׁנְּשָׂאַתּוּ וְתִטְבּל. שֶׁתַּלְמִיד חָכָם יוֹדֵעַ שֶׁהִיא אֲסוּרָה וְנִזְהָר מִזֶּה וְלֹא יִקְרַב לָהּ עַד שֶׁתִּטְבּל:","דִּין הַכְּתָמִים בַּזְּמַן הַזֶּה כְּמוֹ שֶׁבֵּאַרְנוּ וְאֵין בַּדָּבָר חִדּוּשׁ וְלֹא מִנְהָג אֶלָּא כָּל כֶּתֶם שֶׁאָמַרְנוּ שֶׁהִיא טְהוֹרָה הֲרֵי הִיא טְהוֹרָה וְכָל כֶּתֶם שֶׁאָמַרְנוּ טְמֵאָה (אִם אֵין בַּכֶּתֶם שִׁעוּר כְּדֵי לָחוּשׁ לְזִיבוּת) סוֹפֶרֶת שִׁבְעַת יָמִים מִיּוֹם שֶׁנִּמְצָא בּוֹ הַכֶּתֶם. וְאִם הָיָה שִׁעוּר הַכֶּתֶם כְּדֵי לָחוּשׁ לְזִיבוּת סוֹפֶרֶת שִׁבְעַת יָמִים מֵאַחַר יוֹם שֶׁנִּמְצָא בּוֹ הַכֶּתֶם. שֶׁאֵין הָרוֹאָה דָּם כְּרוֹאָה כֶּתֶם:","וְכֵן כָּל מַה שֶּׁאָמַרְנוּ בְּיוֹלֶדֶת שֶׁאִמּוֹ טְהוֹרָה הֲרֵי הִיא טְהוֹרָה בַּזְּמַן הַזֶּה. וְכֵן הָאִשָּׁה שֶׁרָאֲתָה לֹבֶן אוֹ דָּם יָרֹק אוֹ שֶׁהִשְׁלִיכָה חֲתִיכָה אֲדֻמָּה שֶׁאֵין עִמָּהּ דָּם הֲרֵי הִיא טְהוֹרָה אַף בַּזְּמַן הַזֶּה. שֶׁלֹּא הֶחְמִירוּ אֶלָּא בְּרוֹאָה דָּם טָמֵא [וְאֵין זֶה דָּם טָמֵא]:","וְכֵן אִם הָיְתָה בָּהּ מַכָּה וְהָיָה הַדָּם שׁוֹתֵת מִמֶּנָּה אוֹ שֶׁבָּא הַדָּם עִם מֵימֵי רַגְלַיִם הֲרֵי זוֹ טְהוֹרָה. וְלֹא נִתְחַדֵּשׁ דָּבָר אֶלָּא סְפִירַת שִׁבְעַת יָמִים נְקִיִּים לְכָל רוֹאָה דָּם טָמֵא כְּמוֹ שֶׁאָמַרְנוּ וְשֶׁיִּהְיוּ כָּל מַרְאֵה דָּמִים טְמֵאִים:","זֶה שֶׁתִּמְצָא בְּמִקְצָת הַמְּקוֹמוֹת שֶׁהַנִּדָּה יוֹשֶׁבֶת שִׁבְעַת יָמִים בְּנִדָּתָהּ אַף עַל פִּי שֶׁלֹּא רָאֲתָה דָּם אֶלָּא יוֹם אֶחָד וְאַחַר הַשִּׁבְעָה תֵּשֵׁב שִׁבְעַת יָמִים נְקִיִּים אֵין זֶה מִנְהָג אֶלָּא טָעוּת הוּא מִמִּי שֶׁהוֹרָה לָהֶם כָּךְ וְאֵין רָאוּי לִפְנוֹת לְדָבָר זֶה כְּלָל אֶלָּא אִם רָאֲתָה יוֹם אֶחָד סוֹפֶרֶת אַחֲרָיו שִׁבְעָה (נְקִיִּים) וְטוֹבֶלֶת בְּלֵיל שְׁמִינִי שֶׁהוּא לַיִל שֵׁנִי שֶׁלְּאַחַר נִדָּתָהּ וּמֻתֶּרֶת לְבַעְלָהּ:","וְכֵן זֶה שֶׁתִּמְצָא בְּמִקְצָת מְקוֹמוֹת וְתִמְצָא תְּשׁוּבוֹת לְמִקְצָת הַגְּאוֹנִים שֶׁיּוֹלֶדֶת זָכָר לֹא תְּשַׁמֵּשׁ מִטָּתָהּ עַד סוֹף אַרְבָּעִים. וְיוֹלֶדֶת נְקֵבָה אַחַר שְׁמוֹנִים. וְאַף עַל פִּי שֶׁלֹּא רָאֲתָה דָּם אֶלָּא בְּתוֹךְ הַשִּׁבְעָה. אֵין זֶה מִנְהָג אֶלָּא טָעוּת הוּא בְּאוֹתָן הַתְּשׁוּבוֹת וְדֶרֶךְ אֶפִּיקוֹרוֹסוּת בְּאוֹתָן הַמְּקוֹמוֹת וּמִן הַצְּדוֹקִין לָמְדוּ דָּבָר זֶה. וּמִצְוָה לְכוֹפָן כְּדֵי לְהוֹצִיא מִלִּבָּן וּלְהַחֲזִירָן לְדִבְרֵי חֲכָמִים שֶׁתִּסְפֹּר שִׁבְעָה יָמִים נְקִיִּים בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵין הָאִשָּׁה עוֹלָה מִטֻּמְאָתָהּ וְיוֹצֵאת מִידֵי עֶרְוָה עַד שֶׁתִּטְבּל בְּמֵי מִקְוֶה כָּשֵׁר. וְלֹא יִהְיֶה דָּבָר חוֹצֵץ בֵּין בְּשָׂרָהּ וּבֵין הַמַּיִם. וּבְהִלְכוֹת מִקְוָאוֹת יִתְבָּאֵר הַמִּקְוֶה הַכָּשֵׁר וְהַפָּסוּל וְדֶרֶךְ הַטְּבִילָה וּמִשְׁפְּטֵי הַחֲצִיצָה. אֲבָל אִם רָחֲצָה בַּמֶּרְחָץ אֲפִלּוּ נָפְלוּ עָלֶיהָ כָּל מֵימוֹת שֶׁבָּעוֹלָם הֲרֵי הִיא אַחַר הָרְחִיצָה כְּמוֹת שֶׁהָיְתָה קֹדֶם הָרְחִיצָה בְּכָרֵת. שֶׁאֵין לְךָ דָּבָר שֶׁמַּעֲלֶה מִטֻּמְאָה לְטָהֳרָה אֶלָּא טְבִילָה בְּמֵי מִקְוֵה אוֹ בְּמַעֲיָן אוֹ בַּיַּמִּים שֶׁהֵם כְּמַעֲיָן כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מִקְוָאוֹת:","כָּל שִׁבְעָה יָמִים נְקִיִּים שֶׁבַּזְּמַן הַזֶּה אַף עַל פִּי שֶׁהֵן סָפֵק אִם טָבְלָה בָּהֶן כְּאִלּוּ לֹא טָבְלָה. וְאִם טָבְלָה בַּשְּׁבִיעִי אַף עַל פִּי שֶׁאָסוּר לַעֲשׂוֹת כֵּן לְכַתְּחִלָּה שֶׁמָּא יָבוֹא לִבְעֹל בַּשְּׁבִיעִי אַחַר הַטְּבִילָה. הוֹאִיל וְטָבְלָה בִּזְמַנָּהּ אֲפִלּוּ הָיְתָה זָבָה וַדָּאִית הֲרֵי זוֹ עָלְתָה לָהּ טְבִילָה:","וְאָסוּר לְאָדָם שֶׁיִּדְבַּק בְּאִשְׁתּוֹ בְּשִׁבְעַת יָמִים נְקִיִּים אֵלּוּ וְאַף עַל פִּי שֶׁהִיא בִּכְסוּתָהּ וְהוּא בִּכְסוּתוֹ. וְלֹא יִקְרַב לָהּ וְלֹא יִגַּע בָּהּ אֲפִלּוּ בְּאֶצְבַּע קְטַנָּה. וְלֹא יֹאכַל עִמָּהּ בִּקְעָרָה אַחַת. כְּלָלוֹ שֶׁל דָּבָר יִנְהֹג עִמָּהּ בִּימֵי סְפִירָה כְּמוֹ שֶׁיִּנְהֹג בִּימֵי נִדָּה שֶׁעֲדַיִן הִיא בְּכָרֵת עַד שֶׁתִּטְבּל כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל מְלָאכוֹת שֶׁהָאִשָּׁה עוֹשָׂה לְבַעְלָהּ נִדָּה עוֹשָׂה לְבַעְלָהּ חוּץ מֵהַרְחָצַת פָּנָיו יָדָיו וְרַגְלָיו וּמְזִיגַת הַכּוֹס וְהַצָּעַת הַמִּטָּה בְּפָנָיו. גְּזֵרָה שֶׁמָּא יָבוֹא לִדְבַר עֲבֵרָה. וּמִפְּנֵי זֶה לֹא תֹּאכַל עִמּוֹ בִּקְעָרָה אַחַת וְלֹא יִגַּע בִּבְשָׂרָהּ מִפְּנֵי הֶרְגֵּל עֲבֵרָה. וְכֵן בְּשִׁבְעַת יָמִים נְקִיִּים לֹא תַּעֲשֶׂה לוֹ שָׁלֹשׁ מְלָאכוֹת אֵלּוּ. וּמֻתָּר לְאִשָּׁה לְהִתְקַשֵּׁט בִּימֵי נִדָּתָהּ כְּדֵי שֶׁלֹּא תִּתְגַּנֶּה עַל בַּעְלָהּ:"],"Mishneh Torah, Forbidden Intercourse 22":["אָסוּר לְהִתְיַחֵד עִם עֶרְוָה מִן הָעֲרָיוֹת בֵּין זְקֵנָה בֵּין יַלְדָּה שֶׁדָּבָר זֶה גּוֹרֵם לְגַלּוֹת עֶרְוָה. חוּץ מֵהָאֵם עִם בְּנָהּ וְהָאָב עִם בִּתּוֹ וְהַבַּעַל עִם אִשְׁתּוֹ נִדָּה. וְחָתָן שֶׁפֵּרְסָה אִשְׁתּוֹ נִדָּה קֹדֶם שֶׁיִּבְעל אָסוּר לְהִתְיַחֵד עִמָּהּ אֶלָּא הִיא יְשֵׁנָה בֵּין הַנָּשִׁים וְהוּא יָשֵׁן בֵּין הָאֲנָשִׁים. וְאִם בָּא עָלֶיהָ בִּיאָה רִאשׁוֹנָה וְאַחַר כָּךְ נִטְמֵאת מֻתָּר לְהִתְיַחֵד עִמָּהּ:","לֹא נֶחְשְׁדוּ יִשְׂרָאֵל עַל מִשְׁכַּב זָכוּר וְעַל הַבְּהֵמָה. לְפִיכָךְ אֵין אָסוּר לְהִתְיַחֵד עִמָּהֶן. וְאִם נִתְרַחֵק אֲפִלּוּ מִיִּחוּד זָכוּר וּבְהֵמָה הֲרֵי זֶה מְשֻׁבָּח. וּגְדוֹלֵי הַחֲכָמִים הָיוּ מַרְחִיקִין הַבְּהֵמָה כְּדֵי שֶׁלֹּא יִתְיַחֲדוּ עִמָּהּ. וְאִסּוּר יִחוּד הָעֲרָיוֹת מִפִּי הַקַּבָּלָה:","כְּשֶׁאֵרַע מַעֲשֶׂה אַמְנוֹן וְתָמָר גָּזַר דָּוִד וּבֵית דִּינוֹ עַל יִחוּד פְּנוּיָה. וְאַף עַל פִּי שֶׁאֵינָהּ עֶרְוָה בִּכְלַל יִחוּד עֲרָיוֹת הִיא. וְשַׁמַּאי וְהִלֵּל גָּזְרוּ עַל יִחוּד כּוּתִית. נִמְצָא כָּל הַמִּתְיַחֵד עִם אִשָּׁה שֶׁאָסוּר לְהִתְיַחֵד עִמָּהּ בֵּין יִשְׂרְאֵלִית בֵּין כּוּתִית מַכִּין אֶת שְׁנֵיהֶן מַכַּת מַרְדּוּת הָאִישׁ וְהָאִשָּׁה. וּמַכְרִיזִין עֲלֵיהֶן. חוּץ מֵאֵשֶׁת אִישׁ שֶׁאַף עַל פִּי שֶׁאָסוּר לְהִתְיַחֵד עִמָּהּ אִם נִתְיַחֵד אֵין לוֹקִין. שֶׁלֹּא לְהוֹצִיא לַעַז עָלֶיהָ שֶׁזִּנְּתָה וְנִמְצְאוּ מוֹצִיאִין לַעַז עַל הַבָּנִים שֶׁהֵן מַמְזֵרִים:","כָּל אִשָּׁה שֶׁאָסוּר לְהִתְיַחֵד עִמָּהּ אִם הָיְתָה אִשְׁתּוֹ עִמּוֹ הֲרֵי זוֹ מֻתֶּרֶת לְהִתְיַחֵד מִפְּנֵי שֶׁאִשְׁתּוֹ מְשַׁמַּרְתּוֹ. אֲבָל לֹא תִּתְיַחֵד יִשְׂרְאֵלִית עִם הַכּוּתִי וְאַף עַל פִּי שֶׁאִשְׁתּוֹ עִמּוֹ שֶׁאֵין אִשְׁתּוֹ שֶׁל כּוּתִי מְשַׁמַּרְתּוֹ וְאֵין לָהֶן בּוּשָׁה:","וְכֵן אֵין מוֹסְרִין תִּינוֹק יִשְׂרָאֵל לְכוּתִי לְלַמְּדוֹ סֵפֶר וּלְלַמְּדוֹ אָמָּנוּת. מִפְּנֵי שֶׁכֻּלָּן חֲשׁוּדִין עַל מִשְׁכַּב זָכוּר. וְאֵין מַעֲמִידִין בְּהֵמָה בְּפֻנְדָּקִיּוֹת שֶׁל כּוּתִים וַאֲפִלּוּ זְכָרִים אֵצֶל זְכָרִים וּנְקֵבוֹת אֵצֶל נְקֵבוֹת:","וְאֵין מוֹסְרִין בְּהֵמָה חַיָּה וְעוֹף לְרוֹעֶה כּוּתִי אֲפִלּוּ זְכָרִים לְכוּתִים וּנְקֵבוֹת לְכוּתִית מִפְּנֵי שֶׁכֻּלָּן חֲשׁוּדִין עַל הַרְבָּעַת בְּהֵמָה וּכְבָר בֵּאַרְנוּ שֶׁהֵן אֲסוּרִין בְּזָכוּר וּבִבְהֵמָה וְנֶאֱמַר (ויקרא יט יד) \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל\":","וּמִפְּנֵי מָה אֵין מוֹסְרִין בְּהֵמָה נְקֵבָה לְכוּתִית מִפְּנֵי שֶׁכֻּלָּן בְּחֶזְקַת נוֹאֲפִים וּכְשֶׁיָּבוֹא הַנּוֹאֵף לִשְׁכַּב עִם הַכּוּתִית זוֹ אֶפְשָׁר שֶׁלֹּא יִמְצָאֶנָּה וְיִשְׁכַּב עִם הַבְּהֵמָה אוֹ אֲפִלּוּ יִמְצָאֶנָּה יִשְׁכַּב עִם הַבְּהֵמָה:","לֹא תִּתְיַחֵד אִשָּׁה אַחַת אֲפִלּוּ עִם אֲנָשִׁים הַרְבֵּה עַד שֶׁתִּהְיֶה אִשְׁתּוֹ שֶׁל אֶחָד מֵהֶם שָׁם. וְכֵן לֹא יִתְיַחֵד אִישׁ אֶחָד אֲפִלּוּ עִם נָשִׁים הַרְבֵּה. נָשִׁים הַרְבֵּה עִם אֲנָשִׁים הַרְבֵּה אֵין חוֹשְׁשִׁין לְיִחוּד. הָיוּ הָאֲנָשִׁים מִבַּחוּץ וְהַנָּשִׁים מִבִּפְנִים אוֹ הָאֲנָשִׁים מִבִּפְנִים וְהַנָּשִׁים מִבַּחוּץ וּפֵרְשָׁה אִשָּׁה אַחַת לְבֵין הָאֲנָשִׁים אוֹ אִישׁ לְבֵין הַנָּשִׁים אֲסוּרִין מִשּׁוּם יִחוּד. אֲפִלּוּ אִישׁ שֶׁעִסְקוֹ וּמְלַאכְתּוֹ עִם הַנָּשִׁים אָסוּר לוֹ לְהִתְיַחֵד עִם הַנָּשִׁים. כֵּיצַד יַעֲשֶׂה. יִתְעַסֵּק עִמָּהֶן וְאִשְׁתּוֹ עִמּוֹ אוֹ יִפְנֶה לִמְלָאכָה אַחֶרֶת:","מֻתָּר לְהִתְיַחֵד עִם שְׁתֵּי יְבָמוֹת. אוֹ עִם שְׁתֵּי צָרוֹת. אוֹ עִם אִשָּׁה וַחֲמוֹתָהּ. אוֹ עִם אִשָּׁה וּבַת בַּעְלָהּ. אוֹ עִם אִשָּׁה וּבַת חֲמוֹתָהּ. מִפְּנֵי שֶׁשּׂוֹנְאוֹת זוֹ אֶת זוֹ וְאֵין מְחַפּוֹת זוֹ עַל זוֹ. וְכֵן מֻתָּר לְהִתְיַחֵד עִם אִשָּׁה שֶׁיֵּשׁ עִמָּהּ תִּינֹקֶת קְטַנָּה שֶׁיּוֹדַעַת טַעַם בִּיאָה וְאֵינָהּ מוֹסֶרֶת עַצְמָהּ לְבִיאָה. שֶׁאֵינָהּ מְזַנָּה בְּפָנֶיהָ שֶׁהֲרֵי זוֹ מְגַלָּה אֶת סוֹדָהּ:","תִּינֹקֶת מִבַּת שָׁלֹשׁ וּלְמַטָּה וְתִינוֹק בֶּן תֵּשַׁע וּלְמַטָּה מֻתָּר לְהִתְיַחֵד עִמָּהֶן. שֶׁלֹּא גָּזְרוּ אֶלָּא עַל יִחוּד אִשָּׁה הָרְאוּיָה לְבִיאָה וְאִישׁ הָרָאוּי לְבִיאָה:","אַנְדְּרוֹגִינוּס אֵינוֹ מִתְיַחֵד עִם הַנָּשִׁים. וְאִם נִתְיַחֵד אֵין מַכִּין אוֹתוֹ מִפְּנֵי שֶׁהוּא סָפֵק. אֲבָל הָאִישׁ מִתְיַחֵד עִם הָאַנְדְּרוֹגִינוּס וְעִם הַטֻּמְטוּם:","אֵשֶׁת אִישׁ שֶׁהָיָה בַּעְלָהּ בָּעִיר אֵינָהּ חוֹשֶׁשֶׁת לְיִחוּד. מִפְּנֵי שֶׁאֵימַת בַּעְלָהּ עָלֶיהָ. וְאִם הָיָה זֶה גַּס בָּהּ כְּגוֹן שֶׁגָּדְלָה עִמּוֹ אוֹ שֶׁהָיְתָה קְרוֹבָתוֹ לֹא יִתְיַחֵד עִמָּהּ וְאַף עַל פִּי שֶׁבַּעְלָהּ בָּעִיר. וְכֵן כָּל הַמִּתְיַחֵד עִם אִשָּׁה וְהָיָה הַפֶּתַח פָּתוּחַ לִרְשׁוּת הָרַבִּים אֵין חוֹשְׁשִׁין מִשּׁוּם יִחוּד:","מִי שֶׁאֵין לוֹ אִשָּׁה לֹא יְלַמֵּד תִּינוֹקוֹת. מִפְּנֵי שֶׁאִמּוֹת הַבָּנִים בָּאוֹת לְבֵית הַסֵּפֶר לִבְנֵיהֶם וְנִמְצָא מִתְגָּרֶה בְּנָשִׁים. וְכֵן אִשָּׁה לֹא תְּלַמֵּד קְטַנִּים מִפְּנֵי אֲבוֹתֵיהֶן שֶׁהֵן בָּאִין בִּגְלַל בְּנֵיהֶם וְנִמְצְאוּ מִתְיַחֲדִים עִמָּהּ. וְאֵין הַמְלַמֵּד צָרִיךְ שֶׁתִּהְיֶה אִשְׁתּוֹ שְׁרוּיָה עִמּוֹ בְּבֵית הַסֵּפֶר אֶלָּא הִיא בְּבֵיתָהּ וְהוּא מְלַמֵּד בִּמְקוֹמוֹ:","תִּקְּנוּ חֲכָמִים שֶׁתִּהְיֶינָה הַנָּשִׁים מְסַפְּרוֹת זוֹ עִם זוֹ בְּבֵית הַכִּסֵּא כְּדֵי שֶׁלֹּא יִכָּנֵס שָׁם אִישׁ מִשּׁוּם יִחוּד:","אֵין מְמַנִּין אֲפִלּוּ אָדָם נֶאֱמָן וְכָשֵׁר לִהְיוֹת שׁוֹמֵר חָצֵר שֶׁיֵּשׁ שָׁם נָשִׁים אַף עַל פִּי שֶׁהוּא עוֹמֵד בַּחוּץ שֶׁאֵין אַפּוֹטְרוֹפּוֹס לַעֲרָיוֹת. וְאָסוּר לְאָדָם לְמַנּוֹת אַפּוֹטְרוֹפּוֹס עַל בֵּיתוֹ שֶׁלֹּא יַנְהִיג אִשְׁתּוֹ לִדְבַר עֲבֵרָה:","אָסוּר לְתַלְמִיד חָכָם לִשְׁכֹּן בְּחָצֵר שֶׁיֵּשׁ בָּהּ אַלְמָנָה אַף עַל פִּי שֶׁאֵינוֹ מִתְיַחֵד עִמָּהּ מִפְּנֵי הַחֲשָׁד. אֶלָּא אִם כֵּן הָיְתָה אִשְׁתּוֹ עִמּוֹ. וְכֵן אַלְמָנָה אֲסוּרָה לְגַדֵּל כֶּלֶב מִפְּנֵי הַחֲשָׁד. וְלֹא תִּקְנֶה אִשָּׁה עֲבָדִים זְכָרִים אֲפִלּוּ קְטַנִּים מִפְּנֵי הַחֲשָׁד:","אֵין דּוֹרְשִׁין בְּסִתְרֵי עֲרָיוֹת בִּשְׁלֹשָׁה מִפְּנֵי שֶׁהָאֶחָד טָרוּד בִּשְׁאֵלַת הָרַב וְהַשְּׁנַיִם נוֹשְׂאִין וְנוֹתְנִין זֶה עִם זֶה וְאֵין דַּעְתָּם פְּנוּיָה לִשְׁמֹעַ. שֶׁדַּעְתּוֹ שֶׁל אָדָם קְרוֹבָה אֵצֶל עֲרָיוֹת. אִם נִסְתַּפֵּק לוֹ דָּבָר שֶׁשָּׁמַע מוֹרֶה לְהָקֵל. לְפִיכָךְ אֵין דּוֹרְשִׁין אֶלָּא לִשְׁנַיִם כְּדֵי שֶׁיִּהְיֶה הָאֶחָד הַשּׁוֹמֵעַ מְפַנֶּה דַּעְתּוֹ וְיוֹדֵעַ מַה שֶּׁיִּשְׁמַע מִן הָרַב:","אֵין לְךָ דָּבָר בְּכָל הַתּוֹרָה כֻּלָּהּ שֶׁהוּא קָשֶׁה לְרֹב הָעָם לִפְרשׁ אֶלָּא מִן הָעֲרָיוֹת וְהַבִּיאוֹת הָאֲסוּרוֹת. אָמְרוּ חֲכָמִים בְּשָׁעָה שֶׁנִּצְטַוּוּ יִשְׂרָאֵל עַל הָעֲרָיוֹת בָּכוּ וְקִבְּלוּ מִצְוָה זוֹ בְּתַרְעוֹמוֹת וּבְכִיָּה שֶׁנֶּאֱמַר (במדבר יא י) \"בֹּכֶה לְמִשְׁפְּחֹתָיו\" עַל עִסְקֵי מִשְׁפָּחוֹת:","וְאָמְרוּ חֲכָמִים גֵּזֶל וַעֲרָיוֹת נַפְשׁוֹ שֶׁל אָדָם מִתְאַוָּה לָהֶן וּמְחַמְּדָתָן. וְאֵין אַתָּה מוֹצֵא קָהָל בְּכָל זְמַן וּזְמַן שֶׁאֵין בָּהֶן פְּרוּצִין בַּעֲרָיוֹת וּבִיאוֹת אֲסוּרוֹת. [וְעוֹד] אָמְרוּ חֲכָמִים רֹב בְּגֵזֶל מִעוּט בַּעֲרָיוֹת וְהַכּל בַּאֲבַק לָשׁוֹן הָרַע:","לְפִיכָךְ רָאוּי לוֹ לְאָדָם לָכֹף יִצְרוֹ בְּדָבָר זֶה וּלְהַרְגִּיל עַצְמוֹ בִּקְדֻשָּׁה יְתֵרָה וּבְמַחֲשָׁבָה טְהוֹרָה וּבְדֵעָה נְכוֹנָה כְּדֵי לְהִנָּצֵל מֵהֶן. וְיִזָּהֵר מִן הַיִּחוּד שֶׁהוּא הַגּוֹרֵם הַגָּדוֹל. גְּדוֹלֵי הַחֲכָמִים הָיוּ אוֹמְרִים לְתַלְמִידֵיהֶם הִזָּהֲרוּ בִּי מִפְּנֵי בִּתִּי הִזָּהֲרוּ בִּי מִפְּנֵי כַּלָּתִי. כְּדֵי לְלַמֵּד לְתַלְמִידֵיהֶם שֶׁלֹּא יִתְבַּיְּשׁוּ מִדָּבָר זֶה וְיִתְרַחֲקוּ מִן הַיִּחוּד:","וְכֵן יִנְהֹג לְהִתְרַחֵק מִן הַשְּׂחוֹק וּמִן הַשִּׁכְרוּת וּמִדִּבְרֵי עֲגָבִים שֶׁאֵלּוּ גּוֹרְמִין גְּדוֹלִים וְהֵם מַעֲלוֹת שֶׁל עֲרָיוֹת. וְלֹא יֵשֵׁב בְּלֹא אִשָּׁה שֶׁמִּנְהָג זֶה גּוֹרֵם לְטָהֳרָה יְתֵרָה. גְּדוֹלָה מִכָּל זֹאת אָמְרוּ יַפְנֶה עַצְמוֹ וּמַחֲשַׁבְתּוֹ לְדִבְרֵי תּוֹרָה וְיַרְחִיב דַּעְתּוֹ בַּחָכְמָה שֶׁאֵין מַחְשֶׁבֶת עֲרָיוֹת מִתְגַּבֶּרֶת אֶלָּא בְּלֵב פָּנוּי מִן הַחָכְמָה. וּבַחָכְמָה הוּא אוֹמֵר (משלי ה יט) \"אַיֶּלֶת אֲהָבִים וְיַעֲלַת חֵן דַּדֶּיהָ יְרַוֵּךָ בְכָל עֵת בְּאַהֲבָתָהּ תִּשְׁגֶּה תָמִיד\":"],"Mishneh Torah, Foreign Worship and Customs of the Nations 2":["עִקַּר הַצִּוּוּי בַּעֲבוֹדַת כּוֹכָבִים שֶׁלֹּא לַעֲבֹד אֶחָד מִכָּל הַבְּרוּאִים לֹא מַלְאָךְ וְלֹא גַּלְגַּל וְלֹא כּוֹכָב וְלֹא אֶחָד מֵאַרְבָּעָה הַיְסוֹדוֹת וְלֹא אֶחָד מִכָּל הַנִּבְרָאִים מֵהֶן. וְאַף עַל פִּי שֶׁהָעוֹבֵד יוֹדֵעַ שֶׁה' הוּא הָאֱלֹהִים וְהוּא עוֹבֵד הַנִּבְרָא הַזֶּה עַל דֶּרֶךְ שֶׁעָבַד אֱנוֹשׁ וְאַנְשֵׁי דּוֹרוֹ תְּחִלָּה הֲרֵי זֶה עוֹבֵד כּוֹכָבִים. וְעִנְיָן זֶה הוּא שֶׁהִזְהִירָה תּוֹרָה עָלָיו וְאָמְרָה (דברים ד יט) \"וּפֶן תִּשָּׂא עֵינֶיךָ הַשָּׁמַיְמָה וְרָאִיתָ אֶת הַשֶּׁמֶשׁ\" וְגוֹ' (דברים ד יט) \"אֲשֶׁר חָלַק ה' אֱלֹהֶיךָ אֹתָם לְכָל הָעַמִּים\". כְּלוֹמַר שֶׁמָּא תָּשׁוּט בְּעֵין לִבְּךָ וְתִרְאֶה שֶׁאֵלּוּ הֵן הַמַּנְהִיגִים אֶת הָעוֹלָם וְהֵם שֶׁחָלַק ה' אוֹתָם לְכָל הָעוֹלָם לִהְיוֹת חַיִּים וְהוֹוִים וְאֵינָם נִפְסָדִים כְּמִנְהָגוֹ שֶׁל עוֹלָם וְתֹאמַר שֶׁרָאוּי לְהִשְׁתַּחֲווֹת לָהֶם וּלְעָבְדָן. וּבָעִנְיָן הַזֶּה צִוָּה וְאָמַר (דברים יא טז) \"הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה לְבַבְכֶם\". כְּלוֹמַר שֶׁלֹּא תִּטְּעוּ בְּהִרְהוּר הַלֵּב לַעֲבֹד אֵלּוּ לִהְיוֹת סַרְסוּר בֵּינֵיכֶם וּבֵין הַבּוֹרֵא:","סְפָרִים רַבִּים חִבְּרוּ עוֹבְדֵי כּוֹכָבִים בַּעֲבוֹדָתָהּ הֵיאַךְ עִקַּר עֲבוֹדָתָהּ וּמַה מַּעֲשֶׂיהָ וּמִשְׁפָּטֶיהָ. צִוָּנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לִקְרוֹת בְּאוֹתָן הַסְּפָרִים כְּלָל וְלֹא נְהַרְהֵר בָּהּ וְלֹא בְּדָבָר מִדְּבָרֶיהָ. וַאֲפִלּוּ לְהִסְתַּכֵּל בִּדְמוּת הַצּוּרָה אָסוּר שֶׁנֶּאֱמַר (ויקרא יט ד) \"אַל תִּפְנוּ אֶל הָאֱלִילִים\". וּבָעִנְיָן הַזֶּה נֶאֱמַר (דברים יב ל) \"וּפֶן תִּדְרשׁ לֵאלֹהֵיהֶם לֵאמֹר אֵיכָה יַעַבְדוּ\", שֶׁלֹּא תִּשְׁאַל עַל דֶּרֶךְ עֲבוֹדָתָהּ הֵיאַךְ הִיא אַף עַל פִּי שֶׁאֵין אַתָּה עוֹבְדָהּ, שֶׁדָּבָר זֶה גּוֹרֵם לְהִפָּנוֹת אַחֲרֶיהָ וְלַעֲשׂוֹת כְּמָה שֶׁהֵן עוֹשִׂין שֶׁנֶּאֱמַר וְאֶעֱשֶׂה כֵּן גַּם אָנִי:","וְכָל הַלָּאוִין הָאֵלּוּ בְּעִנְיָן אֶחָד הֵן וְהוּא שֶׁלֹּא יִפְנֶה אַחַר עֲבוֹדַת כּוֹכָבִים וְכָל הַנִּפְנֶה אַחֲרֶיהָ בְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בּוֹ מַעֲשֶׂה הֲרֵי זֶה לוֹקֶה. וְלֹא עֲבוֹדַת כּוֹכָבִים בִּלְבַד הוּא שֶׁאָסוּר לְהִפָּנוֹת אַחֲרֶיהָ בְּמַחֲשָׁבָה אֶלָּא כָּל מַחֲשָׁבָה שֶׁהוּא גּוֹרֵם לוֹ לָאָדָם לַעֲקֹר עִקָּר מֵעִקְּרֵי הַתּוֹרָה מֻזְהָרִין אָנוּ שֶׁלֹּא לְהַעֲלוֹתָהּ עַל לִבֵּנוּ וְלֹא נַסִּיחַ דַּעְתֵּנוּ לְכָךְ וְנַחְשֹׁב וְנִמָּשֵׁךְ אַחַר הִרְהוּרֵי הַלֵּב. מִפְּנֵי שֶׁדַּעְתּוֹ שֶׁל אָדָם קְצָרָה וְלֹא כָּל הַדֵּעוֹת יְכוֹלִין לְהַשִּׂיג הָאֱמֶת עַל בֻּרְיוֹ. וְאִם יִמָּשֵׁךְ כָּל אָדָם אַחַר מַחְשְׁבוֹת לִבּוֹ נִמְצָא מַחֲרִיב אֶת הָעוֹלָם לְפִי קֹצֶר דַּעְתּוֹ. כֵּיצַד. פְּעָמִים יָתוּר אַחַר עֲבוֹדַת כּוֹכָבִים וּפְעָמִים יַחְשֹׁב בְּיִחוּד הַבּוֹרֵא שֶׁמָּא הוּא שֶׁמָּא אֵינוֹ. מַה לְּמַעְלָה וּמַה לְּמַטָּה מַה לְּפָנִים וּמַה לְּאָחוֹר. וּפְעָמִים בַּנְּבוּאָה שֶׁמָּא הִיא אֱמֶת שֶׁמָּא הִיא אֵינָהּ. וּפְעָמִים בַּתּוֹרָה שֶׁמָּא הִיא מִן הַשָּׁמַיִם שֶׁמָּא אֵינָהּ. וְאֵינוֹ יוֹדֵעַ הַמִּדּוֹת שֶׁיָּדִין בָּהֶן עַד שֶׁיֵּדַע הָאֱמֶת עַל בֻּרְיוֹ וְנִמְצָא יוֹצֵא לִידֵי מִינוּת. וְעַל עִנְיָן זֶה הִזְהִירָה תּוֹרָה וְנֶאֱמַר בָּהּ (במדבר טו לט) \"וְלֹא תָתֻרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר אַתֶּם זֹנִים\". כְּלוֹמַר לֹא יִמָּשֵׁךְ כָּל אֶחָד מִכֶּם אַחַר דַּעְתּוֹ הַקְּצָרָה וִידַמֶּה שֶׁמַּחֲשַׁבְתּוֹ מַשֶּׂגֶת הָאֱמֶת. כָּךְ אָמְרוּ חֲכָמִים (גמרא ברכות יב ב) \"אַחֲרֵי לְבַבְכֶם זוֹ מִינוּת\" וְאַחֲרֵי עֵינֵיכֶם זוֹ זְנוּת. וְלָאו זֶה אַף עַל פִּי שֶׁהוּא גּוֹרֵם לָאָדָם לְטָרְדוֹ מִן הָעוֹלָם הַבָּא אֵין בּוֹ מַלְקוֹת:","מִצְוַת עֲבוֹדַת כּוֹכָבִים כְּנֶגֶד הַמִּצְוֹת כֻּלָּן הִיא שֶׁנֶּאֱמַר (במדבר טו כב) \"וְכִי תִשְׁגּוּ וְלֹא תַעֲשׂוּ אֵת כָּל הַמִּצְוֹת\" וְגוֹ' וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבַּעֲבוֹדַת כּוֹכָבִים הַכָּתוּב מְדַבֵּר. הָא לָמַדְתָּ שֶׁכָּל הַמּוֹדֶה בַּעֲבוֹדַת כּוֹכָבִים כּוֹפֵר בְּכָל הַתּוֹרָה כֻּלָּהּ וּבְכָל הַנְּבִיאִים וּבְכָל מַה שֶּׁנִּצְטַוּוּ הַנְּבִיאִים מֵאָדָם וְעַד סוֹף הָעוֹלָם שֶׁנֶּאֱמַר (במדבר טו כג) \"מִן הַיּוֹם אֲשֶׁר צִוָּה ה' וָהָלְאָה לְדֹרֹתֵיכֶם\". וְכָל הַכּוֹפֵר בַּעֲבוֹדַת כּוֹכָבִים מוֹדֶה בְּכָל הַתּוֹרָה כֻּלָּהּ וּבְכָל הַנְּבִיאִים וּבְכָל מַה שֶּׁנִּצְטַוּוּ הַנְּבִיאִים מֵאָדָם וְעַד סוֹף הָעוֹלָם וְהוּא עִקַּר כָּל הַמִּצְוֹת כֻּלָּן:","יִשְׂרָאֵל שֶׁעָבַד עֲבוֹדַת כּוֹכָבִים הֲרֵי הוּא כְּעוֹבֵד כּוֹכָבִים לְכָל דְּבָרָיו וְאֵינוֹ כְּיִשְׂרָאֵל שֶׁעוֹבֵר עֲבֵרָה שֶׁיֵּשׁ בָּהּ סְקִילָה. מוּמָר לַעֲבוֹדַת כּוֹכָבִים הֲרֵי הוּא מוּמָר לְכָל הַתּוֹרָה כֻּלָּהּ. וְכֵן הָאֶפִּיקוֹרְסִים מִיִּשְׂרָאֵל אֵינָן כְּיִשְׂרָאֵל לְדָבָר מִן הַדְּבָרִים וְאֵין מְקַבְּלִים אוֹתָם בִּתְשׁוּבָה לְעוֹלָם שֶׁנֶּאֱמַר (משלי ב יט) \"כָּל בָּאֶיהָ לֹא יְשׁוּבוּן וְלֹא יַשִּׂיגוּ אָרְחוֹת חַיִּים\". וְהָאֶפִּיקוֹרְסִים הֵם הַתָּרִים אַחַר מַחְשְׁבוֹת לִבָּם בְּסִכְלוּת דְּבָרִים שֶׁאָמַרְנוּ עַד שֶׁנִּמְצְאוּ עוֹבְרִים עַל גּוּפֵי תּוֹרָה לְהַכְעִיס בִּשְׁאָט נֶפֶשׁ בְּיָד רָמָה וְאוֹמְרִים שֶׁאֵין בָּזֶה עָוֹן. וְאָסוּר לְסַפֵּר עִמָּהֶן וּלְהָשִׁיב עֲלֵיהֶן תְּשׁוּבָה כְּלָל שֶׁנֶּאֱמַר (משלי ה ח) \"וְאַל תִּקְרַב אֶל פֶּתַח בֵּיתָהּ\". וּמַחֲשָׁבָה שֶׁל אֶפִּיקוֹרוֹס לַעֲבוֹדַת כּוֹכָבִים:","כָּל הַמּוֹדֶה בַּעֲבוֹדַת כּוֹכָבִים שֶׁהִיא אֱמֶת אַף עַל פִּי שֶׁלֹּא עֲבָדָהּ הֲרֵי זֶה מְחָרֵף וּמְגַדֵּף אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא. וְאֶחָד הָעוֹבֵד עֲבוֹדַת כּוֹכָבִים וְאֶחָד הַמְגַדֵּף אֶת ה' שֶׁנֶּאֱמַר (במדבר טו ל) \"וְהַנֶּפֶשׁ אֲשֶׁר תַּעֲשֶׂה בְּיָד רָמָה מִן הָאֶזְרָח וּמִן הַגֵּר אֶת ה' הוּא מְגַדֵּף\". לְפִיכָךְ תּוֹלִין עוֹבֵד עֲבוֹדַת כּוֹכָבִים כְּמוֹ שֶׁתּוֹלִין אֶת הַמְגַדֵּף וּשְׁנֵיהֶם נִסְקָלִין. וּמִפְּנֵי זֶה כָּלַלְתִּי דִּין הַמְגַדֵּף בְּהִלְכוֹת עֲבוֹדַת כּוֹכָבִים שֶׁשְּׁנֵיהֶם כּוֹפְרִים בָּעִקָּר הֵם:","וְאֵלּוּ הֵן דִּינֵי הַמְגַדֵּף. אֵין הַמְגַדֵּף חַיָּב סְקִילָה עַד שֶׁיְּפָרֵשׁ אֶת הַשֵּׁם הַמְיֻחָד שֶׁל אַרְבַּע אוֹתִיּוֹת שֶׁהוּא אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוּ\"ד וִיבָרֵךְ אוֹתוֹ בְּשֵׁם מִן הַשֵּׁמוֹת שֶׁאֵינָם נִמְחָקִים שֶׁנֶּאֱמַר (ויקרא כד טז) \"וְנֹקֵב שֵׁם ה'\", עַל הַשֵּׁם הַמְיֻחָד חַיָּב סְקִילָה וְעַל שְׁאָר הַכִּנּוּיִים בְּאַזְהָרָה. וְיֵשׁ מִי שֶׁמְּפָרֵשׁ שֶׁאֵינוֹ חַיָּב אֶלָּא עַל שֵׁם יוּ\"ד הֵ\"א וָא\"ו הֵ\"א וַאֲנִי אוֹמֵר שֶׁעַל שְׁנֵיהֶם הוּא נִסְקָל:","אַזְהָרָה שֶׁל מְגַדֵּף מִנַּיִן שֶׁנֶּאֱמַר (שמות כב כז) \"אֱלֹהִים לֹא תְקַלֵּל\". בְּכָל יוֹם וָיוֹם בּוֹדְקִין אֶת הָעֵדִים בְּכִנּוּיִים יַכֶּה יוֹסִי אֶת יוֹסִי. נִגְמַר הַדִּין מוֹצִיאִין אֶת כָּל אָדָם לַחוּץ וְשׁוֹאֲלִים אֶת הַגָּדוֹל שֶׁבָּעֵדִים וְאוֹמְרִים לוֹ אֱמֹר מַה שֶּׁשָּׁמַעְתָּ בְּפֵרוּשׁ וְהוּא אוֹמֵר וְהַדַּיָּנִים עוֹמְדִים עַל רַגְלֵיהֶם וְקוֹרְעִין וְלֹא מְאַחִין. וְהָעֵד הַשֵּׁנִי אוֹמֵר אַף אֲנִי כְּמוֹתוֹ שָׁמַעְתִּי. וְאִם הָיוּ עֵדִים רַבִּים צָרִיךְ כָּל אֶחָד וְאֶחָד מֵהֶן לוֹמַר כָּזֶה שָׁמַעְתִּי:","מְגַדֵּף שֶׁחָזַר בּוֹ בְּתוֹךְ כְּדֵי דִּבּוּר אֵינוֹ כְּלוּם אֶלָּא כֵּיוָן שֶׁגִּדֵּף בְּעֵדִים נִסְקָל. מִי שֶׁגִּדֵּף אֶת הַשֵּׁם בְּשֵׁם עֲבוֹדַת כּוֹכָבִים קַנָּאִים פּוֹגְעִים בּוֹ וְהוֹרְגִים אוֹתוֹ. וְאִם לֹא הֲרָגוּהוּ קַנָּאִים וּבָא לְבֵית דִּין אֵינוֹ נִסְקָל עַד שֶׁיְּבָרֵךְ בְּשֵׁם מִן הַשֵּׁמוֹת הַמְיֻחָדִים:","כָּל הַשּׁוֹמֵעַ בִּרְכַּת הַשֵּׁם חַיָּב לִקְרֹעַ וַאֲפִלּוּ עַל בִּרְכַּת הַכִּנּוּיִין חַיָּב לִקְרֹעַ וְהוּא שֶׁיִּשְׁמָעֶנָּה מִיִּשְׂרָאֵל. אֶחָד הַשּׁוֹמֵעַ וְאֶחָד הַשּׁוֹמֵעַ מִפִּי הַשּׁוֹמֵעַ חַיָּב לִקְרֹעַ. אֲבָל הַשּׁוֹמֵעַ מִפִּי הָעוֹבֵד כּוֹכָבִים אֵינוֹ חַיָּב לִקְרֹעַ. וְלֹא קָרְעוּ אֶלְיָקִים וְשֶׁבְנָא אֶלָּא מִפְּנֵי שֶׁרַבְשָׁקֵה הָיָה יִשְׂרָאֵל מוּמָר. כָּל הָעֵדִים וְהַדַּיָּנִים סוֹמְכִים אֶת יְדֵיהֶם אֶחָד אֶחָד עַל רֹאשׁ הַמְגַדֵּף וְאוֹמֵר לוֹ דָּמְךָ בְּרֹאשְׁךָ שֶׁאַתָּה גָּרַמְתָּ לְךָ. וְאֵין בְּכָל הֲרוּגֵי בֵּית דִּין מִי שֶׁסּוֹמְכִים עָלָיו אֶלָּא מְגַדֵּף בִּלְבַד שֶׁנֶּאֱמַר וְסָמְכוּ כָל הַשֹּׁמְעִים אֶת יְדֵיהֶם:"],"Mishneh Torah, Foundations of the Torah 4":["אַרְבָּעָה גּוּפִים הַלָּלוּ שֶׁהֵם אֵשׁ וְרוּחַ וּמַיִם וְאֶרֶץ הֵם יְסוֹדוֹת כָּל הַנִּבְרָאִים לְמַטָּה מִן הָרָקִיעַ. וְכָל שֶׁיִּהְיֶה מֵאָדָם וּמִבְּהֵמָה וְעוֹף וְרֶמֶשׂ וְדָג וְצֶמַח וּמַתֶּכֶת וַאֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת וּשְׁאָר אַבְנֵי בִּנְיָן וְהָרִים וְגוּשֵׁי עָפָר הַכּל גָּלְמָן מְחֻבָּר מֵאַרְבָּעָה יְסוֹדוֹת הַלָּלוּ. נִמְצְאוּ כָּל הַגּוּפִים שֶׁלְּמַטָּה מִן הָרָקִיעַ חוּץ מֵאַרְבָּעָה יְסוֹדוֹת הָאֵלּוּ מְחֻבָּרִים מִגֹּלֶם וְצוּרָה. וְגֹלֶם שֶׁלָּהֶם מְחֻבָּר מֵאַרְבָּעָה יְסוֹדוֹת הָאֵלּוּ. אֲבָל כָּל אֶחָד מֵאַרְבָּעָה הַיְסוֹדוֹת אֵינוֹ מְחֻבָּר אֶלָּא מִגֹּלֶם וְצוּרָה בִּלְבַד:","דֶּרֶךְ הָאֵשׁ וְהָרוּחַ לִהְיוֹת מַהֲלָכָם מִמַּטָּה מִטַּבּוּר הָאָרֶץ לְמַעְלָה כְּלַפֵּי הָרָקִיעַ. וְדֶרֶךְ הַמַּיִם וְהָאָרֶץ לִהְיוֹת מַהֲלָכָם מִתַּחַת הָרָקִיעַ לְמַטָּה עַד לָאֶמְצַע. שֶׁאֶמְצַע הָרָקִיעַ הוּא הַמַּטָּה שֶׁאֵין לְמַטָּה מִמֶּנּוּ. וְאֵין הִלּוּכָם לֹא בְּדַעְתָּם וְלֹא בְּחֶפְצָם אֶלָּא מִנְהָג שֶׁנִּקְבַּע בָּהֶן וְטֶבַע שֶׁנִּטְבַּע בָּהֶן. טֶבַע הָאֵשׁ חַם וְיָבֵשׁ וְהוּא קַל מִכֻּלָּם. וְהָרוּחַ חַם וְלַח. וְהַמַּיִם קָרִים וְלַחִים. וְהָאָרֶץ יְבֵשָׁה וְקָרָה. וְהִיא כְּבֵדָה מִכֻּלָּם וְהַמַּיִם קַלִּים מִמֶּנָּה לְפִיכָךְ נִמְצָאִים לְמַעְלָה עַל הָאָרֶץ. וְהָרוּחַ קַל מִן הַמַּיִם לְפִיכָךְ הוּא מְרַחֵף עַל פְּנֵי הַמַּיִם. וְהָאֵשׁ קַל מִן הָרוּחַ. וּמִפְּנֵי שֶׁהֵם יְסוֹדוֹת לְכָל גּוּפִים שֶׁתַּחַת הָרָקִיעַ יִמָּצֵא כָּל גּוּף וְגוּף מֵאָדָם וּבְהֵמָה וְחַיָּה וְעוֹף וְדַג וְצֶמַח וּמַתֶּכֶת וְאֶבֶן גָּלְמוֹ מְחֻבָּר מֵאֵשׁ וְרוּחַ וּמַיִם וְעָפָר. וְאַרְבַּעְתָּן יִתְעָרְבוּ בְּיַחַד וְיִשְׁתַּנּוּ כָּל אֶחָד מֵהֶם בְּעֵת הָעֵרוּב עַד שֶׁיִּמָּצֵא הַמְחֻבָּר מֵאַרְבַּעְתָּן אֵינוֹ דּוֹמֶה לְאֶחָד מֵהֶן כְּשֶׁהוּא לְבַדּוֹ. וְאֵין בַּמְעֹרָב מֵהֶן אֲפִלּוּ חֵלֶק אֶחָד שֶׁהוּא אֵשׁ בִּפְנֵי עַצְמוֹ אוֹ מַיִם בִּפְנֵי עַצְמָן אוֹ אֶרֶץ בִּפְנֵי עַצְמָהּ אוֹ רוּחַ בִּפְנֵי עַצְמָהּ אֶלָּא הַכּל נִשְׁתַּנּוּ וְנַעֲשׂוּ גּוּף אֶחָד. וְכָל גּוּף וְגוּף הַמְחֻבָּר מֵאַרְבַּעְתָּן יִמָּצֵא בּוֹ קֹר וְחֹם לַח וְיָבֵשׁ כְּאֶחָד. אֲבָל יֵשׁ מֵהֶם גּוּפִים שֶׁיִּהְיֶה בָּהֶם חָזְקָה מִיסוֹד הָאֵשׁ כְּמוֹ בַּעֲלֵי נֶפֶשׁ חַיָּה. לְפִיכָךְ יֵרָאֶה בָּהֶם הַחֹם יָתֵר. וְיֵשׁ מֵהֶן גּוּפִין שֶׁיִּהְיֶה בָּהֶן חָזְקָה מִיסוֹד הָאָרֶץ כְּמוֹ הָאֲבָנִים. לְפִיכָךְ יֵרָאֶה בָּהֶם הַיֹּבֶשׁ הַרְבֵּה. וְיֵשׁ מֵהֶן גּוּפִין שֶׁיִּהְיֶה בָּהֶן חָזְקָה מִיסוֹד הַמַּיִם. לְפִיכָךְ יֵרָאֶה בָּהֶם הַלַּח יָתֵר. וְעַל הַדֶּרֶךְ הַזֶּה יִמָּצֵא גּוּף חַם יֶתֶר מִגּוּף אַחֵר חַם. וְגוּף יָבֵשׁ יֶתֶר מִגּוּף אַחֵר יָבֵשׁ. וְכֵן יִמָּצְאוּ גּוּפִים שֶׁיֵּרָאֶה בָּהֶן הַקֹּר בִּלְבַד. וְגוּפִים יֵרָאֶה בָּהֶן הַלַּח בִּלְבַד. וְגוּפִים יֵרָאֶה בָּהֶן הַקֹּר וְהַיֹּבֶשׁ כְּאֶחָד בְּשָׁוֶה. אוֹ הַקֹּר וְהַלַּח כְּאֶחָד בְּשָׁוֶה. אוֹ הַחֹם וְהַיֹּבֶשׁ כְּאֶחָד בְּשָׁוֶה. אוֹ הַחֹם וְהַלַּח כְּאֶחָד בְּשָׁוֶה. לְפִי רֹב הַיְסוֹד שֶׁהָיָה בְּעִקַּר הַתַּעֲרֹבֶת יֵרָאֶה מַעֲשֵׂה אוֹתוֹ הַיְסוֹד וְטִבְעוֹ בַּגּוּף הַמְעֹרָב:","וְכָל הַמְחֻבָּר מֵאַרְבָּעָה יְסוֹדוֹת אֵלּוּ הוּא נִפְרָד בַּסּוֹף. יֵשׁ שֶׁהוּא נִפְרָד לְאַחַר יָמִים אֲחָדִים. וְיֵשׁ שֶׁהוּא נִפְרָד לְאַחַר שָׁנִים רַבּוֹת. וְכָל שֶׁנִּתְחַבֵּר מֵהֶם אִי אֶפְשָׁר שֶׁלֹּא יִפָּרֵד לָהֶן. אֲפִלּוּ הַזָּהָב וְהָאֹדֶם אִי אֶפְשָׁר שֶׁלֹּא יִפָּסֵד וְיַחֲזֹר לִיסוֹדוֹתָיו. וְיָשׁוּב מִקְצָתוֹ לָאֵשׁ. וּמִקְצָתוֹ לַמַּיִם. וּמִקְצָתוֹ לָרוּחַ. וּמִקְצָתוֹ לָאָרֶץ:","הוֹאִיל וְכָל הַנִּפְסָד יִפָּרֵד לִיסוֹדוֹת אֵלּוּ לָמָּה נֶאֱמַר לָאָדָם (בראשית ג יט) \"וְאֶל עָפָר תָּשׁוּב\". לְפִי שֶׁרֹב בִּנְיָנוֹ מִן הֶעָפָר. וְלֹא כָּל הַנִּפְסָד כְּשֶׁיִּפָּסֵד מִיָּד יַחֲזֹר לְאַרְבָּעָה הַיְסוֹדוֹת. אֶלָּא יִפָּסֵד וְיַחֲזֹר לְדָבָר אַחֵר וְדָבָר אַחֵר לְדָבָר אַחֵר וְסוֹף הַדְּבָרִים יַחֲזֹר לַיְסוֹדוֹת וְנִמְצְאוּ כָּל הַדְּבָרִים חוֹזְרִין חֲלִילָה:","אַרְבָּעָה יְסוֹדוֹת הָאֵלּוּ מִשְׁתַּנִּים זֶה לָזֶה תָּמִיד בְּכָל יוֹם וּבְכָל שָׁעָה מִקְצָתָן לֹא כָּל גּוּפָן. כֵּיצַד. מִקְצָת הָאָרֶץ הַקְּרוֹבָה מִן הַמַּיִם מִשְׁתַּנֵּית וּמִתְפּוֹרֶרֶת וְנַעֲשֵׂית מַיִם. וְכֵן מִקְצָת הַמַּיִם הַסְּמוּכִים לָרוּחַ מִשְׁתַּנִּין וּמִתְמַסְמְסִין וְהֹוִין רוּחַ. וְכֵן הָרוּחַ מִקְצָתוֹ הַסָּמוּךְ לָאֵשׁ מִשְׁתַּנֶּה וּמִתְחוֹלֵל וְנַעֲשֶׂה אֵשׁ. וְכֵן הָאֵשׁ מִקְצָתָהּ הַסָּמוּךְ לָרוּחַ מִתְחוֹלֵל מִשְׁתַּנֶּה וּמִתְכַּנֵּס וְנַעֲשֶׂה רוּחַ. וְכֵן הָרוּחַ מִקְצָתוֹ הַסָּמוּךְ לַמַּיִם מִשְׁתַּנֶּה וּמִתְכַּנֵּס וְנַעֲשֶׂה מַיִם. וְכֵן הַמַּיִם מִקְצָתוֹ הַסָּמוּךְ לָאָרֶץ מִשְׁתַּנֶּה וּמִתְכַּנֵּס וְנַעֲשֶׂה אֶרֶץ. וְשִׁנּוּי זֶה מְעַט מְעַט וּלְפִי אֹרֶךְ הַיָּמִים. וְאֵין כָּל הַיְסוֹד מִשְׁתַּנֶּה עַד שֶׁיֵּעָשֶׂה כָּל הַמַּיִם רוּחַ אוֹ כָּל הָרוּחַ אֵשׁ. שֶׁאִי אֶפְשָׁר שֶׁיִּבָּטֵל אֶחָד מִן הַיְסוֹדוֹת הָאַרְבָּעָה. אֶלָּא מִקְצָת יִשְׁתַּנֶּה מֵאֵשׁ לְרוּחַ וּמִקְצָת יִשְׁתַּנֶּה מֵרוּחַ לְאֵשׁ. וְכֵן בֵּין כָּל אֶחָד וַחֲבֵרוֹ יִמָּצֵא הַשִּׁנּוּי בֵּין אַרְבַּעְתָּן וְחוֹזְרוֹת חֲלִילָה לְעוֹלָם:","וְשִׁנּוּי זֶה יִהְיֶה בִּסְבִיבַת הַגַּלְגַּל וּמִסְּבִיבָתוֹ יִתְחַבְּרוּ אַרְבַּעְתָּן וְיִהְיֶה מֵהֶן שְׁאָר גָּלְמֵי בְּנֵי אָדָם וְנֶפֶשׁ חַיָּה צֶמַח וְאֶבֶן וּמַתֶּכֶת. וְהָאֵל נוֹתֵן לְכָל גֹּלֶם וְגֹלֶם צוּרָה רְאוּיָה לוֹ עַל יְדֵי מַלְאָךְ הָעֲשִׂירִי שֶׁהִיא הַצּוּרָה הַנִּקְרֵאת אִישִׁים:","לְעוֹלָם אֵין אַתָּה רוֹאֶה גֹּלֶם בְּלֹא צוּרָה אוֹ צוּרָה בְּלֹא גֹּלֶם. אֶלָּא לֵב הָאָדָם הוּא שֶׁמְּחַלֵּק גּוּף הַנִּמְצָא בְּדַעְתּוֹ וְיוֹדֵעַ שֶׁהוּא מְחֻבָּר מִגֹּלֶם וְצוּרָה. וְיוֹדֵעַ שֶׁיֵּשׁ שָׁם גּוּפִים שֶׁגָּלְמָם מְחֻבָּר מֵאַרְבַּעַת הַיְסוֹדוֹת. וְגוּפִים שֶׁגָּלְמָם פָּשׁוּט וְאֵינוֹ מְחֻבָּר מִגֹּלֶם אַחֵר. וְהַצּוּרוֹת שֶׁאֵין לָהֶם גֹּלֶם אֵינָן נִרְאִין לָעַיִן אֶלָּא בְּעֵין הַלֵּב הֵן יְדוּעִין. כְּמוֹ שֶׁיָּדַעְנוּ אֲדוֹן הַכּל בְּלֹא רְאִיַּת עַיִן:","נֶפֶשׁ כָּל בָּשָׂר הִיא צוּרָתוֹ שֶׁנָּתַן לוֹ הָאֵל וְהַדַּעַת הַיְתֵרָה הַמְּצוּיָה בְּנַפְשׁוֹ שֶׁל אָדָם הִיא צוּרַת הָאָדָם הַשָּׁלֵם בְּדַעְתּוֹ. וְעַל צוּרָה זוֹ נֶאֱמַר בַּתּוֹרָה נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ כְּלוֹמַר שֶׁתִּהְיֶה לוֹ צוּרָה הַיּוֹדַעַת וּמַשֶּׂגֶת הַדֵּעוֹת שֶׁאֵין לָהֶם גֹּלֶם כְּמוֹ הַמַּלְאָכִים שֶׁהֵם צוּרָה בְּלֹא גֹּלֶם עַד שֶׁיִּדְמֶה לָהֶן. וְאֵינוֹ אוֹמֵר עַל צוּרָה זוֹ הַנִּכֶּרֶת לָעֵינַיִם שֶׁהִיא הַפֶּה וְהַחֹטֶם וְהַלְּסָתוֹת וּשְׁאָר רשֶׁם הַגּוּף שֶׁזּוֹ תֹּאַר שְׁמָהּ. וְאֵינָהּ הַנֶּפֶשׁ הַמְּצוּיָה לְכָל נֶפֶשׁ חַיָּה שֶׁבָּהּ אוֹכֵל וְשׁוֹתֶה וּמוֹלִיד וּמַרְגִּישׁ וּמְהַרְהֵר. אֶלָּא הַדֵּעָה שֶׁהִיא צוּרַת הַנֶּפֶשׁ וּבְצוּרַת הַנֶּפֶשׁ הַכָּתוּב מְדַבֵּר בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. וּפְעָמִים רַבּוֹת תִּקָּרֵא זֹאת הַצּוּרָה נֶפֶשׁ וְרוּחַ. וּלְפִיכָךְ צָרִיךְ לְהִזָּהֵר בִּשְׁמוֹתָן שֶׁלֹּא יִטְעֶה אָדָם בָּהֶן. וְכָל שֵׁם וְשֵׁם יִלָּמֵד מֵעִנְיָנוֹ:","אֵין צוּרַת הַנֶּפֶשׁ הַזֹּאת מְחֻבֶּרֶת מִן הַיְסוֹדוֹת כְּדֵי שֶׁתִּפָּרֵד לָהֶם, וְאֵינָהּ מִכֹּחַ הַנְּשָׁמָה עַד שֶׁתְּהֵא צְרִיכָה לַנְּשָׁמָה כְּמוֹ שֶׁהַנְּשָׁמָה צְרִיכָה לַגּוּף. אֶלָּא מֵאֵת ה' מִן הַשָּׁמַיִם הִיא. לְפִיכָךְ כְּשֶׁיִּפָּרֵד הַגֹּלֶם שֶׁהוּא מְחֻבָּר מִן הַיְסוֹדוֹת וְתֹאבַד הַנְּשָׁמָה מִפְּנֵי שֶׁאֵינָהּ מְצוּיָה אֶלָּא עִם הַגּוּף וּצְרִיכָה לַגּוּף בְּכָל מַעֲשֶׂיהָ לֹא תִּכָּרֵת הַצּוּרָה הַזֹּאת. לְפִי שֶׁאֵינָהּ צְרִיכָה לַנְּשָׁמָה בְּמַעֲשֶׂיהָ. אֶלָּא יוֹדַעַת וּמַשֶּׂגֶת הַדֵּעוֹת הַפְּרוּדוֹת מִן הַגְּלָמִים וְיוֹדַעַת בּוֹרֵא הַכּל וְעוֹמֶדֶת לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. הוּא שֶׁאָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (קהלת יב ז) \"וְיָשֹׁב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ\":","כָּל הַדְּבָרִים הָאֵלּוּ שֶׁדִּבַּרְנוּ בְּעִנְיָן זֶה כְּמַר מִדְּלִי הֵם וּדְבָרִים עֲמֻקִּים הֵם. אֲבָל אֵינָם כְּעִנְיַן עֹמֶק פֶּרֶק רִאשׁוֹן וְשֵׁנִי. וּבֵאוּר כָּל אֵלּוּ הַדְּבָרִים שֶׁבְּפֶרֶק שְׁלִישִׁי וּרְבִיעִי הוּא הַנִּקְרָא מַעֲשֵׂה בְּרֵאשִׁית. וְכָךְ צִוּוּ הַחֲכָמִים הָרִאשׁוֹנִים שֶׁאֵין דּוֹרְשִׁין בַּדְּבָרִים הָאֵלּוּ בָּרַבִּים אֶלָּא לְאָדָם אֶחָד מוֹדִיעִין דְּבָרִים אֵלּוּ וּמְלַמְּדִין אוֹתָן:","וּמָה בֵּין עִנְיַן מַעֲשֵׂה מֶרְכָּבָה לְעִנְיַן מַעֲשֵׂה בְּרֵאשִׁית. שֶׁעִנְיַן מַעֲשֵׂה מֶרְכָּבָה אֲפִלּוּ לְאֶחָד אֵין דּוֹרְשִׁים בּוֹ אֶלָּא אִם כֵּן הָיָה חָכָם וּמֵבִין מִדַּעְתּוֹ מוֹסְרִין לוֹ רָאשֵׁי הַפְּרָקִים. וְעִנְיַן מַעֲשֵׂה בְּרֵאשִׁית מְלַמְּדִין אוֹתוֹ לְיָחִיד אַף עַל פִּי שֶׁאֵינוֹ מֵבִין אוֹתוֹ מִדַּעְתּוֹ וּמוֹדִיעִים אוֹתוֹ כָּל מַה שֶּׁיָּכוֹל לֵידַע מִדְּבָרִים אֵלּוּ. וְלָמָּה אֵין מְלַמְּדִין אוֹתוֹ לָרַבִּים. לְפִי שֶׁאֵין כָּל אָדָם יֵשׁ לוֹ דַּעַת רְחָבָה לְהַשִּׂיג פֵּרוּשׁ וּבֵאוּר כָּל הַדְּבָרִים עַל בֻּרְיָן:","בִּזְמַן שֶׁאָדָם מִתְבּוֹנֵן בַּדְּבָרִים הָאֵלּוּ וּמַכִּיר כָּל הַבְּרוּאִים מִמַּלְאָךְ וְגַלְגַּל וְאָדָם כַּיּוֹצֵא בּוֹ וְיִרְאֶה חָכְמָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל הַיְצוּרִים וְכָל הַבְּרוּאִים. מוֹסִיף אַהֲבָה לַמָּקוֹם וְתִצְמָא נַפְשׁוֹ וְיִכְמַהּ בְּשָׂרוֹ לֶאֱהֹב הַמָּקוֹם בָּרוּךְ הוּא. וְיִירָא וְיִפְחַד מִשִּׁפְלוּתוֹ וְדַלּוּתוֹ וְקַלּוּתוֹ כְּשֶׁיַּעֲרִיךְ עַצְמוֹ לְאֶחָד מֵהַגּוּפוֹת הַקְּדוֹשִׁים הַגְּדוֹלִים. וְכָל שֶׁכֵּן לְאַחַת מֵהַצּוּרוֹת הַטְּהוֹרוֹת הַנִּפְרָדוֹת מִן הַגְּלָמִים שֶׁלֹּא נִתְחַבְּרוּ בַּגֹּלֶם כְּלָל. וְיִמְצָא עַצְמוֹ שֶׁהוּא כִּכְלִי מָלֵא בּוּשָׁה וּכְלִמָּה רֵיק וְחָסֵר:","וְעִנְיְנֵי אַרְבָּעָה פְּרָקִים אֵלּוּ שֶׁבְּחָמֵשׁ מִצְוֹת הָאֵלּוּ הֵם שֶׁחֲכָמִים הָרִאשׁוֹנִים קוֹרְאִין אוֹתוֹ פַּרְדֵּס כְּמוֹ שֶׁאָמְרוּ אַרְבָּעָה נִכְנְסוּ לַפַּרְדֵּס. וְאַף עַל פִּי שֶׁגְּדוֹלֵי יִשְׂרָאֵל הָיוּ וַחֲכָמִים גְּדוֹלִים הָיוּ לֹא כֻּלָּם הָיָה בָּהֶן כֹּחַ לֵידַע וּלְהַשִּׂיג כָּל הַדְּבָרִים עַל בֻּרְיָן. וַאֲנִי אוֹמֵר שֶׁאֵין רָאוּי לְטַיֵּל בַּפַּרְדֵּס אֶלָּא מִי שֶׁנִּתְמַלֵּא כְּרֵסוֹ לֶחֶם וּבָשָׂר. וְלֶחֶם וּבָשָׂר הוּא לֵידַע הָאָסוּר וְהַמֻּתָּר וְכַיּוֹצֵא בָּהֶם מִשְּׁאָר הַמִּצְוֹת. וְאַף עַל פִּי שֶׁדְּבָרִים אֵלּוּ דָּבָר קָטָן קָרְאוּ אוֹתָן חֲכָמִים שֶׁהֲרֵי אָמְרוּ חֲכָמִים דָּבָר גָּדוֹל מַעֲשֵׂה מֶרְכָּבָה וְדָבָר קָטָן הֲוָיוֹת דְּאַבַּיֵּי וְרָבָא. אַף עַל פִּי כֵן רְאוּיִין הֵן לְהַקְדִּימָן. שֶׁהֵן מְיַשְּׁבִין דַּעְתּוֹ שֶׁל אָדָם תְּחִלָּה. וְעוֹד שֶׁהֵם הַטּוֹבָה הַגְּדוֹלָה שֶׁהִשְׁפִּיעַ הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשּׁוּב הָעוֹלָם הַזֶּה כְּדֵי לִנְחל חַיֵּי הָעוֹלָם הַבָּא. וְאֶפְשָׁר שֶׁיְּדָעֵם הַכּל קָטָן וְגָדוֹל אִישׁ וְאִשָּׁה בַּעַל לֵב רָחָב וּבַעַל לֵב קָצָר:"],"Mishneh Torah, Gifts to the Poor 3":["אֵין מַנִּיחִין אֶת הַפֵּאָה מִשָּׂדֶה עַל חֲבֶרְתָּהּ. כֵּיצַד. הָיוּ לוֹ שְׁתֵּי שָׂדוֹת לֹא יִקְצֹר אֶת הָאַחַת כֻּלָּהּ וְיַנִּיחַ בַּשְּׁנִיָּה פֵּאָה הָרְאוּיָה לִשְׁתֵּיהֶן. שֶׁנֶּאֱמַר (ויקרא כג כב) \"לֹא תְכַלֶּה פְּאַת שָׂדְךָ בְּקֻצְרֶךָ\" שֶׁיַּנִּיחַ בְּכָל אַחַת וְאַחַת פֵּאָה הָרְאוּיָה לָהּ. וְאִם הִנִּיחַ מִשָּׂדֶה עַל חֲבֶרְתָּהּ אֵינָהּ פֵּאָה:","הָיְתָה שָׂדֵהוּ זְרוּעָה כֻּלָּהּ מִין אֶחָד וְהָיָה נַחַל בְּתוֹךְ הַשָּׂדֶה אַף עַל פִּי שֶׁאֵינוֹ מוֹשֵׁךְ. אוֹ אַמַּת הַמַּיִם שֶׁאֵינוֹ יָכוֹל לִקְצֹר מַה שֶּׁבִּשְׁנֵי צְדָדֶיהָ כְּאַחַת וְהוּא שֶׁתִּהְיֶה מוֹשֶׁכֶת וּקְבוּעָה. הֲרֵי זֶה כִּשְׁתֵּי שָׂדוֹת וְנוֹתֵן פֵּאָה מִצַּד זֶה לְעַצְמוֹ וּמִצַּד זֶה לְעַצְמוֹ:","וְכֵן אִם הָיָה מַפְסִיק דֶּרֶךְ הַיָּחִיד שֶׁהוּא רָחָב אַרְבַּע אַמּוֹת אוֹ דֶּרֶךְ הָרַבִּים הָרָחָב שֵׁשׁ עֶשְׂרֵה אַמָּה. אֲבָל שְׁבִיל הַיָּחִיד וְהוּא פָּחוֹת מֵאַרְבַּע אוֹ שְׁבִיל הָרַבִּים פָּחוֹת מִשֵּׁשׁ עֶשְׂרֵה אַמָּה אִם הָיָה קָבוּעַ בִּימוֹת הַחַמָּה וּבִימוֹת הַגְּשָׁמִים מַפְסִיק. וְאִם אֵינוֹ קָבוּעַ בִּימוֹת הַגְּשָׁמִים אֵינוֹ מַפְסִיק אֶלָּא הֲרֵי הוּא כְּשָׂדֶה אַחַת:","הָיָה מַפְסִיק בָּהּ אֶרֶץ בּוּרָה שֶׁאֵינָה זְרוּעָה וְלֹא חֲרוּשָׁה. אוֹ אֶרֶץ נִירָה וְהִיא שֶׁנֶּחֶרְשָׁה וְלֹא נִזְרְעָה. אוֹ שֶׁהִפְסִיק בָּהּ זֶרַע אַחֵר. כְּגוֹן שֶׁהָיָה חִטִּים מִכָּאן וְחִטִּים מִכָּאן וּשְׂעוֹרִים בָּאֶמְצַע. אוֹ שֶׁקָּצַר בְּאֶמְצָעָהּ אֲפִלּוּ קֹדֶם שֶׁתָּבִיא שְׁלִישׁ וְחָרַשׁ מָקוֹם שֶׁקָּצַר. הֲרֵי זוֹ נִפְסֶקֶת לִשְׁתֵּי שָׂדוֹת. וְהוּא שֶׁיִּהְיֶה רֹחַב כָּל אֶחָד מֵאֵלּוּ כִּשְׁלֹשָׁה תְּלָמִים שֶׁל פָּתִיח וְהוּא פָּחוֹת מִבֵּית רֹבַע. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשָׂדֶה קְטַנָּה שֶׁהִיא חֲמִשִּׁים אַמָּה שֶׁל שְׁתֵּי אַמּוֹת אוֹ פָּחוֹת. אֲבָל אִם הָיְתָה יְתֵרָה עַל זוֹ אֵין הַבּוּר אוֹ הַנִּיר מַפְסִיקָהּ לִשְׁתַּיִם אֶלָּא אִם כֵּן הָיְתָה בּוֹ רֹחַב בֵּית רֹבַע. אֲבָל זֶרַע אַחֵר כָּל שֶׁהוּא מַפְסִיק בָּהּ:","אֲכָלָהּ גּוֹבַאי אוֹ קִרְסְמוּהָ נְמָלִים בְּאֶמְצָעָהּ אִם חָרַשׁ מָקוֹם שֶׁאָכְלוּ הֲרֵי זֶה מַפְסִיק:","הַזּוֹרֵעַ בָּהָר שֶׁאֵינוֹ כֻּלּוֹ שָׁוֶה אֶלָּא יֵשׁ בּוֹ תִּלִּים גְּבוֹהִים וּמְקוֹמוֹת מְקוֹמוֹת עֲמֻקּוֹת אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לַחֲרשׁ אוֹתוֹ כֻּלּוֹ וּלְזָרְעוֹ כְּאַחַת אֶלָּא נֶחְרָשׁ הַמָּקוֹם הַגָּבוֹהַּ בִּפְנֵי עַצְמוֹ וְהַנָּמוּךְ בִּפְנֵי עַצְמוֹ הֲרֵי זֶה כְּשָׂדֶה אַחַת וּמַנִּיחַ פֵּאָה אַחַת בְּסוֹף הָהָר עַל כָּל הָהָר:","מַדְרֵגוֹת שֶׁהֵן גְּבוֹהוֹת עֲשָׂרָה טְפָחִים נוֹתֵן פֵּאָה מִכָּל אַחַת וְאַחַת. וְאִם הָיוּ רָאשֵׁי שׁוּרוֹת מְעֹרָבִים נוֹתֵן מֵאַחַת עַל הַכּל. הָיוּ פָּחוֹת מֵעֲשָׂרָה אַף עַל פִּי שֶׁאֵין רָאשֵׁי הַשּׁוּרוֹת מְעֹרָבִין נוֹתֵן מֵאַחַת עַל הַכּל. הָיָה סֶלַע עַל פְּנֵי כָּל הַשָּׂדֶה. אִם עוֹקֵר הוּא אֶת הַמַּחְרֵשָׁה מִצַּד זֶה וְנוֹתְנָהּ מִצַּד זֶה מַפְסִיק. וְאִם לָאו אֵינוֹ מַפְסִיק:","הַזּוֹרֵעַ שָׂדֶה שֶׁיֵּשׁ בָּהּ אִילָנוֹת אַף עַל פִּי שֶׁהִיא מַלְבְּנוֹת מַלְבְּנוֹת בֵּין הָאִילָנוֹת וְאֵין כָּל הַזֶּרַע מְעֹרָב נוֹתֵן פֵּאָה אַחַת לְכָל הַשָּׂדֶה. שֶׁדָּבָר יָדוּעַ שֶׁשָּׂדֶה אַחַת הִיא וּמִפְּנֵי מְקוֹם הָאִילָנוֹת נֶחְלַק הַזֶּרַע:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיוּ הָאִילָנוֹת כָּל עֲשָׂרָה בְּתוֹךְ בֵּית סְאָה. אֲבָל אִם הָיוּ כָּל עֲשָׂרָה אִילָנוֹת בְּיוֹתֵר מִבֵּית סְאָה הֲרֵי זֶה נוֹתֵן פֵּאָה מִכָּל מַלְבֵּן וּמַלְבֵּן. שֶׁהֲרֵי הָאִילָנוֹת מְרֻחָקִים הַרְבֵּה וְלֹא מִפְּנֵי הָאִילָנוֹת זָרַע מַלְבְּנוֹת מַלְבְּנוֹת:","וְכֵן מַלְבְּנוֹת הַבְּצָלִים שֶׁבֵּין הַיָּרָק נוֹתֵן פֵּאָה אַחַת לְכָל הַבְּצָלִים. וְאַף עַל פִּי שֶׁהַיָּרָק מַבְדִּיל בֵּינֵיהֶן וּמְשִׂימָם מַלְבְּנוֹת מַלְבְּנוֹת:","שָׂדֶה שֶׁכֻּלָּה זְרוּעָה מִין אֶחָד וְכֵיוָן שֶׁהִתְחִילוּ בָּהּ מְקוֹמוֹת לִיבַשׁ עָקַר אוֹ תָּלַשׁ מַה שֶּׁיָּבַשׁ מִכָּאן וּמִכָּאן עַד שֶׁנִּשְׁאַר הַלַּח מְפֹרָד מַלְבְּנוֹת מַלְבְּנוֹת מְרֻחָקוֹת זוֹ מִזּוֹ. אִם הָיָה דֶּרֶךְ בְּנֵי אָדָם שָׁם לִזְרֹעַ מֵאוֹתוֹ הַמִּין עֲרוּגוֹת עֲרוּגוֹת כְּגוֹן שֶׁבֶת אוֹ חַרְדָּל הֲרֵי זֶה מַנִּיחַ פֵּאָה מִכָּל מַלְבֵּן וּמַלְבֵּן. שֶׁהָרוֹאֶה אוֹמֵר עֲרוּגוֹת עֲרוּגוֹת נִזְרְעוּ. וְאִם הָיָה מִין אֶחָד שֶּׁזּוֹרְעִין אוֹתוֹ שָׂדוֹת כְּגוֹן תְּבוּאָה וְקִטְנִיּוֹת נוֹתֵן אַחַת לַכּל:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה יָבֵשׁ מִכָּאן וְיָבֵשׁ מִכָּאן וְלַח בָּאֶמְצַע. אֲבָל לַח מִכָּאן וּמִכָּאן וְיָבֵשׁ בָּאֶמְצַע מַנִּיחַ מִן הַיָּבֵשׁ בִּפְנֵי עַצְמוֹ וּמִן הַלַּח בִּפְנֵי עַצְמוֹ:","שָׂדֶה שֶׁזְּרָעָהּ בְּצָלִים אוֹ פּוֹלִים אוֹ אֲפוּנִים וְכַיּוֹצֵא בָּהֶן וְהָיָה בְּדַעְתּוֹ לִמְכֹּר מִקְצָתָן לַחִין בַּשּׁוּק וּמַנִּיחַ מִקְצָת הַשָּׂדֶה יָבֵשׁ וְיַעֲשֶׂה מִמֶּנּוּ גֹּרֶן. חַיָּב לְהַנִּיחַ פֵּאָה לְזֶה שֶׁמּוֹכֵר לַח בִּפְנֵי עַצְמוֹ וְלָזֶה שֶׁקּוֹצֵר אוֹתוֹ יָבֵשׁ בִּפְנֵי עַצְמוֹ:","הַזּוֹרֵעַ אֶת שָׂדֵהוּ מִין אֶחָד אַף עַל פִּי שֶׁהוּא עוֹשֵׂהוּ שְׁתֵּי גֳּרָנוֹת מַנִּיחַ פֵּאָה אַחַת. זְרָעָהּ שְׁנֵי מִינִים אַף עַל פִּי שֶׁהוּא עוֹשֶׂה אוֹתָהּ גֹּרֶן אַחַת נוֹתֵן פֵּאָה לְמִין זֶה בִּפְנֵי עַצְמוֹ וּפֵאָה לְמִין זֶה בִּפְנֵי עַצְמוֹ:","זָרַע שְׁנֵי זְרָעִים מִמִּין אֶחָד כְּגוֹן שֶׁזְּרָעָהּ שְׁנֵי מִינֵי חִטִּים אוֹ שְׁנֵי מִינֵי שְׂעוֹרִים. אִם עֲשָׂאָן גֹּרֶן אַחַת נוֹתֵן פֵּאָה אַחַת. שְׁתֵּי גֳּרָנוֹת נוֹתֵן שְׁתֵּי פֵּאוֹת. וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי:","הָאַחִין שֶׁחָלְקוּ נוֹתְנִין שְׁתֵּי פֵּאוֹת. חָזְרוּ וְנִשְׁתַּתְּפוּ נוֹתְנִין פֵּאָה אַחַת. הַשֻּׁתָּפִין שֶׁקָּצְרוּ חֲצִי הַשָּׂדֶה וְאַחַר כָּךְ חָלְקוּ. זֶה שֶׁלָּקַח הַקָּצִיר אֵינוֹ מַפְרִישׁ כְּלוּם. וְזֶה שֶׁלָּקַח הַקָּמָה מַפְרִישׁ עַל הַחֵצִי שֶׁלָּקַח בִּלְבַד. חָזְרוּ וְנִשְׁתַּתְּפוּ וְקָצְרוּ הַחֵצִי הָאַחֵר בְּשֻׁתָּפוּת. כָּל אֶחָד מֵהֶן מַפְרִישׁ מֵחֶלְקוֹ שֶׁבַּקָּמָה עַל חֵלֶק חֲבֵרוֹ שֶׁבַּקָּמָה אֲבָל לֹא עַל הַחֵצִי שֶׁנִּקְצַר:","שָׂדֶה שֶׁהִגִּיעַ חֶצְיָהּ עַד שְׁלִישׁ וְחֶצְיָהּ לֹא הִגִּיעַ. וְהִתְחִיל וְקָצַר בְּחֵצִי שֶׁהִגִּיעַ חֶצְיוֹ וְאַחַר כָּךְ הֵבִיאָה כֻּלָּהּ שְׁלִישׁ וְאַחַר כָּךְ גָּמַר הַחֵצִי הָרִאשׁוֹן שֶׁהִגִּיעַ בַּתְּחִלָּה. מַפְרִישׁ מִן הָרִאשׁוֹן עַל הָאֶמְצָעִיִּים וּמִן הָאֶמְצָעִיִּים עַל הָרִאשׁוֹן וְעַל הָאַחֲרוֹן:","הַמּוֹכֵר מְקוֹמוֹת מְקוֹמוֹת מִשָּׂדֵהוּ לַאֲנָשִׁים הַרְבֵּה. אִם מָכַר כָּל הַשָּׂדֶה כָּל אֶחָד וְאֶחָד נוֹתֵן פֵּאָה אַחַת מֵחֶלְקוֹ שֶׁלָּקַח. וְאִם הִתְחִיל בַּעַל הַשָּׂדֶה לִקְצֹר וּמָכַר מִקְצָת וְשִׁיֵּר מִקְצָת. בַּעַל הַשָּׂדֶה נוֹתֵן פֵּאָה הָרְאוּיָה לַכּל. שֶׁכֵּיוָן שֶׁהִתְחִיל לִקְצֹר נִתְחַיֵּב בַּכּל. וְאִם מָכַר תְּחִלָּה מַפְרִישׁ הַלּוֹקֵחַ עַל מַה שֶּׁלָּקַח וּבַעַל הַשָּׂדֶה עַל מַה שֶּׁשִּׁיֵּר:","שְׂדֵה אִילָן אֵין מַפְסִיק בָּהּ אֶלָּא גָּדֵר גָּבוֹהַּ הַמַּבְדִּיל בֵּין הָאִילָנוֹת. אֲבָל אִם הָיָה הַגָּדֵר מַבְדִּיל מִלְּמַטָּה וְהַבַּדִּים וְהַפְּאֵרוֹת מְעֹרָבִין מִלְּמַעְלָה וְנוֹגְעִין בַּגָּדֵר עַל גַּבּוֹ הֲרֵי זֶה כְּשָׂדֶה אַחַת וְנוֹתֵן פֵּאָה לַכּל:","שְׁנַיִם שֶׁלָּקְחוּ אִילָן אֶחָד נוֹתְנִין מִמֶּנּוּ פֵּאָה אַחַת. לָקַח זֶה צְפוֹנוֹ וְזֶה דְּרוֹמוֹ זֶה נוֹתֵן פֵּאָה לְעַצְמוֹ וְזֶה נוֹתֵן פֵּאָה לְעַצְמוֹ:","הֶחָרוּבִין כָּל שֶׁאָדָם עוֹמֵד בְּצַד חָרוּב זֶה וַחֲבֵרוֹ עוֹמֵד בְּצַד חָרוּב זֶה וְרוֹאִין זֶה אֶת זֶה הֲרֵי הֵן כֻּלָּן שָׂדֶה אַחַת וּפֵאָה אַחַת לְכֻלָּן. הָיוּ שְׁנֵי הַצְּדָדִין רוֹאִין אֶת הָאֶמְצָעִיִּים וְאֵין הַצְּדָדִים רוֹאִין זֶה אֶת זֶה מַפְרִישׁ מִצַּד אֶחָד מִן הָרִאשׁוֹנִים עַל הָאֶמְצָעִיִּים וּמִן הָאֶמְצָעִיִּים עַל הָרִאשׁוֹנִים. אֲבָל לֹא יַפְרִישׁ מִצַּד זֶה עַל הַצַּד הָאַחֵר:","הַזֵּיתִים כָּל מַה שֶּׁיֵּשׁ מֵהֶן בְּרוּחַ אַחַת מֵרוּחוֹת הָעִיר כְּגוֹן זֵיתִים שֶׁיֵּשׁ בְּמַעֲרַב הָעִיר כֻּלָּן אוֹ בְּמִזְרָחָהּ הֲרֵי הֵן כְּשָׂדֶה אַחַת וּפֵאָה אַחַת לְכֻלָּן:","הַבּוֹצֵר אֶת מִקְצָת כַּרְמוֹ מִכָּאן וּמִכָּאן כְּדֵי לְהָקֵל מֵעַל הַגֶּפֶן עַד שֶׁיִּמְצְאוּ שְׁאָר הָאֶשְׁכּוֹלוֹת רֶוַח וַיּוֹסִיפוּ הוּא הַנִּקְרָא מֵדֵּל. וּכְבָר בֵּאַרְנוּ שֶׁהַבּוֹצֵר מֵרוּחַ אַחַת אֵינוֹ מֵדֵּל וּלְפִיכָךְ נוֹתֵן מִן הַנִּשְׁאָר פֵּאָה הָרְאוּיָה לַכּל. וְאַף עַל פִּי שֶׁבָּצַר לַשּׁוּק. אֲבָל אִם הֵדֵּל לִמְכֹּר בַּשּׁוּק אֵינוֹ נוֹתֵן פֵּאָה לְזֶה שֶׁהֵדֵּל. הֵדֵּל לְהָבִיא בְּבֵיתוֹ נוֹתֵן מִן הַנִּשְׁאָר שֶׁהִנִּיחַ לִדְרֹךְ פֵּאָה אַחַת הָרְאוּיָה לַכּל:"],"Mishneh Torah, Heave Offerings 14":["חֲמִשִׁים תְּאֵנוֹת שִׁחוֹרוֹת וַחֲמִשִּׁים לְבָנוֹת שֶׁנָּפְלָה לְתוֹכָן תְּאֵנָה אַחַת שֶׁל תְּרוּמָה. הָיְתָה לְבָנָה הַשְּׁחוֹרוֹת מֻתָּרוֹת וְהַלְּבָנוֹת מְדֻמָּעוֹת. הָיְתָה שְׁחוֹרָה הַשְּׁחוֹרוֹת מְדֻמָּעוֹת וְהַלְּבָנוֹת מֻתָּרוֹת. וְאִם אֵין יָדוּעַ אִם שְׁחוֹרָה הָיְתָה וְאִם לְבָנָה עוֹלָה בְּאֶחָד וּמֵאָה מִן הַכּל. יָדַע מֶה הָיְתָה אַחַר שֶׁנָּפְלָה וְשָׁכַח הֲרֵי כֻּלָּן מְדֻמָּעוֹת:","וְכֵן עִגּוּלֵי דְּבֵלָה וּמַלְבְּנִים שֶׁל דְּבֵלָה שֶׁנָּפַל עִגּוּל אוֹ מַלְבֵּן שֶׁל תְּרוּמָה לְתוֹכָן וְאֵין יָדוּעַ אִם מַלְבֵּן הָיָה אוֹ עִגּוּל הֲרֵי הָעִגּוּלִין מִצְטָרְפִין לַמַּלְבְּנִים וְתַעֲלֶה הַתְּרוּמָה בְּאֶחָד וּמֵאָה מִן הַכּל. עִגּוּלֵי דְּבֵלָה גְּדוֹלִים וּקְטַנִּים שֶׁנָּפַל עִגּוּל דְּבֵלָה לְתוֹכָן וְאֵין יָדוּעַ אִם גָּדוֹל הָיָה אִם קָטָן הֲרֵי הֵן מַעֲלִין בֵּין בְּמִנְיָן בֵּין בְּמִשְׁקָל. כֵּיצַד. נָפַל עִגּוּל לְמֵאָה עִגּוּלִין גְּדוֹלִים וּקְטַנִּים הֲרֵינִי אוֹמֵר קָטָן נָפַל וּמַגְבִּיהַּ אֶחָד מִן הַקְּטַנִּים. נָפַל עִגּוּל לְתוֹךְ אַרְבָּעִים עִגּוּלִים מֵהֶן עֶשְׂרִים עִגּוּל מִשְׁקַל כָּל אֶחָד אַרְבַּע לִיטְרִין וּמֵהֶן עֶשְׂרִים עִגּוּל מִשְׁקַל כָּל אֶחָד לִיטְרָא הוֹאִיל וּמִשְׁקַל הַכּל מֵאָה לִיטְרִין וְאֶחָד הֲרֵינִי אוֹמֵר קָטָן נָפַל וּמַגְבִּיהַּ אֶחָד מִן הַקְּטַנִּים:","וְהַקֶּמַח וְהַסּלֶת אֵינָן מִצְטָרְפִין לְהַעֲלוֹת אֶת הַתְּרוּמָה:","סְאָה שֶׁל חִטִּים שֶׁנָּפְלָה עַל פִּי מְגוּרָה שֶׁל חִטִּים אֵין מְשַׁעֲרִין אוֹתָהּ בְּאֶחָד וּמֵאָה. שֶׁאֵין מְשַׁעֲרִין אֶלָּא אִם נִבְלְלָה תְּרוּמָה עִם הַחֻלִּין. אוֹ אִם אֵין יָדוּעַ בְּאֵיזֶה מָקוֹם נָפְלָה הַתְּרוּמָה. וְכֵיצַד יַעֲשֶׂה. רוֹאִין אֶת הַתְּרוּמָה כְּאִלּוּ הִיא חִטִּים עַל גַּבֵּי שְׂעוֹרִים וּמַפְרִישׁ הַתְּרוּמָה עַצְמָהּ שֶׁנָּפְלָה עַל גַּבֵּי הַמְּגוּרָה עִם מְעַט מִן הַחֻלִּין שֶׁנָּפְלָה עֲלֵיהֶן כְּמִי שֶׁמְּאַסֵּף חִטִּים מֵעַל גַּבֵּי שְׂעוֹרִין:","שְׁתֵּי קֻפּוֹת אוֹ שְׁתֵּי מְגוּרוֹת שֶׁנָּפְלָה תְּרוּמָה לְתוֹךְ אַחַת מֵהֶן וְנִבְלְלָה וְאֵין יָדוּעַ לְאֵי זוֹ מֵהֶן נָפְלָה. אִם הָיוּ שְׁתֵּי מְגוּרוֹת בְּבַיִת אֶחָד הֲרֵי אֵלּוּ מִצְטָרְפוֹת וְתַעֲלֶה בְּאֶחָד וּמֵאָה מִן הַכּל כְּאִלּוּ הָיוּ שְׁתֵּיהֶן מְגוּרָה אַחַת וְהַקֻּפּוֹת מִצְטָרְפוֹת. וַאֲפִלּוּ הָיְתָה קֻפָּה בְּבַיִת זֶה וְקֻפָּה בְּבַיִת אַחֵר לְפִי שֶׁקָּרוֹב הַדָּבָר לְקַבֵּץ שְׁתֵּיהֶן בְּבַיִת אֶחָד. אֲבָל אִם הָיוּ שְׁתֵּי הַקֻּפּוֹת בִּשְׁתֵּי עֲיָרוֹת אֵינָן מִצְטָרְפוֹת:","וְכֵיצַד מַעֲלֶה סְאָה שֶׁנָּפְלָה. אִם רָצָה לְהַעֲלוֹת מֵאֶחָד מִשְּׁתֵּיהֶן מַעֲלֶה וְאִם רָצָה לְהַעֲלוֹת חֶצְיָהּ מִזּוֹ וְחֶצְיָהּ מִזּוֹ מַעֲלֶה. כַּדִּים מְלֵאִים תְּאֵנִים שֶׁל חֻלִּין שֶׁדָּרַס לִיטְרָא תְּאֵנִים שֶׁל תְּרוּמָה בְּפִי כַּד אֶחָד מֵהֶם וְאֵין יָדוּעַ אֵי זוֹ הִיא אִם הָיוּ שָׁם מֵאָה כַּד וְכַד הֲרֵי זוֹ תַּעֲלֶה וְלוֹקֵחַ כַּד אֶחָד מֵהֶם וּמוֹכְרָהּ לַכֹּהֵן חוּץ מִדְּמֵי אוֹתָהּ לִיטְרָא וְהַשְּׁאָר מֻתָּרִין. וְאִם הָיוּ פָּחוֹת מִמֵּאָה הַפּוּמִין כֻּלָּן מְדֻמָּעוֹת וְהַשּׁוּלַיִם מֻתָּרִין:","וְכֵן אִם דְּרָסָהּ עַל פִּי כַּוֶּרֶת אוֹ עַל פִּי עִגּוּל וְאֵין יָדוּעַ אֵי זֶה הוּא. דְּרָסָהּ עַל פִּי הָעִגּוּל וְאֵין יָדוּעַ אִם בִּצְפוֹנוֹ אוֹ בִּדְרוֹמוֹ וְלֹא אֵי זוֹ עִגּוּל הוּא. רוֹאִין אוֹתָם כְּאִלּוּ הֵם פְּרוּדוֹת וְתַעֲלֶה לְפִי הַמִּשְׁקָל. אִם יֵשׁ בְּכָל הָעִגּוּלִין מֵאָה לִיטְרִין תַּעֲלֶה. וְהוּא שֶׁיֵּשׁ בְּכָל עִגּוּל מֵהֶן יֶתֶר עַל שְׁנֵי לִיטְרִין כְּדֵי שֶׁתִּבָּטֵל הַתְּרוּמָה בְּרֹב. שֶׁסְּפֵק הַתְּרוּמָה בָּטֵל בְּרֹב הַחֻלִּין:","הַתְּרוּמָה וַדָּאָהּ אוֹסֵר בְּמֵאָה וּסְפֵקָהּ אוֹסֵר בַּחֲמִשִּׁים. וְאֵין לָהּ הֶתֵּר אֶלָּא בְּרֹב. וְאִם הָיָה בְּיוֹתֵר מֵחֲמִשִּׁים אֵינָהּ צְרִיכָה רֹב. כֵּיצַד. תְּאֵנָה אַחַת תְּרוּמָה שֶׁנָּפְלָה לְתִשְׁעִים וָתֵשַׁע וַהֲרֵי הַמֵּאָה קַיָּמִין הַכּל אָסוּר לְזָרִים כְּמוֹ שֶׁבֵּאַרְנוּ:","נָפְלָה אַחַת מֵחֲמִשִּׁים וְאָבְדָה אַחַת מִן הַכּל שֶׁמָּא אַחַת מִן הַחֻלִּין הִיא שֶׁאָבְדָה אוֹ הָאַחַת שֶׁנָּפְלָה הִיא שֶׁאָבְדָה הֲרֵי אֵלּוּ אֲסוּרוֹת עַד שֶׁיַּרְבֶּה עֲלֵיהֶן חֻלִּין מִמָּקוֹם אַחֵר וְיוֹסִיף עֲלֵיהֶן חֲמִשִּׁים תְּאֵנִים וְאַחַת יוֹתֵר עַל הַכּל. וְאִם נָפְלָה אַחַת שֶׁל תְּרוּמָה לְתוֹךְ חֲמִשִּׁים וְאַחַת וְאָבְדָה אַחַת מִן הַכּל הֻתַּר הַשְּׁאָר לְזָרִים:","סְאָה תְּרוּמָה שֶׁנָּפְלָה לְפָחוֹת מִמֵּאָה מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ אוֹ לְמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ וְנִדְמַע הַכּל אִם לְמַעֲשֵׂר רִאשׁוֹן נָפְלָה יִקְרָא שֵׁם לִתְרוּמַת מַעֲשֵׂר וְיִמְכֹּר הַכּל לַכֹּהֲנִים חוּץ מִדְּמֵי תְּרוּמָה שֶׁנָּפְלָה וּמִדְּמֵי תְּרוּמַת מַעֲשֵׂר שֶׁבּוֹ. וְאִם לְמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ נָפְלָה הֲרֵי אֵלּוּ יִפָּדוּ וְיִמָּכְרוּ לַכֹּהֵן חוּץ מִדְּמֵי תְּרוּמָה:","סְאָה תְּרוּמָה טְמֵאָה שֶׁנָּפְלָה לְפָחוֹת מִמֵּאָה חֻלִּין אוֹ מִמַּעֲשֵׂר רִאשׁוֹן אוֹ מַעֲשֵׂר שֵׁנִי אוֹ הֶקְדֵּשׁ בֵּין טְמֵאִין בֵּין טְהוֹרִים הוֹאִיל וְנִדְמַע הַכּל הֲרֵי הַכּל כִּתְרוּמָה טְמֵאָה שֶׁאֲסוּרָה בַּאֲכִילָה לַכּל וַהֲרֵי הַכּל אָסוּר לְעוֹלָם וּמַנִּיחִים אוֹתָן עַד שֶׁיֵּרָקְבוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁאֵין דַּרְכּוֹ לְהֵאָכֵל חַי. אֲבָל בְּדָבָר שֶׁדַּרְכּוֹ לְהֵאָכֵל חַי לֹא יַנִּיחָן שֶׁמָּא יִתָּקֵל בָּהֶם וְיֹאכַל מֵהֶן. אֶלָּא יַדְלִיק הַכּל כְּדֶרֶךְ שֶׁמַּדְלִיקִין תְּרוּמָה טְמֵאָה:","סְאָה תְּרוּמָה טְהוֹרָה שֶׁנָּפְלָה לְפָחוֹת מִמֵּאָה חֻלִּין טְמֵאִין יִמָּכֵר הַכּל לַכֹּהֲנִים חוּץ מִדְּמֵי תְּרוּמָה וְהַכֹּהֵן אוֹכֵל מְדֻמָּע זֶה קְלָיוֹת. אוֹ יָלוּשׁ אוֹתוֹ בְּמֵי פֵּרוֹת שֶׁאֵינָן מַכְשִׁירִין כְּדֵי שֶׁלֹּא תִּטָּמֵא הַתְּרוּמָה שֶׁבּוֹ מִן הַחֻלִּין הַטְּמֵאִין. אוֹ יָלוּשׁ מְדֻמָּע זֶה פָּחוֹת מִכַּבֵּיצָה שֶׁאֵין אֹכֶל טָמֵא מְטַמֵּא אֹכֶל אַחֵר עַד שֶׁיִּהְיֶה כַּבֵּיצָה. אוֹ יִתְחַלֵּק מְדֻמָּע זֶה פָּחוֹת מִכַּבֵּיצָה בְּכָל עִסָּה כְּדֵי שֶׁלֹּא תִּטָּמֵא הַתְּרוּמָה שֶׁבּוֹ:","סְאָה תְּרוּמָה טְמֵאָה שֶׁנָּפְלָה לְמֵאָה חֻלִּין טְהוֹרִין. וְכֵן סְאָה תְּרוּמָה טְהוֹרָה שֶׁנָּפְלָה לְמֵאָה חֻלִּין טְמֵאִין. תַּעֲלֶה בְּאֶחָד וּמֵאָה וְתֵאָכֵל קְלָיוֹת אוֹ תִּלּוֹשׁ בְּמֵי פֵּרוֹת אוֹ פָּחוֹת מִכַּבֵּיצָה. שֶׁאֵין הַסְּאָה שֶׁנָּפְלָה הִיא הַסְּאָה עַצְמָהּ שֶׁעָלְתָה:","סְאָה תְּרוּמָה טְמֵאָה שֶׁנָּפְלָה לְמֵאָה סְאָה שֶׁל תְּרוּמָה טְהוֹרָה בָּטְלָה בְּמִעוּט וְאוֹכְלִין הַכּל בְּטָהֳרָה. וְאִם נָפְלָה לְפָחוֹת מִמֵּאָה יַנִּיחַ הַכּל עַד שֶׁיֵּרָקֵב:","שְׁתֵּי קֻפּוֹת שֶׁנָּפְלָה סְאָה שֶׁל תְּרוּמָה לְתוֹךְ אַחַת מֵהֶן וְנוֹדַע לְאֵי זוֹ מֵהֶן נָפְלָה וְאַחַר כָּךְ נָפְלָה סְאָה שְׁנִיָּה וְאֵין יָדוּעַ לְאֵי זוֹ מֵהֶן נָפְלָה. אוֹמְרִים לְמָקוֹם שֶׁנָּפְלָה רִאשׁוֹנָה נָפְלָה שְׁנִיָּה לְפִי שֶׁתּוֹלִין אֶת הַקַּלְקָלָה בַּמְקֻלְקָל. נָפְלָה סְאָה רִאשׁוֹנָה לְתוֹךְ אַחַת מֵהֶם וְאֵין יָדוּעַ לְאֵי זוֹ מֵהֶן נָפְלָה וְאַחַר כָּךְ נָפְלָה סְאָה שְׁנִיָּה וְנוֹדַע לְאֵי זוֹ מֵהֶן נָפְלָה. אֵין אוֹמְרִים לְמָקוֹם שֶׁנָּפְלָה שְׁנִיָּה נָפְלָה רִאשׁוֹנָה אֶלָּא שְׁתֵּיהֶן מְקֻלְקָלוֹת:","הָיוּ שְׁתֵּי קֻפּוֹת אַחַת טְמֵאָה וְאַחַת טְהוֹרָה וְנָפְלָה סְאָה שֶׁל תְּרוּמָה לְאַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא אוֹמְרִין לְתוֹךְ הַטְּמֵאָה נָפְלָה:","שְׁתֵּי קֻפּוֹת אַחַת תְּרוּמָה טְהוֹרָה וְאַחַת שֶׁל חֻלִּין טְמֵאִין נָפְלָה סְאָה תְּרוּמָה טְהוֹרָה לְתוֹךְ אַחַת מֵהֶן אוֹמְרִין לְתוֹךְ שֶׁל תְּרוּמָה נָפְלָה וְהַחֻלִּין יֵאָכְלוּ בְּטָהֳרָה כִּתְרוּמָה:","נָפְלָה סְאָה תְּרוּמָה טְמֵאָה לְתוֹךְ אַחַת מֵהֶן אוֹמְרִין לְתוֹךְ שֶׁל תְּרוּמָה נָפְלָה וְהַחֻלִּין יֵאָכְלוּ קְלָיוֹת בְּטָהֳרָה כִּתְרוּמָה גְּדוֹלָה:","סְאָה תְּרוּמָה טְמֵאָה שֶׁנָּפְלָה לְתוֹךְ אַחַת מֵהֶן אוֹמְרִין לְתוֹךְ שֶׁל תְּרוּמָה נָפְלָה וְהַחֻלִּין יֵאָכְלוּ קְלָיוֹת אוֹ יִלּוֹשׁוּ בְּמֵי פֵּרוֹת:","שְׁתֵּי קֻפּוֹת אַחַת שֶׁל תְּרוּמָה טְמֵאָה וְאַחַת שֶׁל חֻלִּין טְהוֹרִין וְנָפְלָה סְאָה שֶׁל תְּרוּמָה טְהוֹרָה לְתוֹךְ אַחַת מֵהֶן אוֹמְרִין לְתוֹךְ שֶׁל תְּרוּמָה נָפְלָה וְהַחֻלִּין יֵאָכְלוּ קְלָיוֹת:","נָפְלָה סְאָה שֶׁל תְּרוּמָה טְמֵאָה לְתוֹךְ אַחַת מֵהֶן שְׁתֵּיהֶן אֲסוּרוֹת שֶׁסְּפֵק תְּרוּמָה טְמֵאָה אָסוּר וּסְפֵק הַמְדֻמָּע מֻתָּר מִפְּנֵי שֶׁאִסּוּר תְּרוּמָה טְמֵאָה מִן הַתּוֹרָה וְאִסּוּר הַמְדֻמָּע מִדִּבְרֵיהֶן עַל הָעִקָּרִים שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מַאֲכָלוֹת:"],"Mishneh Torah, Hiring 11":["מִצְוַת עֲשֵׂה לִתֵּן שְׂכַר הַשָּׂכִיר בִּזְמַנּוֹ שׁנֶּאֱמַר (דברים כד טו) \"בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ\" וְגוֹ'. וְאִם אִחֲרוֹ לְאַחַר זְמַנּוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כד טו) \"וְלֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ\". וְאֵין לוֹקִין עָלָיו שֶׁהֲרֵי הוּא חַיָּב לְשַׁלֵּם. אֶחָד שְׂכַר הָאָדָם וְאֶחָד שְׂכַר הַבְּהֵמָה וְאֶחָד שְׂכַר הַכֵּלִים חַיָּב לִתֵּן בִּזְמַנּוֹ וְאִם אִחֵר לְאַחַר זְמַן עוֹבֵר בְּלֹא תַּעֲשֶׂה. וְגֵר תּוֹשָׁב יֵשׁ בּוֹ מִשּׁוּם בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ וְאִם אִחֲרוֹ אֵינוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה:","כָּל הַכּוֹבֵשׁ שְׂכַר שָׂכִיר כְּאִלּוּ נָטַל נַפְשׁוֹ מִמֶּנּוּ שֶׁנֶּאֱמַר (דברים כד טו) \"וְאֵלָיו הוּא נשֵֹׁא אֶת נַפְשׁוֹ\". וְעוֹבֵר בְּאַרְבַּע אַזְהָרוֹת וַעֲשֵׂה. עוֹבֵר מִשּׁוּם בַּל (ויקרא יט יג) \"תַּעֲשֹׁק\" וּמִשּׁוּם בַּל (ויקרא יט יג) \"תִּגְזל\" וּמִשּׁוּם לֹא תָלִין פְּעֻלַּת שָׂכִיר וּמִשּׁוּם (דברים כד טו) \"לֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ\" וּמִשּׁוּם (דברים כד טו) \"בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ\". אֵי זֶהוּ זְמַנּוֹ שְׂכִיר יוֹם גּוֹבֶה כָּל הַלַּיְלָה וְעָלָיו נֶאֱמַר (ויקרא יט יג) \"לֹא תָלִין פְּעֻלַּת שָׂכִיר אִתְּךָ עַד בֹּקֶר\". וּשְׂכִיר לַיְלָה גּוֹבֶה כָּל הַיּוֹם וְעָלָיו נֶאֱמַר בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ. וּשְׂכִיר שָׁעוֹת שֶׁל יוֹם גּוֹבֶה כָּל הַיּוֹם וּשְׂכִיר שָׁעוֹת שֶׁל לַיְלָה גּוֹבֶה כָּל הַלַּיְלָה. שְׂכִיר שַׁבָּת שְׂכִיר חֹדֶשׁ שְׂכִיר שָׁנָה שְׂכִיר שָׁבוּעַ יָצָא בַּיּוֹם גּוֹבֶה כָּל הַיּוֹם יָצָא בַּלַּיְלָה גּוֹבֶה כָּל (אוֹתוֹ) הַלַּיְלָה:","נָתַן טַלִּיתוֹ לְאֻמָּן וּגְמָרָהּ וְהוֹדִיעוֹ אֲפִלּוּ אִחֲרוֹ עֲשָׂרָה יָמִים כָּל זְמַן שֶׁהַכְּלִי בְּיַד הָאֻמָּן אֵינוֹ עוֹבֵר. נְתָנָהּ בַּחֲצִי הַיּוֹם כֵּיוָן שֶׁשָּׁקְעָה עָלָיו חַמָּה עוֹבֵר מִשּׁוּם בַּל (ויקרא יט יג) \"תָּלִין\" שֶׁהַקַּבְּלָנוּת כִּשְׂכִירוּת הִיא וְחַיָּב לִתֵּן לוֹ בִּזְמַנּוֹ:","הָאוֹמֵר לִשְׁלוּחוֹ צֵא וּשְׂכֹר לִי פּוֹעֲלִים. אָמַר לָהֶם שְׂכַרְכֶם עַל בַּעַל הַבַּיִת שְׁנֵיהֶם אֵינָן עוֹבְרִין מִשּׁוּם בַּל (ויקרא יט יג) \"תָּלִין\" זֶה לְפִי שֶׁלֹּא שְׂכָרָן וְזֶה לְפִי שֶׁאֵין פְּעֻלָּתָן אֶצְלוֹ. וְאִם לֹא אָמַר לָהֶם שְׂכַרְכֶם עַל בַּעַל הַבַּיִת הַשָּׁלִיחַ עוֹבֵר. אֵין הַשּׂוֹכֵר עוֹבֵר אֶלָּא בִּזְמַן שֶׁתְּבָעוֹ הַשָּׂכִיר וְלֹא נָתַן לוֹ אֲבָל אִם לֹא תְּבָעוֹ אוֹ שֶׁתְּבָעוֹ וְלֹא הָיָה לוֹ מַה יִּתֵּן לוֹ אוֹ שֶׁהִמְחָהוּ אֵצֶל אַחֵר וְקִבֵּל הֲרֵי זֶה פָּטוּר:","הַמַּשְׁהֶה שְׂכַר שָׂכִיר עַד אַחַר זְמַנּוֹ אַף עַל פִּי שֶׁכְּבָר עָבַר בַּעֲשֵׂה וְלֹא תַּעֲשֶׂה הֲרֵי זֶה חַיָּב לִתֵּן מִיָּד. וְכָל עֵת שֶׁיִּשְׁהֶה עוֹבֵר עַל לָאו שֶׁל דִּבְרֵיהֶם שֶׁנֶּאֱמַר (משלי ג כח) \"אַל תֹּאמַר לְרֵעֲךָ לֵךְ וָשׁוּב\":","כָּל שָׂכִיר שֶׁשְּׂכָרוֹ בְּעֵדִים וּתְבָעוֹ בִּזְמַנּוֹ וְאָמַר בַּעַל הַבַּיִת נָתַתִּי לְךָ שְׂכָרְךָ וְהַשָּׂכִיר אוֹמֵר לֹא נָטַלְתִּי כְּלוּם תִּקְּנוּ חֲכָמִים שֶׁיִּשָּׁבַע הַשָּׂכִיר בִּנְקִיטַת חֵפֶץ וְיִטּל כְּדִין כָּל נִשְׁבָּע וְנוֹטֵל מִפְּנֵי שֶׁבַּעַל הַבַּיִת טָרוּד בְּפוֹעֲלָיו וְזֶה הַשָּׂכִיר נוֹשֵׂא נַפְשׁוֹ לָזֶה. אֲפִלּוּ הָיָה הַשָּׂכִיר קָטָן הַשָּׂכִיר נִשְׁבָּע וְנוֹטֵל. שְׂכָרוֹ שֶׁלֹּא בְּעֵדִים מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְלֹא שְׂכַרְתִּיךָ נֶאֱמָן לוֹמַר שְׂכַרְתִּיךָ וְנָתַתִּי לְךָ שְׂכָרְךָ וְיִשָּׁבַע בַּעַל הַבַּיִת הֶסֵּת שֶׁנָּתַן אוֹ שְׁבוּעַת הַתּוֹרָה אִם הוֹדָה בְּמִקְצָת כִּשְׁאָר הַטְּעָנוֹת. הָיָה לוֹ עֵד אֶחָד שֶׁשְּׂכָרוֹ אֵינוֹ מוֹעִיל לוֹ כְּלוּם וְכֵן אִם תְּבָעוֹ אַחַר זְמַנּוֹ אַף עַל פִּי שֶׁשְּׂכָרוֹ בְּעֵדִים הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְאִם לֹא הֵבִיא רְאָיָה יִשָּׁבַע בַּעַל הַבַּיִת הֶסֵּת. הֵבִיא רְאָיָה שֶׁתְּבָעוֹ כָּל זְמַנּוֹ הֲרֵי זֶה נִשְׁבָּע וְנוֹטֵל כָּל אוֹתוֹ הַיּוֹם שֶׁל תְּבִיעָה. כֵּיצַד. הָיָה עוֹשֶׂה עִמּוֹ בְּיוֹם שֵׁנִי עַד הָעֶרֶב זְמַנּוֹ כָּל לֵיל שְׁלִישִׁי וּבַיּוֹם הַשְּׁלִישִׁי אֵינוֹ נִשְׁבָּע וְנוֹטֵל. וְאִם הֵבִיא עֵדִים שֶׁהָיָה תּוֹבְעוֹ כָּל לֵיל שְׁלִישִׁי הֲרֵי זֶה נִשְׁבָּע וְנוֹטֵל כָּל יוֹם שְׁלִישִׁי. אֲבָל מִלֵּיל רְבִיעִי וָהָלְאָה הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְכֵן אִם הֵבִיא עֵדִים שֶׁהָיָה תּוֹבְעוֹ וְהוֹלֵךְ עַד יוֹם חֲמִישִׁי הֲרֵי זֶה נִשְׁבָּע וְנוֹטֵל כָּל יוֹם חֲמִישִׁי:","בַּעַל הַבַּיִת אוֹמֵר שְׁתַּיִם קָצַצְתִּי לְךָ וְהַשָּׂכִיר אוֹמֵר שָׁלֹשׁ קָצַצְתָּ לִי לֹא תִּקְּנוּ חֲכָמִים שֶׁיִּשָּׁבַע הַשָּׂכִיר כָּאן אֶלָּא הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְאִם לֹא הֵבִיא רְאָיָה אַף עַל פִּי שֶׁכְּבָר נָתַן לוֹ שְׁתַּיִם אוֹ שֶׁאָמַר לוֹ הֵילָךְ הֲרֵי בַּעַל הַבַּיִת נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְדָבָר זֶה תַּקָּנַת חֲכָמִים הוּא כְּדֵי שֶׁלֹּא יֵלֵךְ הַשָּׂכִיר בְּפַחֵי נֶפֶשׁ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁשְּׂכָרוֹ בְּעֵדִים וְלֹא יָדְעוּ כַּמָּה פָּסַק לוֹ וּתְבָעוֹ בִּזְמַנּוֹ אֲבָל אִם שְׂכָרוֹ שֶׁלֹּא בְּעֵדִים אוֹ שֶׁתְּבָעוֹ אַחַר זְמַנּוֹ יִשָּׁבַע בַּעַל הַבַּיִת הֶסֵּת שֶׁלֹּא קָצַץ לוֹ אֶלָּא מַה שֶּׁכְּבָר נָתַן לוֹ אוֹ שֶׁלֹּא נִשְׁאַר לוֹ אֶצְלוֹ אֶלָּא זֶה שֶׁאָמַר לוֹ הֵילָךְ כְּדִין כָּל הַטְּעָנוֹת:","הַנּוֹתֵן טַלִּיתוֹ לְאֻמָּן אֻמָּן אוֹמֵר שְׁנַיִם קָצַצְתָּ לִי וְהַלָּה אוֹמֵר לֹא קָצַצְתִּי אֶלָּא אֶחָד כָּל זְמַן שֶׁהַטַּלִּית בְּיַד הָאֻמָּן אִם יָכוֹל לִטְעֹן שֶׁהִיא לְקוּחָה בְּיָדוֹ הֲרֵי הָאֻמָּן נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל. וְיָכוֹל לִטְעֹן שֶׁהִיא בִּשְׂכָרוֹ עַד כְּדֵי דָּמֶיהָ. וְאִם יָצָאת טַלִּית מִתַּחַת יָדוֹ אוֹ שֶׁאֵין לוֹ בָּהּ חֲזָקָה וְאֵינוֹ יָכוֹל לִטְעֹן שֶׁהִיא לְקוּחָה בְּיָדוֹ הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה וְאִם לֹא הֵבִיא רְאָיָה יִשָּׁבַע בַּעַל הַטַּלִּית הֶסֵּת אוֹ שְׁבוּעַת הַתּוֹרָה אִם הוֹדָה בְּמִקְצָת כְּדִין כָּל הַטְּעָנוֹת. שֶׁאֵין זֶה כְּדִין הַשָּׂכִיר:","שָׂכִיר הַבָּא לְהִשָּׁבַע אֵין מַחֲמִירִין עָלָיו וְאֵין מְגַלְגְּלִין עָלָיו כְּלָל אֶלָּא נִשְׁבָּע שֶׁלֹּא נָטַל וְיִטּל. וּלְכָל הַנִּשְׁבָּעִין אֵין מְקִלִּין חוּץ מִן הַשָּׂכִיר שֶׁמְּקִלִּין עָלָיו וּפוֹתְחִין לוֹ תְּחִלָּה וְאוֹמְרִים לוֹ אַל תְּצַעֵר עַצְמְךָ הִשָּׁבַע וְטל. אֲפִלּוּ הָיָה שְׂכָרוֹ פְּרוּטָה אַחַת וּבַעַל הַבַּיִת אוֹמֵר נְתַתִּיהָ לֹא יִטּל אֶלָּא בִּשְׁבוּעָה. וְכֵן כָּל הַנִּשְׁבָּע וְנוֹטֵל אֲפִלּוּ לֹא יִטְעֹן אֶלָּא פְּרוּטָה אַחַת לֹא יִטּל אוֹתָהּ אֶלָּא בִּשְׁבוּעָה כְּעֵין שֶׁל תּוֹרָה:"],"Mishneh Torah, Human Dispositions 2":["חוֹלֵי הַגּוּף טוֹעֲמִים הַמַּר מָתוֹק וּמָתוֹק מַר. וְיֵשׁ מִן הַחוֹלִים מִי שֶׁמִּתְאַוְּה וְתָאֵב לְמַאֲכָלוֹת שֶׁאֵינָן רְאוּיִין לַאֲכִילָה כְּגוֹן הֶעָפָר וְהַפֶּחָם וְשׂוֹנֵא הַמַּאֲכָלוֹת הַטּוֹבִים כְּגוֹן הַפַּת וְהַבָּשָׂר הַכּל לְפִי רֹב הַחלִי. כָּךְ בְּנֵי אָדָם שֶׁנַּפְשׁוֹתֵיהֶם חוֹלוֹת מִתְאַוִּים וְאוֹהֲבִים הַדֵּעוֹת הָרָעוֹת וְשׂוֹנְאִים הַדֶּרֶךְ הַטּוֹבָה וּמִתְעַצְּלִים לָלֶכֶת בָּהּ וְהִיא כְּבֵדָה עֲלֵיהֶם לִמְאֹד לְפִי חָלְיָם. וְכֵן יְשַׁעְיָהוּ אוֹמֵר בַּאֲנָשִׁים הַלָּלוּ (ישעיה ה כ) \"הוֹי הָאֹמְרִים לָרַע טוֹב וְלַטּוֹב רָע שָׂמִים חשֶׁךְ לְאוֹר וְאוֹר לְחשֶׁךְ שָׂמִים מַר לְמָתוֹק וּמָתוֹק לְמָר\". וַעֲלֵיהֶם נֶאֱמַר (משלי ב יג) \"הַעֹזְבִים אָרְחוֹת ישֶׁר לָלֶכֶת בְּדַרְכֵי חשֶׁךְ\". וּמַה הִיא תַּקָּנַת חוֹלֵי הַנְּפָשׁוֹת. יֵלְכוּ אֵצֶל הַחֲכָמִים שֶׁהֵן רוֹפְאֵי הַנְּפָשׁוֹת וִירַפְּאוּ חָלְיָם בַּדֵּעוֹת שֶׁמְּלַמְּדִין אוֹתָם עַד שֶׁיַּחֲזִירוּם לַדֶּרֶךְ הַטּוֹבָה. וְהַמַּכִּירִים בַּדֵּעוֹת הָרָעוֹת שֶׁלָּהֶם וְאֵינָם הוֹלְכִים אֵצֶל הַחֲכָמִים לְרַפֵּא אוֹתָם עֲלֵיהֶם אָמַר שְׁלֹמֹה (משלי א ז) \"חָכְמָה וּמוּסָר אֱוִילִים בָּזוּ\":","וְכֵיצַד הִיא רְפוּאָתָם. מִי שֶׁהוּא בַּעַל חֵמָה אוֹמְרִים לוֹ לְהַנְהִיג עַצְמוֹ שֶׁאִם הֻכָּה וְקֻלַּל לֹא יַרְגִּישׁ כְּלָל. וְיֵלֵךְ בְּדֶרֶךְ זוֹ זְמַן מְרֻבֶּה עַד שֶׁיִּתְעַקֵּר הַחֵמָה מִלִּבּוֹ. וְאִם הָיָה גְּבַהּ לֵב יַנְהִיג עַצְמוֹ בְּבִזָּיוֹן הַרְבֵּה וְיֵשֵׁב לְמַטָּה מִן הַכּל וְיִלְבַּשׁ בְּלוֹיֵי סְחָבוֹת הַמְבַזּוֹת אֶת לוֹבְשֵׁיהֶם וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ עַד שֶׁיַּעֲקֹר גֹּבַהּ הַלֵּב מִמֶּנּוּ וְיַחֲזֹר לַדֶּרֶךְ הָאֶמְצָעִית שֶׁהוּא דֶּרֶךְ הַטּוֹבָה. וְלִכְשֶׁיַּחֲזֹר לַדֶּרֶךְ הָאֶמְצָעִית יֵלֵךְ בָּהּ כָּל יָמָיו. וְעַל קַו זֶה יַעֲשֶׂה בִּשְׁאָר כָּל הַדֵּעוֹת אִם הָיָה רָחוֹק לַקָּצֶה הָאֶחָד יַרְחִיק עַצְמוֹ לַקָּצֶה הַשֵּׁנִי וְיִנְהֹג בּוֹ זְמַן רַב עַד שֶׁיַּחֲזֹר בּוֹ לַדֶּרֶךְ הַטּוֹבָה וְהִיא מִדָּה בֵּינוֹנִית שֶׁבְּכָל דֵּעָה וְדֵעָה:","וְיֵשׁ דֵּעוֹת שֶׁאָסוּר לוֹ לָאָדָם לִנְהֹג בָּהֶן בְּבֵינוֹנִית אֶלָּא יִתְרַחֵק מִן הַקָּצֶה הָאֶחָד עַד הַקָּצֶה הָאַחֵר. וְהוּא גֹּבַהּ לֵב. שֶׁאֵין דֶּרֶךְ הַטּוֹבָה שֶׁיִּהְיֶה אָדָם עָנָו בִּלְבַד אֶלָּא שֶׁיִּהְיֶה שְׁפַל רוּחַ וְתִהְיֶה רוּחוֹ נְמוּכָה לִמְאֹד. וּלְפִיכָךְ נֶאֱמַר בְּמשֶׁה רַבֵּנוּ (במדבר יב ג) \"עָנָו מְאֹד\" וְלֹא נֶאֱמַר עָנָו בִּלְבַד. וּלְפִיכָךְ צִוּוּ חֲכָמִים מְאֹד מְאֹד הֱוֵי שְׁפַל רוּחַ. וְעוֹד אָמְרוּ שֶׁכָּל הַמַּגְבִּיהַּ לִבּוֹ כָּפַר בָּעִקָּר שֶׁנֶּאֱמַר (דברים ח יד) \"וְרָם לְבָבֶךָ וְשָׁכַחְתָּ אֶת ה' אֱלֹקֶיךָ\". וְעוֹד אָמְרוּ בְּשַׁמָּתָא מַאן דְּאִית בֵּיהּ גַּסּוּת הָרוּחַ וַאֲפִלּוּ מִקְצָתָהּ. וְכֵן הַכַּעַס מִדָּה רָעָה הִיא עַד לִמְאֹד וְרָאוּי לָאָדָם שֶׁיִּתְרַחֵק מִמֶּנָּה עַד הַקָּצֶה הָאַחֵר. וִילַמֵּד עַצְמוֹ שֶׁלֹּא יִכְעֹס וַאֲפִלּוּ עַל דָּבָר שֶׁרָאוּי לִכְעֹס עָלָיו. וְאִם רָצָה לְהַטִּיל אֵימָה עַל בָּנָיו וּבְנֵי בֵּיתוֹ אוֹ עַל הַצִּבּוּר אִם הָיָה פַּרְנָס וְרָצָה לִכְעֹס עֲלֵיהֶן כְּדֵי שֶׁיַּחְזְרוּ לַמּוּטָב יַרְאֶה עַצְמוֹ בִּפְנֵיהֶם שֶׁהוּא כּוֹעֵס כְּדֵי לְיַסְּרָם וְתִהְיֶה דַּעְתּוֹ מְיֻשֶּׁבֶת בֵּינוֹ לְבֵין עַצְמוֹ כְּאָדָם שֶׁהוּא מְדַמֶּה כּוֹעֵס בִּשְׁעַת כַּעֲסוֹ וְהוּא אֵינוֹ כּוֹעֵס. אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים כָּל הַכּוֹעֵס כְּאִלּוּ עוֹבֵד עֲבוֹדַת כּוֹכָבִים. וְאָמְרוּ שֶׁכָּל הַכּוֹעֵס אִם חָכָם הוּא חָכְמָתוֹ מִסְתַּלֶּקֶת מִמֶּנּוּ וְאִם נָבִיא הוּא נְבוּאָתוֹ מִסְתַּלֶּקֶת מִמֶּנּוּ. וּבַעֲלֵי כַּעַס אֵין חַיֵּיהֶם חַיִּים. לְפִיכָךְ צִוּוּ לְהִתְרַחֵק מִן הַכַּעַס עַד שֶׁיַּנְהִיג עַצְמוֹ שֶׁלֹּא יַרְגִּישׁ אֲפִלּוּ לַדְּבָרִים הַמַּכְעִיסִים וְזוֹ הִיא הַדֶּרֶךְ הַטּוֹבָה. וְדֶרֶךְ הַצַּדִּיקִים הֵן עֲלוּבִין וְאֵינָן עוֹלְבִין שׁוֹמְעִים חֶרְפָּתָם וְאֵינָם מְשִׁיבִין עוֹשִׂין מֵאַהֲבָה וּשְׂמֵחִים בְּיִסּוּרִים. וַעֲלֵיהֶם הַכָּתוּב אוֹמֵר (שופטים ה לא) \"וְאֹהֲבָיו כְּצֵאת הַשֶּׁמֶשׁ בִּגְבֻרָתוֹ\":","לְעוֹלָם יַרְבֶּה אָדָם בִּשְׁתִיקָה וְלֹא יְדַבֵּר אֶלָּא אוֹ בִּדְבַר חָכְמָה אוֹ בִּדְבָרִים שֶׁצָּרִיךְ לָהֶם לְחַיֵּי גּוּפוֹ. אָמְרוּ עַל רַב תַּלְמִיד רַבֵּנוּ הַקָּדוֹשׁ שֶׁלֹּא שָׂח שִׂיחָה בְּטֵלָה כָּל יָמָיו. וְזוֹ הִיא שִׂיחַת רֹב כָּל אָדָם. וַאֲפִלּוּ בְּצָרְכֵי הַגּוּף לֹא יַרְבֶּה אָדָם דְּבָרִים. וְעַל זֶה צִוּוּ חֲכָמִים וְאָמְרוּ כָּל הַמַּרְבֶּה דְּבָרִים מֵבִיא חֵטְא. וְאָמְרוּ (משנה אבות א יז) \"לֹא מָצָאתִי לַגּוּף טוֹב אֶלָּא שְׁתִיקָה\". וְכֵן בְּדִבְרֵי תּוֹרָה וּבְדִבְרֵי חָכְמָה יִהְיוּ דִּבְרֵי הָאָדָם מְעַטִּים וְעִנְיְנֵיהֶם מְרֻבִּים. וְהוּא שֶׁצִּוּוּ חֲכָמִים וְאָמְרוּ (גמרא פסחים ג ב) \"לְעוֹלָם יִשְׁנֶה אָדָם לְתַלְמִידָיו דֶּרֶךְ קְצָרָה\". אֲבָל אִם הָיוּ הַדְּבָרִים מְרֻבִּין וְהָעִנְיָן מֻעָט הֲרֵי זוֹ סִכְלוּת וְעַל זֶה נֶאֱמַר (קהלת ה ב) \"כִּי בָּא הַחֲלוֹם בְּרֹב עִנְיָן וְקוֹל כְּסִיל בְּרֹב דְּבָרִים\":","(משנה אבות ג יג) \"סְיָג לַחָכְמָה שְׁתִיקָה\". לְפִיכָךְ לֹא יְמַהֵר לְהָשִׁיב וְלֹא יַרְבֶּה לְדַבֵּר. וִילַמֵּד לַתַּלְמִידִים בְּשׁוּבָה וָנַחַת בְּלֹא צְעָקָה וּבְלֹא אֲרִיכוּת לָשׁוֹן. הוּא שֶׁאָמַר שְׁלֹמֹה (קהלת ט יז) \"דִּבְרֵי חֲכָמִים בְּנַחַת נִשְׁמָעִים\":","אָסוּר לָאָדָם לְהַנְהִיג עַצְמוֹ בְּדִבְרֵי חֲלָקוֹת וּפִתּוּי. וְלֹא יִהְיֶה אֶחָד בַּפֶּה וְאֶחָד בַּלֵּב אֶלָּא תּוֹכוֹ כְּבָרוֹ וְהָעִנְיָן שֶׁבַּלֵּב הוּא הַדָּבָר שֶׁבַּפֶּה. וְאָסוּר לִגְנֹב דַּעַת הַבְּרִיּוֹת וַאֲפִלּוּ דַּעַת הַנָּכְרִי. כֵּיצַד. לֹא יִמְכֹּר לְנָכְרִי בְּשַׂר נְבֵלָה בִּמְקוֹם בְּשַׂר שְׁחוּטָה. וְלֹא מִנְעָל שֶׁל מֵתָה בִּמְקוֹם מִנְעָל שֶׁל שְׁחוּטָה. וְלֹא יְסַרְהֵב בַּחֲבֵרוֹ שֶׁיֹּאכַל אֶצְלוֹ וְהוּא יוֹדֵעַ שֶׁאֵינוֹ אוֹכֵל. וְלֹא יַרְבֶּה לוֹ בְּתִקְרֹבֶת וְהוּא יוֹדֵעַ שֶׁאֵינוֹ מְקַבֵּל. וְלֹא יִפְתַּח לוֹ חֲבִיּוֹת שֶׁהוּא צָרִיךְ לְפָתְחָן לְמָכְרָן כְּדֵי לְפַתּוֹתוֹ שֶׁבִּשְׁבִיל כְּבוֹדוֹ פָּתַח וְכֵן כָּל כַּיּוֹצֵא בּוֹ. וַאֲפִלּוּ מִלָּה אַחַת שֶׁל פִּתּוּי וְשֶׁל גְּנֵבַת דַּעַת אָסוּר, אֶלָּא שְׂפַת אֱמֶת וְרוּחַ נָכוֹן וְלֵב טָהוֹר מִכָּל עָמָל וְהַוּוֹת:","לֹא יְהֵא אָדָם בַּעַל שְׂחוֹק וּמַהֲתַלּוֹת וְלֹא עָצֵב וְאוֹנֵן אֶלָּא שָׂמֵחַ. כָּךְ אָמְרוּ חֲכָמִים שְׂחוֹק וְקַלּוּת רֹאשׁ מַרְגִּילִין אֶת הָאָדָם לְעֶרְוָה. וְצִוּוּ שֶׁלֹּא יְהֵא אָדָם פָּרוּץ בִּצְחוֹק וְלֹא עָצֵב וּמִתְאַבֵּל אֶלָּא מְקַבֵּל אֶת כָּל הָאָדָם בְּסֵבֶר פָּנִים יָפוֹת. וְכֵן לֹא יִהְיֶה בַּעַל נֶפֶשׁ רְחָבָה נִבְהָל לַהוֹן וְלֹא עָצֵב וּבָטֵל מִמְּלָאכָה. אֶלָּא בַּעַל עַיִן טוֹבָה מְמַעֵט בְּעֵסֶק וְעוֹסֵק בַּתּוֹרָה. וְאוֹתוֹ הַמְּעַט שֶׁהוּא חֶלְקוֹ יִשְׂמַח בּוֹ. וְלֹא בַּעַל קְטָטָה וְלֹא בַּעַל קִנְאָה וְלֹא בַּעַל תַּאֲוָה וְלֹא רוֹדֵף אַחַר הַכָּבוֹד. כָּךְ אָמְרוּ חֲכָמִים הַקִּנְאָה וְהַתַּאֲוָה וְהַכָּבוֹד מוֹצִיאִין אֶת הָאָדָם מִן הָעוֹלָם. כְּלָלוֹ שֶׁל דָּבָר יֵלֵךְ בַּמִּדָּה הַבֵּינוֹנִית שֶׁבְּכָל דֵּעָה וְדֵעָה עַד שֶׁיִּהְיוּ כָּל דֵּעוֹתָיו מְכֻוָּנוֹת בָּאֶמְצָעוּת. וְהוּא שֶׁשְּׁלֹמֹה אָמַר (משלי ד כו) \"פַּלֵּס מַעְגַּל רַגְלֶךָ וְכָל דְּרָכֶיךָ יִכֹּנוּ\":"],"Mishneh Torah, Immersion Pools 5":["מִקְוְה שֶׁנָּפְלוּ אֵלָיו שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין מִכְּלִי אֶחָד אוֹ מִשְּׁנַיִם וּשְׁלֹשָׁה כֵּלִים מִצְטָרְפִין וְהוּא שֶׁיַּתְחִיל הַשֵּׁנִי עַד שֶׁלֹּא פָּסַק הָרִאשׁוֹן. מֵאַרְבָּעָה כֵּלִים אֵין מִצְטָרְפִין. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁלֹּא נִתְכַּוֵּן לְרַבּוֹת. אֲבָל אִם נִתְכַּוֵּן לְרַבּוֹת אֶת מֵי הַמִּקְוֶה אֲפִלּוּ נָפַל מִשְׁקַל דִּינָר בְּכָל שָׁנָה מִצְטָרֵף לִשְׁלֹשָׁה לוֹגִין בֵּין שֶׁקָּדְמוּ הַשְּׁאוּבִים אֶת הַכְּשֵׁרִים בֵּין שֶׁקָּדְמוּ הַכְּשֵׁרִים אֶת הַשְּׁאוּבִים אוֹ שֶׁנָּפְלוּ שְׁתֵּיהֶן כְּאַחַת. כֵּיוָן שֶׁנָּפְלוּ שְׁלֹשָׁה לוֹגִין שְׁאוּבִין לְתוֹךְ אַרְבָּעִים סְאָה [קֹדֶם שֶׁנָּפְלוּ בּוֹ אַרְבָּעִים סְאָה אוֹ לְפָחוֹת מֵאַרְבָּעִים] נִפְסַל הַכּל וְנַעֲשָׂה שָׁאוּב:","שְׁנַיִם שֶׁהֵטִילוּ זֶה לוֹג וּמֶחֱצָה וְזֶה לוֹג וּמֶחֱצָה. וְהַסּוֹחֵט כְּסוּתוֹ וְהִגְבִּיהָהּ וְהַמַּיִם שֶׁבָּהּ נוֹפְלִין מִמְּקוֹמוֹת הַרְבֵּה. וְכֵן הַמְעָרֶה מִן הַצַּרְצוּר שֶׁמֵּטִיל מִמְּקוֹמוֹת הַרְבֵּה הֲרֵי אֵלּוּ פּוֹסְלִין:","הַמַּטְבִּיל כַּר אוֹ כֶּסֶת שֶׁל עוֹר בְּמִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מְכֻוָּנוֹת כֵּיוָן שֶׁהִגְבִּיהַּ שִׂפְתוֹתֵיהֶן מִן הַמַּיִם נִמְצְאוּ הַמַּיִם שֶׁבְּתוֹכָן שְׁאוּבִין. כֵּיצַד יַעֲשֶׂה. מַטְבִּילָן וּמַעֲלָן דֶּרֶךְ שׁוּלֵיהֶן. אֲבָל הַקֻּפָּה וְהַשַּׂק מַטְבִּילָן וּמַעֲלָן כְּדַרְכָּן וְאֵינוֹ חוֹשֵׁשׁ:","מִקְוֶה שֶׁיֵּשׁ בּוֹ שָׁלֹשׁ גּוּמוֹת מִמַּיִם שְׁאוּבִין לוֹג בְּכָל גּוּמָא וְנָפְלוּ לְתוֹכוֹ מַיִם כְּשֵׁרִים אִם יָדוּעַ שֶׁנָּפַל לְתוֹכוֹ אַרְבָּעִים סְאָה מַיִם כְּשֵׁרִים עַד שֶׁלֹּא יַגִּיעוּ לַגּוּמָא הַשְּׁלִישִׁית כָּשֵׁר וְאִם לָאו פָּסוּל:","שְׁנֵי מִקְוָאוֹת אֵין בְּכָל אֶחָד מֵהֶן אַרְבָּעִים סְאָה וְנָפַל לָזֶה לוֹג וּמֶחֱצָה וְלָזֶה לוֹג וּמֶחֱצָה וְנִתְעָרְבוּ שְׁנֵי הַמִּקְוָאוֹת הֲרֵי אֵלּוּ כְּשֵׁרִין מִפְּנֵי שֶׁלֹּא נִקְרָא עַל אֶחָד מֵהֶן שֵׁם פָּסוּל. אֲבָל מִקְוֶה שֶׁאֵין בּוֹ אַרְבָּעִים סְאָה שֶׁנָּפַל לְתוֹכוֹ שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין וְאַחַר כָּךְ נֶחְלָק לִשְׁנַיִם וְרִבָּה מַיִם כְּשֵׁרִים עַל כָּל אֶחָד מֵהֶן הֲרֵי אֵלּוּ פְּסוּלִין שֶׁכָּל הַמִּקְוֶה כֻּלּוֹ שֶׁנִּפְסַל כְּמַיִם שְׁאוּבִין הוּא חָשׁוּב וּכְאִלּוּ כָּל מֵימָיו נִשְׁאֲבוּ בִּכְלִי:","בּוֹר שֶׁהוּא מָלֵא מַיִם שְׁאוּבִים וְהָאַמָּה נִכְנֶסֶת לוֹ וְיוֹצֵאת מִמֶּנּוּ לְעוֹלָם הוּא בְּפִסּוּלוֹ עַד שֶׁתְּחַשֵּׁב שֶׁלֹּא נִשְׁאֲרוּ מִן הַשְּׁאוּבִין שֶׁהָיוּ בַּבּוֹר שְׁלֹשָׁה לוֹגִין. מִקְוֶה שֶׁנָּפַל לְתוֹכוֹ מַיִם שְׁאוּבִין וְנִפְסַל וְאַחַר כָּךְ רִבָּה עָלָיו מַיִם כְּשֵׁרִים עַד שֶׁנִּמְצְאוּ הַכְּשֵׁרִים אַרְבָּעִים סְאָה הֲרֵי הוּא בְּפִסּוּלוֹ עַד שֶׁיֵּצְאוּ כָּל הַמַּיִם שֶׁהָיוּ בְּתוֹכוֹ וְיִפְחֲתוּ הַשְּׁאוּבִין מִשְּׁלֹשָׁה לוֹגִין. כֵּיצַד. מִקְוֶה שֶׁיֵּשׁ בּוֹ עֶשְׂרִים סְאָה מֵי גְּשָׁמִים וְנָפַל לְתוֹכוֹ סְאָה מַיִם שְׁאוּבִים וְאַחַר כָּךְ הִרְבָּה עָלָיו מַיִם כְּשֵׁרִים. הֲרֵי זֶה בְּפִסּוּלוֹ עַד שֶׁיֵּדַע שֶׁיָּצְאוּ מִמֶּנּוּ עֶשְׂרִים סְאָה שֶׁהָיוּ בּוֹ וַחֲמִשָּׁה קַבִּין וְיוֹתֵר מֵרְבִיעַ הַקַּב וְלֹא נִשְׁאַר מִן הַכּל שֶׁנִּפְסַל חוּץ מִפָּחוֹת מִשְּׁלֹשָׁה לוֹגִין. וְכֵן אִם עָשָׂה מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מַיִם כְּשֵׁרִים וְעֵרְבוֹ עִם הַמִּקְוֶה הַזֶּה הַפָּסוּל טִהֲרוּ אֵלּוּ אֶת אֵלּוּ:","הַמְסַלֵּק אֶת הַטִּיט לַצְּדָדִים וְנִמְשְׁכוּ מִמֶּנּוּ שְׁלֹשָׁה לוֹגִים לַמִּקְוֶה הֲרֵי זֶה כָּשֵׁר. הָיָה תּוֹלֵשׁ הַטִּיט וּמַגְבִּיהוֹ בְּיָדוֹ וְהִבְדִּילוֹ מִן הַמִּקְוֶה לְצִדָּהּ וְנִמְשְׁכוּ מִמֶּנּוּ שְׁלֹשָׁה לוֹגִין הֲרֵי אֵלּוּ פּוֹסְלִין:","גַּיִס הָעוֹבֵר מִמָּקוֹם לְמָקוֹם וְכֵן בְּהֵמָה הָעוֹבֶרֶת מִמָּקוֹם לְמָקוֹם וְזָלְפוּ בִּידֵיהֶן וּבְרַגְלֵיהֶם שְׁלֹשָׁה לוֹגִין לַמִּקְוֶה הֲרֵי זֶה כָּשֵׁר. וְלֹא עוֹד אֶלָּא אֲפִלּוּ עָשׂוּ מִקְוֶה בַּתְּחִלָּה הֲרֵי זֶה כָּשֵׁר:","מִקְוֶה שֶׁאֵין בּוֹ אַרְבָּעִים סְאָה וְנָפַל לְתוֹכוֹ פָּחוֹת מִשְּׁלֹשָׁה לוֹגִין מַיִם טְמֵאִין שְׁאוּבִין הֲרֵי זֶה כָּשֵׁר לְחַלָּה וְלִתְרוּמָה וְלִטּל מֵהֶן לַיָּדַיִם. וּפְסוּלִין לְהַקְווֹת עֲלֵיהֶן. יָרְדוּ עֲלֵיהֶן גְּשָׁמִים וְרַבּוּ עֲלֵיהֶן הֲרֵי אֵלּוּ כְּשֵׁרִים לְהַקְווֹת עֲלֵיהֶם. נָפַל לְתוֹכוֹ שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין טְמֵאִים הֲרֵי זֶה פָּסוּל לְחַלָּה וְלִתְרוּמָה וְלִטּל מִמֶּנּוּ לַיָּדַיִם. וּפְסוּלִין לְהַקְווֹת עָלָיו. יָרְדוּ גְּשָׁמִים וְרַבּוּ עֲלֵיהֶן הֲרֵי הֵן כְּשֵׁרִין לְחַלָּה וְלִתְרוּמָה וְלִטּל מֵהֶן לַיָּדַיִם וּפְסוּלִין לְהַקְווֹת עֲלֵיהֶן עַד שֶׁיֵּצְאוּ כָּל הַמַּיִם הָרִאשׁוֹנִים שֶׁנַּעֲשׂוּ כֻּלָּן כִּשְׁאוּבִין וְלֹא יִשָּׁאֵר מֵהֶן אֶלָּא פָּחוֹת מִשְּׁלֹשָׁה לוֹגִין. וְכֵן מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה חָסֵר דִּינָר וְנָפְלוּ לְתוֹכוֹ שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין טְמֵאִין הֲרֵי זֶה פָּסוּל לְחַלָּה וְלִתְרוּמָה וְלִטּל מִמֶּנּוּ לַיָּדַיִם וּפְסוּלִין לְהַקְווֹת עֲלֵיהֶן. נָפַל לְתוֹכוֹ פָּחוֹת מִשְּׁלֹשָׁה לוֹגִין מַיִם אֲפִלּוּ כֻּלָּן טְמֵאִין וְאַחַר כָּךְ נָפְלוּ לְתוֹכוֹ מִשְׁקַל דִּינָר מֵי גְּשָׁמִים שֶׁהִשְׁלִימוּ כָּשֵׁר. כְּשֵׁם שֶׁטָּהוֹר לִטְבִילָה כָּךְ טָהוֹר לְכָל דָּבָר:"],"Mishneh Torah, Inheritances 6":["אֵין אָדָם יָכוֹל לְהוֹרִישׁ לְמִי שֶׁאֵינוֹ רָאוּי לְיָרְשׁוֹ וְלֹא לַעֲקֹר הַיְרֻשָּׁה מִן הַיּוֹרֵשׁ אַף עַל פִּי שֶׁזֶּה מָמוֹן הוּא. לְפִי שֶׁנֶּאֱמַר בְּפָרָשַׁת נְחָלוֹת (במדבר כז יא) \"וְהָיְתָה לִבְנֵי יִשְׂרָאֵל לְחֻקַּת מִשְׁפָּט\" לוֹמַר שֶׁחֻקָּה זוֹ לֹא נִשְׁתַּנָּה וְאֵין הַתְּנַאי מוֹעִיל בָּהּ. בֵּין שֶׁצִּוָּה וְהוּא בָּרִיא בֵּין שֶׁהָיָה שְׁכִיב מֵרַע בֵּין עַל פֶּה בֵּין בִּכְתָב אֵינוֹ מוֹעִיל:","לְפִיכָךְ הָאוֹמֵר אִישׁ פְּלוֹנִי בְּנִי בְּכוֹרִי לֹא יִטּל פִּי שְׁנַיִם. אִישׁ פְּלוֹנִי בְּנִי לֹא יִירַשׁ עִם אֶחָיו. לֹא אָמַר כְּלוּם. אִישׁ פְּלוֹנִי יִירָשֵׁנִי בְּמָקוֹם שֶׁיֵּשׁ לוֹ בַּת. בִּתִּי תִּירָשֵׁנִי בְּמָקוֹם שֶׁיֵּשׁ לוֹ בֵּן. לֹא אָמַר כְּלוּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל הָיוּ לוֹ יוֹרְשִׁין רַבִּים כְּגוֹן בָּנִים רַבִּים אוֹ אַחִים אוֹ בָּנוֹת וְאָמַר כְּשֶׁהוּא שְׁכִיב מֵרַע פְּלוֹנִי אָחִי יִירָשֵׁנִי מִכְּלַל אֶחַי אוֹ בִּתִּי פְּלוֹנִית תִּירָשֵׁנִי מִכְּלַל בְּנוֹתַי דְּבָרָיו קַיָּמִין בֵּין שֶׁאָמַר עַל פֶּה בֵּין שֶׁכָּתַב בִּכְתָב. אֲבָל אִם אָמַר פְּלוֹנִי בְּנִי יִירָשֵׁנִי לְבַדּוֹ אִם אָמַר עַל פֶּה דְּבָרָיו קַיָּמִין. אֲבָל אִם כָּתַב כָּל נְכָסָיו לִבְנוֹ לֹא עָשָׂהוּ אֶלָּא אַפּוֹטְרוֹפּוֹס כְּמוֹ שֶׁבֵּאַרְנוּ:","אָמַר פְּלוֹנִי בְּנִי יִירַשׁ חֲצִי נְכָסַי וּשְׁאָר בָּנַי הַחֵצִי דְּבָרָיו קַיָּמִין. אֲבָל אִם אָמַר הַבְּכוֹר יִירַשׁ כַּפָּשׁוּט אוֹ שֶׁאָמַר לֹא יִירַשׁ פִּי שְׁנַיִם עִם אֶחָיו לֹא אָמַר כְּלוּם שֶׁנֶּאֱמַר (דברים כא טז) \"לֹא יוּכַל לְבַכֵּר אֶת בֶּן הָאֲהוּבָה עַל פְּנֵי בֶן הַשְּׂנוּאָה הַבְּכֹר\" (דברים כא יז) \"כִּי אֶת הַבְּכֹר בֶּן הַשְּׂנוּאָה יַכִּיר\":","וְאִם הָיָה בָּרִיא אֵינוֹ יָכוֹל לְהוֹסִיף וְלֹא לִגְרֹעַ לֹא לַבְּכוֹר וְלֹא לְאֶחָד מִשְּׁאָר הַיּוֹרְשִׁין:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁאָמַר בִּלְשׁוֹן יְרֻשָּׁה. אֲבָל אִם נָתַן מַתָּנָה דְּבָרָיו קַיָּמִין. לְפִיכָךְ הַמְחַלֵּק נְכָסָיו עַל פִּיו לְבָנָיו כְּשֶׁהוּא שְׁכִיב מֵרַע רִבָּה לְאֶחָד וּמִעֵט לְאֶחָד וְהִשְׁוָה לָהֶן הַבְּכוֹר דְּבָרָיו קַיָּמִין. וְאִם אָמַר מִשּׁוּם יְרֻשָּׁה לֹא אָמַר כְּלוּם:","כָּתַב בֵּין בַּתְּחִלָּה בֵּין בָּאֶמְצַע בֵּין בַּסּוֹף מִשּׁוּם מַתָּנָה אַף עַל פִּי שֶׁהִזְכִּיר לְשׁוֹן יְרֻשָּׁה בַּתְּחִלָּה וּבַסּוֹף דְּבָרָיו קַיָּמִין. כֵּיצַד. תִּנָּתֵן שָׂדֶה פְּלוֹנִי לִפְלוֹנִי בְּנִי וְיִירָשֶׁנָּה. אוֹ שֶׁאָמַר יִירָשֶׁנָּה וְתִנָּתֵן לוֹ וְיִירָשֶׁנָּה. אוֹ יִירָשֶׁנָּה וְתִנָּתֵן לוֹ. הוֹאִיל וְיֵשׁ שָׁם לְשׁוֹן מַתָּנָה אַף עַל פִּי שֶׁהִזְכִּיר לְשׁוֹן יְרֻשָּׁה בַּתְּחִלָּה וּבַסּוֹף דְּבָרָיו קַיָּמִין. וְכֵן אִם הָיוּ שָׁלֹשׁ שָׂדוֹת לִשְׁלֹשָׁה יוֹרְשִׁין וְאָמַר יִירַשׁ פְּלוֹנִי שָׂדֶה פְּלוֹנִית וְתִנָּתֵן לִפְלוֹנִי שָׂדֶה פְּלוֹנִית וְיִירַשׁ פְּלוֹנִי שָׂדֶה פְּלוֹנִית קָנוּ. אַף עַל פִּי שֶׁזֶּה שֶׁאָמַר לוֹ בִּלְשׁוֹן יְרֻשָּׁה אֵינוֹ זֶה שֶׁאָמַר לוֹ בִּלְשׁוֹן מַתָּנָה. וְהוּא שֶׁלֹּא יִשְׁהֶה בֵּין אֲמִירָה לַאֲמִירָה כְּדֵי דִּבּוּר. אֲבָל אִם שָׁהָה צָרִיךְ שֶׁיְּהֵא לְשׁוֹן הַמַּתָּנָה מְעֹרָב בִּשְׁלָשְׁתָּן:","כֵּיצַד. אִם הָיָה לְשׁוֹן הַמַּתָּנָה בָּאֶמְצַע יֹאמַר פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי יִירְשׁוּ שָׂדֶה פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי שֶׁנְּתַתִּים לָהֶן בְּמַתָּנָה וְיִירָשׁוּם. וְאִם הָיָה לְשׁוֹן הַמַּתָּנָה בַּתְּחִלָּה יֹאמַר תִּנָּתֵן שָׂדֶה פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי לִפְלוֹנִי וּפְלוֹנִי וּפְלוֹנִי וְיִירָשׁוּם. וְאִם הָיָה לְשׁוֹן הַמַּתָּנָה בַּסּוֹף יֹאמַר יִירַשׁ פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי שָׂדֶה פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי שֶּׁנְּתַתִּים לָהֶן בְּמַתָּנָה:","יְרֻשַּׁת הַבַּעַל אַף עַל פִּי שֶׁהִיא מִדִּבְרֵיהֶם עָשׂוּ חִזּוּק לְדִבְרֵיהֶם כְּשֶׁל תּוֹרָה. וְאֵין הַתְּנַאי מוֹעִיל בָּהּ אֶלָּא אִם כֵּן הִתְנָה עִמָּהּ כְּשֶׁהִיא אֲרוּסָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת:","הָעַכּוּ\"ם יוֹרֵשׁ אֶת אָבִיו דְּבַר תּוֹרָה. אֲבָל שְׁאָר יְרֻשּׁוֹתֵיהֶן מַנִּיחִין אוֹתוֹ לְפִי מִנְהָגָם:","וְהַגֵּר אֵינוֹ יוֹרֵשׁ אֶת אָבִיו הָעַכּוּ\"ם אֶלָּא מִדִּבְרֵיהֶם תִּקְּנוּ לוֹ שֶׁיִּירַשׁ כְּשֶׁהָיָה שֶׁמָּא יַחְזֹר לְמִרְדּוֹ. וְיֵרָאֶה לִי שֶׁתְּנַאי מוֹעִיל בִּירֻשָּׁה זוֹ הוֹאִיל וְאֵין הָעַכּוּ\"ם מְחֻיָּב לַעֲמֹד בְּתַקָּנַת חֲכָמִים. וְאֵין הָעַכּוּ\"ם יוֹרֵשׁ אֶת אָבִיו הַגֵּר וְלֹא גֵּר יוֹרֵשׁ אֶת גֵּר לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים:","כָּל הַנּוֹתֵן נְכָסָיו לַאֲחֵרִים וְהִנִּיחַ הַיּוֹרְשִׁין. אַף עַל פִּי שֶׁאֵין הַיּוֹרְשִׁין נוֹהֲגִין (בּוֹ) כַּשּׁוּרָה אֵין רוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ. וְזָכוּ הָאֲחֵרִים בְּכָל מַה שֶּׁנָּתַן לָהֶן. מִדַּת חֲסִידוּת הִיא שֶׁלֹּא יָעִיד אָדָם חָסִיד בְּצַוָּאָה שֶׁמַּעֲבִירִין בּוֹ הַיְרֻשָּׁה מִן הַיּוֹרֵשׁ אֲפִלּוּ מִבֵּן שֶׁאֵינוֹ נוֹהֵג כַּשּׁוּרָה לְאָחִיו חָכָם וְנוֹהֵג כַּשּׁוּרָה:","יִשְׂרָאֵל שֶׁהֵמִיר יוֹרֵשׁ אֶת קְרוֹבָיו הַיִּשְׂרְאֵלִים כְּשֶׁהָיָה. וְאִם רָאוּ בֵּית דִּין לְאַבֵּד אֶת מָמוֹנוֹ וּלְקָנְסוֹ שֶׁלֹּא יִירַשׁ כְּדֵי שֶׁלֹּא לְחַזֵּק אֶת יְדֵיהֶם הָרְשׁוּת בְּיָדָן. וְאִם יֵשׁ לוֹ בָּנִים בְּיִשְׂרָאֵל תִּנָּתֵן יְרֻשַּׁת אֲבִיהֶן הַמּוּמָר לָהֶן. וְכֵן הַמִּנְהָג תָּמִיד בַּמַּעֲרָב:","צִוּוּ חֲכָמִים שֶׁלֹּא יְשַׁנֶּה אָדָם בֵּין הַבָּנִים בְּחַיָּיו אֲפִלּוּ בְּדָבָר מוּעָט שֶׁלֹּא יָבוֹאוּ לִידֵי תַּחֲרוּת וְקִנְאָה כַּאֲחֵי יוֹסֵף עִם יוֹסֵף:"],"Mishneh Torah, Kings and Wars 6":["אֵין עוֹשִׂין מִלְחָמָה עִם אָדָם בָּעוֹלָם עַד שֶׁקּוֹרְאִין לוֹ שָׁלוֹם. אֶחָד מִלְחֶמֶת הָרְשׁוּת וְאֶחָד מִלְחֶמֶת מִצְוָה. שֶׁנֶּאֱמַר (דברים כ, י) \"כִּי תִקְרַב אֶל עִיר לְהִלָּחֵם עָלֶיהָ וְקָרָאתָ אֵלֶיהָ לְשָׁלוֹם\". אִם הִשְׁלִימוּ וְקִבְּלוּ שֶׁבַע מִצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ עֲלֵיהֶן אֵין הוֹרְגִין מֵהֶן נְשָׁמָה וַהֲרֵי הֵן לְמַס. שֶׁנֶּאֱמַר (דברים כ, יא) \"יִהְיוּ לְךָ לָמַס וַעֲבָדוּךָ\". קִבְּלוּ עֲלֵיהֶן הַמַּס וְלֹא קִבְּלוּ הָעַבְדוּת אוֹ שֶׁקִּבְּלוּ הָעַבְדוּת וְלֹא קִבְּלוּ הַמַּס. אֵין שׁוֹמְעִין לָהֶם עַד שֶׁיְּקַבְּלוּ שְׁנֵיהֶם. וְהָעַבְדוּת שֶׁיְּקַבְּלוּ הוּא שֶׁיִּהְיוּ נִבְזִים וּשְׁפָלִים לְמַטָּה וְלֹא יָרִימוּ רֹאשׁ בְּיִשְׂרָאֵל אֶלָּא יִהְיוּ כְּבוּשִׁים תַּחַת יָדָם. וְלֹא יִתְמַנּוּ עַל יִשְׂרָאֵל לְשׁוּם דָּבָר שֶׁבָּעוֹלָם. וְהַמַּס שֶׁיְּקַבְּלוּ שֶׁיִּהְיוּ מוּכָנִים לַעֲבוֹדַת הַמֶּלֶךְ בְּגוּפָם וּמָמוֹנָם. כְּגוֹן בִּנְיַן הַחוֹמוֹת. וְחֹזֶק הַמְּצוּדוֹת. וּבִנְיַן אַרְמוֹן הַמֶּלֶךְ וְכַיּוֹצֵא בּוֹ. שֶׁנֶּאֱמַר (מלכים א ט, טו) \"וְזֶה דְבַר הַמַּס אֲשֶׁר הֶעֱלָה הַמֶּלֶךְ שְׁלֹמֹה לִבְנוֹת אֶת בֵּית ה' וְאֶת בֵּיתוֹ וְאֶת הַמִּלּוֹא וְאֵת חוֹמַת יְרוּשָׁלָםִ\" (מלכים א ט, יט) \"וְאֵת כָּל עָרֵי הַמִּסְכְּנוֹת אֲשֶׁר הָיוּ לִשְׁלֹמֹה\" (מלכים א ט, כ) \"כָּל הָעָם הַנּוֹתָר מִן הָאֱמֹרִי\" (מלכים א ט, כא) \"וַיַּעֲלֵם שְׁלֹמֹה לְמַס עֹבֵד עַד הַיּוֹם הַזֶּה\" (מלכים א ט, כב) \"וּמִבְּנֵי יִשְׂרָאֵל לֹא נָתַן שְׁלֹמֹה עָבֶד כִּי הֵם אַנְשֵׁי הַמִּלְחָמָה וַעֲבָדָיו וְשָׂרָיו וְשָׁלִישָׁיו וְשָׂרֵי רִכְבּוֹ וּפָרָשָׁיו\":","וְיֵשׁ לַמֶּלֶךְ לְהַתְנוֹת עִמָּהֶם שֶׁיִּקַּח חֲצִי מָמוֹנָם אוֹ הַקַּרְקָעוֹת וְיַנִּיחַ כָּל הַמִּטַּלְטְלִין אוֹ הַמִּטַּלְטְלִים וְיַנִּיחַ הַקַּרְקָעוֹת כְּפִי מַה שֶּׁיַּתְנֶה:","וְאָסוּר לְשַׁקֵּר בִּבְרִיתָם וּלְכַזֵּב לָהֶם אַחַר שֶׁהִשְׁלִימוּ וְקִבְּלוּ שֶׁבַע מִצְוֹת:","וְאִם לֹא הִשְׁלִימוּ אוֹ שֶׁהִשְׁלִימוּ וְלֹא קִבְּלוּ שֶׁבַע מִצְוֹת. עוֹשִׂין עִמָּהֶם מִלְחָמָה וְהוֹרְגִין כָּל הַזְּכָרִים הַגְּדוֹלִים. וּבוֹזְזִין כָּל מָמוֹנָם וְטַפָּם. וְאֵין הוֹרְגִין אִשָּׁה וְלֹא קָטָן שֶׁנֶּאֱמַר (דברים כ, יד) \"וְהַנָּשִׁים וְהַטָּף\" זֶה טַף שֶׁל זְכָרִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִלְחֶמֶת הָרְשׁוּת שֶׁהוּא עִם שְׁאָר הָאֻמּוֹת. אֲבָל שִׁבְעָה עֲמָמִין וַעֲמָלֵק שֶׁלֹּא הִשְׁלִימוּ אֵין מַנִּיחִין מֵהֶם נְשָׁמָה שֶׁנֶּאֱמַר (דברים כ, טו) \"כֵּן תַּעֲשֶׂה לְכָל\" וְגוֹ' (דברים כ, טז) \"רַק מֵעָרֵי הָעַמִּים\" (דברים כ, טז) \"לֹא תְחַיֶּה כָּל נְשָׁמָה\". וְכֵן הוּא אוֹמֵר בַּעֲמָלֵק (דברים כה, יט) \"תִּמְחֶה אֶת זֵכֶר עֲמָלֵק\". וּמִנַּיִן שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בְּאֵלּוּ שֶׁלֹּא הִשְׁלִימוּ שֶׁנֶּאֱמַר (יהושע יא, יט) \"לֹא הָיְתָה עִיר אֲשֶׁר הִשְׁלִימָה אֶל בְּנֵי יִשְׂרָאֵל בִּלְתִּי הַחִוִּי ישְׁבֵי גִבְעוֹן אֶת הַכּל לָקְחוּ בַמִּלְחָמָה\" (יהושע יא, כ) \"כִּי מֵאֵת ה' הָיְתָה לְחַזֵּק אֶת לִבָּם לִקְרַאת הַמִּלְחָמָה אֶת יִשְׂרָאֵל לְמַעַן הַחֲרִימָם\". מִכְלַל שֶׁשָּׁלְחוּ לָהֶם לְשָׁלוֹם וְלֹא קִבְּלוּ:","שְׁלֹשָׁה כְּתָבִים שָׁלַח יְהוֹשֻׁעַ עַד שֶׁלֹּא נִכְנַס לָאָרֶץ. הָרִאשׁוֹן שָׁלַח לָהֶם מִי שֶׁרוֹצֶה לִבְרֹחַ יִבְרַח. וְחָזַר וְשָׁלַח מִי שֶׁרוֹצֶה לְהַשְׁלִים יַשְׁלִים. וְחָזַר וְשָׁלַח מִי שֶׁרוֹצֶה לַעֲשׂוֹת מִלְחָמָה יַעֲשֶׂה. אִם כֵּן מִפְּנֵי מָה הֶעֱרִימוּ יוֹשְׁבֵי גִּבְעוֹן. לְפִי שֶׁשָּׁלַח לָהֶם בַּכְּלָל וְלֹא קִבְּלוּ. וְלֹא יָדְעוּ מִשְׁפַּט יִשְׂרָאֵל וְדִמּוּ שֶׁשּׁוּב אֵין פּוֹתְחִין לָהֶם לְשָׁלוֹם. וְלָמָּה קָשָׁה הַדָּבָר לַנְּשִׂיאִים וְרָאוּ שֶׁרָאוּי לְהַכּוֹתָם לְפִי חֶרֶב לוּלֵי הַשְּׁבוּעָה. מִפְּנֵי שֶׁכָּרְתוּ לָהֶם בְּרִית וַהֲרֵי הוּא אוֹמֵר (דברים ז, ב) \"לֹא תִכְרֹת לָהֶם בְּרִית\" אֶלָּא הָיָה דִּינָם שֶׁיִּהְיוּ לְמַס עֲבָדִים. וְהוֹאִיל וּבְטָעוּת נִשְׁבְּעוּ לָהֶן בְּדִין הָיָה שֶׁיֵּהָרְגוּ עַל שֶׁהִטְעוּם לוּלֵי חִלּוּל הַשֵּׁם:","עַמּוֹן וּמוֹאָב אֵין שׁוֹלְחִין לָהֶם לְשָׁלוֹם שֶׁנֶּאֱמַר (דברים כג, ז) \"לֹא תִדְרשׁ שְׁלֹמָם וְטֹבָתָם כָּל יָמֶיךָ\". אָמְרוּ חֲכָמִים לְפִי שֶׁנֶּאֱמַר (דברים כ, י) \"וְקָרָאתָ אֵלֶיהָ לְשָׁלוֹם\" יָכוֹל עַמּוֹן וּמוֹאָב כֵּן. תַּלְמוּד לוֹמַר לֹא תִדְרשׁ שְׁלֹמָם וְטֹבָתָם. לְפִי שֶׁנֶּאֱמַר (דברים כג, יז) \"עִמְּךָ יֵשֵׁב בְּקִרְבְּךָ\" (דברים כג, יז) \"בַּטּוֹב לוֹ לֹא תּוֹנֶנּוּ\". יָכוֹל עַמּוֹן וּמוֹאָב כֵּן תַּלְמוּד לוֹמַר וְטֹבָתָם. וְאַף עַל פִּי שֶׁאֵין שׁוֹאֲלִים בִּשְׁלוֹמָם אִם הִשְׁלִימוּ מֵעַצְמָם תְּחִלָּה מְקַבְּלִין אוֹתָן:","כְּשֶׁצָּרִין עַל עִיר לְתָפְשָׂהּ. אֵין מַקִּיפִין אוֹתָהּ מֵאַרְבַּע רוּחוֹתֶיהָ אֶלָּא מִשָּׁלֹשׁ רוּחוֹתֶיהָ. וּמַנִּיחִין מָקוֹם לַבּוֹרֵחַ וּלְכָל מִי שֶׁיִּרְצֶה לְהִמָּלֵט עַל נַפְשׁוֹ. שֶׁנֶּאֱמַר (במדבר לא, ז) \"וַיִּצְבְּאוּ עַל מִדְיָן כַּאֲשֶׁר צִוָּה ה' אֶת משֶׁה\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבְּכָךְ צִוָּהוּ:","אֵין קוֹצְצִין אִילָנֵי מַאֲכָל שֶׁחוּץ לַמְּדִינָה וְאֵין מוֹנְעִין מֵהֶם אַמַּת הַמַּיִם כְּדֵי שֶׁיִּיבְשׁוּ. שֶׁנֶּאֱמַר (דברים כ, יט) \"לֹא תַשְׁחִית אֶת עֵצָהּ\". וְכָל הַקּוֹצֵץ לוֹקֶה. וְלֹא בְּמָצוֹר בִּלְבַד אֶלָּא בְּכָל מָקוֹם כָּל הַקּוֹצֵץ אִילַן מַאֲכָל דֶּרֶךְ הַשְׁחָתָה לוֹקֶה. אֲבָל קוֹצְצִין אוֹתוֹ אִם הָיָה מַזִּיק אִילָנוֹת אֲחֵרִים. אוֹ מִפְּנֵי שֶׁמַּזִּיק בִּשְׂדֵה אֲחֵרִים. אוֹ מִפְּנֵי שֶׁדָּמָיו יְקָרִים. לֹא אָסְרָה תּוֹרָה אֶלָּא דֶּרֶךְ הַשְׁחָתָה:","כָּל אִילַן סְרָק מֻתָּר לָקֹץ אוֹתוֹ וַאֲפִלּוּ אֵינוֹ צָרִיךְ לוֹ. וְכֵן אִילַן מַאֲכָל שֶׁהִזְקִין וְאֵינוֹ עוֹשֶׂה אֶלָּא דָּבָר מוּעָט שֶׁאֵינוֹ רָאוּי לִטְרֹחַ בּוֹ מֻתָּר לָקֹץ אוֹתוֹ. וְכַמָּה יְהֵא הַזַּיִת עוֹשֶׂה וְלֹא יְקֻצֶּנּוּ. רֹבַע הַקַּב זֵיתִים. וְדֶקֶל שֶׁהוּא עוֹשֶׂה קַב תְּמָרִים לֹא יְקֻצֶּנּוּ:","וְלֹא הָאִילָנוֹת בִּלְבַד. אֶלָּא כָּל הַמְשַׁבֵּר כֵּלִים. וְקוֹרֵעַ בְּגָדִים. וְהוֹרֵס בִּנְיָן. וְסוֹתֵם מַעְיָן. וּמְאַבֵּד מַאֲכָלוֹת דֶּרֶךְ הַשְׁחָתָה. עוֹבֵר בְּלֹא תַשְׁחִית. וְאֵינוֹ לוֹקֶה אֶלָּא מַכַּת מַרְדּוּת מִדִּבְרֵיהֶם:","צָרִין עַל עֲיָרוֹת שֶׁל עַכּוּ\"ם שְׁלֹשָׁה יָמִים קֹדֶם הַשַּׁבָּת וְעוֹשִׂין עִמָּהֶם מִלְחָמָה בְּכָל יוֹם וְיוֹם וַאֲפִלּוּ בְּשַׁבָּת. שֶׁנֶּאֱמַר (דברים כ, כ) \"עַד רִדְתָּהּ\" וַאֲפִלּוּ בְּשַׁבָּת. בֵּין מִלְחֶמֶת מִצְוָה בֵּין מִלְחֶמֶת רְשׁוּת:","כְּשֶׁחוֹנִין חוֹנִין בְּכָל מָקוֹם. וּמִי שֶׁנֶּהֱרַג בַּמִּלְחָמָה בַּמָּקוֹם שֶׁיִּפּל שָׁם יִקָּבֵר. קוֹנֶה מְקוֹמוֹ כְּמֵת מִצְוָה:","אַרְבָּעָה דְּבָרִים פָּטְרוּ בַּמַּחֲנֶה. אוֹכְלִים הַדְּמַאי. וּפְטוּרִים מֵרְחִיצַת יָדַיִם בַּתְּחִלָּה. וּמְבִיאִין עֵצִים מִכָּל מָקוֹם. וַאֲפִלּוּ מְצָאָן תְּלוּשִׁים וִיבֵשִׁים אֵין מַקְפִּידִין עַל כָּךְ בַּמַּחֲנֶה. וְכֵן פְּטוּרִין מִלְּעָרֵב עֵרוּבֵי חֲצֵרוֹת בַּמַּחֲנֶה אֶלָּא מְטַלְטְלִין מֵאֹהֶל לְאֹהֶל וּמִסֻּכָּה לְסֻכָּה וְהוּא שֶׁיַּקִּיפוּ כָּל הַמַּחֲנֶה מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים כְּדֵי שֶׁתִּהְיֶה רְשׁוּת יָחִיד כְּמוֹ שֶׁנִּתְבָּאֵר בְּהִלְכוֹת שַׁבָּת. וְאֵין מְחִצָּה פְּחוּתָה מֵעֲשָׂרָה. וּכְשֵׁם שֶׁפְּטוּרִין מִכָּל אֵלּוּ בַּהֲלִיכָתָן כָּךְ פְּטוּרִין בַּחֲזִירָתָן:","וְאָסוּר לְהִפָּנוֹת בְּתוֹךְ הַמַּחֲנֶה אוֹ עַל פְּנֵי הַשָּׂדֶה בְּכָל מָקוֹם. אֶלָּא מִצְוַת עֲשֵׂה לְתַקֵּן שָׁם דֶּרֶךְ מְיֻחֶדֶת לְהִפָּנוֹת בָּהּ. שֶׁנֶּאֱמַר (דברים כג, יג) \"וְיָד תִּהְיֶה לְךָ מִחוּץ לַמַּחֲנֶה\":","וְכֵן מִצְוַת עֲשֵׂה לִהְיוֹת יָתֵד לְכָל אֶחָד וְאֶחָד תְּלוּיָה עִם כְּלֵי מִלְחַמְתּוֹ. וְיֵצֵא בְּאוֹתָהּ הַדֶּרֶךְ וְיַחְפֹּר בָּהּ וְיִפָּנֶה וִיכַסֶּה. שֶׁנֶּאֱמַר (דברים כג, יד) \"וְיָתֵד תִּהְיֶה לְךָ עַל אֲזֵנֶךָ\" וְגוֹ'. וּבֵין שֶׁיֵּשׁ עִמָּהֶן אָרוֹן וּבֵין שֶׁאֵין עִמָּהֶן אָרוֹן כָּךְ הֵם עוֹשִׂים תָּמִיד. שֶׁנֶּאֱמַר (דברים כג, טו) \"וְהָיָה מַחֲנֶיךָ קָדוֹשׁ\":"],"Mishneh Torah, Leavened and Unleavened Bread 9":["נוסח ההגדה שנהגו בה ישראל בזמן הגלות כך הוא, מתחיל על כוס שני ואומר:","בבהילו יצאנו ממצרים. הא לחמא עניא דאכלו אבהתנא בארעא דמצרים: כל דכפין ייתי וייכול, כל דצריך לפסח ייתי ויפסח. שתא הכא, לשנה הבאה בארעא דישראל. שתא הדא עבדי, לשתא דאתיא בני חורי.","מה נשתנה הלילה הזה מכל הלילות! שבכל הלילות אין אנו מטבילין אפילו פעם אחת, והלילה הזה שתי פעמים. שבכל הלילות אנו אוכלים חמץ ומצה, והלילה הזה כולו מצה. שבכל הלילות אנו אוכלים שאר ירקות, והלילה הזה מרור. שבכל הלילות אנו אוכלין בין יושבין בין מסובין, והלילה הזה כולנו מסובין.","עבדים היינו לפרעה במצרים, ויוציאנו יי אלהינו משם ביד חזקה ובזרוע נטויה. ואילו לא הוציא הקדוש ברוך הוא את אבותינו ממצרים, עדיין אנו ובנינו ובני בנינו משועבדים היינו לפרעה במצרים. ואפילו כולנו חכמים, כולנו נבונים, כולנו זקנים, כולנו יודעים את התורה – מצוה עלינו לספר ביציאת מצרים. וכל המאריך ביציאת מצרים – הרי זה משובח.","מעשה ברבי אליעזר, ורבי יהושע, ורבי אלעזר בן עזריה, ורבי עקיבה, ורבי טרפון, שהיו מסובין בבני ברק. והיו מספרין ביציאת מצרים כל אותו הלילה, עד שבאו תלמידיהם ואמרו להם: רבותינו! הגיע זמן קריאת שמע של שחרית.","אמר להם רבי אלעזר בן עזריה: הרי אני כבן שבעים שנה, ולא זכיתי שתאמר יציאת מצרים בלילות, עד שדרשה בן זומא, שנאמר (דברים ט״ז:ג׳): \"למען תזכור את יום צאתך מארץ מצרים כל ימי חייך\" – \"ימי חייך\" הימים, \"כל ימי חייך\" הלילות. וחכמים אומרים: \"ימי חייך\" העולם הזה, \"כל ימי חייך\" להביא את ימות המשיח.","ברוך המקום שנתן תורה לישראל עמו, ברוך הוא. כנגד ארבעה בנים דברה תורה: אחד חכם, ואחד רשע, ואחד תם, ואחד שאינו יודע לשאל.","חכם מה הוא אומר: \"מה העדות והחקים והמשפטים אשר צוה יי אלהינו אתכם\" (דברים ו׳:כ׳). אף אתה אמור לו כהלכות הפסח: אין מפטירין אחר הפסח אפיקומן.","רשע מה הוא אומר: \"מה העבודה הזאת לכם\" (שמות י״ב:כ״ו). \"לכם\" ולא לו, ולפי שהוציא את עצמו מן הכלל כפר בעיקר. אף אתה הקהה את שניו ואמור לו (שמות י״ג:ח׳): \"בעבור זה עשה יי לי בצאתי ממצרים\". \"לי\" ולא לו, ואילו היה שם לא היה נגאל.","תם מה הוא אומר: \"מה זאת?\" (שמות י״ג:י״ד). ואמרת אליו: \"בחוזק יד הוציאנו יי ממצרים מבית עבדים\".","ושאינו יודע לשאל את פתח לו, שנאמר (שמות י״ג:ח׳): \"והגדת לבנך ביום ההוא לאמר: בעבור זה עשה יי לי בצאתי ממצרים\". \"והגדת לבנך\" יכול מראש חודש? תלמוד לומר \"ביום ההוא\". אי \"ביום ההוא\" יכול מבעוד יום? תלמוד לומר \"בעבור זה\" – לא אמרתי אלא בשעה שמצה ומרור מונחים לפניך.","מתחילה עובדי עבודה זרה היו אבותינו, ועכשיו קרבנו המקום ברוך הוא לעבודתו, שנאמר (יהושע כ״ד:ב׳): \"ויאמר יהושע אל כל העם, כה אמר יי אלהי ישראל: בעבר הנהר ישבו אבותיכם מעולם, תרח אבי אברהם ואבי נחור, ויעבדו אלהים אחרים. ואקח את אביכם את אברהם מעבר הנהר, ואולך אותו בכל ארץ כנען. וארבה את זרעו ואתן לו את יצחק. ואתן ליצחק את יעקב ואת עשו. ואתן לעשו את הר שעיר לרשת אותו, ויעקב ובניו ירדו מצרים\".","ברוך שומר הבטחתו לישראל עמו, ברוך הוא! שהקדוש ברוך הוא מחשב את הקץ לעשות כמו שאמר לאברהם אבינו בין הבתרים, שנאמר (בראשית ט״ו:י״ג): \"ויאמר לאברם: ידוע תדע כי גר יהיה זרעך בארץ לא להם, ועבדום וענו אותם ארבע מאות שנה. וגם את הגוי אשר יעבודו דן אנכי, ואחרי כן יצאו ברכוש גדול\".","היא שעמדה לאבותינו ולנו, שלא אחד בלבד עמד עלינו. אלא בכל דור ודור עומדים עלינו לכלותינו, והקדוש ברוך הוא מצילנו מידם. צא ולמד מה בקש לבן הארמי לעשות ליעקב אבינו: שפרעה הרשע לא גזר אלא על הזכרים, ולבן בקש לעקור את הכל, שנאמר (דברים כ״ו:ה׳): \"ארמי אובד אבי, וירד מצרימה ויגר שם\" – מלמד שלא ירד להשתקע אלא לגור שם, שנאמר (בראשית מ״ז:ד׳): \"ויאמרו אל פרעה: לגור בארץ באנו, כי אין מרעה לצאן אשר לעבדיך, כי כבד הרעב בארץ כנען. ועתה ישבו נא עבדיך בארץ גשן\".","\"במתי מעט\", כמו שנאמר (דברים י׳:כ״ב): \"בשבעים נפש ירדו אבותיך מצרימה, ועתה שמך יי אלהיך ככוכבי השמים לרוב\".","\"ויהי שם לגוי\" – מלמד שהיו ישראל מצויינין שם. \"גדול ועצום\", כמו שנאמר (שמות א׳:ז׳): ובני ישראל פרו וישרצו וירבו ויעצמו במאד מאד, ותמלא הארץ אותם\".","ורב, כמו שנאמר (יחזקאל ט״ז:ז׳): \"רבבה כצמח השדה נתתיך, ותרבי ותגדלי ותבאי בעדי עדיים שדים נכונו ושערך צמח, ואת ערום ועריה\".","\"וירעו אותנו המצרים\", כמו שנאמר (שמות א׳:י׳): \"הבה נתחכמה לו, פן ירבה והיה כי תקראנה מלחמה ונוסף גם הוא על שונאינו, ונלחם בנו ועלה מן הארץ\".","\"ויענונו\", כמו שנאמר: \"וישימו עליו שרי מסים למען ענותו בסבלותם, ויבן ערי מסכנות לפרעה, את פיתום ואת רעמסס\".","\"ויתנו עלינו עבודה קשה\", כמו שנאמר: \"ויעבידו מצרים את בני ישראל בפרך\".","\"ונצעק אל יי אלהי אבותינו\", כמו שנאמר (שמות ב׳:כ״ג): ויהי בימים הרבים ההם וימת מלך מצרים, ויאנחו בני ישראל מן העבודה ויזעקו, ותעל שועתם אל האלהים מן העבודה\".","\"וישמע יי את קולנו\", כמו שנאמר: \"וישמע אלהים את נאקתם, ויזכור אלהים את בריתו את אברהם את יצחק ואת יעקב\".","\"וירא את עניינו\" – זו פרישות דרך ארץ, כמו שנאמר: \"וירא אלהים את בני ישראל וידע אלהים\".","\"ואת עמלינו\" – אלו הבנים, כמו שנאמר: \"כל הבן הילוד היאורה תשליכוהו, וכל הבת תחיון\".","\"ואת לחצינו\" – זה הדוחק, כמו שנאמר (שמות ג ט): \"וגם ראיתי את הלחץ אשר מצרים לוחצים אותם\".","\"ויוציאנו יי ממצרים\" – לא על ידי מלאך, לא על ידי שרף, ולא על ידי שליח. אלא הקדוש ברוך הוא בכבודו, שנאמר: (שמות י״ב:י״ב): \"ועברתי בארץ מצרים בלילה הזה, והכיתי כל בכור בארץ מצרים מאדם ועד בהמה, ובכל אלהי מצרים אעשה שפטים. אני יי\".","\"ביד חזקה\" – זה הדבר, כמו שנאמר (שמות ט׳:ג׳): \"הנה יד יי הויה במקנך אשר בשדה, בסוסים בחמורים בגמלים בבקר ובצאן, דבר כבד מאד\".","\"ובזרוע נטויה\" – זו החרב, כמו שנאמר (דברי הימים א כ״א:ט״ז): \"וחרבו שלופה בידו, נטויה על ירושלם\".","\"ובמורא גדול\" – זו גלוי שכינה, כמו שנאמר (דברים ד׳:ל״ד): \"או הנסה אלהים לבא לקחת לו גוי מקרב גוי, במסות באותות ובמופתים ובמלחמה, וביד חזקה ובזרוע נטויה ובמוראים גדולים, ככל אשר עשה לכם יי אלהיכם במצרים לעיניך\".","\"ובאותות\" – זה המטה, כמו שנאמר (שמות ד): \"ואת המטה הזה תקח בידך, אשר תעשה בו את האותות\".","\"ובמופתים\" – זה הדם, כמו שנאמר (יואל ג): \"ונתתי מופתים בשמים ובארץ, דם ואש ותמרות עשן\".","דבר אחר: \"ביד חזקה\" – שתים, \"ובזרוע נטויה\" – שתים, \"ובמורא גדול\" – שתים, \"ובאותות\" – שתים, \"ובמופתים\" – שתים. אלו עשר מכות שהביא הקדוש ברוך הוא על המצרים במצרים, ואלו הן: דם, צפרדע, כנים, ערוב, דבר, שחין, ברד, ארבה, חושך, מכת בכורות. רבי יהודה היה נותן בהם סימן: דצ\"ך עד\"ש באח\"ב.","רבן גמליאל אומר: כל שלא אמר שלושה דברים אלו בפסח, לא יצא ידי חובתו: פסח, מצה, ומרורים.","פסח שהיו אבותינו אוכלין בזמן שבית המקדש קיים, על שם מה? על שם שפסח המקום על בתי אבותינו במצרים, שנאמר (שמות יב): \"ואמרתם זבח פסח הוא ליי, אשר פסח על בתי בני ישראל במצרים, בנגפו את מצרים ואת בתינו הציל. ויקד העם וישתחוו\".","מצה זו שאנו אוכלין, על שם מה? על שם שלא הספיק בצקם של אבותינו להחמיץ, עד שנגלה עליהם מלך מלכי המלכים הקדוש ברוך הוא וגאלם מיד, שנאמר (שמות יב): \"ויאפו את הבצק אשר הוציאו ממצרים, עוגות מצות כי לא חמץ, כי גורשו ממצרים ולא יכלו להתמהמה, וגם צדה לא עשו להם\".","מרורים אלו שאנו אוכלים, על שם מה? על שם שמררו המצרים את חיי אבותינו במצרים, שנאמר (שמות א): \"וימררו את חייהם בעבודה קשה, בחומר ובלבנים ובכל עבודה בשדה, את כל עבודתם אשר עבדו בהם בפרך\".","ובכל דור ודור חייב אדם להראות את עצמו כאילו הוא יצא ממצרים. שלא את אבותינו בלבד גאל אלא אף אותנו גאל, שנאמר (דברים ו): \"ואותנו הוציא משם, למען הביא אותנו לתת לנו את הארץ אשר נשבע לאבותינו\".","לפיכך אנו חייבים להודות, להלל, לשבח, לפאר, לרומם, לגדל, ולהדר, ולנצח למי שעשה לנו ולאבותינו את כל הנסים האלו, והוציאנו מעבדות לחירות, ומשעבוד לגאולה, ומיגון לשמחה, ומאבל ליום טוב, ומאפלה לאור גדול. ונאמר לפניו: \"הללויה\".","\"הללויה! הללו עבדי יי, הללו את שם יי! יהי שם יי מבורך...\" עד \"חלמיש למעינו מים\" (תהלים קיג-קיד).","ברוך אתה יי, אלהינו מלך העולם, אשר גאלנו וגאל את אבותינו ממצרים, והגיענו ללילה הזה לאכול בו מצה ומרורים. כן יי אלהינו ואלהי אבותינו, יגיענו למועדים ולרגלים אחרים הבאים לקראתנו לשלום, שמחים בבנין עירך וששים בעבודתך. ונאכל שם מן הזבחים ומן הפסחים שיגיע דמם על קיר מזבחך לרצון, ונודה לך שיר חדש על גאולתנו ועל פדות נפשנו. ברוך אתה יי, גאל ישראל.","כסדר שמברכין וקוראים ההגדה בליל יום טוב ראשון של פסח, כך מברכים וקוראים בליל השני של גליות. וכן חייבין בליל השני בארבעה כוסות, ובשאר הדברים שנעשו בלילה הראשון."],"Mishneh Torah, Marriage 12":["כְּשֶׁנּוֹשֵׂא אָדָם אִשָּׁה בֵּין בְּתוּלָה בֵּין בְּעוּלָה בֵּין גְּדוֹלָה בֵּין קְטַנָּה אַחַת בַּת יִשְׂרָאֵל וְאַחַת הַגִּיֹּרֶת אוֹ הַמְשֻׁחְרֶרֶת יִתְחַיֵּב לָהּ בַּעֲשָׂרָה דְּבָרִים וְיִזְכֶּה בְּאַרְבָּעָה דְּבָרִים:","וְהָעֲשָׂרָה שְׁלֹשָׁה מֵהֶן מִן הַתּוֹרָה וְאֵלּוּ הֵן. (שמות כא י) \"שְׁאֵרָהּ. כְּסוּתָהּ. וְעוֹנָתָהּ\". שְׁאֵרָהּ אֵלּוּ מְזוֹנוֹתֶיהָ. כְּסוּתָהּ כְּמַשְׁמָעוֹ. עוֹנָתָהּ לָבֹא עָלֶיהָ כְּדֶרֶךְ כָּל הָאָרֶץ. וְהַשִּׁבְעָה מִדִּבְרֵי סוֹפְרִים וְכֻלָּן תְּנַאי בֵּית דִּין הֵם. הָאֶחָד מֵהֶם עִקַּר כְּתֻבָּה. וְהַשְּׁאָר הֵם הַנִּקְרָאִין תְּנָאֵי כְּתֻבָּה וְאֵלּוּ הֵן. לְרַפֹּאתָהּ אִם חָלְתָה. וְלִפְדּוֹתָהּ אִם נִשְׁבֵּית. לְקָבְרָהּ אִם מֵתָה. וְלִהְיוֹת נִזּוֹנֶת מִן נְכָסָיו. וְיוֹשֶׁבֶת בְּבֵיתוֹ אַחַר מוֹתוֹ כָּל זְמַן אַלְמְנוּתָהּ. וְלִהְיוֹת בְּנוֹתֶיהָ מִמֶּנּוּ נִזּוֹנוֹת מִנְּכָסָיו אַחֲרֵי מוֹתוֹ עַד שֶׁתִּתְאָרֵסְנָה. וְלִהְיוֹת בָּנֶיהָ הַזְּכָרִים מִמֶּנּוּ יוֹרְשִׁין כְּתֻבָּתָהּ יוֹתֵר עַל חֶלְקָם בַּיְרֻשָּׁה שֶׁעִם אֲחֵיהֶם:","וְהָאַרְבָּעָה שֶׁזּוֹכָה בָּהֶן כֻּלָּם מִדִּבְרֵי סוֹפְרִים וְאֵלּוּ הֵן. לִהְיוֹת מַעֲשֵׂה יָדֶיהָ שֶׁלּוֹ. וְלִהְיוֹת מְצִיאָתָהּ שֶׁלּוֹ. וְשֶׁיִּהְיֶה אוֹכֵל כָּל פֵּרוֹת נְכָסֶיהָ בְּחַיֶּיהָ. וְאִם מֵתָה בְּחַיָּיו יִירָשֶׁנָּה. וְהוּא קוֹדֵם לְכָל אָדָם בַּיְרֻשָּׁה:","וְעוֹד תִּקְּנוּ חֲכָמִים שֶׁיִּהְיוּ מַעֲשֵׂה יְדֵי הָאִשָּׁה כְּנֶגֶד מְזוֹנוֹתֶיהָ. וּפִדְיוֹנָהּ כְּנֶגֶד אֲכִילַת פֵּרוֹת נְכָסֶיהָ. וּקְבוּרָתָהּ כְּנֶגֶד יְרֻשָּׁתוֹ לִכְתֻבָּתָהּ. לְפִיכָךְ אִם אָמְרָה הָאִשָּׁה אֵינִי נִזּוֹנִית וְאֵינִי עוֹשָׂה שׁוֹמְעִין לָהּ וְאֵין כּוֹפִין אוֹתָהּ. אֲבָל אִם אָמַר הַבַּעַל אֵינִי זָנֵךְ וְאֵינִי נוֹטֵל כְּלוּם מִמַּעֲשֵׂה יָדַיִךְ אֵין שׁוֹמְעִין לוֹ שֶׁמָּא לֹא יְסַפְּקוּ לָהּ מַעֲשֵׂה יָדֶיהָ בִּמְזוֹנוֹתֶיהָ. וּמִפְּנֵי תַּקָּנָה זוֹ יֵחָשְׁבוּ הַמְּזוֹנוֹת מִתְּנָאֵי הַכְּתֻבָּה:","כָּל הַדְּבָרִים הָאֵלּוּ אַף עַל פִּי שֶׁלֹּא נִכְתְּבוּ בִּשְׁטַר הַכְּתֻבָּה וַאֲפִלּוּ לֹא כָּתְבוּ כְּתֻבָּה אֶלָּא נָשָׂא סְתָם כֵּיוָן שֶׁנְּשָׂאָהּ זָכָה בְּאַרְבָּעָה דְּבָרִים שֶׁלּוֹ וְזָכְתָה הָאִשָּׁה בַּעֲשָׂרָה דְּבָרִים שֶׁלָּהּ וְאֵינָן צְרִיכִין לְפָרֵשׁ:","הִתְנָה הַבַּעַל שֶׁלֹּא יִתְחַיֵּב בְּאֶחָד מִן הַדְּבָרִים שֶׁהוּא חַיָּב בָּהֶן. אוֹ שֶׁהִתְנַת הָאִשָּׁה שֶׁלֹּא יִזְכֶּה הַבַּעַל בְּאֶחָד מִן הַדְּבָרִים שֶׁהוּא זוֹכֶה בָּהֶם הַתְּנַאי קַיָּם חוּץ מִשְּׁלֹשָׁה דְּבָרִים שֶׁאֵין הַתְּנַאי מוֹעִיל בָּהֶן. וְכָל הַמַּתְנֶה עֲלֵיהֶן תְּנָאוֹ בָּטֵל. וְאֵלּוּ הֵן. עוֹנָתָהּ. וְעִקַּר כְּתֻבָּתָהּ. וִירֻשָּׁתָהּ:","כֵּיצַד. הִתְנָה עִם הָאִשָּׁה שֶׁאֵין לָהּ עָלָיו עוֹנָה תְּנָאוֹ בָּטֵל וְחַיָּב בְּעוֹנָתָהּ. שֶׁהֲרֵי הִתְנָה עַל מַה שֶּׁכָּתוּב בַּתּוֹרָה וְאֵינוֹ תְּנַאי מָמוֹן:","הִתְנָה עִמָּהּ לִפְחֹת מֵעִקַּר כְּתֻבָּה אוֹ שֶׁכָּתַב לָהּ מָאתַיִם אוֹ מֵאָה עִקַּר כְּתֻבָּה וְכָתְבָה לוֹ שֶׁנִּתְקַבְּלָה מֵהֶן כָּךְ וְכָךְ וְהִיא לֹא נִתְקַבְּלָה תְּנָאוֹ בָּטֵל שֶׁכָּל הַפּוֹחֵת לִבְתוּלָה מִמָּאתַיִם וּלְאַלְמָנָה מִמֵּאָה הֲרֵי בְּעִילָתוֹ בְּעִילַת זְנוּת:","הִתְנָה עִמָּהּ אַחַר שֶׁנְּשָׂאָהּ שֶׁלֹּא יִירָשֶׁנָּה תְּנָאוֹ בָּטֵל וְאַף עַל פִּי שֶׁיְּרֻשַּׁת הַבַּעַל מִדִּבְרֵי סוֹפְרִים עָשׂוּ חִזּוּק לְדִבְרֵיהֶם כְּשֶׁל תּוֹרָה. וְכָל תְּנַאי שֶׁבַּיְרֻשָּׁה בָּטֵל וְאַף עַל פִּי שֶׁהוּא מָמוֹן שֶׁנֶּאֱמַר בָּהּ (במדבר כז יא) \"לְחֻקַּת מִשְׁפָּט\". וּבִשְׁאָר הַדְּבָרִים תְּנָאוֹ קַיָּם, כְּגוֹן שֶׁהִתְנָה עִמָּהּ שֶׁאֵין לָהּ שְׁאֵר וּכְסוּת, עַל מְנָת שֶׁלֹּא יֹאכַל פֵּרוֹת נְכָסֶיהָ, וְכָל כַּיּוֹצֵא בָּזֶה, תְּנָאוֹ קַיָּם:","כַּמָּה מְזוֹנוֹת פּוֹסְקִין לָאִשָּׁה. פּוֹסְקִין לָהּ לֶחֶם שְׁתֵּי סְעֻדּוֹת בְּכָל יוֹם סְעֻדָּה בֵּינוֹנִית שֶׁל כָּל אָדָם בְּאוֹתָהּ הָעִיר כְּאָדָם שֶׁאֵינוֹ לֹא חוֹלֶה וְלֹא גַּרְגְּרָן וּמֵאוֹתוֹ מַאֲכָל שֶׁל אַנְשֵׁי אוֹתָהּ הָעִיר. אִם חִטִּים חִטִּים וְאִם שְׂעוֹרִים שְׂעוֹרִים. וְכֵן אֹרֶז וְדֹחַן אוֹ מִשְּׁאָר מִינִין שֶׁנָּהֲגוּ בָּהֶן. וּפוֹסְקִין לָהּ פַּרְפֶּרֶת לֶאֱכל בָּהּ אֶת הַפַּת כְּגוֹן קִטְנִית אוֹ יְרָקוֹת וְכַיּוֹצֵא בָּהֶן. וְשֶׁמֶן לַאֲכִילָה וְשֶׁמֶן לְהַדְלָקַת הַנֵּר וּפֵרוֹת וּמְעַט יַיִן לִשְׁתּוֹת אִם הָיָה מִנְהַג הַמָּקוֹם שֶׁיִּשְׁתּוּ הַנָּשִׁים יַיִן. וּפוֹסְקִין לָהּ שָׁלֹשׁ סְעֻדּוֹת בְּשַׁבָּת וּבָשָׂר אוֹ דָּגִים כְּמִנְהַג הַמָּקוֹם. וְנוֹתֵן לָהּ בְּכָל שַׁבָּת וְשַׁבָּת מָעָה כֶּסֶף לִצְרָכֶיהָ כְּגוֹן פְּרוּטָה לְכִבּוּס אוֹ לְמֶרְחָץ וְכַיּוֹצֵא בָּהֶן:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּעָנִי שֶׁבְּיִשְׂרָאֵל אֲבָל אִם הָיָה עָשִׁיר הַכּל לְפִי עָשְׁרוֹ. אֲפִלּוּ הָיָה מָמוֹנוֹ רָאוּי לַעֲשׂוֹת לָהּ כַּמָּה תַּבְשִׁילֵי בָּשָׂר בְּכָל יוֹם כּוֹפִין אוֹתוֹ וּפוֹסְקִין לָהּ מְזוֹנוֹת כְּפִי מָמוֹנוֹ. וְאִם הָיָה עָנִי בְּיוֹתֵר וְאֵינוֹ יָכוֹל לִתֵּן לָהּ אֲפִלּוּ לֶחֶם שֶׁהִיא צְרִיכָה לוֹ כּוֹפִין אוֹתוֹ לְהוֹצִיא וְתִהְיֶה כְּתֻבָּתָהּ חוֹב עָלָיו עַד שֶׁתִּמְצָא יָדוֹ וְיִתֵּן:","בַּעַל שֶׁרָצָה לִתֵּן לְאִשְׁתּוֹ מְזוֹנוֹתֶיהָ הָרְאוּיוֹת לָהּ וְתִהְיֶה אוֹכֶלֶת וְשׁוֹתָה לְעַצְמָהּ וְהוּא שׁוֹתֶה וְאוֹכֵל לְעַצְמוֹ הָרְשׁוּת בְּיָדוֹ וּבִלְבַד שֶׁיֹּאכַל עִמָּהּ מִלֵּילֵי שַׁבָּת לְלֵילֵי שַׁבָּת:","הָאִשָּׁה שֶׁפָּסְקוּ לָהּ מְזוֹנוֹת וְהוֹתִירוּ הַמּוֹתָר לַבַּעַל. הָיָה בַּעְלָהּ כֹּהֵן אֵינוֹ נוֹתֵן לָהּ כָּל מְזוֹנוֹתֶיהָ תְּרוּמָה מִפְּנֵי שֶׁטֹּרַח גָּדוֹל הוּא לָהּ לְשָׁמְרָן מִדְּבָרִים הַמְטַמְּאִין וּלְאָכְלָן בְּטָהֳרָה אֶלָּא נוֹתֵן לָהּ מֶחֱצָה חֻלִּין וּמֶחֱצָה תְּרוּמָה:","כְּשֵׁם שֶׁאָדָם חַיָּב בִּמְזוֹנוֹת אִשְׁתּוֹ כָּךְ הוּא חַיָּב בִּמְזוֹנוֹת בָּנָיו וּבְנוֹתָיו הַקְּטַנִּים עַד שֶׁיִּהְיוּ בְּנֵי שֵׁשׁ שָׁנִים. מִכָּאן וְאֵילָךְ מַאֲכִילָן עַד שֶׁיִּגְדְּלוּ כְּתַקָּנַת חֲכָמִים. וְאִם לֹא רָצָה גּוֹעֲרִין בּוֹ וּמַכְלִימִין אוֹתוֹ וּפוֹצְרִין בּוֹ. וְאִם לֹא רָצָה מַכְרִיזִין עָלָיו בַּצִּבּוּר וְאוֹמְרִים פְּלוֹנִי אַכְזָרִי הוּא וְאֵינוֹ רוֹצֶה לָזוּן בָּנָיו וַהֲרֵי פָּחוּת הוּא מֵעוֹף טָמֵא שֶׁהוּא זָן אֶת אֶפְרוֹחָיו. וְאֵין כּוֹפִין אוֹתוֹ לְזוּנָם אַחַר שֵׁשׁ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאִישׁ שֶׁאֵינוֹ אָמוּד וְאֵין יָדוּעַ אִם רָאוּי לִתֵּן צְדָקָה אוֹ אֵינוֹ רָאוּי אֲבָל אִם הָיָה אָמוּד שֶׁיֵּשׁ לוֹ מָמוֹן הָרָאוּי לִתֵּן מִמֶּנּוּ צְדָקָה הַמַּסְפֶּקֶת לָהֶן מוֹצִיאִין מִמֶּנּוּ בַּעַל כָּרְחוֹ מִשּׁוּם צְדָקָה וְזָנִין אוֹתָן עַד שֶׁיִּגְדְּלוּ:","מִי שֶׁהָלַךְ לִמְדִינָה אַחֶרֶת וּבָאָה אִשְׁתּוֹ לְבֵית דִּין לִתְבֹּעַ מְזוֹנוֹת. שְׁלֹשָׁה חֳדָשִׁים הָרִאשׁוֹנִים מִיּוֹם הֲלִיכָתוֹ אֵין פּוֹסְקִין לָהּ בָּהֶן מְזוֹנוֹת שֶׁחֲזָקָה שֶׁאֵין אָדָם מַנִּיחַ בֵּיתוֹ רֵיקָן. מִכָּאן וְאֵילָךְ פּוֹסְקִין לָהּ מְזוֹנוֹת. וְאִם הָיוּ לוֹ נְכָסִים בֵּית דִּין יוֹרְדִין לִנְכָסָיו וּמוֹכְרִין לִמְזוֹנוֹתֶיהָ. וְאֵין מְחַשְּׁבִין עִמָּהּ עַל מַעֲשֵׂה יָדֶיהָ עַד שֶׁיָּבוֹא בַּעְלָהּ, אִם מָצָא שֶׁעָשְׂתָה הֲרֵי אֵלּוּ שֶׁלּוֹ. וְכֵן אִם לֹא עָמְדָה בַּדִּין אֶלָּא מָכְרָה לְעַצְמָהּ לִמְזוֹנוֹת מִכְרָהּ קַיָּם וְאֵינָהּ צְרִיכָה הַכְרָזָה וְלֹא שְׁבוּעָה עַד שֶׁיָּבוֹא בַּעְלָהּ וְיִטְעֹן אוֹ עַד שֶׁתָּבוֹא לִגְבּוֹת כְּתֻבָּתָהּ אַחַר מוֹתוֹ מְגַלְגְּלִין עָלֶיהָ שֶׁלֹּא מָכְרָה אֶלָּא לִמְזוֹנוֹת שֶׁהִיא צְרִיכָה לָהֶן:","וּכְשֵׁם שֶׁבֵּית דִּין מוֹכְרִין לִמְזוֹן הָאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ כָּךְ מוֹכְרִין לִמְזוֹן בָּנָיו וּבְנוֹתָיו כְּשֶׁהֵן בְּנֵי שֵׁשׁ שָׁנִים אוֹ פָּחוֹת. אֲבָל יֶתֶר עַל שֵׁשׁ אֵינָן זָנִין אוֹתָן מִנְּכָסָיו שֶׁלֹּא בְּפָנָיו אַף עַל פִּי שֶׁהוּא אָמוּד. וְכֵן מִי שֶׁנִּשְׁתַּטָּה בֵּית דִּין יוֹרְדִין לִנְכָסָיו וּמוֹכְרִים וְזָנִין אִשְׁתּוֹ וּבָנָיו וּבְנוֹתָיו שֶׁהֵן בְּנֵי שֵׁשׁ שָׁנִים אוֹ פָּחוֹת וּמְפַרְנְסִין אוֹתָן:","יֵשׁ מִן הַגְּאוֹנִים שֶׁהוֹרָה שֶׁאֵין פּוֹסְקִין מְזוֹנוֹת לְאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם אוֹ שֶׁמֵּת בַּעְלָהּ עַד שֶׁיְּהֵא שְׁטַר כְּתֻבָּה יוֹצֵא מִתַּחַת יָדָהּ. וְאִם לֹא תּוֹצִיא שְׁטַר כְּתֻבָּה אֵין לָהּ מְזוֹנוֹת שֶׁמָּא נָטְלָה כְּתֻבָּתָהּ מִבַּעְלָהּ אוֹ מָחֲלָה לוֹ כְּתֻבָּתָהּ שֶׁאֵין לָהּ מְזוֹנוֹת כְּמוֹ שֶׁיִּתְבָּאֵר. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁפּוֹסְקִין לָהּ מְזוֹנוֹת בְּחֶזְקַת שֶׁלֹּא נָטְלָה וְלֹא מָחֲלָה וְאֵין מַצְרִיכִין אוֹתָהּ לְהָבִיא כְּתֻבָּה. וְדַעְתִּי נוֹטָה לָזֶה בְּמִי שֶׁהָלַךְ בַּעְלָהּ הוֹאִיל וְיֵשׁ לָהּ מְזוֹנוֹת מִן הַתּוֹרָה. אֲבָל אִם מֵת בַּעְלָהּ אֵין לָהּ מְזוֹנוֹת עַד שֶׁתָּבִיא כְּתֻבָּה. מִפְּנֵי שֶׁהִיא אוֹכֶלֶת בְּתַקָּנַת חֲכָמִים וְעוֹד שֶׁנִּזֹּנֶת מִנִּכְסֵי יוֹרְשִׁים וּלְעוֹלָם טוֹעֲנִין לְיוֹרֵשׁ:","הָלַךְ בַּעְלָהּ וְלָוְתָה וְאָכְלָה כְּשֶׁיָּבוֹא חַיָּב לְשַׁלֵּם. עָמַד אֶחָד מִדַּעַת עַצְמוֹ וְזָנָהּ מִשֶּׁלּוֹ אִם יָבוֹא הַבַּעַל אֵינוֹ חַיָּב לְשַׁלֵּם לוֹ וַהֲרֵי זֶה אִבֵּד אֶת מְעוֹתָיו מִפְּנֵי שֶׁלֹּא צִוָּהוּ לְזוּנָהּ וְהִיא לֹא לָוְתָה מִמֶּנּוּ:","הַבַּעַל שֶׁאָמַר לְאִשְׁתּוֹ בְּשָׁעָה שֶׁהָלַךְ טְלִי מַעֲשֵׂה יָדַיִךְ בִּמְזוֹנוֹתַיִךְ אֵין לָהּ מְזוֹנוֹת שֶׁאִלּוּ לֹא רָצְתָה בְּדָבָר זֶה וְלֹא סָמְכָה דַּעְתָּהּ הָיָה לָהּ לְתָבְעוֹ אוֹ לוֹמַר לוֹ אֵין מַעֲשֵׂה יָדַי מַסְפִּיקִין לִי:","הֲרֵי שֶׁעָמְדָה בַּדִּין וּפָסְקוּ לָהּ מְזוֹנוֹת וּמָכְרוּ בֵּין דִּין וְנָתְנוּ לָהּ. אוֹ שֶׁמָּכְרָה הִיא לְעַצְמָהּ וּבָא הַבַּעַל וְאָמַר הִנַּחְתִּי לָהּ מְזוֹנוֹת. הֲרֵי זוֹ נִשְׁבַּעַת בִּנְקִיטַת חֵפֶץ שֶׁלֹּא הִנִּיחַ לָהּ. לֹא תָּבְעָה וְלֹא מָכְרָה אֶלָּא שָׁהֲתָה עַד שֶׁבָּא הוּא אוֹמֵר הִנַּחְתִּי וְהִיא אוֹמֶרֶת לֹא הִנַּחְתָּ אֶלָּא לָוִיתִי מִזֶּה וְנִתְפַּרְנַסְתִּי. נִשְׁבָּע שְׁבוּעַת הֶסֵּת שֶׁהִנִּיחַ לָהּ וְנִפְטָר וְיִשָּׁאֵר הַחוֹב עָלֶיהָ:","מָכְרָה מִטַּלְטְלִין וְאָמְרָה לִמְזוֹנוֹת מָכַרְתִּי וְהוּא טוֹעֵן וְאוֹמֵר מְזוֹנוֹתַיִךְ הִנַּחְתִּי נִשְׁבַּעַת שְׁבוּעַת הֶסֵּת שֶׁלֹּא הִנִּיחַ. הֲרֵי שֶׁלֹּא תָּבְעָה וְלֹא לָוְתָה וְלֹא מָכְרָה אֶלָּא דָּחֲקָה עַצְמָהּ בַּיּוֹם וּבַלַּיְלָה וְעָשְׂתָה וְאָכְלָה אֵין לָהּ כְּלוּם:","הַמַּדִּיר אֶת אִשְׁתּוֹ מִלֵּהָנוֹת לוֹ בֵּין שֶׁפֵּרֵשׁ עַד זְמַן פְּלוֹנִי בֵּין שֶׁלֹּא פֵּרֵשׁ אֶלָּא סְתָם מַמְתִּינִין לוֹ שְׁלֹשִׁים יוֹם. אִם תַּמּוּ יְמֵי נִדְרוֹ אוֹ שֶׁלֹּא תַּמּוּ וְהִתִּיר נִדְרוֹ הֲרֵי זֶה מוּטָב וְאִם לָאו יוֹצִיא וְיִתֵּן כְּתֻבָּה. וּבְאוֹתָן הַשְּׁלֹשִׁים יוֹם תִּהְיֶה הִיא עוֹשָׂה וְאוֹכֶלֶת וְיִהְיֶה אֶחָד מֵחֲבֵרָיו מְפַרְנֵס אוֹתָהּ דְּבָרִים שֶׁהִיא צְרִיכָה לָהֶן יֶתֶר עַל מַעֲשֵׂה יָדֶיהָ אִם אֵין מַעֲשֵׂה יָדֶיהָ מַסְפִּיקִין לַכּל:","הַמַּדִּיר אֶת אִשְׁתּוֹ שֶׁלֹּא תִּטְעֹם אֶחָד מִכָּל הַפֵּרוֹת מַמְתִּינִין לוֹ עַד שְׁלֹשִׁים יוֹם. יֶתֶר עַל כֵּן יוֹצִיא וְיִתֵּן כְּתֻבָּה. אֲפִלּוּ הִדִּירָהּ שֶׁלֹּא תֹּאכַל מַאֲכָל רַע. אֲפִלּוּ הִדִּירָהּ מִמִּין שֶׁלֹּא אָכְלָה אוֹתוֹ מִיָּמֶיהָ. יוֹצִיא אַחַר שְׁלֹשִׁים יוֹם וְיִתֵּן כְּתֻבָּה. נָדְרָה הִיא שֶׁלֹּא תֹּאכַל אֶחָד מִכָּל הַפֵּרוֹת וְקִיֵּם לָהּ הוּא אֶת נִדְרָהּ אוֹ נָדְרָה בְּנָזִיר וְלֹא הֵפֵר לָהּ. אִם רָצָה שֶׁתֵּשֵׁב תַּחְתָּיו וְלֹא תֹּאכַל פֵּרוֹת אוֹ תִּהְיֶה נְזִירָה תֵּשֵׁב. וְאִם אָמַר אֵינִי רוֹצֶה בְּאִשָּׁה נַדְרָנִית יוֹצִיא וְיִתֵּן כְּתֻבָּה שֶׁהֲרֵי הָיָה בְּיָדוֹ לְהָפֵר וְהוּא קִיֵּם לָהּ בִּרְצוֹנוֹ:"],"Mishneh Torah, Marriage 23":["הָאִשָׁה שֶׁהִתְנֵית עַל בַּעְלָהּ לְבַטֵּל זְכוּת מִדְּבָרִים שֶׁזּוֹכֶה בָּהֶן הַבַּעַל אִם כָּתַב לָהּ וְעוֹדָהּ אֲרוּסָה קֹדֶם הַנִּשּׂוּאִין אֵינוֹ צָרִיךְ לִקְנוֹת מִיָּדוֹ. אֶלָּא כָּל מַה שֶּׁכָּתַב לָהּ קַיָּם. וְאִם כָּתַב לָהּ אַחַר הַנִּשּׂוּאִין צָרִיךְ לִקְנוֹת מִיָּדוֹ:","הִתְנָה עִמָּהּ שֶׁלֹּא יִהְיוּ לוֹ דִּין וּדְבָרִים בִּנְכָסֶיהָ אִם מָכְרָה וְנָתְנָה מִכְרָהּ וּמַתְּנָתָהּ קַיָּם. אֲבָל אוֹכֵל פֵּרוֹתֵיהֶן כָּל זְמַן שֶׁהֵן בִּרְשׁוּתָהּ. וְאִם קָנוּ מִיָּדוֹ כְּשֶׁהִיא אֲרוּסָה שֶׁאֵין לוֹ דִּין וּדְבָרִים בִּנְכָסֶיהָ הֲרֵי סִלֵּק עַצְמוֹ מִגּוּף הַקַּרְקַע וְאֵין לוֹ בִּנְכָסֶיהָ פֵּרוֹת לְעוֹלָם. וַאֲפִלּוּ עִרְעֵר עַל קִנְיָנוֹ וְאָמַר לֹא עָלָה בְּדַעְתִּי שֶׁאֵין לִי פֵּרוֹת מִפְּנֵי קִנְיָן זֶה אֶלָּא שֶׁאִם מָכְרָה מִכְרָהּ קַיָּם שֶׁאֵין אָדָם נוֹשֵׂא אִשָּׁה בְּלֹא נְכָסִים אֵין שׁוֹמְעִין לוֹ אֶלָּא כְּבָר סִלֵּק עַצְמוֹ מִגּוּף הַקַּרְקַע:","הִתְנָה עִמָּהּ שֶׁלֹּא יֹאכַל פֵּרוֹת נְכָסֶיהָ הֲרֵי זֶה אֵינוֹ אוֹכֵל פֵּרוֹתֵיהֶן אֲבָל מוֹכְרִין אֶת הַפֵּרוֹת וְלוֹקְחִין בָּהֶן קַרְקַע וְהוּא אוֹכֵל פֵּרוֹתֶיהָ. שֶׁלֹּא סִלֵּק עַצְמוֹ אֶלָּא מִפֵּרוֹת נְכָסִים אֵלּוּ בִּלְבַד:","הִתְנָה עִמָּהּ שֶׁלֹּא יֹאכַל פֵּרוֹת נְכָסֶיהָ וְלֹא פֵּירֵי פֵּרוֹתֵיהֶן לוֹקְחִין הַפֵּרוֹת וְקוֹנִין בָּהֶם קַרְקַע וְלוֹקְחִין פֵּרוֹת קַרְקַע זוֹ וְקוֹנִין בָּהֶם קַרְקַע שְׁנִיָּה וְהוּא אוֹכֵל פֵּרוֹת אֵלּוּ שֶׁהֵן פֵּירֵי פֵּירֵי פֵּרוֹת. וְכֵן הַדָּבָר תָּמִיד עַד שֶׁיַּתְנֶה עִמָּהּ שֶׁלֹּא יִהְיוּ לוֹ לֹא פֵּרוֹת וְלֹא פֵּירֵי פֵּרוֹתֵיהֶן עַד לְעוֹלָם. וְאַחַר כָּךְ לֹא יִהְיוּ לוֹ פֵּרוֹת בְּחַיֶּיהָ אֲבָל אִם מֵתָה יִירַשׁ הַכּל:","הִתְנָה עִמָּהּ שֶׁלֹּא יִירָשֶׁנָּה הֲרֵי זֶה לֹא יִירָשֶׁנָּה אֲבָל אוֹכֵל פֵּרוֹת בְּחַיֶּיהָ. וְכֵן אִם הִתְנָה עִמָּהּ שֶׁיִּירַשׁ מִקְצָת נְכָסִים וְכֵן אִם הִתְנָה עִמָּהּ שֶׁאִם מֵתָה בְּלֹא בָּנִים יַחְזְרוּ נְכָסִין לְבֵית אָבִיהָ הַכּל קַיָּם:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהִתְנָה עִמָּהּ קֹדֶם שֶׁתִּנָּשֵׂא שֶׁהַנַּחֲלָה הַבָּאָה לוֹ לָאָדָם שֶׁלֹּא מִמִּשְׁפַּחְתּוֹ מַתְנֶה עָלֶיהָ שֶׁלֹּא יִירָשֶׁנָּה קֹדֶם שֶׁתְּהֵא רְאוּיָה לוֹ. אֲבָל אִם הִתְנָה עִמָּהּ אַחַר שֶׁנִּשֵּׂאת תְּנָאוֹ בָּטֵל וְיִירָשֶׁנָּה כְּמוֹ שֶׁבֵּאַרְנוּ:","הִתְנָה עִמָּהּ אַחַר נִשּׂוּאִין שֶׁלֹּא יִהְיוּ לוֹ דִּין וּדְבָרִים בִּנְכָסֶיהָ וְלֹא בְּפֵירֵי פֵּרוֹתֶיהָ עַד עוֹלָם בְּחַיֶּיהָ וּבְמוֹתָהּ הֲרֵי זֶה אֵינוֹ אוֹכֵל פֵּרוֹת כְּלָל. אֲבָל אִם מֵתָה יִירָשֶׁנָּה כְּמוֹ שֶׁבֵּאַרְנוּ:","הַבַּעַל שֶׁהוֹצִיא הוֹצָאוֹת עַל נִכְסֵי מְלוֹג בֵּין שֶׁהוֹצִיא מְעַט וְאָכַל פֵּרוֹת הַרְבֵּה בֵּין שֶׁהוֹצִיא הַרְבֵּה וְאָכַל פֵּרוֹת מְעַט וַאֲפִלּוּ אָכַל גְּרוֹגֶרֶת אַחַת דֶּרֶךְ כָּבוֹד אוֹ שֶׁאָכַל דִּינָר אֶחָד אֲפִלּוּ שֶׁלֹּא דֶּרֶךְ כָּבוֹד וַאֲפִלּוּ לֹא לָקַח בַּפֵּרוֹת מִמַּה שֶּׁהוֹצִיא אֶלָּא חֲבִילָה אַחַת שֶׁל זְמוֹרוֹת. מַה שֶּׁהוֹצִיא הוֹצִיא וּמַה שֶּׁאָכַל אָכַל:","וְכֵן אִם נָפְלוּ לָהּ כְּסָפִים בְּמָקוֹם רָחוֹק וְהוֹצִיא עֲלֵיהֶן הוֹצָאוֹת עַד שֶׁהֱבִיאָן אוֹ עַד שֶׁהוֹצִיאָן מִיַּד מִי שֶׁהָיוּ אֶצְלוֹ וְלָקַח בָּהֶן קַרְקַע וְאָכַל פֵּרוֹתֶיהָ כַּשִּׁעוּר מַה שֶּׁהוֹצִיא הוֹצִיא וּמַה שֶּׁאָכַל אָכַל. הוֹצִיא וְלֹא אָכַל אוֹ שֶׁאָכַל פָּחוֹת מִכַּשִּׁעוּר שָׁמִין כַּמָּה שֶׁהִשְׁבִּיחוּ וְשׁוֹאֲלִין אוֹתוֹ כַּמָּה הוֹצִיא. אִם הַשֶּׁבַח יֶתֶר עַל הַהוֹצָאָה יִשָּׁבַע בִּנְקִיטַת חֵפֶץ כַּמָּה הוֹצִיא וְנוֹטֵל הַהוֹצָאָה. וְאִם הַהוֹצָאָה יְתֵרָה עַל הַשֶּׁבַח אֵין לוֹ מִן הַהוֹצָאָה אֶלָּא כְּשִׁעוּר הַשֶּׁבַח וּבִשְׁבוּעָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּמְגָרֵשׁ אֲבָל הָאִשָּׁה שֶׁמָּרְדָה עַל בַּעְלָהּ אֲפִלּוּ אָכַל הַרְבֵּה שָׁמִין לוֹ כַּמָּה אָכַל וּפוֹחֵת אוֹתוֹ מִמַּה שֶּׁרָאוּי לִתֵּן לוֹ מִן הַהוֹצָאָה אַחַר שֶׁיִּשָּׁבַע וְנוֹטְלוֹ. שֶׁלֹּא הִקְנָה לָהּ כְּדֵי שֶׁתִּטּל וְתֵצֵא מֵעַצְמָהּ. וְכֵן הַמּוֹצִיא הוֹצָאוֹת עַל נִכְסֵי אִשְׁתּוֹ קְטַנָּה וּמֵאֲנָה בּוֹ רוֹאִין כַּמָּה אָכַל וְכַמָּה הוֹצִיא וְכַמָּה הִשְׁבִּיחַ וְשָׁמִין לוֹ כְּאָרִיס שֶׁהֲרֵי בִּרְשׁוּת יָרַד:","מִנְהָגוֹת רַבּוֹת יֵשׁ בִּנְדוּנְיָא. יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁיִּכְתְּבוּ בַּכְּתֻבּוֹת הַנְּדוּנְיָא יֶתֶר עַל דָּמֶיהָ בִּשְׁלִישׁ אוֹ בְּחֹמֶשׁ אוֹ בְּמֶחֱצָה. כְּגוֹן שֶׁתִּהְיֶה הַנְּדוּנְיָא מֵאָה וְכוֹתְבִים שֶׁהִכְנִיסָה מֵאָה וַחֲמִשִּׁים כְּדֵי לְהַרְבּוֹת בִּפְנֵי הָעָם וּכְשֶׁתָּבוֹא לִגְבּוֹת לֹא תִּגְבֶּה אֶלָּא הַמֵּאָה. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לִכְתֹּב פָּחוֹת. וְאִם פָּסְקָה לְהָבִיא לוֹ בְּמֵאָה כֵּלִים נוֹתֶנֶת שְׁוֵה מֵאָה וְעֶשְׂרִים אוֹ מֵאָה וַחֲמִשִּׁים וְכוֹתְבִין שֶׁהִכְנִיסָה לוֹ מֵאָה. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לִכְתֹּב שְׁוֵה מָנֶה בְּמָנֶה. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁיִּתֵּן הָאִישׁ מָעוֹת לְפִי הַנְּדוּנְיָא דָּבָר קָצוּב שֶׁתִּתְקַשֵּׁט בּוֹ הַכַּלָּה וְתִקְנֶה בּוֹ בְּשָׂמִים וְכַיּוֹצֵא בָּהֶן. וְיֵשׁ מְקוֹמוֹת שֶׁיַּכְנִיס הָאִישׁ שׁוּם מִשֶּׁלּוֹ לָאִשָּׁה וְיִצְטָרֵף לִנְדֻנְיָתָהּ לְהִתְנָאוֹת בּוֹ:","הַנּוֹשֵׂא סְתָם כּוֹתֵב וְנוֹתֵן כְּמִנְהַג הַמְּדִינָה. וְכֵן הִיא שֶׁפָּסְקָה לְהַכְנִיס נוֹתֶנֶת כְּמִנְהַג הַמְּדִינָה וּכְשֶׁתָּבֹא לִגְבּוֹת כְּתֻבָּתָהּ מַגְבִּין לָהּ מַה שֶּׁבִּכְתֻבָּתָהּ כְּמִנְהַג הַמְּדִינָה. וּבְכָל הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן מִנְהַג הַמְּדִינָה עִקָּר גָּדוֹל הוּא וְעַל פִּיו דָּנִין וְהוּא שֶׁיִּהְיֶה אוֹתוֹ מִנְהָג פָּשׁוּט בְּכָל הַמְּדִינָה:","אִישׁ וְאִשָּׁה שֶׁהָיוּ בֵּינֵיהֶם שִׁדּוּכִין וְאָמַר לָהּ כַּמָּה אֶת מַכְנֶסֶת לִי כָּךְ וְכָךְ וְאָמְרָה לוֹ וְכַמָּה אַתָּה נוֹתֵן לִי אוֹ כּוֹתֵב לִי כָּךְ וְכָךְ. וְכֵן הָאָב שֶׁפָּסַק עַל יְדֵי בְּנוֹ וּבִתּוֹ כַּמָּה אַתָּה נוֹתֵן לְבִנְךָ כָּךְ וְכָךְ וְכַמָּה אַתָּה נוֹתֵן לְבִתְּךָ כָּךְ וְכָךְ וְעָמְדוּ וְקִדְּשׁוּ קָנוּ אוֹתָן הַדְּבָרִים וְאַף עַל פִּי שֶׁלֹּא הָיָה בֵּינֵיהֶן קִנְיָן. וְאֵלּוּ הֵן הַדְּבָרִים הַנִּקְנִים בַּאֲמִירָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁפָּסַק הָאָב לְבִתּוֹ בֵּין קְטַנָּה וּבֵין גְּדוֹלָה וּפָסַק הָאָב לִבְנוֹ [ב.] וּבְנִשּׂוּאִין רִאשׁוֹנִים שֶׁדַּעְתּוֹ שֶׁל אָדָם קְרוֹבָה אֵצֶל בְּנוֹ וּמֵרֹב שִׂמְחָתוֹ בַּנִּשּׂוּאִין הָרִאשׁוֹנִים גָּמַר וּמַקְנֶה לוֹ בַּאֲמִירָה. אֲבָל אָח שֶׁפָּסַק לַאֲחוֹתוֹ אוֹ אִשָּׁה שֶׁפָּסְקָה לְבִתָּהּ וְכֵן שְׁאָר קְרוֹבִים וְכֵן הָאָב שֶׁפָּסַק לִבְנוֹ אוֹ לְבִתּוֹ בְּנִשּׂוּאִין שְׁנִיִּים לֹא קָנוּ אוֹתָן הַדְּבָרִים עַד שֶׁיִּקְנוּ מִידֵי הַפּוֹסֵק שֶׁיִּתֵּן כָּךְ וְכָךְ:","הָאָב שֶׁפָּסַק עַל יַד בִּתּוֹ לֹא קָנְתָה הַבַּת אוֹתָהּ הַמַּתָּנָה עַד שֶׁיִּכְנֹס אוֹתָהּ בַּעְלָהּ. וְכֵן הַבֵּן לֹא קָנָה עַד שֶׁיִּכְנֹס. שֶׁכָּל הַפּוֹסֵק אֵינוֹ פּוֹסֵק אֶלָּא עַל מְנָת לִכְנֹס. לְפִיכָךְ הַפּוֹסֵק מָעוֹת לַחֲתָנוֹ וּמֵת קֹדֶם שֶׁיִּכְנֹס וְנָפְלָה לִפְנֵי אָחִיו לְיִבּוּם יָכוֹל הָאָב לוֹמַר לַיָּבָם לְאָחִיךָ הָיִיתִי רוֹצֶה לִתֵּן וּלְךָ אֵינִי רוֹצֶה לִתֵּן. וַאֲפִלּוּ הָיָה הָרִאשׁוֹן עַם הָאָרֶץ וְהַשֵּׁנִי חָכָם. וְאַף עַל פִּי שֶׁהַבַּת רוֹצָה בּוֹ:","הַפּוֹסֵק מָעוֹת לַחֲתָנוֹ וְהָלַךְ הָאָב לִמְדִינָה אַחֶרֶת יְכוֹלָה הִיא לוֹמַר לַבַּעַל אֲנִי לֹא פָּסַקְתִּי עַל עַצְמִי מָה אֲנִי יְכוֹלָה לַעֲשׂוֹת אוֹ כְּנוֹס בְּלֹא נְדוּנְיָא אוֹ פָּטְרֵנִי בְּגֵט. אֲבָל אִם פָּסְקָה הִיא עַל עַצְמָהּ וְלֹא הִגִּיעָה יָדָהּ הֲרֵי זוֹ יוֹשֶׁבֶת עַד שֶׁתִּמְצָא מַה שֶּׁפָּסְקָה אוֹ עַד שֶׁתָּמוּת. וְלָמָּה לֹא תִּפְטֹר עַצְמָהּ בְּמַרְדּוּת. שֶׁהַמּוֹרֶדֶת וְהִיא אֲרוּסָה הַבַּעַל רוֹצֶה לְכָנְסָהּ וְהִיא אֵינָהּ רוֹצָה אֲבָל זוֹ אֵין הַבַּעַל רוֹצֶה בָּהּ עַד שֶׁתִּתֵּן הַנְּדוּנְיָא שֶׁפָּסְקָה וְהִיא רוֹצָה בּוֹ שֶׁהֲרֵי אוֹמֶרֶת לוֹ אוֹ כְּנֹס אוֹ פְּטֹר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּגְדוֹלָה אֲבָל בִּקְטַנָּה שֶׁפָּסְקָה עַל עַצְמָהּ כּוֹפִין אוֹתוֹ לִתֵּן גֵּט אוֹ יִכְנֹס בְּלֹא נְדוּנְיָא:","הַנּוֹשֵׂא אִשָּׁה וּפָסְקָה עִמּוֹ שֶׁיִּהְיֶה זָן אֶת בִּתָּהּ כָּךְ וְכָךְ שָׁנִים חַיָּב לָזוּן אוֹתָם שָׁנִים שֶׁקִּבֵּל עַל עַצְמוֹ. וְהוּא שֶׁיַּתְנוּ עַל דָּבָר זֶה בִּשְׁעַת הַקִּדּוּשִׁין. אֲבָל שֶׁלֹּא בִּשְׁעַת הַקִּדּוּשִׁין עַד שֶׁיִּקְנוּ מִיָּדוֹ אוֹ עַד שֶׁיִּכְתֹּב בִּשְׁטָר וְכַיּוֹצֵא בּוֹ כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מִקָּח וּמִמְכָּר. נִתְגָּרְשָׁה בְּתוֹךְ הַשָּׁנִים שֶׁקִּבֵּל עַל עַצְמוֹ לָזוּן אֶת בִּתָּהּ וְנִשֵּׂאת לְאַחֵר וּפָסְקָה גַּם עִמּוֹ שֶׁיִּהְיֶה זָן אוֹתָהּ הַבַּת כָּךְ וְכָךְ שָׁנִים לֹא יֹאמַר רִאשׁוֹן אִם תָּבוֹא לְבֵיתִי אֲזוּנָהּ אֶלָּא מוֹלִיךְ מְזוֹנוֹתֶיהָ לַמָּקוֹם שֶׁהִיא שָׁם אִמָּהּ. וְכֵן לֹא יֹאמְרוּ שְׁנֵיהֶם הֲרֵי אָנוּ זָנִין אוֹתָהּ כְּאַחַת אֶלָּא אֶחָד זָנָהּ וְאֶחָד נוֹתֵן לָהּ דְּמֵי מְזוֹנוֹת:","נִשֵּׂאת הַבַּת בְּתוֹךְ זְמַן זֶה הַבַּעַל חַיָּב בִּמְזוֹנוֹתֶיהָ. וּבַעֲלֵי אִמָּהּ שְׁנֵיהֶם כָּל אֶחָד וְאֶחָד נוֹתֵן לָהּ דְּמֵי מְזוֹנוֹת. מֵתוּ אֵלּוּ שֶׁפָּסְקוּ לָזוּן אוֹתָהּ אִם קָנוּ מִיָּדָן אוֹ שֶׁחִיֵּב עַצְמוֹ בִּשְׁטָר הֲרֵי זוֹ כְּבַעַל חוֹב בִּשְׁטָר וְטוֹרֶפֶת מְזוֹנוֹתֶיהָ מִנִּכְסֵיהֶן הַמְשֻׁעְבָּדִים עַד סוֹף הַזְּמַן שֶׁפָּסְקוּ. וְאִם פָּסְקוּ בִּשְׁעַת הַקִּדּוּשִׁין וְלֹא הָיָה שָׁם קִנְיָן הֲרֵי הֵם דְּבָרִים שֶׁלֹּא נִתְּנוּ לִכָּתֵב וְאֵינָהּ טוֹרֶפֶת בִּמְזוֹנוֹתֶיהָ:"],"Mishneh Torah, Mourning 11":["אַף עַל פִּי שֶׁאֵין אֲבֵלוּת בַּמּוֹעֵד קוֹרֵעַ עַל מֵתוֹ בַּמּוֹעֵד וְחוֹלֵץ כְּתֵפוֹ. וּמַבְרִין אֶת הָאֲבֵלִים לֶחֶם בַּמּוֹעֵד. כָּל אֵלּוּ בְּחֻלּוֹ שֶׁל מוֹעֵד אֲבָל בְּיוֹם טוֹב אֲפִלּוּ בְּיוֹם טוֹב שֵׁנִי אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַבְרִין:","אֵין קוֹרְעִין בַּמּוֹעֵד וְלֹא חוֹלְצִין אֶלָּא הַקְּרוֹבִים שֶׁחַיָּבִין בָּאֵבֶל. אוֹ הַקּוֹרֵעַ וְהַחוֹלֵץ עַל הֶחָכָם אוֹ עַל אָדָם כָּשֵׁר. אוֹ מִי שֶׁהָיָה עוֹמֵד בִּשְׁעַת יְצִיאַת נְשָׁמָה. וּמַבְרִין הַכּל עַל הֶחָכָם בַּמּוֹעֵד לְתוֹךְ הָרְחָבָה כְּדֶרֶךְ שֶׁמַּבְרִין אֶת הָאֲבֵלִים. שֶׁהַכּל אֲבֵלִים עָלָיו:","כְּשֶׁמַּבְרִין אֶת הָאֲבֵלִים בַּמּוֹעֵד אֵין מַבְרִין אֶלָּא עַל מִטּוֹת זְקוּפוֹת. וְאֵין אוֹמְרִין בִּרְכַּת אֲבֵלִים בַּמּוֹעֵד. אֲבָל עוֹמְדִין בְּשׁוּרָה וּמְנַחֲמִין וּפוֹטְרִין. וְאֵין מַנִּיחִין אֶת הַמִּטָּה בָּרְחוֹב שֶׁלֹּא לְהַרְגִּיל אֶת הַהֶסְפֵּד. שֶׁהַמּוֹעֵד אָסוּר בְּהֶסְפֵּד וּבְתַעֲנִית. וְכֵן אֵין מְלַקְּטִים עַצְמוֹת אָבִיו וְאִמּוֹ בַּמּוֹעֵד שֶׁאֵבֶל הוּא לוֹ. וְאֵין צָרִיךְ לוֹמַר שְׁאָר קְרוֹבִים. וְכֵן אֵין מַסְפִּידִין אֶת הַמֵּת בַּחֲנֻכָּה וּבְפוּרִים וְלֹא בְּרָאשֵׁי חֳדָשִׁים אֲבָל נוֹהֲגִין בָּהֶן כָּל דִּבְרֵי אֲבֵלוּת. וּמֻתָּר לִסְפֹּד לִפְנֵי חֲנֻכָּה וּפוּרִים וּלְאַחֲרֵיהֶן:","הַנָּשִׁים בַּמּוֹעֵד מְעַנּוֹת אֲבָל לֹא מְטַפְּחוֹת. וּבְרָאשֵׁי חֳדָשִׁים וּבַחֲנֻכָּה וּבְפוּרִים מְעַנּוֹת וּמְטַפְּחוֹת אֲבָל אֵין מְקוֹנְנוֹת לֹא בָּזֶה וְלֹא בָּזֶה. נִקְבַּר הַמֵּת לֹא מְעַנּוֹת וְלֹא מְטַפְּחוֹת:","אֵי זֶהוּ עִנּוּי שֶׁכֻּלָּן עוֹנוֹת כְּאַחַת. קִינָה שֶׁאַחַת אוֹמֶרֶת וְכֻלָּן עוֹנוֹת אַחֲרֶיהָ. שֶׁנֶּאֱמַר (ירמיה ט יט) \"וְלַמֵּדְנָה בְנוֹתֵיכֶם נֶהִי וְאִשָּׁה רְעוּתָהּ קִינָה\". בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר הָעָם שֶׁמֵּתוּ. אֲבָל תַּלְמִיד חָכָם שֶׁמֵּת סוֹפְדִים אוֹתוֹ בַּמּוֹעֵד וְאֵין צָרִיךְ לוֹמַר בַּחֲנֻכָּה וּבְפוּרִים וְרָאשֵׁי חֳדָשִׁים אֲבָל לֹא בְּיוֹם טוֹב שֵׁנִי. וְאֵין סוֹפְדִין אוֹתוֹ בְּיָמִים אֵלּוּ אֶלָּא בְּפָנָיו. נִקְבַּר אֲסוּרִין בְּהֶסְפֵּד. וְיוֹם שְׁמוּעָתוֹ כִּבְפָנָיו הוּא וְסוֹפְדִין אוֹתוֹ אַף עַל פִּי שֶׁהִיא רְחוֹקָה:","לֹא תְּעוֹרֵר אִשָּׁה עַל מֵת שֶׁלָּהּ שְׁלֹשִׁים יוֹם קֹדֶם לֶחָג. כְּדֵי שֶׁלֹּא יָבוֹא הֶחָג וְהֵם דָּוִים. שֶׁאֵין הַמֵּת מִשְׁתַּכֵּחַ מִן הַלֵּב שְׁלֹשִׁים יוֹם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמֵת יָשָׁן. אֲבָל אִם מֵת בְּתוֹךְ שְׁלֹשִׁים יוֹם סָמוּךְ לֶחָג מְעוֹרֶרֶת:","שִׁבְעַת יְמֵי הַחַתְנוּת הֲרֵי הֵן כְּרֶגֶל וּמִי שֶׁמֵּת לוֹ מֵת בְּתוֹךְ יְמֵי הַמִּשְׁתֶּה אֲפִלּוּ אָבִיו וְאִמּוֹ מַשְׁלִים שִׁבְעַת יְמֵי הַשִּׂמְחָה וְאַחַר כָּךְ נוֹהֵג שִׁבְעַת יְמֵי אֲבֵלוּת. וּמוֹנֶה הַשְּׁלֹשִׁים מֵאַחַר יְמֵי הַשִּׂמְחָה:","הֵכִין כָּל צָרְכֵי הַסְּעוּדָה וְאָפָה פִּתּוֹ וְטָבַח טִבְחוֹ כְּדֵי שֶׁיִּכָּנְסוּ לַשִּׂמְחָה וּמֵת לוֹ מֵת קֹדֶם שֶׁיִּכָּנְסוּ לַשִּׂמְחָה. אִם לֹא נָתַן מַיִם עַל גַּבֵּי בָּשָׂר מוֹכֵר הַבָּשָׂר וְהַפַּת וְנוֹהֵג שִׁבְעַת יְמֵי אֲבֵלוּת וְאַחַר כָּךְ נוֹהֵג שִׁבְעַת יְמֵי הַמִּשְׁתֶּה. וְאִם נָתַן מַיִם עַל גַּבֵּי בָּשָׂר שֶׁהֲרֵי אִי אֶפְשָׁר לְמָכְרוֹ. מַכְנִיסִין אֶת הַמֵּת לְחֶדֶר וְאֶת הֶחָתָן וְאֶת הַכַּלָּה לַחֻפָּה. וּבוֹעֵל בְּעִילַת מִצְוָה וּפוֹרֵשׁ וְנוֹהֵג שִׁבְעַת יְמֵי הַמִּשְׁתֶּה וְאַחַר כָּךְ נוֹהֵג שִׁבְעַת יְמֵי אֲבֵלוּת. וְכָל אוֹתָן הַיָּמִים נוֹהֵג בִּדְבָרִים שֶׁבְּצִנְעָה כְּשַׁבָּת. לְפִיכָךְ הוּא יָשֵׁן בֵּין הָאֲנָשִׁים וְאִשְׁתּוֹ יְשֵׁנָה בֵּין הַנָּשִׁים כְּדֵי שֶׁלֹּא יְשַׁמֵּשׁ מִטָּתוֹ. וְאֵין מוֹנְעִין תַּכְשִׁיטִין מִן הַכַּלָּה כָּל שְׁלֹשִׁים יוֹם. הָיוּ בְּמָקוֹם שֶׁאֶפְשָׁר לִמְכֹּר הַבָּשָׂר אַף עַל פִּי שֶׁנָּתַן עָלָיו מַיִם מוֹכֵר וְנוֹהֵג אֲבֵלוּת תְּחִלָּה. הָיוּ בְּמָקוֹם שֶׁאִי אֶפְשָׁר לִמְכֹּר הַבָּשָׂר אַף עַל פִּי שֶׁלֹּא נָתַן עָלָיו מַיִם נוֹהֵג שִׁבְעַת יְמֵי הַמִּשְׁתֶּה תְּחִלָּה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁמֵּת אָבִיו שֶׁל חָתָן אוֹ אִמָּהּ שֶׁל כַּלָּה. שֶׁאִם יַפְסִידוּ סְעוּדָה זוֹ אֵין לָהֶם מִי שֶׁיִּטְרַח לָהֶם. אֲבָל אִם מֵת אָבִיהָ שֶׁל כַּלָּה אוֹ אִמּוֹ שֶׁל חָתָן אוֹ שְׁאָר קְרוֹבֵיהֶם נוֹהֲגִין שִׁבְעַת יְמֵי הָאֵבֶל תְּחִלָּה וְאַחַר כָּךְ תִּכָּנֵס לַחֻפָּה וְיִנְהֲגוּ שִׁבְעַת יְמֵי הַמִּשְׁתֶּה:"],"Mishneh Torah, Murderer and the Preservation of Life 1":["כָּל הוֹרֵג נֶפֶשׁ בֶּן אָדָם עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כ יג) (דברים ה יז) \"לֹא תִרְצָח\". וְאִם רָצַח בְּזָדוֹן בִּפְנֵי עֵדִים מִיתָתוֹ בְּסַיִף שֶׁנֶּאֱמַר (שמות כא כ) \"נָקֹם יִנָּקֵם\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ מִיתַת סַיִף. בֵּין שֶׁהָרַג אֶת חֲבֵרוֹ בְּבַרְזֶל בֵּין שֶׁשְּׂרָפוֹ בָּאֵשׁ מִיתָתוֹ בְּסַיִף:","מִצְוָה בְּיַד גּוֹאֵל הַדָּם [לַהֲרֹג אֶת הָרוֹצֵחַ] שֶׁנֶּאֱמַר (במדבר לה יט) \"גֹּאֵל הַדָּם הוּא יָמִית אֶת הָרֹצֵחַ\". וְכָל הָרָאוּי לִירֻשָּׁה הוּא גּוֹאֵל הַדָּם. לֹא רָצָה גּוֹאֵל הַדָּם אוֹ שֶׁלֹּא הָיָה יָכוֹל לַהֲמִיתוֹ אוֹ שֶׁאֵין לוֹ גּוֹאֵל דָּם בֵּית דִּין מְמִיתִין אֶת הָרוֹצֵחַ בְּסַיִף:","הָאָב שֶׁהָרַג אֶת בְּנוֹ. אִם הָיָה בֶּן לַנֶּהֱרָג הֲרֵי זֶה הוֹרֵג אֲבִי אָבִיו מִפְּנֵי שֶׁהוּא גּוֹאֵל. וְאִם אֵין לוֹ בֵּן אֵין אֶחָד מִן הָאַחִין נַעֲשֶׂה גּוֹאֵל הַדָּם לְהָמִית אֶת אָבִיו אֶלָּא בֵּית דִּין מְמִיתִין אוֹתוֹ. וְאֶחָד הַזָּכָר וְאֶחָד הַנְּקֵבָה בִּגְאֻלַּת הַדָּם:","וּמֻזְהָרִין בֵּית דִּין שֶׁלֹּא לִקַּח כֹּפֶר מִן הָרוֹצֵחַ. וַאֲפִלּוּ נָתַן כָּל מָמוֹן שֶׁבָּעוֹלָם וַאֲפִלּוּ רָצָה גּוֹאֵל הַדָּם לְפָטְרוֹ. שֶׁאֵין נַפְשׁוֹ שֶׁל זֶה הַנֶּהֱרָג קִנְיַן גּוֹאֵל הַדָּם אֶלָּא קִנְיַן הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנֶּאֱמַר (במדבר לה לא) \"וְלֹא תִקְחוּ כֹפֶר לְנֶפֶשׁ רֹצֵחַ\". וְאֵין לְךָ דָּבָר שֶׁהִקְפִּידָה תּוֹרָה עָלָיו כִּשְׁפִיכוּת דָּמִים שֶׁנֶּאֱמַר (במדבר לה לג) \"וְלֹא תַחֲנִיפוּ אֶת הָאָרֶץ\" וְגוֹ'. (במדבר לה לג) \"כִּי הַדָּם הוּא יַחֲנִיף אֶת הָאָרֶץ\" וְגוֹ':","רוֹצֵחַ שֶׁהָרַג בְּזָדוֹן אֵין מְמִיתִין אוֹתוֹ הָעֵדִים וְלֹא הָרוֹאִים אוֹתוֹ עַד שֶׁיָּבוֹא לְבֵית דִּין וִידִינוּהוּ לְמִיתָה. שֶׁנֶּאֱמַר (במדבר לה יב) \"וְלֹא יָמוּת הָרֹצֵחַ עַד עָמְדוֹ לִפְנֵי הָעֵדָה לַמִּשְׁפָּט\". וְהוּא הַדִּין לְכָל מְחֻיְּבֵי מִיתוֹת בֵּית דִּין שֶׁעָבְרוּ וְעָשׂוּ שֶׁאֵין מְמִיתִין אוֹתָן עַד שֶׁיִּגָּמֵר דִּינָם בְּבֵית דִּין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁעָבַר וְעָשָׂה הֶעָוֹן שֶׁחַיָּב עָלָיו מִיתַת בֵּית דִּין. אֲבָל הָרוֹדֵף אַחַר חֲבֵרוֹ לְהָרְגוֹ אֲפִלּוּ הָיָה הָרוֹדֵף קָטָן הֲרֵי כָּל יִשְׂרָאֵל מְצֻוִּין לְהַצִּיל הַנִּרְדָּף מִיַּד הָרוֹדֵף וַאֲפִלּוּ בְּנַפְשׁוֹ שֶׁל רוֹדֵף:","כֵּיצַד. אִם הִזְהִירוּהוּ וַהֲרֵי הוּא רוֹדֵף אַחֲרָיו אַף עַל פִּי שֶׁלֹּא קִבֵּל עָלָיו הַתְרָאָה כֵּיוָן שֶׁעֲדַיִן הוּא רוֹדֵף הֲרֵי זֶה נֶהֱרָג. וְאִם יְכוֹלִים לְהַצִּילוֹ בְּאֵיבָר מֵאֵיבְרֵי הָרוֹדֵף כְּגוֹן שֶׁיַּכּוּ אוֹתוֹ בְּחֵץ אוֹ בְּאֶבֶן אוֹ בְּסַיִף וְיִקְטְעוּ אֶת יָדוֹ אוֹ יִשְׁבְּרוּ אֶת רַגְלוֹ אוֹ יְסַמּוּ אֶת עֵינוֹ עוֹשִׂין. וְאִם [אֵינָן] יְכוֹלִין לְכַוֵּן וּלְהַצִּילוֹ אֶלָּא אִם כֵּן הֲרָגוּהוּ לַרוֹדֵף הֲרֵי אֵלּוּ הוֹרְגִין אוֹתוֹ אַף עַל פִּי שֶׁעֲדַיִן לֹא הָרַג שֶׁנֶּאֱמַר (דברים כה יב) \"וְקַצֹּתָה אֶת כַּפָּהּ לֹא תָחוֹס עֵינֶךָ\":","אֶחָד בִּמְבוּשָׁיו וְאֶחָד כָּל דָּבָר שֶׁיֵּשׁ בּוֹ סַכָּנַת נְפָשׁוֹת. אֶחָד הָאִישׁ אוֹ הָאִשָּׁה. עִנְיַן הַכָּתוּב שֶׁכָּל הַחוֹשֵׁב לְהַכּוֹת חֲבֵרוֹ הַכָּאָה הַמְּמִיתָה אוֹתוֹ מַצִּילִין אֶת הַנִּרְדָּף בְּכַפּוֹ שֶׁל רוֹדֵף. וְאִם אֵינָן יְכוֹלִין מַצִּילִין אוֹתוֹ אַף בְּנַפְשׁוֹ שֶׁנֶּאֱמַר (דברים כה יב) \"לֹא תָחוֹס עֵינְךָ\":","אַף זוֹ מִצְוַת לֹא תַּעֲשֶׂה שֶׁלֹּא לָחוּס עַל נֶפֶשׁ הָרוֹדֵף. לְפִיכָךְ הוֹרוּ חֲכָמִים שֶׁהָעֻבָּרָה שֶׁהִיא מַקְשָׁה לֵילֵד מֻתָּר לַחְתֹּךְ הָעֵבָּר בְּמֵעֶיהָ בֵּין בְּסַם בֵּין בְּיָד מִפְּנֵי שֶׁהוּא כְּרוֹדֵף אַחֲרֶיהָ לְהָרְגָהּ. וְאִם מִשֶּׁהוֹצִיא רֹאשׁוֹ אֵין נוֹגְעִין בּוֹ שֶׁאֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ וְזֶהוּ טִבְעוֹ שֶׁל עוֹלָם:","אֶחָד הָרוֹדֵף אַחַר חֲבֵרוֹ לְהָרְגוֹ אוֹ רוֹדֵף אַחַר נַעֲרָה מְאֹרָסָה לְאָנְסָהּ. שֶׁנֶּאֱמַר (דברים כב כו) \"כִּי כַּאֲשֶׁר יָקוּם אִישׁ עַל רֵעֵהוּ וּרְצָחוֹ נֶפֶשׁ כֵּן הַדָּבָר הַזֶּה\". וַהֲרֵי הוּא אוֹמֵר (דברים כב כז) \"צָעֲקָה הַנַּעֲרָה הַמְאֹרָסָה וְאֵין מוֹשִׁיעַ לָהּ\". הָא יֵשׁ לָהּ מוֹשִׁיעַ מוֹשִׁיעָהּ בְּכָל דָּבָר שֶׁיָּכוֹל לְהוֹשִׁיעַ וַאֲפִלּוּ בַּהֲרִיגַת הָרוֹדֵף:","וְהוּא הַדִּין לִשְׁאָר כָּל הָעֲרָיוֹת חוּץ מִן הַבְּהֵמָה. אֲבָל הַזָּכוּר מַצִּילִין אוֹתוֹ בְּנֶפֶשׁ הָרוֹדֵף כִּשְׁאָר כָּל הָעֲרָיוֹת. אֲבָל הָרוֹדֵף אַחַר הַבְּהֵמָה לְרָבְעָהּ. אוֹ שֶׁרָדַף לַעֲשׂוֹת מְלָאכָה בְּשַׁבָּת אוֹ לַעֲבֹד עֲבוֹדָה זָרָה. אַף עַל פִּי שֶׁהַשַּׁבָּת וַעֲבוֹדָה זָרָה עִקְּרֵי הַדָּת אֵין מְמִיתִין אוֹתוֹ עַד שֶׁיַּעֲשֶׂה וִיבִיאוּהוּ לְבֵית דִּין וִידִינוּהוּ וְיָמוּת:","רָדַף אַחַר עֶרְוָה וּתְפָשָׂהּ וְשָׁכַב עִמָּהּ וְהֶעֱרָה. אַף עַל פִּי שֶׁלֹּא גָּמַר בִּיאָתוֹ אֵין מְמִיתִין אוֹתוֹ עַד עָמְדוֹ בַּדִּין. רָדַף אַחַר עֶרְוָה וַאֲחֵרִים הָיוּ רוֹדְפִין אַחֲרָיו לְהַצִּילָהּ. וְאָמְרָה לָהֶם הֲנִיחוּהוּ כְּדֵי שֶׁלֹּא יַהַרְגֵנִי. אֵין שׁוֹמְעִין לָהּ אֶלָּא מַבְהִילִין אוֹתוֹ וּמוֹנְעִין אוֹתוֹ מִלִּבְעל בְּאֵיבָרָיו. וְאִם אֵינָן יְכוֹלִים לְמָנְעוֹ בְּאֵיבָרָיו אֲפִלּוּ בְּנַפְשׁוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל הַיָּכוֹל לְהַצִּיל בְּאֵיבָר מֵאֵיבָרָיו וְלֹא טָרַח בְּכָךְ אֶלָּא הִצִּיל בְּנַפְשׁוֹ שֶׁל רוֹדֵף וַהֲרָגוֹ הֲרֵי זֶה שׁוֹפֵךְ דָּמִים וְחַיָּב מִיתָה אֲבָל אֵין בֵּית דִּין מְמִיתִין אוֹתוֹ:","כָּל הַיָּכוֹל לְהַצִּיל וְלֹא הִצִּיל עוֹבֵר עַל (ויקרא יט טז) \"לֹא תַעֲמֹד עַל דַּם רֵעֶךָ\". וְכֵן הָרוֹאֶה אֶת חֲבֵרוֹ טוֹבֵעַ בַּיָּם. אוֹ לִסְטִים בָּאִים עָלָיו. אוֹ חַיָּה רָעָה בָּאָה עָלָיו. וְיָכוֹל לְהַצִּילוֹ הוּא בְּעַצְמוֹ. אוֹ שֶׁיִּשְׂכֹּר אֲחֵרִים לְהַצִּילוֹ וְלֹא הִצִּיל. אוֹ שֶׁשָּׁמַע עוֹבְדֵי כּוֹכָבִים אוֹ מוֹסְרִים מְחַשְּׁבִים עָלָיו רָעָה אוֹ טוֹמְנִין לוֹ פַּח וְלֹא גִּלָּה אֹזֶן חֲבֵרוֹ וְהוֹדִיעוֹ. אוֹ שֶׁיָּדַע בְּעַכּוּ\"ם אוֹ בְּאוֹנֵס שֶׁהוּא בָּא עַל חֲבֵרוֹ וְיָכוֹל לְפַיְּסוֹ בִּגְלַל חֲבֵרוֹ לְהָסִיר מַה שֶּׁבְּלִבּוֹ וְלֹא פִּיְּסוֹ. וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ. הָעוֹשֶׂה אוֹתָם עוֹבֵר עַל לֹא תַעֲמֹד עַל דַּם רֵעֶךָ:","הָרוֹאֶה רוֹדֵף אַחַר חֲבֵרוֹ לְהָרְגוֹ אוֹ אַחַר עֶרְוָה לְבָעֳלָהּ וְיָכוֹל לְהַצִּיל וְלֹא הִצִּיל. הֲרֵי זֶה בִּטֵּל מִצְוַת עֲשֵׂה שֶׁהִיא (דברים כה יב) \"וְקַצֹּתָה אֶת כַּפָּהּ\". וְעָבַר עַל שְׁנֵי לָאוִין עַל (דברים כה יב) \"לֹא תָחוֹס עֵינְךָ\" וְעַל (ויקרא יט טז) \"לֹא תַעֲמֹד עַל דַּם רֵעֶךָ\":","אַף עַל פִּי שֶׁאֵין לוֹקִין עַל לָאוִין אֵלּוּ מִפְּנֵי שֶׁאֵין מַעֲשֶׂה בָּהֶן חֲמוּרִים הֵם. שֶׁכָּל הַמְאַבֵּד נֶפֶשׁ אַחַת מִיִּשְׂרָאֵל כְּאִלּוּ אִבֵּד כָּל הָעוֹלָם כֻּלּוֹ. וְכָל הַמְקַיֵּם נֶפֶשׁ אַחַת מִיִּשְׂרָאֵל כְּאִלּוּ קִיֵּם כָּל הָעוֹלָם כֻּלּוֹ:"],"Mishneh Torah, Murderer and the Preservation of Life 9":["הָרוּג שֶׁנִּמְצָא נוֹפֵל לָאָרֶץ וְלֹא נוֹדַע מִי הִכָּהוּ מַנִּיחִין אוֹתוֹ בִּמְקוֹמוֹ. וְיוֹצְאִין חֲמִשָּׁה זְקֵנִים מִבֵּית דִּין הַגָּדוֹל שֶׁבִּירוּשָׁלַיִם שֶׁנֶּאֱמַר (דברים כא ב) \"וְיָצְאוּ זְקֵנֶיךָ וְשֹׁפְטֶיךָ\" וּמוֹדְדִין מִמֶּנּוּ אֶל הֶעָרִים שֶׁסְּבִיבוֹת הֶחָלָל. אֲפִלּוּ נִמְצָא בְּצַד עִיר זוֹ שֶׁהַדָּבָר יָדוּעַ בְּוַדַּאי שֶׁהִיא הַקְּרוֹבָה מִצְוָה לִמְדֹּד:","אַחַר שֶׁמּוֹדְדִין וְנוֹדְעָה הָעִיר הַקְּרוֹבָה קוֹבְרִין אֶת הַנֶּהֱרָג בִּמְקוֹמוֹ וְחוֹזְרִין זִקְנֵי יְרוּשָׁלַיִם לִמְקוֹמָן. וּבֵית דִּין שֶׁל אוֹתָהּ הָעִיר מְבִיאִין עֶגְלַת בָּקָר מִשֶּׁל אַנְשֵׁי אוֹתָהּ הָעִיר וּמוֹרִידִין אוֹתָהּ אֶל נַחַל שֶׁשּׁוֹטֵף בְּחָזְקָה וְזֶהוּ (דברים כא ד) \"אֵיתָן\" הָאָמוּר בַּתּוֹרָה:","וְעוֹרְפִין אוֹתָהּ שָׁם בְּקוֹפִיץ מֵאַחֲרֶיהָ. וּבֵית דִּין שֶׁל אוֹתָהּ הָעִיר עִם כָּל זְקֵנֶיהָ אֲפִלּוּ הֵם מֵאָה כֻּלָּן רוֹחֲצִין אֶת יְדֵיהֶן שָׁם בִּמְקוֹם עֲרִיפָתָהּ וְאוֹמְרִים שָׁם בְּתוֹךְ הַנַּחַל בִּלְשׁוֹן הַקֹּדֶשׁ (דברים כא ז) \"יָדֵינוּ לֹא שָׁפְכוּ אֶת הַדָּם הַזֶּה וְעֵינֵינוּ לֹא רָאוּ\". כְּלוֹמַר שֶׁלֹּא בָּא לְיָדֵינוּ הַנֶּהֱרָג הַזֶּה וּפְטָרְנוּהוּ בְּלֹא מְזוֹנוֹת וְלֹא רְאִינוּהוּ וּפְטָרְנוּהוּ בְּלֹא לְוָיָה. וְהַכֹּהֲנִים אוֹמְרִים בִּלְשׁוֹן הַקֹּדֶשׁ (דברים כא ח) \"כַּפֵּר לְעַמְּךָ יִשְׂרָאֵל\". וְהוֹלְכִין לָהֶן. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְכַפֵּר עַל הַדָּם שֶׁנֶּאֱמַר (דברים כא ח) \"וְנִכַּפֵּר לָהֶם הַדָּם\":","כְּשֶׁמּוֹדְדִין מִן הֶחָלָל מְדַקְדְּקִין בַּמִּדָּה וְאֵין מְקַדְּרִין בָּהּ. וְאֵין מוֹדְדִין אֶלָּא לְעִיר שֶׁיֵּשׁ בָּהּ בֵּית דִּין שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה. וְאֵין מוֹדְדִין לִירוּשָׁלַיִם שֶׁיְּרוּשָׁלַיִם אֵין מְבִיאָה עֶגְלָה עֲרוּפָה לְפִי שֶׁלֹּא נִתְחַלְּקָה לִשְׁבָטִים וְנֶאֱמַר (דברים כא א) \"בָּאֲדָמָה אֲשֶׁר ה' אֱלֹהֶיךָ נֹתֵן לְךָ לְרִשְׁתָּהּ\":","נִמְצָא קָרוֹב לִירוּשָׁלַיִם אוֹ לְעִיר שֶׁאֵין בָּהּ בֵּית דִּין מַנִּיחִין אוֹתָהּ וּמוֹדְדִין אֶל שְׁאָר הָעֲיָרוֹת הַסְּמוּכוֹת לוֹ. נִמְצָא סָמוּךְ לַסְּפָר אוֹ לְעִיר שֶׁיֵּשׁ בָּהּ עַכּוּ\"ם אֵין מוֹדְדִין כָּל עִקָּר שֶׁהֲרֵי זֶה בְּחֶזְקַת שֶׁהֲרָגוּהוּ עַכּוּ\"ם:","אֵין הָעִיר הַקְּרוֹבָה מְבִיאָה אֶלָּא בִּזְמַן שֶׁמִּנְיַן הָרֹב שֶׁבָּהּ כְּמוֹ מִנְיַן הָעִיר הָרְחוֹקָה מִמֶּנָּה. אֲבָל אִם הָיוּ אֵלּוּ שֶׁבָּרְחוֹקָה מְרֻבִּין עַל אַנְשֵׁי הַקְּרוֹבָה מִמֶּנָּה הוֹלְכִין אַחַר הָרֹב וְהַמְרֻבִּין מְבִיאִין הָעֶגְלָה:","אַף עַל פִּי שֶׁהוֹלְכִין אַחַר הָרֹב מִן הַתּוֹרָה וְהוֹלְכִין אַחַר הַקָּרוֹב הָרֹב עָדִיף:","נִמְצָא הַנֶּהֱרָג מְכֻוָּן בֵּין שְׁתֵּי עֲיָרוֹת וְאַנְשֵׁי זוֹ כְּאַנְשֵׁי זוֹ בְּשָׁוֶה יָבִיאוּ עֶגְלָה אַחַת בְּשֻׁתָּפוּת. וְיַתְנוּ וְיֹאמְרוּ. אִם זוֹ הִיא הַקְּרוֹבָה הֲרֵי הִיא שֶׁלָּהֶן וְאֵלּוּ יִתְּנוּ לָהֶם חֶלְקָם מַתָּנָה. וְאִם אֵלּוּ הֵם הַקְּרוֹבִים הֲרֵי הוּא שֶׁלָּהֶן וְאֵלּוּ יִתְּנוּ לָהֶן חֶלְקָם מַתָּנָה. לְפִי שֶׁאִי אֶפְשָׁר לְצַמְצֵם וַאֲפִלּוּ בִּידֵי אָדָם:","מֵהֵיכָן מוֹדְדִין. מֵחָטְמוֹ. נִמְצָא גּוּפוֹ בְּמָקוֹם אֶחָד וְרֹאשׁוֹ בְּמָקוֹם אַחֵר מוֹלִיכִין הַגּוּף אֵצֶל הָרֹאשׁ וְקוֹבְרִים אוֹתוֹ בִּמְקוֹמוֹ. וְכֵן כָּל מֵת מִצְוָה מוֹלִיכִין גּוּפוֹ אֵצֶל רֹאשׁוֹ וְנִקְבָּר בִּמְקוֹמוֹ:","נִמְצְאוּ מֵתִים רַבִּים זֶה בְּצַד זֶה. מוֹדְדִין מֵחָטְמוֹ שֶׁל כָּל אֶחָד וְאֶחָד מֵהֶן. וְאִם הָיְתָה עִיר אַחַת קְרוֹבָה לְכֻלָּם מְבִיאָה עֶגְלָה אַחַת עַל כֻּלָּן. נִמְצְאוּ זֶה עַל גַּבֵּי זֶה מוֹדְדִין מִן הָעֶלְיוֹן כְּמוֹת שֶׁהֵן מֻנָּחִין:","נֶאֱמַר (דברים כא א) \"כִּי יִמָּצֵא חָלָל\" לֹא חָנוּק וְלֹא מְפַרְפֵּר שֶׁאֵין זֶה נִקְרָא חָלָל. (דברים כא א) \"בָּאֲדָמָה\" לֹא טָמוּן בְּגַל. (דברים כא א) \"נֹפֵל\" לֹא תָּלוּי בְּאִילָן. (דברים כא א) \"בַּשָּׂדֶה\" לֹא צָף עַל פְּנֵי הַמַּיִם. (דברים כא א) \"לֹא נוֹדַע מִי הִכָּהוּ\" הָא אִם נוֹדַע לֹא הָיוּ עוֹרְפִין:","אֲפִלּוּ רָאָה הַהוֹרֵג עֵד אֶחָד אֲפִלּוּ עֶבֶד אוֹ אִשָּׁה אוֹ פָּסוּל לְעֵדוּת בָּעֲבֵרָה לֹא הָיוּ עוֹרְפִין. לְפִיכָךְ מִשֶּׁרַבּוּ הָרַצְחָנִים בְּגָלוּי בָּטְלָה עֶגְלָה עֲרוּפָה:","עֵד אֶחָד אוֹמֵר רָאִיתִי אֶת הַהוֹרֵג וְעֵד אֶחָד הִכְחִישׁוֹ וְאָמַר לוֹ לֹא רָאִיתָ הָיוּ עוֹרְפִין. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁבָּאוּ שְׁנֵיהֶם כְּאַחַת. אֲבָל אִם אָמַר אֶחָד אֲנִי רָאִיתִי אֶת הַהוֹרֵג הֲרֵי זֶה נֶאֱמָן כִּשְׁנַיִם לְעִנְיָן זֶה. וְאִם בָּא אַחַר כָּךְ עֵד אֶחָד וְהִכְחִישׁוֹ וְאָמַר לוֹ לֹא רָאִיתָ אֵין מַשְׁגִּיחִין עַל דִּבְרֵי הָאַחֲרוֹן וְאֵין עוֹרְפִין:","בָּאוּ שְׁנַיִם אַחַר שֶׁהֵעִיד הָאֶחָד וְהִכְחִישׁוּהוּ וְאָמְרוּ לוֹ לֹא רָאִיתָ הֲרֵי הֵן כִּשְׁתֵּי עֵדֻיּוֹת הַמַּכְחִישׁוֹת זוֹ אֶת זוֹ וְעוֹרְפִין. אִשָּׁה אוֹמֶרֶת רָאִיתִי אֶת הַהוֹרֵג וְאִשָּׁה אַחֶרֶת מַכְחֶשֶׁת אוֹתָהּ וְאוֹמֶרֶת לֹא רָאִית הָיוּ עוֹרְפִין בֵּין שֶׁבָּאוּ שְׁתֵּיהֶן כְּאַחַת בֵּין שֶׁבָּאוּ זוֹ אַחַר זוֹ. שְׁנַיִם אוֹמְרִים רָאִינוּ וְאֶחָד אוֹמֵר לָהֶן לֹא רְאִיתֶם אֵין עוֹרְפִין. אֶחָד אוֹמֵר רָאִיתִי וּשְׁנַיִם אוֹמְרִים לוֹ לֹא רָאִיתָ הָיוּ עוֹרְפִין:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ שְׁלָשְׁתָּן כְּשֵׁרִים אוֹ פְּסוּלִים. אֲבָל אִם אָמַר עֵד אֶחָד רָאִיתִי הַהוֹרֵג וּשְׁתֵּי נָשִׁים אוֹ שְׁנֵי פְּסוּלִים אוֹמְרִים לוֹ לֹא רָאִיתָ אֵין עוֹרְפִין:","שְׁתֵּי נָשִׁים אוֹ שְׁנֵי פְּסוּלִים אוֹמְרִים רָאִינוּ הַהוֹרֵג וְעֵד אֶחָד מַכְחִישָׁם וְאוֹמֵר לֹא רְאִיתֶם עוֹרְפִים. שֶׁאֲפִילוּ מֵאָה נָשִׁים אוֹ מֵאָה פְּסוּלִים וְעֵד אֶחָד מַכְחִישׁ אֶת כֻּלָּן הֲרֵי אֵלּוּ כְּאִישׁ אֶחָד וְעֵד אֶחָד:","שָׁלֹשׁ נָשִׁים אוֹ שְׁלֹשָׁה פְּסוּלִים אוֹמְרִים רָאִינוּ הַהוֹרֵג וְאַרְבַּע נָשִׁים אוֹ אַרְבָּעָה פְּסוּלִים אוֹמְרִים לֹא רְאִיתֶם עוֹרְפִין. זֶה הַכְּלָל בִּפְסוּלִין [הַלֵּךְ] אַחַר רֹב הַמִּנְיָן בְּכָל מָקוֹם:"],"Mishneh Torah, Negative Mitzvot 10":["שלא לפנות אחר עבודה זרה, שנאמר (ויקרא יט, ד): \"אל תפנו אל האלילים\"."],"Mishneh Torah, Negative Mitzvot 110":["שלא למכור שדה החרם, שנאמר \"לא יימכר\" (ויקרא כז,כח)."],"Mishneh Torah, Negative Mitzvot 121":["שלא לשבור עצם בפסח, שנאמר (שמות יב, מו): \"ועצם לא תשברו בו\"."],"Mishneh Torah, Negative Mitzvot 132":["שלא לאכול פיגול, שנאמר \"המקריב אותו לא ייחשב לו, פיגול יהיה; והנפש האוכלת ממנו, עוונה תישא\" (ויקרא ז,יח); והוא בכרת."],"Mishneh Torah, Negative Mitzvot 143":["שלא לאכול מעשר שני של יצהר חוץ לירושלים, שנאמר \"ויצהרך\" (דברים יב,יז)."],"Mishneh Torah, Negative Mitzvot 154":["שלא להקדים תרומה לביכורים, ולא מעשר ראשון לתרומה, ולא מעשר שני לראשון, אלא מוציאין על הסדר: .ביכורים תחילה, ואחר כך תרומה גדולה, ואחר כך מעשר ראשון, ואחר כך מעשר שני; שנאמר \"מלאתך ודמעך, לא תאחר\" (שמות כב,כח), כלומר לא תאחר דבר הראוי להקדימו."],"Mishneh Torah, Negative Mitzvot 165":["שלא ייצא כוהן מן העזרה בשעת עבודה, שנאמר \"ומפתח אוהל מועד לא תצאו\" (ויקרא י,ז)."],"Mishneh Torah, Negative Mitzvot 176":["שלא לאכול שרץ הארץ, שנאמר \"וכל השרץ, השורץ על הארץ--שקץ הוא, לא ייאכל\" (ויקרא יא,מא)."],"Mishneh Torah, Negative Mitzvot 187":["שלא לאכול בשר בחלב, שנאמר \"לא תבשל גדי, בחלב אימו\" פעם שנייה (שמות לד,כו); כך למדו מפי השמועה, שאחד לאיסור בישול ואחד לאיסור אכילה."],"Mishneh Torah, Negative Mitzvot 198":["שלא לאכול תערובת חמץ, שנאמר \"כל מחמצת, לא תאכלו\" (שמות יב,כ)."],"Mishneh Torah, Negative Mitzvot 208":["שלא ייכנס באוהל המת, שנאמר \"על נפש מת, לא יבוא\" (במדבר ו,ו)."],"Mishneh Torah, Negative Mitzvot 219":["שלא לחסום בהמה בשעת מלאכה בדבר שאוכלת ממנו ונהנית, שנאמר \"לא תחסום שור, בדישו\" (דברים כה,ד)."],"Mishneh Torah, Negative Mitzvot 23":["שלא לבנות עיר הנידחת לכמות שהייתה, שנאמר \"לא תיבנה עוד\" (דברים יג,יז)."],"Mishneh Torah, Negative Mitzvot 240":["שלא למנוע העבוט מבעליו העני בעת שהוא צריך לו, שנאמר \"לא תשכב, בעבוטו\" (דברים כד,יב); כלומר, לא תשכב ועבוטו עימך, אלא תשיבנו לו בלילה, הואיל והוא צריך לו בלילה."],"Mishneh Torah, Negative Mitzvot 251":["שלא יונה בדברים, שנאמר \"ולא תונו איש את עמיתו\" (ויקרא כה, יז); זו אונאת דברים."],"Mishneh Torah, Negative Mitzvot 262":["שלא למנוע מאמה עברייה היעודה שאר כסות ועונה, שנאמר \"שְׁאֵרָהּ כְּסוּתָהּ וְעוֹנָתָהּ לֹא יִגְרָע\" (שמות כא, י); והוא הדין לשאר הנשים."],"Mishneh Torah, Negative Mitzvot 273":["שלא לעוול המשפט, שנאמר \"לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט\" (ויקרא יט, טו)."],"Mishneh Torah, Negative Mitzvot 284":["שלא למנות בדיינין אדם שאינו חכם בדברי תורה, אף על פי שהוא חכם בחכמות אחרות, שנאמר \"לֹא תַכִּירוּ פָּנִים בַּמִּשְׁפָּט\" (דברים א, יז)."],"Mishneh Torah, Negative Mitzvot 295":["שלא ליקח כופר מן הרוצח, שנאמר \"ולא תקחו כופר לנפש רוצח\" (במדבר לה, לא)."],"Mishneh Torah, Negative Mitzvot 305":["שלא לנטור, שנאמר \"לא תיטור\" (ויקרא יט,יח)."],"Mishneh Torah, Negative Mitzvot 316":["שלא לקלל הנשיא, והוא המלך או ראש ישיבת ארץ ישראל, שנאמר \"ונשיא בעמך, לא תאור\" (שמות כב,כז)."],"Mishneh Torah, Negative Mitzvot 327":["שלא לעשות מלאכה ביום הכיפורים, שנאמר בו \"כל מלאכה, לא תעשו\" (ויקרא טז,כט; ויקרא כג,כח; ויקרא כג,לא; במדבר כט,ז)."],"Mishneh Torah, Negative Mitzvot 338":["שלא לגלות ערוות אישה ובת בנה, שנאמר \"את בת בנה\" (ויקרא יח,יז)."],"Mishneh Torah, Negative Mitzvot 349":["שלא תביא אישה בהמה עליה, שנאמר \"ואישה, לא תעמוד לפני בהמה לרבעה\" (ויקרא יח,כג)."],"Mishneh Torah, Negative Mitzvot 36":["שלא לשאול באוב, שנאמר \"ושואל אוב\" (דברים יח,יא)."],"Mishneh Torah, Negative Mitzvot 41":["שלא לכתוב בגוף כעובדי עבודה זרה, שנאמר \"וכתובת קעקע, לא תיתנו בכם\" (ויקרא יט,כח)."],"Mishneh Torah, Negative Mitzvot 52":["שלא להתחתן בעובדי עבודה זרה, שנאמר \"ולא תתחתן, בם\" (דברים ז,ג)."],"Mishneh Torah, Negative Mitzvot 63":["שלא לחלל את שם הקדוש ברוך הוא, שנאמר \"וְלֹא תְחַלְּלוּ אֶת שֵׁם קָדְשִׁי\" (ויקרא כב, לב)."],"Mishneh Torah, Negative Mitzvot 74":["שלא יעבוד הזר במקדש, שנאמר \"וְזָר לֹא יִקְרַב אֲלֵיכֶם\" (במדבר יח, ד)."],"Mishneh Torah, Negative Mitzvot 85":["שלא לעשות במתכונת הקטורת, שנאמר \"ובמתכונתה, לא תעשו\" (ראה שמות ל,לז)."],"Mishneh Torah, Negative Mitzvot 96":["שלא להקריב בעל מום מיד הגויים, שנאמר \"ומיד בן נכר, לא תקריבו\" (ויקרא כב,כה)."],"Mishneh Torah, Neighbors 4":["מִי שֶׁהָיְתָה לוֹ עֲלִיָּה לְמַעְלָה מִבֵּיתוֹ שֶׁל חֲבֵרוֹ וְנָפַל כֹּתֶל מִכָּתְלֵי הַבַּיִת אֵין בַּעַל הָעֲלִיָּה נוֹתֵן לוֹ כְּלוּם בִּיצִיאוֹתָיו וְכוֹפֶה אֶת בַּעַל הַבַּיִת לִבְנוֹתוֹ כְּשֶׁהָיָה. אֲבָל אֵין בַּעַל הַבַּיִת כּוֹפֶה לְבַעַל הָעֲלִיָּה לִבְנוֹת כֹּתֶל עֲלִיָּה שֶׁנָּפַל. וְהַתִּקְרָה שֶׁל בַּיִת הֲרֵי הִיא שֶׁל בַּעַל הַבַּיִת וְהַמַּעֲזִיבָה שֶׁעַל הַתִּקְרָה הֲרֵי הִיא שֶׁל בַּעַל הָעֲלִיָּה:","נָפְלוּ שְׁנֵיהֶם הַבַּיִת וְהָעֲלִיָּה הֲרֵי שְׁנֵיהֶם חוֹלְקִין בָּעֵצִים וּבַאֲבָנִים וּבֶעָפָר. וְאִם נִשְׁתַּבְּרוּ מִקְצָת הָאֲבָנִים רוֹאִין אֵי זוֹ רְאוּיָה לְהִשְׁתַּבֵּר אִם אַבְנֵי הַבַּיִת אוֹ אַבְנֵי הָעֲלִיָּה. וְדָבָר זֶה יָדוּעַ מִדֶּרֶךְ הַנְּפִילָה אִם נָפַל הָעֶלְיוֹן עַל הַתַּחְתּוֹן וַהֲרָסוֹ אוֹ נִשְׁמַט הַתַּחְתּוֹן וְנָפַל הָעֶלְיוֹן וְנֶהֱרַס. וְאִם אֵינָן יוֹדְעִין כֵּיצַד נָפַל חוֹלְקִין הָאֲבָנִים הַשְּׁלֵמוֹת וְהַשְּׁבוּרוֹת:","אָמַר בַּעַל הָעֲלִיָּה לְבַעַל הַבַּיִת לִבְנוֹת כְּדֵי שֶׁיִּבְנֶה עֲלִיָּתוֹ עַל גַּבָּיו וְהוּא אֵינוֹ רוֹצֶה הֲרֵי בַּעַל הָעֲלִיָּה בּוֹנֶה אֶת הַבַּיִת כְּשֶׁהָיָה. וְיוֹשֵׁב וְדָר בְּתוֹכוֹ עַד אֲשֶׁר יִתֵּן כָּל יְצִיאוֹתָיו וְאַחַר כָּךְ יֵצֵא וְיִבְנֶה עֲלִיָּתוֹ אִם רוֹצֶה:","וְאִם אֵין אֶחָד מֵהֶן יָכוֹל לִבְנוֹת בַּעַל הָעֲלִיָּה נוֹטֵל שְׁלִישׁ הַקַּרְקַע וּבַעַל הַבַּיִת שְׁנֵי שְׁלִישִׁים:","רָצָה בַּעַל הַבַּיִת לִבְנוֹת בֵּיתוֹ בּוֹנֶה כְּשֶׁהָיָה. וְאִם בָּא לְשַׁנּוֹת בַּכְּתָלִים אִם חִזֵּק אוֹתָן וְהִרְבָּה בְּרָחְבָּן יוֹתֵר מִמַּה שֶּׁהָיוּ שׁוֹמְעִין לוֹ. רָצָה לְמַעֵט בְּרָחְבָּן אוֹ לִפְחוֹת מֵחָזְקָן כְּגוֹן שֶׁהָיוּ אֲבָנִים וּבִקֵּשׁ לְהַחְזִיר לְבֵנִים וְכַיּוֹצֵא בָּהֶן אֵין שׁוֹמְעִין לוֹ. בָּא לְשַׁנּוֹת אֶת הַתִּקְרָה לְקוֹרוֹת כְּבֵדִין וַחֲזָקִין שׁוֹמְעִין לוֹ. לִפְחוֹת בְּרָחְבָּן פָּחוֹת מִמַּה שֶּׁהָיוּ אֵין שׁוֹמְעִין לוֹ. הִרְבָּה בְּחַלּוֹנוֹת אוֹ שֶׁהוֹסִיף בְּגֹבַהּ הַבַּיִת אֵין שׁוֹמְעִין לוֹ. מִעֵט בְּחַלּוֹנוֹת אוֹ שֶׁמִּעֵט בְּגֹבַהּ הַבַּיִת שׁוֹמְעִין לוֹ. וְכֵן בַּעַל הָעֲלִיָּה בּוֹנֶה אוֹתָהּ אִם רָצָה כְּשֶׁהָיְתָה. וְאִם בָּא לְשַׁנּוֹת הַכְּתָלִים לְהַרְחִיב וּלְהַחְזִיק אֵין שׁוֹמְעִין לוֹ מִפְּנֵי שֶׁהוּא מַכְבִּיד עַל כֹּתֶל הַתַּחְתּוֹן. אֲבָל לְמַעֵט שׁוֹמְעִין לוֹ. וְכֵן בְּקוֹרוֹת תִּקְרָה הָעֶלְיוֹנָה אִם שִׁנָּה אוֹתָם לְקַלִּים מִמַּה שֶּׁהָיוּ שׁוֹמְעִין לוֹ. לִכְבֵדִים מֵהֶן אֵין שׁוֹמְעִין לוֹ. הִרְבָּה בְּחַלּוֹנוֹת אוֹ שֶׁמִּעֵט בְּגֹבַהּ הָעֲלִיָּה שׁוֹמְעִין לוֹ. אֲבָל אִם מִעֵט בְּחַלּוֹנוֹת אוֹ הִרְבָּה בְּגָבְהָהּ אֵין שׁוֹמְעִין לוֹ:","נִתְדַּלְדְּלוּ קוֹרוֹת הַבַּיִת וְיָרְדוּ לַאֲוִיר הַבַּיִת אִם הִגִּיעוּ לְתוֹךְ עֲשָׂרָה טְפָחִים סוֹתֵר וּבוֹנֶה. וְאִם לֹא הִגִּיעוּ יָכוֹל בַּעַל הָעֲלִיָּה לְעַכֵּב עָלָיו. וַאֲפִלּוּ אָמַר לוֹ בַּעַל הַבַּיִת אֲנִי אֶשְׂכֹּר לְךָ מָקוֹם כְּדֵי שֶׁתָּדוּר בּוֹ עַד שֶׁאֲתַקֵּן הַתִּקְרָה אֵין שׁוֹמְעִין לוֹ שֶׁהֲרֵי אוֹמֵר לוֹ אֵינִי רוֹצֶה שֶׁאֶטְרַח מִמָּקוֹם לְמָקוֹם כְּדֵי שֶׁתְּתַקֵּן אֶת בֵּיתְךָ:","הִתְנוּ בֵּינֵיהֶם עַל דָּבָר זֶה. אִם נִשְׁאַר בְּגֹבַהּ הַבַּיִת כְּדֵי שֶׁיִּקַּח אָדָם חֲבִילָה בֵּינוֹנִית עַל רֹאשׁוֹ וְיִכָּנֵס בָּהּ תַּחַת קוֹרוֹת אֵלּוּ שֶׁנֶּעֶקְמוּ אֵינוֹ סוֹתֵר. וְאִם אֵינוֹ יָכוֹל לְהִכָּנֵס בָּהּ עַד שֶׁיָּכֹף אֶת רֹאשׁוֹ סוֹתֵר וּמְתַקֵּן וּבוֹנֶה. וְאֵין בַּעַל הָעֲלִיָּה יָכוֹל לְעַכֵּב שֶׁהֲרֵי הִתְנוּ בֵּינֵיהֶם תְּחִלָּה:","בֵּית הַבַּד שֶׁהוּא בָּנוּי בָּעֳבִי הָהָר וְגִנָּה אַחַת עַל גַּבָּיו. וְנִפְחֲתוּ שְׁמֵי בֵּית הַבַּד כְּאַרְבָּעָה טְפָחִים אוֹ יוֹתֵר. הֲרֵי בַּעַל הַגִּנָּה יוֹרֵד וְזוֹרֵעַ לְמַטָּה עַד שֶׁיַּעֲשֶׂה זֶה לַבַּיִת בַּדוֹ כֵּיפִין. וִיתַקֵּן הָעֶלְיוֹן קַרְקַע גִּנָּתוֹ וְיִזְרַע כָּל גִּנָּתוֹ:","שְׁתֵּי גִּנּוֹת זוֹ עַל גַּב זוֹ וְהַיָּרָק בֵּינְתַיִם בְּגֹבַהּ עֳבִי הָאָרֶץ שֶׁבֵּינֵיהֶם. כָּל שֶׁהָעֶלְיוֹן יָכוֹל לִפְשֹׁט אֶת יָדוֹ וְלִטּל אוֹתוֹ מֵעִקָּרוֹ הֲרֵי הוּא שֶׁלּוֹ וּבִלְבַד שֶׁלֹּא יֶאֱנֹס אֶת עַצְמוֹ וְהַשְּׁאָר שֶׁל תַּחְתּוֹן. הָיָה מַגִּיעַ לְנוֹפוֹ וְאֵינוֹ מַגִּיעַ לְעִקָּרוֹ לֹא יִטּל הָעֶלְיוֹן וְאִם נָטַל אֵין מוֹצִיאִין אוֹתוֹ מִיָּדוֹ. אֲבָל הָאִילָן הָעוֹמֵד עַל הַמֵּצַר אַף עַל פִּי שֶׁהוּא נוֹטֶה לְתוֹךְ שָׂדֶה אַחַת מֵהֶן הֲרֵי שְׁנֵיהֶם חוֹלְקִין בְּפֵרוֹתָיו:","שָׁטַף נָהָר אֶת זֵיתָיו וּשְׁתָלָם בְּתוֹךְ שְׂדֵה חֲבֵרוֹ וְאָמַר הַלָּה זֵיתַי אֲנִי נוֹטֵל אֵין שׁוֹמְעִין לוֹ מִשּׁוּם יִשּׁוּב הָאָרֶץ אֶלָּא יַעַמְדוּ בִּמְקוֹמָן. וְאִם עֲקָרָן הַנָּהָר בְּגוּשֵׁיהֶן כְּשֶׁשְּׁתָלָן יַחְלְקוּ הַפֵּרוֹת בַּעַל הַשָּׂדֶה עִם בַּעַל הַזֵּיתִים כָּל שָׁלֹשׁ שָׁנִים וּלְאַחַר שָׁלֹשׁ הַכּל לְבַעַל הַשָּׂדֶה. וְאִם לֹא נֶעֶקְרוּ בְּגוּשֵׁיהֶן הַכּל לְבַעַל הַקַּרְקַע מִיָּד:","כַּיּוֹצֵא בּוֹ הַמּוֹכֵר זֵיתָיו לְעֵצִים אִם פָּסַק עִמּוֹ לָקֹץ מִיַּד כָּל הַפֵּרוֹת שֶׁיַּעֲשׂוּ הֲרֵי הֵן לְבַעַל הַקַּרְקַע. וְאִם הִתְנָה עִמּוֹ לָקֹץ כָּל זְמַן שֶׁיִּרְצֶה כָּל הַפֵּרוֹת שֶׁיּוֹצִיאוּ לְבַעַל הָעֵצִים. מָכַר סְתָם אִם עָשׂוּ פָּחוֹת מֵרְבִיעִית לִסְאָה חוּץ מִן הַהוֹצָאָה הֲרֵי אֵלּוּ שֶׁל בַּעַל הַזֵּיתִים. עָשׂוּ רְבִיעִית לִסְאָה חוּץ מִן הַהוֹצָאָה הֲרֵי אֵלּוּ יַחֲלֹקוּ:"],"Mishneh Torah, Oaths 4":["מִי שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכַל הַיּוֹם כְּלוּם וְאָכַל פָּחוֹת מִכְּזַיִת פָּטוּר. שֶׁאֵין אֲכִילָה פְּחוּתָה מִכְּזַיִת. וַהֲרֵי הוּא כְּאוֹכֵל חֲצִי שִׁעוּר מִנְּבֵלוֹת וּטְרֵפוֹת וְכַיּוֹצֵא בָּהֶן. וְאִם אָמַר שְׁבוּעָה שֶׁלֹּא אֹכַל דָּבָר זֶה וַאֲכָלוֹ חַיָּב. וַאֲפִלּוּ הָיָה הַדָּבָר שֶׁנִּשְׁבַּע עָלָיו זֶרַע חַרְדָּל אֶחָד אוֹ פָּחוֹת מִמֶּנּוּ:","נִשְׁבַּע שֶׁלֹּא יִטְעֹם כְּלוּם וְאָכַל כָּל שֶׁהוּא חַיָּב:","מִי שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכַל הַיּוֹם וְשָׁתָה חַיָּב שֶׁהַשְּׁתִיָּה בִּכְלַל אֲכִילָה. לְפִיכָךְ אִם אָכַל וְשָׁתָה אֵינוֹ חַיָּב אֶלָּא מַלְקוֹת אַחַת אִם הָיָה מֵזִיד אוֹ חַטָּאת אַחַת אִם הָיָה שׁוֹגֵג:","נִשְׁבַּע שֶׁלֹּא יִשְׁתֶּה הַיּוֹם הֲרֵי זֶה מֻתָּר לֶאֱכל. שֶׁאֵין אֲכִילָה בִּכְלַל שְׁתִיָּה. וְכַמָּה יִשְׁתֶּה וִיהֵא חַיָּב. נִרְאֶה לִי שֶׁאֵינוֹ חַיָּב עַד שֶׁיִּשְׁתֶּה רְבִיעִית כִּשְׁאָר הָאִסּוּרִין:","שְׁבוּעָה שֶׁלֹּא אֹכַל הַיּוֹם וְאָכַל מִינִין הַרְבֵּה. אוֹ שְׁבוּעָה שֶׁלֹּא אֶשְׁתֶּה הַיּוֹם וְשָׁתָה מִינֵי מַשְׁקִין הַרְבֵּה אֵינוֹ חַיָּב אֶלָּא אַחַת. וַאֲפִלּוּ אָמַר שְׁבוּעָה שֶׁלֹּא אֹכַל הַיּוֹם בָּשָׂר וּפַת וְקִטְנִית וְאָכַל הַכּל אֵינוֹ חַיָּב אֶלָּא אַחַת. וְכֻלָּן מִצְטָרְפִין לִכְזַיִת:","שְׁבוּעָה שֶׁלֹּא אֹכַל וְשֶׁלֹּא אֶשְׁתֶּה וְאָכַל וְשָׁתָה חַיָּב שְׁתַּיִם שֶׁהַשְּׁתִיָּה בִּכְלַל אֲכִילָה. וְהוֹאִיל וּפֵרֵט וְאָמַר וְשֶׁלֹּא אֶשְׁתֶּה גִּלָּה דַּעְתּוֹ שֶׁלֹּא כָּלַל הַשְּׁתִיָּה בִּכְלַל הָאֲכִילָה וְנִמְצָא כְּנִשְׁבָּע עַל זֶה בִּפְנֵי עַצְמוֹ וְעַל זֶה בִּפְנֵי עַצְמוֹ וּלְפִיכָךְ חַיָּב שְׁתַּיִם:","וְכֵן הָאוֹמֵר שְׁבוּעָה שֶׁלֹּא אֹכַל פַּת חִטִּין וּפַת שְׂעוֹרִין וּפַת כֻּסְּמִין וַאֲכָלָן חַיָּב עַל כָּל אַחַת וְאַחַת שֶׁלֹּא אָמַר פַּת וּפַת וּפַת אֶלָּא לְחַלֵּק וּלְחַיֵּב עַל כָּל אַחַת:","הָיָה חֲבֵרוֹ מְסַרְהֵב בּוֹ לֶאֱכל אֶצְלוֹ וְאָמַר לוֹ בּוֹא וּשְׁתֵה עִמִּי יַיִן וְחָלָב וּדְבַשׁ. וְאָמַר שְׁבוּעָה שֶׁאֵינִי שׁוֹתֶה יַיִן וְחָלָב וּדְבַשׁ וְשָׁתָה מֵהֶן חַיָּב עַל כָּל אַחַת וְאַחַת בִּפְנֵי עַצְמוֹ. שֶׁהָיָה לוֹ לוֹמַר שְׁבוּעָה שֶׁאֵינִי שׁוֹתֶה כְּלוּם אוֹ מַה שֶּׁאָמַרְתָּ וּמִשֶּׁחָזַר וּפֵרֵט גִּלָּה דַּעְתּוֹ שֶׁחִיֵּב עַצְמוֹ בִּשְׁבוּעָה עַל כָּל מִין וּמִין בִּפְנֵי עַצְמוֹ. לְפִיכָךְ אֵין מִצְטָרְפִין זֶה עִם זֶה וְאֵינוֹ חַיָּב עַד שֶׁיֹּאכַל כַּשִּׁעוּר מִמִּין אֶחָד. הוֹאִיל וְהֵן חֲלוּקִין לְחַטָּאוֹת הֲרֵי הֵן כְּחֵלֶב וְדָם שֶׁאֵינָן מִצְטָרְפִין לִכְזַיִת כְּמוֹ שֶׁנִּתְבָּאֵר בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת:","שְׁבוּעָה שֶׁלֹּא אֹכַל כִּכָּר זוֹ אוֹ שֶׁלֹּא אֹכַל אוֹתָהּ כֵּיוָן שֶׁאָכַל מִמֶּנָּה כְּזַיִת חַיָּב. שְׁבוּעָה שֶׁלֹּא אֹכָלֶנָּה אֵינוֹ חַיָּב עַד שֶׁיֹּאכַל אֶת כֻּלָּהּ. אָמַר שְׁבוּעָה שֶׁלֹּא אֹכַל כִּכָּר זוֹ שְׁבוּעָה שֶׁלֹּא אֹכָלֶנָּה וַאֲכָלָהּ אֵינוֹ חַיָּב אֶלָּא אַחַת:","וְכֵן אִם אָמַר שְׁבוּעָה שֶׁלֹּא אֹכַל הַיּוֹם וְחָזַר וְנִשְׁבַּע עַל הַכִּכָּר שֶׁלֹּא יֹאכָלֶנָּה וַאֲכָלָהּ כֻּלָּהּ בְּאוֹתוֹ הַיּוֹם אֵינוֹ חַיָּב אֶלָּא אַחַת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. שֶׁאֵין שְׁבוּעָה חָלָה עַל שְׁבוּעָה. אֲבָל אִם נִשְׁבַּע עַל הַכִּכָּר שֶׁלֹּא יֹאכָלֶנָּה וְחָזַר וְנִשְׁבַּע שֶׁלֹּא יֹאכַל כְּלוּם. אוֹ שֶׁלֹּא יֹאכַל כִּכָּר זוֹ וַאֲכָלָהּ כֻּלָּהּ חַיָּב שְׁתַּיִם. שֶׁבְּשָׁעָה שֶׁנִּשְׁבַּע בַּתְּחִלָּה שֶׁלֹּא יֹאכְלֶנָּה אֵינוֹ חַיָּב עַד שֶׁיֹּאכַל כֻּלָּהּ. וּכְשֶׁחָזַר וְנִשְׁבַּע שֶׁלֹּא יֹאכַל [כְּלוּם] אוֹ שֶׁלֹּא יֹאכַל אוֹתָהּ מִשֶּׁיֹּאכַל מִמֶּנָּה כְּזַיִת יִתְחַיֵּב וּכְשֶׁיֹּאכַל כֻּלָּהּ יִתְחַיֵּב בִּשְׁבוּעָה רִאשׁוֹנָה:","שְׁבוּעָה שֶׁלֹּא אֹכַל תְּאֵנִים. וְחָזַר וְנִשְׁבַּע עַל הַתְּאֵנִים וְעַל הָעֲנָבִים. חַיָּב עַל הַתְּאֵנִים שְׁתַּיִם שֶׁהֲרֵי כָּלַל הַתְּאֵנִים שֶׁנֶּאֶסְרוּ בִּשְׁבוּעָה רִאשׁוֹנָה עִם הָעֲנָבִים שֶׁהָיוּ מֻתָּרִין וּמִתּוֹךְ שֶׁחָלָה שְׁבוּעָה שְׁנִיָּה עַל הָעֲנָבִים חָלָה עַל הַתְּאֵנִים וְנִתְחַיֵּב בִּשְׁתֵּי שְׁבוּעוֹת כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת:","שְׁבוּעָה שֶׁלֹּא אֹכַל שְׁמוֹנֶה. שְׁבוּעָה שֶׁלֹּא אֹכַל תֵּשַׁע. שְׁבוּעָה שֶׁלֹּא אֹכַל עֶשֶׂר. בֵּין שֶׁאָכַל שְׁמוֹנֶה בֵּין שֶׁאָכַל תֵּשַׁע בֵּין שֶׁאָכַל עֶשֶׂר אֵינוֹ חַיָּב אֶלָּא אַחַת:","שְׁבוּעָה שֶׁלֹּא אֹכַל עֶשֶׂר. שְׁבוּעָה שֶׁלֹּא אֹכַל תֵּשַׁע. שְׁבוּעָה שֶׁלֹּא אֹכַל שְׁמוֹנֶה. אִם אָכַל עֶשֶׂר חַיָּב שָׁלֹשׁ עַל כָּל שְׁבוּעָה וּשְׁבוּעָה אַחַת. וְכֵן אִם אָכַל תֵּשַׁע חַיָּב שְׁתַּיִם. אָכַל שְׁמוֹנֶה חַיָּב אַחַת:","שְׁבוּעָה שֶׁלֹּא אֹכַל תְּאֵנִים וְחָזַר וְנִשְׁבַּע שֶׁלֹּא יֹאכַל תְּאֵנִים וַעֲנָבִים כְּאַחַת. וְשָׁגַג וְאָכַל תְּאֵנִים וְהִפְרִישׁ קָרְבָּן. וְאַחַר כָּךְ שָׁגַג וְאָכַל עֲנָבִים אֵינוֹ חַיָּב עַל הָעֲנָבִים מִפְּנֵי שֶׁהֵן כַּחֲצִי שִׁעוּר וְאֵין מְבִיאִין קָרְבָּן עַל חֲצִי שִׁעוּר:","וְכֵן הַנִּשְׁבָּע שֶׁלֹּא יֹאכַל עֶשֶׂר וְחָזַר וְנִשְׁבַּע שֶׁלֹּא יֹאכַל עֶשֶׂר וְתֵשַׁע וְאָכַל עֶשֶׂר וְהִפְרִישׁ קָרְבָּן וְחָזַר וְשָׁגַג וְאָכַל תֵּשַׁע הֲרֵי זֶה כַּחֲצִי שִׁעוּר. וְאֵין מְבִיאִין קָרְבָּן עַל חֲצִי שִׁעוּר. שֶׁעִנְיַן שְׁבוּעָה אַחֲרוֹנָה שֶׁלֹּא יֹאכַל תֵּשַׁע וְעֶשֶׂר:","שְׁבוּעָה שֶׁלֹּא אֹכַל כִּכָּר זוֹ הַגְּדוֹלָה אִם אֹכַל כִּכָּר זוֹ הַקְּטַנָּה וְשָׁכַח תְּנַאי זֶה בְּעֵת שֶׁאָכַל הַקְּטַנָּה וְאָכַל אַחַר כָּךְ הַגְּדוֹלָה בְּמֵזִיד חַיָּב:","אָכַל אֶת הַקְּטַנָּה וְהוּא זוֹכֵר הַתְּנַאי וְיוֹדֵעַ שֶׁבַּאֲכִילָתָהּ תֵּאָסֵר הַגְּדוֹלָה וְשָׁכַח וְאָכַל אֶת הַגְּדוֹלָה וְכִמְדֻמֶּה לוֹ שֶׁעֲדַיִן לֹא נֶאֶסְרָה פָּטוּר. אָכַל שְׁתֵּיהֶן בִּשְׁגָגָה פָּטוּר. שְׁתֵּיהֶן בְּמֵזִיד בֵּין שֶׁאָכַל הַגְּדוֹלָה בַּתְּחִלָּה אוֹ בָּאַחֲרוֹנָה חַיָּב:","וְכֵן אִם תְּלָאָן זוֹ בָּזוֹ וְנִשְׁבַּע וְאָמַר שְׁבוּעָה שֶׁלֹּא אֹכַל אַחַת מֵהֶם אִם אָכַלְתִּי הָאַחֶרֶת וְשָׁכַח הַתְּנַאי וְאָכַל אַחַת מֵהֶן וְאָכַל הַשְּׁנִיָּה בְּזָדוֹן חַיָּב:","אָכַל הָרִאשׁוֹנָה בְּזָדוֹן וְהַשְּׁנִיָּה בִּשְׁגָגָה פָּטוּר. שְׁתֵּיהֶן בְּזָדוֹן חַיָּב:","שְׁבוּעָה שֶׁאֹכַל כִּכָּר זוֹ הַיּוֹם וְעָבַר הַיּוֹם וְלֹא אֲכָלָהּ. בְּשׁוֹגֵג מֵבִיא קָרְבָּן עוֹלֶה וְיוֹרֵד. בְּמֵזִיד אֵינוֹ לוֹקֶה שֶׁהֲרֵי לֹא עָשָׂה מַעֲשֶׂה וְאַף עַל פִּי שֶׁעָבַר עַל שְׁבוּעַת שֶׁקֶר:","וּמִפְּנֵי מָה לוֹקֶה אִם נִשְׁבַּע שֶׁאָכַל וְהוּא לֹא אָכַל אוֹ שֶׁלֹּא אָכַל וְהוּא אָכַל וְאַף עַל פִּי שֶׁלֹּא עָשָׂה מַעֲשֶׂה. מִפְּנֵי שֶׁמֵּעֵת שְׁבוּעָתוֹ לַשֶּׁקֶר נִשְׁבַּע. אֲבָל אִם נִשְׁבַּע שֶׁיַּעֲשֶׂה וְהוּא לֹא עָשָׂה אֵינָהּ שְׁבוּעַת שֶׁקֶר מִשְּׁעַת שְׁבוּעָה:","מִי שֶׁאָמַר לַחֲבֵרוֹ שְׁבוּעָה לֹא אֹכַל לְךָ אוֹ שְׁבוּעָה שֶׁאֵינִי אוֹכֵל לְךָ אוֹ שֶׁהָיָה מְסַרְהֵב בּוֹ לֶאֱכל אֶצְלוֹ וְהוּא נִמְנַע וְנִשְׁבַּע וְאָמַר שְׁבוּעָה שֶׁאֹכַל לְךָ. וְכֵן הָאוֹמֵר לֹא שְׁבוּעָה לֹא אֹכַל לְךָ. כָּל אֵלּוּ אֲסוּרִין וַהֲרֵי נִשְׁבַּע שֶׁלֹּא יֹאכַל אֶצְלוֹ. וְאִם אָמַר כָּל הַלְּשׁוֹנוֹת הָאֵלּוּ וְעָבַר וְאָכַל אֵינוֹ חַיָּב אֶלָּא אַחַת:"],"Mishneh Torah, Offerings for Unintentional Transgressions 10":["שִׁשָׁה מִצְוָתָן שֶׁיַּקְרִיבוּ קָרְבָּן עוֹלֶה וְיוֹרֵד וְאֵלּוּ הֵן. הַמְצֹרָע. וְהַיּוֹלֶדֶת. וְהַנִּשְׁבָּע שְׁבוּעַת הָעֵדוּת בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה. וְהַנִּשְׁבָּע שְׁבוּעַת בִּטּוּי לַשֶּׁקֶר בִּשְׁגָגָה. וְהַטָּמֵא שֶׁאָכַל קֹדֶשׁ בִּשְׁגָגָה. וְהַטָּמֵא שֶׁנִּכְנַס לַמִּקְדָּשׁ בִּשְׁגָגָה:","קָרְבַּן הַיּוֹלֶדֶת אִם הָיְתָה עֲשִׁירָה מְבִיאָה כֶּבֶשׂ בֶּן שְׁנָתוֹ לְעוֹלָה וּבֶן יוֹנָה אוֹ תּוֹר לְחַטָּאת. וְאִם אֵין יָדָהּ מַשֶּׂגֶת הֲרֵי קָרְבָּנָהּ יוֹרֵד וּמְבִיאָה שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה אֶחָד עוֹלָה וְאֶחָד חַטָּאת. אֲפִלּוּ הָיְתָה יָדָהּ מַשֶּׂגֶת לְשֶׂה וְאֵינָהּ מַשֶּׂגֶת לִנְסָכָיו מְבִיאָה קָרְבַּן עָנִי:","הַמְצֹרָע כְּשֶׁיִּטְהַר מֵבִיא שָׁלֹשׁ בְּהֵמוֹת מֵהֶן שְׁנֵי כְּבָשִׂים אֶחָד עוֹלָה וְאֶחָד אָשָׁם וְכַבְשָׂה לְחַטָּאת. אִם אֵין יָדוֹ מַשֶּׂגֶת מֵבִיא שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה אֶחָד עוֹלָה וְאֶחָד חַטָּאת. וְכֶבֶשׂ לְאָשָׁם:","עַל שְׁבוּעַת הָעֵדוּת וְעַל שִׁגְגַת שְׁבוּעַת בִּטּוּי וְעַל שִׁגְגַת טֻמְאַת מִקְדָּשׁ וְטֻמְאַת קָדָשָׁיו מֵבִיא כִּשְׂבָּה אוֹ שְׂעִירָה כִּשְׁאָר הַחַטָּאוֹת הַקְּבוּעוֹת. וְאִם אֵין יָדוֹ מַשֶּׂגֶת מֵבִיא שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה אֶחָד עוֹלָה וְאֶחָד חַטָּאת. וְאִם אֵין יָדוֹ מַשֶּׂגֶת לְעוֹף מֵבִיא עֲשִׂירִית הָאֵיפָה סלֶת וְהִיא הַקְּרוּיָה מִנְחַת חוֹטֵא שֶׁכְּבָר נִתְפָּרְשׁוּ מַעֲשֶׂיהָ בְּהִלְכוֹת מַעֲשֵׂה הַקָּרְבָּנוֹת:","כָּל הַקָּרְבָּנוֹת הָאֵלּוּ מְפֹרָשִׁין בַּתּוֹרָה וּמְפֹרָשׁ זֶה שֶׁחַיָּב לַהֲבִיאָן. חוּץ מִטָּמֵא שֶׁנִּכְנַס לַמִּקְדָּשׁ בִּשְׁגָגָה אוֹ אָכַל קֹדֶשׁ שֶׁכָּךְ כָּתוּב שָׁם (ויקרא ה א) \"וְנֶפֶשׁ כִּי תֶחֱטָא וְשָׁמְעָה קוֹל אָלָה\" וְגוֹ'. (ויקרא ה ב) \"אוֹ נֶפֶשׁ אֲשֶׁר תִּגַּע בְּכָל דָּבָר טָמֵא\" וְגוֹ'. (ויקרא ה ד) \"אוֹ נֶפֶשׁ כִּי תִשָּׁבַע לְבַטֵּא בִשְׂפָתַיִם\" וְגוֹ'. (ויקרא ה ה) \"וְהָיָה כִי יֶאְשַׁם לְאַחַת מֵאֵלֶּה\" וְגוֹ'. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁחִיֵּב כָּאן קָרְבָּן לְטָמֵא כְּשֶׁנִּטְמָא וְנִכְנַס לַמִּקְדָּשׁ אוֹ אָכַל קֹדֶשׁ וְהוּא לֹא יָדַע אַף עַל פִּי שֶׁהַדָּבָר מִפִּי הַקַּבָּלָה הֲרֵי הוּא כִּמְפֹרָשׁ שֶׁהֲרֵי בְּפֵרוּשׁ חִיְּבָה תּוֹרָה כָּרֵת לְטָמֵא שֶׁאָכַל קֹדֶשׁ וּלְטָמֵא שֶׁנִּכְנַס לַמִּקְדָּשׁ. בְּאוֹכֵל נֶאֱמַר (ויקרא ז כ) \"וְהַנֶּפֶשׁ אֲשֶׁר תֹּאכַל בָּשָׂר מִזֶּבַח הַשְּׁלָמִים אֲשֶׁר לַה' וְטֻמְאָתוֹ עָלָיו וְנִכְרְתָה\". וּבְנִכְנָס לַמִּקְדָּשׁ נֶאֱמַר (במדבר יט כ) \"וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מִתּוֹךְ הַקָּהָל כִּי אֶת מִקְדַּשׁ ה' טִמֵּא\". וְכֵיוָן שֶׁחִיְּבָה תּוֹרָה כָּרֵת עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו פֵּרֵשׁ הַקָּרְבָּן שֶׁמְּבִיאִין עַל שִׁגְגָתָן:","כָּל קָרְבָּנוֹת שֶׁהָאִשָּׁה חַיֶּבֶת בַּעְלָהּ מֵבִיא עַל יָדֶיהָ. אִם הָיָה עָנִי מֵבִיא קָרְבַּן עָנִי וְאִם הָיָה עָשִׁיר מֵבִיא עַל יָדֶיהָ קָרְבַּן עָשִׁיר. וּמֵבִיא אָדָם עַל יְדֵי בְּנוֹ וְעַל יְדֵי בִּתּוֹ וְעַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ קָרְבַּן עָנִי וּמַאֲכִילָן בִּזְבָחִים:","הַמֶּלֶךְ וְכֹהֵן מָשִׁיחַ מְבִיאִין קָרְבָּנָן עַל שְׁבוּעַת הָעֵדוּת אוֹ עַל שְׁבוּעַת בִּטּוּי אוֹ עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו כִּשְׁאָר הֶדְיוֹטוֹת. שֶׁלֹּא חִלֵּק הַכָּתוּב קָרְבַּן מֶלֶךְ מִקָּרְבַּן הֶדְיוֹט וּמִקָּרְבַּן כֹּהֵן מָשִׁיחַ אֶלָּא בְּמִצְווֹת שֶׁחַיָּבִים עַל שִׁגְגָתָן חַטָּאת קְבוּעָה כְּמוֹ שֶׁבֵּאַרְנוּ אֲבָל בְּקָרְבָּן עוֹלֶה וְיוֹרֵד כֻּלָּן שָׁוִים. כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת שְׁבוּעוֹת אֵימָתַי יִהְיֶה חַיָּב עַל שְׁבוּעַת הָעֵדוּת וְעַל שְׁבוּעַת שִׁגְגַת בִּטּוּי וְאֵימָתַי יִהְיֶה פָּטוּר עֲלֵיהֶן וְעַל אֵי זוֹ דֶּרֶךְ יִהְיֶה חַיָּב קָרְבָּנוֹת הַרְבֵּה כְּמִנְיַן הַשְּׁבוּעוֹת וְעַל אֵי זֶה דֶּרֶךְ לֹא יִהְיֶה חַיָּב אֶלָּא קָרְבָּן אֶחָד. וּבְהִלְכוֹת מְחֻסְּרֵי כַּפָּרָה אֲבָאֵר בְּאֵיזֶה דֶּרֶךְ תִּתְחַיֵּב הַיּוֹלֶדֶת וְהַמְצֹרָע קָרְבָּנוֹת הַרְבֵּה וּבְאֵי זֶה דֶּרֶךְ יִתְחַיֵּב כָּל אֶחָד מֵהֶן קָרְבָּן אֶחָד:","כָּל הַמֵּבִיא קָרְבָּן עַל הַזָּדוֹן כִּשְׁגָגָה. אִם הָיָה אָנוּס פָּטוּר מִן הַקָּרְבָּן. וְאֵין צָרִיךְ לוֹמַר שְׁאָר עֲבֵרוֹת שֶׁאֵינוֹ חַיָּב חַטָּאת אֶלָּא עַל שִׁגְגָתָן שֶׁאִם הָיָה אָנוּס פָּטוּר:","מִי שֶׁהִפְרִישׁ מָעוֹת לְכַבְשָׂה שֶׁל חַטָּאתוֹ וְצָרִיךְ לָהֶן. הֲרֵי זֶה מֵבִיא שְׂעִירָה וִיחַלֵּל אוֹתָם הַמָּעוֹת עַל הַשְּׂעִירָה וְיֵהָנֶה בָּהֶן. וְכֵן אִם הִפְרִישׁ לִשְׂעִירָה וְלָקַח כִּשְׂבָּה יֵהָנֶה בָּהֶן:","הִפְרִישׁ מָעוֹת לִבְהֵמָה וְהֶעֱנִי יִקַּח שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה וִיחַלֵּל עֲלֵיהֶן אוֹתָם הַמָּעוֹת וְיֵהָנֶה בָּהֶם. הִפְרִישׁ מָעוֹת לִבְנֵי יוֹנָה אוֹ לְתוֹרִים וְהֶעֱנִי. יָבִיא עֲשִׂירִית הָאֵיפָה וִיחַלֵּל עֲלֵיהֶן אוֹתָם הַמָּעוֹת וְיֵהָנֶה בָּהֶן. וְכֵן אִם הָיָה עָנִי וְהִפְרִישׁ מָעוֹת לַעֲשִׂירִית הָאֵיפָה וְהֶעֱשִׁיר יוֹסִיף עֲלֵיהֶן וְיָבִיא עוֹף. הִפְרִישׁ לְעוֹף וְהֶעֱשִׁיר יוֹסִיף עֲלֵיהֶן וְיָבִיא כִּשְׂבָּה אוֹ שְׂעִירָה. אֲפִלּוּ הָיָה מוֹרִישׁוֹ גּוֹסֵס הֲרֵי זֶה עָנִי עַד שֶׁיָּמוּת מוֹרִישׁוֹ וְיִירָשֶׁנּוּ:","עָשִׁיר שֶׁהִפְרִישׁ כִּשְׂבָּה אוֹ שְׂעִירָה וְנָפַל בָּהּ מוּם [וְהֶעֱנִי] אִם רָצָה יָבִיא בְּדָמֶיהָ עוֹף אֲבָל אִם הִפְרִישׁ עוֹף וְנִפְסַל לֹא יָבִיא בְּדָמָיו עֲשִׂירִית הָאֵיפָה שֶׁאֵין לָעוֹף פִּדְיוֹן:","הִפְרִישׁ עֲשִׂירִית הָאֵיפָה וְהֶעֱשִׁיר. עַד שֶׁלֹּא קָדְשָׁה בִּכְלִי הֲרֵי הִיא כְּכָל הַמְּנָחוֹת וְתִפָּדֶה וְתֵאָכֵל. וּמִשֶּׁקָּדְשָׁהּ בִּכְלִי תְּעֻבַּר צוּרָתָהּ וְתֵצֵא לְבֵית הַשְּׂרֵפָה:","עָשִׁיר שֶׁהִפְרִישׁ קֵן לְמָכְרָהּ וְלִקַּח בְּדָמֶיהָ כִּשְׂבָּה אוֹ שְׂעִירָה וְהֶעֱנִי יָבִיא קֵן זוֹ אַף עַל פִּי שֶׁהִיא קְדֵשַּׁת דָּמִים שֶׁהִיא נִדְחֵית. וְלָמָּה לֹא נִדְחֵית מִפְּנֵי שֶׁדִּחוּי מֵעִקָּרוֹ אֵינוֹ דִּחוּי וַהֲרֵי נִרְאֶה קֵן זוֹ לוֹ עַתָּה. עָנִי שֶׁהִקְרִיב קָרְבַּן עָשִׁיר יָצָא וְעָשִׁיר שֶׁהִקְרִיב קָרְבַּן עָנִי לֹא יָצָא:"],"Mishneh Torah, Offerings for Unintentional Transgressions 8":["כָּל חֵטְא שֶׁחַיָּבִין עַל שִׁגְגָתוֹ חַטָּאת קְבוּעָה חַיָּבִין עַל לֹא הוֹדַע שֶׁלּוֹ אָשָׁם תָּלוּי. וּמַהוּ לֹא הוֹדַע. אִם נִסְתַּפֵּק לוֹ אִם שָׁגַג בְּדָבָר זֶה אוֹ לֹא שָׁגַג הֲרֵי זֶה מְצֻוֶּה לְהַקְרִיב אָשָׁם שֶׁנֶּאֱמַר (ויקרא ה יז) \"וְלֹא יָדַע וְאָשֵׁם וְנָשָׂא עֲוֹנוֹ\" (ויקרא ה יח) \"וְהֵבִיא אַיִל תָּמִים מִן הַצֹּאן בְּעֶרְכְּךָ לְאָשָׁם\" וְזֶהוּ הַנִּקְרָא אָשָׁם תָּלוּי מִפְּנֵי שֶׁהוּא מְכַפֵּר עַל הַסָּפֵק וְתוֹלֶה לוֹ עַד שֶׁיִּוָּדַע לוֹ בְּוַדַּאי שֶׁחָטָא בִּשְׁגָגָה וְיַקְרִיב חַטָּאתוֹ:","אֵינוֹ חַיָּב בְּאָשָׁם תָּלוּי עַד שֶׁיִּהְיֶה שָׁם אִסּוּר קָבוּעַ. כֵּיצַד. אָכַל חֵלֶב וְסָפֵק אִם הָיָה כְּזַיִת אוֹ פָּחוֹת מִכְּזַיִת. אוֹ שֶׁהָיְתָה לְפָנָיו חֲתִיכַת חֵלֶב וַחֲתִיכַת שֻׁמָּן וְאָכַל אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זֶה מֵהֶן אָכַל. אִשְׁתּוֹ וַאֲחוֹתוֹ עִמּוֹ בַּבַּיִת בָּעַל אַחַת מֵהֶן וְאֵין יוֹדֵעַ אֵי זוֹ מֵהֶן בָּעַל. שַׁבָּת וְחל וְעָשָׂה מְלָאכוֹת בְּאֶחָד מֵהֶם וְאֵין יָדוּעַ בְּאֵי זֶה יוֹם עָשָׂה. אוֹ שֶׁעָשָׂה מְלָאכָה בְּשַׁבָּת וְלֹא יָדַע מֵעֵין אֵי זוֹ מְלָאכָה עָשָׂה. הֲרֵי זֶה מֵבִיא אָשָׁם תָּלוּי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל אִם הָיְתָה לְפָנָיו חֲתִיכָה אַחַת סָפֵק שֶׁהִיא חֵלֶב סָפֵק שֶׁהִיא שֻׁמָּן וַאֲכָלָהּ פָּטוּר שֶׁהֲרֵי אֵין כָּאן אִסּוּר קָבוּעַ. וְכָל הָאוֹכֵל חֵלֶב הַכְּוִי פָּטוּר מֵאָשָׁם תָּלוּי שֶׁהֲרֵי אֵין כָּאן אִסּוּר קָבוּעַ. וְכֵן הַבָּא עַל אִשָּׁה שֶׁהִיא סְפֵק נִדָּה אוֹ סְפֵק עֶרְוָה שֶׁל קֵרוּב בָּשָׂר פָּטוּר מֵאָשָׁם תָּלוּי. לְפִיכָךְ הָאִשָּׁה שֶׁנִּמְצָא דָּם עַל עֵד שֶׁלָּהּ לְאַחַר זְמַן וְהַנּוֹשֵׂא יְבִמְתּוֹ בְּתוֹךְ שְׁלֹשָׁה חֳדָשִׁים וְיָלְדָה וְאֵין יָדוּעַ אִם בֶּן תִּשְׁעָה לָרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לָאַחֲרוֹן הֲרֵי אֵלּוּ פְּטוּרִין מִן הַקָּרְבָּן. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ. שֶׁהֲרֵי אֵין שָׁם אִסּוּר קָבוּעַ:","הָאוֹכֵל חֲתִיכָה וְעֵד אֶחָד אוֹמֵר לוֹ זֶה שֶׁאָכַלְתָּ חֵלֶב הָיָה וְעֵד אֶחָד אוֹמֵר לֹא אָכַלְתָּ חֵלֶב. אִשָּׁה אוֹמֶרֶת אָכַל וְאִשָּׁה אוֹמֶרֶת לֹא אָכַל. הוֹאִיל וְנִקְבַּע הָאִסּוּר וְהוּא אֵינוֹ יוֹדֵעַ אִם חָטָא אוֹ לֹא חָטָא הֲרֵי זֶה מֵבִיא אָשָׁם תָּלוּי. וְכֵן כָּל הַבָּא עַל אֵשֶׁת אִישׁ שֶׁעֵד אֶחָד אוֹמֵר מֵת בַּעְלָהּ וְעֵד אֶחָד אוֹמֵר לֹא מֵת. חַיָּב בְּאָשָׁם תָּלוּי. וְהוּא הַדִּין לִסְפֵק מְגֹרֶשֶׁת שֶׁהֲרֵי נִקְבַּע הָאִסּוּר. אֲבָל סְפֵק מְקֻדֶּשֶׁת לֹא נִקְבַּע הָאִסּוּר:","מִי שֶׁהָיוּ לְפָנָיו שְׁתֵּי חֲתִיכוֹת אַחַת שֶׁל חֵלֶב וְאַחַת שֶׁל שֻׁמָּן. וְאָכַל אַחַת מֵהֶן וּבָא עַכּוּ\"ם אוֹ כֶּלֶב וְאָכַל אֶת הַשְּׁנִיָּה. אוֹ שֶׁאָכַל עַכּוּ\"ם אוֹ כֶּלֶב אֶת הָרִאשׁוֹנָה וּבָא יִשְׂרָאֵל וְאָכַל הַשְּׁנִיָּה. אוֹ שֶׁאָכַל רִאשׁוֹנָה בְּזָדוֹן וּשְׁנִיָּה בִּשְׁגָגָה. אוֹ שֶׁאָכַל רִאשׁוֹנָה בִּשְׁגָגָה וּשְׁנִיָּה בְּזָדוֹן. הֲרֵי זֶה חַיָּב בְּאָשָׁם תָּלוּי הוֹאִיל וְהָיָה שָׁמָּה אִסּוּר קָבוּעַ. אָכַל שְׁתֵּיהֶן בְּזָדוֹן פָּטוּר מִקָּרְבָּן. אָכַל שְׁתֵּיהֶן בִּשְׁגָגָה מֵבִיא חַטָּאת. אָכַל אֶת הָרִאשׁוֹנָה בִּשְׁגָגָה וּבָא אַחֵר וְאָכַל אֶת הַשְּׁנִיָּה בִּשְׁגָגָה שְׁנֵיהֶן חַיָּבִין בְּאָשָׁם תָּלוּי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","חֵלֶב וְנוֹתָר לְפָנָיו. אָכַל אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ מֵהֶן אָכַל. אִשְׁתּוֹ נִדָּה וַאֲחוֹתוֹ עִמּוֹ בַּבַּיִת וְשָׁגַג בְּאַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ מֵהֶן בָּעַל. שַׁבָּת וְיוֹם הַכִּפּוּרִים וְעָשָׂה מְלָאכָה בֵּין הַשְּׁמָשׁוֹת שֶׁבֵּינֵיהֶן. הֲרֵי זֶה פָּטוּר מִקָּרְבָּן וְאֵינוֹ מֵבִיא חַטָּאת שֶׁהֲרֵי אֵינוֹ יוֹדֵעַ עַצְמוֹ שֶׁל חֵטְא כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֵינוֹ מֵבִיא אָשָׁם תָּלוּי שֶׁהֲרֵי יוֹדֵעַ בְּוַדַּאי שֶׁחָטָא:","כָּל דָּבָר שֶׁחַיָּבִין עַל וַדָּאוֹ חַטָּאת קְבוּעָה אַחַת חַיָּבִין עַל לֹא הוֹדַע שֶׁלּוֹ אָשָׁם תָּלוּי אֶחָד. וְכָל דָּבָר שֶׁחַיָּבִין עַל וַדָּאוֹ חַטָּאוֹת הַרְבֵּה חַיָּבִין עַל לֹא הוֹדַע שֶׁלּוֹ אֲשָׁמוֹת תְּלוּיִין הַרְבֵּה כְּמִנְיַן הַחַטָּאוֹת. כֵּיצַד. כְּשֵׁם שֶׁאִם אָכַל חֵלֶב וְדָם וְנוֹתָר וּפִגּוּל בְּהֶעְלֵם אַחַת חַיָּב אַרְבַּע חַטָּאוֹת. כָּךְ אִם נִסְתַּפֵּק לוֹ אִם אֲכָלָן אוֹ לֹא אָכַל אֶלָּא חֲתִיכוֹת שֶׁל הֶתֵּר שֶׁהָיוּ עִמָּהֶם מֵבִיא אַרְבָּעָה אֲשָׁמוֹת תְּלוּיִין. וְכֵן אִם נִסְתַּפֵּק לוֹ אִם הָאִשָּׁה שֶׁבָּא עָלֶיהָ אִשְׁתּוֹ. אוֹ פְּלוֹנִית הָעֶרְוָה שֶׁהָיְתָה עִמָּהּ שֶׁחַיָּב עָלֶיהָ שְׁמוֹנֶה חַטָּאוֹת. הֲרֵי זֶה מֵבִיא שְׁמוֹנָה אֲשָׁמוֹת תְּלוּיִין:","הָאוֹכֵל חֲתִיכָה מִשְּׁתֵי חֲתִיכוֹת וְנִסְתַּפֵּק לוֹ אִם שֶׁל חֵלֶב אָכַל אוֹ שֶׁל שֻׁמָּן אָכַל וְאַחַר שֶׁנּוֹלַד לוֹ הַסָּפֵק אָכַל חֲתִיכָה מִשְּׁתֵי חֲתִיכוֹת אֲחֵרוֹת וְנִסְתַּפֵּק לוֹ אִם שֶׁל חֵלֶב אָכַל אוֹ שֶׁל שֻׁמָּן. הֲרֵי זֶה מֵבִיא שְׁתֵּי אֲשָׁמוֹת תְּלוּיִין:","כְּשֵׁם שֶׁיְּדִיעַת וַדַּאי בֵּינְתַיִם מְחַלֶּקֶת לְחַטָּאוֹת כָּךְ יְדִיעַת סָפֵק בֵּינְתַיִם מְחַלֶּקֶת לַאֲשָׁמוֹת. לְפִיכָךְ אִם אָכַל חֲמִשָּׁה זֵיתֵי חֵלֶב בְּהֶעְלֵם אַחַת. וְנוֹדַע לוֹ יְדִיעַת סָפֵק עַל אַחַת מֵהֶם וְחָזַר וְנוֹדַע לוֹ יְדִיעַת סָפֵק אַחֶרֶת עַל הַשֵּׁנִי. וְכֵן עַל כָּל אַחַת וְאַחַת. חַיָּב אָשָׁם תָּלוּי עַל כָּל אַחַת וְאַחַת:","חֲתִיכָה שֶׁל שֻׁמָּן וַחֲתִיכָה שֶׁל חֵלֶב. אָכַל אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא וְהֵבִיא אָשָׁם תָּלוּי. וְחָזַר וְאָכַל אֶת הַשְּׁנִיָּה מֵבִיא חַטָּאת. וְכֵן אִם אָכַל אַחֵר אֶת הַשְּׁנִיָּה מֵבִיא הָאַחֵר אָשָׁם תָּלוּי כְּמוֹ שֶׁבֵּאַרְנוּ:","חֲתִיכָה שֶׁל חֵלֶב וַחֲתִיכָה שֶׁל חֵלֶב נוֹתָר. אָכַל אֶת אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא. מֵבִיא חַטָּאת עַל הַחֵלֶב וְאָשָׁם תָּלוּי מִשּׁוּם נוֹתָר. אָכַל אֶת הַשְּׁנִיָּה בְּהֶעְלֵם שֵׁנִי מֵבִיא שָׁלֹשׁ חַטָּאוֹת. וְאִם הָיָה בָּהּ שְׁוֵה פְּרוּטָה מֵבִיא אָשָׁם וַדַּאי מִשּׁוּם מְעִילָה. אָכַל אֶחָד אֶת אַחַת מִשְּׁתֵּיהֶן. וּבָא אַחֵר וְאָכַל אֶת הַשְּׁנִיָּה. זֶה מֵבִיא חַטָּאת וְאָשָׁם תָּלוּי וְזֶה מֵבִיא חַטָּאת וְאָשָׁם תָּלוּי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Other Sources of Defilement 11":["כָּל מָקוֹם שֶׁנֶּאֱמַר בָּאֳכָלִין פָּסוּל הוּא שֶׁיִּהְיֶה הָאֹכֶל עַצְמוֹ טָמֵא וְלֹא יְטַמֵּא אֹכֶל אַחֵר. אֶלָּא אִם נָגַע בְּאֹכֶל אַחֵר הֲרֵי הוּא טָהוֹר:","הָרִאשׁוֹן שֶׁבְּחֻלִּין טָמֵא וּמְטַמֵּא. הַשֵּׁנִי פָּסוּל וְלֹא מְטַמֵּא וְאֵין שֵׁנִי עוֹשֶׂה שְׁלִישִׁי בְּחֻלִּין. וּמִנַּיִן לְאֹכֶל שֵׁנִי שֶׁהוּא פָּסוּל בְּחֻלִּין שֶׁנֶּאֱמַר (ויקרא יא לג) \"וּכְלִי חֶרֶשׂ אֲשֶׁר יִפּל מֵהֶן אֶל תּוֹכוֹ כּל אֲשֶׁר בְּתוֹכוֹ יִטְמָא\". נִמְצָא הַשֶּׁרֶץ אָב וּכְלִי חֶרֶס שֶׁנָּפַל הַשֶּׁרֶץ לַאֲוִירוֹ רִאשׁוֹן וְהָאֹכֶל שֶׁבַּכְּלִי שֵׁנִי וַהֲרֵי הוּא אוֹמֵר יִטְמָא. וְכֵן שֶׁרֶץ שֶׁנָּפַל לַאֲוִיר הַתַּנּוּר הַפַּת שְׁנִיָּה שֶׁהַתַּנּוּר רִאשׁוֹן:","הָרִאשׁוֹן וְהַשֵּׁנִי שֶׁבַּתְּרוּמָה טְמֵאִים וּמְטַמְּאִים. הַשְּׁלִישִׁי פָּסוּל וְלֹא מְטַמֵּא וְאֵין שְׁלִישִׁי עוֹשֶׂה רְבִיעִי בִּתְרוּמָה. מִנַּיִן לְאוֹכֵל שְׁלִישִׁי שֶׁהוּא פָּסוּל בִּתְרוּמָה שֶׁנֶּאֱמַר (ויקרא כב ז) \"וּבָא הַשֶּׁמֶשׁ וְטָהֵר וְאַחַר יֹאכַל מִן הַקֳדָשִׁים\" נִמְצָא טְבוּל יוֹם אָסוּר בִּתְרוּמָה עַד שֶׁיַּעֲרִיב שִׁמְשׁוֹ וְאִם נָגַע בָּהּ פְּסָלָהּ וּטְבוּל יוֹם כְּשֵׁנִי לְטֻמְאָה הוּא. הָא לָמַדְתָּ שֶׁהַשֵּׁנִי עוֹשֶׂה שְׁלִישִׁי בִּתְרוּמָה:","הָרִאשׁוֹן וְהַשֵּׁנִי וְהַשְּׁלִישִׁי בַּקֹּדֶשׁ טְמֵאִין וּמְטַמְּאִין. הָרְבִיעִי פָּסוּל וְאֵינוֹ מְטַמֵּא וְאֵין רְבִיעִי עוֹשֶׂה חֲמִישִׁי לְעוֹלָם. וּמִנַּיִן לַשְּׁלִישִׁי בַּקֹּדֶשׁ שֶׁהוּא טָמֵא שֶׁנֶּאֱמַר (ויקרא ז יט) \"וְהַבָּשָׂר אֲשֶׁר יִגַּע בְּכָל טָמֵא לֹא יֵאָכֵל\" וּכְבָר קָרָא הַכָּתוּב לַשֵּׁנִי טָמֵא שֶׁנֶּאֱמַר (ויקרא יא לג) \"כּל אֲשֶׁר בְּתוֹכוֹ יִטְמָא\" הָא לָמַדְתָּ שֶׁבְּשַׂר הַקֹּדֶשׁ שֶׁנָּגַע בְּשֵׁנִי נִטְמָא וְיִשָּׂרֵף. וּמִנַּיִן לָרְבִיעִי בַּקֹּדֶשׁ שֶׁהוּא פָּסוּל מִקַּל וָחֹמֶר. וּמַה מְחֻסַּר כִּפּוּרִים שֶׁהוּא מֻתָּר בִּתְרוּמָה אָסוּר בְּקֹדֶשׁ עַד שֶׁיָּבִיא כַּפָּרָתוֹ. הַשְּׁלִישִׁי שֶׁהוּא פָּסוּל בִּתְרוּמָה אֵינוֹ דִּין שֶׁיַּעֲשֶׂה רְבִיעִי בְּקֹדֶשׁ. אֲבָל הַחֲמִישִׁי טָהוֹר:","בְּשַׂר תַּאֲוָה אַף עַל פִּי שֶׁהוּא טָהוֹר גָּזְרוּ עָלָיו שֶׁיִּהְיֶה כִּשְׁלִישִׁי לְטֻמְאָה מְטַמֵּא אֶת הַקֹּדֶשׁ וְאֵינוֹ פּוֹסֵל אֶת הַתְּרוּמָה. וְיֵרָאֶה לִי שֶׁלֹּא גָּזְרוּ עָלָיו אֶלָּא כְּדֵי שֶׁלֹּא יְעָרְבוּהוּ עִם בְּשַׂר הַקֹּדֶשׁ וְיָבוֹאוּ לִטְעוֹת וְלִשְׁגֹּג בּוֹ וִידַמּוּ שֶׁהַבָּשָׂר זֶה הוּא חֹל וְהוּא קֹדֶשׁ וְיֹאכְלֶנּוּ בְּטֻמְאָה:","חִבּוּרֵי אֳכָלִין עַל יְדֵי מַשְׁקִין הֲרֵי הֵן חִבּוּר לְטַמֵּא טֻמְאַת אֳכָלִין וְהַדָּבָר סָפֵק אִם חֲשׁוּבִים כְּגוּף אֶחָד לִמְנוֹת בָּהֶן רִאשׁוֹן וְשֵׁנִי וּשְׁלִישִׁי. אוֹ חוֹשְׁבִים זֶה הָאֹכֶל שֶׁנָּגְעָה בּוֹ הַטֻּמְאָה רִאשׁוֹן וְהָאֹכֶל הַמְחֻבָּר לוֹ שֵׁנִי:","הַשֵּׁנִי שֶׁבְּחֻלִּין פּוֹסֵל אָכֳלֵי תְּרוּמָה וְעוֹשֶׂה אוֹתָן שְׁלִישִׁי. וְאִם נָגַע בְּמַשְׁקֵה חֻלִּין טִמְּאָן וְאֵין צָרִיךְ לוֹמַר אִם נָגַע בְּמַשְׁקֵה תְּרוּמָה אוֹ בְּמַשְׁקֵה קֹדֶשׁ שֶׁהוּא מְטַמֵּא אֶת הַכּל:","הַשְּׁלִישִׁי שֶׁבַּתְּרוּמָה שֶׁנָּגַע בְּאָכֳלֵי קֹדֶשׁ פְּסָלָן וְנַעֲשׂוּ רְבִיעִי. וְאִם נָגַע בְּמַשְׁקֵה הַקֹּדֶשׁ טִמְּאָן וְנַעֲשׂוּ תְּחִלָּה. אֲבָל אִם נָגַע שְׁלִישִׁי שֶׁבִּתְרוּמָה בְּמַשְׁקֵה תְּרוּמָה הֲרֵי הוּא טָהוֹר. וְכֵן רְבִיעִי שֶׁבַּקֹּדֶשׁ אִם נָגַע בְּמַשְׁקֵה קֹדֶשׁ הֲרֵי זֶה טָהוֹר:","חֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת תְּרוּמָה הַשְּׁלִישִׁי שֶׁבָּהֶן פָּסוּל כִּתְרוּמָה. וְאִם נָגַע בַּקֹּדֶשׁ אֵינוֹ עוֹשֵׂהוּ רְבִיעִי וַאֲפִלּוּ מַשְׁקֵה קֹדֶשׁ אֵינוֹ פּוֹסֵל. וְחֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַקֹּדֶשׁ הַשְּׁלִישִׁי שֶׁבָּהֶן טָהוֹר כְּחֻלִּין:","הָאוֹכֵל רְבִיעִי שֶׁבַּקֹּדֶשׁ אָסוּר לוֹ לֶאֱכל אֶת הַקֹּדֶשׁ וּמֻתָּר לִגַּע בַּקֹּדֶשׁ וְאֵינוֹ פּוֹסְלוֹ. אֲפִלּוּ תַּבְשִׁיל שֶׁנִּתְעָרֵב בּוֹ הַקֹּדֶשׁ וְאֵין בּוֹ כְּזַיִת בִּכְדֵי אֲכִילַת פְּרָס הֲרֵי זֶה לֹא יֵאָכֵל בִּרְבִיעִי שֶׁל קֹדֶשׁ אֶלָּא בַּחֲמִישִׁי שֶׁהוּא טָהוֹר כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאוֹכֵל שְׁלִישִׁי שֶׁבַּתְּרוּמָה עַצְמָהּ אוֹ שֶׁל חֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת תְּרוּמָה הֲרֵי זֶה אָסוּר לֶאֱכל אֶת הַתְּרוּמָה עַד שֶׁיִּטְבּל. וּמֻתָּר לִגַּע בִּתְרוּמָה וַהֲרֵי הִיא טְהוֹרָה. בַּאֲכִילָה עָשׂוּ מַעֲלָה בִּנְגִיעָה לֹא עָשׂוּ מַעֲלָה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְרוּמָה עַצְמָהּ. אֲבָל תַּבְשִׁיל שֶׁנִּתְעָרְבָה בּוֹ תְּרוּמָה אִם אֵין שָׁם כְּזַיִת בִּכְדֵי אֲכִילַת פְּרָס הֲרֵי זֶה מֻתָּר לֶאֱכל מֵאוֹתוֹ תַּבְשִׁיל כְּדֶרֶךְ שֶׁמֻּתָּר לִגַּע בִּתְרוּמָה:","הָאוֹכֵל שְׁלִישִׁי שֶׁבִּתְרוּמָה אוֹ שֶׁל חֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַתְּרוּמָה אַף עַל פִּי שֶׁהוּא טָהוֹר לִנְגִיעַת תְּרוּמָה הֲרֵי הוּא כְּשֵׁנִי לְעִנְיַן קֹדֶשׁ שֶׁטָּהֳרַת תְּרוּמָה טֻמְאָה הִיא אֵצֶל הַקֹּדֶשׁ. אֲבָל הָאוֹכֵל שְׁלִישִׁי שֶׁבְּחֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַקֹּדֶשׁ הֲרֵי הוּא טָהוֹר שֶׁאֵין לְךָ דָּבָר שֶׁעוֹשֶׂה רְבִיעִי בַּקֹּדֶשׁ אֶלָּא קֹדֶשׁ מִקֹּדֶשׁ בִּלְבַד:","כָּל קֹדֶשׁ הָאָמוּר בְּעִנְיַן טֻמְאַת אֳכָלִין וּמַשְׁקִין הוּא קָדְשֵׁי מִקְדָּשׁ הַמְקֻדָּשִׁין כְּגוֹן בְּשַׂר קָדְשֵׁי קָדָשִׁים. וּבְשַׂר קָדָשִׁים קַלִּים. וְחַלּוֹת תּוֹדָה וּרְקִיקֵי נָזִיר שֶׁנִּשְׁחַט עֲלֵיהֶן הַזֶּבַח. וְהַמְּנָחוֹת שֶׁקָּדְשׁוּ בִּכְלִי. וּשְׁתֵּי הַלֶּחֶם וְלֶחֶם הַפָּנִים מִשֶּׁקָּרְמוּ בַּתַּנּוּר. אֲבָל חַלּוֹת תּוֹדָה וּרְקִיקֵי נָזִיר שֶׁלֹּא נִשְׁחַט עֲלֵיהֶן הַזֶּבַח. וְהַמְּנָחוֹת שֶׁלֹּא קָדְשׁוּ בִּכְלִי. אֵינָן לֹא כְּקֹדֶשׁ וְלֹא כְּחֻלִּין אֶלָּא כִּתְרוּמָה:","הַחַלָּה וְהַבִּכּוּרִים וְתַשְׁלוּמֵי תְּרוּמָה [וְחֻמְשָׁהּ] הֲרֵי הֵן כִּתְרוּמָה:","הַטֶּבֶל. וְהַמְדֻמָּע. וְגִדּוּלֵי תְּרוּמָה. וּמַעֲשֵׂר שֵׁנִי וְרִאשׁוֹן. וְעִסָּה הַטְּבוּלָה לְחַלָּה. הֲרֵי הֵן כְּחֻלִּין וְהָרִאשׁוֹן טָמֵא בָּהֶן וְהַשֵּׁנִי פָּסוּל וְאֵין בָּהֶן שְׁלִישִׁי:","כָּל דָּבָר שֶׁוַּדָּאוֹ מְטַמֵּא אֶת הַחֻלִּין מִן הַתּוֹרָה גָּזְרוּ עַל סְפֵקוֹ בְּחֻלִּין הַטְּבוּלִין לְחַלָּה שֶׁתֵּעָשֶׂה אוֹתָהּ הָעִסָּה בְּטָהֳרָה. וּמַפְרִישִׁים מִמֶּנָּה חַלָּה וְחַלָּתָהּ תְּלוּיָה לֹא נֶאֱכֶלֶת וְלֹא נִשְׂרֶפֶת:"],"Mishneh Torah, Other Sources of Defilement 4":["שְׁמוֹנָּה שְׁרָצִים הָאֲמוּרִין בַּתּוֹרָה. וְהֵן הַחלֶד וְהָעַכְבָּר וְהַצָּב וְהָאֲנָקָה וְהַלְּטָאָה וְהַכֹּחַ וְהַתִּנְשֶׁמֶת וְהַחֹמֶט. טֻמְאַת כֻּלָּן שָׁוָה וְהֵן הַנִּקְרָאִין שֶׁרֶץ לְעִנְיַן טֻמְאָה:","הַשֶּׁרֶץ אָב מֵאֲבוֹת הַטֻּמְאוֹת מְטַמֵּא אָדָם וְכֵלִים בְּמַגָּע וּכְלֵי חֶרֶס בָּאֲוִיר וְאֵינוֹ מְטַמֵּא בְּמַשָּׂא. וְהַנּוֹגֵעַ בּוֹ אֵינוֹ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ. וְשִׁעוּר טֻמְאָתוֹ בְּכַעֲדָשָׁה וְכָל הַשְּׁרָצִים מִצְטָרְפִין לְכַעֲדָשָׁה:","הָאֵיבָרִים אֵין לָהֶן שִׁעוּר. אֵיבָר מִן הַשֶּׁרֶץ כִּבְרִיָּתוֹ:","בָּשָׂר וְגִידִים וַעֲצָמוֹת שֶׁהוּא פָּחוֹת מִכַּעֲדָשָׁה בֵּין שֶׁפֵּרַשׁ מִן הַחַי בֵּין שֶׁפֵּרַשׁ מִן הַמֵּת מְטַמֵּא טֻמְאָתוֹ. וְהוּא שֶׁיִּהְיֶה בַּבָּשָׂר שֶׁעָלָיו אוֹ בַּמֹּחַ שֶׁבָּעֶצֶם כְּדֵי לְהַעֲלוֹת אֲרוּכָה:","בָּשָׂר מִן הַחַי הַפּוֹרֵשׁ מִן הַשֶּׁרֶץ טָהוֹר שֶׁאֵין מְטַמֵּא אֶלָּא אֵיבָר הַדּוֹמֶה לַשֶּׁרֶץ כֻּלּוֹ. מַה שֶּׁרֶץ בָּשָׂר וְגִידִים וַעֲצָמוֹת אַף אֵיבָר הַפּוֹרֵשׁ בָּשָׂר וְגִידִים וַעֲצָמוֹת:","הַכֻּלְיָא וְהַכָּבֵד וְהַלָּשׁוֹן וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁהֵן אֵיבָר וְאֵין עוֹשִׂין חֲלִיפִין הֲרֵי הֵן כְּבָשָׂר. וְאִם פֵּרְשׁוּ מִן הַחַי טְהוֹרִין:","דַּם הַשֶּׁרֶץ כִּבְשָׂרוֹ וּמִצְטָרֵף לְכַעֲדָשָׁה כָּל זְמַן שֶׁהוּא מְחֻבָּר בַּבָּשָׂר:","עַצְמוֹת הַשֶּׁרֶץ וְגִידָיו וְצִפָּרְנָיו טְהוֹרִין. וְעוֹר הַחלֶד וְהָעַכְבָּר וְהַצָּב וְהַתִּנְשֶׁמֶת טָהוֹר אַף עַל פִּי שֶׁהוּא לַח וַעֲדַיִן לֹא עִבְּדוֹ וְלֹא הָלַךְ בּוֹ. אֲבָל עוֹר הָאֲנָקָה וְהַכֹּחַ וְהַלְּטָאָה וְהַחֹמֶט כִּבְשָׂרָן וּמְטַמֵּא בְּכַעֲדָשָׁה. וְאִם עִבְּדָן אוֹ שֶׁהִלֵּךְ בָּהֶן כְּדֵי עֲבוֹדָה טְהוֹרִין. וְכַמָּה הִיא כְּדֵי עֲבוֹדָה כְּדֵי הִלּוּךְ אַרְבָּעָה מִילִין:","קוּלְיַית הַשֶּׁרֶץ הַנּוֹגֵעַ בָּהּ טָהוֹר אַף עַל פִּי שֶׁהִיא מְלֵאָה מֹחַ וְהוּא שֶׁיִּהְיֶה הַמֹּחַ מִתְקַשְׁקֵשׁ שֶׁאֵינוֹ מַעֲלֶה אֲרוּכָה. אֲבָל אִם הָיָה עוֹמֵד בִּמְקוֹמוֹ וְיֵשׁ בּוֹ כְּדֵי לְהַעֲלוֹת אֲרוּכָה בָּהּ מִבַּחוּץ הֲרֵי הַנּוֹגֵעַ בָּהּ טָמֵא כְּכָל הָאֵיבָרִים שֶׁיֵּשׁ בָּהֶן כְּדֵי לְהַעֲלוֹת אֲרוּכָה כְּמוֹ שֶׁבֵּאַרְנוּ. נִקְּבָה הַקּוּלִית בְּכָל שֶׁהוּא הַנּוֹגֵעַ בָּהּ מִכָּל מָקוֹם טָמֵא:","בֵּיצַת הַשֶּׁרֶץ הַמְרֻקֶּמֶת אַף עַל פִּי שֶׁהַשֶּׁרֶץ נִרְאֵית מִתּוֹכָהּ טְהוֹרָה. נִקְּבָה כָּל שֶׁהוּא הַנּוֹגֵעַ בָּהּ טָמֵא:","שֶׁרֶץ שֶׁחֶצְיוֹ בָּשָׂר וְחֶצְיוֹ אֲדָמָה הַנּוֹגֵעַ בַּבָּשָׂר טָמֵא וּבָאֲדָמָה טָהוֹר. וְאִם הִשְׁרִיץ עַל פְּנֵי כֻּלּוֹ אַף הַנּוֹגֵעַ בָּאֲדָמָה שֶׁעֲדַיִן לֹא נִגְמְרָה צוּרָתוֹ טָמֵא:","בְּשַׂר הַשֶּׁרֶץ שֶׁנִּפְסַד וְהִבְאִישׁ וְנִפְסַל מִלֶּאֱכל הַכֶּלֶב טָהוֹר. יָבַשׁ עַד שֶׁנַּעֲשָׂה כַּחֶרֶשׂ אִם יָכוֹל לְהַשְׁרוֹת בְּפוֹשְׁרִין מֵעֵת לְעֵת וְלַחֲזֹר לַח כְּשֶׁהָיָה מְטַמֵּא וְאִם לָאו טָהוֹר וַאֲפִלּוּ כָּאֳכָלִין טְמֵאִים אֵינוֹ מְטַמֵּא. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִקְצָת הַשֶּׁרֶץ. אֲבָל שֶׁרֶץ שֶׁיָּבַשׁ וְשִׁלְדּוֹ קַיָּם אוֹ שֶׁנִּשְׂרַף וְשִׁלְדּוֹ קַיָּם הוֹאִיל וְתַבְנִית כֻּלּוֹ עוֹמֶדֶת הֲרֵי זֶה מְטַמֵּא. וְקָרוֹב בְּעֵינַי שֶׁטֻּמְאָה זוֹ מִדִּבְרֵיהֶם:","כְּזַיִת מִן הַנְּבֵלָה אוֹ כַּעֲדָשָׁה מִן הַשֶּׁרֶץ שֶׁצָּמְקוּ וְחָסְרוּ טְהוֹרִין. פָּחוֹת מִכַּעֲדָשָׁה מִן הַשֶּׁרֶץ וּפָחוֹת מִכְּזַיִת מִן הַנְּבֵלָה שֶׁתָּפְחוּ וְעָמְדוּ עַל כַּשִּׁעוּר מְטַמְּאִין מִדִּבְרֵי סוֹפְרִים. הָיוּ בַּתְּחִלָּה כַּשִּׁעוּר וְצָמְקוּ וְחָזְרוּ וְתָפְחוּ עַד שֶׁהִגִּיעוּ לְשִׁעוּרָן הֲרֵי אֵלּוּ מְטַמְּאִין כְּשֶׁהָיוּ דִּין תּוֹרָה. וְכֵן אַתָּה אוֹמֵר בִּכְזַיִת מִן הַמֵּת:","הַשֶּׁרֶץ אֵינוֹ מְטַמֵּא עַד שֶׁיָּמוּת. הֻתְּזוּ רָאשֵׁיהֶן אַף עַל פִּי שֶׁעֲדַיִן הָרֹאשׁ מְעֹרֶה בְּעוֹר הַגּוּף אַף עַל פִּי שֶׁהֵן מְפַרְכְּסִין כִּזְנַב הַלְּטָאָה מְטַמְּאִין. שְׁאָר שְׁקָצִים וּרְמָשִׂים כֻּלָּן כְּגוֹן הַצְּפַרְדֵּעַ וְהַנָּחָשׁ וְהָעַקְרָב וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁהֵן אֲסוּרִין בַּאֲכִילָה הֲרֵי הֵן טְהוֹרִין מִכְּלוּם וַאֲפִלּוּ כָּאֳכָלִין טְמֵאִין אֵינָן. וְאֵין לְךָ בְּכָל הַשְּׁרָצִים מַה שֶּׁמְּטַמֵּא בְּמוֹתוֹ חוּץ מִשְּׁמוֹנַת הַמִּינִין הַמְפֹרָשִׁין בַּתּוֹרָה:"],"Mishneh Torah, Overview of Mishneh Torah Contents 2":["ספר אהבה","הלכותיו שש, וזה הוא סידורן: הלכות קרית שמע, הלכות תפילה וברכת כוהנים, הלכות תפילין ומזוזה וספר תורה, הלכות ציצית, הלכות ברכות, הלכות מילה.","הלכות קרית שמע. מצות עשה אחת, והיא לקרות קרית שמע פעמיים ביום.","הלכות תפילה וברכת כוהנים. יש בכללן שתי מצוות עשה: (א) לעבוד את ה' בתפילה בכל יום; (ב) לברך כוהנים את ישראל בכל יום.","הלכות תפילין ומזוזה וספר תורה. יש בכללן חמש מצוות עשה; וזה הוא פרטן: (א) להיות תפילין על הראש; (ב) לקושרם על היד; (ג) לקבוע מזוזה בפתחי השערים; (ד) לכתוב כל איש ספר תורה לעצמו; (ה) לכתוב המלך ספר שני לעצמו כדי שיהיה לו שני ספרי תורה.","הלכות ציצית. מצות עשה אחת, והיא לעשות ציצית על כנפי הכסות.","הלכות ברכות. מצות עשה אחת, והיא לברך את שמו אחר אכילה.","הלכות מילה. מצות עשה אחת, והיא למול את הזכרים ביום השמיני.","נמצאו כל המצוות הנכללות בספר זה, אחת עשרה מצוות עשה."],"Mishneh Torah, Ownerless Property and Gifts 2":["נִּכְסֵי גֵּר שֶׁאֵין לוֹ יוֹרְשִׁים. וְנִכְסֵי הַהֶפְקֵר וְשָׂדֶה שֶׁמְּכָרָהּ הָעַכּוּ\"ם לְיִשְׂרָאֵל וַעֲדַיִן לֹא הֶחֱזִיק בָּהּ. כֻּלָּם דִּינָם שָׁוֶה. כָּל הַמַּחֲזִיק בָּהֶם בְּדֶרֶךְ מִדַּרְכֵי הַחֲזָקָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מְכִירָה קָנָה חוּץ מֵאֲכִילַת הַפֵּרוֹת:","כֵּיצַד. הַלּוֹקֵחַ קַרְקַע מֵחֲבֵרוֹ וְהֶחֱזִיק בָּהּ בַּאֲכִילַת פֵּרוֹתֶיהָ קָנָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל בְּנִכְסֵי הֶפְקֵר אוֹ נִכְסֵי הַגֵּר אֲפִלּוּ אָכַל פֵּרוֹת הָאִילָן כַּמָּה שָׁנִים לֹא קָנָה גּוּף הָאִילָן וְלֹא גּוּף הַקַּרְקַע עַד שֶׁיַּעֲשֶׂה מַעֲשֶׂה בְּגוּף הָאָרֶץ אוֹ יַעֲבֹד עֲבוֹדָה בָּאִילָן. וּמַעֲשֶׂה בְּאִשָּׁה אַחַת שֶׁאָכְלָה פֵּרוֹת דֶּקֶל שְׁלֹשׁ עֶשְׂרֵה שָׁנָה וּבָא אֶחָד וְהֶחֱזִיק בָּאִילָן בַּעֲבוֹדָה שֶׁעָבַד בְּגוּף הָאִילָן וּבָא מַעֲשֶׂה לִפְנֵי חֲכָמִים וְאָמְרוּ זֶה הָאַחֲרוֹן קָנָה:","יֵשׁ דְּבָרִים רַבִּים שֶׁאִם הֶחֱזִיק בָּהֶן הַלּוֹקֵחַ לֹא קָנָה עֲדַיִן. וְאִם הֶחֱזִיק בְּאֶחָד מֵהֶן בְּנִכְסֵי הַגֵּר אוֹ בְּנִכְסֵי הֶפְקֵר קָנָה. כֵּיצַד. הַמּוֹצֵא פַּלְטְרִים גְּדוֹלִים בְּנוּיִין בְּנִכְסֵי הַגֵּר אוֹ בְּנִכְסֵי הֶפְקֵר וְסִיֵּד בָּהֶן סִיּוּד אֶחָד אוֹ כִּיֵּר בָּהֶן כִּיּוּר אֶחָד כְּגוֹן אַמָּה אוֹ יוֹתֵר כְּנֶגֶד הַפֶּתַח קָנָה:","הַצָּר צוּרָה בְּנִכְסֵי הַגֵּר קָנָה. וְהַמַּצִּיעַ מַצָּעוֹת בְּנִכְסֵי הַגֵּר קָנָה. הַנָּר אֶת הַשָּׂדֶה בְּנִכְסֵי הַגֵּר קָנָה. הַמְפַצֵּל זְמוֹרוֹת הַגֶּפֶן אוֹ שָׂרִיגֵי אִילָנוֹת וְכַפּוֹת תְּמָרִים בְּנִכְסֵי הַגֵּר. אִם דַּעְתּוֹ לַעֲבֹד הָאִילָן קָנָה. וְאִם דַּעְתּוֹ לְהַאֲכִיל הָעֵצִים לִבְהֵמָה לֹא קָנָה:","כֵּיצַד. הָיָה כּוֹרֵת מִכָּאן וּמִכָּאן הֲרֵי חֶזְקָתוֹ שֶׁנִּתְכַּוֵּן לַעֲבוֹדַת הָאִילָן. הָיָה כּוֹרֵת מֵרוּחַ אַחַת אֵינוֹ מִתְכַּוֵּן אֶלָּא לָעֵצִים. וְכֵן הַמְלַקֵּט עֵצִים וַעֲשָׂבִים וַאֲבָנִים מִן הַשָּׂדֶה. אִם דַּעְתּוֹ לְתַקֵּן הָאָרֶץ קָנָה. וְאִם לָעֵצִים לֹא קָנָה:","כֵּיצַד. לִקֵּט הַגַּס וְהַדַּק הֲרֵי זוֹ בְּחֶזְקַת שֶׁנִּתְכַּוֵּן לְתַקֵּן אֶת הָאָרֶץ. לִקֵּט הַגַּס וְלֹא הַדַּק הֲרֵי זֶה בְּחֶזְקַת שֶׁנִּתְכַּוֵּן לָעֵצִים. וְכֵן הַמַּשְׁוֶה פְּנֵי הָאָרֶץ. אִם דַּעְתּוֹ לְתַקֵּן הָאָרֶץ קָנָה. וְאִם דַּעְתּוֹ לְהַשְׁווֹת מָקוֹם שֶׁיַּעֲמִיד בּוֹ גֹּרֶן לֹא קָנָה:","כֵּיצַד. הָיָה לוֹקֵחַ עָפָר מִמָּקוֹם גָּבוֹהַּ וְנוֹתְנוֹ לַמָּקוֹם הַנָּמוּךְ הֲרֵי זֶה מְתַקֵּן הָאָרֶץ. רְאִינוּהוּ שֶׁאֵינוֹ מַקְפִּיד עַל זֶה אֶלָּא מַשְׁלִיךְ הֶעָפָר וְהַצְּרוֹרוֹת בְּכָל מָקוֹם בְּלֹא הַקְפָּדָה הֲרֵי זֶה בְּחֶזְקַת שֶׁאֵינוֹ מִתְכַּוֵּן אֶלָּא לְהַשְׁווֹת מָקוֹם לְדַיִשׁ. וְכֵן הַפּוֹתֵחַ מַיִם לְתוֹךְ הָאָרֶץ. אִם לְתַקֵּן הָאָרֶץ קָנָה. וְאִם לָצוּד הַדָּגִים לֹא קָנָה:","כֵּיצַד. עָשָׂה מָקוֹם שֶׁיִּכָּנְסוּ בּוֹ הַמַּיִם בִּלְבַד הֲרֵי זֶה מִתְכַּוֵּן לְתַקֵּן הָאָרֶץ. עָשָׂה שְׁנֵי פְּתָחִים אֶחָד לְהַכְנִיס וְאֶחָד לְהוֹצִיא הֲרֵי זֶה מִתְכַּוֵּן לָצוּד דָּגִים:","הַבּוֹנֶה פַּלְטֵרִין גְּדוֹלִים בְּנִכְסֵי הַגֵּר וּבָא אַחֵר וְהֶעֱמִיד לָהֶם דְּלָתוֹת קָנָה הָאַחֲרוֹן. שֶׁהָרִאשׁוֹן לֹא עָשָׂה בְּגוּף הָאָרֶץ כְּלוּם. וַהֲרֵי הוּא כְּמִי שֶׁעָשָׂה גַּל אֲבָנִים עַל הָאָרֶץ שֶׁאֵינוֹ קוֹנֶה. שֶׁהֲרֵי לֹא הוֹעִיל בְּגָדֵר זֶה מִפְּנֵי שֶׁהוּא רָחָב בְּיוֹתֵר וּמְפֻלָּשׁ. וְאֵין צוּרַת אוֹתוֹ הַבִּנְיָן מוֹעֶלֶת לוֹ עַד שֶׁיַּעֲמִיד דְּלָתוֹת:","הַמֵּפִיץ הַזֶּרַע לְתוֹךְ הַתְּלָמִים לֹא קָנָה. שֶׁבְּעֵת שֶׁהִשְׁלִיךְ הַזֶּרַע לֹא הִשְׁבִּיחַ כְּלוּם וּבְעֵת שֶׁצָּמַח וְהִשְׁבִּיחַ שֶׁבַח הַבָּא מֵאֵלָיו הוּא וְאֵינוֹ קוֹנֶה:","הָיְתָה מְחִצָּה בְּנִכְסֵי הַגֵּר וּבָא זֶה וְעָשָׂה מְחִצָּה אַחֶרֶת עַל גַּבָּהּ לֹא קָנָה. וַאֲפִלּוּ נִבְלְעָה מְחִצָּה הַתַּחְתּוֹנָה וַהֲרֵי הָעֶלְיוֹנָה קַיֶּמֶת. שֶׁבְּעֵת שֶׁבָּנָה לֹא הוֹעִיל וּבְעֵת שֶׁהוֹעִיל מֵאֵלָיו בָּא הַמַּעֲשֶׂה:","הַמַּחֲזִיק בְּנִכְסֵי הַגֵּר וּבְהֶפְקֵר וְהוּא אֵין דַּעְתּוֹ לִקְנוֹת. אַף עַל פִּי שֶׁבָּנָה וְגָדַר לֹא קָנָה:","הָעוֹדֵר בְּנִכְסֵי הַגֵּר וְכַסָּבוּר שֶׁהֵן שֶׁלּוֹ לֹא קָנָה. עָדַר בְּנִכְסֵי גֵּר זֶה וּכְסָבוּר שֶׁל גֵּר אַחֵר. הוֹאִיל וְנִתְכַּוֵּן בְּמַעֲשָׂיו אֵלּוּ לִזְכּוֹת מִן הַהֶפְקֵר הֲרֵי זֶה קָנָה:","הָיָה מַשְׁכּוֹן יִשְׂרָאֵל בְּיַד הַגֵּר וּכְשֶׁמֵּת הַגֵּר בָּא יִשְׂרָאֵל אַחֵר וְהֶחֱזִיק בְּמַשְׁכּוֹן זֶה. מוֹצִיאִין אוֹתוֹ מִיָּדוֹ. שֶׁכֵּיוָן שֶׁמֵּת הַגֵּר בָּטֵל שִׁעְבּוּדוֹ:","הָיָה מַשְׁכּוֹן הַגֵּר בְּיַד יִשְׂרָאֵל וּבָא יִשְׂרָאֵל אַחֵר וְהֶחֱזִיק בּוֹ. לוֹקֵחַ מִמֶּנּוּ הָרִאשׁוֹן כְּנֶגֶד מְעוֹתָיו וְהָאַחֲרוֹן קָנָה אֶת הַשְּׁאָר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה הַמַּשְׁכּוֹן בַּחֲצַר הָרִאשׁוֹן. אֲבָל אִם הָיָה בַּחֲצֵרוֹ חֲצֵרוֹ קוֹנָה לוֹ שֶׁלֹּא מִדַּעְתּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן מְצִיאָה. וְאֵין לְזֶה הָאַחֲרוֹן כְּלוּם:","גֵּר שֶׁמֵּת וּבִזְבְּזוּ יִשְׂרָאֵל אֶת נְכָסָיו וְהָיוּ בָּהֶן עֲבָדִים גְּדוֹלִים. קָנוּ עַצְמָן בְּנֵי חוֹרִין. אֲבָל הָעֲבָדִים הַקְּטַנִּים הֲרֵי הֵן כִּבְהֵמָה וְכָל הַמַּחֲזִיק בָּהֶן זָכָה בָּהֶם. וּכְבָר בֵּאַרְנוּ דַּרְכֵי הַחֲזָקָה שֶׁיִּקְנוּ בָּהֶם אֶת הָעֲבָדִים:","גֵּר שֶׁמֵּת וּבִזְבְּזוּ יִשְׂרָאֵל אֶת נְכָסָיו. וְשָׁמְעוּ שֶׁעֲדַיִן לֹא מֵת אוֹ שֶׁיֵּשׁ לוֹ בֵּן אוֹ שֶׁאִשְׁתּוֹ מְעֻבֶּרֶת. כֻּלָּן חַיָּבִין לְהַחְזִיר. הֶחְזִירוּ כֻּלָּן וְאַחַר כָּךְ שָׁמְעוּ שֶׁמֵּת שֶׁשְּׁמוּעָה רִאשׁוֹנָה אֱמֶת הָיְתָה וּבָרִאשׁוֹנָה מֵת. אוֹ מֵת בְּנוֹ מִקֹּדֶם אוֹ הִפִּילָה אִשְׁתּוֹ. כָּל הַמַּחֲזִיק בַּשְּׁנִיָּה קָנָה וּבָרִאשׁוֹנָה לֹא קָנָה:"],"Mishneh Torah, Paschal Offering 4":["כְּבָר נִתְבָּאֵר בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין שֶׁהַפֶּסַח אֵינוֹ נִשְׁחַט אֶלָּא לְשֵׁם פֶּסַח וּלְשֵׁם בְּעָלָיו וְאִם שְׁחָטוֹ בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם פָּסוּל. הַשּׁוֹחֵט אֶת הַפֶּסַח עַל בְּנֵי חֲבוּרָה וְאָמַר לָהֶם לְאַחַר זְמַן אוֹתוֹ הַפֶּסַח שֶׁשָּׁחַטְתִּי עֲלֵיכֶם שֶׁלֹּא לִשְׁמוֹ שְׁחַטְתִּיו. אִם הָיָה נֶאֱמָן לָהֶן סוֹמְכִין עַל דְּבָרָיו. וְאִם לָאו שׁוּרַת הַדִּין שֶׁאֵינוֹ נֶאֱמָן. וְהָרוֹצֶה לְהַחְמִיר עַל עַצְמוֹ הֲרֵי זֶה מְשֻׁבָּח וְיָבִיא פֶּסַח שֵׁנִי:","בְּשַׂר הַפֶּסַח שֶׁנִּטְמָא וְנוֹדַע לוֹ קֹדֶם זְרִיקָה אַף עַל פִּי שֶׁהָאֵימוּרִין טְהוֹרִין לֹא יִזְרֹק אֶת הַדָּם שֶׁאֵין הַפֶּסַח בָּא אֶלָּא לַאֲכִילָה וְאִם זָרַק לֹא הֻרְצָּה. וְאִם לֹא נוֹדַע לוֹ עַד שֶׁנִּזְרַק הַדָּם הֻרְצָּה שֶׁהַצִּיץ מְרַצֶּה עַל שִׁגְגַת הַבָּשָׂר שֶׁנִּטְמָא וְאֵינוֹ מְרַצֶּה עַל הַזָּדוֹן. נִטְמְאוּ מִקְצָת הָאֵיבָרִים שׂוֹרֵף אֶת הַטְּמֵאִים וְאוֹכֵל אֶת הַטְּהוֹרִים. נִטְמְאוּ הָאֵימוּרִים וְהַבָּשָׂר קַיָּם זוֹרֵק אֶת הַדָּם וְהַבָּשָׂר נֶאֱכָל לָעֶרֶב. נִטְמְאוּ הַבְּעָלִים אַחַר שֶׁנִּשְׁחַט לֹא יִזְרֹק אֶת הַדָּם וְאִם זָרַק לֹא הֻרְצָּה. לְפִיכָךְ חַיָּבִין בְּפֶסַח שֵׁנִי שֶׁאֵין הַצִּיץ מְרַצֶּה עַל טֻמְאַת הַגּוּף אֶלָּא אִם נִטְמְאָה בְּטֻמְאַת הַתְּהוֹם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בִּיאַת הַמִּקְדָּשׁ:","הַפֶּסַח שֶׁיָּצָא מִירוּשָׁלַיִם אוֹ שֶׁנִּטְמָא בְּאַרְבָּעָה עָשָׂר יִשָּׂרֵף מִיָּד. נִטְמְאוּ הַבְּעָלִים אוֹ מֵתוּ אוֹ מָשְׁכוּ אֶת יְדֵיהֶם אֲפִלּוּ נִטְמְאוּ אוֹ מֵתוּ קֹדֶם זְרִיקַת הַדָּם מַנִּיחִין אוֹתוֹ עַד שֶׁתְּעֻבַּר צוּרָתוֹ וְאַחַר כָּךְ יִשָּׂרֵף. זֶה הַכְּלָל כָּל שֶׁפְּסוּלוֹ בְּגוּפוֹ יִשָּׂרֵף מִיָּד. בַּדָּם אוֹ בַּבְּעָלִים תְּעֻבַּר צוּרָתוֹ וְאַחַר כָּךְ יִשָּׂרֵף. לְפִיכָךְ אִם שְׁחָטוֹ אַחַר שֶׁנּוֹדַע שֶׁמָּשְׁכוּ הַבְּעָלִים אֶת יְדֵיהֶם אוֹ מֵתוּ אוֹ נִטְמְאוּ וְנִדְּחוּ לְפֶסַח שֵׁנִי הֲרֵי זֶה יִשָּׂרֵף מִיָּד. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיִּשָּׂרֵף אִם נִטְמְאוּ הַבְּעָלִים כְּשֶׁנִּטְמְאוּ כָּל בְּנֵי הַחֲבוּרָה. אֲבָל אִם נִטְמְאוּ מִקְצָתָן זָכוּ טְהוֹרִים בְּחֶלְקָם שֶׁל טְמֵאִים. אַף עַל פִּי שֶׁנִּטְמְאוּ מִקְצָתָן אַחַר שֶׁהִתְחִילוּ לֶאֱכל זָכוּ הַטְּהוֹרִים שֶׁעֲדַיִן לֹא הִתְחִילוּ. אֲבָל אִם הִתְחִילוּ כֻּלָּן וְנִטְמְאוּ מִקְצָתָן לֹא זָכוּ טְהוֹרִים בְּחֶלְקָן שֶׁל טְמֵאִים אֶלָּא הַטְּהוֹרִים אוֹכְלִין חֶלְקָם וְחֵלֶק הַטְּמֵאִים יִשָּׂרֵף. וְהוּא הַדִּין אִם מֵתוּ מִקְצָתָן. נִטְמָא שָׁלֵם אוֹ רֻבּוֹ שׂוֹרְפִים אוֹתוֹ לִפְנֵי הַבִּירָה בִּפְנֵי הַכּל כְּדֵי לְבַיְּשָׁן עַד שֶׁיִּזָהֲרוּ בּוֹ. וְשׂוֹרְפִין אוֹתוֹ מֵעֲצֵי הַמַּעֲרָכָה כְּדֵי שֶׁלֹּא יַחְשְׁדוּ אוֹתָן וְיֹאמְרוּ מֵעֲצֵי הַמַּעֲרָכָה גָּנְבוּ. לְפִיכָךְ אִם יִשְׂרְפוּהוּ בְּקַשׁ וּבְקָנִים וְרָצוּ לִשְׂרֹף מִשֶּׁל עַצְמָן שׂוֹרְפִין. נִטְמָא מִעוּטוֹ וְכֵן הַנּוֹתָר שׂוֹרְפִין אוֹתוֹ בְּחַצְרוֹתֵיהֶן מֵעֲצֵי עַצְמָן אֲבָל לֹא מֵעֲצֵי הַמַּעֲרָכָה שֶׁלֹּא יִשָּׁאֲרוּ מֵהֶן אֶצְלָם וְיִמְעֲלוּ בָּהֶן:","הַמַּפְרִישׁ נְקֵבָה לְפִסְחוֹ אוֹ זָכָר בֶּן שְׁתֵּי שָׁנִים. יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִמָּכֵר וְיָבִיא בְּדָמָיו פֶּסַח. וְאִם לֹא נָפַל בָּהּ מוּם עַד שֶׁהִקְרִיב פִּסְחוֹ יָבִיא בְּדָמָיו שְׁלָמִים:","הִפְרִישׁ פִּסְחוֹ וּמֵת. לֹא יְבִיאֶנּוּ בְּנוֹ אַחֲרָיו לְשֵׁם הַפֶּסַח אֶלָּא לְשֵׁם שְׁלָמִים. וְאִם הָיָה מְמֻנֶּה עִם אָבִיו עָלָיו יְבִיאֶנּוּ לְשֵׁם פֶּסַח. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁמֵּת אָבִיו אַחַר חֲצוֹת אַרְבָּעָה עָשָׂר אֲבָל קֹדֶם חֲצוֹת הֲרֵי זֶה נִדְחֶה לְפֶסַח שֵׁנִי מִפְּנֵי שֶׁהוּא אוֹנֵן כְּמוֹ שֶׁיִּתְבָּאֵר וְיָבִיא פִּסְחוֹ זֶה בַּשֵּׁנִי:","מִי שֶׁאָבַד פִּסְחוֹ וּמְצָאוֹ אַחַר שֶׁהִפְרִישׁ פֶּסַח אַחֵר וַהֲרֵי שְׁנֵיהֶן עוֹמְדִין יַקְרִיב אֵי זֶה מֵהֶן שֶׁיִּרְצֶה לְשֵׁם פֶּסַח וְהַשֵּׁנִי יִקְרַב שְׁלָמִים. מְצָאוֹ אַחַר שֶׁשָּׁחַט פִּסְחוֹ הֲרֵי זֶה יִקְרַב שְׁלָמִים. וְכֵן אִם הֵמִיר בָּזֶה הַנִּמְצָא אַחַר שְׁחִיטָה הֲרֵי תְּמוּרָה זוֹ תִּקְרַב שְׁלָמִים. אֲבָל אִם מְצָאוֹ קֹדֶם שְׁחִיטַת זֶה שֶׁהִפְרִישׁ. הוֹאִיל וְזֶה הַנִּמְצָא רָאוּי לְהַקְרִיבוֹ פֶּסַח וְרָאוּי לְהַקְרִיבוֹ שְׁלָמִים כְּמוֹ שֶׁבֵּאַרְנוּ. אִם הֵמִיר בָּזֶה הַנִּמְצָא בֵּין קֹדֶם שְׁחִיטַת הַמֻּפְרָשׁ תַּחְתָּיו בֵּין אַחַר שְׁחִיטָה. אֵין תְּמוּרָתוֹ קְרֵבָה אֶלָּא תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְיָבִיא בְּדָמֶיהָ שְׁלָמִים:","פֶּסַח שֶׁעָבְרָה שְׁנָתוֹ וּשְׁלָמִים הַבָּאִים מֵחֲמַת הַפֶּסַח הֲרֵי הֵם כִּשְׁלָמִים לְכָל דָּבָר טְעוּנִין סְמִיכָה וּנְסָכִים וּתְנוּפַת חָזֶה וְשׁוֹק מַה שֶּׁאֵין כֵּן בְּפֶסַח:","פֶּסַח שֶׁנִּתְעָרֵב בִּשְׁלָמִים יִקְרְבוּ כֻּלָּן שְׁלָמִים. נִתְעָרֵב בִּזְבָחִים אֲחֵרִים יִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיָבִיא בִּדְמֵי הַיָּפֶה שֶׁבָּהֶן מִמִּין זֶה וּבִדְמֵי הַיָּפֶה שֶׁבָּהֶן שְׁלָמִים וְיַפְסִיד הַמּוֹתָר מִבֵּיתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בִּפְסוּלֵי הַמֻּקְדָּשִׁין. נִתְעָרֵב בִּבְכוֹרוֹת. יִרְעוּ הַכּל עַד שֶׁיִּפּל בָּהֶן מוּם וְיֵאָכֵלוּ כִּבְכוֹר בַּעַל מוּם. וְיָבִיא בְּהֵמָה שֶׁהִיא יָפָה כַּיָּפָה שֶׁבְּתַעֲרוֹבוֹת וְיֹאמַר כָּל מָקוֹם שֶׁהוּא הַפֶּסַח קְדֻשָּׁתוֹ תָּחוּל עַל זוֹ וְיַקְרִיבֶנָּה שְׁלָמִים אִם קָרֵב פִּסְחוֹ:","הַמַּפְרִישׁ פִּסְחוֹ עַד שֶׁלֹּא נִתְגַּיֵּר וְנִתְגַּיֵּר. עַד שֶׁלֹּא נִשְׁתַּחְרֵר וְנִשְׁתַּחְרֵר. עַד שֶׁלֹּא הֵבִיא שְׁתֵּי שְׂעָרוֹת וְהֵבִיא. הֲרֵי זֶה מַקְרִיבוֹ לְשֵׁם פֶּסַח. שֶׁאֵין בַּעֲלֵי חַיִּים נִדְחִין כְּמוֹ שֶׁבֵּאַרְנוּ בִּפְסוּלֵי הַמֻּקְדָּשִׁין:","הַמַּפְרִישׁ מָעוֹת לְפִסְחוֹ וְהוֹתִירוּ. יָבִיא הַמּוֹתָר שְׁלָמִים. הַמְמַנֶּה אֲחֵרִים עַל פִּסְחוֹ וְעַל חֲגִיגָתוֹ. הֲרֵי הַמָּעוֹת שֶׁיִּקַּח מֵהֶן בְּחֶלְקָם חֻלִּין. אַף עַל פִּי שֶׁזֶּה הִפְרִישׁ טָלֶה לְפִסְחוֹ וְזֶה הִפְרִישׁ מָעוֹת לְפִסְחוֹ וְלָקַח מִמֶּנּוּ הַמָּעוֹת וּמִנָּהוּ עַל פִּסְחוֹ הֲרֵי הַמָּעוֹת חֻלִּין שֶׁעַל מְנָת כֵּן הִקְדִּישׁוּ יִשְׂרָאֵל אֶת פִּסְחֵיהֶן וְאֶת חֲגִיגָתָן וְאֶת מְעוֹת פִּסְחֵיהֶן וַחֲגִיגָתָן:","עֵצִים שֶׁל צְלִיַּת הַפֶּסַח כְּפֶסַח. וְכֵן מַצָּה וּמָרוֹר הוֹאִיל וְהֵן מַכְשִׁירֵי הַפֶּסַח הֲרֵי הֵם כְּפֶסַח. וְאִם לָקַח מִמְּעוֹת הַפֶּסַח מִמִּי שֶׁמִּנָּה אוֹתָן עִמּוֹ כְּדֵי לְמַנּוֹתָן עִמּוֹ בַּמַּצָּה וּמָרוֹר אוֹ לִהְיוֹת לוֹ חֵלֶק בָּעֵצִים שֶׁצּוֹלֶה בָּהֶן הֲרֵי הַמָּעוֹת חֻלִּין:"],"Mishneh Torah, Plaintiff and Defendant 15":["מִי שֶׁעִרְעֵר עַל שָׂדֶה זוֹ וְהֵבִיא עֵדִים שֶׁהִיא יְדוּעָה לוֹ וְהֵבִיא זֶה שֶׁבְּתוֹכָהּ שְׁטָר שֶׁלְּקָחָהּ מִמֶּנּוּ וְהֵבִיא עֵדִים שֶׁאֲכָלָהּ שְׁנֵי חֲזָקָה. אוֹמְרִים לוֹ בַּתְּחִלָּה קַיֵּם שְׁטָרְךָ. אִם נִתְקַיֵּם הֲרֵי טוֹב וְיָדוּן בַּשְּׁטָר. וְאִם אִי אֶפְשָׁר לוֹ לְקַיְּמוֹ סוֹמְכִין עַל עֵדֵי חֲזָקָה וְיִשָּׁבַע הֶסֵּת שֶׁלְּקָחָהּ:","עֵדֵי הַחֲזָקָה שֶׁהֵעִיד אֶחָד מִשְּׁנֵיהֶם שֶׁאֲכָלָהּ חִטִּים שְׁנֵי חֲזָקָה וְהַשֵּׁנִי הֵעִיד שֶׁאֲכָלָהּ שְׂעוֹרִים עֵדוּתָן קַיֶּמֶת שֶׁאֵין הָעֵד מְדַקְדֵּק בָּזֶה. הֵעִיד הָאֶחָד שֶׁאֲכָלָהּ זֶה שָׁנָה רִאשׁוֹנָה שְׁלִישִׁית וַחֲמִישִׁית וְהַשֵּׁנִי מֵעִיד שֶׁאֲכָלָהּ שְׁנִיָּה וּרְבִיעִית וְשִׁשִּׁית אֵין עֵדוּתָן מִצְטָרֶפֶת. שֶׁבַּשָּׁנָה שֶׁמֵּעִיד בָּהּ זֶה לֹא הֵעִיד בָּהּ זֶה. וְתַחְזֹר הַקַּרְקַע וְהַפֵּרוֹת:","מִי שֶׁיָּרַד לְשָׂדֶה בְּחֶזְקַת שֶׁהוּא יוֹרֵשׁ וְאָכַל פֵּרוֹתֶיהָ וְנִמְצָא יוֹרֵשׁ אַחַר שֶׁהוּא קָרוֹב מִמֶּנּוּ וְרָאוּי לְיָרְשָׁהּ בֵּין שֶׁנִּמְצָא בְּעֵדִים בֵּין שֶׁהוֹדָה לוֹ זֶה שֶׁיָּרַד תְּחִלָּה חַיָּב לְהַחְזִיר כָּל הַפֵּרוֹת שֶׁאָכַל:","שְׁנַיִם שֶׁהָיוּ עוֹרְרִין עַל הַשָּׂדֶה זֶה אוֹמֵר שֶׁלִּי וְזֶה אוֹמֵר שֶׁלִּי וְאֵין לְאֶחָד מֵהֶן רְאָיָה. אוֹ שֶׁהֵבִיא כָּל אֶחָד מֵהֶם עֵדִים שֶׁהִיא שֶׁלּוֹ אוֹ שֶׁל אֲבוֹתָיו אוֹ שֶׁהֵבִיא כָּל אֶחָד מִשְּׁנֵיהֶם עֵדִים שֶׁאֲכָלָהּ שְׁנֵי חֲזָקָה וְהַשָּׁנִים שֶׁהֵעִידוּ בָּהֶן אֵלּוּ הֵן הַשָּׁנִים עַצְמָן שֶׁהֵעִידוּ בָּהֶן אֵלּוּ. מַנִּיחִין אוֹתָהּ בִּידֵיהֶן וְכָל הַמִּתְגַּבֵּר יֵרֵד בָּהּ וְיִהְיֶה הָאַחֵר מוֹצִיא מִיָּדוֹ וְעָלָיו הָרְאָיָה. וְאִם בָּא שְׁלִישִׁי וְתָקַף עֲלֵיהֶן וְיָרַד לְתוֹכָהּ מְסַלְּקִין אוֹתוֹ מִמֶּנָּה:","הֵבִיא הָאֶחָד עֵדִים שֶׁהִיא שֶׁל אֲבוֹתָיו וְשֶׁאֲכָלָהּ שְׁנֵי חֲזָקָה וַהֲרֵי הִיא תַּחַת יָדוֹ. וְהֵבִיא הָאַחֵר עֵדִים שֶׁאֲכָלָהּ שְׁנֵי חֲזָקָה וַהֲרֵי הִיא תַּחַת יָדוֹ. נִמְצֵאת עֵדוּת הַחֲזָקָה שֶׁל שְׁנֵיהֶם מֻכְחֶשֶׁת. מַעֲמִידִין אוֹתָהּ בְּיַד זֶה שֶׁהֵעִידוּ עָלָיו עֵדֵי הַחֲזָקָה שֶׁהִיא שֶׁל אֲבוֹתָיו וּמוֹרִידִין אוֹתוֹ לְתוֹכָהּ. חָזַר הַשֵּׁנִי וְהֵבִיא אַף הוּא עֵדִים שֶׁהִיא שֶׁל אֲבוֹתָיו שֶׁהֲרֵי נִמְצֵאת גַּם עֵדוּת זוֹ מֻכְחֶשֶׁת. חוֹזְרִין בֵּית דִּין וּמְסַלְּקִין מִמֶּנָּה אַף הָרִאשׁוֹן וּמַנִּיחִין אוֹתָהּ בְּיַד שְׁנֵיהֶם וְכָל הַמִּתְגַּבֵּר יֵרֵד בָּהּ:","זֶה אוֹמֵר שֶׁל אֲבוֹתַי וְזֶה אוֹמֵר שֶׁל אֲבוֹתַי זֶה הֵבִיא עֵדִים שֶׁהִיא שֶׁל אֲבוֹתָיו וְזֶה הֵבִיא עֵדִים שֶׁאֲכָלָהּ שְׁנֵי חֲזָקָה תַּחְזֹר לָזֶה שֶׁהֵבִיא עֵדִים שֶׁהִיא שֶׁל אֲבוֹתָיו וְיַחְזִיר הַפֵּרוֹת שֶׁאָכַל. שֶׁהֲרֵי לֹא טָעַן כְּלוּם וְאֵין אֲכִילָתוֹ רְאָיָה שֶׁכָּל חֲזָקָה שֶׁאֵין עִמָּהּ טַעֲנָה עַל הַבְּעָלִים אֵינָהּ כְּלוּם. חָזַר זֶה הַמַּחֲזִיק וְאָמַר כֵּן שֶׁל אֲבוֹתֶיךָ הָיְתָה וְאַתָּה מְכַרְתָּהּ לִי וְזֶה שֶׁטָּעַנְתִּי תְּחִלָּה שֶׁהִיא שֶׁל אֲבוֹתַי כְּלוֹמַר שֶׁאֲנִי סוֹמֵךְ עָלֶיהָ וַהֲרֵי הִיא שֶׁלִּי כְּשֶׁל אֲבוֹתַי. אוֹ שֶׁאָמַר שֶׁל אֲבוֹתַי שֶׁלְּקָחוּהָ מֵאֲבוֹתֶיךָ הֲרֵי זוֹ טַעֲנָה נְכוֹנָה שֶׁהֲרֵי נָתַן אֲמַתְלָא לִדְבָרָיו הָרִאשׁוֹנִים וּמַעֲמִידִין אוֹתָהּ בְּיָדוֹ. וְאִם טָעַן בַּתְּחִלָּה וְאָמַר שֶׁל אֲבוֹתַי וְלֹא שֶׁל אֲבוֹתֶיךָ אֵין שׁוֹמְעִין לוֹ בְּטַעֲנָה זוֹ הָאַחֶרֶת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רְאוּבֵן שֶׁהָיָה בְּתוֹךְ שָׂדֶה וּבָא שִׁמְעוֹן וְעִרְעֵר עָלָיו וְאָמַר רְאוּבֵן שָׂדֶה זוֹ מִלֵּוִי קְנִיתִיהָ וְאָכַלְתִּי אוֹתָהּ שְׁנֵי חֲזָקָה אָמַר לוֹ שִׁמְעוֹן וַהֲלֹא שְׁטָר זֶה מְקֻיָּם בְּיָדִי שֶׁאֲנִי לְקַחְתִּיהָ מִלֵּוִי מֵהַיּוֹם אַרְבַּע שָׁנִים. חָזַר רְאוּבֵן וְאָמַר וְכִי תַּעֲלֶה עַל דַּעְתְּךָ שֶׁשָּׁלֹשׁ שָׁנִים בִּלְבַד יֵשׁ לִי מִשֶּׁקְּנִיתִיהָ שָׁנִים רַבּוֹת יֵשׁ לִי מִשֶּׁלְּקַחְתִּיהָ וַאֲנִי קְדַמְתִּיךָ. הֲרֵי טַעֲנַת רְאוּבֵן טַעֲנָה. שֶׁאָדָם קוֹרֵא לְשָׁנִים רַבּוֹת שְׁנֵי חֲזָקָה. לְפִיכָךְ אִם הֵבִיא רְאוּבֵן עֵדִים שֶׁאֲכָלָהּ שֶׁבַע שָׁנִים שֶׁנִּמְצָא שֶׁאָכַל שְׁנֵי חֲזָקָה קֹדֶם שֶׁלְּקָחָהּ שִׁמְעוֹן מַעֲמִידִין אוֹתָהּ בְּיָדוֹ. אֲבָל אִם אֲכָלָהּ פָּחוֹת מִשֶּׁבַע שָׁנִים תַּחְזֹר לְשִׁמְעוֹן שֶׁאֵין לְךָ מְחָאָה גְּדוֹלָה מִזּוֹ שֶׁהֲרֵי מְכָרָהּ קֹדֶם שֶׁהֶחְזִיק רְאוּבֵן:","זֶה אוֹמֵר שֶׁל אֲבוֹתַי וְהֵבִיא עֵדִים וְזֶה אוֹמֵר שֶׁל אֲבוֹתַי וְאֵין לוֹ עֵדִים תַּחְזֹר לָזֶה שֶׁהֵבִיא עֵדִים וּמוֹצִיאִין מִזֶּה כָּל פֵּרוֹת שֶׁהוֹדָה בָּהֶן שֶׁאֲכָלָן אַף עַל פִּי שֶׁאֵין עָלָיו עֵדִים שֶׁאָכַל. שֶׁהֲרֵי הוּא אוֹמֵר שֶׁמֵּחֲמַת אֲבוֹתָיו אָכַל וַהֲרֵי הָעֵדִים שֶׁהָיָה שֶׁל אֲבוֹתָיו שֶׁל זֶה הַטּוֹעֵן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הֵבִיא הַמְעַרְעֵר עֵדִים שֶׁזּוֹ הַשָּׂדֶה שֶׁלּוֹ וְזֶה שֶׁבְּתוֹכָהּ טוֹעֵן מִמְּךָ לְקַחְתִּיהָ וַהֲרֵי שְׁטָרִי וְהוֹצִיא שְׁטָר מְקֻיָּם. טָעַן הַמְעַרְעֵר שֶׁהוּא מְזֻיָּף וְהוֹדָה בַּעַל הַשְּׁטָר וְאָמַר כֵּן הוּא אֲבָל הָיָה לִי שְׁטָר כָּשֵׁר וְאָבַד וְלָקַחְתִּי זֶה שֶׁבְּיָדִי כְּדֵי לְאַיֵּם עָלָיו שֶׁיּוֹדֶה שֶׁמָּכַר לִי בֶּאֱמֶת. הוֹאִיל וְאִלּוּ רָצָה הָיָה אוֹמֵר בִּשְׁטָרוֹ שֶׁהֲרֵי מְקֻיָּם הוּא הֲרֵי זֶה נֶאֱמָן וְאֵין מוֹצִיאִין אֶת הַשָּׂדֶה מִתַּחַת יָדוֹ וְיִשָּׁבַע הֶסֵּת:","הֵבִיא הַמְעַרְעֵר עֵדִים שֶׁזּוֹ הַשָּׂדֶה שֶׁלּוֹ וְזֶה שֶׁבְּתוֹכָהּ טוֹעֵן מִמְּךָ לְקַחְתִּיהָ וַאֲכַלְתִּיהָ שְׁנֵי חֲזָקָה וְהֵבִיא עֵדִים שֶׁאֲכָלָהּ שְׁנֵי חֲזָקָה טָעַן הַמְעַרְעֵר וְאָמַר הֵיאַךְ תִּטְעֹן שֶׁלָּקַחְתָּ מִמֶּנִּי הַיּוֹם שָׁלֹשׁ שָׁנִים וּבְאוֹתוֹ הַזְּמַן לֹא הָיִיתִי בִּמְדִינָה זוֹ. מַצְרִיכִין זֶה שֶׁבְּתוֹכָהּ לְהָבִיא רְאָיָה שֶׁזֶּה פְּלוֹנִי שֶׁמְּעַרְעֵר הָיָה עִמּוֹ בַּמְּדִינָה בַּזְּמַן הַזֶּה שֶׁטּוֹעֵן שֶׁמָּכַר לוֹ בּוֹ אֲפִלּוּ יוֹם אֶחָד כְּדֵי שֶׁיִּהְיֶה אֶפְשָׁר שֶׁיִּמְכֹּר וְאִם לֹא הֵבִיא מְסַלְּקִין אוֹתוֹ:","מִי שֶׁהָלַךְ לִמְדִינַת הַיָּם וְאָבְדָה דֶּרֶךְ שָׂדֵהוּ בֵּין שֶׁהָיוּ אַרְבַּע הַשָּׂדוֹת הַמַּקִּיפוֹת אוֹתָהּ לְאַרְבָּעָה אֲנָשִׁים בֵּין שֶׁהָיוּ הָאַרְבַּע שָׂדוֹת קְנוּיוֹת מֵאֶחָד הֲרֵי כָּל אֶחָד מֵהֶן דּוֹחֵהוּ וְאוֹמֵר שֶׁמָּא דֶּרֶךְ שֶׁלְּךָ עַל חֲבֵרִי הוּא. לְפִיכָךְ יִקְנֶה לוֹ דֶּרֶךְ בְּמֵאָה מָנֶה אוֹ יִפְרַח בָּאֲוִיר. וְכֵן אִם הָיוּ אַרְבַּע הַשָּׂדוֹת לְאִישׁ אֶחָד שֶׁקָּנָה אוֹתָן מֵאַרְבָּעָה אֵין לוֹ עָלָיו דֶּרֶךְ שֶׁהֲרֵי אוֹמֵר לוֹ עַתָּה אִם אַחְזִיר לְכָל אֶחָד שְׁטָרוֹ אֵין אַתָּה יָכוֹל לַעֲבֹר עַל אֶחָד מֵהֶן וַאֲנִי קָנִיתִי מִכָּל אֶחָד מֵהֶן כָּל זְכוּת שֶׁיֵּשׁ לוֹ. אֲבָל אִם הָיָה בַּעַל אַרְבַּע שָׂדוֹת הַמַּקִּיפוֹ אִישׁ אֶחָד וְהוּא בַּעַל הַמֵּצַר שֶׁלָּהּ מִתְּחִלָּה וְעַד סוֹף הֲרֵי זֶה אוֹמֵר לוֹ מִכָּל מָקוֹם דַּרְכִּי עָלֶיךָ וְיֵלֵךְ לוֹ בִּקְצָרָה בְּאֵי זוֹ שָׂדֶה שֶׁיִּרְצֶה בַּעַל הַשָּׂדֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם הֶחֱזִיק בַּדֶּרֶךְ וְאוֹמֵר זוֹ הִיא דַּרְכִּי אֵין מְסַלְּקִין אוֹתוֹ מִמֶּנָּה אֶלָּא בִּרְאָיָה בְּרוּרָה:"],"Mishneh Torah, Positive Mitzvot 100":["להיות היולדת טמאה כנידה."],"Mishneh Torah, Positive Mitzvot 111":["להיות המצורע מגלח כל שערו, שנאמר: \"וְהָיָה בַּיּוֹם הַשְּׁבִיעִי יְגַלַּח אֶת כָּל שְׂעָרוֹ\" (ויקרא יד, ט)."],"Mishneh Torah, Positive Mitzvot 122":["להניח עומר השכחה."],"Mishneh Torah, Positive Mitzvot 133":["להפריש חלה לכוהן, שנאמר: \"ראשית, עריסותיכם--חלה, תרימו תרומה\" (במדבר טו,כ)."],"Mishneh Torah, Positive Mitzvot 144":["ליתן ראשית הגז לכוהן, שנאמר: \"וראשית גז צאנך--תיתן לו\" (דברים יח,ד)."],"Mishneh Torah, Positive Mitzvot 155":["לקדש שבת, שנאמר: \"זכור את יום השבת, לקדשו\" (שמות כ,ז)."],"Mishneh Torah, Positive Mitzvot 166":["לשבות בראשון של חג הסוכות, שנאמר: \"ביום הראשון, מקרא קודש\" (ויקרא כג,לה)."],"Mishneh Torah, Positive Mitzvot 177":["להשוות בין בעלי דינין בשעה שעומדין בדין, שנאמר: \"בצדק, תשפוט עמיתך\" (ויקרא יט,טו)."],"Mishneh Torah, Positive Mitzvot 188":["להכרית זרעו של עמלק, שנאמר: \"תמחה את זכר עמלק\" (דברים כה,יט)."],"Mishneh Torah, Positive Mitzvot 199":["להשיב המשכון לבעליו, שנאמר: \"השב תשיב לו את העבוט\" (דברים כד,יג)."],"Mishneh Torah, Positive Mitzvot 209":["לכבד החכמים, שנאמר: \"מפני שיבה תקום\" (ויקרא יט, לב)."],"Mishneh Torah, Positive Mitzvot 22":["לִשְׁמֹר בַּיִת זֶה תָּמִיד, שֶׁנֶּאֱמָר: \"וְאַתָּה וּבָנֶיךָ אִתָּךְ לִפְנֵי אֹהֶל הָעֵדֻת\" (במדבר יח, ב)."],"Mishneh Torah, Positive Mitzvot 230":["לתלות מי שנתחייב תלייה, שנאמר: \"ותלית אותו, על עץ\" (דברים כא,כב)."],"Mishneh Torah, Positive Mitzvot 241":["לדון בנזקי האש, שנאמר: \"כי תצא אש ומצאה קוצים\" (שמות כב,ה)."],"Mishneh Torah, Positive Mitzvot 29":["לַעֲרֹךְ אֵשׁ בְּמִזְבַּח הָעוֹלָה תָּמִיד, שֶׁנֶּאֱמָר: \"אֵשׁ תמיד תוקד על המזבח\" (ויקרא ו, ו)."],"Mishneh Torah, Positive Mitzvot 4":["לְיִרְאָה מִמֶּנּוּ, שֶׁנֶּאֱמָר: \"אֶת-ה' אֱלֹהֶיךָ תִּירָא\" (דברים ו יג, י כ)."],"Mishneh Torah, Positive Mitzvot 50":["להוסיף קרבן בחג הסוכות, שנאמר: \"וְהִקְרַבְתֶּם עוֹלָה אִשֵּׁה רֵיחַ נִיחוֹחַ\" (במדבר כט, יג)."],"Mishneh Torah, Positive Mitzvot 61":["להיות כל קרבן בהמה תמים, שנאמר: \"תָּמִים יִהְיֶה לְרָצוֹן\" (ויקרא כב, כא)."],"Mishneh Torah, Positive Mitzvot 72":["להקריב קרבן עולה ויורד, שנאמר: \"ואם לא תגיע ידו\" (ויקרא ה,ז), \"ואם לא תשיג ידו\" (ויקרא ה,יא)."],"Mishneh Torah, Positive Mitzvot 83":["להביא כל הקרבנות שיש על האדם בחובה או בנדבה ברגל ראשון שפגע בו, שנאמר: \"ובאת שמה\" (דברים יב,ה), \"והבאתם שמה\" (דברים יב,ו)."],"Mishneh Torah, Positive Mitzvot 94":["לקיים אדם כל מה שהוציא בשפתיו, מקרבן או צדקה וכיוצא בהם, שנאמר: \"מוצא שפתיך, תשמור ועשית\" (דברים כג,כד)."],"Mishneh Torah, Prayer and the Priestly Blessing 15":["שִׁשָּׁה דְּבָרִים מוֹנְעִין נְשִׂיאַת כַּפַּיִם. הַלָּשׁוֹן. וְהַמּוּמִין. וִהָעֲבֵרָה. וְהַשָּׁנִים. וְהַיַּיִן. וְטֻמְאַת הַיָּדַיִם. הַלָּשׁוֹן כֵּיצַד. הָעִלְּגִים שֶׁאֵין מוֹצִיאִין אֶת הָאוֹתִיּוֹת כְּתִקּוּנָן כְּגוֹן שֶׁקּוֹרִין לַאֲלֵפִי״ן עַיְנִי״ן וּלְעַיְנִי״ן אֲלֵפִי״ן אוֹ לְשִׁבּלֶת סִבּלֶת וְכַיּוֹצֵא בָּהֶן אֵין נוֹשְׂאִין אֶת כַּפֵּיהֶן. וְכֵן כְּבֵדֵי פֶּה וּכְבֵדֵי לָשׁוֹן שֶׁאֵין דִּבְרֵיהֶם נִכָּרִים לַכּל אֵין נוֹשְׂאִין אֶת כַּפֵּיהֶן:","הַמּוּמִין כֵּיצַד. כֹּהֵן שֶׁיֵּשׁ מוּמִין בְּפָנָיו אוֹ בְּיָדָיו אוֹ בְּרַגְלָיו כְּגוֹן שֶׁהָיוּ אֶצְבְּעוֹתָיו עֲקֻמּוֹת אוֹ עֲקֻּשּׁוֹת אוֹ שֶׁהָיוּ יָדָיו בּוֹהֲקָנִיּוֹת לֹא יִשָּׂא אֶת כַּפָּיו לְפִי שֶׁהָעָם מִסְתַּכְּלִין בּוֹ. מִי שֶׁהָיָה רִירוֹ יוֹרֵד עַל זְקָנוֹ בְּשָׁעָה שֶׁהוּא מְדַבֵּר וְכֵן הַסּוּמָא בְּאַחַת מֵעֵינָיו לֹא יִשָּׂא אֶת כַּפָּיו. וְאִם הָיָה דַּשׁ בְּעִירוֹ וְהַכּל הָיוּ רְגִילִים בְּזֶה הַסּוּמָא בְּאַחַת מֵעֵינָיו אוֹ בְּזֶה שֶׁרִירוֹ זָב מֻתָּר לְפִי שֶׁאֵין מִסְתַּכְּלִין בּוֹ. וְכֵן מִי שֶׁהָיוּ יָדָיו צְבוּעוֹת אִסְטִיס וּפוּאָה לֹא יִשָּׂא אֶת כַּפָּיו. וְאִם רֹב אַנְשֵׁי הָעִיר מְלַאכְתָּן בְּכָךְ מֻתָּר לְפִי שֶׁאֵין מִסְתַּכְּלִין בּוֹ:","הָעֲבֵרָה כֵּיצַד. כֹּהֵן שֶׁהָרַג אֶת הַנֶּפֶשׁ אַף עַל פִּי שֶׁעָשָׂה תְּשׁוּבָה לֹא יִשָּׂא אֶת כַּפָּיו שֶׁנֶּאֱמַר (ישעיה א טו) ״יְדֵיכֶם דָּמִים מָלֵאוּ״ וּכְתִיב (ישעיה א טו) ״וּבְפָרִשְׂכֶם כַּפֵּיכֶם״ וְגוֹ׳‎. וְכֹהֵן שֶׁעָבַד כּוֹכָבִים בֵּין בְּאֹנֶס בֵּין בִּשְׁגָגָה אַף עַל פִּי שֶׁעָשָׂה תְּשׁוּבָה אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו לְעוֹלָם שֶׁנֶּאֱמַר (מלכים ב כג ט) ״אַךְ לֹא יַעֲלוּ כֹּהֲנֵי הַבָּמוֹת״ וְגוֹ׳‎. וּבְרָכָה כַּעֲבוֹדָה הִיא שֶׁנֶּאֱמַר (דברים י ח) ״לְשָׁרְתוֹ וּלְבָרֵךְ בִּשְׁמוֹ״. וְכֵן כֹּהֵן שֶׁהֵמִיר לְעַכּוּ״ם אַף עַל פִּי שֶׁחָזַר בּוֹ אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו לְעוֹלָם. וּשְׁאָר הָעֲבֵרוֹת אֵין מוֹנְעִין:","הַשָּׁנִים כֵּיצַד. כֹּהֵן נַעַר לֹא יִשָּׂא אֶת כַּפָּיו עַד שֶׁיִּתְמַלֵּא זְקָנוֹ. וְהַיַּיִן כֵּיצַד. מִי שֶׁשָּׁתָה רְבִיעִית יַיִן בְּבַת אַחַת אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו עַד שֶׁיָּסִיר אֶת יֵינוֹ מֵעָלָיו לְפִי שֶׁהֻקְּשָׁה בְּרָכָה לַעֲבוֹדָה. שָׁתָה רְבִיעִית יַיִן בִּשְׁתֵּי פְּעָמִים אוֹ שֶׁנָּתַן לְתוֹכוֹ מְעַט מַיִם מֻתָּר. וְאִם שָׁתָה יוֹתֵר מֵרְבִיעִית אַף עַל פִּי שֶׁהָיָה מָזוּג אַף עַל פִּי שֶׁשְּׁתָאוֹ בְּכַמָּה פְּעָמִים לֹא יִשָּׂא אֶת כַּפָּיו עַד שֶׁיָּסִיר אֶת יֵינוֹ מֵעָלָיו. וְכַמָּה הִיא רְבִיעִית אֶצְבָּעִים עַל אֶצְבָּעִים בְּרוּם אֶצְבָּעִים וַחֲצִי אֶצְבַּע וְחֹמֶשׁ אֶצְבַּע בְּגוּדָל. וְזֶה הָאֶצְבַּע שֶׁמּוֹשְׁחִין בּוֹ בְּכָל הַתּוֹרָה כֻּלָּהּ הוּא הַגּוּדָל וְהוּא הַנִּקְרָא בֹּהֶן יָד:","טֻמְאַת הַיָּדַיִם כֵּיצַד. כֹּהֵן שֶׁלֹּא נָטַל אֶת יָדָיו לֹא יִשָּׂא אֶת כַּפָּיו אֶלָּא נוֹטֵל אֶת יָדָיו עַד הַפֶּרֶק כְּדֶרֶךְ שֶׁמְּקַדְּשִׁין לַעֲבוֹדָה וְאַחַר כָּךְ מְבָרֵךְ שֶׁנֶּאֱמַר (תהילים קלד ב) ״שְׂאוּ יְדֵכֶם קֹדֶשׁ וּבָרַכוּ אֶת יְיָ׳‎״. וְהֶחָלָל אֵינוֹ נוֹשֵׂא אֶת כַּפָּיו לְפִי שֶׁאֵינוֹ בְּכִהוּנוֹ:","כֹּהֵן שֶׁלֹּא הָיָה לוֹ דָּבָר מִכָּל אֵלּוּ הַדְּבָרִים הַמּוֹנְעִין נְשִׂיאַת כַּפַּיִם אַף עַל פִּי שֶׁאֵינוֹ חָכָם וְאֵינוֹ מְדַקְדֵּק בְּמִצְוֹת אוֹ שֶׁהָיוּ הַבְּרִיּוֹת מְרַנְּנִים אַחֲרָיו אוֹ שֶׁלֹּא הָיָה מַשָּׂאוֹ וּמַתָּנוֹ בְּצֶדֶק הֲרֵי זֶה נוֹשֵׂא אֶת כַּפָּיו וְאֵין מוֹנְעִין אוֹתוֹ לְפִי שֶׁזּוֹ מִצְוַת עֲשֵׂה עַל כָּל כֹּהֵן וְכֹהֵן שֶׁרָאוּי לִנְשִׂיאַת כַּפַּיִם וְאֵין אוֹמְרִים לְאָדָם רָשָׁע הוֹסֵף רֶשַׁע וְהִמָּנַע מִן הַמִּצְוֹת:","וְאַל תִּתְמַהּ וְתֹאמַר וּמַה תּוֹעִיל בִּרְכַּת הֶדְיוֹט זֶה. שֶׁאֵין קִבּוּל הַבְּרָכָה תָּלוּי בַּכֹּהֲנִים אֶלָּא בְּהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנֶּאֱמַר (במדבר ו כז) ״וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרַכֶם״. הַכֹּהֲנִים עוֹשִׂים מִצְוָתָן שֶׁנִּצְטַוּוּ בָּהּ וְהַקָּדוֹשׁ בָּרוּךְ הוּא בְרַחֲמָיו מְבָרֵךְ אֶת יִשְׂרָאֵל כְּחֶפְצוֹ:","עַם שֶׁהֵם אֲחוֹרֵי הַכֹּהֲנִים אֵינָם בִּכְלַל הַבְּרָכָה. וְהָעוֹמְדִים מִצִּדֵּיהֶן הֲרֵי הֵם בִּכְלַל הַבְּרָכָה. וְאִם הָיְתָה מְחִצָּה בֵּין הַכֹּהֲנִים וּבֵין הַמִּתְבָּרְכִים אֲפִלּוּ הִיא חוֹמָה שֶׁל בַּרְזֶל הוֹאִיל וּפְנֵיהֶם מוּל פְּנֵי הַכֹּהֲנִים הֲרֵי הֵם בִּכְלַל הַבְּרָכָה:","נְשִׂיאַת כַּפַּיִם בַּעֲשָׂרָה וְכֹהֲנִים מִן הַמִּנְיָן. בֵּית הַכְּנֶסֶת שֶׁכֻּלָּן כֹּהֲנִים כֻּלָּם נוֹשְׂאִים אֶת כַּפֵּיהֶם. וּלְמִי הֵם מְבָרְכִים לְאַחֵיהֶם שֶׁבַּצָּפוֹן וְלַאֲחֵיהֶם שֶׁבַּדָּרוֹם. וּמִי עוֹנֶה אַחֲרֵיהֶם אָמֵן הַנָּשִׁים וְהַטַּף. וְאִם נִשְׁאֲרוּ שָׁם עֲשָׂרָה כֹּהֲנִים יוֹתֵר עַל אֵלּוּ שֶׁעָלוּ לַדּוּכָן הָעֲשָׂרָה עוֹנִין אָמֵן וְהַשְּׁאָר מְבָרְכִין:","צִבּוּר שֶׁלֹּא הָיָה בָּהֶן כֹּהֵן אֶלָּא שְׁלִיחַ צִבּוּר לְבַדּוֹ לֹא יִשָּׂא אֶת כַּפָּיו. וְאִם הָיְתָה הַבְטָחָתוֹ שֶׁהוּא נוֹשֵׂא אֶת כַּפָּיו וְחוֹזֵר לִתְפִלָּתוֹ רַשַּׁאי. וְאִם אֵין לָהֶם כֹּהֵן כְּלָל כְּשֶׁיַּגִּיעַ שְׁלִיחַ צִבּוּר לְשִׂים שָׁלוֹם אוֹמֵר אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ בָּרְכֵנוּ בַּבְּרָכָה הַמְשֻׁלֶּשֶׁת בַּתּוֹרָה הַכְּתוּבָה עַל יְדֵי משֶׁה עַבְדְּךָ הָאֲמוּרָה מִפִּי אַהֲרֹן וּבָנָיו כֹּהֲנִים עַם קְדוֹשֶׁךָ כָּאָמוּר (במדבר ו כד) ״יְבָרֶכְךָ יְיָ׳‎ וְיִשְׁמְרֶךָ״ (במדבר ו כה) ״יָאֵר יְיָ׳‎ פָּנָיו אֵלֶיךָ וִיחֻנֶּךָּ״ (במדבר ו כו) ״יִשָּׂא יְיָ׳‎ פָּנָיו אֵלֶיךָ וְיָשֵׂם לְךָ שָׁלוֹם״ (במדבר ו כז) ״וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרַכֶם״. וְאֵין הָעָם עוֹנִין אָמֵן. וּמַתְחִיל וְאוֹמֵר שִׂים שָׁלוֹם:","כֹּהֵן שֶׁנָּשָׂא אֶת כַּפָּיו בְּבֵית הַכְּנֶסֶת וְהָלַךְ לְבֵית הַכְּנֶסֶת אַחֵר וּמָצָא צִבּוּר שֶׁמִּתְפַּלְּלִין וְלֹא הִגִּיעוּ לְבִרְכַּת כֹּהֲנִים נוֹשֵׂא יָדָיו לָהֶן וּמְבָרְכָן. וַאֲפִלּוּ כַּמָּה פְּעָמִים בְּיוֹם. כֹּהֵן שֶׁלֹּא עָקַר רַגְלָיו מִמְּקוֹמוֹ לַעֲלוֹת לַדּוּכָן בְּשָׁעָה שֶׁאָמַר שְׁלִיחַ צִבּוּר רְצֵה שׁוּב אֵינוֹ עוֹלֶה בְּאוֹתָהּ תְּפִלָּה. אֲבָל אִם עָקַר רַגְלָיו לַעֲלוֹת אַף עַל פִּי שֶׁלֹּא הִגִּיעַ לַדּוּכָן אֶלָּא אַחַר עֲבוֹדָה הֲרֵי זֶה עוֹלֶה וּמְבָרֵךְ:","כָּל כֹּהֵן שֶׁאֵינוֹ עוֹלֶה לַדּוּכָן אַף עַל פִּי שֶׁבִּטֵּל מִצְוַת עֲשֵׂה אַחַת הֲרֵי זֶה כְּעוֹבֵר עַל שָׁלֹשׁ עֲשֵׂה שֶׁנֶּאֱמַר (במדבר ו כג) ״כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל״ (במדבר ו כג) ״אָמוֹר לָהֶם״ (במדבר ו כז) ״וְשָׂמוּ אֶת שְׁמִי״. וְכָל כֹּהֵן שֶׁאֵינוֹ מְבָרֵךְ אֵינוֹ מִתְבָּרֵךְ וְכָל כֹּהֵן הַמְבָרֵךְ מִתְבָּרֵךְ שֶׁנֶּאֱמַר (בראשית יב ג) ״וַאֲבָרַכָה מְבָרְכֶיךָ״:סְלִיקוּ הִלְכוֹת תְּפִלָה בְּסִיַּעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Reading the Shema 4":["נָּשִׁים וַעֲבָדִים וּקְטַנִּים פְּטוּרִים מִקְּרִיאַת שְׁמַע. וּמְלַמְּדִין אֶת הַקְּטַנִּים לִקְרוֹתָהּ בְּעוֹנָתָהּ וּמְבָרְכִין לְפָנֶיהָ וּלְאַחֲרֶיהָ כְּדֵי לְחַנְּכָן בְּמִצְוֹת. מִי שֶׁהָיָה לִבּוֹ טָרוּד וְנֶחְפַּז לִדְבַר מִצְוָה פָּטוּר מִכָּל הַמִּצְוֹת וּמִקְּרִיאַת שְׁמַע. לְפִיכָךְ חָתָן שֶׁנָּשָׂא בְּתוּלָה פָּטוּר מִקְּרִיאַת שְׁמַע עַד שֶׁיָּבוֹא עָלֶיהָ. לְפִי שֶׁאֵין דַּעְתּוֹ פְּנוּיָה שֶׁמָּא לֹא יִמְצָא לָהּ בְּתוּלִים. וְאִם שָׁהָה עַד מוֹצָאֵי שַׁבָּת וְלֹא בָּעַל חַיָּב לִקְרוֹת מִמּוֹצָאֵי שַׁבָּת וְאֵילָךְ שֶׁהֲרֵי נִתְקָרְרָה דַּעְתּוֹ וְלִבּוֹ גַּס בָּהּ אַף עַל פִּי שֶׁלֹּא בָּעַל:","אֲבָל הַנּוֹשֵׂא אֶת הַבְּעוּלָה אַף עַל פִּי שֶׁעוֹסֵק בְּמִצְוָה חַיָּב לִקְרוֹת הוֹאִיל וְאֵין לוֹ דָּבָר שֶׁמְּבַלְבֵּל דַּעְתּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁמֵּת לוֹ מֵת שֶׁהוּא חַיָּב לְהִתְאַבֵּל עָלָיו פָּטוּר מִקְּרִיאַת שְׁמַע עַד שֶׁיִּקְבְּרֶנּוּ מִפְּנֵי שֶׁאֵין דַּעְתּוֹ פְּנוּיָה לִקְרוֹת. וְאִם הָיָה מְשַׁמֵּר אֶת הַמֵּת אַף עַל פִּי שֶׁאֵינוֹ מֵתוֹ פָּטוּר מִקְּרִיאַת שְׁמַע. וְאִם הָיוּ הַשּׁוֹמְרִים שְׁנַיִם הָאֶחָד מְשַׁמֵּר וְהַשֵּׁנִי נִשְׁמָט לְמָקוֹם אַחֵר וְקוֹרֵא וְחוֹזֵר וּמְשַׁמֵּר וְנִשְׁמָט הָאַחֵר וְקוֹרֵא. וְכֵן הַחוֹפֵר קֶבֶר לְמֵת פָּטוּר מִקְּרִיאַת שְׁמַע:","אֵין מוֹצִיאִין אֶת הַמֵּת לְקָבְרוֹ סָמוּךְ לִזְמַן קְרִיאַת שְׁמַע אֶלָּא אִם כֵּן הָיָה אָדָם גָּדוֹל. וְאִם הִתְחִילוּ וְהוֹצִיאוּ וְהִגִּיעַ זְמַן הַקְּרִיאָה וְהֵן מְלַוִּין אֶת הַמֵּת. כָּל שֶׁיֵּשׁ לַמִּטָּה צֹרֶךְ בָּהֶן כְּגוֹן נוֹשְׂאֵי הַמִּטָּה וְחִלּוּפֵיהֶן וְחִלּוּפֵי חִלּוּפֵיהֶן בֵּין שֶׁהָיוּ לִפְנֵי הַמִּטָּה בֵּין שֶׁהָיוּ לְאַחַר הַמִּטָּה פְּטוּרִין. וּשְׁאָר הַמְלַוִּין שֶׁאֵין לַמִּטָּה צֹרֶךְ בָּהֶן חַיָּבִין:","הָיוּ עֲסוּקִים בְּהֶסְפֵּד וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע בִּזְמַן שֶׁהַמֵּת מֻנָּח לִפְנֵיהֶן נִשְׁמָטִים אֶחָד אֶחָד וְקוֹרְאִין וְחוֹזְרִין לַהֶסְפֵּד. אֵין הַמֵּת מֻטָּל לִפְנֵיהֶם כָּל הָעָם קוֹרִין קְרִיאַת שְׁמַע וְהָאָבֵל יוֹשֵׁב וְדוֹמֵם לְפִי שֶׁאֵינוֹ חַיָּב לִקְרוֹת עַד שֶׁיִּקְבֹּר אֶת מֵתוֹ:","קָבְרוּ אֶת הַמֵּת וְחָזְרוּ הָאֲבֵלִים לְקַבֵּל תַּנְחוּמִין וְכָל הָעָם הוֹלְכִים אַחֲרֵיהֶם מִמְּקוֹם הַקֶּבֶר לַמָּקוֹם שֶׁעוֹמְדִים בּוֹ הָאֲבֵלִים לַעֲשׂוֹת שׁוּרָה לְקַבֵּל תַּנְחוּמִין. אִם יְכוֹלִין הָעָם לְהַתְחִיל וְלִגְמֹר אֲפִלּוּ פָּסוּק אֶחָד קֹדֶם שֶׁיַּגִּיעוּ לַשּׁוּרָה יַתְחִילוּ וְאִם לָאו לֹא יַתְחִילוּ אֶלָּא יְנַחֲמוּ אֶת הָאֲבֵלִים וְאַחַר שֶׁיִּפָּטְרוּ מֵהֶן יַתְחִילוּ לִקְרוֹת. בְּנֵי אָדָם הָעוֹמְדִין בַּשּׁוּרָה, הַפְּנִימִיִּים שֶׁהֵן רוֹאִין פְּנֵי הָאֲבֵלִים פְּטוּרִין מִקְּרִיאַת שְׁמַע וְהַחִיצוֹנִים הוֹאִיל וְאֵינָן רוֹאִין אֶת הָאֲבֵלִים חַיָּבִין בִּקְרִיאַת שְׁמַע בִּמְקוֹמָן:","כָּל מִי שֶׁהוּא פָּטוּר מִלִּקְרוֹת קְרִיאַת שְׁמַע אִם רָצָה לְהַחֲמִיר עַל עַצְמוֹ לִקְרוֹת קוֹרֵא. וְהוּא שֶׁתְּהֵא דַּעְתּוֹ פְּנוּיָה עָלָיו. אֲבָל אִם הָיָה זֶה הַפָּטוּר מִלִּקְרוֹת מְבֹהָל אֵינוֹ רַשַּׁאי לִקְרוֹת עַד שֶׁתִּתְיַשֵּׁב דַּעְתּוֹ עָלָיו:","כָּל הַטְּמֵאִין חַיָּבִין בִּקְרִיאַת שְׁמַע וּמְבָרְכִין לְפָנֶיהָ וּלְאַחֲרֶיהָ וְהֵן בְּטֻמְאָתָן. אַף עַל פִּי שֶׁאֶפְשָׁר לָהֶן לַעֲלוֹת מִטֻּמְאָתָן בּוֹ בַּיּוֹם כְּגוֹן הַנּוֹגְעִין בְּשֶׁרֶץ אוֹ בְּנִדָּה וְזָבָה וּמִשְׁכָּבָהּ וְכַיּוֹצֵא בָּהֶן. וְעֶזְרָא וּבֵית דִּינוֹ תִּקְּנוּ שֶׁלֹּא יִקְרָא בְּדִבְרֵי תּוֹרָה בַּעַל קֶרִי לְבַדּוֹ וְהוֹצִיאוּהוּ מִכְּלַל שְׁאָר הַטְּמֵאִין עַד שֶׁיִּטְבּל. וְלֹא פָּשְׁטָה תַּקָּנָה זוֹ בְּכָל יִשְׂרָאֵל וְלֹא הָיָה כֹּחַ בְּרֹב הַצִּבּוּר לַעֲמֹד בָּהּ לְפִיכָךְ בָּטְלָה. וּכְבָר נָהֲגוּ כָּל יִשְׂרָאֵל לִקְרוֹת בַּתּוֹרָה וְלִקְרוֹת קְרִיאַת שְׁמַע וְהֵן בַּעֲלֵי קְרָיִין לְפִי שֶׁאֵין דִּבְרֵי תּוֹרָה מְקַבְּלִין טֻמְאָה אֶלָּא עוֹמְדִין בְּטָהֳרָתָן לְעוֹלָם שֶׁנֶּאֱמַר (ירמיה כג כט) ״הֲלוֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם יְיָ׳‎״ מָה אֵשׁ אֵינָהּ מְקַבֶּלֶת טֻמְאָה אַף דִּבְרֵי תּוֹרָה אֵינָם מְקַבְּלִין טֻמְאָה:"],"Mishneh Torah, Red Heifer 13":["מַעֲלוֹת יְתֵרוֹת עָשׂוּ בְּטָהֳרַת הַחַטָּאת. שֶׁהָאָדָם הַטָּהוֹר אֲפִלּוּ טָבַל לְקֹדֶשׁ וְעוֹמֵד וּמְשַׁמֵּשׁ עַל גַּבֵּי הַמִּזְבֵּחַ אֵינוֹ טָהוֹר לְחַטָּאת וְלֹא לִשְׂרֵפַת הַפָּרָה וְלֹא לְמִלּוּי הַמַּיִם וְלֹא לְקַדְּשָׁן וְלֹא לְהַזּוֹת עַד שֶׁיִּטְבּל לְשֵׁם חַטָּאת וְאַחַר כָּךְ יִהְיֶה טָהוֹר לְחַטָּאת. וְכֵן הַכֵּלִים אֲפִלּוּ מִזְרָק שֶׁבָּעֲזָרָה אֵינוֹ טָהוֹר לְחַטָּאת עַד שֶׁיַּטְבִּילוּהוּ לְשֵׁם חַטָּאת. וְכֵן כָּל הָאֳכָלִין וְכָל הַמַּשְׁקִין אַף עַל פִּי שֶׁהֵן טְהוֹרִין הֲרֵי הֵן לְעִנְיַן חַטָּאת כָּאֳכָלִין וּמַשְׁקִין הַמְטַמְּאִין:","כָּל כְּלִי הָרָאוּי לְמִשְׁכָּב אוֹ לְמוֹשָׁב אַף עַל פִּי שֶׁהוּא טָהוֹר לְגַבֵּי הַקֹּדֶשׁ הֲרֵי הוּא לְגַבֵּי חַטָּאת כְּמִדְרַס הַזָּב עַד שֶׁיַּטְבִּילוּהוּ לְשֵׁם חַטָּאת. יוֹחָנָן בֶּן גֻּדְגְּדָא הָיָה אוֹכֵל בְּטָהֳרַת הַקֹּדֶשׁ כָּל יָמָיו וְהָיָה מִטְפַּחְתּוֹ כְּמִדְרַס הַזָּב לְעִנְיַן הַחַטָּאת:","כָּל וְלַד הַטֻּמְאוֹת אַף עַל פִּי שֶׁאֵינוֹ מְטַמֵּא אָדָם וְלֹא כֵלִים אֲפִלּוּ לְקֹדֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ. הֲרֵי הוּא מְטַמֵּא אָדָם וְכֵלִים לְחַטָּאת. לְפִיכָךְ אָמְרוּ הַמְקַדֵּשׁ אֶת מֵי חַטָּאת לֹא יִנְעל אֶת הַסַּנְדָּל. שֶׁמָּא יִפְּלוּ מַשְׁקִין עַל הַסַּנְדָּל וְנִמְצָא הַסַּנְדָּל טָמֵא שֶׁכָּל הַמַּשְׁקִין טְמֵאִין הֵן לִגבֵּי החטָּאת וִיתִטמֵּא זֶה הַמְקַדֵּשׁ בִּנְגִיעָתוֹ בְּסַנְדָּל וְנִמְצְאוּ מֵי חַטָּאת טְמֵאִים:","מִי שֶׁנִּטְמְאוּ יָדָיו בִּלְבַד בַּדְּבָרִים הַמְטַמְּאִין אֶת הַיָּדַיִם כְּגוֹן שֶׁנָּגַע בָּאֳכָלִין אוֹ בְּמַשְׁקִין וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁהוּא טָהוֹר לַקֹּדֶשׁ וְאֵינוֹ צָרִיךְ אֶלָּא טְבִילַת יָדָיו בִּלְבַד כְּמוֹ שֶׁיִּתְבָּאֵר. הֲרֵי נִטְמָא כָּל גּוּפוֹ לְעִנְיַן הַחַטָּאת וְצָרִיךְ טְבִילָה. אֲפִלּוּ לֹא נִטְמֵאת אֶלָּא יָדוֹ אַחַת נִטְמָא כֻּלּוֹ וַהֲרֵי הוּא רִאשׁוֹן לְטֻמְאָה:","כָּל הַטָּעוּן טְבִילָה בֵּין מִן הַתּוֹרָה בֵּין מִדִּבְרֵיהֶם מְטַמֵּא אֶת מֵי חַטָּאת וְאֶת אֵפֶר הַחַטָּאת וְאֶת הַמַּזֶּה מֵי חַטָּאת בְּמַגָּע וּבְמַשָּׂא. וְכֵן מְטַמֵּא אֶת הָאֵזוֹב הַמֻּכְשָׁר וְאֶת הַמַּיִם שֶׁנִּתְמַלְּאוּ וַעֲדַיִן לֹא נִתְקַדְּשׁוּ. וְאֶת הַכְּלִי הָרֵיקָן הַטָּהוֹר לְחַטָּאת. מְטַמֵּא כָּל אֶחָד מֵאֵלּוּ בְּמַגָּע אֲבָל לֹא בְּמַשָּׂא. וְטָמֵא שֶׁנָּגַע בְּמִקְצָת אֵפֶר חַטָּאת פָּסַל אֶת כֻּלּוֹ:","אֵין מוֹנִין לְחַטָּאת רִאשׁוֹן וְשֵׁנִי וּשְׁלִישִׁי כְּדֶרֶךְ שֶׁמּוֹנִין לִתְרוּמָה וּלְקֹדֶשׁ. כֵּיצַד. עֲשָׂרָה שֶׁטָּבְלוּ לְשֵׁם חַטָּאת וְנִטְמָא אֶחָד מֵהֶן אֲפִלּוּ לֹא נִטְמָא אֶלָּא לְגַבֵּי חַטָּאת בִּלְבַד כְּגוֹן שֶׁנִּטְמֵאת יָדוֹ בִּלְבַד וְנָגַע בַּחֲבֵרוֹ וַחֲבֵרוֹ בַּחֲבֵרוֹ אֲפִלּוּ הֵן מֵאָה כֻּלָּן טְמֵאִין לְחַטָּאת. וְכֵן כֵלִים הַטְּהוֹרִים לְחַטָּאת שֶׁנִּטְמָא כְּלִי מֵהֶן אֲפִלּוּ לֹא נִטְמְאוּ אֶלָּא אֲחוֹרָיו בִּלְבַד לְגַבֵּי חַטָּאת כְּגוֹן שֶׁנָּגְעוּ מַשְׁקִין בַּאֲחוֹרָיו וְנָגַע כְּלִי זֶה בִּכְלִי שֵׁנִי וְשֵׁנִי בִּשְׁלִישִׁי נִטְמְאוּ הַכֵּלִים כֻּלָּן לְגַבֵּי הַחַטָּאת וַאֲפִלּוּ הֵן מֵאָה:","כָּל הָרָאוּי לְהִתְטַמֵּא בְּמִדְרַס הַזָּב אַף עַל פִּי שֶׁהוּא טָהוֹר לְקֹדֶשׁ אִם הֵנִידוֹ הַטָּהוֹר לְחַטָּאת נִטְמָא אַף עַל פִּי שֶׁלֹּא נָגַע בּוֹ. וְכֵן הַטָּהוֹר לְחַטָּאת שֶׁהֵנִיד אֶת הָאָדָם שֶׁאֵינוֹ טָהוֹר לְחַטָּאת. אוֹ שֶׁהֵנִיד אֶת רֻקּוֹ אוֹ אֶת מֵימֵי רַגְלָיו שֶׁל אָדָם זֶה. נִטְמָא אַף עַל פִּי שֶׁלֹּא נָגַע בּוֹ. אֲבָל כְּלִי שֶׁאֵינוֹ רָאוּי לְמִדְרָס אֵינוֹ מְטַמֵּא אֶת הַטָּהוֹר לְחַטָּאת אֶלָּא אִם כֵּן נָגַע בּוֹ:","כְּלִי הַטָּמֵא בִּטְמֵא מֵת אִם הֵנִידוֹ הַטָּהוֹר לְחַטָּאת נִטְמָא וְאַף עַל פִּי שֶׁלֹּא נָגַע בּוֹ וְאַף עַל פִּי שֶׁאֵין טְמֵא מֵת מְטַמֵּא בְּמַשָּׂא כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד. מַפְתֵּחַ שֶׁהוּא טְמֵא מֵת שֶׁהָיָה תָּלוּי בַּדֶּלֶת וְסָגַר הַטָּהוֹר לְחַטָּאת אֶת הַדֶּלֶת הוֹאִיל וְהֵנִיד אֶת הַמַּפְתֵּחַ הַטָּמֵא נִטְמָא. וְכֵן אִם הֵסִיט אֶת הַשֶּׁרֶץ וְאֶת שִׁכְבַת זֶרַע הֲרֵי זֶה טָמֵא לְחַטָּאת אַף עַל פִּי שֶׁאֵין אֵלּוּ מְטַמְּאִין בְּמַשָּׂא כְּמוֹ שֶׁיִּתְבָּאֵר:","הַטָּהוֹר לְחַטָּאת שֶׁנָּגַע בְּכֵלִים שֶׁהָיוּ לְמַעְלָה מִן הַזָּב וְכַיּוֹצֵא בּוֹ וְהֵן הַנִּקְרָאִין מַדָּף אַף עַל פִּי שֶׁהוּא טָהוֹר לְקֹדֶשׁ נִטְמָא לְחַטָּאת. וְכֵן כְּלִי הַטָּהוֹר לְחַטָּאת שֶׁנָּגַע בְּמַדָּף נִטְמָא לְחַטָּאת:","הַטָּהוֹר לְחַטָּאת שֶׁנָּגַע בָּאֳכָלִין וּמַשְׁקִין בֵּין טְהוֹרִין בֵּין טְמֵאִים שֶׁכָּל אֳכָלִין וּמַשְׁקִין לְגַבֵּי חַטָּאת אֵינָן טְהוֹרִין אִם נָגַע בָּהֶן בְּיָדוֹ נִטְמָא כָּל גּוּפוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. נָגַע בָּהֶן בְּרַגְלוֹ אוֹ בִּשְׁאָר גּוּפוֹ אוֹ שֶׁהֱסִיטָן בְּיָדוֹ וְלֹא נָגַע בָּהֶן טָהוֹר. וְכֵן אִם נָגַע בְּתַנּוּר וְכַיּוֹצֵא בּוֹ מִשְׁאָר כֵּלִים שֶׁאֵינָם טְהוֹרִין לְחַטָּאת נִטְמָא כֻּלּוֹ. אֲבָל אִם נָגַע בְּרַגְלוֹ בָּהֶן הֲרֵי הוּא טָהוֹר לְחַטָּאת כְּמוֹ שֶׁהָיָה:","הַטָּהוֹר לְחַטָּאת שֶׁהִכְנִיס רֹאשׁוֹ וְרֻבּוֹ לְתוֹךְ מַיִם שֶׁנִּתְמַלְּאוּ לְחַטָּאת נִטְמָא מִפְּנֵי שֶׁהֵן שְׁאוּבִין. וּמִדִּבְרֵי סוֹפְרִים שֶׁהַבָּא רֹאשׁוֹ וְרֻבּוֹ בְּמַיִם שְׁאוּבִין נִטְמָא כְּמוֹ שֶׁיִּתְבָּאֵר:","הַכּל נֶאֱמָנִין עַל טָהֳרַת הַחַטָּאת וַאֲפִלּוּ עַמֵּי הָאָרֶץ מִפְּנֵי חֻמְרָתָהּ. וּמַעֲלוֹת אֵלּוּ שֶׁעָשׂוּ בָּהּ הַכּל נִזְהָרִין בָּהּ. וַהֲרֵי נֶאֱמַר בַּתּוֹרָה (במדבר יט ט) \"וְהָיְתָה לַעֲדַת בְּנֵי יִשְׂרָאֵל לְמִשְׁמֶרֶת\" כָּל יִשְׂרָאֵל רְאוּיִין לִשְׁמִירָה. לְפִיכָךְ עַם הָאָרֶץ שֶׁהֵבִיא כְּלִי מִבֵּיתוֹ אֲפִלּוּ כְּלִי חֶרֶס וְאָמַר כְּלִי זֶה טָהוֹר לְחַטָּאת הֲרֵי זֶה טָהוֹר וּמְקַדְּשִׁין בּוֹ וּמַזִּין מִמֶּנּוּ. וְאַף עַל פִּי שֶׁאוֹתוֹ כְּלִי טָמֵא לְקֹדֶשׁ וְלִתְרוּמָה. וְכֵן עַם הָאָרֶץ שֶׁאָמַר טָהוֹר אֲנִי לְחַטָּאת אוֹ שֶׁהָיוּ מֵי חַטָּאת אֶצְלוֹ וְאָמַר טְהוֹרִין הֵן נֶאֱמָן. שֶׁאֵין אָדָם מִיִּשְׂרָאֵל מְזַלְזֵל בָּהּ:"],"Mishneh Torah, Repentance 10":["אַל יֹאמַר אָדָם הֲרֵינִי עוֹשֶׂה מִצְוֹת הַתּוֹרָה וְעוֹסֵק בְּחָכְמָתָהּ כְּדֵי שֶׁאֲקַבֵּל כָּל הַבְּרָכוֹת הַכְּתוּבוֹת בָּהּ אוֹ כְּדֵי שֶׁאֶזְכֶּה לְחַיֵּי הָעוֹלָם הַבָּא, וְאֶפְרשׁ מִן הָעֲבֵרוֹת שֶׁהִזְהִירָה תּוֹרָה מֵהֶן כְּדֵי שֶׁאֶנָּצֵל מִן הַקְּלָלוֹת הַכְּתוּבוֹת בַּתּוֹרָה אוֹ כְּדֵי שֶׁלֹּא אֶכָּרֵת מֵחַיֵּי הָעוֹלָם הַבָּא. אֵין רָאוּי לַעֲבֹד אֶת ה' עַל הַדֶּרֶךְ הַזֶּה, שֶׁהָעוֹבֵד עַל דֶּרֶךְ זֶה הוּא עוֹבֵד מִיִּרְאָה וְאֵינָהּ מַעֲלַת הַנְּבִיאִים וְלֹא מַעֲלַת הַחֲכָמִים. וְאֵין עוֹבְדִים ה' עַל דֶּרֶךְ זֶה אֶלָּא עַמֵּי הָאָרֶץ וְהַנָּשִׁים וְהַקְּטַנִּים שֶׁמְּחַנְּכִין אוֹתָן לַעֲבֹד מִיִּרְאָה עַד שֶׁתִּרְבֶּה דַּעְתָּן וְיַעַבְדוּ מֵאַהֲבָה:","הָעוֹבֵד מֵאַהֲבָה עוֹסֵק בַּתּוֹרָה וּבַמִּצְוֹת וְהוֹלֵךְ בִּנְתִיבוֹת הַחָכְמָה לֹא מִפְּנֵי דָּבָר בָּעוֹלָם וְלֹא מִפְּנֵי יִרְאַת הָרָעָה וְלֹא כְּדֵי לִירַשׁ הַטּוֹבָה אֶלָּא עוֹשֶׂה הָאֱמֶת מִפְּנֵי שֶׁהוּא אֱמֶת וְסוֹף הַטּוֹבָה לָבוֹא בִּגְלָלָהּ. וּמַעֲלָה זוֹ הִיא מַעֲלָה גְּדוֹלָה מְאֹד וְאֵין כָּל חָכָם זוֹכֶה לָהּ. וְהִיא מַעֲלַת אַבְרָהָם אָבִינוּ שֶׁקְּרָאוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֲבוֹ לְפִי שֶׁלֹּא עָבַד אֶלָּא מֵאַהֲבָה. וְהִיא הַמַּעֲלָה שֶׁצִּוָּנוּ בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי משֶׁה שֶׁנֶּאֱמַר (דברים ו ה) \"וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךָ\". וּבִזְמַן שֶׁיֶּאֱהֹב אָדָם אֶת ה' אַהֲבָה הָרְאוּיָה מִיָּד יַעֲשֶׂה כָּל הַמִּצְוֹת מֵאַהֲבָה:","וְכֵיצַד הִיא הָאַהֲבָה הָרְאוּיָה. הוּא שֶׁיֹּאהַב אֶת ה' אַהֲבָה גְּדוֹלָה יְתֵרָה עַזָּה מְאֹד עַד שֶׁתְּהֵא נַפְשׁוֹ קְשׁוּרָה בְּאַהֲבַת ה' וְנִמְצָא שׁוֹגֶה בָּהּ תָּמִיד כְּאִלּוּ חוֹלֶה חֳלִי הָאַהֲבָה שֶׁאֵין דַּעְתּוֹ פְּנוּיָה מֵאַהֲבַת אוֹתָהּ אִשָּׁה וְהוּא שׁוֹגֶה בָּהּ תָּמִיד בֵּין בְּשִׁבְתּוֹ בֵּין בְּקוּמוֹ בֵּין בְּשָׁעָה שֶׁהוּא אוֹכֵל וְשׁוֹתֶה. יֶתֶר מִזֶּה תִּהְיֶה אַהֲבַת ה' בְּלֵב אוֹהֲבָיו שׁוֹגִים בָּהּ תָּמִיד כְּמוֹ שֶׁצִּוָּנוּ בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ. וְהוּא שֶׁשְּׁלֹמֹה אָמַר דֶּרֶךְ מָשָׁל (שיר השירים ב ה) \"כִּי חוֹלַת אַהֲבָה אָנִי\". וְכָל שִׁיר הַשִּׁירִים מָשָׁל הוּא לְעִנְיָן זֶה:","אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים שֶׁמָּא תֹּאמַר הֲרֵינִי לָמֵד תּוֹרָה בִּשְׁבִיל שֶׁאֶהְיֶה עָשִׁיר בִּשְׁבִיל שֶׁאֶקְרָא רַבִּי בִּשְׁבִיל שֶׁאֲקַבֵּל שָׂכָר בָּעוֹלָם הַבָּא. תַּלְמוּד לוֹמַר (דברים יא יג) \"לְאַהֲבָה אֶת ה'\". כָּל מַה שֶּׁאַתֶּם עוֹשִׂים לֹא תַּעֲשׂוּ אֶלָּא מֵאַהֲבָה. וְעוֹד אָמְרוּ חֲכָמִים בְּמִצְוֹתָיו חָפֵץ מְאֹד וְלֹא בִּשְׂכַר מִצְוֹתָיו. וְכֵן הָיוּ גְּדוֹלֵי הַחֲכָמִים מְצַוִּים לִנְבוֹנֵי תַּלְמִידֵיהֶם וּמַשְׂכִּילֵיהֶם בְּיִחוּד אַל תִּהְיוּ כַּעֲבָדִים הַמְשַׁמְּשִׁים אֶת הָרַב וְכוּ' אֶלָּא מִפְּנֵי שֶׁהוּא הָרַב רָאוּי לְשַׁמְּשׁוֹ כְּלוֹמַר עִבְדוּ מֵאַהֲבָה:","כָּל הָעוֹסֵק בַּתּוֹרָה כְּדֵי לְקַבֵּל שָׂכָר אוֹ כְּדֵי שֶׁלֹּא תַּגִּיעַ עָלָיו פֻּרְעָנוּת הֲרֵי זֶה עוֹסֵק שֶׁלֹּא לִשְׁמָהּ. וְכָל הָעוֹסֵק בָּהּ לֹא לְיִרְאָה וְלֹא לְקַבֵּל שָׂכָר אֶלָּא מִפְּנֵי אַהֲבַת אֲדוֹן כָּל הָאָרֶץ שֶׁצִּוָּה בָּהּ הֲרֵי זֶה עוֹסֵק בָּהּ לִשְׁמָהּ. וְאָמְרוּ חֲכָמִים לְעוֹלָם יַעֲסֹק אָדָם בַּתּוֹרָה וַאֲפִלּוּ שֶׁלֹּא לִשְׁמָהּ שֶׁמִּתּוֹךְ שֶׁלֹּא לִשְׁמָהּ בָּא לִשְׁמָהּ. לְפִיכָךְ כְּשֶׁמְּלַמְּדִין אֶת הַקְּטַנִּים וְאֶת הַנָּשִׁים וּכְלַל עַמֵּי הָאָרֶץ אֵין מְלַמְּדִין אוֹתָן אֶלָּא לַעֲבֹד מִיִּרְאָה וּכְדֵי לְקַבֵּל שָׂכָר, עַד שֶׁתִּרְבֶּה דַּעְתָּן וְיִתְחַכְּמוּ חָכְמָה יְתֵרָה מְגַלִּים לָהֶם רָז זֶה מְעַט מְעַט וּמַרְגִּילִין אוֹתָן לְעִנְיָן זֶה בְּנַחַת עַד שֶׁיַּשִּׂיגוּהוּ וְיֵדְעוּהוּ וְיַעַבְדוּהוּ מֵאַהֲבָה:","דָּבָר יָדוּעַ וּבָרוּר שֶׁאֵין אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְשֶׁרֶת בְּלִבּוֹ שֶׁל אָדָם עַד שֶׁיִּשְׁגֶּה בָּהּ תָּמִיד כָּרָאוּי וְיַעֲזֹב כָּל מַה שֶּׁבָּעוֹלָם חוּץ מִמֶּנָּה. כְּמוֹ שֶׁצִּוָּה וְאָמַר בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ. אֵינוֹ אוֹהֵב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא בְּדַעַת שֶׁיְּדָעֵהוּ. וְעַל פִּי הַדֵּעָה תִּהְיֶה הָאַהֲבָה אִם מְעַט מְעַט וְאִם הַרְבֵּה הַרְבֵּה. לְפִיכָךְ צָרִיךְ הָאָדָם לְיַחֵד עַצְמוֹ לְהָבִין וּלְהַשְׂכִּיל בְּחָכְמוֹת וּתְבוּנוֹת הַמּוֹדִיעִים לוֹ אֶת קוֹנוֹ כְּפִי כֹּחַ שֶׁיֵּשׁ בָּאָדָם לְהָבִין וּלְהַשִּׂיג כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת יְסוֹדֵי הַתּוֹרָה:","(נגמר ספר ראשון והוא ספר המדע.)"],"Mishneh Torah, Rest on a Holiday 4":["אֵין מוֹצִיאִין אֶת הָאֵשׁ לֹא מִן הָעֵצִים וְלֹא מִן הָאֲבָנִים וְלֹא מִן הַמַּתָּכוֹת. כְּגוֹן שֶׁחוֹכְכִין אוֹתָן זוֹ בָּזוֹ אוֹ מַכִּין זוֹ בָּזוֹ עַד שֶׁתֵּצֵא הָאֵשׁ. וְכֵן הַנֵּפְט הַחַד בְּיוֹתֵר שֶׁהוּא בְּמַיִם שֶׁמְּנִידִין אוֹתָם עַד שֶׁיִּדָּלֵק. אוֹ כְּלִי זַךְ קָשֶׁה אוֹ זְכוּכִית מְלֵאָה מַיִם שֶׁמַּנִּיחִין אוֹתָהּ כְּנֶגֶד עֵין הַשֶּׁמֶשׁ עַד שֶׁיַּחֲזֹר נָגְהָהּ לַפִּשְׁתָּן וְכַיּוֹצֵא בּוֹ וְיִדְלַק. כָּל זֶה וְכַיּוֹצֵא בּוֹ אָסוּר בְּיוֹם טוֹב. שֶׁלֹּא הֻתַּר בְּיוֹם טוֹב אֶלָּא לְהַבְעִיר מֵאֵשׁ מְצוּיָה. אֲבָל לְהַמְצִיא אֵשׁ אָסוּר שֶׁהֲרֵי אֶפְשָׁר לְהַמְצִיא אוֹתָהּ מִבָּעֶרֶב:","אַף עַל פִּי שֶׁהֻתְּרָה הַבְעָרָה בְּיוֹם טוֹב שֶׁלֹּא לְצֹרֶךְ אָסוּר לְכַבּוֹת אֶת הָאֵשׁ אֲפִלּוּ הֻבְעֲרָה לְצֹרֶךְ אֲכִילָה. שֶׁהַכִּבּוּי מְלָאכָה שֶׁאֵין בּוֹ צֹרֶךְ אֲכִילָה כְּלָל. וּכְשֵׁם שֶׁאֵין מְכַבִּים אֶת הָאֵשׁ כָּךְ אֵין מְכַבִּים אֶת הַנֵּר וְאִם כִּבָּה לוֹקֶה כְּמִי שֶׁאָרַג אוֹ בָּנָה:","אֵין מְסַלְּקִין אֶת פִּי הַנֵּר לְמַעְלָה כְּדֵי שֶׁתִּכְבֶּה. וְאֵין מְסִירִין אֶת הַשֶּׁמֶן מִמֶּנּוּ וְאֵינוֹ חוֹתֵךְ אֶת רֹאשׁ הַפְּתִילָה בִּכְלִי. אֲבָל נוֹפֵץ אֶת רֹאשָׁהּ בְּיָדוֹ. אֲגֻדָּה שֶׁל עֵצִים שֶׁהֻדְלְקָה בִּמְדוּרָה כָּל עֵץ שֶׁלֹּא אָחֲזָה בּוֹ הָאֵשׁ מֻתָּר לְשָׁמְטוֹ וְאֵינוֹ דּוֹמֶה לְמֵסִיר שֶׁמֶן מִן הַנֵּר:","אֵין מְכַבִּין אֶת הַדְּלֵקָה כְּדֵי לְהַצִּיל מָמוֹן בְּיוֹם טוֹב כְּדֶרֶךְ שֶׁאֵין מְכַבִּין בְּשַׁבָּת אֶלָּא מְנִיחָהּ וְיוֹצֵא. וְאֵין מְכַבִּין אֶת הַנֵּר מִפְּנֵי תַּשְׁמִישׁ הַמִּטָּה אֶלָּא כּוֹפֶה עָלָיו כְּלִי אוֹ עוֹשֶׂה מְחִצָּה בֵּינוֹ לְבֵין הַנֵּר אוֹ מוֹצִיאוֹ לְבֵית אַחֵר. וְאִם אֵינוֹ יָכוֹל לַעֲשׂוֹת אַחַת מִכָּל אֵלּוּ הֲרֵי זֶה אָסוּר לְכַבּוֹת וְאָסוּר לְשַׁמֵּשׁ עַד שֶׁתִּכְבֶּה מֵאֵלֶיהָ:","מֻתָּר לְטַלְטֵל אֶת הַנֵּר וְהוּא דּוֹלֵק וְאֵין גּוֹזְרִין שֶׁמָּא יִכְבֶּה. וְאָסוּר לְהָנִיחַ אֶת הַנֵּר עַל גַּבֵּי דֶּקֶל וְכַיּוֹצֵא בּוֹ בְּיוֹם טוֹב שֶׁמָּא יָבוֹא לְהִשְׁתַּמֵּשׁ בִּמְחֻבָּר בְּיוֹם טוֹב:","אֵין מְעַשְּׁנִין בִּקְטֹרֶת בְּיוֹם טוֹב מִפְּנֵי שֶׁהוּא מְכַבֶּה. וַאֲפִלּוּ לְהָרִיחַ בָּהּ. וְאֵין צָרִיךְ לוֹמַר לְגַמֵּר אֶת הַבַּיִת וְאֶת הַכֵּלִים שֶׁהוּא אָסוּר. וּמֻתָּר לְעַשֵּׁן תַּחַת הַפֵּרוֹת כְּדֵי שֶׁיֻּכְשְׁרוּ לַאֲכִילָה כְּמוֹ שֶׁמֻּתָּר לִצְלוֹת בָּשָׂר עַל הָאֵשׁ. וּמְמַתְּקִין אֶת הַחַרְדָּל בְּגַחֶלֶת שֶׁל מַתֶּכֶת אֲבָל לֹא בְּגַחֶלֶת שֶׁל עֵץ מִפְּנֵי שֶׁהוּא מְכַבֶּה. וְאֵין מְכַבִּין אֶת הָאֵשׁ כְּדֵי שֶׁלֹּא תִּתְעַשֵּׁן הַקְּדֵרָה אוֹ הַבַּיִת:","אֵין נוֹפְחִין בְּמַפּוּחַ בְּיוֹם טוֹב כְּדֵי שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהָאֻמָּנִין עוֹשִׂין. אֲבָל נוֹפְחִין בִּשְׁפוֹפֶרֶת. אֵין עוֹשִׂין פֶּחָמִין וְאֵין גּוֹדְלִין אֶת הַפְּתִילָה וְלֹא מְהַבְהֲבִין אוֹתָהּ וְלֹא חוֹתְכִין אוֹתָהּ לִשְׁנַיִם בִּכְלִי. אֲבָל מְמַעֲכָהּ בַּיָּד וְשׁוֹרֶה אוֹתָהּ בְּשֶׁמֶן וּמַנִּיחַ אוֹתָהּ בֵּין שְׁתֵּי נֵרוֹת וּמַדְלִיק בָּאֶמְצַע וְנִמְצֵאת הַפְּתִילָה נֶחְלֶקֶת בְּפִי שְׁתֵּי נֵרוֹת:","אֵין שׁוֹבְרִין אֶת הַחֶרֶשׂ וְאֵין חוֹתְכִין אֶת הַנְּיָר לִצְלוֹת עֲלֵיהֶם. וְאֵין פּוֹצְעִין אֶת הַקָּנֶה לַעֲשׂוֹתוֹ כְּמוֹ שִׁפּוּד לִצְלוֹת בּוֹ מָלִיחַ. שִׁפּוּד שֶׁנִּרְצָף אַף עַל פִּי שֶׁהוּא יָכוֹל לְפָשְׁטוֹ בְּיָדוֹ אֵין מְתַקְּנִין אוֹתוֹ. שְׁנֵי כֵּלִים שֶׁהֵן מְחֻבָּרִין בִּתְחִלַּת עֲשִׂיָּתָן כְּגוֹן שְׁתֵּי נֵרוֹת אוֹ שְׁנֵי כּוֹסוֹת אֵין פּוֹחֲתִין אוֹתָן לִשְׁנַיִם מִפְּנֵי שֶׁהוּא כִּמְתַקֵּן כְּלִי:","אֵין מַשְׁחִיזִין אֶת הַסַּכִּין בְּמַשְׁחֶזֶת שֶׁלָּהּ אֲבָל מְחַדְּדָהּ עַל גַּבֵּי הָעֵץ אוֹ עַל גַּבֵּי חֶרֶשׂ אוֹ אֶבֶן וְאֵין מוֹרִים דָּבָר זֶה לָרַבִּים כְּדֵי שֶׁלֹּא יָבֹאוּ לְחַדְּדָהּ בְּמַשְׁחֶזֶת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁיְּכוֹלָה לַחְתֹּךְ בְּדֹחַק אוֹ שֶׁנִּפְגְּמָה. אֲבָל אִם אֵינָהּ יְכוֹלָה לַחְתֹּךְ כְּלָל אֵין מַשְׁחִיזִין אוֹתָהּ אֲפִלּוּ עַל הָעֵץ שֶׁמָּא יָבֹא לְהַשְׁחִיזָהּ בְּמַשְׁחֶזֶת. ומִפְּנֵי זֶה אָסְרוּ לְהַרְאוֹת סַכִּין לְחָכָם בְּיוֹם טוֹב שֶׁמָּא תִּהְיֶה פְּגוּמָה וְיֹאמַר לוֹ אָסוּר לִשְׁחֹט בָּהּ מִשּׁוּם פְּגִימָתָהּ וְיֵלֵךְ וִיחַדְּדֶנָּהּ בְּמַשְׁחֶזֶת. וְחָכָם שֶׁרָאָה הַסַּכִּין לְעַצְמוֹ הֲרֵי זֶה מַשְׁאִילָהּ לְעַם הָאָרֶץ:","אֵין מְבַקְּעִין עֵצִים בְּיוֹם טוֹב לֹא בְּקוֹרְדוֹם וְלֹא בְּמַגָּל וְלֹא בִּמְגֵרָה אֶלָּא בְּקוֹפִיץ וּבַצַּד הַחַד שֶׁלּוֹ. אֲבָל לֹא בַּצַּד הָרָחָב מִפְּנֵי שֶׁהִיא כְּקוֹרְדוֹם. וְלָמָּה אָסְרוּ בְּקוֹרְדוֹם וְכַיּוֹצֵא בּוֹ שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל שֶׁהֲרֵי אֶפְשָׁר הָיָה לוֹ לְבַקֵּעַ מֵעֶרֶב יוֹם טוֹב. וְלָמָּה לֹא נֶאֱסַר הַבִּקּוּעַ כְּלָל מִפְּנֵי שֶׁאֶפְשָׁר שֶׁיִּפְגַּע בְּעֵץ עָבֶה וְלֹא יוּכַל לְהַבְעִירוֹ וְיִמָּנַע מִלְּבַשֵּׁל. לְפִיכָךְ הִתִּירוּ לְבַקֵּעַ בְּשִׁנּוּי. וְכָל הַדְּבָרִים הַדּוֹמִין לָזֶה מִזֶּה הַטַּעַם הִתִּירוּ בָּהֶן מַה שֶּׁהִתִּירוּ וְאָסְרוּ מַה שֶּׁאָסְרוּ:","לֹא תִּכָּנֵס אִשָּׁה בֵּין הָעֵצִים לִטּל מֵהֶן אוּד לִצְלוֹת בּוֹ. וְאֵין סוֹמְכִין אֶת הַקְּדֵרָה וְלֹא אֶת הַדֶּלֶת בִּבְקַעַת שֶׁל קוֹרָה. שֶׁלֹּא הִתִּירוּ לְטַלְטֵל עֵצִים בְּיוֹם טוֹב אֶלָּא לְהַסָּקָה בִּלְבַד:","מְסַלְּקִין תְּרִיסֵי חֲנֻיּוֹת וּמַחְזִירִין אוֹתָן בְּיוֹם טוֹב כְּדֵי שֶׁיּוֹצִיא תַּבְלִין שֶׁהוּא צָרִיךְ לָהֶן מִן הַחֲנוּת וְלֹא יִמָּנַע מִשִּׂמְחַת יוֹם טוֹב. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁיֵּשׁ לָהֶן צִיר בְּאֶמְצַע אֲבָל יֵשׁ לָהֶן צִיר מִן הַצַּד אָסוּר גְּזֵרָה שֶׁמָּא יִתְקַע. וְשֶׁאֵין לָהֶן צִיר כָּל עִקָּר אֲפִלּוּ בַּבַּיִת מֻתָּר לְהַחֲזִיר:","כֵּלִים שֶׁהֵן מְפֻצָּלִין כְּגוֹן מְנוֹרָה שֶׁל חֻלְיוֹת וְכִסֵּא וְשֻׁלְחָן שֶׁהֵן חֲתִיכוֹת חֲתִיכוֹת מַעֲמִידִין אוֹתָן בְּיוֹם טוֹב וְהוּא שֶׁלֹּא יִתְקַע. לְפִי שֶׁאֵין בִּנְיָן בְּכֵלִים. אֲבָנִים שֶׁל בֵּית הַכִּסֵּא מֻתָּר לְצַדְּדָן בְּיוֹם טוֹב. בִּנְיָן עֲרַאי הוּא וּמִשּׁוּם כְּבוֹדוֹ לֹא גָּזְרוּ:","הָעוֹשֶׂה מְדוּרָה בְּיוֹם טוֹב כְּשֶׁהוּא עוֹרֵךְ אֶת הָעֵצִים אֵינוֹ מַנִּיחַ זֶה עַל זֶה עַד שֶׁיַּסְדִּיר הַמַּעֲרָכָה מִפְּנֵי שֶׁנִּרְאֶה כְּבוֹנֶה. וְאַף עַל פִּי שֶׁהוּא בִּנְיָן עֲרַאי אָסוּר. אֶלָּא אוֹ שׁוֹפֵךְ הָעֵצִים בְּעִרְבּוּב אוֹ עוֹרֵךְ בְּשִׁנּוּי. כֵּיצַד. מַנִּיחַ עֵץ לְמַעְלָה וּמַנִּיחַ אַחֵר תַּחְתָּיו וְאַחֵר תַּחְתָּיו עַד שֶׁהוּא מַגִּיעַ לָאָרֶץ:","וְכֵן הַקְּדֵרָה אוֹחֵז אוֹתָהּ וּמַכְנִיס הָאֲבָנִים תַּחְתֶּיהָ. אֲבָל לֹא יַנִּיחֶנָּהּ עַל גַּבֵּי הָאֲבָנִים. וְכֵן הַמִּטָּה אוֹחֵז הַקְּרָשִׁים לְמַעְלָה וּמַכְנִיס הָרַגְלַיִם תַּחְתֵּיהֶן. אֲפִלּוּ בֵּיצִים לֹא יַעֲמִיד אוֹתָן בְּשׁוּרָה עַל גַּבֵּי שׁוּרָה עַד שֶׁיַּעַמְדוּ כְּמוֹ מִגְדָּל אֶלָּא יְשַׁנֶּה וְיַתְחִיל מִלְּמַעְלָה לְמַטָּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה צָרִיךְ שִׁנּוּי:","מְסִירִין זְבוּבִין הַנִּתְלִים בַּבְּהֵמָה אַף עַל פִּי שֶׁהֵן עוֹשִׂין חַבּוּרָה. וְאֵין מְיַלְּדִין אֶת הַבְּהֵמָה בְּיוֹם טוֹב אֲבָל מְסַעֲדִין. כֵּיצַד. אוֹחֵז בַּוָּלָד שֶׁלֹּא יִפּל לָאָרֶץ וְנוֹפֵחַ לוֹ בְּחָטְמוֹ וְנוֹתֵן דָּד לְתוֹךְ פִּיו. הָיְתָה בְּהֵמָה טְהוֹרָה וְרִחֲקָה אֶת הַוָּלָד מֻתָּר לְזַלֵּף מִשִּׁלְיָתָהּ עָלָיו וְלִתֵּן בּוּל מֶלַח בְּרַחְמָהּ כְּדֵי שֶׁתְּרַחֵם עָלָיו. אֲבָל הַטְּמֵאָה אָסוּר לַעֲשׂוֹת לָהּ כֵּן לְפִי שֶׁאֵינָהּ צְרִיכָה:","כְּלִי שֶׁנִּטְמָא מֵעֶרֶב יוֹם טוֹב אֵין מַטְבִּילִין אוֹתוֹ בְּיוֹם טוֹב גְּזֵרָה שֶׁמָּא יַשְׁהֶה אוֹתוֹ בְּטֻמְאָתוֹ. וְאִם הָיָה צָרִיךְ לְהַטְבִּיל מַיִם שֶׁבּוֹ מַטְבִּיל אֶת הַכְּלִי בְּמֵימָיו וְאֵינוֹ חוֹשֵׁשׁ. כְּלִי שֶׁהָיָה טָהוֹר לִתְרוּמָה וְרָצָה לְהַטְבִּילוֹ לְקֹדֶשׁ מֻתָּר לְהַטְבִּילוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִטְּבִילוֹת מַעֲלוֹת שְׁאָר הַטֻּמְאוֹת:","כְּלִי שֶׁנִּטְמָא בְּיוֹם טוֹב מַטְבִּילִין אוֹתוֹ בְּיוֹם טוֹב. נִטְמָא הַכְּלִי בְּמַשְׁקִין טְמֵאִין שֶׁהֵן וְלַד הַטֻּמְאָה מֵעֶרֶב יוֹם טוֹב מַטְבִּילִין אוֹתוֹ בְּיוֹם טוֹב לְפִי שֶׁהוּא טָהוֹר מִן הַתּוֹרָה כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. וּמַדְלִין בִּדְלִי טָמֵא וְהוּא טָהוֹר מֵאֵלָיו. נִדָּה שֶׁאֵין לָהּ בְּגָדִים לְהַחֲלִיף מַעֲרֶמֶת וְטוֹבֶלֶת בִּבְגָדֶיהָ:","דְּבָרִים רַבִּים אָסְרוּ בְּיוֹם טוֹב מִשּׁוּם גְּזֵרַת מִקָּח וּמִמְכָּר. כֵּיצַד. אֵין פּוֹסְקִים דָּמִים לְכַתְּחִלָּה עַל הַבְּהֵמָה בְּיוֹם טוֹב אֶלָּא מֵבִיא שְׁתֵּי בְּהֵמוֹת שָׁווֹת זוֹ לָזוֹ וְשׁוֹחֲטִין אַחַת מֵהֶן וּמְחַלְּקִין בֵּינֵיהֶן וּלְמָחָר יוֹדְעִין כַּמָּה דְּמֵי הַשְּׁנִיָּה וְכָל אֶחָד וְאֶחָד נוֹתֵן דְּמֵי חֶלְקוֹ. כְּשֶׁהֵן מְחַלְּקִין בֵּינֵיהֶן לֹא יֹאמַר זֶה אֲנִי בְּסֶלַע וְאַתָּה בִּשְׁנַיִם שֶׁאֵין מַזְכִּירִין שׁוּם דָּמִים אֶלָּא זֶה נוֹטֵל שְׁלִישׁ וְזֶה רְבִיעַ:","כְּשֶׁהֵן מְחַלְּקִין לֹא יִשְׁקְלוּ בְּמֹאזְנַיִם שֶׁאֵין מַשְׁגִּיחִין בְּכַף מֹאזְנַיִם כָּל עִקָּר. אֲפִלּוּ לִתֵּן בּוֹ בָּשָׂר לְשָׁמְרוֹ מִן הָעַכְבָּרִים אָסוּר אִם הָיוּ הַמֹּאזְנַיִם תְּלוּיִין מִפְּנֵי שֶׁנִּרְאֶה כְּשׁוֹקֵל בְּכַף מֹאזְנַיִם. וְטַבָּח אֻמָּן אָסוּר לִשְׁקל בְּיָדוֹ. וְאָסוּר לִשְׁקל בִּכְלִי מָלֵא מַיִם. וְאֵין מְטִילִין חַלָּשִׁים עַל הַמָּנוֹת. אֲבָל מְטִילִין חַלָּשִׁים עַל בְּשַׂר הַקָּדָשִׁים בְּיוֹם טוֹב כְּדֵי לְחַבֵּב אֶת הַמִּצְוָה:","לֹא יֹאמַר אָדָם לַטַּבָּח תֵּן לִי בְּדִינָר בָּשָׂר אֶלָּא תֵּן לִי חֵלֶק אוֹ חֲצִי חֵלֶק וּלְמָחָר עוֹשִׂין חֶשְׁבּוֹן עַל שָׁוְיוֹ. וְכֵן לֹא יִקַּח מִבַּעַל הַחֲנוּת בְּמִדָּה אוֹ בְּמִשְׁקָל אֶלָּא כֵּיצַד הוּא עוֹשֶׂה. אוֹמֵר לַחֶנְוָנִי מַלֵּא לִי כְּלִי זֶה וּלְמָחָר נוֹתֵן לוֹ שָׁוְיוֹ. וַאֲפִלּוּ הָיָה כְּלִי הַמְיֻחָד לְמִדָּה יְמַלְּאֶנּוּ וְהוּא שֶׁלֹּא יַזְכִּיר לוֹ שֵׁם מִדָּה:","הַנַּחְתּוֹם מוֹדֵד תַּבְלִין וְנוֹתֵן לַקְּדֵרָה בִּשְׁבִיל שֶׁלֹּא יַפְסִיד תַּבְשִׁילוֹ. אֲבָל הָאִשָּׁה לֹא תָּמֹד קֶמַח לְעִסָּה. וְכֵן לֹא יָמֹד אָדָם שְׂעוֹרִים לִתֵּן לִפְנֵי בְּהֶמְתּוֹ אֶלָּא מְשַׁעֵר וְנוֹתֵן לָהּ:","וּמֻתָּר לִקַּח מִן הַחֶנְוָנִי בֵּיצִים וֶאֱגוֹזִים בְּמִנְיָן. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן וּבִלְבַד שֶׁלֹּא יַזְכִּיר לוֹ שׁוּם דָּמִים וְלֹא סְכוּם מִנְיָן. כֵּיצַד סְכוּם הַמִּנְיָן. הֲרֵי שֶׁהָיָה נוֹשֶׁה בּוֹ עֲשָׂרָה רִמּוֹנִים אוֹ עֲשָׂרָה אֱגוֹזִים לֹא יֹאמַר לוֹ בְּיוֹם טוֹב תֵּן לִי עֲשָׂרָה כְּדֵי שֶׁיִּהְיֶה לְךָ עֶשְׂרִים אֶצְלִי אֶלָּא לוֹקֵחַ סְתָם וּלְמָחָר עוֹשֶׂה חֶשְׁבּוֹן:","הוֹלֵךְ אָדָם אֵצֶל חֶנְוָנִי אוֹ רוֹעֶה הָרָגִיל אֶצְלוֹ אוֹ אֵצֶל הַפַּטָּם הָרָגִיל אֶצְלוֹ וְלוֹקֵחַ מִמֶּנּוּ בְּהֵמוֹת וְעוֹפוֹת וְכָל מַה שֶּׁיִּרְצֶה וְהוּא שֶׁלֹּא יַזְכִּיר לוֹ שׁוּם דָּמִים וְלֹא סְכוּם מִנְיָן:","הַלְוָאַת יוֹם טוֹב תּוֹבְעִין אוֹתָהּ בְּדִין שֶׁאִם תֹּאמַר לֹא נִתְּנָה לְהִתָּבַע אֵינוֹ נוֹתֵן לוֹ כְּלוּם וְנִמְצָא נִמְנָע מִשִּׂמְחַת יוֹם טוֹב:","אַף עַל פִּי שֶׁאֵין מַגְבִּיהִין תְּרוּמָה וּמַעַשְׂרוֹת בְּיוֹם טוֹב אִם הָיוּ לוֹ תְּרוּמוֹת וּמַעַשְׂרוֹת שֶׁהִגְבִּיהָן מֵאֶמֶשׁ הֲרֵי זֶה מוֹלִיכָן לַכֹּהֵן בְּיוֹם טוֹב. וְאֵין צָרִיךְ לוֹמַר חַלָּה וּזְרוֹעַ וּלְחָיַיִם וְקֵיבָה שֶׁמּוֹלִיכָן לַכֹּהֵן בְּיוֹם טוֹב. וְגַּבָּאֵי צְדָקָה גּוֹבִין מִן הַחֲצֵרוֹת בְּיוֹם טוֹב. וְלֹא יִהְיוּ מַכְרִיזִין כְּדֶרֶךְ שֶׁמַּכְרִיזִין בְּחל. אֶלָּא גּוֹבִין בְּצִנְעָה וְנוֹתְנִין לְתוֹךְ חֵיקָן וּמְחַלְּקִין לְכָל שְׁכוּנָה וּשְׁכוּנָה בִּפְנֵי עַצְמָהּ:"],"Mishneh Torah, Ritual Slaughter 13":["הַלוֹקֵחַ אֵם עַל הַבָּנִים וּשִׁחָטָהּ. הַבָּשָׂר מֻתָּר בַּאֲכִילָה וְלוֹקֶה עַל שְׁחִיטַת הָאֵם שֶׁנֶּאֱמַר (דברים כב ו) \"לֹא תִקַּח הָאֵם עַל הַבָּנִים\". וְכֵן אִם מֵתָה קֹדֶם שֶׁיְּשַׁלְּחֶנָּה לוֹקֶה. וְאִם שִׁלְּחָהּ אַחַר שֶׁלְּקָחָהּ פָּטוּר:","וְכֵן כָּל מִצְוַת לֹא תַּעֲשֶׂה שֶׁנִּתְּקָה לַעֲשֵׂה חַיָּב לְקַיֵּם עֲשֵׂה שֶׁבָּהּ. וְאִם לֹא קִיְּמוֹ לוֹקֶה:","בָּא אֶחָד וְחָטַף הָאֵם מִיָּדוֹ וְשִׁלְּחָהּ אוֹ שֶׁבָּרְחָה מִתַּחַת יָדוֹ שֶׁלֹּא מִדַּעְתּוֹ לוֹקֶה שֶׁנֶּאֱמַר (דברים כב ז) \"שַׁלֵּחַ תְּשַׁלַּח\" עַד שֶׁיְּשַׁלֵּחַ מֵעַצְמוֹ וַהֲרֵי לֹא קִיֵּם עֲשֵׂה שֶׁבָּהּ:","נָטַל אֵם עַל הַבָּנִים וְקִצֵּץ אֲגַפֶּיהָ כְּדֵי שֶׁלֹּא תָּעוּף וְשִׁלְּחָהּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וּמַשְׁהֶה אוֹתָהּ אֶצְלוֹ עַד שֶׁיִּגְדְּלוּ כְּנָפֶיהָ וּמְשַׁלְּחָהּ. וְאִם מֵתָה קֹדֶם לָזֶה אוֹ בָּרְחָה וְאָבְדָה לוֹקֶה שֶׁהֲרֵי לֹא קִיֵּם עֲשֵׂה שֶׁבָּהּ:","וְכֵיצַד מְשַׁלֵּחַ הָאֵם. אוֹחֵז בִּכְנָפֶיהָ וּמַפְרִיחָהּ. שִׁלְּחָהּ וְחָזְרָה וְשִׁלְּחָהּ וְחָזְרָה אֲפִלּוּ אַרְבַּע וְחָמֵשׁ פְּעָמִים חַיָּב לְשַׁלֵּחַ שֶׁנֶּאֱמַר (דברים כב ז) \"שַׁלֵּחַ תְּשַׁלַּח\":","הָאוֹמֵר הֲרֵינִי נוֹטֵל אֶת הָאֵם וּמְשַׁלֵּחַ אֶת הַבָּנִים חַיָּב לְשַׁלֵּחַ אֶת הָאֵם שֶׁנֶּאֱמַר (דברים כב ז) \"שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם\":","לָקַח אֶת הַבָּנִים וְהֶחֱזִירָן לַקֵּן וְאַחַר כָּךְ חָזְרָה הָאֵם עֲלֵיהֶן פָּטוּר מִלְּשַׁלֵּחַ. שִׁלֵּחַ אֶת הָאֵם וְחָזַר וְצָד אוֹתָהּ הֲרֵי זֶה מֻתָּר. לֹא אָסְרָה תּוֹרָה אֶלָּא לָצוּד אוֹתָהּ וְהִיא אֵינָהּ יְכוֹלָה לִפְרֹחַ בִּשְׁבִיל הַבָּנִים שֶׁהִיא מְרַחֶפֶת עֲלֵיהֶן שֶׁלֹּא יִלָּקְחוּ שֶׁנֶּאֱמַר (דברים כב ו) \"וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים\". אֲבָל אִם הוֹצִיאָהּ מִתַּחַת יָדוֹ וְחָזַר וְצָד אוֹתָהּ מֻתָּר:","שִׁלּוּחַ הָאֵם אֵינוֹ נוֹהֵג אֶלָּא בְּעוֹף טָהוֹר שֶׁאֵינוֹ מְזֻמָּן כְּגוֹן יוֹנֵי שׁוֹבָךְ וַעֲלִיָּה וְעוֹפוֹת שֶׁקִּנְּנוּ בַּפַּרְדֵּס שֶׁנֶּאֱמַר (דברים כב ו) \"כִּי יִקָּרֵא\". אֲבָל הַמְזֻמָּן כְּגוֹן אֲוָזִין וְתַרְנְגוֹלִין וְיוֹנִים שֶׁקִּנְּנוּ בַּבַּיִת אֵינוֹ חַיָּב לְשַׁלֵּחַ:","הָיוּ הָאֶפְרוֹחִין מַפְרִיחִין שֶׁאֵינָן צְרִיכִין לְאִמָּן אוֹ בֵּיצִים מוּזָרוֹת אֵינוֹ חַיָּב לְשַׁלֵּחַ. הָיוּ אֶפְרוֹחִין טְרֵפוֹת הֲרֵי אֵלּוּ כְּבֵיצִים מוּזָרוֹת וּפָטוּר מִלְּשַׁלֵּחַ:","זָכָר שֶׁמְּצָאוֹ רוֹבֵץ עַל הַקֵּן פָּטוּר מִלְּשַׁלֵּחַ. עוֹף טָמֵא רוֹבֵץ עַל בֵּיצֵי עוֹף טָהוֹר אוֹ עוֹף טָהוֹר רוֹבֵץ עַל בֵּיצֵי עוֹף טָמֵא פָּטוּר מִלְּשַׁלֵּחַ:","הָיְתָה רוֹבֶצֶת עַל בֵּיצִים שֶׁאֵינָן מִינָהּ וְהֵן טְהוֹרִין הֲרֵי זֶה מְשַׁלֵּחַ. וְאִם לֹא שִׁלֵּחַ אֵינוֹ לוֹקֶה. הָיְתָה הָאֵם טְרֵפָה חַיָּב לְשַׁלְּחָהּ:","שָׁחַט מִקְצָת סִימָנִין בְּתוֹךְ הַקֵּן קֹדֶם שֶׁיִּקָּחֶנָּה חַיָּב לְשַׁלֵּחַ וְאִם לֹא שִׁלֵּחַ אֵינוֹ לוֹקֶה:","הָיְתָה מְעוֹפֶפֶת. אִם כְּנָפֶיהָ נוֹגְעוֹת בַּקֵּן חַיָּב לְשַׁלֵּחַ. וְאִם לָאו פָּטוּר מִלְּשַׁלֵּחַ. הָיְתָה מַטְלִית אוֹ כְּנָפַיִם חוֹצְצוֹת בֵּין כְּנָפֶיהָ וּבֵין הַקֵּן הֲרֵי זֶה מְשַׁלֵּחַ. וְאִם לֹא שִׁלֵּחַ אֵינוֹ לוֹקֶה:","הָיוּ שְׁנֵי סִדְרֵי בֵּיצִים וּכְנָפֶיהָ נוֹגְעוֹת בַּסֵּדֶר הָעֶלְיוֹן. אוֹ שֶׁהָיְתָה רוֹבֶצֶת עַל בֵּיצִים מוּזָרוֹת וְתַחְתֵּיהֶן בֵּיצִים יָפוֹת. אוֹ שֶׁהָיְתָה אֵם עַל גַּבֵּי אֵם. אוֹ שֶׁהָיָה הַזָּכָר עַל הַקֵּן וְהָאֵם עַל הַזָּכָר. הֲרֵי זֶה לֹא יִקַּח. וְאִם לָקַח יְשַׁלֵּחַ וְאִם לֹא שִׁלֵּחַ אֵינוֹ לוֹקֶה:","הָיְתָה יוֹשֶׁבֶת בֵּין הָאֶפְרוֹחִים אוֹ בֵּין הַבֵּיצִים וְאֵינָהּ נוֹגַעַת בָּהֶן פָּטוּר מִלְּשַׁלֵּחַ. וְכֵן אִם הָיְתָה בְּצַד הַקֵּן וּכְנָפֶיהָ נוֹגְעוֹת בַּקֵּן מִצִּדּוֹ פָּטוּר מִלְּשַׁלֵּחַ:","הָיְתָה עַל שְׁנֵי בַּדֵּי אִילָן וְהַקֵּן בֵּינֵיהֶן רוֹאִין כָּל שֶׁאִלּוּ יִנָּטְלוּ הַבַּדִּין תִּפּל עַל הַקֵּן חַיָּב לְשַׁלֵּחַ:","הָיְתָה רוֹבֶצֶת עַל אֶפְרוֹחַ אֶחָד אוֹ עַל בֵּיצָה אַחַת חַיָּב לְשַׁלֵּחַ. הַמּוֹצֵא קֵן עַל פְּנֵי הַמַּיִם אוֹ עַל גַּבֵּי בַּעֲלֵי חַיִּים חַיָּב לְשַׁלֵּחַ. לֹא נֶאֱמַר (דברים כב ו) \"אֶפְרוֹחִים אוֹ בֵּיצִים\" וְלֹא נֶאֱמַר (דברים כב ו) \"בְּכָל עֵץ אוֹ עַל הָאָרֶץ\" אֶלָּא שֶׁדִּבֵּר הַכָּתוּב בְּהוֹוֶה:","אָסוּר לִזְכּוֹת בַּבֵּיצִים כָּל זְמַן שֶׁהָאֵם רוֹבֶצֶת עֲלֵיהֶן. לְפִיכָךְ אֲפִלּוּ הָיְתָה רוֹבֶצֶת עַל הַבֵּיצִים אוֹ עַל הָאֶפְרוֹחִים בַּעֲלִיָּתוֹ וּשׁוֹבָכוֹ אֵינָן מְזֻמָּנִין. וְלֹא קָנָה לוֹ חֲצֵרוֹ. כְּשֵׁם שֶׁאֵינוֹ יָכוֹל לִזְכּוֹת בָּהֶן לַאֲחֵרִים כָּךְ לֹא תִּזְכֶּה לוֹ חֲצֵרוֹ בָּהֶן. וּלְפִיכָךְ חַיָּב לְשַׁלֵּחַ:","אָסוּר לִטּל אֵם עַל הַבָּנִים וַאֲפִלּוּ לְטַהֵר בָּהֶן אֶת הַמְצֹרָע שֶׁהִיא מִצְוָה. וְאִם לָקַח חַיָּב לְשַׁלֵּחַ. וְאִם לֹא שִׁלֵּחַ לוֹקֶה. שֶׁאֵין עֲשֵׂה דּוֹחֶה לֹא תַעֲשֶׂה וַעֲשֵׂה. (וַעֲשֵׂה) וְלֹא עֲשֵׂה דּוֹחֶה עֲשֵׂה:","הַמַּקְדִּישׁ עוֹף לְבֶדֶק הַבַּיִת וּפָרַח מִיָּדוֹ וַהֲרֵי הוּא מַכִּירוֹ וּמְצָאוֹ רוֹבֵץ עַל הָאֶפְרוֹחִים אוֹ עַל הַבֵּיצִים לוֹקֵחַ הַכּל וּמְבִיאָן לִידֵי גִּזְבָּר. שֶׁאֵין שִׁלּוּחַ הָאֵם נוֹהֵג בְּמֻקְדָּשִׁין שֶׁנֶּאֱמַר (דברים כב ז) \"וְאֶת הַבָּנִים תִּקַּח לָךְ\" וְאֵלּוּ אֵינָן שֶׁלְּךָ:","עוֹף שֶׁהָרַג אֶת הַנֶּפֶשׁ פָּטוּר מִלְּשַׁלֵּחַ מִפְּנֵי שֶׁהוּא מְצֻוֶּה לַהֲבִיאוֹ לְבֵית דִּין לָדוּן אוֹתוֹ:"],"Mishneh Torah, Robbery and Lost Property 11":["הֲשָׁבַת אֲבֵדָה לְיִשְׂרָאֵל מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (דברים כב א) \"הָשֵׁב תְּשִׁיבֵם\". וְהָרוֹאֶה אֲבֵדַת יִשְׂרָאֵל וְנִתְעַלֵּם מִמֶּנָּה וֶהֱנִיחָהּ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כב א) \"לֹא תִרְאֶה אֶת שׁוֹר אָחִיךָ\" (דברים כב א) \"וְהִתְעַלַּמְתָּ מֵהֶם\". וּבִטֵּל מִצְוַת עֲשֵׂה. וְאִם הֱשִׁיבָהּ קִיֵּם מִצְוַת עֲשֵׂה:","לָקַח אֶת הָאֲבֵדָה וְלֹא הֱשִׁיבָהּ בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל שְׁנֵי לָאוִין עַל (דברים כב ג) \"לֹא תוּכַל לְהִתְעַלֵּם\" וְעַל (ויקרא יט יג) \"לֹא תִגְזל\". אֲפִלּוּ הָיָה בַּעַל הָאֲבֵדָה רָשָׁע וְאוֹכֵל נְבֵלָה לְתֵאָבוֹן וְכַיּוֹצֵא בּוֹ מִצְוָה לְהָשִׁיב לוֹ אֲבֵדָתוֹ. אֲבָל אוֹכֵל נְבֵלָה לְהַכְעִיס הֲרֵי הוּא אֶפִּיקוֹרוֹס וְהָאֶפִּיקוֹרוֹסִים וְעוֹבְדֵי עַכּוּ\"ם וּמְחַלְּלֵי שַׁבָּת בְּפַרְהֶסְיָא אָסוּר לְהַחְזִיר לָהֶן אֲבֵדָה כְּעַכּוּ\"ם:","אֲבֵדַת עוֹבֵד עַכּוּ\"ם מֻתֶּרֶת שֶׁנֶּאֱמַר (דברים כב ג) \"אֲבֵדַת אָחִיךָ\". וְהַמַּחֲזִירָהּ הֲרֵי זֶה עוֹבֵר עֲבֵרָה מִפְּנֵי שֶׁהוּא מַחֲזִיק יַד רִשְׁעֵי עוֹלָם. וְאִם הֶחֱזִירָהּ לְקַדֵּשׁ אֶת הַשֵּׁם כְּדֵי שֶׁיְּפָאֲרוּ אֶת יִשְׂרָאֵל וְיֵדְעוּ שֶׁהֵם בַּעֲלֵי אֱמוּנָה הֲרֵי זֶה מְשֻׁבָּח. וּבְמָקוֹם שֶׁיֵּשׁ חִלּוּל הַשֵּׁם אֲבֵדָתוֹ אֲסוּרָה וְחַיָּב לְהַחְזִירָהּ. וּבְכָל מָקוֹם מַכְנִיסִין כְּלֵיהֶם מִפְּנֵי הַגַּנָּבִים כִּכְלֵי יִשְׂרָאֵל מִפְּנֵי דַּרְכֵי שָׁלוֹם:","טָעוּת הָעַכּוּ\"ם כַּאֲבֵדָתוֹ וּמֻתֶּרֶת. וְהוּא שֶׁטָּעָה מֵעַצְמוֹ אֲבָל לְהַטְעוֹתוֹ אָסוּר:","כֵּיצַד. כְּגוֹן שֶׁעָשָׂה הָעַכּוּ\"ם חֶשְׁבּוֹן וְטָעָה. וְצָרִיךְ שֶׁיֹּאמַר לוֹ יִשְׂרָאֵל רְאֵה שֶׁעַל חֶשְׁבּוֹנְךָ אֲנִי סוֹמֵךְ וְאֵינִי יוֹדֵעַ אֶלָּא מַה שֶּׁאַתָּה אוֹמֵר אֲנִי נוֹתֵן לְךָ כְּגוֹן זֶה מֻתָּר. אֲבָל אִם לֹא אָמַר לוֹ כֵּן אָסוּר שֶׁמָּא יִתְכַּוֵּן הַגּוֹי לְבָדְקוֹ וְנִמְצָא שֵׁם שָׁמַיִם מִתְחַלֵּל:","עִיר שֶׁיִּשְׂרְאֵלִים וְעַכּוּ\"ם דָּרִין בָּהּ וּמֶחֱצָה עַכּוּ\"ם וּמֶחֱצָה יִשְׂרָאֵל וּמָצָא בָּהּ אֲבֵדָה נוֹטֵל וּמַכְרִיז. וְאִם בָּא יִשְׂרָאֵל וְנָתַן סִימָנֶיהָ חַיָּב לְהַחְזִיר:","הָיָה רֹב הָעִיר עַכּוּ\"ם אִם מָצָא בְּמָקוֹם מִן הָעִיר שֶׁרֹב הַמְּצוּיִים שָׁם יִשְׂרָאֵל חַיָּב לְהַכְרִיז. אֲבָל אִם מָצָא בִּסְרַטְיָא וּפְלַטְיָא גְּדוֹלָה בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת שֶׁהָעַכּוּ\"ם מְצוּיִין שָׁם תָּמִיד וּבְכָל מָקוֹם שֶׁהָרַבִּים מְצוּיִין שָׁם הֲרֵי הַמְּצִיאָה שֶׁלּוֹ. וַאֲפִלּוּ בָּא יִשְׂרָאֵל וְנָתַן סִימָנֶיהָ. שֶׁהֲרֵי נִתְיָאֵשׁ מִמֶּנָּה כְּשֶׁנָּפְלָה מִפְּנֵי שֶׁהוּא אוֹמֵר עַכּוּ\"ם מְצָאָהּ אַף עַל פִּי שֶׁהִיא שֶׁלּוֹ. הָרוֹצֶה לֵילֵךְ בְּדֶרֶךְ הַטּוֹב וְהַיָּשָׁר וְעוֹשֶׂה לְפָנִים מִשּׁוּרַת הַדִּין מַחְזִיר אֶת הָאֲבֵדָה לְיִשְׂרָאֵל כְּשֶׁיִּתֵּן אֶת סִימָנֶיהָ:","מָצָא בְּעִיר זוֹ שֶׁרֻבָּהּ עַכּוּ\"ם חָבִית שֶׁל יַיִן יֵינָהּ אָסוּר בַּהֲנָאָה וְקַנְקַנָּהּ מֻתָּר מִשּׁוּם אֲבֵדָה. וְאִם בָּא יִשְׂרָאֵל וְנָתַן סִימָנֶיהָ מֻתָּר בִּשְׁתִיָּה לְזֶה יִשְׂרָאֵל שֶׁמְּצָאָהּ:","עוֹף שֶׁחָטַף בָּשָׂר וְהִשְׁלִיכוֹ בְּחָצֵר אַחֶרֶת אַף עַל פִּי שֶׁרֹב הָעִיר יִשְׂרָאֵל הֲרֵי זֶה מֻתָּר מִשּׁוּם אֲבֵדָה שֶׁהֲרֵי נִתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנּוּ:","הַמּוֹצֵא אֲבֵדָה בְּזוּטוֹ שֶׁל יָם וּבִשְׁלוּלִיתוֹ שֶׁל נָהָר שֶׁאֵינוֹ פּוֹסֵק אַף עַל פִּי שֶׁיֵּשׁ בָּהּ סִימָן הֲרֵי זוֹ שֶׁל מוֹצְאָהּ שֶׁנֶּאֱמַר (דברים כב ג) \"אֲשֶׁר תֹּאבַד מִמֶּנּוּ וּמְצָאתָהּ\". מִי שֶׁאֲבוּדָה מִמֶּנּוּ וּמְצוּיָה הִיא אֵצֶל כָּל אָדָם. יָצָאת זוֹ שֶׁאֲבוּדָה מִמֶּנּוּ וּמִכָּל אָדָם שֶׁזֶּה וַדַּאי נִתְיָאֵשׁ מִמֶּנָּה:","הַמְאַבֵּד מָמוֹנוֹ לְדַעַת אֵין נִזְקָקִין לוֹ. כֵּיצַד. הִנִּיחַ פָּרָתוֹ בְּרֶפֶת שֶׁאֵין לָהּ דֶּלֶת וְלֹא קְשָׁרָהּ וְהָלַךְ לוֹ. הִשְׁלִיךְ כִּיסוֹ בִּרְשׁוּת הָרַבִּים וְהָלַךְ לוֹ וְכָל כַּיּוֹצֵא בָּזֶה. הֲרֵי זֶה אִבֵּד מָמוֹנוֹ לְדַעְתּוֹ. וְאַף עַל פִּי שֶׁאָסוּר לְרוֹאֶה דָּבָר זֶה לִטּל לְעַצְמוֹ אֵינוֹ זָקוּק לְהַחְזִיר שֶׁנֶּאֱמַר (דברים כב ג) \"אֲשֶׁר תֹּאבַד\" פְּרָט לִמְאַבֵּד לְדַעְתּוֹ:","אֲבֵדָה שֶׁאֵין בָּהּ שְׁוֵה פְּרוּטָה אֵינוֹ חַיָּב לְהִטַּפֵּל וְלֹא לְהַחְזִירָהּ:","מָצָא שַׂק אוֹ קֻפָּה אִם הָיָה חָכָם אוֹ זָקֵן מְכֻבָּד שֶׁאֵין דַּרְכּוֹ לִטּל כֵּלִים אֵלּוּ בְּיָדוֹ אֵינוֹ חַיָּב לְהִטַּפֵּל בָּהֶן וְאוֹמֵד אֶת דַּעְתּוֹ אִלּוּ הָיוּ שֶׁלּוֹ אִם הָיָה מַחֲזִירָן לְעַצְמוֹ כָּךְ חַיָּב לְהַחְזִיר שֶׁל חֲבֵרוֹ. וְאִם לֹא הָיָה מוֹחֵל עַל כְּבוֹדוֹ אֲפִלּוּ הָיָה שֶׁלּוֹ כָּךְ בְּשֶׁל חֲבֵרוֹ אֵינוֹ חַיָּב לְהַחְזִיר. הָיָה דַּרְכּוֹ לְהַחְזִיר כֵּלִים כָּאֵלּוּ בַּשָּׂדֶה וְאֵין דַּרְכּוֹ לְהַחְזִירָן בָּעִיר וּמְצָאָן בָּעִיר אֵינוֹ חַיָּב לְהַחְזִיר. מְצָאָן בַּשָּׂדֶה חַיָּב לְהַחְזִירָן עַד שֶׁיַּגִּיעוּ לִרְשׁוּת הַבְּעָלִים. וְאַף עַל פִּי שֶׁהֲרֵי נִכְנַס בָּהֶן לָעִיר וְאֵין דַּרְכּוֹ בְּכָךְ:","וְכֵן אִם מָצָא בְּהֵמָה וְהִכִּישָׁהּ נִתְחַיֵּב לְהִטַּפֵּל בָּהּ וּלְהַחֲזִירָהּ אַף עַל פִּי שֶׁאֵינָהּ לְפִי כְּבוֹדוֹ שֶׁהֲרֵי הִתְחִיל בַּמִּצְוָה. הֶחֱזִירָהּ וּבָרְחָה אֲפִלּוּ מֵאָה פְּעָמִים חַיָּב לְהַחְזִיר שֶׁנֶּאֱמַר (דברים כב א) \"הָשֵׁב תְּשִׁיבֵם\" הָשֵׁב אֲפִלּוּ מֵאָה פְּעָמִים מַשְׁמָעוֹ. לְעוֹלָם הוּא חַיָּב לְהִטַּפֵּל בָּהּ עַד שֶׁיַּחֲזִירֶנָּהּ לִרְשׁוּת בְּעָלֶיהָ לְמָקוֹם הַמִּשְׁתַּמֵּר. אֲבָל אִם הֶחֱזִירָהּ לְמָקוֹם שֶׁאֵין מִשְׁתַּמֵּר כְּגוֹן גִּנָּה וְחֻרְבָּה וְאָבְדָה מִשָּׁם חַיָּב בְּאַחֲרָיוּתָהּ:","הֶחְזִיר אֶת הָאֲבֵדָה בְּשַׁחֲרִית לְמָקוֹם שֶׁהַבְּעָלִים נִכְנָסִין וְיוֹצְאִין שָׁם בְּשַׁחֲרִית אֵינוֹ חַיָּב לְהִטַּפֵּל בָּהּ שֶׁהֲרֵי הַבְּעָלִים רוֹאִין אוֹתָהּ אַף עַל פִּי שֶׁהוּא מָקוֹם שֶׁאֵינוֹ מִשְׁתַּמֵּר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁאֵין בּוֹ רוּחַ חַיִּים. אֲבָל בְּבַעֲלֵי חַיִּים לְעוֹלָם חַיָּב לְהִטַּפֵּל בָּהּ עַד שֶׁיַּכְנִיסֶנָּה לִרְשׁוּת הַבְּעָלִים הַמִּשְׁתַּמֶּרֶת. וְאֵינוֹ צָרִיךְ דַּעַת בְּעָלִים:","רָאָה בְּהֵמָה שֶׁבָּרְחָה מִן הַדִּיר וְהֶחֱזִירָהּ לִמְקוֹמָהּ הֲרֵי זֶה קִיֵּם הַמִּצְוָה וְאֵינוֹ צָרִיךְ דַּעַת הַבְּעָלִים:","הַהוֹלֵךְ בְּדֶרֶךְ הַטּוֹב וְהַיָּשָׁר וְעוֹשֶׂה לִפְנִים מִשּׁוּרַת הַדִּין מַחְזִיר אֶת הָאֲבֵדָה בְּכָל מָקוֹם אַף עַל פִּי שֶׁאֵינָהּ לְפִי כְּבוֹדוֹ:","כֹּהֵן שֶׁרָאָה הָאֲבֵדָה בְּבֵית הַקְּבָרוֹת אֵינוֹ מִטַּמֵּא לְהַחְזִירָהּ שֶׁבְּעֵת שֶׁמְּקַיֵּם מִצְוַת עֲשֵׂה שֶׁל הֶשֵּׁב אֲבֵדָה מְבַטֵּל עֲשֵׂה שֶׁל (ויקרא כא ו) \"קְדשִׁים יִהְיוּ\" וְעוֹבֵר עַל לֹא תַּעֲשֶׂה שֶׁל (ויקרא כא ד) \"לֹא יִטַּמָּא בַּעַל בְּעַמָּיו\" וְאֵין עֲשֵׂה דּוֹחֶה אֶת לֹא תַּעֲשֶׂה וַעֲשֵׂה:","רָאָה אֶת הָאֲבֵדָה וְאָמַר לוֹ אָבִיו אַל תַּחְזִירֶנָּה יַחְזִיר וְלֹא יְקַבֵּל מִמֶּנּוּ. שֶׁאִם קִבֵּל מֵאָבִיו נִמְצָא בְּעֵת שֶׁקִּיֵּם מִצְוַת עֲשֵׂה שֶׁל (שמות כ יב) (דברים ה טז) \"כַּבֵּד אֶת אָבִיךָ\" בִּטֵּל עֲשֵׂה שֶׁל (דברים כב א) \"הָשֵׁב תְּשִׁיבֵם\" וְעָבַר עַל (דברים כב ג) \"לֹא תוּכַל לְהִתְעַלֵּם\":","הָרוֹאֶה מַיִם שׁוֹטְפִין וּבָאִין לְהַשְׁחִית בִּנְיַן חֲבֵרוֹ אוֹ שָׂדֵהוּ חַיָּב לִגְדֹּר בִּפְנֵיהֶם וּלְמָנְעָם שֶׁנֶּאֱמַר (דברים כב ג) \"לְכָל אֲבֵדַת אָחִיךָ\" לְרַבּוֹת אֲבֵדַת קַרְקָעוֹ:"],"Mishneh Torah, Robbery and Lost Property 6":["קוֹרוֹת וַאֲבָנִים וְעֵצִים וְכַיּוֹצֵא בָּהֶן שֶׁשְּׁטָפָם הַנָּהָר אִם נִתְיָאֲשׁוּ הַבְּעָלִים מֵהֶן הֲרֵי אֵלּוּ מֻתָּרִין וְהֵן שֶׁל מַצִּילָן. וְאִם אֵינוֹ יוֹדֵעַ אִם נִתְיָאֲשׁוּ אִם לֹא נִתְיָאֲשׁוּ חַיָּב לְהַחְזִיר. וְאֵין צָרִיךְ לוֹמַר אִם הָיוּ הַבְּעָלִים מְרַדְּפִין אַחֲרֵיהֶן:","לְפִיכָךְ הַמַּצִּיל מִן הַנָּהָר וּמִזּוּטוֹ שֶׁל יָם וּמִשְּׁלוּלִיתוֹ שֶׁל נָהָר וּמִן הָעַכּוּ\"ם וּמִן הַדְּלֵקָה וּמִן הָאֲרִי וּמִן הַדֹּב וּמִן הַנָּמֵר וּמִן הַבַּרְדְּלָס. אִם יָדַע בְּוַדַּאי שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים הֲרֵי אֵלּוּ שֶׁלּוֹ. וְאִם לֹא יָדַע יַחְזִיר:","הַמַּצִּיל מִיַּד לִסְטִים יִשְׂרָאֵל הֲרֵי אֵלּוּ שֶׁלּוֹ מִפְּנֵי שֶׁסְּתָם הַדָּבָר שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים. וְאִם יָדַע שֶׁלֹּא נִתְיָאֲשׁוּ חַיָּב לְהַחְזִיר. אֲבָל הַמַּצִּיל מִיַּד לִסְטִים עוֹבֵד כּוֹכָבִים אוֹ מוֹכֵס עַכּוּ\"ם חַיָּב לְהַחְזִיר שֶׁסְּתָם הַדָּבָר שֶׁלֹּא נִתְיָאֲשׁוּ הַבְּעָלִים. וְאִם יָדַע בְּוַדַּאי שֶׁנִּתְיָאֲשׁוּ הֲרֵי אֵלּוּ שֶׁלּוֹ. וּמִפְּנֵי מָה סְתָם לִסְטִים יִשְׂרָאֵל נִתְיָאֲשׁוּ הַבְּעָלִים וּסְתָם הָעַכּוּ\"ם לֹא נִתְיָאֲשׁוּ. מִפְּנֵי שֶׁהַבְּעָלִים יוֹדְעִים שֶׁהָעַכּוּ\"ם מַחֲזִירִין מִיַּד הַגַּזְלָן אַף עַל פִּי שֶׁאֵין שָׁם עֵדִים שֶׁגָּזַל אֶלָּא בִּרְאָיוֹת רְעוּעוֹת וּבְאֹמֶד הַדַּעַת:","שַׁחֲלַיִים הַצּוֹמְחִים בְּתוֹךְ הַפִּשְׁתָּן הַמְלַקְּטָן כְּשֶׁהֵן לַחִין אֵין בּוֹ מִשּׁוּם גֵּזֶל מִפְּנֵי שֶׁהֵן מַפְסִידִין הַפִּשְׁתָּן שֶׁל בַּעַל הַשָּׂדֶה. וְאִם יָבְשׁוּ אֲסוּרִין מִשּׁוּם גֵּזֶל שֶׁכְּבָר הִפְסִידוּ מַה שֶּׁהִפְסִידוּ. וְאִם הָיוּ עַל הַגְּבוּל אֲסוּרִין אֲפִלּוּ כְּשֶׁהֵן לַחִין:","כְּבָר בֵּאַרְנוּ בְּנִזְקֵי מָמוֹן שֶׁהַמּוֹצִיא תִּבְנוֹ וְקַשּׁוֹ לִרְשׁוּת הָרַבִּים אֵין בָּהֶם מִשּׁוּם גֵּזֶל. אֲבָל הַמּוֹצִיא הַגָּלָל לִרְשׁוּת הָרַבִּים בֵּין בִּשְׁעַת הוֹצָאַת זְבָלִים בֵּין שֶׁלֹּא בִּשְׁעַת הוֹצָאַת זְבָלִים חַיָּבִין עֲלֵיהֶם מִשּׁוּם גֵּזֶל:","מִי שֶׁנִּתְחַלְּפוּ לוֹ כֵּלָיו בְּכֵלִים אֲחֵרִים בְּבֵית הָאָבֶל אוֹ בְּבֵית הַמִּשְׁתֶּה הֲרֵי זֶה לֹא יִשְׁתַּמֵּשׁ בָּהֶן עַד שֶׁיָּבוֹא הַלָּה וְיַחְזִיר וְיִטּל אֶת שֶׁלּוֹ. נִתְחַלְּפוּ לוֹ בְּבֵית הָאֻמָּן אִם אִשְׁתּוֹ וּבָנָיו שֶׁל אֻמָּן נָתְנוּ לוֹ אוֹ שֶׁנָּתַן לוֹ הָאֻמָּן וְאָמַר לוֹ טֹל כֵּלֶיךָ הֲרֵי זֶה לֹא יִשְׁתַּמֵּשׁ בָּהֶן עַד שֶׁיָּבוֹא הַלָּה וְיַחְזִיר וְיִטּל אֶת שֶׁלּוֹ. אָמַר לוֹ הָאֻמָּן טֹל כְּלִי זֶה הֲרֵי זֶה יִשְׁתַּמֵּשׁ בּוֹ עַד שֶׁיָּבוֹא הַלָּה וְיַחְזִיר וְיִטּל אֶת שֶׁלּוֹ שֶׁמָּא כֵּלָיו שֶׁל אֻמָּן הוּא אוֹ בַּעַל הַכְּלִי צִוָּה אֶת הָאֻמָּן לְמָכְרוֹ לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","דְּבָרִים הַרְבֵּה אָסְרוּ חֲכָמִים מִשּׁוּם גֵּזֶל וְהָעוֹבֵר עֲלֵיהֶן הֲרֵי זֶה גַּזְלָן מִדִּבְרֵיהֶם. כְּגוֹן מַפְרִיחֵי יוֹנִים וְהַמְשַׂחֲקִים בְּקֻבִּיָּא. מַפְרִיחֵי יוֹנִים כֵּיצַד. לֹא יַפְרִיחַ אָדָם בְּתוֹךְ הַיִּשּׁוּב שֶׁהֲרֵי לוֹקֵחַ מָמוֹן אֲחֵרִים שֶׁלֹּא כַּדִּין מִפְּנֵי שֶׁמְּשַׁלֵּחַ זָכָר וְיָבִיא נְקֵבָה מִשּׁוֹבָךְ אַחֵר אוֹ נְקֵבָה וְתָבִיא זָכָר. וְלֹא יוֹנִים בִּלְבַד אֶלָּא כָּל הָעוֹשֶׂה כָּזֶה בִּשְׁאָר עוֹפוֹת אוֹ חַיָּה וּבְהֵמָה הֲרֵי זֶה גַּזְלָן מִדִּבְרֵיהֶם:","וְכֵן אָסְרוּ חֲכָמִים לָצוּד יוֹנִים בְּתוֹךְ הַיִּשּׁוּב מִפְּנֵי שֶׁהֵן שֶׁל אֲחֵרִים. וְאֵין פּוֹרְשִׂין נִישׁוֹבִין לְיוֹנִים אֶלָּא אִם כֵּן הִרְחִיק מִן הַיִּשּׁוּב אַרְבָּעָה מִילִין. וְאִם הָיָה יִשּׁוּב כְּרָמִים אֲפִלּוּ מֵאָה מִיל לֹא יִפְרשֹׁ שֶׁהַיּוֹנִים שֶׁל בַּעֲלֵי כְּרָמִים הֵם. וְכֵן לֹא יִפְרשֹׁ בְּתוֹךְ הַשּׁוֹבָכִין אַף עַל פִּי שֶׁהֵן שֶׁלּוֹ אוֹ שֶׁל עַכּוּ\"ם אוֹ שֶׁל הֶפְקֵר וְאַף עַל פִּי שֶׁהִרְחִיק מִן הַיִּשּׁוּב מֵאָה מִיל מִפְּנֵי שֶׁהַיּוֹנִים בָּאוֹת לְיִשּׁוּב הַשּׁוֹבָכִין:","מַרְחִיקִין אֶת הַשּׁוֹבָךְ מִן הָעִיר חֲמִשִּׁים אַמָּה. וְלֹא יַעֲשֶׂה אָדָם שׁוֹבָךְ בְּתוֹךְ שָׂדֵהוּ אֶלָּא אִם כֵּן יֵשׁ לוֹ חֲמִשִּׁים אַמָּה לְכָל רוּחַ כְּדֵי שֶׁלֹּא יִמָּשְׁכוּ הַגּוֹזָלוֹת וְיַפְסִידוּ בַּשָּׂדוֹת וְיֹאכְלוּ מִשֶּׁל אֲחֵרִים. וְאִם לְקָחוֹ מֵאַחֵר אֲפִלּוּ הָיָה בֵּינוֹ וּבֵין תְּחִלַּת שְׂדֵה חֲבֵרוֹ בֵּית רֹבַע בִּלְבַד הֲרֵי הוּא בְּחֶזְקָתוֹ וְאֵין מְחַיְּבִין אוֹתוֹ לְהַרְחִיק:","הַמְשַׂחֲקִין בְּקֻבִּיָּא כֵּיצַד. אֵלּוּ שֶׁמְּשַׂחֲקִין בְּעֵצִים אוֹ בִּצְרוֹרוֹת אוֹ בַּעֲצָמוֹת וְכַיּוֹצֵא בָּהֶן וְעוֹשִׂים תְּנַאי בֵּינֵיהֶם שֶׁכָּל הַנּוֹצֵחַ אֶת חֲבֵרוֹ בְּאוֹתוֹ שְׂחוֹק יִקַּח מִמֶּנּוּ כָּךְ וְכָךְ הֲרֵי זֶה גֵּזֶל מִדִּבְרֵיהֶם. אַף עַל פִּי שֶׁבִּרְצוֹן הַבְּעָלִים לָקַח הוֹאִיל וְלָקַח מָמוֹן חֲבֵרוֹ בְּחִנָּם דֶּרֶךְ שְׂחוֹק וְהִתּוּל הֲרֵי זֶה גּוֹזֵל. וְכֵן הַמְשַׂחֲקִים בִּבְהֵמָה אוֹ בְּחַיָּה אוֹ בְּעוֹפוֹת וְעוֹשִׂים תְּנַאי שֶׁכָּל שֶׁתְּנַצֵּחַ בְּהֶמְתּוֹ אוֹ תָּרוּץ יוֹתֵר יִקַּח מֵחֲבֵרוֹ כָּךְ וְכָךְ וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ הַכּל אָסוּר וְגֵזֶל מִדִּבְרֵיהֶם הוּא:","וְהַמְשַׂחֵק בְּקֻבִּיָּא עִם הָעַכּוּ\"ם אֵין בּוֹ אִסּוּר גֵּזֶל אֲבָל יֵשׁ בּוֹ אִסּוּר עוֹסֵק בִּדְבָרִים בְּטֵלִים שֶׁאֵין רָאוּי לְאָדָם שֶׁיַּעֲסֹק כָּל יָמָיו אֶלָּא בְּדִבְרֵי חָכְמָה וּבְיִשּׁוּבוֹ שֶׁל עוֹלָם:","מְצוּדוֹת חַיָּה וְעוֹפוֹת וְדָגִים שֶׁנָּפְלוּ מִינֵי הַחַיָּה לְתוֹךְ הַמְּצוּדָה וּבָא אַחֵר וּנְטָלָן הֲרֵי זֶה גֵּזֶל מִדִּבְרֵיהֶם מִפְּנֵי שֶׁעֲדַיִן לֹא הִגִּיעוּ לְיַד הַזּוֹכֶה בָּהֶן:","נָהָר הַמּוֹשֵׁךְ וּמַעְיָנוֹת הַנּוֹבְעִין הֲרֵי הֵן שֶׁל כָּל אָדָם. עָנִי הַמְנַקֵּף בְּרֹאשׁ הַזַּיִת זֵיתִים שֶׁל שִׁכְחָה וּבָא עָנִי אַחֵר וּנְטָלָן מֵעַל הָאָרֶץ הֲרֵי זֶה גֵּזֶל מִדִּבְרֵיהֶם. וְאִם הָיָה הֶעָנִי מְקַבֵּץ בְּיָדוֹ בְּרֹאשׁ הַזַּיִת וּמַשְׁלִיךְ לָאָרֶץ הֲרֵי זֶה גֵּזֶל גָּמוּר שֶׁהֲרֵי הִגִּיעוּ לְיַד הַזּוֹכֶה בָּהֶן:","הַדְּבוֹרִים אֵינָן בִּרְשׁוּתוֹ שֶׁל אָדָם כְּמוֹ תַּרְנְגוֹלִים וַאֲוָזִים וְאַף עַל פִּי כֵן יֵשׁ בָּהֶן קִנְיָן מִדִּבְרֵיהֶם. וְהַגּוֹזֵל נְחִיל דְּבוֹרִים אוֹ שֶׁמְּנָעוֹ מִבְּעָלָיו אִם בָּא לִרְשׁוּתוֹ הֲרֵי זֶה גֵּזֶל מִדִּבְרֵיהֶם. לְפִיכָךְ מִי שֶׁיָּצָא נְחִיל שֶׁל דְּבוֹרִים מֵרְשׁוּתוֹ וְשָׁכַן בִּרְשׁוּת חֲבֵרוֹ יֵשׁ לְבַעַל הַנְּחִיל לְהַלֵּךְ בְּתוֹךְ שְׂדֵה חֲבֵרוֹ עַד שֶׁיִּטּל אֶת נְחִילוֹ. וְאִם הִזִּיק מְשַׁלֵּם מַה שֶּׁהִזִּיק. אֲבָל לֹא יָקֹץ אֶת שׂוֹכֹה עַל מְנָת לִתֵּן דָּמִים:","נֶאֱמֶנֶת אִשָּׁה אוֹ קָטָן לוֹמַר מִכָּאן יָצָא נְחִיל זֶה וְהוּא שֶׁיִּהְיוּ מְשִׂיחִין לְפִי תֻּמָּן וְיִהְיוּ הַבְּעָלִים מְרַדְּפִין אַחַר הַנְּחִיל וְשׁוֹאֲלִים הֵיכָן חוֹנֶה. וְאַף עַל פִּי שֶׁאֵין אִשָּׁה אוֹ קָטָן בְּנֵי עֵדוּת הוֹאִיל וְקִנְיַן דְּבוֹרִים מִדִּבְרֵיהֶם הֶאֱמִינוּ אוֹתָם בּוֹ:","כָּל מִי שֶׁיֵּשׁ בְּיָדוֹ גֵּזֶל שֶׁל דִּבְרֵיהֶם אֵינוֹ יוֹצֵא מִיָּדוֹ בְּדַיָּנִין. וְכֵן אִם כָּפַר בּוֹ וְנִשְׁבַּע אֵינוֹ מוֹסִיף חֹמֶשׁ כְּמוֹ שֶׁמּוֹסִיף עַל הַגֵּזֶל הַגָּמוּר:"],"Mishneh Torah, Sabbath 17":["מָבוֹי שֶׁיֵּשׁ לוֹ שְׁלֹשָׁה כְּתָלִים הוּא הַנִּקְרָא מָבוֹי סָתוּם. וּמָבוֹי שֶׁיֵּשׁ לוֹ שְׁנֵי כְּתָלִים בִּלְבַד זֶה כְּנֶגֶד זֶה וְהָעָם נִכְנָסִין בְּרוּחַ זוֹ וְיוֹצְאִין בְּשֶׁכְּנֶגְדָהּ הוּא הַנִּקְרָא מָבוֹי הַמְפֻלָּשׁ:","הֵיאַךְ מַתִּירִין מָבוֹי הַסָּתוּם. עוֹשֶׂה לוֹ בְּרוּחַ רְבִיעִית לֶחִי אֶחָד אוֹ עוֹשֶׂה עָלָיו קוֹרָה וְדַיּוֹ. וְתֵחָשֵׁב אוֹתָהּ קוֹרָה אוֹ אוֹתוֹ לֶחִי כְּאִלּוּ סָתַם רוּחַ רְבִיעִית וְיֵעָשֶׂה רְשׁוּת הַיָּחִיד וְיִהְיֶה מֻתָּר לְטַלְטֵל בְּכֻלּוֹ. שֶׁדִּין תּוֹרָה בְּשָׁלֹשׁ מְחִצּוֹת בִּלְבַד מֻתָּר לְטַלְטֵל וּמִדִּבְרֵי סוֹפְרִים הִיא הָרוּחַ הָרְבִיעִית וּלְפִיכָךְ דַּי לָהּ בְּלֶחִי אוֹ קוֹרָה:","וְהֵיאַךְ מַתִּירִין מָבוֹי מְפֻלָּשׁ. עוֹשֶׂה לוֹ צוּרַת פֶּתַח מִכָּאן וְלֶחִי אוֹ קוֹרָה מִכָּאן. וּמָבוֹי עָקֹם תּוֹרָתוֹ כִּמְפֻלָּשׁ:","מָבוֹי שֶׁהוּא שָׁוֶה מִתּוֹכוֹ וּמִדְרוֹן לִרְשׁוּת הָרַבִּים אוֹ שָׁוֶה לִרְשׁוּת הָרַבִּים וּמִדְרוֹן לְתוֹכוֹ אֵינוֹ צָרִיךְ לֹא לֶחִי וְלֹא קוֹרָה שֶׁהֲרֵי הוּא מֻבְדָּל מֵרְשׁוּת הָרַבִּים:","מָבוֹי שֶׁצִּדּוֹ אֶחָד כָּלֶה לַיָּם וְצִדּוֹ אֶחָד כָּלֶה לְאַשְׁפָּה שֶׁל רַבִּים אֵינוֹ צָרִיךְ כְּלוּם. שֶׁאַשְׁפָּה שֶׁל רַבִּים אֵינָהּ עֲשׂוּיָה לְהִתְפַּנּוֹת וְאֵין חוֹשְׁשִׁין שֶׁמָּא יַעֲלֶה הַיָּם שִׂרְטוֹן:","מָבוֹי מְפֻלָּשׁ שֶׁהוּא כָּלֶה לְאֶמְצַע רְחָבָה שֶׁל רַבִּים. אִם לֹא הָיָה מְכֻוָּן כְּנֶגֶד פֶּתַח הָרְחָבָה הֲרֵי זֶה כְּסָתוּם וְאֵינוֹ צָרִיךְ מִצַּד הָרְחָבָה כְּלוּם. אֲבָל אִם הָיָה כָּלֶה לְצִדְדֵי הָרְחָבָה אָסוּר. וְאִם הָיְתָה שֶׁל יָחִיד אַף לְאֶמְצָעָהּ אָסוּר. פְּעָמִים בּוֹנֶה מִצַּד אֶחָד וְנִמְצָא כָּלֶה לְצִדָּהּ שֶׁל רְחָבָה:","אֵין הַמָּבוֹי נִתָּר בְּלֶחִי אוֹ קוֹרָה עַד שֶׁיִּהְיוּ בָּתִּים וַחֲצֵרוֹת פְּתוּחוֹת לְתוֹכוֹ וְיִהְיֶה אָרְכּוֹ מֵאַרְבַּע אַמּוֹת וּלְמַעְלָה וְיִהְיֶה אָרְכּוֹ יָתֵר עַל רָחְבּוֹ. אֲבָל מָבוֹי שֶׁאָרְכּוֹ כְּרָחְבּוֹ הֲרֵי הוּא כְּחָצֵר וְאֵינוֹ נִתָּר אֶלָּא בִּשְׁנֵי לְחָיַיִם מִשְּׁנֵי רוּחוֹתָיו כָּל לֶחִי בְּמַשֶּׁהוּ. אוֹ בְּפַס רָחָב אַרְבָּעָה מֵרוּחַ אַחַת:","חָצֵר שֶׁאָרְכָּהּ יֶתֶר עַל רָחְבָּהּ הֲרֵי הִיא כְּמָבוֹי וְנִתֶּרֶת בְּלֶחִי אוֹ קוֹרָה. וּמָבוֹי שֶׁאֵין בָּתִּים וַחֲצֵרוֹת פְּתוּחוֹת לְתוֹכוֹ כְּגוֹן שֶׁלֹּא הָיָה בּוֹ אֶלָּא בַּיִת אֶחָד אוֹ חָצֵר אַחַת וְכֵן מָבוֹי שֶׁאֵין בְּאָרְכּוֹ אַרְבַּע אַמּוֹת אֵינוֹ נִתָּר אֶלָּא בִּשְׁנֵי לְחָיַיִם אוֹ בְּפַס אַרְבָּעָה וּמַשֶּׁהוּ:","מָבוֹי שֶׁאֵין בְּרָחְבּוֹ שְׁלֹשָׁה טְפָחִים אֵינוֹ צָרִיךְ לֹא לֶחִי וְלֹא קוֹרָה וּמֻתָּר לְטַלְטֵל בְּכֻלּוֹ. שֶׁכָּל פָּחוֹת מִשְּׁלֹשָׁה הֲרֵי הוּא כְּלָבוּד. מָבוֹי שֶׁהֶכְשֵׁרוֹ בְּקוֹרָה אַף עַל פִּי שֶׁמֻּתָּר לְטַלְטֵל בְּכֻלּוֹ כִּרְשׁוּת הַיָּחִיד הַזּוֹרֵק מִתּוֹכוֹ לִרְשׁוּת הָרַבִּים אוֹ מֵרְשׁוּת הָרַבִּים לְתוֹכוֹ פָּטוּר. שֶׁהַקּוֹרָה מִשּׁוּם הֶכֵּר הִיא עֲשׂוּיָה. אֲבָל אִם הֶכְשֵׁרוֹ בְּלֶחִי הַזּוֹרֵק מִתּוֹכוֹ לִרְשׁוּת הָרַבִּים אוֹ מֵרְשׁוּת הָרַבִּים לְתוֹכוֹ חַיָּב שֶׁהַלֶּחִי הֲרֵי הוּא כִּמְחִצָּה בְּרוּחַ רְבִיעִית:","שְׁנֵי כְּתָלִים בִּרְשׁוּת הָרַבִּים וְהָעָם עוֹבְרִים בֵּינֵיהֶם כֵּיצַד מַכְשִׁיר בֵּינֵיהֶם. עוֹשֶׂה דְּלָתוֹת מִכָּאן וּדְלָתוֹת מִכָּאן וְאַחַר כָּךְ יַעֲשֶׂה בֵּינֵיהֶם רְשׁוּת הַיָּחִיד. וְאֵינוֹ צָרִיךְ לִנְעל הַדְּלָתוֹת בַּלַּיְלָה אֲבָל צָרִיךְ שֶׁיִּהְיוּ רְאוּיוֹת לְהִנָּעֵל. הָיוּ מְשֻׁקָּעוֹת בְּעָפָר מְפַנֶּה אוֹתָן וּמְתַקְּנָן לְהִנָּעֵל. אֲבָל צוּרַת פֶּתַח אוֹ לֶחִי וְקוֹרָה אֵינָן מוֹעִילִין בְּהֶכְשֵׁר רְשׁוּת הָרַבִּים:","מֻתָּר לְטַלְטֵל בְּמָבוֹי תַּחַת הַקּוֹרָה אוֹ בֵּין הַלְּחָיַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה סָמוּךְ לִרְשׁוּת הָרַבִּים. אֲבָל אִם הָיָה סָמוּךְ לְכַרְמְלִית אָסוּר לְטַלְטֵל תַּחַת הַקּוֹרָה אוֹ בֵּין הַלְּחָיַיִם עַד שֶׁיַּעֲשֶׂה לֶחִי אַחֵר לְהַתִּיר תּוֹךְ הַפֶּתַח שֶׁהֲרֵי מָצָא מִין אֶת מִינוֹ וְנֵעוֹר:","בַּכּל עוֹשִׂין לְחָיַיִם אֲפִלּוּ בְּדָבָר שֶׁיֵּשׁ בּוֹ רוּחַ חַיִּים וַאֲפִלּוּ בְּאִסּוּרֵי הֲנָיָה. עֲבוֹדָה זָרָה עַצְמָהּ אוֹ אֲשֵׁרָה שֶׁעָשָׂה אוֹתָהּ לֶחִי כָּשֵׁר שֶׁהַלֶּחִי עָבְיוֹ כָּל שֶׁהוּא. גֹּבַהּ הַלֶּחִי אֵין פָּחוֹת מֵעֲשָׂרָה טְפָחִים רָחְבּוֹ וְעָבְיוֹ כָּל שֶׁהוּא:","בַּכּל עוֹשִׂין קוֹרָה אֲבָל לֹא בַּאֲשֵׁרָה לְפִי שֶׁיֵּשׁ לְרֹחַב הַקּוֹרָה שִׁעוּר. וְכָל הַשִּׁעוּרִין אֲסוּרִים מִן הָאֲשֵׁרָה. וְכֵן רֹחַב הַקּוֹרָה אֵין פָּחוֹת מִטֶּפַח וְעָבְיָהּ כָּל שֶׁהוּא. וְהוּא שֶׁתִּהְיֶה בְּרִיאָה לְקַבֵּל אָרִיחַ שֶׁהוּא חֲצִי לְבֵנָה שֶׁל שְׁלֹשָׁה טְפָחִים עַל שְׁלֹשָׁה טְפָחִים. וּמַעֲמִידֵי קוֹרָה צְרִיכִין שֶׁיִּהְיוּ בְּרִיאִין כְּדֵי לְקַבֵּל קוֹרָה וַחֲצִי לְבֵנָה:","כַּמָּה יִהְיֶה פֶּתַח הַמָּבוֹי וְיִהְיֶה דַּי לְהַכְשִׁירוֹ בְּלֶחִי אוֹ קוֹרָה. גָּבְהוֹ אֵין פָּחוֹת מֵעֲשָׂרָה טְפָחִים וְלֹא יֶתֶר עַל עֶשְׂרִים אַמָּה וְרָחְבּוֹ עַד עֶשֶׂר אַמּוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא הָיָה לוֹ צוּרַת פֶּתַח. אֲבָל אִם הָיָה לוֹ צוּרַת פֶּתַח אֲפִלּוּ הָיָה גָּבוֹהַּ מֵאָה אַמָּה אוֹ פָּחוֹת מֵעֲשָׂרָה אוֹ רֹחַב מֵאָה אַמָּה הֲרֵי זֶה מֻתָּר:","וְכֵן אִם הָיָה בְּקוֹרָה שֶׁל מָבוֹי כִּיּוּר וְצִיּוּר עַד שֶׁיִּהְיוּ הַכּל מִסְתַּכְּלִין בָּהּ אַף עַל פִּי שֶׁהִיא לְמַעְלָה מֵעֶשְׂרִים אַמָּה כְּשֵׁרָה. שֶׁהַקּוֹרָה מִשּׁוּם הֶכֵּר עֲשׂוּיָה וְאִם הָיְתָה לְמַעְלָה מֵעֶשְׂרִים אֵינָהּ נִכֶּרֶת וְאִם יֵשׁ בָּהּ צִיּוּר וְכִיּוּר מִסְתַּכְּלִים בָּהּ וְנִמְצָא שָׁם הֶכֵּר:","מָבוֹי שֶׁהָיָה גָּבְהוֹ מִן הָאָרֶץ עַד קַרְקָעִית קוֹרָה עֶשְׂרִים אַמָּה וָעֳבִי הַקּוֹרָה לְמַעְלָה מֵעֶשְׂרִים כָּשֵׁר. הָיָה גָּבְהוֹ יֶתֶר מֵעֶשְׂרִים וּבָא לְמַעֲטוֹ בַּקּוֹרָה שֶׁמַּנִּיחַ אוֹתָהּ לְמַטָּה צָרִיךְ לִהְיוֹת בְּרָחְבָּהּ טֶפַח כְּקוֹרָה. הָיָה גָּבְהוֹ פָּחוֹת מֵעֲשָׂרָה חוֹקֵק בּוֹ מֶשֶׁךְ אַרְבַּע עַל אַרְבַּע אַמּוֹת וּמַעֲמִיק כְּדֵי לְהַשְׁלִימוֹ לַעֲשָׂרָה:","נִפְרַץ בּוֹ פִּרְצָה מִצִּדּוֹ כְּלַפֵּי רֹאשׁוֹ אִם נִשְׁאַר עוֹמֵד בְּרֹאשׁוֹ פַּס רֹחַב אַרְבָּעָה טְפָחִים מֻתָּר וְהוּא שֶׁלֹּא תִּהְיֶה הַפִּרְצָה יֶתֶר עַל עֶשֶׂר. וְאִם לֹא נִשְׁאַר פַּס אַרְבָּעָה אָסוּר אֶלָּא אִם כֵּן הָיְתָה הַפִּרְצָה פָּחוֹת מִשְּׁלֹשָׁה שֶׁכָּל פָּחוֹת מִשְּׁלֹשָׁה כְּלָבוּד:","נִפְרַץ הַמָּבוֹי בִּמְלוֹאוֹ לֶחָצֵר וְנִפְרְצָה חָצֵר כְּנֶגְדּוֹ לִרְשׁוּת הָרַבִּים הֲרֵי זֶה אָסוּר מִפְּנֵי שֶׁהוּא מָבוֹי מְפֻלָּשׁ. וְהֶחָצֵר מֻתֶּרֶת שֶׁהֶחָצֵר שֶׁרַבִּים בּוֹקְעִין בָּהּ וְנִכְנָסִין בָּזוֹ וְיוֹצְאִין בָּזוֹ הֲרֵי הִיא רְשׁוּת הַיָּחִיד גְּמוּרָה:","מָבוֹי שֶׁהָיוּ לוֹ שְׁבִילִים מִצַּד זֶה וּשְׁבִילִים מִצַּד אַחֵר שֶׁנִּמְצְאוּ מְפֻלָּשִׁין לִרְשׁוּת הָרַבִּים אַף עַל פִּי שֶׁאֵינָן מְכֻוָּנִין זֶה כְּנֶגֶד זֶה הֲרֵי כָּל אֶחָד מֵהֶן מָבוֹי מְפֻלָּשׁ. כֵּיצַד מַכְשִׁירִין אוֹתוֹ. עוֹשֶׂה צוּרַת פֶּתַח לְכָל אֶחָד וְאֶחָד מִן הַשְּׁבִילִים שֶׁבַּצַּד הָאֶחָד. וְכֵן לַפֶּתַח הַגָּדוֹל. וְעוֹשֶׂה לְכָל הַשְּׁבִילִים שֶׁבַּצַּד הַשֵּׁנִי לֶחִי אוֹ קוֹרָה:","מָבוֹי שֶׁצִּדּוֹ אֶחָד אָרֹךְ וְצִדּוֹ הַשֵּׁנִי קָצָר מַנִּיחַ אֶת הַקּוֹרָה כְּנֶגֶד הַקָּצָר. הֶעֱמִיד לֶחִי בַּחֲצִי הַמָּבוֹי הַפְּנִימִי שֶׁהוּא לִפְנִים מִן הַלֶּחִי מֻתָּר לְטַלְטֵל בּוֹ וְהַחֵצִי הַחִיצוֹן שֶׁהוּא חוּץ מִן הַלֶּחִי אָסוּר:","מָבוֹי שֶׁהוּא רָחָב עֶשְׂרִים אַמָּה עוֹשֶׂה פַּס גָּבוֹהַּ עֲשָׂרָה טְפָחִים בְּמֶשֶׁךְ אַרְבַּע אַמּוֹת שֶׁהוּא שִׁעוּר מֶשֶׁךְ הַמָּבוֹי וּמַעֲמִידוֹ בָּאֶמְצַע וְנִמְצָא כִּשְׁנֵי מְבוֹאוֹת שֶׁיֵּשׁ בְּפֶתַח כָּל אֶחָד מֵהֶן עֶשֶׂר אַמּוֹת. אוֹ מַרְחִיק שְׁתֵּי אַמּוֹת מִכָּאן וּמַעֲמִיד פַּס שָׁלֹשׁ אַמּוֹת וּמַרְחִיק שְׁתֵּי אַמּוֹת מִכָּאן וּמַעֲמִיד פַּס שָׁלֹשׁ אַמּוֹת מִכָּאן וְנִמְצָא פֶּתַח הַמָּבוֹי עֶשֶׂר אַמּוֹת וְהַצְּדָדִין הֲרֵי הֵן כִּסְתוּמִין שֶׁהֲרֵי עוֹמֵד מְרֻבֶּה עַל הַפָּרוּץ:","לֶחִי הַבּוֹלֵט מִדָּפְנוֹ שֶׁל מָבוֹי כָּשֵׁר. וְלֶחִי הָעוֹמֵד מֵאֵלָיו אִם סָמְכוּ עָלָיו מִקֹּדֶם הַשַּׁבָּת כָּשֵׁר. וְלֶחִי שֶׁהוּא נִרְאֶה מִבִּפְנִים לֶחִי וּמִבַּחוּץ אֵינוֹ נִרְאֶה לֶחִי. אוֹ שֶׁהָיָה נִרְאֶה מִבַּחוּץ לֶחִי וּמִבִּפְנִים נִרְאֶה שֶׁהוּא שָׁוֶה וּכְאִלּוּ אֵין שָׁם לֶחִי. הֲרֵי זֶה נִדּוֹן מִשּׁוּם לֶחִי. לֶחִי שֶׁהִגְבִּיהוֹ מִן הַקַּרְקַע שְׁלֹשָׁה טְפָחִים אוֹ שֶׁהִפְלִיגוֹ מִן הַכֹּתֶל שְׁלֹשָׁה לֹא עָשָׂה כְּלוּם. אֲבָל פָּחוֹת מִשְּׁלֹשָׁה טְפָחִים כָּשֵׁר שֶׁכָּל פָּחוֹת מִשְּׁלֹשָׁה כְּלָבוּד. לֶחִי שֶׁהָיָה רָחָב הַרְבֵּה. בֵּין שֶׁהָיָה רָחְבּוֹ פָּחוֹת מֵחֲצִי רֹחַב הַמָּבוֹי בֵּין שֶׁהָיָה רָחְבּוֹ כַּחֲצִי רֹחַב הַמָּבוֹי כָּשֵׁר וְנִדּוֹן מִשּׁוּם לֶחִי. אֲבָל אִם הָיָה יָתֵר עַל חֲצִי רֹחַב הַמָּבוֹי נִדּוֹן מִשּׁוּם עוֹמֵד מְרֻבֶּה עַל הַפָּרוּץ:","קוֹרָה שֶׁפֵּרֵס עָלֶיהָ מַחְצֶלֶת הֲרֵי בִּטְּלָהּ שֶׁהֲרֵי אֵינָהּ נִכֶּרֶת. לְפִיכָךְ אִם הָיְתָה הַמַּחְצֶלֶת מְסֻלֶּקֶת מִן הָאָרֶץ שְׁלֹשָׁה טְפָחִים אוֹ יֶתֶר אֵינָהּ מְחִצָּה. נָעַץ שְׁתֵּי יְתֵדוֹת בִּשְׁנֵי כָּתְלֵי מָבוֹי מִבַּחוּץ וְהִנִּיחַ עֲלֵיהֶן הַקּוֹרָה לֹא עָשָׂה כְּלוּם. שֶׁצָּרִיךְ לִהְיוֹת הַקּוֹרָה עַל גַּבֵּי הַמָּבוֹי לֹא סָמוּךְ לוֹ:","קוֹרָה הַיּוֹצְאָה מִכֹּתֶל זֶה וְאֵינָהּ נוֹגַעַת בַּכֹּתֶל הַשֵּׁנִי וְכֵן שְׁתֵּי קוֹרוֹת אַחַת יוֹצְאָה מִכֹּתֶל זֶה וְאַחַת יוֹצְאָה מִכֹּתֶל זֶה וְאֵינָן מַגִּיעוֹת זוֹ לָזוֹ פָּחוֹת מִשְּׁלֹשָׁה אֵינוֹ צָרִיךְ לְהָבִיא קוֹרָה אַחֶרֶת. הָיָה בֵּינֵיהֶן שְׁלֹשָׁה צָרִיךְ לְהָבִיא קוֹרָה אַחֶרֶת:","וְכֵן שְׁתֵּי קוֹרוֹת הַמַּתְאִימוֹת לֹא בָּזוֹ כְּדֵי לְקַבֵּל אָרִיחַ וְלֹא בָּזוֹ כְּדֵי לְקַבֵּל אָרִיחַ אִם יֵשׁ בִּשְׁתֵּיהֶן כְּדֵי לְקַבֵּל אָרִיחַ אֵינוֹ צָרִיךְ לְהָבִיא קוֹרָה אַחֶרֶת. הָיְתָה אַחַת לְמַטָּה וְאַחַת לְמַעְלָה רוֹאִין אֶת הָעֶלְיוֹנָה כְּאִלּוּ הִיא לְמַטָּה וְהַתַּחְתּוֹנָה כְּאִלּוּ הִיא לְמַעְלָה. וּבִלְבַד שֶׁלֹּא תִּהְיֶה עֶלְיוֹנָה לְמַעְלָה מֵעֶשְׂרִים וְלֹא תַּחְתּוֹנָה לְמַטָּה מֵעֲשָׂרָה. וְלֹא יִהְיֶה בֵּינֵיהֶן שְׁלֹשָׁה טְפָחִים כְּשֶׁרוֹאִין אוֹתָהּ שֶׁיָּרְדָה זוֹ וְעָלְתָה זוֹ בְּכַוָּנָה עַד שֶׁיֵּעָשׂוּ זוֹ בְּצַד זוֹ:","הָיְתָה הַקּוֹרָה עֲקֻמָּה רוֹאִין אוֹתָהּ כְּאִלּוּ הִיא פְּשׁוּטָה. עֲגֻלָּה רוֹאִין אוֹתָהּ כְּאִלּוּ הִיא מְרֻבַּעַת. וְאִם הָיָה בְּהֶקֵפָהּ שְׁלֹשָׁה טְפָחִים יֵשׁ בָּהּ רֹחַב טֶפַח. הָיְתָה הַקּוֹרָה בְּתוֹךְ הַמָּבוֹי וַעֲקֻמָּה חוּץ לַמָּבוֹי. אוֹ שֶׁהָיְתָה עֲקֻמָּה לְמַעְלָה מֵעֶשְׂרִים אוֹ לְמַטָּה מֵעֲשָׂרָה. רוֹאִין כּל שֶׁאִלּוּ יִנָּטֵל הָעִקּוּם וְיִשָּׁאֲרוּ שְׁנֵי רָאשֶׁיהָ אֵין בֵּין זֶה לָזֶה שְׁלֹשָׁה אֵינוֹ צָרִיךְ לְהָבִיא קוֹרָה אַחֶרֶת. וְאִם לָאו צָרִיךְ לְהָבִיא קוֹרָה אַחֶרֶת:","בְּאֵר שֶׁעָשָׂה לָהּ שְׁמוֹנָה פַּסִּין מֵאַרְבַּע זָוִיּוֹת שְׁנֵי פַּסִּין דְּבוּקִין בְּכָל זָוִית הֲרֵי אֵלּוּ כִּמְחִצָּה. וְאַף עַל פִּי שֶׁהַפָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד בְּכָל רוּחַ וָרוּחַ. הוֹאִיל וְאַרְבַּע הַזָּוִיּוֹת עוֹמְדוֹת הֲרֵי זֶה מֻתָּר לְמַלְּאוֹת מִן הַבְּאֵר וּלְהַשְׁקוֹת לִבְהֵמָה. וְכַמָּה יִהְיֶה גֹּבַהּ כָּל פַּס מֵהֶן עֲשָׂרָה טְפָחִים וְרָחְבּוֹ שִׁשָּׁה טְפָחִים וּבֵין כָּל פַּס לְפַס כִּמְלֹא שְׁתֵּי רִבְקוֹת שֶׁל אַרְבָּעָה אַרְבָּעָה בָּקָר אַחַת נִכְנֶסֶת וְאַחַת יוֹצְאָה. שִׁעוּר רֹחַב זֶה אֵין יֶתֶר עַל שְׁלֹשׁ עֶשְׂרֵה אַמָּה וּשְׁלִישׁ:","הָיָה בְּמָקוֹם אֶחָד מִן הַזָּוִיּוֹת אוֹ בְּכָל זָוִית מֵאַרְבַּעְתָּן אֶבֶן גְּדוֹלָה אוֹ אִילָן אוֹ תֵּל הַמִּתְלַקֵּט עֲשָׂרָה מִתּוֹךְ אַרְבַּע אַמּוֹת אוֹ חֲבִילָה שֶׁל קָנִים. רוֹאִין כּל שֶׁאִלּוּ יֵחָלֵק וְיֵשׁ בּוֹ אַמָּה לְכָאן וְאַמָּה לְכָאן בְּגֹבַהּ עֲשָׂרָה נִדּוֹן מִשּׁוּם זָוִית שֶׁיֵּשׁ בָּהּ שְׁנֵי פַּסִּין. חֲמִשָּׁה קָנִים וְאֵין בֵּין זֶה לָזֶה שְׁלֹשָׁה וְיֵשׁ בֵּינֵיהֶן שִׁשָּׁה טְפָחִים לְכָאן וְשִׁשָּׁה טְפָחִים לְכָאן נִדּוֹנִים מִשּׁוּם זָוִית שֶׁיֵּשׁ בָּהּ שְׁנֵי פַּסִּין:","מֻתָּר לְהַקְרִיב אַרְבַּע הַזָּוִיּוֹת הָאֵלּוּ לִבְאֵר. וְהוּא שֶׁתִּהְיֶה פָּרָה רֹאשָׁהּ וְרֻבָּה לִפְנִים מִן הַפַּסִּין וְשׁוֹתָה. אַף עַל פִּי שֶׁלֹּא יֹאחַז רֹאשׁ הַבְּהֵמָה עִם הַכְּלִי שֶׁבּוֹ הַמַּיִם הוֹאִיל וְרֹאשָׁהּ וְרֻבָּה בִּפְנִים מֻתָּר אֲפִלּוּ לְגָמָל. הָיוּ קְרוֹבִים יֶתֶר מִזֶּה אָסוּר לְהַשְׁקוֹת מֵהֶן אֲפִלּוּ לִגְדִי שֶׁהוּא כֻּלּוֹ נִכְנָס לִפְנִים. וּמֻתָּר לְהַרְחִיק כָּל שֶׁהוּא וּבִלְבַד שֶׁיַּרְבֶּה בְּפַסִּים פְּשׁוּטִים שֶׁמַּנִּיחִין אוֹתָן בְּכָל רוּחַ וְרוּחַ כְּדֵי שֶׁלֹּא יְהֵא בֵּין פַּס לַחֲבֵרוֹ יוֹתֵר עַל שְׁלֹשׁ עֶשְׂרֵה אַמָּה וּשְׁלִישׁ:","לֹא הִתִּירוּ הַפַּסִּים הָאֵלּוּ אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל וּלְבֶהֱמַת עוֹלֵי רְגָלִים בִּלְבַד וְהוּא שֶׁיִּהְיֶה בְּאֵר מַיִם חַיִּים שֶׁל רַבִּים. אֲבָל בִּשְׁאָר אֲרָצוֹת אָדָם יֵרֵד לַבְּאֵר וְיִשְׁתֶּה אוֹ יַעֲשֶׂה לוֹ מְחִצָּה מַקֶּפֶת לַבְּאֵר גְּבוֹהָה עֲשָׂרָה טְפָחִים וְיַעֲמֹד בְּתוֹכָהּ וְיִדְלֶה וְיִשְׁתֶּה. וְאִם הָיָה הַבְּאֵר רָחָב הַרְבֵּה שֶׁאֵין אָדָם יָכוֹל לֵירֵד בּוֹ הֲרֵי זֶה יִדְלֶה וְיִשְׁתֶּה בֵּין הַפַּסִּין:","וְכֵן בּוֹר הָרַבִּים וּבְאֵר הַיָּחִיד אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל אֵין מְמַלְּאִין מֵהֶן אֶלָּא אִם כֵּן עָשׂוּ לָהֶן מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים:","הַמְמַלֵּא לִבְהֶמְתּוֹ בֵּין הַפַּסִּים מְמַלֵּא וְנוֹתֵן בִּכְלִי לְפָנֶיהָ. וְאִם הָיָה אֵבוּס רֹאשׁוֹ נִכְנָס לְבֵין הַפַּסִּים וְהָיָה גָּבוֹהַּ עֲשָׂרָה וְרָחָב אַרְבָּעָה לֹא יְמַלֵּא וְיִתֵּן לְפָנֶיהָ שֶׁמָּא יִתְקַלְקֵל הָאֵבוּס וְיוֹצִיא הַדְּלִי לָאֵבוּס וּמִן הָאֵבוּס לְקַרְקַע רְשׁוּת הָרַבִּים אֶלָּא מְמַלֵּא וְשׁוֹפֵךְ וְהִיא שׁוֹתָה מֵאֵלֶיהָ:","הַזּוֹרֵק מֵרְשׁוּת הָרַבִּים לְבֵין הַפַּסִּין חַיָּב הוֹאִיל וְיֵשׁ בְּכָל זָוִית וְזָוִית מְחִצָּה גְּמוּרָה שֶׁיֵּשׁ בָּהּ גֹּבַהּ עֲשָׂרָה וְיוֹתֵר מֵאַרְבָּעָה עַל אַרְבָּעָה וַהֲרֵי הָרִבּוּעַ נִכָּר וְנִרְאֶה וְנַעֲשָׂה כָּל שֶׁבֵּינֵיהֶם רְשׁוּת הַיָּחִיד. וַאֲפִלּוּ הָיָה בְּבִקְעָה וְאֵין שָׁם בֵּינֵיהֶם בְּאֵר שֶׁהֲרֵי בְּכָל רוּחַ וְרוּחַ פַּס מִכָּאן וּפַס מִכָּאן. וַאֲפִלּוּ הָיוּ רַבִּים בּוֹקְעִין וְעוֹבְרִין בֵּין הַפַּסִּין לֹא בָּטְלוּ הַמְּחִצּוֹת וַהֲרֵי הֵן כַּחֲצֵרוֹת שֶׁהָרַבִּים בּוֹקְעִין בָּהֶן וְהַזּוֹרֵק לְתוֹכָן חַיָּב. וּמֻתָּר לְהַשְׁקוֹת הַבְּהֵמָה בֵּינֵיהֶן אִם הָיָה בֵּינֵיהֶן בְּאֵר:","חָצֵר שֶׁרֹאשָׁהּ אֶחָד נִכְנָס לְבֵין הַפַּסִּין מֻתָּר לְטַלְטֵל מִתּוֹכָהּ לְבֵין הַפַּסִּין וּמִבֵּין הַפַּסִּין לְתוֹכָהּ. הָיוּ שְׁתֵּי חֲצֵרוֹת אֲסוּרִין עַד שֶׁיְּעָרְבוּ. יָבְשׁוּ הַמַּיִם בְּשַׁבָּת אָסוּר לְטַלְטֵל בֵּין הַפַּסִּין שֶׁלֹּא נֶחְשְׁבוּ מְחִצָּה לְטַלְטֵל בְּתוֹכָן אֶלָּא מִשּׁוּם הַמַּיִם. בָּאוּ לוֹ מַיִם בְּשַׁבָּת מֻתָּר לְטַלְטֵל בֵּינֵיהֶן. שֶׁכָּל מְחִצָּה שֶׁנַּעֲשֵׂית בְּשַׁבָּת שְׁמָהּ מְחִצָּה. מָבוֹי שֶׁנִּטְּלָה קוֹרָתוֹ אוֹ לֶחְיוֹ בְּשַׁבָּת אָסוּר לְטַלְטֵל בּוֹ אַף עַל פִּי שֶׁנִּפְרַץ לְכַרְמְלִית:","אַכְסַדְרָה בַּבִּקְעָה מֻתָּר לְטַלְטֵל בְּכֻלָּהּ וְאַף עַל פִּי שֶׁהִיא בַּת שָׁלֹשׁ מְחִצּוֹת וְתִקְרָה. שֶׁאָנוּ רוֹאִין כְּאִלּוּ פִּי תִּקְרָה יוֹרֵד וְסוֹתֵם רוּחַ רְבִיעִית. וְהַזּוֹרֵק מֵרְשׁוּת הָרַבִּים לְתוֹכָהּ פָּטוּר כְּזוֹרֵק לְמָבוֹי סָתוּם שֶׁיֵּשׁ לוֹ קוֹרָה. בַּיִת אוֹ חָצֵר שֶׁנִּפְרַץ קֶרֶן זָוִית שֶׁלָּהּ בְּעֶשֶׂר אַמּוֹת הֲרֵי זֶה אָסוּר לְטַלְטֵל בְּכֻלּוֹ אַף עַל פִּי שֶׁכָּל פִּרְצָה שֶׁהִיא עַד עֶשֶׂר אַמּוֹת כְּפֶתַח. אֵין עוֹשִׂין פֶּתַח בְּקֶרֶן זָוִית. וְאִם הָיְתָה שָׁם קוֹרָה מִלְּמַעְלָה עַל אֹרֶךְ הַפִּרְצָה רוֹאִין אוֹתָהּ שֶׁיָּרְדָה וְסָתְמָה וּמֻתָּר לְטַלְטֵל בְּכֻלּוֹ וְהוּא שֶׁלֹּא תִּהְיֶה בַּאֲלַכְסוֹן:","הָאֶצְבַּע שֶׁמְּשַׁעֲרִין בָּהּ בְּכָל מָקוֹם הִיא רֹחַב הַגּוּדָל שֶׁל יָד. וְהַטֶּפַח אַרְבַּע אֶצְבָּעוֹת. וְכָל אַמָּה הָאֲמוּרָה בְּכָל מָקוֹם בֵּין בְּשַׁבָּת בֵּין בְּסֻכָּה וְכִלְאַיִם הִיא אַמָּה בַּת שִׁשָּׁה טְפָחִים. וּפְעָמִים מְשַׁעֲרִין בְּאַמָּה בַּת שִׁשָּׁה טְפָחִים דְּחוּקוֹת זוֹ לְזוֹ. וּפְעָמִים מְשַׁעֲרִין בְּאַמָּה בַּת שִׁשָּׁה שׂוֹחֲקוֹת וְרוֹוְחוֹת וְזֶה וָזֶה לְהַחֲמִיר. כֵּיצַד. מֶשֶׁךְ מָבוֹי בְּאַרְבַּע אַמּוֹת שׂוֹחֲקוֹת וְגָבְהוֹ עֶשְׂרִים אַמָּה עֲצֵבוֹת. רֹחַב הַפִּרְצָה עֶשֶׂר אַמּוֹת עֲצֵבוֹת. וְכַיּוֹצֵא בָּהֶן לְעִנְיַן סֻכָּה וְכִלְאַיִם:"],"Mishneh Torah, Sabbath 28":["כָּל בֵּית דִּירָה שֶׁהוּא יוֹצֵא מִן הַמְּדִינָה אִם הָיָה בֵּינוֹ וּבֵין הַמְּדִינָה שִׁבְעִים אַמָּה וּשְׁנֵי שְׁלִישֵׁי אַמָּה שֶׁהוּא צֶלַע בֵּית סָאתַיִם הַמְרֻבַּעַת אוֹ פָּחוֹת מִזֶּה הֲרֵי זֶה מִצְטָרֵף לִמְדִינָה וְנֶחְשָׁב מִמֶּנָּה. וּכְשֶׁמּוֹדְדִין לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ מוֹדְדִין חוּץ מִבֵּית דִּירָה זֶה:","הָיָה בַּיִת זֶה קָרוֹב לַמְּדִינָה בְּשִׁבְעִים אַמָּה וּבַיִת שֵׁנִי קָרוֹב לְבַיִת רִאשׁוֹן בְּשִׁבְעִים אַמָּה וּבַיִת שְׁלִישִׁי קָרוֹב לַשֵּׁנִי בְּשִׁבְעִים אַמָּה וְכֵן עַד מַהֲלַךְ כַּמָּה יָמִים הֲרֵי הַכּל כִּמְדִינָה אַחַת וּכְשֶׁמּוֹדְדִין מוֹדְדִין מִחוּץ לַבַּיִת הָאַחֲרוֹן. וְהוּא שֶׁיִּהְיֶה בֵּית דִּירָה זֶה אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אוֹ יֶתֶר:","וְכֵן בֵּית הַכְּנֶסֶת שֶׁיֵּשׁ בּוֹ בֵּית דִּירָה לְחַזָּנִין וּבֵית עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת שֶׁיֵּשׁ בּוֹ בֵּית דִּירָה לְכֹהֲנֵיהֶם וְהָאוֹצָרוֹת שֶׁיֵּשׁ בָּהֶן בֵּית דִּירָה וְהַגֶּשֶׁר וְהַקֶּבֶר שֶׁיֵּשׁ בָּהֶן בֵּית דִּירָה וְשָׁלֹשׁ מְחִצּוֹת שֶׁאֵין עָלֶיהָ תִּקְרָה וְיֵשׁ בָּהֶן אַרְבַּע עַל אַרְבַּע אַמּוֹת וְהַבֻּרְגָּנִין וְהַבַּיִת הַבָּנוּי בַּיָּם וּשְׁתֵּי מְחִצּוֹת שֶׁיֵּשׁ עֲלֵיהֶן תִּקְרָה וּמְעָרָה שֶׁיֵּשׁ בִּנְיָן עַל פִּיהָ וְיֵשׁ בָּהּ בֵּית דִּירָה. כָּל אֵלּוּ מִצְטָרְפִין עִמָּהּ אִם הָיוּ בְּתוֹךְ שִׁבְעִים אַמָּה וְשִׁירַיִם. וּמֵאוֹתוֹ הַבַּיִת הַיּוֹצֵא רוֹאִין כְּאִלּוּ חוּט מָתוּחַ עַל פְּנֵי כָּל הַמְּדִינָה וּמוֹדְדִין חוּץ לְאוֹתוֹ הַחוּט אַלְפַּיִם אַמָּה:","וְאֵלּוּ שֶׁאֵין מִצְטָרְפִין עִמָּהּ. שְׁתֵּי מְחִצּוֹת שֶׁאֵין עֲלֵיהֶן תִּקְרָה אַף עַל פִּי שֶׁדָּרִין בֵּינֵיהֶן. וְהַגֶּשֶׁר וְהַקֶּבֶר וּבֵית הַכְּנֶסֶת וּבֵית עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְהָאוֹצָרוֹת שֶׁאֵין בָּהֶן בֵּית דִּירָה וְהַבּוֹר וְהַשִּׁיחַ וְהַמְּעָרָה וְהַשּׁוֹבָךְ וּבַיִת שֶׁבַּסְּפִינָה כָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן אֵין מִצְטָרְפִין עִמָּהּ:","הָיוּ שְׁתֵּי עֲיָרוֹת זוֹ סְמוּכָה לָזוֹ אִם יֵשׁ בֵּינֵיהֶן מֵאָה וְאַרְבָּעִים וְאַחַת וּשְׁלִישׁ כְּדֵי שֶׁיִּהְיֶה שִׁבְעִים אַמָּה וְשִׁירַיִם לָזוֹ וְשִׁבְעִים אַמָּה וְשִׁירַיִם לָזוֹ חוֹשְבִין שְׁתֵּיהֶן כְּעִיר אַחַת וְנִמְצֵאת כָּל עִיר מֵהֶן מְהַלֶּכֶת אֶת כָּל הָעִיר הַשְּׁנִיָּה וָחוּצָה לָהּ אַלְפַּיִם אַמָּה. הָיוּ שְׁלֹשָׁה כְּפָרִים מְשֻׁלָּשִׁין אִם יֵשׁ בֵּין הָאֶמְצָעִי וּבֵין כָּל אֶחָד וְאֶחָד מִן הַחִיצוֹנִים אַלְפַּיִם אַמָּה אוֹ פָּחוֹת מִכָּאן וּבֵין הַשְּׁנַיִם הַחִיצוֹנִים מָאתַיִם שָׁלֹשׁ וּשְׁמוֹנִים פָּחוֹת שְׁלִישׁ כְּדֵי שֶׁיִּהְיֶה בֵּין כָּל אֶחָד מֵהֶן וּבֵין הָאֶמְצָעִי כְּשֶׁתִּרְאֶה אוֹתוֹ כְּאִלּוּ הוּא בֵּינֵיהֶן מֵאָה וְאַרְבָּעִים וְאַחַת אַמָּה וּשְׁלִישׁ הֲרֵי שְׁלָשְׁתָּן כִּמְדִינָה אַחַת וּמוֹדְדִין אַלְפַּיִם אַמָּה לְכָל רוּחַ מִחוּץ לִשְׁלָשְׁתָּן. עִיר שֶׁהֻקְּפָה וּלְבַסּוֹף יָשְׁבָה מוֹדְדִין לָהּ מִישִׁיבָתָהּ. יָשְׁבָה וּלְבַסּוֹף הֻקְּפָה מוֹדְדִין לָהּ מֵחוֹמוֹתֶיהָ:","עִיר שֶׁהָיְתָה אֲרֻכָּה אוֹ מְרֻבַּעַת הוֹאִיל וְיֵשׁ לָהּ אַרְבַּע זָוִיּוֹת שָׁווֹת מַנִּיחִין אוֹתָהּ כְּמוֹת שֶׁהִיא וּמוֹדְדִין לָהּ אַלְפַּיִם אַמָּה לְכָל רוּחַ מֵאַרְבַּע רוּחוֹתֶיהָ. הָיְתָה עֲגֻלָּה עוֹשִׂין לָהּ זָוִיּוֹת וְרוֹאִין אוֹתָהּ כְּאִלּוּ הוּא בְּתוֹךְ הַמְרֻבָּע וּמוֹדְדִין חוּץ מִצַּלְעוֹת אוֹתוֹ מְרֻבָּע אַלְפַּיִם אַמָּה לְכָל רוּחַ שֶׁנִּמְצָא מִשְׂתַּכֵּר הַזָּוִיּוֹת:","וְכֵן אִם הָיְתָה הָעִיר מְשֻׁלֶּשֶׁת אוֹ שֶׁיֵּשׁ לָהּ צְלָעוֹת רַבּוֹת מְרַבְּעִין אוֹתָהּ וְאַחַר כָּךְ מוֹדְדִין חוּץ לַמְרֻבָּע אַלְפַּיִם אַמָּה לְכָל רוּחַ. וּכְשֶׁהוּא מְרַבְּעָהּ מְרַבְּעָהּ בְּרִבּוּעַ הָעוֹלָם כְּדֵי שֶׁתְּהֵא כָּל רוּחַ מִמֶּנָּה מְשׁוּכָה כְּנֶגֶד רוּחַ מֵרוּחוֹת הָעוֹלָם וּמְכֻוֶּנֶת כְּנֶגְדָּהּ:","הָיְתָה רְחָבָה מִצַּד אֶחָד וּקְצָרָה מִצַּד אֶחָד רוֹאִין אוֹתָהּ כְּאִלּוּ הִיא כֻּלָּהּ רְחָבָה. הָיְתָה עֲשׂוּיָה כְּמִין גַּ\"ם אוֹ שֶׁהָיְתָה עֲשׂוּיָה כְּקֶשֶׁת אִם יֵשׁ בֵּין שְׁנֵי רָאשֶׁיהָ פָּחוֹת מֵאַרְבַּעַת אֲלָפִים אַמָּה מוֹדְדִין לָהּ מִן הַיֶּתֶר וְרוֹאִין אֶת כָּל הָרֹחַב שֶׁבֵּין הַיֶּתֶר וְהַקֶּשֶׁת כְּאִלּוּ הוּא מָלֵא בָּתִּים. וְאִם הָיָה בֵּין שְׁנֵי רָאשֶׁיהָ אַרְבַּעַת אֲלָפִים אֵין מוֹדְדִין לָהּ אֶלָּא מִן הַקֶּשֶׁת:","עִיר שֶׁיּוֹשֶׁבֶת עַל שְׂפַת הַנַּחַל. אִם יֵשׁ לְפָנֶיהָ דַּקָּה רֹחַב אַרְבַּע אַמּוֹת עַל שְׂפַת הַנַּחַל כְּדֵי שֶׁיַּעַמְדוּ עָלֶיהָ וְיִשְׁתַּמְּשׁוּ בַּנַּחַל נִמְצָא הַנַּחַל בִּכְלַל הָעִיר וּמוֹדְדִין לָהּ אַלְפַּיִם אַמָּה מִשְּׂפַת הַנַּחַל הַשְּׁנִיָּה וְיֵעָשֶׂה הַנַּחַל כֻּלּוֹ בִּכְלַל הַמְּדִינָה מִפְּנֵי הַדַּקָּה הַבְּנוּיָה מִצִּדּוֹ. וְאִם לֹא הָיָה שָׁם דַּקָּה אֵין מוֹדְדִין לָהֶן אֶלָּא מִפֶּתַח בָּתֵּיהֶן וְנִמְצָא הַנַּחַל נִמְדָּד מִן הָאַלְפַּיִם שֶׁלָּהֶם:","יוֹשְׁבֵי צְרִיפִין אֵין מוֹדְדִין לָהֶן אֶלָּא מִפֶּתַח בָּתֵּיהֶן. וְאִם יֵשׁ שָׁם שָׁלֹשׁ חֲצֵרוֹת שֶׁל שְׁנֵי שְׁנֵי בָּתִּים הֻקְבְּעוּ כֻּלָּם וּמְרַבְּעִין אוֹתָהּ וְנוֹתְנִין לָהֶם אַלְפַּיִם אַמָּה לְכָל רוּחַ כִּשְׁאָר הָעֲיָרוֹת:","אֵין מוֹדְדִין אֶלָּא בְּחֶבֶל שֶׁל חֲמִשִּׁים אַמָּה לֹא פָּחוֹת וְלֹא יֶתֶר וּבְחֶבֶל שֶׁל פִּשְׁתָּן כְּדֵי שֶׁלֹּא יִמָּשֵׁךְ יוֹתֵר מִדַּאי. הִגִּיעַ לְגַיְא אִם הָיָה רָחְבּוֹ חֲמִשִּׁים אַמָּה שֶׁיָּכוֹל לְהַבְלִיעוֹ בְּחֶבֶל הַמִּדָּה מַבְלִיעוֹ וְהוּא שֶׁיִּהְיֶה בְּעָמְקוֹ פָּחוֹת מֵאַרְבַּעַת אֲלָפִים:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהָיָה חוּט הַמִּשְׁקלֶת יוֹרֵד כְּנֶגְדּוֹ שֶׁאִי אֶפְשָׁר לְהִשְׁתַּמֵּשׁ בּוֹ. אֲבָל אִם אֵין חוּט הַמִּשְׁקלֶת יוֹרֵד כְּנֶגְדּוֹ אֵינוֹ מַבְלִיעוֹ אֶלָּא אִם כֵּן הָיָה עָמְקוֹ אַלְפַּיִם אוֹ פָּחוֹת מִכֵּן:","הָיָה גַּיְא מְעֻקָּם מְקַדֵּר וְעוֹלֶה מְקַדֵּר וְיוֹרֵד. הָיָה גַּיְא רָחָב מֵחֲמִשִּׁים שֶׁאֵינוֹ יָכוֹל לְהַבְלִיעוֹ הוֹלֵךְ לְמָקוֹם שֶׁהוּא יָכוֹל לְהַבְלִיעוֹ וּמַבְלִיעוֹ וְצוֹפֶה כְּנֶגֶד מִדָּתוֹ וְחוֹזֵר:","הִגִּיעַ לְכֹתֶל אֵין אוֹמְרִים יִקֹּב אֶת הַכֹּתֶל אֶלָּא אוֹמֵד רָחְבּוֹ וְהוֹלֵךְ לוֹ. וְאִם אֶפְשָׁר לְהִשְׁתַּמֵּשׁ בּוֹ מוֹדְדוֹ מְדִידָה יָפָה. וְאִם הָיָה חוּט הַמִּשְׁקלֶת יוֹרֵד כְּנֶגְדּוֹ מוֹדֵד רָחְבּוֹ מְדִידָה יָפָה:","הִגִּיעַ לְהַר אִם הָיָה הַר מִתְלַקֵּט מִמֶּנּוּ גָּבוֹהַּ עֲשָׂרָה טְפָחִים בְּאֹרֶךְ חָמֵשׁ אַמּוֹת מַבְלִיעוֹ וְחוֹזֵר לְמִדָּתוֹ. וְאִם הָיָה גָּבוֹהַּ הַרְבֵּה עַד שֶׁיִּתְלַקֵּט מִמֶּנּוּ עֲשָׂרָה טְפָחִים מִתּוֹךְ מֶשֶׁךְ אַרְבַּע אַמּוֹת אוֹמְדוֹ וְהוֹלֵךְ לוֹ. וְאִם אֵינוֹ יָכוֹל לְהַבְלִיעוֹ כְּגוֹן שֶׁהָיָה רָחְבּוֹ יֶתֶר מֵחֲמִשִּׁים מְקַדְּרוֹ מְעַט מְעַט. וְזֶה הוּא שֶׁאָמְרוּ מְקַדְּרִין בֶּהָרִים:","כֵּיצַד מְקַדְּרִין בְּהָרִים אוֹ בְּגֵיאָיוֹת שֶׁאֵינוֹ יָכוֹל לְהַבְלִיעָן. אוֹחֲזִין שְׁנַיִם חֶבֶל שֶׁל אַרְבַּע אַמּוֹת הָעֶלְיוֹן אוֹחֵז קְצָתוֹ מִכְּנֶגֶד מַרְגְּלוֹתָיו וְהַתַּחְתּוֹן אוֹחֵז בַּקָּצֶה הַשֵּׁנִי כְּנֶגֶד לִבּוֹ וְחוֹזֵר הָעֶלְיוֹן לַעֲמֹד בִּמְקוֹם הַתַּחְתּוֹן וְהַתַּחְתּוֹן יוֹרֵד וּמַרְחִיק מִמֶּנּוּ מִדַּת הַחֶבֶל וְכֵן מִתְגַּלְגְּלִים וְהוֹלְכִין עַד שֶׁמּוֹדְדִין אֶת כֻּלּוֹ. וּכְשֶׁיֵּלֵךְ הַמּוֹדֵד לְהַבְלִיעַ הָהָר אוֹ הַגַּיְא לֹא יֵצֵא חוּץ לַתְּחוּם שֶׁלֹּא יִרְאוּ אוֹתוֹ הָעוֹבְרִים וְיֹאמְרוּ מִדַּת תְּחוּמִין בָּאָה לְכָאן:","אֵין סוֹמְכִין אֶלָּא עַל מְדִידַת אָדָם מֻמְחֶה שֶׁהוּא יוֹדֵעַ מִדַּת הַקַּרְקַע. הָיוּ לָנוּ תְּחוּמֵי שַׁבָּת מֻחְזָקִין וּבָא מֻמְחֶה וּמָדַד רִבָּה בַּתְּחוּם מֵהֶן וּמִעֵט בַּתְּחוּם. שׁוֹמְעִין לוֹ בַּתְּחוּם שֶׁרִבָּה. וְכֵן אִם בָּאוּ שְׁנַיִם מֻמְחִין וּמָדְדוּ הַתְּחוּם אֶחָד רִבָּה וְאֶחָד מִעֵט שׁוֹמְעִין לַמְרַבֶּה. וּבִלְבַד שֶׁלֹּא יְרַבֶּה יֶתֶר מִמִּדַּת אֲלַכְסוֹנָהּ שֶׁל עִיר:","כֵּיצַד. בְּעֵת שֶׁיְּרַבֶּה זֶה נֹאמַר שֶׁמָּא הָרִאשׁוֹן מִקֶּרֶן אֲלַכְסוֹן שֶׁל עִיר מָדַד הָאַלְפַּיִם וּלְפִיכָךְ מִעֵט מִדָּתוֹ וְנִמְצָא צֶלַע הַתְּחוּם בֵּינוֹ וּבֵין הַמְּדִינָה פָּחוֹת מֵאַלְפַּיִם. וְזֶה הָאַחֲרוֹן מָדַד אַלְפַּיִם מִצֶּלַע הַמְּדִינָה. וְאֵין מַחֲזִיקִין עַל הָרִאשׁוֹן שֶׁטָּעָה בְּיוֹתֵר עַל זֶה. לְפִיכָךְ אִם רִבָּה זֶה הָאַחֲרוֹן יֶתֶר עַל הָרִאשׁוֹן אֲפִלּוּ בַּחֲמֵשׁ מֵאוֹת וּשְׁמוֹנִים אַמָּה בְּקֵרוּב שׁוֹמְעִין לוֹ. בְּיוֹתֵר עַל זֶה אֵין שׁוֹמְעִין לוֹ:","אֲפִלּוּ עֶבֶד אֲפִלּוּ שִׁפְחָה נֶאֱמָנִין לוֹמַר עַד כָּאן תְּחוּם הַשַּׁבָּת. וְנֶאֱמָן הַגָּדוֹל לוֹמַר זָכוּר אֲנִי שֶׁעַד כָּאן הָיִינוּ בָּאִים בְּשַׁבָּת כְּשֶׁהָיִיתִי קָטָן. וְסוֹמְכִין עַל עֵדוּתוֹ בְּדָבָר זֶה. שֶׁלֹּא אָמְרוּ חֲכָמִים בַּדָּבָר לְהַחֲמִיר אֶלָּא לְהָקֵל מִפְּנֵי שֶׁשִּׁעוּר אַלְפַּיִם אַמָּה מִדִּבְרֵיהֶם:"],"Mishneh Torah, Sabbatical Year and the Jubilee 11":["אֶרֶץ יִשְׂרָאֵל הַמִּתְחַלֶּקֶת לִשְׁבָטִים אֵינָהּ נמְכֶּרֶת לִצְמִיתוּת שֶׁנֶּאֱמַר (ויקרא כה כג) \"וְהָאָרֶץ לֹא תִמָּכֵר לִצְמִתֻת\". וְאִם מָכַר לִצְמִיתוּת שְׁנֵיהֶם עוֹבְרִין בְּלֹא תַּעֲשֶׂה. וְאֵין מַעֲשֵׂיהֶן מוֹעִילִין אֶלָּא תַּחֲזֹר הַשָּׂדֶה לִבְעָלֶיהָ בַּיּוֹבֵל:","וְהַמּוֹכֵר שָׂדֵהוּ לְשִׁשִּׁים שָׁנָה אֵינָהּ יוֹצְאָה בַּיּוֹבֵל שֶׁאֵין חוֹזֵר בַּיּוֹבֵל אֶלָּא דָּבָר הַנִמְכָּר סְתָם אוֹ הַנִמְכָּר לִצְמִיתוּת:","לֹא יִמְכֹּר אָדָם בֵּיתוֹ אוֹ שְׂדֵה אֲחֻזָּתוֹ אַף עַל פִּי שֶׁהֵם חוֹזְרִין אַחַר זְמַן אֶלָּא אִם כֵּן הֶעֱנִי שֶׁנֶּאֱמַר (ויקרא כה כה) \"וְכִי יָמוּךְ אָחִיךָ וּמָכַר מֵאֲחֻזָּתוֹ\". אֲבָל לִמְכֹּר וּלְהַנִּיחַ הַדָּמִים בְּכִיסוֹ אוֹ לַעֲשׂוֹת בָּהֶן סְחוֹרָה אוֹ לִקַּח בָּהֶן כֵּלִים אוֹ עֲבָדִים וּבְהֵמָה אֵינוֹ רַשַּׁאי אֶלָּא לִמְזוֹנוֹת בִּלְבַד. וְאִם עָבַר וּמָכַר מִכָּל מָקוֹם הֲרֵי אֵלּוּ מְכוּרִין:","וְדָנִין בְּבַיִת דִּין בָּתֵּי עָרֵי חוֹמָה וּבְשָׂדֶה דִּין שְׂדֵה אֲחֻזָּה. דִּין מוֹכֵר שְׂדֶה אֲחֻזָּתוֹ לְחַשֵּׁב אֶת הַדָּמִים לְפִי הַשָּׁנִים הַנִּשְׁאָרוֹת לַיּוֹבֵל. וּבְכָל עֵת שֶׁיִּרְצֶה לִפְדּוֹת מְחַשֵּׁב עִם הַלּוֹקֵחַ עַל הַשָּׁנִים שֶׁאָכַל. וְגוֹרֵעַ מִדְּמֵי הַמּוֹכֵר וּמַחֲזִיר לוֹ הַשְּׁאָר:","כֵּיצַד. הֲרֵי הַנִּשְׁאָר לַיּוֹבֵל עֶשֶׂר שָׁנִים וּמָכַר לוֹ שָׂדֶה בְּמֵאָה דִּינָר. אֲכָלָהּ הַלּוֹקֵחַ שָׁלֹשׁ שָׁנִים וְרָצָה הַמּוֹכֵר לִגְאל נוֹתֵן לוֹ שִׁבְעִים דִּינָר וּמַחֲזִיר שָׂדֵהוּ. וְכֵן אִם אֲכָלָהּ שֵׁשׁ שָׁנִים נוֹתֵן לוֹ אַרְבָּעִים דִּינָר וּמַחֲזִיר לוֹ שָׂדֵהוּ. לֹא גְאָלָהּ אֶלָּא הִנִּיחָהּ בְּיַד הַלּוֹקֵחַ עַד שְׁנַת הַיּוֹבֵל תַּחֲזֹר לַבְּעָלִים בְּלֹא דָּמִים שֶׁנֶּאֱמַר (ויקרא כה טו) \"בְּמִסְפַּר שְׁנֵי תְבוּאֹת יִמְכָּר לָךְ\":","מְכָרָהּ לוֹ וְהִיא מְלֵאָה פֵּרוֹת וּלְאַחַר שְׁתֵּי שָׁנִים גְאָלָהּ אֵינוֹ יָכוֹל לוֹמַר לוֹ הַחֲזִירֶנָּה לִי מְלֵאָה פֵּרוֹת כְּמוֹ שֶׁמָּכַרְתִּי לְךָ. לְפִיכָךְ אִם מְכָרָהּ לוֹ מְלֵאָה פֵּרוֹת לִפְנֵי רֹאשׁ הַשָּׁנָה וּגְאָלָהּ אַחַר שְׁתֵּי שָׁנִים הֲרֵי זֶה אוֹכֵל שָׁלֹשׁ תְּבוּאוֹת בִּשְׁתֵּי הַשָּׁנִים וְאֵינוֹ מְחַשֵּׁב עִמּוֹ אֶלָּא לְפִי שְׁתֵּי שָׁנִים בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כז יח) \"עַל פִּי הַשָּׁנִים\" לֹא עַל פִּי הַתְּבוּאוֹת:","הַקָּנִים וְהַזְּמוֹרוֹת וּפֵרוֹת שִׁקְמָה שֶׁבְּתוֹכָהּ הֲרֵי הֵן שֶׁל לוֹקֵחַ כִּשְׁאָר הַפֵּרוֹת שֶׁלָּהּ. אֲבָל אִילָן שֶׁנִּכְסַח אוֹ שֶׁיָּבַשׁ שְׁנֵיהֶן אֲסוּרִין בּוֹ. כֵּיצַד יַעֲשֶׂה. יִמָּכֵר וְיִלָּקַח בְּדָמָיו קַרְקַע וְהַלּוֹקֵחַ אוֹכֵל פֵּרוֹתֶיהָ עַד שֶׁתִּגָּאֵל הַשָּׂדֶה מִיָּדוֹ:","הַלּוֹקֵחַ שְׂדֵה אֲחֻזָּה וּנְטָעָהּ אִילָנוֹת וְהִשְׁבִּיחָה כְּשֶׁהִיא חוֹזֶרֶת בַּיּוֹבֵל שָׁמִין שֶׁבַח הָאִילָנוֹת שֶׁבְּתוֹכָהּ. וְנוֹתֵן בַּעַל הַשָּׂדֶה דְּמֵי הַשֶּׁבַח לַלּוֹקֵחַ שֶׁנֶּאֱמַר (ויקרא כה לג) \"וְיָצָא מִמְכַּר בַּיִת\" מִמְכָּר חוֹזֵר וְלֹא הַשֶּׁבַח:","הַמּוֹכֵר אֶת שָׂדֵהוּ בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג כְּמוֹ שֶׁבֵּאַרְנוּ אֵינוֹ מֻתָּר לִגְאל לְפָחוֹת מִשְּׁתֵּי שָׁנִים שֶׁנֶּאֱמַר (ויקרא כה טו) \"בְּמִסְפַּר שְׁנֵי תְבוּאֹת יִמְכָּר לָךְ\". וַאֲפִלּוּ רָצָה הַלּוֹקֵחַ אָסוּר שֶׁנֶּאֱמַר (ויקרא כה טו) \"בְּמִסְפַּר שָׁנִים אַחַר הַיּוֹבֵל תִּקְנֶה מֵאֵת עֲמִיתֶךָ\". אֵין פָּחוֹת מִשְּׁתֵּי שָׁנִים מֵעֵת לְעֵת מִיּוֹם הַמְּכִירָה:","וְצָרִיךְ שֶׁיֹּאכַל הַלּוֹקֵחַ שְׁתֵּי תְּבוּאוֹת בִּשְׁתֵּי שָׁנִים וְאַחַר כָּךְ יִגְאַל שֶׁנֶּאֱמַר (ויקרא כה טו) \"שְׁנֵי תְּבוּאוֹת\". לְפִיכָךְ אִם הָיְתָה אַחַת מִשְּׁתֵּי הַשָּׁנִים שְׁבִיעִית אוֹ שְׁנַת שִׁדָּפוֹן אוֹ יֵרָקוֹן אֵינָהּ עוֹלָה מִן הַמִּנְיָן:","הִנִּיחָהּ הַלּוֹקֵחַ בּוּרָה שָׁנָה וַאֲכָלָהּ שָׁנָה. אוֹ אֲכָלָהּ שָׁנָה וְנָרָהּ שָׁנָה וְלֹא זְרָעָהּ הֲרֵי אֵלּוּ עוֹלִין לַמִּנְיָן. מְכָרָהּ בִּשְׁנַת יוֹבֵל עַצְמָהּ אֵינָהּ נִמְכֶּרֶת וְהַדָּמִים חוֹזְרִין לַבְּעָלִים:","מְכָרָהּ שָׁנָה אַחַת לִפְנֵי הַיּוֹבֵל הֲרֵי הַלּוֹקֵחַ אוֹכֵל אוֹתָהּ שָׁנָה שְׁנִיָּה אַחַר הַיּוֹבֵל שֶׁנֶּאֱמַר (ויקרא כה טו) \"שְׁנֵי תְבוּאֹת\":","מָכַר נְקָעִים מְלֵאִים מַיִם אוֹ סְלָעִים שֶׁאֵינָם רְאוּיִין לִזְרִיעָה הֲרֵי זֶה פּוֹדֶה בְּפָחוֹת מִשְּׁתֵּי שָׁנִים שֶׁנֶּאֱמַר (ויקרא כה טו) \"בְּמִסְפַּר שְׁנֵי תְבוּאֹת\". שָׂדֶה הָרָאוּי לַתְּבוּאָה הִיא שֶׁאֵינָהּ נִגְאֶלֶת אֶלָּא אַחַר שְׁתֵּי שָׁנִים. וְאִם לֹא גְּאָלָהּ אַף עַל פִּי שֶׁאֵינָהּ רְאוּיָה לִזְרִיעָה חוֹזֶרֶת לַבְּעָלִים בַּיּוֹבֵל:","מָכַר אִילָנוֹת אֵין נִגְאָלִין לְפָחוֹת מִשְּׁתֵּי שָׁנִים שֶׁהֲרֵי רְאוּיִים לִתְבוּאוֹת. וְאִם לֹא גְּאָלָן אֵינָן חוֹזְרִין לַבְּעָלִים בַּיּוֹבֵל שֶׁנֶּאֱמַר (ויקרא כה כז כח) \"וְשָׁב לַאֲחֻזָּתוֹ\" וְלֹא לָאִילָנוֹת:","מָכַר שָׂדֵהוּ לְרִאשׁוֹן וְרִאשׁוֹן מָכַר לְשֵׁנִי וְשֵׁנִי לִשְׁלִישִׁי אֲפִלּוּ מֵאָה זֶה אַחַר זֶה בִּשְׁנַת הַיּוֹבֵל תַּחֲזֹר לָאָדוֹן הָרִאשׁוֹן. שֶׁנֶּאֱמַר (ויקרא כז כד) \"בִּשְׁנַת הַיּוֹבֵל יָשׁוּב הַשָּׂדֶה לַאֲשֶׁר קָנָהוּ מֵאִתּוֹ לַאֲשֶׁר לוֹ אֲחֻזַּת הָאָרֶץ\":","מְכָרָהּ לְרִאשׁוֹן בְּמֵאָה דִּינָר וְרִאשׁוֹן לְשֵׁנִי בְּמָאתַיִם וְרָצָה הָאָדוֹן לִגְאל אֵינוֹ מְחַשֵּׁב אֶלָּא עִם הָרִאשׁוֹן שֶׁנֶּאֱמַר (ויקרא כה כז) \"לָאִישׁ אֲשֶׁר מָכַר לוֹ\". מְכָרָהּ לְרִאשׁוֹן בְּמָאתַיִם וְרִאשׁוֹן לְשֵׁנִי בְּמֵאָה הֲרֵי זֶה מְחַשֵּׁב עִם הָאַחֲרוֹן. וְכֵן אִם מָכַר בְּמֵאָה וְהִשְׁבִּיחָה בְּיַד הַלּוֹקֵחַ וַהֲרֵי הִיא רְאוּיָה לְהִמָּכֵר בְּמָאתַיִם מְחַשֵּׁב לְפִי מַה שֶּׁמָּכַר. וְאִם מְכָרָהּ בְּמָאתַיִם וְהִכְסִיפָה וַהֲרֵי הִיא רְאוּיָה לְהִמָּכֵר בְּמֵאָה מְחַשֵּׁב לְפִי מַה שֶּׁהִיא. וּלְעוֹלָם מְיַפִּים כֹּחַ מוֹכֵר שְׂדֵה אֲחֻזָּה וּמְרֵעִין כֹּחַ הַלּוֹקֵחַ:","הַמּוֹכֵר שְׂדֵה אֲחֻזָּתוֹ וְהָיוּ לוֹ שָׂדוֹת אֲחֵרוֹת וּמָכַר מֵאוֹתָם הַשָּׂדוֹת כְּדֵי לִגְאל שָׂדֶה שֶׁמָּכַר אֵין שׁוֹמְעִין לוֹ. שֶׁנֶּאֱמַר (ויקרא כה כו) \"וּמָצָא כְּדֵי גְאֻלָּתוֹ\" עַד שֶׁיִּמְצָא דָּבָר שֶׁאֵינוֹ מָצוּי לוֹ בְּשָׁעָה שֶׁמָּכַר. וְכֵן אִם לָוָה לִגְאל אֵין שׁוֹמְעִין לוֹ שֶׁנֶּאֱמַר (ויקרא כה כו) \"וְהִשִּׂיגָה יָדוֹ\" לֹא שֶׁיִּלְוֶה:","מָצָא מְעַט וְרָצָה לִגְאל חֲצִי הַשָּׂדֶה שֶׁמָּכַר אֵין שׁוֹמְעִין לוֹ שֶׁנֶּאֱמַר (ויקרא כה כו) \"כְּדֵי גְאֻלָּתוֹ\". אוֹ גּוֹאֵל אֶת כֻּלָּהּ אוֹ אֵינוֹ גּוֹאֵל. וְאִם רָצוּ קְרוֹבָיו לִגְאל גּוֹאֲלִים שֶׁנֶּאֱמַר (ויקרא כה כה) \"וּבָא גֹאֲלוֹ הַקָּרֹב אֵלָיו\":","הַנּוֹתֵן שָׂדֵהוּ מַתָּנָה הֲרֵי זוֹ חוֹזֶרֶת לוֹ בַּיּוֹבֵל שֶׁנֶּאֱמַר (ויקרא כה יג) \"תָּשֻׁבוּ אִישׁ אֶל אֲחֻזָּתוֹ\" לְרַבּוֹת אֶת הַמַּתָּנָה:","הָאַחִין שֶׁחָלְקוּ כְּלָקוֹחוֹת הֵן וּמַחְזִירִין זֶה לָזֶה חֶלְקוֹ בַּיּוֹבֵל. לֹא תִּבָּטֵל חֲלוּקָתָן מִכְּמוֹת שֶׁהָיְתָה. וְכֵן הַבְּכוֹר וְהַמְיַבֵּם אֵשֶׁת אָחִיו מַחֲזִיר בַּיּוֹבֵל חֵלֶק שֶׁנָּטַל וְנוֹטֵל הַחֵלֶק שֶׁכְּנֶגְדּוֹ:","אֲבָל הַיּוֹרֵשׁ אֶת אִשְׁתּוֹ אַף עַל פִּי שֶׁיְּרֻשַּׁת הַבַּעַל מִדִּבְרֵיהֶם עָשׂוּ חִזּוּק לְדִבְרֵיהֶם כְּשֶׁל תּוֹרָה וְאֵינוֹ מַחֲזִיר בַּיּוֹבֵל. וְאִם יָרַשׁ מִמֶּנָּה בֵּית הַקְּבָרוֹת יַחֲזִיר לִבְנֵי מִשְׁפָּחָה מִשּׁוּם פְּגַם מִשְׁפָּחָה וְיִתְּנוּ לוֹ דָּמֶיהָ וּמְנַכִּין לוֹ דְּמֵי קֶבֶר אִשְׁתּוֹ שֶׁהֲרֵי חַיָּב בִּקְבוּרָתָהּ:"],"Mishneh Torah, Sacrifices Rendered Unfit 10":["הָאִשָׁה שֶׁאָמְרָה הֲרֵי עָלַי קֵן כְּשֶׁאֵלֵד זָכָר. יָלְדָה זָכָר מְבִיאָה אַרְבָּעָה עוֹפוֹת. שְׁנַיִם לְנִדְרָהּ וְהֵן עוֹלָה כְּמוֹ שֶׁבֵּאַרְנוּ. וּשְׁנַיִם לְחוֹבָתָהּ מִשּׁוּם לֵידָה וְהֵן אֶחָד עוֹלָה וְאֶחָד חַטָּאת. נִמְצֵאתָ לָמֵד שֶׁהַכֹּהֵן צָרִיךְ לַעֲשׂוֹת שָׁלֹשׁ פְּרֵדִין לְמַעְלָה. וּפְרֵדָה אַחַת לְמַטָּה. טָעָה וְעָשָׂה שְׁתַּיִם לְמַעְלָה וּשְׁתַּיִם לְמַטָּה וְלֹא נִמְלַךְ צְרִיכָה לְהָבִיא עוֹד פְּרֵדָה אַחַת וְיַקְרִיבֶנָּה לְמַעְלָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֵבִיאָה הָאַרְבָּעָה מִמִּין אֶחָד כְּגוֹן שֶׁהָיוּ כֻּלָּן תּוֹרִין אוֹ בְּנֵי יוֹנָה. אֲבָל אִם הָיוּ שְׁתֵּי תּוֹרִין עִם שְׁנֵי בְּנֵי יוֹנָה וְעָשָׂה שְׁנַיִם לְמַעְלָה וּשְׁנַיִם לְמַטָּה. צְרִיכָה לְהָבִיא עוֹד תּוֹר וּבֶן יוֹנָה וְיַעֲשֶׂה שְׁתֵּיהֶן לְמַעְלָה כְּדֵי לָצֵאת יְדֵי חוֹבָתָהּ. שֶׁאִם עָשָׂה בַּתְּחִלָּה שְׁתֵּי הַתּוֹרִין לְמַטָּה צְרִיכָה תּוֹר לְמַעְלָה לְהַשְׁלִים חוֹבָתָהּ. וְאִם עָשָׂה שְׁנֵי בְּנֵי הַיּוֹנָה לְמַטָּה צְרִיכָה בֶּן יוֹנָה לְמַעְלָה לְהַשְׁלִים חוֹבָתָהּ. שֶׁאֵין אָדָם מֵבִיא חוֹבָתוֹ גּוֹזָל אֶחָד תּוֹר אַחַת אוֹ בֶּן יוֹנָה אֶלָּא אוֹ שְׁנֵיהֶן תּוֹרִין אוֹ שְׁנֵיהֶן בְּנֵי יוֹנָה:","פֵּרְשָׁה נִדְרָהּ וְאָמְרָה לַכֹּהֵן אֵלּוּ לְנִדְרִי וְאֵלּוּ לְחוֹבָתִי. וַעֲשָׂאָם הַכֹּהֵן שְׁתַּיִם לְמַעְלָה וּשְׁתַּיִם לְמַטָּה וְלֹא יָדַע אֵי זֶה מֵהֶן עָשָׂה לְמַעְלָה וְאֵי זֶה מֵהֶן עָשָׂה לְמַטָּה. צְרִיכָה לְהָבִיא שְׁלֹשָׁה עוֹפוֹת. שְׁנַיִם לְנִדְרָהּ וְאֶחָד לְהַשְׁלִים חוֹבָתָהּ. וְיֵעָשׂוּ הַשְּׁנַיִם לְמַעְלָה שֶׁהֲרֵי פֵּרְשָׁה נִדְרָהּ וְשֶׁמָּא שְׁנַיִם שֶׁל נִדְרָהּ נַעֲשָׂה לְמַטָּה שֶׁהֵם פְּסוּלוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהֵבִיאָה הָאַרְבָּעָה שֶׁפֵּרְשָׁה נִדְרָהּ בִּשְׁנַיִם מֵהֶן מִמִּין אֶחָד. אֲבָל אִם הָיוּ שְׁנֵי מִינִין תָּבִיא אַרְבָּעָה אֲחֵרִים. שְׁנַיִם מִמִּין שֶׁפֵּרְשָׁה בּוֹ נִדְרָהּ יֵעָשׂוּ לְנִדְרָהּ וּשְׁנַיִם מֵאֵי זֶה מִין שֶׁתִּרְצֶה יִהְיוּ לְחוֹבָתָהּ וְיֵעָשׂוּ אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה:","קָבְעָה נִדְרָהּ וְאָמְרָה אִם אֵלֵד זָכָר הֲרֵי עָלַי שְׁתֵּי תּוֹרִים. וְיָלְדָה וְהֵבִיאָה אַרְבָּעָה עוֹפוֹת. שְׁנַיִם לְנִדְרָהּ וּשְׁנַיִם לְחוֹבָתָהּ. וְעָשָׂה שְׁנַיִם לְמַעְלָה וּשְׁנַיִם לְמַטָּה וְלֹא יָדַע אֵי זֶה נַעֲשָׂה לְמַעְלָה וְאֵי זֶה נַעֲשָׂה לְמַטָּה. וְגַם הִיא שָׁכְחָה וְלֹא יָדְעָה בְּאֵי זֶה מִין קָבְעָה נִדְרָהּ אִם בְּתוֹרִים אוֹ בִּבְנֵי הַיּוֹנָה. הֲרֵי זוֹ צְרִיכָה לְהָבִיא שְׁתֵּי תּוֹרִים עִם שְׁנֵי בְּנֵי יוֹנָה לְנִדְרָהּ וְיֵעָשׂוּ אַרְבַּעְתָּן לְמַעְלָה. וְתָבִיא גּוֹזָל אֶחָד לְהַשְׁלִים חוֹבָתָהּ וְיֵעָשֶׂה לְמַעְלָה. (שֶׁכְּבָר עָשָׂה שְׁנַיִם לְמַטָּה שֶׁהֵם חַטָּאת). בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֵבִיאָה הָאַרְבָּעָה תְּחִלָּה מִמִּין אֶחָד. אֲבָל אִם הָיוּ שְׁנֵי מִינִין צְרִיכָה לְהָבִיא שִׁשָּׁה עוֹפוֹת. שְׁתֵּי תּוֹרִים עִם שְׁנֵי בְּנֵי יוֹנָה לְנִדְרָהּ. וְתָבִיא לְחוֹבָתָהּ שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה וְיֵעָשֶׂה אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה. וְכֵן אִם נְתָנָתַם לַכֹּהֵן וְשָׁכְחָה מַה נָּתְנָה לוֹ. וְהָלַךְ הַכֹּהֵן וְעָשָׂה וְאֵינוֹ יוֹדֵעַ הֵיכָן עָשָׂה אִם הַכּל לְמַעְלָה אוֹ הַכּל לְמַטָּה אוֹ מֶחֱצָה לְמַעְלָה וּמֶחֱצָה לְמַטָּה. הֲרֵי זוֹ תָּבִיא שְׁתֵּי תּוֹרִים עִם שְׁנֵי בְּנֵי יוֹנָה לְנִדְרָהּ. וְתָבִיא שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה לְחוֹבָתָהּ:","קָבְעָה חוֹבָתָהּ וְקָבְעָה נִדְרָהּ וְשָׁכְחָה בַּמֶּה קָּבְעָה. וְאֶפְשָׁר שֶׁחוֹבָתָהּ כֶּבֶשׂ לְעוֹלָה וּפְרֵדָה אַחַת תּוֹר אוֹ בֶּן יוֹנָה לְחַטָּאת. לְפִיכָךְ תָּבִיא שִׁשָּׁה פְּרֵדִין. אַרְבָּעָה לְנִדְרָהּ וּשְׁנַיִם לְחוֹבָתָהּ. וְעוֹד תָּבִיא חַטָּאת אֶחָד בֶּן יוֹנָה אוֹ תּוֹר עִם כֶּבֶשׂ. נִמְצֵאת שֶׁהֵבִיאָה שִׁבְעָה עוֹפוֹת [וְכֶבֶשׂ]:","וְכָל הַחַטָּאוֹת הָאֵלּוּ אֵינָן נֶאֱכָלוֹת מִפְּנֵי שֶׁהֵם סָפֵק:"],"Mishneh Torah, Sacrifices Rendered Unfit 4":["וְלַד חַטָּאת וּתְמוּרַת חַטָּאת וְחַטָּאת שֶׁמֵּתוּ בְּעָלֶיהָ וְחַטָּאת שֶׁאָבְדָה וְנִמְצֵאת אַחַר שֶׁכִּפְּרוּ הַבְּעָלִים הֲרֵי אֵלּוּ יָמוּתוּ. נִמְצֵאת אַחַר שֶׁנִּשְׁחֲטָה הַחַטָּאת הַשְּׁנִיָּה שֶׁהִפְרִישׁ קֹדֶם שֶׁיִּזָּרֵק דָּמָהּ. הֲרֵי זוֹ סָפֵק אִם תָּמוּת אִם תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם. לְפִיכָךְ תָּמוּת. וְכֵיצַד הֵן מֵתוֹת. לֹא שֶׁיַּהַרְגֵם בִּכְלִי אוֹ בְּיָדוֹ אֶלָּא יַכְנִיסֵם לְבַיִת וְנוֹעֵל עֲלֵיהֶם עַד שֶׁיָּמוּתוּ. וּדְבָרִים אֵלּוּ כֻּלָּם מִפִּי משֶׁה רַבֵּנוּ נִשְׁמְעוּ. אֵין כָּל הַדְּבָרִים אֲמוּרִים אֶלָּא בְּחַטַּאת יָחִיד בִּלְבַד. אֲבָל חַטַּאת צִבּוּר שֶׁאָבְדָה וְנִמְצֵאת אַחַר כַּפָּרָה בֵּין רְאוּיָה בֵּין אֵינָהּ רְאוּיָה תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְתִמָּכֵר וְיִפְּלוּ דָּמֶיהָ לִנְדָבָה. וְאֵין אַתָּה יָכוֹל לוֹמַר בְּחַטַּאת צִבּוּר וָלָד אוֹ תְּמוּרָה אוֹ שֶׁמֵּתוּ בְּעָלֶיהָ. שֶׁכָּל קָרְבְּנוֹת הַצִּבּוּר זְכָרִים וְאֵין הַצִּבּוּר עוֹשִׂין תְּמוּרָה כְּמוֹ שֶׁיִּתְבָּאֵר וְאֵין כָּל יִשְׂרָאֵל מֵתִים:","פַּר וְשָׂעִיר שֶׁל יוֹם הַכִּפּוּרִים שֶׁאָבְדוּ וְהִפְרִישׁ אֲחֵרִים תַּחְתֵּיהֶן. וְכֵן שְׂעִירֵי עֲבוֹדָה זָרָה שֶׁאָבְדוּ וְהִפְרִישׁ אֲחֵרִים תַּחְתֵּיהֶן. יִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיִמָּכְרוּ וְיִפְּלוּ דְּמֵיהֶן לִנְדָבָה. שֶׁאֵין חַטַּאת הַצִּבּוּר מֵתָה. וְלָמָּה לֹא יִקְרְבוּ עַצְמָן נְדָבָה שֶׁהֲרֵי זְכָרִים הֵם. גְּזֵרָה לְאַחַר כַּפָּרָה מִשּׁוּם לִפְנֵי כַּפָּרָה:","הַמַּפְרִישׁ חַטָּאתוֹ וְאָבְדָה וְהִפְרִישׁ אַחֶרֶת תַּחְתֶּיהָ וְנִמְצֵאת הָרִאשׁוֹנָה וַהֲרֵי שְׁתֵּיהֶם עוֹמְדוֹת. מָשַׁךְ אַחַת מִשְּׁתֵיהֶן וְנִתְכַּפֵּר בָּהּ הָאַחֶרֶת תָּמוּת. בָּא לְהִמָּלֵךְ אוֹמְרִין לוֹ שֶׁיִּתְכַּפֵּר בָּזוֹ שֶׁהִפְרִישׁ בָּרִאשׁוֹנָה וְהַשְּׁנִיָּה תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְיִפְּלוּ דָּמֶיהָ לִנְדָבָה. הָיְתָה אַחַת מֵהֶן תְּמִימָה וְאַחַת בַּעֲלַת מוּם. תְּמִימָה תִּקָּרֵב וּבַעֲלַת מוּם תִּפָּדֶה. נִשְׁחֲטָה בַּעֲלַת מוּם קֹדֶם שֶׁיִּזָּרֵק דַּם הַתְּמִימָה הֲרֵי זוֹ אֲסוּרָה בַּהֲנָאָה. הָיוּ שְׁתֵּיהֶן בַּעֲלֵי מוּמִין יִמָּכְרוּ שְׁתֵּיהֶן וְיָבִיא מִדְּמֵיהֶם חַטָּאת וְהַשְּׁאָר יִפּל לִנְדָבָה:","הִפְרִישׁ חַטָּאתוֹ וְאָבְדָה. וְהִפְרִישׁ אַחֶרֶת תַּחְתֶּיהָ וְאָבְדָה. וְהִפְרִישׁ אַחֶרֶת וְנִמְצְאוּ הָאוֹבְדוֹת וַהֲרֵי שְׁלָשְׁתָּן עוֹמְדוֹת וְנִתְכַּפֵּר בָּרִאשׁוֹנָה. שְׁנִיָּה מֵתָה וּשְׁלִישִׁית רוֹעָה. נִתְכַּפֵּר בַּשְּׁלִישִׁית שְׁנִיָּה מֵתָה וְרִאשׁוֹנָה רוֹעָה. נִתְכַּפֵּר בָּאֶמְצָעִית שְׁתֵּיהֶם מֵתוֹת:","הַמַּפְרִישׁ שְׁתֵּי חַטָּאוֹת לְאַחֲרָיוּת. מִתְכַּפֵּר בְּאֵי זוֹ שֶׁיִּרְצֶה וְהַשְּׁנִיָּה תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְיִפְּלוּ דָּמֶיהָ לִנְדָבָה:","הִפְרִישׁ חַטָּאת מְעֻבֶּרֶת וְיָלְדָה. הֲרֵי הִיא וּוְלָדָהּ כִּשְׁתֵּי חַטָּאוֹת שֶׁנִּתְפָּרְשׁוּ לְאַחֲרָיוּת:","הַמַּפְרִישׁ חַטָּאתוֹ וְעָבְרָה שְׁנָתָהּ. תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְתִמָּכֵר וְיָבִיא בְּדָמֶיהָ אַחֶרֶת. וְכֵן אִם הִפְרִישׁ חַטָּאתוֹ וְנָפַל בָּהּ מוּם יָבִיא בְּדָמֶיהָ אַחֶרֶת:","כָּל חַטָּאת שֶׁאָבְדָה וְנִמְצֵאת קֹדֶם כַּפָּרָה. (אַף עַל פִּי שֶׁנִּמְצֵאת בַּעֲלַת מוּם אוֹ שֶׁנִּמְצֵאת אַחַר שֶׁעָבְרָה שְׁנָתָהּ) אֵינָהּ מֵתָה אֶלָּא תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְיִפְּלוּ דָּמֶיהָ לִנְדָבָה. נִמְצֵאת אַחַר כַּפָּרָה אַף עַל פִּי שֶׁנִּמְצֵאת בַּעֲלַת מוּם אוֹ עָבְרָה שְׁנָתָהּ הוֹאִיל וְהָיְתָה אֲבוּדָה בִּשְׁעַת כַּפָּרָה הֲרֵי זוֹ תָּמוּת:","הָיְתָה גְּנוּבָה אוֹ גְּזוּלָה בִּשְׁעַת כַּפָּרָה וְאַחַר כָּךְ חָזְרָה. אֵינָהּ מֵתָה אֶלָּא תִּרְעֶה. לֹא שָׁמְעוּ מִמּשֶׁה רַבֵּנוּ אֶלָּא אֲבוּדָה. הָיְתָה עִקַּר אֲבֵדָתָהּ בַּלַּיְלָה אַף עַל פִּי שֶׁהָיְתָה אֲבוּדָה בִּשְׁעַת כַּפָּרָה. אֵינָהּ מֵתָה אֶלָּא תִּרְעֶה:","אָבְדָה מִמֶּנּוּ וְלֹא מִן הָרוֹעֶה. אוֹ שֶׁאָבְדָה מִן הָרוֹעֶה וְאֵינָהּ אֲבוּדָה מִבְּעָלֶיהָ. אֵינָהּ מֵתָה אֶלָּא רוֹעָה:","וְכָל אֵלּוּ שֶׁרוֹעוֹת רוֹעוֹת עַד שֶׁיִּפּל בָּהֶן מוּם וְיִפְּלוּ דְּמֵיהֶן לִנְדָבָה:","הָיְתָה אֲבוּדָה מִמֶּנּוּ וּמִן הָרוֹעֶה וְאַחֵר מַכִּירָה. אֲפִלּוּ בְּסוֹף הָעוֹלָם. הֲרֵי זוֹ סָפֵק לְפִיכָךְ תָּמוּת:","הָיְתָה נֶחְבֵּאת אֲחוֹרֵי הַדֶּלֶת אוֹ בְּסֵתֶר הַמַּדְרֵגָה הֲרֵי זוֹ אֲבוּדָה. שֶׁהֲרֵי אֵין אָדָם רוֹאֶה אוֹתָהּ בִּשְׁעַת כַּפָּרָה. הָיְתָה בַּשָּׂדֶה אוֹ בַּאֲגַם הֲרֵי זוֹ סָפֵק אֲבוּדָה שֶׁמָּא יֵשׁ שָׁם אָדָם רוֹאֶה אוֹתָהּ בִּשְׁעַת כַּפָּרָה. לְפִיכָךְ תָּמוּת מִסָּפֵק:","הַשּׁוֹלֵחַ חַטָּאתוֹ מִמְּדִינַת הַיָּם. מַקְרִיבִין אוֹתָהּ בְּחֶזְקַת שֶׁהוּא קַיָּם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּחַטַּאת הָעוֹף. אוֹ בְּחַטַּאת בְּהֵמָה שֶׁל אִשָּׁה שֶׁאֵינָהּ בַּת סְמִיכָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אָשָׁם וַדַּאי שֶׁמֵּתוּ בְּעָלָיו. וְשֶׁכִּפְּרוּ בְּעָלָיו. יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִמָּכֵר וְיִפְּלוּ דָּמָיו לִנְדָבָה. שֶׁכָּל שֶׁבְּחַטָּאת תָּמוּת בְּאָשָׁם יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִפְּלוּ דָּמָיו לִנְדָבָה:","כָּל אָשָׁם שֶׁנִּתַּק לִרְעִיָּה. אִם הִקְרִיבוֹ עוֹלָה כָּשֵׁר. וְלָמָּה לֹא יִקָּרֵב בְּעַצְמוֹ עוֹלָה לְכַתְּחִלָּה. גְּזֵרָה לְאַחַר כַּפָּרָה מִשּׁוּם לִפְנֵי כַּפָּרָה:","הַמַּפְרִישׁ נְקֵבָה לַאֲשָׁמוֹ תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְתִמָּכֵר וְיָבִיא בְּדָמֶיהָ אָשָׁם. אִם הִקְרִיב אֲשָׁמוֹ יִפְּלוּ דָּמֶיהָ לִנְדָבָה. וְכֵן וְלָדָהּ:","הִפְרִישׁ נְקֵבָה לְעוֹלָתוֹ וְיָלְדָה זָכָר יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיָבִיא בְּדָמָיו עוֹלָה:","אֲבָל הֶדְיוֹט שֶׁהִפְרִישׁ זָכָר לְחַטָּאת וְנָשִׂיא שֶׁהִפְרִישׁ שְׂעִירָה לְחַטָּאת. וְכֹהֵן מָשִׁיחַ שֶׁהִפְרִישׁ פָּרָה לְחַטָּאת הֲרֵי אֵלּוּ אֵין מִתְקַדְּשִׁין לֹא קְדֻשַּׁת הַגּוּף וְלֹא קְדֻשַּׁת דָּמִים. לְפִיכָךְ יִמָּכְרוּ שֶׁלֹּא בְּמוּם:","הֵבִיא אָשָׁם תָּלוּי וְנוֹדַע לוֹ שֶׁלֹּא חָטָא אוֹ שֶׁחָטָא וַדַּאי. אִם עַד שֶׁלֹּא נִשְׁחַט יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִפְּלוּ דָּמָיו לִנְדָבָה מִפְּנֵי שֶׁלִּבּוֹ שֶׁל אָדָם דָוֶה עַל עֲוֹנוֹתָיו וְהוֹאִיל וְעַל סָפֵק הִפְרִישׁוֹ גָּמַר בְּלִבּוֹ לְהַקְדִּישׁ. הִפְרִישׁ אֲפִלּוּ עַל פִּי עֵדִים וְהוּזַמּוּ יִפְּלוּ דָּמָיו לִנְדָבָה. וְאִם אַחַר שֶׁנִּשְׁחַט נוֹדַע לוֹ. הַדָּם יִשָּׁפֵךְ וְהַבָּשָׂר יִשָּׂרֵף כִּשְׁאָר פְּסוּלֵי הַמֻּקְדָּשִׁין. נוֹדַע לוֹ אַחַר שֶׁנִּזְרַק הַדָּם. הַבָּשָׂר יֵאָכֵל לַכֹּהֲנִים כְּכָל הָאֲשָׁמוֹת:","אָשָׁם וַדַּאי אֵינוֹ כֵּן. אִם עַד שֶׁלֹּא נִשְׁחַט נוֹדַע לוֹ שֶׁלֹּא חָטָא יֵצֵא וְיִרְעֶה בָּעֵדֶר כִּשְׁאָר הַחֻלִּין וְאֵין בּוֹ קְדֻשָּׁה כְּלָל. וְאִם מִשֶּׁנִּשְׁחַט הֲרֵי זֶה יִקָּבֵר. וְאִם מִשֶּׁנִּזְרַק הַדָּם. הַבָּשָׂר יֵצֵא לְבֵית הַשְּׂרֵפָה כִּשְׁאָר פְּסוּלֵי הַמֻּקְדָּשִׁין:","מִי שֶׁנִּתְחַיֵּב בְּאָשָׁם תָּלוּי וְהִפְרִישׁ שְׁנַיִם לְאַחֲרָיוּת. מִתְכַּפֵּר בְּאֶחָד וְהַשֵּׁנִי יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִפְּלוּ דָּמָיו לִנְדָבָה. וְאֵין צָרִיךְ לוֹמַר בְּאָשָׁם וַדַּאי שֶׁהוּא כֵּן:","כָּל הָאֲשָׁמוֹת שֶׁבַּתּוֹרָה בָּאִין בְּנֵי שְׁתַּיִם וּבָאִים בְּכֶסֶף שְׁקָלִים. חוּץ מֵאֲשַׁם מְצֹרָע וַאֲשַׁם נָזִיר שֶׁהֵם בְּנֵי שָׁנָה וְאֵין לִדְמֵיהֶם קִצְבָה. אָשָׁם תָּלוּי בָּא מִן הַקְּטַנִּים אוֹ מִן הַגְּדוֹלִים. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵינוֹ בָּא אֶלָּא בְּכֶסֶף שְׁקָלִים:","הוּזְלוּ אֵילִים וְלֹא יִמָּצֵא אַיִל בִּשְׁתֵּי סְלָעִים אֵין לוֹ תַּקָּנָה אֶלָּא יִשְׁהֵא עַד שֶׁיּוּקְרוּ וְיָבִיא בִּשְׁתֵּי סְלָעִים שֶׁהֲרֵי הִקְפִּידָה תּוֹרָה עַל דָּמָיו וְנָתְנָה לוֹ קִצְבָה:","הִפְרִישׁ אֲשָׁמוֹ וְהָיָה בִּשְׁעַת הַפְרָשָׁה יָפֶה סֶלַע וּבִשְׁעַת כַּפָּרָה יָפֶה שְׁתַּיִם כָּשֵׁר. שֶׁהַדָּחוּי מֵעִקָּרוֹ אֵינוֹ דָּחוּי וַעֲדַיִן לֹא נִרְאֶה עַד שֶׁנַּעֲשָׂה שָׁוֶה שְׁתַּיִם. וְאַף עַל פִּי שֶׁהִשְׁבִּיחַ מֵאֵלָיו אָדָם מִתְכַּפֵּר בְּשֶׁבַח הֶקְדֵּשׁ. הָיָה בִּשְׁעַת הַפְרָשָׁה יָפֶה שְׁתַּיִם וּבִשְׁעַת כַּפָּרָה יָפֶה סֶלַע הֲרֵי זֶה פָּסוּל. חָזַר וְנַעֲשָׂה יָפֶה שְׁתַּיִם יַחְזֹר לְכַשְׁרוּתוֹ שֶׁאֵין בַּעֲלֵי חַיִּים נִדְחִין כְּמוֹ שֶׁבֵּאַרְנוּ. לְמָה הַדָּבָר דּוֹמֶה לְמוּם שֶׁנָּפַל וְעָבַר:","הִפְרִישׁ שְׁתֵּי סְלָעִים לְאָשָׁם וְלָקַח בָּהֶם שְׁנֵי אֵילִים לְאָשָׁם. אִם הָיָה אֶחָד מֵהֶן יָפֶה שְׁתֵּי סְלָעִים יִקָּרֵב לַאֲשָׁמוֹ וְהַשֵּׁנִי יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיִפְּלוּ דָּמָיו לִנְדָבָה:","הָיָה חַיָּב בְּאָשָׁם בֶּן שָׁנָה וְהֵבִיא בֶּן שְׁתַּיִם אוֹ בְּבֶן שְׁתַּיִם וְהֵבִיא בֶּן שָׁנָה. אוֹ שֶׁשְּׁחָטוֹ מְחֻסַּר זְמַן בַּבְּעָלִים. פָּסוּל וּתְעֵבַּר צוּרָתוֹ וְיֵצֵא לְבֵית הַשְּׂרֵפָה. זֶה הַכְּלָל כָּל הַפָּסוּל בְּחַטָּאת פָּסוּל בְּאָשָׁם. חוּץ מִן הָאָשָׁם שֶׁשְּׁחָטוֹ שֶׁלֹּא לִשְׁמוֹ שֶׁהוּא כָּשֵׁר כְּמוֹ שֶׁיִּתְבָּאֵר:","עוֹלַת נָזִיר. עוֹלַת יוֹלֶדֶת. עוֹלַת מְצֹרָע. שֶׁשְּׁחָטָן בְּנֵי שְׁנֵים עָשָׂר חֹדֶשׁ וְיוֹם אֶחָד. אוֹ מְחֻסְּרֵי זְמַן בִּבְעָלִים. כְּשֵׁרִים וּטְעוּנִין נְסָכִים. זֶה הַכְּלָל כָּל שֶׁאֵינוֹ פּוֹסֵל בְּעוֹלַת נְדָבָה אֵינוֹ פּוֹסֵל בְּעוֹלַת חוֹבָה. בֵּין עָלְתָה לַבְּעָלִים בֵּין שֶׁלֹּא עָלְתָה לָהֶם:"],"Mishneh Torah, Sacrificial Procedure 15":["הָאוֹמֵר וְלָדָהּ שֶׁל זוֹ עוֹלָה וִהִיא שְׁלָמִים דְּבָרָיו קַיָּמִים. הִיא שְׁלָמִים וּוְלָדָהּ עוֹלָה. אִם לְכָךְ נִתְכַּוֵּן דְּבָרָיו קַיָּמִים. וְאִם אַחַר שֶׁגָּמַר בְּלִבּוֹ וְהוֹצִיא בִּשְׂפָתָיו שֶׁתִּהְיֶה שְׁלָמִים חָזַר בּוֹ וְאָמַר וּוְלָדָהּ עוֹלָה. אַף עַל פִּי שֶׁחָזַר בּוֹ בְּתוֹךְ כְּדֵי דִּבּוּר הֲרֵי וְלָדָהּ שְׁלָמִים. שֶׁאֵין חֲזָרָה בְּהֶקְדֵּשׁ וַאֲפִלּוּ בְּתוֹךְ כְּדֵי דִּבּוּר:","הָאוֹמֵר יָדָהּ שֶׁל זוֹ עוֹלָה אוֹ רַגְלָהּ שֶׁל זוֹ עוֹלָה תִּמָּכֵר לְחַיָּבֵי עוֹלוֹת וְדָמֶיהָ חֻלִּין חוּץ מִדְּמֵי אוֹתוֹ אֵיבָר. וְהוּא שֶׁיִּהְיֶה זֶה הַמְחֻיָּב עוֹלָה שֶׁקָּנָה אוֹתָהּ נָדַר עוֹלָה בְּדָמִים קְצוּבִים. הָאוֹמֵר לִבָּהּ אוֹ רֹאשָׁהּ שֶׁל זוֹ עוֹלָה. הוֹאִיל וְדָבָר שֶׁהַנְּשָׁמָה תְּלוּיָה בּוֹ הוּא כֻּלָּהּ עוֹלָה. הִקְדִּישׁ אֵיבָר אֶחָד מִן הָעוֹף הֲרֵי זֶה סָפֵק אִם נִתְקַדֵּשׁ כֻּלּוֹ אוֹ לֹא נִתְקַדֵּשׁ:","הָאוֹמֵר בְּהֵמָה זוֹ חֶצְיָהּ עוֹלָה וְחֶצְיָהּ שְׁלָמִים קָדְשָׁה. וְאֵינָהּ קְרֵבָה אֶלָּא תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם וְתִמָּכֵר וְיָבִיא בַּחֲצִי דָּמֶיהָ עוֹלָה וּבַחֲצִי דָּמֶיהָ שְׁלָמִים. הָיָה מְחֻיָּב חַטָּאת וְאָמַר חֶצְיָהּ חַטָּאת וְחֶצְיָהּ עוֹלָה אוֹ שְׁלָמִים. אוֹ שֶׁאָמַר חֶצְיָהּ עוֹלָה אוֹ שְׁלָמִים וְחֶצְיָהּ חַטָּאת. הֲרֵי הִיא תָּמוּת כְּמוֹ שֶׁיִּתְבָּאֵר בַּחַטָּאוֹת הַמֵּתוֹת:","בֶּהֱמַת הַשֻּׁתָּפִין שֶׁהִקְדִּישׁ אֶחָד מֵהֶן חֶצְיָהּ שֶׁלּוֹ וְחָזַר וְלָקַח חֶצְיָהּ הָאַחֵר וְהִקְדִּישׁוֹ הֲרֵי זוֹ קְדֵשָׁה וּקְרֵבָה. אַף עַל פִּי שֶׁמִּתְּחִלָּתָהּ דְּחוּיָה הָיְתָה כְּשֶׁהִקְדִּישׁ חֶצְיָהּ אֵין הַדָּחוּי מֵעִקָּרוֹ דָּחוּי וְאַף עַל פִּי שֶׁהוּא קְדֻשַּׁת דָּמִים הוֹאִיל וְהִיא בַּעֲלֵי חַיִּים אֵין בַּעֲלֵי חַיִּים נִדָּחִים. וַהֲרֵי נִרְאֵית כֻּלָּהּ לְהַקְרָבָה לְפִיכָךְ תִּקָּרֵב וְעוֹשָׂה תְּמוּרָה:","הָאוֹמֵר דְּמֵי בְּהֵמָה זוֹ עוֹלָה אוֹ הֲרֵי זוֹ לְעוֹלָה. אִם הָיְתָה רְאוּיָה לִקָּרֵב עוֹלָה נִתְקַדְּשָׁה קְדֻשַּׁת הַגּוּף וְהִיא עַצְמָהּ תִּקָּרֵב עוֹלָה. וְאִם אֵינָהּ רְאוּיָה תִּמָּכֵר וְיָבִיא בְּדָמֶיהָ עוֹלָה:","אָמַר עַל בְּהֵמָה טְמֵאָה וְכַיּוֹצֵא בָּהּ מֵאִסּוּרֵי קָרְבָּן שֶׁאֵין קְדֻשָּׁה חָלָה עֲלֵיהֶן הֲרֵי אֵלּוּ עוֹלָה לֹא אָמַר כְּלוּם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מִזְבֵּחַ. אָמַר הֲרֵי אֵלּוּ לְעוֹלָה יִמָּכְרוּ וְיָבִיא בִּדְמֵיהֶן עוֹלָה:","הָאוֹמֵר דְּמֵי פָּרָה זוֹ לְעוֹלָה כָּל שְׁלֹשִׁים יוֹם וּלְאַחַר שְׁלֹשִׁים יוֹם לִשְׁלָמִים אוֹ שֶׁאָמַר דָּמֶיהָ לִשְׁלָמִים כָּל שְׁלֹשִׁים יוֹם וּלְאַחַר שְׁלֹשִׁים יוֹם לְעוֹלָה דְּבָרָיו קַיָּמִים. וְאִם הִקְרִיב דָּמֶיהָ בְּתוֹךְ שְׁלֹשִׁים יוֹם מֵבִיא בָּהֶן כְּמוֹ שֶׁנָּדַר וְאִם הִקְרִיבוֹ לְאַחַר שְׁלֹשִׁים יוֹם מֵבִיא כְּמוֹ שֶׁנָּדַר:","הָיְתָה לוֹ בְּהֵמָה מְעֻבֶּרֶת וְאָמַר אִם תֵּלֵד זָכָר הֲרֵי הוּא עוֹלָה וְאִם הִיא נְקֵבָה זִבְחֵי שְׁלָמִים. יָלְדָה זָכָר יִקָּרֵב עוֹלָה. יָלְדָה נְקֵבָה תִּקָּרֵב זִבְחֵי שְׁלָמִים. יָלְדָה זָכָר וּנְקֵבָה הַזָּכָר יִקָּרֵב עוֹלָה וְהַנְּקֵבָה זִבְחֵי שְׁלָמִים. יָלְדָה שְׁנֵי זְכָרִים אֶחָד יִקָּרֵב עוֹלָה וְהַשֵּׁנִי יִמָּכֵר לְצָרְכֵי עוֹלָה וְדָמָיו חֻלִּין. וְכֵן אִם יָלְדָה שְׁתֵּי נְקֵבוֹת אַחַת תִּקָּרֵב שְׁלָמִים וּשְׁנִיָּה תִּמָּכֵר לְצָרְכֵי שְׁלָמִים וְדָמֶיהָ חֻלִּין. יָלְדָה טֻמְטוּם וְאַנְדְּרוֹגִינוּס אֵינָן קָדָשִׁים וַהֲרֵי הֵן חֻלִּין כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַמַּקְדִּישׁ עֻבָּר בִּמְעֵי בַּעֲלַת מוּם וְכַיּוֹצֵא בָּהּ הֲרֵי זֶה קָדוֹשׁ:"],"Mishneh Torah, Sacrificial Procedure 9":["מִצְוַת עֲשֵׂה לַעֲשׂוֹת כָּל הָאֲשָׁמוֹת כְּמִצְוָתָן הָאֲמוּרָה בַּתּוֹרָה. וְכֵיצַד מַעֲשֵׂה הָאֲשָׁמוֹת בֵּין אָשָׁם וַדַּאי בֵּין אָשָׁם תָּלוּי. שׁוֹחֵט וְזוֹרֵק הַדָּם כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַפְשִׁיט וּמוֹצִיא הָאֵימוּרִין וּמוֹלְחָן וְזוֹרְקָן עַל גַּב הָאִשִּׁים. וְאִם רָצָה לְהוֹלִיכָן בִּכְלִי מוֹלִיךְ. וּשְׁאָר בְּשָׂרָם נֶאֱכָל לְזִכְרֵי כְּהֻנָּה בָּעֲזָרָה כַּחַטָּאת:","אֲשַׁם מְצֹרָע יֵשׁ בְּקַבָּלַת דָּמוֹ שִׁנּוּי כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מְחֻסְּרֵי כַּפָּרָה. וְאַף עַל פִּי כֵן שְׁאָר מַעֲשָׂיו וּזְרִיקַת דָּמוֹ עַל הַמִּזְבֵּחַ וַאֲכִילָתוֹ כִּשְׁאָר הָאֲשָׁמוֹת לְכָל דָּבָר:","עֲשִׂיַּת כָּל שְׁלָמִים כְּמִצְוָתָן מִצְוַת עֲשֵׂה וְהֵן אַרְבָּעָה מִינִין. הָאֶחָד שַׁלְמֵי צִבּוּר וְהַשְּׁלֹשָׁה שַׁלְמֵי יָחִיד:","וְכֵיצַד מַעֲשֵׂה שַׁלְמֵי צִבּוּר. שׁוֹחֵט וְזוֹרֵק הַדָּם כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַפְשִׁיט וּמוֹצִיא הָאֵימוּרִים וּמוֹלְחָן וּמַקְטִירָן. וְהַשְּׁאָר נֶאֱכָל לְזִכְרֵי כְּהֻנָּה בָּעֲזָרָה כַּחַטָּאת וְכָאָשָׁם מִפְּנֵי שֶׁהֵן קָדְשֵׁי קָדָשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ:","שַׁלְמֵי יָחִיד שְׁלֹשָׁה מִינִין. הָאֶחָד הוּא הַבָּא שְׁלָמִים בְּלֹא לֶחֶם כְּגוֹן שַׁלְמֵי חֲגִיגָה וְשִׂמְחָה וְזֶהוּ הַנִּקְרָא שְׁלָמִים. וְהַשֵּׁנִי שְׁלָמִים הַבָּאִים עִם הַלֶּחֶם בְּנֵדֶר אוֹ נְדָבָה וְזֶהוּ הַנִּקְרָא תּוֹדָה וְאוֹתוֹ הַלֶּחֶם נִקְרָא לֶחֶם תּוֹדָה. וְהַמִּין הַשְּׁלִישִׁי שְׁלָמִים שֶׁמַּקְרִיב הַנָּזִיר בְּיוֹם מְלֹאת נִזְרוֹ וְהֵם בָּאִים עִם לֶחֶם וְזֶהוּ הַנִּקְרָא אֵיל נָזִיר:","וְכֵיצַד מַעֲשֵׂה שְׁלָשְׁתָּן. שׁוֹחֵט וְזוֹרֵק הַדָּם כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַפְשִׁיט וּמוֹצִיא הָאֵימוּרִין. וְאַחַר כָּךְ מְנַתֵּחַ אֶת הַבָּשָׂר וּמַפְרִישׁ הֶחָזֶה וְשׁוֹק הַיָּמִין וְנוֹתֵן הָאֵימוּרִין עִם הֶחָזֶה וְהַשּׁוֹק עַל יְדֵי הַבְּעָלִים וְכֹהֵן מַנִּיחַ יָדוֹ תַּחַת יְדֵי הַבְּעָלִים וּמֵנִיף הַכּל לִפְנֵי ה' בַּמִּזְרָח. וְכֵן כָּל הַטָּעוּן תְּנוּפָה בַּמִּזְרָח מְנִיפִין אוֹתוֹ:","וְכֵיצַד הוּא מֵנִיף. מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד. וְאִם הָיָה הַקָּרְבָּן תּוֹדָה לוֹקֵחַ מִן הַלֶּחֶם הַבָּא עִמָּהּ אֶחָד מֵעֲשָׂרָה וּמַנִּיחוֹ עִם הֶחָזֶה וְהַשּׁוֹק וְהָאֵימוּרִים וּמֵנִיף הַכּל עַל יְדֵי הַבְּעָלִים כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵיצַד מַנִּיחָן עַל יְדֵי הַבְּעָלִים. נוֹתֵן אֶת הַחֲלָבִים עַל יְדֵי הַבְּעָלִים וְחָזֶה וְשׁוֹק לְמַעְלָה וּשְׁתֵּי הַכְּלָיוֹת וְיוֹתֶרֶת הַכָּבֵד לְמַעְלָה מֵהֶם. וְאִם יֵשׁ שָׁם לֶחֶם מַנִּיחוֹ לְמַעְלָה וּמֵנִיף הַכּל:","הָיָה הַקָּרְבָּן אֵיל נָזִיר מוֹצִיא הָאֵימוּרִין וּמַפְרִישׁ חָזֶה וְשׁוֹק וּמְבַשֵּׁל שְׁאָר הָאַיִל בְּעֶזְרַת הַנָּשִׁים. וְלוֹקֵחַ הַכֹּהֵן הַזְּרֹעַ בְּשֵׁלָה מִן הָאַיִל עִם אֶחָד מֵעֲשָׂרָה מִן הַלֶּחֶם הַבָּא עִמּוֹ עִם הֶחָזֶה וְהַשּׁוֹק וְהָאֵימוּרִין וּמַנִּיחַ הַכּל עַל יְדֵי הַנָּזִיר. וְהַכֹּהֵן מַנִּיחַ יָדָיו תַּחַת יְדֵי הַבְּעָלִים וּמֵנִיף הַכּל כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵי זֶהוּ חָזֶה כָּל הָרוֹאֶה אֶת הַקַּרְקַע לְמַעְלָה עַד הַצַּוָּאר. לְמַטָּה עַד הַכָּרֵס. וְחוֹתֵךְ עִמָּהּ שְׁתֵּי צְלָעוֹת אֵילָךְ וְאֵילָךְ. וְאֵי זֶהוּ זְרוֹעַ מִן הַפֶּרֶק שֶׁל אַרְכֻּבָּה עַד כַּף שֶׁל יָד שֶׁהֵם שְׁנֵי אֵיבָרִים מְעֹרִין זֶה בָּזֶה. וְהַזְּרוֹעַ הָאֲמוּרָה הִיא זְרוֹעַ שֶׁל יָמִין. וְשֶׁכְּנֶגְדָהּ בָּרֶגֶל הוּא הַשּׁוֹק הָאָמוּר בְּכָל מָקוֹם:","וְאַחַר שֶׁמְּנִיפָן מוֹלֵחַ הָאֵימוּרִין וּמַקְטִירָן עַל גַּבֵּי הַמִּזְבֵּחַ. אֲבָל הֶחָזֶה וְהַשּׁוֹק נֶאֱכָל לַכֹּהֲנִים שֶׁנֶּאֱמַר (ויקרא ז לד) \"כִּי אֶת חֲזֵה הַתְּנוּפָה וְאֵת שׁוֹק הַתְּרוּמָה\". וּשְׁאָר הַשְּׁלָמִים נֶאֱכָלִים לַבְּעָלִים. וְאֵין הַכֹּהֲנִים זוֹכִין בְּחָזֶה וְשׁוֹק אֶלָּא לְאַחַר הֶקְטֵר הָאֵימוּרִין:","וְכֵן הַלֶּחֶם שֶׁמֵּנִיף בְּתוֹדָה וּבְאֵיל נָזִיר וְהַזְּרוֹעַ הַבְּשֵׁלָה נֶאֱכָלִין לַכֹּהֲנִים. וּשְׁאָר הַלֶּחֶם עִם שְׁאָר הַבָּשָׂר נֶאֱכָל לַבְּעָלִים. וְהַלֶּחֶם שֶׁמֵּנִיף עִם הֶחָזֶה וְהַשּׁוֹק הֵם הַנִּקְרָאִין מוּרָם מִתּוֹדָה. וְהַזְּרוֹעַ בְּשֵׁלָה עִם הֶחָזֶה וְהַשּׁוֹק עִם הַלֶּחֶם שֶׁמֵּנִיף הֵם הַנִּקְרָאִין מוּרָם מֵאֵיל נָזִיר:","הַלֶּחֶם הַמּוּרָם מִן הַתּוֹדָה סְפֵק תְּרוּמָה הוּא. לְפִיכָךְ אֵין חַיָּבִין עָלָיו מִיתָה וְחֹמֶשׁ כִּתְרוּמָה וְאֵינוֹ מְדַמֵּעַ כִּתְרוּמָה:","הָיָה בַּעַל הַתּוֹדָה כֹּהֵן. הֲרֵי שְׁאָר הַלֶּחֶם נֶאֱכָל לַבְּעָלִים כְּתוֹדַת יִשְׂרָאֵל. שֶׁאֵין הַלֶּחֶם הַבָּא עִם הַתּוֹדָה אוֹ עִם אֵיל נָזִיר קָרוּי מִנְחָה:","שְׁנַיִם שֶׁהֵבִיאוּ שְׁלָמִים בְּשֻׁתָּפוּת הָאֶחָד מֵנִיף בִּרְשׁוּת חֲבֵרוֹ אֲפִלּוּ הֵם מֵאָה אֶחָד מֵנִיף עַל יְדֵי כֻּלָּן. מַה שֶּׁאֵין כֵּן בִּסְמִיכָה:","הָיְתָה אִשָּׁה בַּעֲלַת הַקָּרְבָּן אֵינָהּ מְנִיפָה. אֲבָל הַכֹּהֵן מֵנִיף שֶׁקָּרְבָּנָהּ טָעוּן תְּנוּפָה וְהִיא פְּסוּלָה לִתְנוּפָה. וּלְעוֹלָם אֵין אִשָּׁה מְנִיפָה אֶלָּא הַסּוֹטָה וְהַנְּזִירָה בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ. וּתְנוּפָה קוֹדֶמֶת לְהַגָּשָׁה בְּכָל מָקוֹם:","כֵּיצַד הוּא הַלֶּחֶם שֶׁמֵּבִיא עִם הַתּוֹדָה. לוֹקֵחַ עֶשְׂרִים עִשָּׂרוֹן סלֶת וְעוֹשֶׂה מֵהֶם עֲשָׂרָה עֶשְׂרוֹנִים חָמֵץ וַעֲשָׂרָה מַצָּה. הָעֲשָׂרָה שֶׁל חָמֵץ עוֹשֶׂה אוֹתָם עֶשֶׂר חַלּוֹת:","וְכֵיצַד מְחַמְּצָן. מֵבִיא שְׂאוֹר כְּדֵי חִמּוּצָן וְנוֹתְנוֹ לְתוֹךְ הַמִּדָּה וּמְמַלֵּא אֶת הַמִּדָּה אַף עַל פִּי שֶׁסּוֹפָהּ לִהְיוֹת חֲסֵרָה אוֹ יְתֵרָה מִפְּנֵי הַשְּׂאוֹר שֶׁפְּעָמִים יִהְיֶה עָבֶה וְקָשֶׁה וּפְעָמִים רַכָּה אֵין מַשְׁגִּיחִין אֶלָּא עַל מִדָּתָהּ עַתָּה וַהֲרֵי הוּא מוֹדֵד עִשָּׂרוֹן עִשָּׂרוֹן שְׁלָמִים. וְהָעֲשָׂרָה עֶשְׂרוֹנִים שֶׁל מַצָּה עוֹשֶׂה מֵהֶן שְׁלֹשִׁים חַלּוֹת שָׁווֹת. עֶשֶׂר חַלּוֹת מִכָּל מִין. עֶשֶׂר חַלּוֹת מַאֲפֵה תַּנּוּר. וְעֶשֶׂר חַלּוֹת רְקִיקִים. וְעֶשֶׂר חַלּוֹת מֻרְבֶּכֶת:","וְכֵיצַד הִיא הַמֻּרְבֶּכֶת. חוֹלְטָהּ בְּרוֹתְחִין וְאוֹפֶה אוֹתָהּ מְעַט וְאַחַר כָּךְ קוֹלֶה אוֹתָהּ בְּשֶׁמֶן עַל הָאִלְפָּס וְכַיּוֹצֵא בּוֹ. כְּדֶרֶךְ שֶׁקּוֹלִין הַסֻּפְגָּנִין. וּמַרְבִּין בְּשַׁמְנָהּ. וְזֶהוּ הָרִבּוּךְ הָאָמוּר בְּכָל מָקוֹם:","וּבְכַמָּה שֶׁמֶן הוּא עוֹשֶׂה הַשְּׁלֹשִׁים חַלּוֹת. בַּחֲצִי לוֹג שֶׁמֶן. וְשִׁעוּר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי. רְבִיעִית מִמֶּנּוּ לִרְבוּכָה. וּשְׁמִינִית לְחַלּוֹת. וּשְׁמִינִית לִרְקִיקִין:","הַחַלּוֹת לוֹתֵת הַסּלֶת שֶׁלָּהֶן בִּשְׁמִינִית שֶׁל שֶׁמֶן. וְאַחַר כָּךְ לָשׁ וְאוֹפֶה אוֹתָן. וְהָרְקִיקִין מוֹשְׁחָן בַּשְּׁמִינִית שֶׁלָּהֶן אַחַר אֲפִיָּתָן. וְהַכֹּהֵן לוֹקֵחַ מִן הַכּל אַרְבַּע חַלּוֹת אַחַת מִכָּל מִין וּמִין שֶׁנֶּאֱמַר (ויקרא ז יד) \"אֶחָד מִכָּל קָרְבָּן\":","וְלַחְמֵי תּוֹדָה שֶׁאָפָה אוֹתָן אַרְבַּע חַלּוֹת יָצָא. לֹא נֶאֱמַר אַרְבָּעִים אֶלָּא לְמִצְוָה. וְהוּא שֶׁיַּפְרִישׁ הַחַלָּה שֶׁלָּהֶן אַחַת מִכָּל קָרְבָּן כְּשֶׁהֵן בָּצֵק. שֶׁאֵין מַפְרִישִׁין פְּרוּסָה שֶׁנֶּאֱמַר (ויקרא ז יד) \"אֶחָד מִכָּל קָרְבָּן\" שֶׁלֹּא יִטּל פָּרוּס:","וְכֵיצַד הוּא הַלֶּחֶם הַבָּא עִם אֵיל נָזִיר. לוֹקֵחַ שִׁשָּׁה עֶשְׂרוֹנוֹת וּשְׁנֵי שְׁלִישֵׁי עִשָּׂרוֹן וְעוֹשֶׂה מֵהֶן עֶשְׂרִים חַלּוֹת שָׁווֹת וְהַכּל מַצָּה. עֲשָׂרָה רְקִיקִין מְשׁוּחִין בְּשֶׁמֶן. וְעֶשֶׂר חַלּוֹת לוֹתֵת הַסּלֶת שֶׁלָּהֶן בְּשֶׁמֶן. וְהַכּל מַאֲפֵה תַּנּוּר וְשֶׁמֶן שֶׁלָּהֶן רְבִיעִית. וְשִׁעוּר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי. וְהַכֹּהֵן לוֹקֵחַ מֵהֶן שְׁתֵּי חַלּוֹת אַחַת מִכָּל מִין:","שְׁנֵי מִינֵי לֶחֶם שֶׁבְּנָזִיר וְאַרְבָּעָה מִינֵי לֶחֶם שֶׁבְּתוֹדָה מְעַכְּבִין זֶה אֶת זֶה. וּמַעֲשֵׂה הַלֶּחֶם שֶׁל שְׁנֵיהֶן חוּץ לָעֲזָרָה:","כֵּיצַד מַעֲשֵׂה הַבְּכוֹר וְהַמַּעֲשֵׂר וְהַפֶּסַח. אַחַר שֶׁזּוֹרֵק דָּמָן כְּמוֹ שֶׁבֵּאַרְנוּ מַפְשִׁיט וּמוֹצִיא הָאֵימוּרִים וּמוֹלְחָן וּמַקְטִירָן. וּשְׁאָר בְּשַׂר הַבְּכוֹר נֶאֱכָל לַכֹּהֲנִים. וּשְׁאָר בְּשַׂר הַמַּעֲשֵׂר נֶאֱכָל לַבְּעָלִים. וּשְׁאָר הַפֶּסַח נֶאֱכָל לִמְנוּיָיו כְּהִלְכוֹתָיו כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת הַפֶּסַח:"],"Mishneh Torah, Sales 2":["עֶבֶד כְּנַעֲנִי הֲרֵי הוּא כְּקַרְקַע לִקְנִיָּה וְנִקְנֶה בְּכֶסֶף וּבִשְׁטָר אוֹ בַּחֲזָקָה:","וּמַה הִיא הַחֲזָקָה בְּקִנְיַן עֲבָדִים. שֶׁיִּשְׁתַּמֵּשׁ בָּהֶן כְּדֶרֶךְ שֶׁמִּשְׁתַּמְּשִׁין בַּעֲבָדִים בִּפְנֵי רַבּוֹ. כֵּיצַד. הִתִּיר לוֹ מִנְעָלוֹ אוֹ שֶׁהִנְעִיל לוֹ מִנְעָלוֹ. אוֹ שֶׁהוֹלִיךְ כֵּלָיו לְבֵית הַמֶּרְחָץ. אוֹ שֶׁהִפְשִׁיטוֹ אוֹ סָכוֹ אוֹ גֵּרְדוֹ אוֹ הִלְבִּישׁוֹ אוֹ הִגְבִּיהַּ אֶת רַבּוֹ קָנָה. וְכֵן אִם הִגְבִּיהַּ הָרַב אֶת הָעֶבֶד קָנָה:","תְּקָפוֹ וֶהֱבִיאוֹ אֶצְלוֹ קָנָה. שֶׁהָעֲבָדִים נִקְנִין בִּמְשִׁיכָה כָּזוֹ. אֲבָל אִם קָרָא לָעֶבֶד וּבָא אֶצְלוֹ. אוֹ שֶׁאָמַר לוֹ רַבּוֹ הָרִאשׁוֹן לֵךְ אֵצֶל הַלּוֹקֵחַ וְהָלַךְ אֶצְלוֹ. לֹא קָנָה עַד שֶׁיִּמְשְׁכֶנּוּ בִּתְקִיפָה אוֹ שֶׁיִּשְׁתַּמֵּשׁ בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם הֶחֱזִיק בּוֹ שֶׁלֹּא בִּפְנֵי הָרַב צָרִיךְ שֶׁיֹּאמַר לוֹ לֵךְ חַזֵּק וּקְנֵה:","עֶבֶד קָטָן הֲרֵי הוּא כִּבְהֵמָה וְקוֹנִין אוֹתוֹ בִּדְבָרִים שֶׁקּוֹנִין בָּהֶן הַבְּהֵמָה וּבִדְבָרִים שֶׁקּוֹנִין בָּהֶן הָעֲבָדִים. לְפִיכָךְ נִקְנֶה בִּמְשִׁיכָה אַף עַל פִּי שֶׁלֹּא תּוֹקְפוֹ:","הַבְּהֵמָה בֵּין דַּקָּה בֵּין גַּסָּה נִקְנֵית בִּמְשִׁיכָה אַף עַל פִּי שֶׁאֶפְשָׁר לְהַגְבִּיהַּ אוֹתָהּ לֹא הִצְרִיכוּהוּ לְהַגְבִּיהַּ. מִפְּנֵי שֶׁמִּתְחַבֶּטֶת בָּאָרֶץ. וְאִם הִגְבִּיהַּ קָנָה. וְהַהַגְבָּהָה קוֹנָה בְּכָל מָקוֹם. אֲבָל הַמְּשִׁיכָה אֵין קוֹנִין בָּהּ אֶלָּא בְּסִמְטָא אוֹ בְּחָצֵר שֶׁל שְׁנֵיהֶם וְאֵין קוֹנִין בָּהּ בִּרְשׁוּת הָרַבִּים וְלֹא בְּחָצֵר שֶׁאֵינָהּ שֶׁל שְׁנֵיהֶם:","כֵּיצַד קוֹנִין אֶת הַבְּהֵמָה בִּמְשִׁיכָה. אֵין צָרִיךְ לוֹמַר אִם מְשָׁכָהּ וְהָלְכָה אוֹ שֶׁרָכַב עָלֶיהָ וְהָלְכָה בּוֹ שֶׁקָּנָה. אֶלָּא אֲפִלּוּ קָרָא לָהּ וּבָאָה אוֹ שֶׁהִכִּישָׁהּ בְּמַקֵּל וְרָצָה בְּפָנָיו כֵּיוָן שֶׁעָקְרָה יָד וְרֶגֶל קְנָאָהּ. וְהוּא שֶׁיִּמְשֹׁךְ בִּפְנֵי הַבְּעָלִים. אֲבָל אִם מָשַׁךְ שֶׁלֹּא בִּפְנֵי הַבְּעָלִים צָרִיךְ שֶׁיֹּאמַר לוֹ קֹדֶם שֶׁיִּמְשֹׁךְ לֵךְ מְשֹׁךְ וּקְנֵה:","הַמּוֹכֵר עֵדֶר לַחֲבֵרוֹ אוֹ שֶׁנָּתַן לוֹ בְּמַתָּנָה. כֵּיוָן שֶׁמָּסַר לוֹ מַשְׁכּוּכִית, הִיא הַבְּהֵמָה הַמְהַלֶּכֶת בְּרֹאשׁ הָעֵדֶר וְהַכּל נִמְשָׁכִים אַחֲרֶיהָ, אֵין צָרִיךְ לוֹמַר לוֹ מְשֹׁךְ וּקְנֵה. שֶׁמְּסִירַת בְּהֵמָה זוֹ כְּמִי שֶׁאָמַר לוֹ לֵךְ מְשֹׁךְ וּקְנֵה. וְכֵיוָן שֶׁמָּשַׁךְ לוֹ הָעֵדֶר קָנָה וְאַף עַל פִּי שֶׁמָּשַׁךְ שֶׁלֹּא בְּפָנָיו:","הָאוֹמֵר לַחֲבֵרוֹ מְשֹׁךְ וְתִקְנֶה אוֹ חַזֵּק וְתִקְנֶה וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ וְהָלַךְ וּמָשַׁךְ אוֹ שֶׁהֶחְזִיק לֹא קָנָה שֶׁמַּשְׁמָע תִּקְנֶה לְהַבָּא וַעֲדַיִן לֹא הִקְנָה לוֹ. אֶלָּא צָרִיךְ הַמּוֹכֵר אוֹ הַנּוֹתֵן לוֹמַר לוֹ לֵךְ חַזֵּק וּקְנֵה אוֹ מְשֹׁךְ וּקְנֵה וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁמַּשְׁמָעָן שֶׁיִּקְנֶה עַתָּה בְּעֵת שֶׁיִּמְשֹׁךְ אוֹ יַחֲזִיק:","הָאוֹמֵר לַחֲבֵרוֹ מְשֹׁךְ פָּרָה זוֹ וְלֹא תִּקְנֶה אֶלָּא לְאַחַר שְׁלֹשִׁים יוֹם וּמָשַׁךְ לֹא קָנָה. וְאִם אָמַר לוֹ קְנֵה מֵעַכְשָׁו וּלְאַחַר שְׁלֹשִׁים יוֹם קָנָה. וַאֲפִלּוּ הָיְתָה עוֹמֶדֶת בַּאֲגַם בְּיוֹם שְׁלֹשִׁים. שֶׁזֶּה כְּמִי שֶׁהִקְנָה אוֹתוֹ מֵעַתָּה עַל תְּנַאי נַעֲשָׂה הַתְּנַאי נִתְקַיֵּם הַקִּנְיָן. וְכָל הָאוֹמֵר עַל מְנָת כְּאוֹמֵר מֵעַכְשָׁו דָּמִי:","הַמּוֹכֵר בְּהֵמָה לַחֲבֵרוֹ אוֹ נְתָנָהּ לוֹ בְּמַתָּנָה וְאָמַר קְנֵה אוֹתָהּ כְּדֶרֶךְ שֶׁבְּנֵי אָדָם קוֹנִין. אִם מָשַׁךְ אוֹ הִגְבִּיהָהּ קָנָה. אֲבָל אִם רָכַב עָלֶיהָ. אִם בַּשָּׂדֶה קָנָה. וְאִם בָּעִיר לֹא קָנָה. לְפִי שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לִרְכֹּב בָּעִיר. לְפִיכָךְ אִם הָיָה אָדָם חָשׁוּב שֶׁדַּרְכּוֹ לִרְכֹּב בָּעִיר. אוֹ אָדָם מְזֻלְזָל בְּיוֹתֵר שֶׁאֵינוֹ מַקְפִּיד עַל הִלּוּכוֹ בָּעִיר רוֹכֵב. כְּגוֹן הַמְטַפְּלִין בְּגִדּוּל הַבְּהֵמוֹת אוֹ הָעֲבָדִים. אוֹ שֶׁהָיְתָה אִשָּׁה. אוֹ שֶׁהָיָה בִּרְשׁוּת הָרַבִּים שֶׁהָרַבִּים דּוֹרְסִין שָׁם. הֲרֵי זֶה קוֹנֶה בִּרְכִיבָה. וְהוּא שֶׁתְּהַלֵּךְ בּוֹ:"],"Mishneh Torah, Sales 30":["הַמּוֹכֵר שֶׁמָּכַר קַרְקַע אוֹ מִטַּלְטְלִין וְזָכָה בָּהֶן הַלּוֹקֵחַ שֶׁלֹּא מִדַּעְתּוֹ יַד הַלּוֹקֵחַ עַל הָעֶלְיוֹנָה. וְאִם רָצָה לוֹקֵחַ אֵין הַמּוֹכֵר יָכוֹל לַחְזֹר בּוֹ וְאִם לֹא רָצָה תַּחְזֹר לִבְעָלֶיהָ. לְפִיכָךְ כּוֹתְבִין שְׁטָר לַמּוֹכֵר אַף עַל פִּי שֶׁאֵין הַלּוֹקֵחַ עִמּוֹ. וּלְעוֹלָם הַלּוֹקֵחַ נוֹתֵן שְׂכַר הַסּוֹפֵר וַאֲפִלּוּ מָכַר שָׂדֵהוּ מִפְּנֵי רָעָתָהּ:","וְכֵן הָעֶבֶד שֶׁקָּנָה אוֹ מָכַר אוֹ נָתַן מַתָּנָה אוֹ נְתָנָהּ לוֹ. יַד הָאָדוֹן עַל הָעֶלְיוֹנָה. אִם רָצָה לְקַיֵּם מַעֲשָׂיו הֲרֵי אֵלּוּ קַיָּמִין וְאִם לֹא רָצָה בָּטְלוּ כָּל מַעֲשָׂיו. וּבִדְבָרִים בִּלְבַד הוּא שֶׁמְּקַיֵּם הָאָדוֹן אוֹ מְבַטֵּל וְאֵינוֹ צָרִיךְ לִקְנוֹת מִמֶּנּוּ כְּלוּם:","וְכֵן הָאִשָּׁה שֶׁמָּכְרָה אוֹ נָתְנָה מַתָּנָה. בֵּין בְּנִכְסֵי בַּעְלָהּ בֵּין בְּנִכְסֵי צֹאן בַּרְזֶל שֶׁהִכְנִיסָה לוֹ. בֵּין בִּדְבָרִים שֶׁיִּחֵד לָהּ בִּכְתֻבָּתָהּ בֵּין בְּנִכְסֵי מְלוֹג. בֵּין בְּקַרְקָעוֹת בֵּין בְּמִטַּלְטְלִין. וְכֵן אִם לָקְחָה אוֹ נִתְנָה [לָהּ מַתָּנָה] יַד הַבַּעַל עַל הָעֶלְיוֹנָה וְאִם רָצָה לְקַיֵּם יְקַיֵּם אִם רָצָה לְבַטֵּל יְבַטֵּל הַכּל. אֲבָל הַבַּעַל שֶׁמָּכַר אוֹ נָתַן בֵּין קַרְקַע שֶׁהִכְנִיסָה לוֹ אִשְׁתּוֹ בִּכְתֻבָּתָהּ אוֹ קַרְקַע שֶׁהִכְנִיס לָהּ שׁוּם מִשֶּׁלּוֹ. בֵּין קַרְקַע שֶׁיִּחֵד לָהּ בִּכְתֻבָּתָהּ. אַף עַל פִּי שֶׁקָּנוּ מִיַּד הָאִשָּׁה אַחַר שֶׁקִּיְּמָה מַעֲשָׂיו הֲרֵי כָּל מַה שֶּׁעָשָׂה בָּטֵל מִפְּנֵי שֶׁהִיא אוֹמֶרֶת נַחַת רוּחַ עָשִׂיתִי לְבַעְלִי:","מָכַר אוֹ נָתַן נִכְסֵי מְלוֹג בֵּין בְּקַרְקָעוֹת בֵּין בְּמִטַּלְטְלִין יַד הָאִשָּׁה עַל הָעֶלְיוֹנָה. רָצְתָה לְבַטֵּל מְבַטְּלָהּ וְאִם קִיְּמָה מַעֲשֶׂיהָ קָנוּ הַלָּקוֹחוֹת:","בַּעַל שֶׁמָּכַר מִטַּלְטְלִין שֶׁל נִכְסֵי צֹאן בַּרְזֶל אוֹ מִטַּלְטְלִין שֶׁנָּתְנָה לוֹ מִשֶּׁלּוֹ אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי אִם עָבַר וּמָכַר אוֹ נָתַן קָנוּ הַלָּקוֹחוֹת וְאֵין הָאִשָּׁה יְכוֹלָה לְהוֹצִיא מִיָּדָם. וְכֵן יֵשׁ לוֹ לַבַּעַל לִמְכֹּר כָּל נְכָסָיו אַף עַל פִּי שֶׁהֵן תַּחַת יַד שִׁעְבּוּד הַכְּתוּבָה. וְאִם תָּבוֹא לִטְרֹף טוֹרֶפֶת אֶלָּא אִם כֵּן כָּתְבָה לַלּוֹקֵחַ תְּחִלָּה וְקָנוּ מִיָּדָהּ:","הָאִשָּׁה שֶׁמָּכְרָה אוֹ נָתְנָה נִכְסֵי צֹאן בַּרְזֶל לְבַעְלָהּ לֹא קָנָה. וְיֵשׁ לָהּ לַחְזֹר וּלְהוֹצִיא מִיָּדוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת. בֵּית דִּין שֶׁמָּכְרוּ אוֹ לָקְחוּ בְּנִכְסֵי יְתוֹמִים בֵּין בְּקַרְקַע בֵּין בְּמִטַּלְטְלִין. וְכֵן הָאַפּוֹטְרוֹפּוֹסִין בֵּין שֶׁמִּנּוּ אוֹתָם בֵּית דִּין בֵּין שֶׁמִּנָּה אוֹתָן אֲבִי יְתוֹמִים. מִקָּחָן מִקָּח וּמִמְכָּרָן מִמְכָּר אֲבָל מַתְּנָתָם אֵינָהּ כְּלוּם שֶׁאֵין אָדָם נוֹתֵן דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ:","הַמּוֹכֵר אוֹ הַנּוֹתֵן בְּשַׁבָּת וְאֵין צָרִיךְ לוֹמַר בַּיּוֹם טוֹב אַף עַל פִּי שֶׁמַּכִּין אוֹתוֹ מַעֲשָׂיו קַיָּמִין. וְכֵן כָּל מִי שֶׁקָּנוּ מִיָּדוֹ בְּשַׁבָּת הַקִּנְיָן קַיָּם וְכוֹתְבִין לְאַחַר הַשַּׁבָּת וְנוֹתְנִין: סְלִיקוּ לְהוּ הִלְכוֹת מְכִירָה בְּסַ\"ד"],"Mishneh Torah, Sanctification of the New Month 14":["הַיָּרֵחַ שְׁנֵי מַהֲלָכִים אְמְצָעיּים יֵשׁ לוֹ. הַיָּרֵחַ עַצְמוֹ מְסַבֵּב בְּגַלְגַּל קָטָן שֶׁאֵינוֹ מַקִּיף אֶת הָעוֹלָם כֻּלּוֹ. וּמַהֲלָכוֹ הָאֶמְצָעִי בְּאוֹתוֹ הַגַּלְגַּל הַקָּטָן נִקְרָא אֶמְצָעִי הַמַּסְלוּל. וְהַגַּלְגַּל הַקָּטָן עַצְמוֹ מְסַבֵּב בְּגַלְגַּל גָּדוֹל הַמַּקִּיף אֶת הָעוֹלָם. וּבְמַהֲלַךְ אֶמְצָעִי זֶה שֶׁל גַּלְגַּל הַקָּטָן בְּאוֹתוֹ הַגַּלְגַּל הַגָּדוֹל הַמַּקִּיף אֶת הָעוֹלָם הוּא הַנִּקְרָא אֶמְצַע הַיָּרֵחַ. מַהֲלַךְ אֶמְצַע הַיָּרֵחַ בְּיוֹם אֶחָד י\"ג מַעֲלוֹת וְי' חֲלָקִים וְל\"ה שְׁנִיּוֹת. סִימָנָם י\"ג יל\"ה:","נִמְצָא מַהֲלָכוֹ בַּעֲשָׂרָה יָמִים קל\"א מַעֲלוֹת וּמ\"ה חֲלָקִים וַחֲמִשִּׁים שְׁנִיּוֹת. סִימָנָם קל\"א מה\"נ. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּק' יוֹם רל\"ז מַעֲלוֹת וְל\"ח חֲלָקִים וְכ\"ג שְׁנִיּוֹת. סִימָנָם רל\"ז ל\"ח כ\"ג. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּאֶלֶף יוֹם רי\"ו מַעֲלוֹת וְכ\"ג חֲלָקִים וְנ' שְׁנִיּוֹת. סִימָנָם רי\"ו כג\"ן. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּי' אֲלָפִים יוֹם ג' מַעֲלוֹת וְנ\"ח חֲלָקִים וְכ' שְׁנִיּוֹת. סִימָנָם ג' נ\"ח כ'. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּכ\"ט יוֹם כ\"ב מַעֲלוֹת וְשִׁשָּׁה חֲלָקִים וְנ\"ו שְׁנִיּוֹת. סִימָנָם כב\"ו ונ\"ו. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּשָׁנָה סְדוּרָה שמ\"ד מַעֲלוֹת וְכ\"ו חֲלָקִים וּמ\"ג שְׁנִיּוֹת. סִימָן לָהֶם שד\"ם כ\"ו מ\"ג. וְעַל דֶּרֶךְ זוֹ תִּכְפּל לְכָל מִנְיַן יָמִים אוֹ שָׁנִים שֶׁתִּרְצֶה:","וּמַהֲלַךְ אֶמְצַע הַמַּסְלוּל בְּיוֹם אֶחָד י\"ג מַעֲלוֹת וּשְׁלֹשָׁה חֲלָקִים וְנ\"ד שְׁנִיּוֹת. סִימָנָם י\"ג גנ\"ד. נִמְצָא מַהֲלָכוֹ בַּעֲשָׂרָה יָמִים ק\"ל מַעֲלוֹת ל\"ט חֲלָקִים בְּלֹא שְׁנִיּוֹת. סִימָנָם ק\"ל ל\"ט. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּמֵאָה יוֹם רכ\"ו מַעֲלוֹת וְכ\"ט חֲלָקִים וְנ\"ג שְׁנִיּוֹת. סִימָנָם רכ\"ו כ\"ט נ\"ג. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּאֶלֶף יוֹם ק\"ד מַעֲלוֹת וְנ\"ח חֲלָקִים וַחֲמִשִּׁים שְׁנִיּוֹת. סִימָנָם ק\"ד נח\"ן. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בַּעֲשֶׂרֶת אֲלָפִים יוֹם שכ\"ט וּמ\"ח חֲלָקִים וְעֶשְׂרִים שְׁנִיּוֹת. סִימָנָם שכ\"ט מח\"כ. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּכ\"ט יוֹם י\"ח מַעֲלוֹת וְנ\"ג חֲלָקִים וְד' שְׁנִיּוֹת. סִימָנָם י\"ח נג\"ד:","וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בְּשָׁנָה סְדוּרָה ש\"ה מַעֲלוֹת וְי\"ג שְׁנִיּוֹת בְּלֹא חֲלָקִים. סִימָנָם ש\"ה י\"ג. מְקוֹם אֶמְצַע הַיָּרֵחַ הָיָה בִּתְחִלַּת לֵיל חֲמִישִׁי שֶׁהוּא הָעִקָּר לְחֶשְׁבּוֹנוֹת אֵלּוּ בְּמַזַּל שׁוֹר מַעֲלָה אַחַת וְי\"ד חֲלָקִים וּמ\"ג שְׁנִיּוֹת. סִימָנָם (א') [ל\"א] י\"ד מ\"ג. וְאֶמְצַע הַמַּסְלוּל הָיָה בְּעִקָּר זֶה פ\"ד מַעֲלוֹת וְכ\"ח חֲלָקִים וּמ\"ב שְׁנִיּוֹת. סִימָנָם פ\"ד כ\"ח מ\"ב. מֵאַחֵר שֶׁתֵּדַע מַהֲלַךְ אֶמְצַע הַיָּרֵחַ וְהָאֶמְצַע שֶׁהוּא הָעִקָּר שֶׁעָלָיו תּוֹסִיף. תֵּדַע מְקוֹם אֶמְצַע הַיָּרֵחַ בְּכָל יוֹם שֶׁתִּרְצֶה עַל דֶּרֶךְ שֶׁעָשִׂיתָ בְּאֶמְצַע הַשֶּׁמֶשׁ. וְאַחַר שֶׁתּוֹצִיא אֶמְצַע הַיָּרֵחַ לִתְחִלַּת הַלַּיְלָה שֶׁתִּרְצֶה הִתְבּוֹנֵן בַּשֶּׁמֶשׁ וְדַע בְּאֵי זֶה מַזָּל הוּא:","אִם הָיְתָה הַשֶּׁמֶשׁ מֵחֲצִי מַזַּל דָּגִים עַד חֲצִי מַזַּל טָלֶה. תָּנִיחַ אֶמְצַע הַיָּרֵחַ כְּמוֹת שֶׁהוּא. וְאִם תִּהְיֶה הַשֶּׁמֶשׁ מֵחֲצִי מַזַּל טָלֶה עַד תְּחִלַּת מַזַּל תְּאוֹמִים. תּוֹסִיף עַל אֶמְצַע הַיָּרֵחַ ט\"ו חֲלָקִים. וְאִם תִּהְיֶה הַשֶּׁמֶשׁ מִתְּחִלַּת מַזַּל תְּאוֹמִים עַד תְּחִלַּת מַזַּל אַרְיֵה. תּוֹסִיף עַל אֶמְצַע הַיָּרֵחַ ט\"ו חֲלָקִים. וְאִם תִּהְיֶה הַשֶּׁמֶשׁ מִתְּחִלַּת מַזַּל אַרְיֵה עַד חֲצִי מַזַּל בְּתוּלָה תּוֹסִיף עַל אֶמְצַע הַיָּרֵחַ ט\"ו חֲלָקִים. וְאִם תִּהְיֶה הַשֶּׁמֶשׁ מֵחֲצִי מַזַּל בְּתוּלָה עַד חֲצִי מֹאזְנַיִם. הָנַח אֶמְצַע הַיָּרֵחַ כְּמוֹת שֶׁהוּא. וְאִם תִּהְיֶה הַשֶּׁמֶשׁ מֵחֲצִי מֹאזְנַיִם עַד תְּחִלַּת מַזַּל קֶשֶׁת. תִּגְרַע מֵאֶמְצַע הַיָּרֵחַ ט\"ו חֲלָקִים. וְאִם תִּהְיֶה הַשֶּׁמֶשׁ מִתְּחִלַּת מַזַּל קֶשֶׁת עַד תְּחִלַּת מַזַּל דְּלִי. תִּגְרַע מֵאֶמְצַע הַיָּרֵחַ ל' חֲלָקִים. וְאִם תִּהְיֶה הַשֶּׁמֶשׁ מִתְּחִלַּת מַזַּל דְּלִי עַד חֲצִי מַזַּל דָּגִים. תִּגְרַע מֵאֶמְצַע הַיָּרֵחַ ט\"ו חֲלָקִים:","וּמַה שֶּׁיִּהְיֶה הָאֶמְצַע אַחַר שֶׁתּוֹסִיף עָלָיו אוֹ תִּגְרַע מִמֶּנּוּ אוֹ תָּנִיחַ אוֹתוֹ כְּמוֹת שֶׁהוּא. הוּא אֶמְצַע הַיָּרֵחַ לְאַחַר שְׁקִיעַת הַחַמָּה בִּכְמוֹ שְׁלִישׁ שָׁעָה בְּאוֹתוֹ הַזְּמַן שֶׁתּוֹצִיא הָאֶמְצַע לוֹ. וְזֶה הוּא הַנִּקְרָא אֶמְצַע הַיָּרֵחַ לִשְׁעַת הָרְאִיָּה:"],"Mishneh Torah, Sanctification of the New Month 8":["חָדְשָׁה שֶׁל לְבָנָה תִּשְׁעָה וְעֶשְׂרִים יוֹם וּמֶחֱצָה וְתשצ\"ג חֲלָקִים כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִי אֶפְשָׁר לוֹמַר שֶׁרֹאשׁ הַחֹדֶשׁ יִהְיֶה בְּמִקְצָת הַיּוֹם עַד שֶׁיִּהְיֶה מִקְצָת הַיּוֹם מֵחֹדֶשׁ שֶׁעָבַר וּמִקְצָתוֹ מֵהַבָּא. שֶׁנֶּאֱמַר (במדבר יא כ) \"עַד חֹדֶשׁ יָמִים\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁיָּמִים אַתָּה מְחַשֵּׁב לְחֹדֶשׁ וְאִי אַתָּה מְחַשֵּׁב שָׁעוֹת:","לְפִיכָךְ עוֹשִׂין חָדְשֵׁי הַלְּבָנָה מֵהֶן חֹדֶשׁ חָסֵר וּמֵהֶם חֹדֶשׁ מָלֵא. חֹדֶשׁ חָסֵר תִּשְׁעָה וְעֶשְׂרִים יוֹם בִּלְבַד וְאַף עַל פִּי שֶׁחָדְשָׁהּ שֶׁל לְבָנָה יֶתֶר עַל זֶה בְּשָׁעוֹת. וְחֹדֶשׁ מָלֵא מִשְּׁלֹשִׁים יוֹם וְאַף עַל פִּי שֶׁחָדְשָׁהּ שֶׁל לְבָנָה פָּחוֹת מִזֶּה בְּשָׁעוֹת. כְּדֵי שֶׁלֹּא לְחַשֵּׁב שָׁעוֹת בַּחֹדֶשׁ אֶלָּא יָמִים שְׁלֵמִים:","אִלּוּ הָיָה חָדְשָׁהּ שֶׁל לְבָנָה תִּשְׁעָה וְעֶשְׂרִים יוֹם וּמֶחֱצָה בִּלְבַד הָיוּ כָּל הַשָּׁנִים חֹדֶשׁ מָלֵא וְחֹדֶשׁ חָסֵר. וְיִהְיוּ יְמֵי שְׁנַת הַלְּבָנָה שנ\"ד, שִׁשָּׁה חֳדָשִׁים חֲסֵרִים וְשִׁשָּׁה חֳדָשִׁים מְלֵאִים. אֲבָל מִפְּנֵי הַחֲלָקִים שֶׁיֵּשׁ בְּכָל חֹדֶשׁ וְחֹדֶשׁ יוֹתֵר עַל חֲצִי הַיּוֹם יִתְקַבֵּץ מֵהֶן שָׁעוֹת וְיָמִים. עַד שֶׁיִּהְיוּ מִקְצָת הַשָּׁנִים חֳדָשִׁים חֲסֵרִים יוֹתֵר עַל הַמְּלֵאִים וּבְמִקְצָת הַשָּׁנִים חֳדָשִׁים מְלֵאִים יוֹתֵר עַל הַחֲסֵרִים:","יוֹם שְׁלֹשִׁים לְעוֹלָם עוֹשִׂין אוֹתוֹ רֹאשׁ חֹדֶשׁ בְּחֶשְׁבּוֹן זֶה. אִם הָיָה הַחֹדֶשׁ שֶׁעָבַר חָסֵר יִהְיֶה יוֹם שְׁלֹשִׁים רֹאשׁ חֹדֶשׁ הַבָּא. וְאִם יִהְיֶה הַחֹדֶשׁ שֶׁעָבַר מָלֵא יִהְיֶה יוֹם שְׁלֹשִׁים רֹאשׁ חֹדֶשׁ הוֹאִיל וּמִקְצָתוֹ רֹאשׁ חֹדֶשׁ. וְיִהְיֶה תַּשְׁלוּם הַחֹדֶשׁ הַמָּלֵא שֶׁעָבַר. וְיִהְיֶה יוֹם אֶחָד וּשְׁלֹשִׁים רֹאשׁ הַחֹדֶשׁ הַבָּא וּמִמֶּנּוּ הוּא הַמִּנְיָן. וְהוּא יוֹם הַקְּבִיעָה. וּלְפִיכָךְ עוֹשִׂין רָאשֵׁי חֳדָשִׁים בְּחֶשְׁבּוֹן זֶה חֹדֶשׁ אֶחָד יוֹם אֶחָד בִּלְבַד וְחֹדֶשׁ אֶחָד שְׁנֵי יָמִים:","סֵדֶר הֶחֳדָשִׁים הַמְּלֵאִים וְהַחֲסֵרִים לְפִי חֶשְׁבּוֹן זֶה כָּךְ הוּא. תִּשְׁרֵי לְעוֹלָם מָלֵא. וְטֵבֵת לְעוֹלָם חָסֵר. וּמִטֵּבֵת וְאֵילָךְ אֶחָד מָלֵא וְאֶחָד חָסֵר עַל הַסֵּדֶר. כֵּיצַד. טֵבֵת חָסֵר שְׁבָט מָלֵא. אֲדָר חָסֵר נִיסָן מָלֵא. אִיָּר חָסֵר סִיוָן מָלֵא. תַּמּוּז חָסֵר אָב מָלֵא. אֱלוּל חָסֵר. וּבְשָׁנָה הַמְעֻבֶּרֶת אֲדָר רִאשׁוֹן מָלֵא וַאֲדָר שֵׁנִי חָסֵר:","נִשְׁאֲרוּ שְׁנֵי הֶחֳדָשִׁים שֶׁהֵן מַרְחֶשְׁוָן וְכִסְלֵו. פְּעָמִים יִהְיוּ שְׁנֵיהֶם מְלֵאִים וּפְעָמִים יִהְיוּ שְׁנֵיהֶם חֲסֵרִים וּפְעָמִים יִהְיֶה מַרְחֶשְׁוָן חָסֵר וְכִסְלֵו מָלֵא. וְשָׁנָה שֶׁיִּהְיוּ בָּהּ שְׁנֵי חֳדָשִׁים אֵלּוּ מְלֵאִים הִיא שֶׁנִּקְרְאוּ חֳדָשֶׁיהָ שְׁלֵמִים. וְשָׁנָה שֶׁיִּהְיוּ בָּהּ שְׁנֵי חֳדָשִׁים אֵלּוּ חֲסֵרִים נִקְרְאוּ חֳדָשֶׁיהָ חֲסֵרִין. וְשָׁנָה שֶׁיִּהְיוּ בָּהּ מַרְחֶשְׁוָן חָסֵר וְכִסְלֵו מָלֵא נִקְרְאוּ חֳדָשֶׁיהָ כְּסִדְרָן:","דֶּרֶךְ יְדִיעַת הַשָּׁנָה אִם חֳדָשֶׁיהָ מְלֵאִים אוֹ חֲסֵרִין אוֹ כְּסִדְרָן לְפִי חֶשְׁבּוֹן זֶה כָּךְ הוּא. תֵּדַע תְּחִלָּה יוֹם שֶׁנִּקְבַּע בּוֹ רֹאשׁ הַשָּׁנָה שֶׁתִּרְצֶה לֵידַע סִדּוּר חֳדָשֶׁיהָ כְּמוֹ שֶׁבֵּאַרְנוּ בְּפֶרֶק שְׁבִיעִי. וְתֵדַע יוֹם שֶׁיִּקָּבַע בּוֹ רֹאשׁ הַשָּׁנָה שֶׁלְּאַחֲרֶיהָ. וּתְחַשֵּׁב מִנְיַן הַיָּמִים שֶׁבֵּינֵיהֶן חוּץ מִיּוֹם הַקְּבִיעָה שֶׁל זוֹ וְשֶׁל זוֹ. אִם תִּמְצָא בֵּינֵיהֶן שְׁנֵי יָמִים יִהְיוּ חָדְשֵׁי הַשָּׁנָה חֲסֵרִין. וְאִם תִּמְצָא בֵּינֵיהֶם שְׁלֹשָׁה יָמִים יִהְיוּ כְּסִדְרָן. וְאִם תִּמְצָא בֵּינֵיהֶם אַרְבָּעָה יָמִים יִהְיוּ חָדְשֵׁי הַשָּׁנָה שְׁלֵמִים:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיְתָה הַשָּׁנָה שֶׁתִּרְצֶה לֵידַע סִדּוּר חֳדָשֶׁיהָ פְּשׁוּטָה. אֲבָל אִם הָיְתָה מְעֵבֶּרֶת. אִם תִּמְצָא בֵּין יוֹם קְבִיעָתָהּ וּבֵין יוֹם קְבִיעַת שָׁנָה שֶׁלְּאַחֲרֶיהָ אַרְבָּעָה יָמִים יִהְיוּ חָדְשֵׁי אוֹתָהּ שָׁנָה הַמְעֻבֶּרֶת חֲסֵרִים. וְאִם תִּמְצָא בֵּינֵיהֶם חֲמִשָּׁה יָמִים יִהְיוּ כְּסִדְרָן. וְאִם תִּמְצָא בֵּינֵיהֶם שִׁשָּׁה יִהְיוּ שְׁלֵמִים:","כֵּיצַד. הֲרֵי שֶׁרָצִינוּ לֵידַע סִדּוּר חָדְשֵׁי שָׁנָה זוֹ. וְהָיָה רֹאשׁ הַשָּׁנָה בַּחֲמִישִׁי וְהִיא פְּשׁוּטָה וְרֹאשׁ הַשָּׁנָה שֶׁלְּאַחֲרֶיהָ בְּשֵׁנִי בְּשַׁבָּת. נִמְצָא בֵּינֵיהֶן שְׁלֹשָׁה יָמִים. יָדַעְנוּ שֶׁשָּׁנָה זוֹ חֳדָשֶׁיהָ כְּסִדְרָן. וְאִלּוּ הָיָה רֹאשׁ הַשָּׁנָה שֶׁלְּאַחֲרֶיהָ בִּשְׁלִישִׁי הָיוּ חָדְשֵׁי הַשָּׁנָה זוֹ שְׁלֵמִים. וְאִלּוּ הָיָה רֹאשׁ הַשָּׁנָה בְּשָׁנָה זוֹ בְּשַׁבָּת וּבַשָּׁנָה שֶׁלְּאַחֲרֶיהָ בִּשְׁלִישִׁי בְּשַׁבָּת הָיוּ חָדְשֵׁי שָׁנָה זוֹ חֲסֵרִין. וְעַל דֶּרֶךְ זוֹ תְּחַשֵּׁב לַשָּׁנָה הַמְעֻבֶּרֶת כְּמוֹ שֶׁבֵּאַרְנוּ:","יֵשׁ שָׁם סִימָנִין שֶׁתִּסְמֹךְ עֲלֵיהֶם כְּדֵי שֶׁלֹּא תִּטְעֶה בְּחֶשְׁבּוֹן סִדּוּר חָדְשֵׁי הַשָּׁנָה וְהֵן בְּנוּיִין עַל עִקְּרֵי זֶה הַחֶשְׁבּוֹן וְהַקְּבִיעוֹת וְהַדְּחִיּוֹת שֶׁבֵּאַרְנוּ דַּרְכָּם. וְאֵלּוּ הֵן. כָּל שָׁנָה שֶׁיִּהְיֶה רֹאשׁ הַשָּׁנָה בָּהּ בַּשְּׁלִישִׁי תִּהְיֶה לְעוֹלָם כְּסִדְרָן לְפִי חֶשְׁבּוֹן זֶה. בֵּין פְּשׁוּטָה בֵּין מְעֻבֶּרֶת. וְאִם יִהְיֶה רֹאשׁ הַשָּׁנָה בְּשַׁבָּת אוֹ בְּשֵׁנִי לֹא תִּהְיֶה כְּסִדְרָן לְעוֹלָם בֵּין בִּפְשׁוּטָה בֵּין בִּמְעֵבֶּרֶת. וְאִם יִהְיֶה רֹאשׁ הַשָּׁנָה בַּחֲמִישִׁי. אִם פְּשׁוּטָה הִיא אִי אֶפְשָׁר שֶׁיִּהְיוּ חֳדָשֶׁיהָ חֲסֵרִים לְפִי חֶשְׁבּוֹן זֶה. וְאִם מְעֻבֶּרֶת הִיא אִי אֶפְשָׁר שֶׁיִּהְיוּ חֳדָשֶׁיהָ כְּסִדְרָן לְפִי חֶשְׁבּוֹן זֶה:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 5":["הַפּוֹדֶה מַעַשְׂרוֹ לְעַצְמוֹ בֵּין שֶׁהוּא שֶׁלּוֹ בֵּין שֶׁנָּפַל לוֹ בִּירֻשָּׁה בֵּין שֶׁנִּתַּן לוֹ בְּטִבְלוֹ מַתָּנָה כְּמוֹ שֶׁבֵּאַרְנוּ. הֲרֵי זֶה מוֹסִיף עָלָיו חֹמֶשׁ. אִם הָיָה שָׁוֶה אַרְבָּעָה נוֹתֵן חֲמִשָּׁה. שֶׁנֶּאֱמַר (ויקרא כז לא) \"וְאִם גָּאל יִגְאַל אִישׁ מִמַּעַשְׂרוֹ חֲמִשִׁיתוֹ יֹסֵף עָלָיו\":","וְאִשָּׁה שֶׁפָּדָת מַעֲשֵׂר שֵׁנִי שֶׁלָּהּ לְעַצְמָהּ אֵינָהּ מוֹסִיפָה חֹמֶשׁ. מִפִּי הַשְּׁמוּעָה לָמְדוּ (ויקרא כז לא) \"אִישׁ מִמַּעַשְׂרוֹ\" וְלֹא אִשָּׁה. וְכֵן אִם פָּדָה פִּדְיוֹן פֵּרוֹת הַמַּעֲשֵׂר לְעַצְמוֹ מוֹסִיף חֹמֶשׁ:","פָּדָה פֵּרוֹת מַעַשְׂרוֹ וְהוֹסִיף חֹמֶשׁ וְחָזַר וּפָדָה הַפִּדְיוֹן לְעַצְמוֹ פַּעַם שְׁנִיָּה מוֹסִיף חֹמֶשׁ שֵׁנִי עַל הַקֶּרֶן בִּלְבַד וְאֵינוֹ מוֹסִיף חֹמֶשׁ עַל הַחֹמֶשׁ:","מַעֲשֵׂר שֵׁנִי שֶׁאֵין בְּחֻמְשׁוֹ שְׁוֵה פְּרוּטָה אֵינוֹ מוֹסִיף עָלָיו חֹמֶשׁ. וְכֵן מַעֲשֵׂר שֶׁאֵין דָּמָיו יְדוּעִין דַּיּוֹ שֶׁיֹּאמַר הוּא וְחֻמְשׁוֹ מְחֻלָּל עַל הַסֶּלַע הַזֶּה. וְכָל מַעֲשֵׂר שֶׁהוּא אֵינוֹ פּוֹדֵהוּ מִשֶּׁלּוֹ אֵינוֹ מוֹסִיף חֹמֶשׁ. וּמַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי אֵינוֹ מוֹסִיף עָלָיו חֹמֶשׁ:","הַפּוֹדֶה מַעֲשֵׂר שֵׁנִי וְהָיָה לוֹ מַעֲשֵׂר שֵׁנִי אַחֵר שֶׁלֹּא נִפְדָּה. אִם אֵין בְּחֻמְשׁוֹ שְׁוֵה פְּרוּטָה דַּיּוֹ שֶׁיֹּאמַר הוּא וְחֻמְשׁוֹ מְחֻלָּל עַל מָעוֹת הָרִאשׁוֹנוֹת לְפִי שֶׁאִי אֶפְשָׁר לְאָדָם לְצַמְצֵם אֶת מְעוֹתָיו:","הַפּוֹדֶה מַעֲשֵׂר בְּיוֹתֵר עַל דָּמָיו לֹא נִתְפְּסָה הַתּוֹסֶפֶת לַמַעֲשֵׂר:","בַּעַל הַבַּיִת אוֹמֵר בְּסֶלַע וְאַחֵר אוֹמֵר בְּסֶלַע. בַּעַל הַבַּיִת קֹדֶם מִפְּנֵי שֶׁהוּא מוֹסִיף חֹמֶשׁ. בַּעַל הַבַּיִת אוֹמֵר בְּסֶלַע וְאַחֵר אוֹמֵר בְּסֶלַע וּפְרוּטָה. הָאַחֵר קֹדֶם מִפְּנֵי שֶׁמּוֹסִיף עַל הַקֶּרֶן:","מֻתָּר לְהַעֲרִים עַל פִּדְיוֹן מַעַשְׂרוֹ. כֵּיצַד. אוֹמֵר לִבְנוֹ וּלְבִתּוֹ הַגְּדוֹלִים וּלְעַבְדּוֹ הָעִבְרִי הֵא לְךָ אֶת הַמָּעוֹת הָאֵלּוּ וּפְדֵה לְךָ בָּהֶן הַמַּעֲשֵׂר כְּדֵי שֶׁלֹּא יוֹסִיף חֹמֶשׁ. אֲבָל לֹא יֹאמַר לוֹ פְּדֵה לִי בָּהֶן. וְכֵן אִם אָמַר לוֹ פְּדֵה לִי מִשֶּׁלְּךָ אֵינוֹ מוֹסִיף חֹמֶשׁ:","אֲבָל לֹא יִתֵּן הַמָּעוֹת לִפְדּוֹת לִבְנוֹ וּלְבִתּוֹ הַקְּטַנִּים וּלְעַבְדּוֹ וְשִׁפְחָתוֹ הַכְּנַעֲנִים מִפְּנֵי שֶׁיָּדָן כְּיָדוֹ. נָתַן לְשִׁפְחָתוֹ הָעִבְרִיָּה אִם מַעֲשֵׂר שֵׁנִי זֶה מִדִּבְרֵיהֶם כְּגוֹן שֶׁהָיָה מֵעָצִיץ שֶׁאֵינוֹ נָקוּב דְּבָרָיו קַיָּמִין. שֶׁאָמָה הָעִבְרִיָּה קְטַנָּה הִיא וְאֵין הַקָּטָן זוֹכֶה לַאֲחֵרִים אֶלָּא בְּדָבָר שֶׁהוּא מִדִּבְרֵיהֶם:","וְכֵן מַעֲרִים וְנוֹתֵן הַמַּעֲשֵׂר מַתָּנָה כְּשֶׁהוּא בְּטִבְלוֹ. וְאוֹמֵר הַנּוֹתֵן הֲרֵי הַפֵּרוֹת הָאֵלּוּ מְחֻלָּלִין עַל מָעוֹת שֶׁבַּבַּיִת:","שְׁנֵי אַחִין אוֹ שְׁנֵי שֻׁתָּפִין [אָב וּבְנוֹ] פּוֹדִין זֶה לָזֶה מַעֲשֵׂר שֵׁנִי כְּדֵי שֶׁלֹּא יוֹסִיף חֹמֶשׁ. אִשָּׁה שֶׁהִכְנִיסָה לְבַעְלָהּ מַעֲשֵׂר שֵׁנִי הוֹאִיל וְהוּא מָמוֹן גָּבוֹהַּ כְּמוֹ שֶׁבֵּאַרְנוּ לֹא קָנָה בַּעַל. לְפִיכָךְ אִם פָּדָהוּ אֵינוֹ מוֹסִיף חֹמֶשׁ:","הַפּוֹדֶה מַעֲשֵׂר שֵׁנִי לְעַצְמוֹ וְנָתַן אֶת הַקֶּרֶן וְלֹא נָתַן אֶת הַחֹמֶשׁ. אַף עַל פִּי שֶׁאֵין הַחֹמֶשׁ מְעַכֵּב וַהֲרֵי נִתְחַלֵּל לֹא יֹאכַל עַד שֶׁיִּתֵּן הַחֹמֶשׁ וַאֲפִלּוּ בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יִפְשַׁע וְלֹא יִתֵּן:","מָעוֹת מַעֲשֵׂר שֵׁנִי אִם רָצָה לְצָרְפָם בְּדִינְרֵי זָהָב כְּדֵי לְהָקֵל מַשָּׂאָן מְצָרְפָן. וְאִם צֵרְפָן לְעַצְמוֹ אֵינוֹ מוֹסִיף חֹמֶשׁ שֶׁאֵין זֶה דֶּרֶךְ פְּדִיָּה:","הַפּוֹרֵט סֶלַע מִמְּעוֹת מַעֲשֵׂר שֵׁנִי בֵּין בִּירוּשָׁלַיִם בֵּין חוּץ לִירוּשָׁלַיִם לֹא יְצָרְפֶנָּה כֻּלָּהּ בְּמָעוֹת נְחשֶׁת אֶלָּא בְּשֶׁקֶל מָעוֹת כֶּסֶף וּבְשֶׁקֶל מָעוֹת נְחשֶׁת:","מֻתָּר לְחַלֵּל כֶּסֶף מַעֲשֵׂר עִם פֵּרוֹת מַעֲשֵׂר עַל הַכֶּסֶף וְהוּא שֶׁיְּהוּ בַּפֵּרוֹת פָּחוֹת מִשְּׁוֵה דִּינָר. אֲבָל אִם הָיָה בָּהֶן שְׁוֵה דִּינָר לֹא יְחַלְּלֵם עִם הַכֶּסֶף אֶלָּא בִּפְנֵי עַצְמָן. כֵּיצַד. הָיוּ לוֹ פֵּרוֹת שְׁוֵה דִּינָר וּשְׁלֹשָׁה דִּינָרִין שֶׁל מַעֲשֵׂר שֵׁנִי אֵינוֹ מְחַלֵּל הַכּל עַל סֶלַע אַחַת. אֲבָל אִם הָיָה לוֹ חֲצִי דִּינָר פֵּרוֹת וַחֲצִי דִּינָר מָעוֹת מְחַלֵּל שְׁנֵיהֶם עַל דִּינָר אֶחָד:"],"Mishneh Torah, Sheqel Dues 3":["חֲצָיֵי הַשְּׁקָלִים הַכּל צְרִיכִין לָהֶן כְּדֵי שֶׁיִּתֵּן כָּל אֶחָד וְאֶחָד חֲצִי שֶׁקֶל שֶׁהוּא חַיָּב. לְפִיכָךְ כְּשֶׁהָיָה אָדָם הוֹלֵךְ אֵצֶל הַשֻּׁלְחָנִי וּמְצָרֵף שֶׁקֶל בִּשְׁנֵי חֲצָאִין יִתֵּן לוֹ תּוֹסֶפֶת עַל הַשֶּׁקֶל. וְאוֹתָהּ הַתּוֹסֶפֶת נִקְרֵאת קַלְבּוֹן. לְפִיכָךְ שְׁנַיִם שֶׁנָּתְנוּ שֶׁקֶל עַל שְׁנֵיהֶם חַיָּבִין בְּקַלְבּוֹן:","כָּל מִי שֶׁאֵינוֹ חַיָּב בִּשְׁקָלִים כְּגוֹן שְׁתֵּי נָשִׁים אוֹ שְׁנֵי עֲבָדִים שֶׁנָּתְנוּ שֶׁקֶל פְּטוּרִים מִן הַקַּלְבּוֹן. וְכֵן אִם הָיָה אֶחָד חַיָּב וְאֶחָד פָּטוּר וְנָתַן הַחַיָּב עַל יַד הַפְּטוּר כְּגוֹן אִישׁ שֶׁנָּתַן שֶׁקֶל עָלָיו וְעַל אִשָּׁה אוֹ עֶבֶד פָּטוּר מִן הַקַּלְבּוֹן. וְכֵן הַכֹּהֲנִים פְּטוּרִין מִן הַקַּלְבּוֹן וְהַשּׁוֹקֵל עַל יַד הַכֹּהֵן פָּטוּר מִן הַקַּלְבּוֹן:","הַנּוֹתֵן שֶׁקֶל עָלָיו וְעַל הֶעָנִי אוֹ עַל שְׁכֵנוֹ אוֹ עַל בֶּן עִירוֹ. אִם נְתָנוֹ לָהֶם מַתָּנָה פָּטוּר מִן הַקַּלְבּוֹן. שֶׁהֲרֵי נָתַן חֲצִי שֶׁקֶל מַתָּנָה כְּדֵי לְהַרְבּוֹת בִּשְׁקָלִים. וְאִם נָתַן לָהֶם הַחֲצִי שֶׁשָּׁקַל עַל יָדָם דֶּרֶךְ הַלְוָאָה עַד שֶׁיַּחֲזִירוּ לוֹ כְּשֶׁתִּמְצָא יָדָם חַיָּב הַקַּלְבּוֹן:","הָאַחִין שֶׁעֲדַיִן לֹא חָלְקוּ מַה שֶּׁהִנִּיחַ לָהֶם אֲבִיהֶם. וְכֵן הַשֻּׁתָּפִים שֶׁנָּתְנוּ שֶׁקֶל עַל יְדֵי שְׁנֵיהֶם פְּטוּרִין מִן הַקַּלְבּוֹן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֻׁתָּפִין שֶׁנָּשְׂאוּ וְנָתְנוּ בִּמְעוֹת הַשֻּׁתָּפוּת וְנִשְׁתַּנָּה עֵין הַמָּעוֹת. אֲבָל אִם הֵבִיא זֶה מְעוֹתָיו וְזֶה מְעוֹתָיו וְעֵרְבוּם וַעֲדַיִן לֹא נִשְׁתַּנּוּ הַמָּעוֹת וְלֹא הוֹצִיאוּם הֲרֵי אֵלּוּ חַיָּבִין בְּקַלְבּוֹן. נָשְׂאוּ וְנָתְנוּ וְאַחַר זְמַן חָלְקוּ וְחָזְרוּ וְנִשְׁתַּתְּפוּ חַיָּבִין בְּקַלְבּוֹן עַד שֶׁיִּשְּׂאוּ וְיִתְּנוּ בְּשֻׁתָּפוּת זוֹ הָאַחֲרוֹנָה וְיִשְׁתַּנּוּ הַמָּעוֹת:","הָאַחִין וְהַשֻּׁתָּפִין שֶׁהָיָה לָהֶן בְּהֵמָה וּכְסָפִים וְחָלְקוּ בַּכְּסָפִים חַיָּבִים בְּקַלְבּוֹן. אַף עַל פִּי שֶׁעֲדַיִן לֹא חָלְקוּ הַבְּהֵמָה. וְאִם חָלְקוּ הַבְּהֵמָה וְלֹא חָלְקוּ הַכְּסָפִים פְּטוּרִין מִן הַקַּלְבּוֹן עַד שֶׁיַּחְלְקוּ הַכְּסָפִים וְאֵין אוֹמְרִין הֲרֵי הֵם עוֹמְדִין לַחֲלוּקָה:","הַנּוֹתֵן שֶׁקֶל לְהֶקְדֵּשׁ כְּדֵי שֶׁיְּחַשְּׁבוּ לוֹ מַחֲצִית הַשֶּׁקֶל שֶׁהוּא חַיָּב בָּהּ וְיִטּל חֲצִי שֶׁקֶל מִמַּה שֶּׁנִּגְבָּה מִן הָאֲחֵרִים חַיָּב שְׁנֵי קַלְבּוֹנוֹת. שֶׁאִלּוּ הָיָה הַשֶּׁקֶל כֻּלּוֹ לִשְׁקָלִים הָיָה חַיָּב קַלְבּוֹן אֶחָד:","כַּמָּה הוּא שִׁעוּר הַקַּלְבּוֹן. בִּזְמַן שֶׁהָיוּ נוֹתְנִין בְּמַחֲצִית הַשֶּׁקֶל שְׁנֵי דִּינָרִין הָיָה הַקַּלְבּוֹן חֲצִי מָעָה שֶׁהוּא אֶחָד מִשְּׁנֵים עָשָׂר בְּדִינָר. וּמֵעוֹלָם לֹא נִתַּן הַקַּלְבּוֹן פָּחוֹת מִזֶּה. וְהַקַּלְבּוֹנוֹת אֵינָן כִּשְׁקָלִים אֶלָּא מַנִּיחִין אוֹתָן הַשֻּׁלְחָנִים בִּפְנֵי עַצְמָן עַד שֶׁיִּסְתַּפֵּק מֵהֶן הַהֶקְדֵּשׁ:","מִי שֶׁאָבַד שִׁקְלוֹ חַיָּב בְּאַחְרָיוּתוֹ עַד שֶׁיִּמְסְרֶנּוּ לַגִּזְבָּר. בְּנֵי הָעִיר שֶׁשָּׁלְחוּ אֶת שִׁקְלֵיהֶן בְּיַד שָׁלִיחַ וְנִגְנְבוּ אוֹ אָבְדוּ. אִם שׁוֹמֵר חִנָּם הוּא הֲרֵי זֶה נִשְׁבָּע לָהֶם וְנִפְטָר כְּדִין כָּל שׁוֹמְרֵי חִנָּם וְהֵן חוֹזְרִין וְנוֹתְנִין שִׁקְלֵיהֶן פַּעַם שְׁנִיָּה. וְאִם אָמְרוּ אַנְשֵׁי הָעִיר הוֹאִיל וְאָנוּ מְשַׁלְּמִין שְׁקָלֵינוּ אֵין רְצוֹנֵנוּ שֶׁיִּשָּׁבַע הַשָּׁלִיחַ שֶׁהוּא נֶאֱמָן לָנוּ אֵין שׁוֹמְעִין לָהֶן. לְפִי שֶׁתַּקָּנַת חֲכָמִים הִיא שֶׁאֵין הֶקְדֵּשׁ יוֹצֵא בְּלֹא שְׁבוּעָה. נִמְצְאוּ הַשְּׁקָלִים הָרִאשׁוֹנִים אַחַר שֶׁנִּשְׁבַּע הַשָּׁלִיחַ אֵלּוּ וְאֵלּוּ שְׁקָלִים הֵם וְאֵין עוֹלִין לָהֶן לְשָׁנָה אַחֶרֶת. וְהָרִאשׁוֹנִים יִפְּלוּ לְשִׁקְלֵי הַשָּׁנָה וְהָאַחֲרוֹנִים יִפְּלוּ לְשִׁקְלֵי שָׁנָה שֶׁעָבְרָה:","שָׁלְחוּ אֶת שִׁקְלֵיהֶם בְּיַד שׁוֹמֵר שָׂכָר שֶׁהֲרֵי הוּא חַיָּב בִּגְנֵבָה וַאֲבֵדָה וְאָבְדוּ מִמֶּנּוּ בְּאֹנֶס. כְּגוֹן שֶׁלְּקָחוּם לִסְטִים מְזֻיָּנִים שֶׁהוּא פָּטוּר. רוֹאִין אִם אַחַר שֶׁנִּתְרְמָה הַתְּרוּמָה נֶאֱנַס נִשְׁבָּע הַשָּׁלִיחַ לַגִּזְבָּרִים וּבְנֵי הָעִיר פְּטוּרִין. שֶׁהַתּוֹרֵם תּוֹרֵם עַל הַגָּבוּי וְעַל הֶעָתִיד לִגָּבוֹת וּבִרְשׁוּת הֶקְדֵּשׁ הֵן וּבְנֵי הָעִיר מֶה הָיָה לָהֶן לַעֲשׂוֹת הֲרֵי לֹא מָסְרוּ אֶלָּא לְשׁוֹמֵר שָׂכָר שֶׁהוּא חַיָּב בִּגְנֵבָה וַאֲבֵדָה. אֲבָל הָאֹנֶס אֵינוֹ מָצוּי. וְאִם אָבְדוּ קֹדֶם שֶׁנִּתְרְמָה הַתְּרוּמָה עֲדַיִן בִּרְשׁוּת בְּנֵי הָעִיר הֵם וְהַשָּׁלִיחַ נִשְׁבָּע לִפְנֵי אַנְשֵׁי הָעִיר וְהֵן מְשַׁלְּמִין. נִשְׁבַּע וְגָבוּ שְׁקָלִים שֵׁנִית וְאַחַר כָּךְ הֶחֱזִירוּם הַלִּסְטִים אֵלּוּ וְאֵלּוּ שְׁקָלִים וְאֵין עוֹלִין לָהֶן לְשָׁנָה אַחֶרֶת וְהַשְּׁנִיִּים יִפְּלוּ לְשִׁקְלֵי שָׁנָה שֶׁעָבְרָה. יֵשׁ מִי שֶׁאוֹמֵר שֶׁהַשְּׁקָלִים הָרִאשׁוֹנִים שֶׁיִּפְּלוּ לְשִׁקְלֵי הַשָּׁנָה הֵם הַשְּׁקָלִים שֶׁנִּגְּבּוּ בַּתְּחִלָּה וְאָבְדוּ אוֹ נֶאֶנְסוּ וְחָזְרוּ. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁהַשְּׁקָלִים הָרִאשׁוֹנִים הֵן שֶׁהִגִּיעוּ לְיַד הַגִּזְבָּר תְּחִלָּה:","הַנּוֹתֵן חֲצִי שֶׁקֶל לַחֲבֵרוֹ לְהוֹלִיכוֹ לְשֻׁלְחָנִי לִשְׁקל אוֹתוֹ עַל יָדוֹ. הָלַךְ וּשְׁקָלוֹ עַל יְדֵי עַצְמוֹ כְּדֵי שֶׁלֹּא יְמַשְׁכְּנוּ אוֹתוֹ. אִם נִתְרְמָה הַתְּרוּמָה מֵעַל הַשּׁוֹקֵל שֶׁזֶּה הַשֶּׁקֶל בִּרְשׁוּת הֶקְדֵּשׁ הוּא שֶׁכְּבָר תְּרָמוֹ עַל הֶעָתִיד לִגְבּוֹת וְנִמְצָא זֶה הִצִּיל עַצְמוֹ בְּמָמוֹן הַהֶקְדֵּשׁ וְנֶהֱנָה בַּשֶּׁקֶל הַזֶּה. וְאִם לֹא נִתְרְמָה הַתְּרוּמָה לֹא מָעַל וְהוּא חַיָּב לִתֵּן לַחֲבֵרוֹ חֲצִי שֶׁקֶל שֶׁנָּתַן לוֹ. וְכֵן הַגּוֹזֵל אוֹ הַגּוֹנֵב חֲצִי שֶׁקֶל וּשְׁקָלוֹ יָצָא וְהוּא חַיָּב לְשַׁלֵּם לַבְּעָלִים שְׁנַיִם אוֹ לְהוֹסִיף חֹמֶשׁ:","הַנּוֹתֵן מַחֲצִית הַשֶּׁקֶל מִן הַהֶקְדֵּשׁ וְנִתְרְמָה הַתְּרוּמָה מִמֶּנּוּ. כְּשֶׁיִּסְתַּפְּקוּ מִמֶּנָּה יִתְחַיֵּב בִּמְעִילָה וְיָצָא יְדֵי מַחֲצִית הַשֶּׁקֶל. נְתָנוֹ מִמְּעוֹת מַעֲשֵׂר שֵׁנִי יֹאכַל כְּנֶגְדּוֹ בִּירוּשָׁלַיִם. מִדְּמֵי שְׁבִיעִית יֹאכַל כְּנֶגְדּוֹ בִּקְדֻשַּׁת שְׁבִיעִית. הָיָה שֶׁל עִיר הַנִּדַּחַת לֹא עָשָׂה כְּלוּם:","הַמַּפְרִישׁ שִׁקְלוֹ וְסָבוּר שֶׁהוּא חַיָּב בּוֹ וְנִמְצָא שֶׁאֵינוֹ חַיָּב לֹא קָדַּשׁ. הַמַּפְרִישׁ שְׁנַיִם וְנִמְצָא שֶׁאֵינוֹ חַיָּב אֶלָּא אֶחָד. אִם בְּזֶה אַחַר זֶה הָאַחֲרוֹן לֹא קָדַּשׁ. וְאִם בְּבַת אַחַת הָאֶחָד שְׁקָלִים וְהַשֵּׁנִי מוֹתַר שְׁקָלִים. הִפְרִישׁ שִׁקְלוֹ וָמֵת יִפּל לִנְדָבָה:","הַלּוֹקֵחַ מָעוֹת בְּיָדוֹ וְאָמַר אֵלּוּ לְשִׁקְלִי. אוֹ שֶׁהָיָה מְלַקֵּט מָעָה מָעָה אוֹ פְּרוּטָה פְּרוּטָה וּכְשֶׁהִתְחִיל לְלַקֵּט אָמַר הֲרֵינִי מְלַקֵּט מָעוֹת לְשִׁקְלִי. אֲפִלּוּ לִקֵּט מְלֹא כִּיס נוֹתֵן מֵהֶן חֲצִי שֶׁקֶל שֶׁהוּא חַיָּב בּוֹ וְהַשְּׁאָר חֻלִּין שֶׁמּוֹתַר הַשְּׁקָלִים חֻלִּין:","מָעוֹת שֶׁנִּמְצְאוּ בֵּין תֵּבָה שֶׁל שְׁקָלִים לְתֵבָה שֶׁל נְדָבָה. קָרוֹב לַשְּׁקָלִים יִפְּלוּ לִשְׁקָלִים. קָרוֹב לַנְּדָבָה יִפְּלוּ לִנְדָבָה. מֶחֱצָה עַל מֶחֱצָה יִפְּלוּ לִנְדָבָה מִפְּנֵי שֶׁהַנְּדָבָה כֻּלָּהּ עוֹלָה לַאִשִּׁים וְהַשְּׁקָלִים מִסְתַּפְּקִין מֵהֶן לְעוֹלוֹת וְלִדְבָרִים אֲחֵרִים:","וְכֵן כָּל הַמָּעוֹת הַנִּמְצָאִים בֵּין כָּל תֵּבָה וְתֵבָה יִפְּלוּ לַקָּרוֹב. נִמְצְאוּ מֶחֱצָה לְמֶחֱצָה. אִם בֵּין עֵצִים לַלְּבוֹנָה נִמְצְאוּ יִפְּלוּ לַלְּבוֹנָה. בֵּין קִנִּים לְגוֹזָלֵי עוֹלָה יִפְּלוּ לְגוֹזָלֵי עוֹלָה. זֶה הַכְּלָל הוֹלְכִין אַחַר הַקָּרוֹב בְּכֻלָּן. מֶחֱצָה לְמֶחֱצָה לְהַחֲמִיר. וְכָל הַמָּעוֹת הַנִּמְצָאוֹת בְּהַר הַבַּיִת חֻלִּין שֶׁאֵין הַגִּזְבָּר מוֹצִיא מָעוֹת מִתְּרוּמַת הַלִּשְׁכָּה עַד שֶׁהוּא מְחַלְּלָן עַל הַבְּהֵמוֹת שֶׁלּוֹקֵחַ לְקָרְבָּנוֹת:"],"Mishneh Torah, Slaves 3":["כָּל עֶבֶד עִבְרִי הֲרֵי הָאָדוֹן חַיָּב בִּמְזוֹנוֹת אִשְׁתּוֹ הַנְּשׂוּאָה לוֹ וְלֹא אֲרוּסָה וְשׁוֹמֶרֶת יָבָם. וְהוּא שֶׁתִּהְיֶה מֻתֶּרֶת לוֹ. אֲבָל אִם הָיְתָה מֵאִסּוּרֵי לָאוִין אֲפִלּוּ שְׁנִיָּה אֵינוֹ חַיָּב בִּמְזוֹנוֹתֶיהָ שֶׁנֶּאֱמַר אִשְׁתּוֹ עִמּוֹ אִשָּׁה הָרְאוּיָה לַעֲמֹד עִמּוֹ. וְכֵן חַיָּב בִּמְזוֹנוֹת בָּנָיו וּבְנוֹתָיו. בִּמְכָרוּהוּ בֵּית דִּין נֶאֱמַר (שמות כא ג) \"אִם בַּעַל אִשָּׁה הוּא וְיָצְאָה אִשְׁתּוֹ עִמּוֹ\". וְכִי תַּעֲלֶה עַל דַּעְתְּךָ שֶׁכֵּיוָן שֶׁנִּקְנָה זֶה נִשְׁתַּעְבְּדָה אִשְׁתּוֹ. אֲבָל לֹא בָּא לְלַמֵּד אֶלָּא שֶׁהָאָדוֹן חַיָּב בִּמְזוֹנוֹתֶיהָ. וּבְמוֹכֵר עַצְמוֹ נֶאֱמַר (ויקרא כה מא) \"וְיָצָא מֵעִמָּךְ הוּא וּבָנָיו עִמּוֹ\". וּבְנִמְכָּר לְעַכּוּ\"ם נֶאֱמַר (ויקרא כה נד) \"וְיָצָא בִּשְׁנַת הַיֹּבֵל הוּא וּבָנָיו עִמּוֹ\". אֶחָד אִשָּׁה וּבָנִים שֶׁהָיוּ לוֹ בִּשְׁעַת מְכִירָה אוֹ אִשָּׁה וּבָנִים שֶׁהָיוּ לוֹ אַחַר מְכִירָתוֹ. וְהוּא שֶׁיִּקָּחֶנָּה מִדַּעַת הָאָדוֹן. אֲבָל אִם לְקָחָהּ שֶׁלֹּא מִדַּעַת רַבּוֹ אֵינוֹ חַיָּב בִּמְזוֹנוֹתֶיהָ:","אַף עַל פִּי שֶׁהָאָדוֹן חַיָּב בִּמְזוֹנוֹת אִשְׁתּוֹ וּבָנָיו אֵין לוֹ בְּמַעֲשֵׂה יְדֵיהֶם כְּלוּם אֶלָּא הֲרֵי מַעֲשֵׂה הָאִשָּׁה וּמְצִיאָתָהּ לְבַעֲלָהּ. וְכָל שֶׁזּוֹכֶה הַבַּעַל בְּאִשְׁתּוֹ זוֹכֶה זֶה אַף עַל פִּי שֶׁהוּא עֶבֶד עִבְרִי:","מִי שֶׁמְּכָרוּהוּ בֵּית דִּין יֵשׁ לְרַבּוֹ לִתֵּן לוֹ שִׁפְחָה כְּנַעֲנִית. בֵּין הָאָדוֹן בֵּין בְּנוֹ שֶׁל אֲדוֹן אִם מֵת אָבִיו הֲרֵי זֶה נוֹתֵן לוֹ שִׁפְחָה. וְכוֹפֵהוּ עַל זֶה כְּדֵי שֶׁיּוֹלִיד מִמֶּנָּה עֲבָדִים. וַהֲרֵי הִיא מֻתֶּרֶת לוֹ כָּל יְמֵי עַבְדוּתוֹ שֶׁנֶּאֱמַר (שמות כא ד) \"אִם אֲדֹנָיו יִתֶּן לוֹ אִשָּׁה\" וְגוֹ'. וְהַמּוֹכֵר עַצְמוֹ אָסוּר בְּשִׁפְחָה כְּנַעֲנִית כִּשְׁאָר כָּל יִשְׂרָאֵל:","אֵין עֶבֶד עִבְרִי מֻתָּר בְּשִׁפְחָה כְּנַעֲנִית עַד שֶׁתִּהְיֶה לוֹ אִשָּׁה יִשְׂרְאֵלִית וּבָנִים. אֲבָל אִם אֵין לוֹ אִשָּׁה וּבָנִים אֵין רַבּוֹ מוֹסֵר לוֹ שִׁפְחָה כְּנַעֲנִית. וְדָבָר זֶה קַבָּלָה הוּא אֲפִלּוּ הָיָה הַנִּמְכָּר כֹּהֵן הֲרֵי זֶה מֻתָּר בְּשִׁפְחָה כְּנַעֲנִית כָּל יְמֵי עַבְדוּתוֹ:","אִם הָיוּ לוֹ אִשָּׁה וּבָנִים אַף עַל פִּי שֶׁמּוֹסֵר לוֹ רַבּוֹ שִׁפְחָה כְּנַעֲנִית אֵינוֹ יָכוֹל לְהַפְרִישׁוֹ מֵאִשְׁתּוֹ וּבָנָיו שֶׁנֶּאֱמַר (שמות כא ג) \"אִשְׁתּוֹ עִמּוֹ\". וְאֵינוֹ יָכוֹל לִתֵּן לוֹ שְׁתֵּי שְׁפָחוֹת. וְלֹא לִתֵּן שִׁפְחָה אַחַת לִשְׁנֵי עֲבָדָיו הָעִבְרִים כְּדֶרֶךְ שֶׁנּוֹתֵן לַכְּנַעֲנִיִּים שֶׁנֶּאֱמַר (שמות כא ד) \"יִתֶּן לוֹ אִשָּׁה\". נִרְצָע שֶׁמָּסַר לוֹ רַבּוֹ שִׁפְחָה כְּנַעֲנִית וְהִגִּיעַ יוֹבֵל וְהָיָה רַבּוֹ מְסָרֵב בּוֹ לָצֵאת וְאֵינוֹ רוֹצֶה לָצֵאת וְחָבַל בּוֹ פָּטוּר שֶׁהֲרֵי נֶאֱסַר בְּשִׁפְחָה:","הַמּוֹכֵר עַצְמוֹ אֵינוֹ נִרְצָע. אֲבָל מְכָרוּהוּ בֵּית דִּין וְעָבַד שֵׁשׁ וְלֹא רָצָה לָצֵאת הֲרֵי זֶה נִרְצָע וְעוֹבֵד עַד שְׁנַת הַיּוֹבֵל אוֹ עַד שֶׁיָּמוּת הָאָדוֹן:","אַף עַל פִּי שֶׁהִנִּיחַ בֵּן אֵין הַנִּרְצָע עוֹבֵד אֶת הַבֵּן מִפִּי הַשְּׁמוּעָה לָמְדוּ (שמות כא ו) \"וַעֲבָדוֹ\", לוֹ וְלֹא לִבְנוֹ. (שמות כא ו) \"לְעוֹלָם\", לְעוֹלָמוֹ שֶׁל יוֹבֵל. נִמְצֵאתָ לָמֵד שֶׁהַנִּרְצָע אֵינוֹ קוֹנֶה אֶת עַצְמוֹ אֶלָּא בַּיּוֹבֵל וּבְמִיתַת הָאָדוֹן:","עֶבֶד עִבְרִי כֹּהֵן אֵינוֹ נִרְצָע מִפְּנֵי שֶׁנַּעֲשָׂה בַּעַל מוּם וַהֲרֵי הוּא אוֹמֵר (ויקרא כה מא) \"וְשָׁב אֶל מִשְׁפַּחְתּוֹ\" לַחֲזָקָה שֶׁהָיָה בָּהּ. וְאֵינוֹ שָׁב לַשְּׂרָרָה שֶׁהָיָה בָּהּ:","כֵּיצַד רוֹצְעִין. מְבִיאוֹ לְבֵית דִּין שֶׁל שְׁלֹשָׁה וְאוֹמֵר דְּבָרָיו לִפְנֵיהֶם וּמַגִּישׁוֹ לְסוֹף שֵׁשׁ אֶל הַדֶּלֶת אוֹ אֶל הַמְּזוּזָה כְּשֶׁהֵן עוֹמְדִין בְּבִנְיָן. בֵּין דֶּלֶת וּמְזוּזָה שֶׁל אָדוֹן בֵּין שֶׁל כָּל אָדָם. וְנוֹקֵב אֶת אָזְנוֹ הַיְמָנִית בְּגוּפָהּ שֶׁל אֹזֶן בְּמַרְצֵעַ שֶׁל מַתֶּכֶת עַד שֶׁיַּגִּיעַ לַדֶּלֶת שֶׁנֶּאֱמַר (דברים טו יז) \"וְנָתַתָּ בְאָזְנוֹ וּבַדֶּלֶת\". וְלֹא נֶאֱמַר (שמות כא ו) \"מְזוּזָה\" אֶלָּא שֶׁיִּהְיֶה עוֹמֵד בֵּין אֵצֶל דֶּלֶת בֵּין אֵצֶל מְזוּזָה. וּמָה מְזוּזָה כְּשֶׁהִיא עוֹמֶדֶת אַף דֶּלֶת כְּשֶׁהִיא עוֹמֶדֶת. אֲבָל הָרְצִיעָה בַּדֶּלֶת אַף עַל פִּי שֶׁאֵין שָׁם מְזוּזָה. הָאָדוֹן הוּא שֶׁרוֹצֵעַ בְּעַצְמוֹ שֶׁנֶּאֱמַר (שמות כא ו) \"וְרָצַע אֲדֹנָיו\" לֹא בְּנוֹ וְלֹא שְׁלוּחוֹ וְלֹא שְׁלִיחַ בֵּית דִּין. וְאֵין רוֹצְעִין שְׁנֵי עֲבָדִים כְּאֶחָד שֶׁאֵין עוֹשִׂין מִצְוֹת חֲבִילוֹת חֲבִילוֹת:","(שמות כא ה) \"וְאִם אָמֹר יֹאמַר הָעֶבֶד\" עַד שֶׁיֹּאמַר וְיִשְׁנֶה. הָעֶבֶד עַד שֶׁיֹּאמַר כְּשֶׁהוּא עֶבֶד אֲבָל אִם אָמַר אַחַר שֵׁשׁ אֵינוֹ נִרְצָע עַד שֶׁיֹּאמַר וְיִשְׁנֶה בְּסוֹף שֵׁשׁ בִּתְחִלַּת פְּרוּטָה אַחֲרוֹנָה. כֵּיצַד. כְּגוֹן שֶׁנִּשְׁאַר מִן הַיּוֹם שְׁוֵה פְּרוּטָה מִדְּמֵי מְכִירָתוֹ אוֹ יֶתֶר מְעַט. אֲבָל אִם נִשְׁאַר פָּחוֹת מִשְּׁוֵה פְּרוּטָה הֲרֵי זֶה כְּאוֹמֵר אַחַר שֵׁשׁ:","הָיְתָה לָעֶבֶד שִׁפְחָה כְּנַעֲנִית וְלוֹ מִמֶּנָּה בָּנִים וּלְרַבּוֹ אֵין אִשָּׁה וּבָנִים אֵינוֹ נִרְצָע שֶׁנֶּאֱמַר (דברים טו טז) \"כִּי אֲהֵבְךָ וְאֶת בֵּיתֶךָ\". לְרַבּוֹ אִשָּׁה וּבָנִים וְלוֹ אֵין אִשָּׁה וּבָנִים אֵינוֹ נִרְצָע שֶׁנֶּאֱמַר (שמות כא ה) \"אָהַבְתִּי אֶת אֲדֹנִי אֶת אִשְׁתִּי וְאֶת בָּנָי\". הוּא אוֹהֵב אֶת רַבּוֹ וְרַבּוֹ אֵינוֹ אוֹהֲבוֹ אֵינוֹ נִרְצָע שֶׁנֶּאֱמַר כִּי טוֹב לוֹ עִמָּךְ. רַבּוֹ אוֹהֲבוֹ וְהוּא אֵינוֹ אוֹהֵב אֶת רַבּוֹ אֵינוֹ נִרְצָע שֶׁנֶּאֱמַר כִּי אֲהֵבְךָ. הוּא חוֹלֶה וְרַבּוֹ אֵינוֹ חוֹלֶה אֵינוֹ נִרְצָע שֶׁנֶּאֱמַר כִּי טוֹב לוֹ עִמָּךְ. רַבּוֹ חוֹלֶה וְהוּא אֵינוֹ חוֹלֶה אוֹ שֶׁהָיוּ שְׁנֵיהֶם חוֹלִים אֵינוֹ נִרְצָע שֶׁנֶּאֱמַר (דברים טו טז) \"כִּי טוֹב לוֹ עִמָּךְ\" עַד שֶׁיִּהְיוּ שְׁנֵיהֶם בְּטוֹבָה:","מַה בֵּין מוֹכֵר עַצְמוֹ לִמְכָרוּהוּ בֵּית דִּין. מוֹכֵר עַצְמוֹ אֵינוֹ נִרְצָע וּמְכָרוּהוּ בֵּית דִּין נִרְצָע. מוֹכֵר עַצְמוֹ אָסוּר בְּשִׁפְחָה כְּנַעֲנִית וּמְכָרוּהוּ בֵּית דִּין רַבּוֹ מוֹסֵר לוֹ שִׁפְחָה כְּנַעֲנִית. מוֹכֵר עַצְמוֹ נִמְכָּר לְעַכּוּ\"ם וּמְכָרוּהוּ בֵּית דִּין אֵינוֹ נִמְכָּר אֶלָּא לְיִשְׂרָאֵל שֶׁנֶּאֱמַר (דברים טו יב) \"כִּי יִמָּכֵר לְךָ אָחִיךָ\" אֵין בֵּית דִּין מוֹכְרִין אוֹתוֹ אֶלָּא לְךָ. מוֹכֵר עַצְמוֹ נִמְכָּר לְשֵׁשׁ וְיֶתֶר עַל שֵׁשׁ מְכָרוּהוּ בֵּית דִּין אֵינוֹ נִמְכָּר אֶלָּא לְשֵׁשׁ. מוֹכֵר עַצְמוֹ אֵין מַעֲנִיקִין לוֹ מְכָרוּהוּ בֵּית דִּין מַעֲנִיקִין לוֹ:","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵין הָאִשָּׁה נִרְצַעַת וְכֵן יֵרָאֶה מֵעִנְיַן הַכָּתוּב שֶׁהֲרֵי אוֹמֵר בְּנִרְצָע (שמות כא ה) \"אָהַבְתִּי אֶת אֲדֹנִי אֶת אִשְׁתִּי וְאֶת בָּנָי\". וּמַהוּ שֶׁנֶּאֱמַר (דברים טו יז) \"וְאַף לַאֲמָתְךָ תַּעֲשֶׂה כֵּן\". לְהַעֲנִיק. שֶׁכְּשֵׁם שֶׁמִּצְוַת עֲשֵׂה לְהַעֲנִיק עֶבֶד עִבְרִי כָּךְ מַעֲנִיק אָמָה הָעִבְרִיָּה:","כָּל הַמְשַׁלֵּחַ עַבְדּוֹ וַאֲמָתוֹ רֵיקָם עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים טו יג) \"לֹא תְשַׁלְּחֶנּוּ רֵיקָם\" וַהֲרֵי הַכָּתוּב נִתְּקוֹ לַעֲשֵׂה שֶׁנֶּאֱמַר (דברים טו יד) \"הַעֲנֵיק תַּעֲנִיק לוֹ\". אֶחָד הַיּוֹצֵא בְּסוֹף שֵׁשׁ אוֹ שֶׁיָּצָא בְּיוֹבֵל אוֹ בְּמִיתַת הָאָדוֹן וְכֵן הָאָמָה הָעִבְרִיָּה שֶׁיָּצָאת בְּאֶחָד מִכָּל אֵלּוּ אוֹ בְּסִימָנִין הֲרֵי אֵלּוּ מַעֲנִיקִין לָהֶם. אֲבָל הַיּוֹצֵא בְּגִרְעוֹן כֶּסֶף אֵין מַעֲנִיקִין לָהֶם שֶׁנֶּאֱמַר (דברים טו יג) \"וְכִי תְשַׁלְּחֶנּוּ חָפְשִׁי מֵעִמָּךְ\" וְזֶה לֹא שִׁלְּחוֹ חָפְשִׁי אֶלָּא הָעֶבֶד נָתַן שְׁאָר הַדָּמִים שֶׁנִּשְׁאַר לוֹ לַעֲבֹד בָּהֶן וְאַחַר כָּךְ יָצָא. (דברים טו יד) \"הַעֲנֵיק תַּעֲנִיק לוֹ מִצֹּאנְךָ מִגָּרְנְךָ וּמִיִּקְבֶךָ\" בְּעִנְיַן צֹאן גֹּרֶן וְיֶקֶב דְּבָרִים שֶׁיֵּשׁ בָּהֶם בְּרָכָה מֵחֲמַת עַצְמָן הוּא שֶׁחַיָּב לְהַעֲנִיק לוֹ מֵהֶם אֲבָל הַכְּסָפִים וְהַבְּגָדִים אֵינוֹ חַיָּב לִתֵּן לוֹ מֵהֶם. וְכַמָּה נוֹתֵן לוֹ אֵין פָּחוֹת מִשְּׁוֵה שְׁלֹשִׁים סֶלַע בֵּין מִמִּין אֶחָד בֵּין מִמִּינִין הַרְבֵּה כִּשְׁלֹשִׁים שֶׁל קְנַס הָעֶבֶד שֶׁנֶּאֱמַר בּוֹ (שמות כא לב) \"יִתֵּן לַאדֹנָיו\". בֵּין שֶׁנִּתְבָּרֵךְ הַבַּיִת בִּגְלָלוֹ בֵּין שֶׁלֹּא נִתְבָּרֵךְ שֶׁנֶּאֱמַר הַעֲנֵיק תַּעֲנִיק לוֹ מִכָּל מָקוֹם. אִם כֵּן לָמָּה נֶאֱמַר (דברים טו יד) \"אֲשֶׁר בֵּרַכְךָ\" הַכּל לְפִי הַבְּרָכָה תֵּן לוֹ:","אִם בָּרַח וּפָגַע בּוֹ יוֹבֵל כְּשֶׁהוּא בּוֹרֵחַ וְיָצָא לְחֵרוּת אֵינוֹ חַיָּב לְהַעֲנִיקוֹ שֶׁנֶּאֱמַר (דברים טו יג) \"וְכִי תְשַׁלְּחֶנּוּ\" וְגוֹ'. עֶנֶק עֶבֶד עִבְרִי לְעַצְמוֹ וְאֵין בַּעַל חוֹב גּוֹבֶה הֵימֶנּוּ. וְעֶנֶק אָמָה הָעִבְרִיָּה וְכֵן מְצִיאָתָהּ לְאָבִיהָ. וְאִם מֵת אָבִיהָ קֹדֶם שֶׁיָּבוֹא לְיָדוֹ הֲרֵי הֵן שֶׁל עַצְמָהּ וְאֵין לְאַחֶיהָ בָּהֶם כְּלוּם שֶׁאֵין אָדָם מוֹרִישׁ זְכוּת שֶׁיֵּשׁ לוֹ בְּבִתּוֹ לִבְנוֹ:"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 10":["נִמְצֵאתָ לָמֵד שֶׁעֶשְׂרים דְּבָרִים הֵן שֶׁבְּכָל אֶחָד מֵהֶן פּוֹסֵל סֵפֶר תּוֹרָה. וְאִם נַעֲשָׂה בּוֹ אֶחָד מֵהֶן הֲרֵי הוּא כְּחֻמָּשׁ מִן הַחֻמָּשִׁין שֶׁמְּלַמְּדִין בָּהֶן הַתִּינוֹקוֹת וְאֵין בּוֹ קְדֻשַּׁת סֵפֶר תּוֹרָה וְאֵין קוֹרִין בּוֹ בָּרַבִּים. וְאֵלּוּ הֵן. א. אִם נִכְתַּב עַל עוֹר בְּהֵמָה טְמֵאָה. ב. שֶׁנִּכְתַּב עַל עוֹר בְּהֵמָה טְהוֹרָה שֶׁאֵינוֹ מְעֻבָּד. ג. שֶׁהָיָה מְעֻבָּד שֶׁלֹּא לְשֵׁם סֵפֶר תּוֹרָה. ד. שֶׁנִּכְתַּב שֶׁלֹּא בִּמְקוֹם כְּתִיבָה עַל הַגְּוִיל בִּמְקוֹם בָּשָׂר וְעַל הַקְּלָף בִּמְקוֹם שֵׂעָר. ה. שֶׁנִּכְתַּב מִקְצָתוֹ עַל הַגְּוִיל וּמִקְצָתוֹ עַל הַקְּלָף. ו. שֶׁנִּכְתַּב עַל דּוּכְסוּסְטוּס. ז. שֶׁנִּכְתַּב בְּלֹא שִׂרְטוּט. ח. שֶׁנִּכְתַּב בְּלֹא שָׁחוֹר הָעוֹמֵד. ט. שֶׁנִּכְתַּב בִּשְׁאָר לְשׁוֹנוֹת. י. שֶׁכְּתָבוֹ אֶפִּיקוֹרוֹס אוֹ כַּיּוֹצֵא בּוֹ מִשְּׁאָר פְּסוּלִין. יא. שֶׁכָּתַב הָאַזְכָּרוֹת בְּלֹא כַּוָּנָה. יב. שֶׁחִסֵּר אֲפִלּוּ אוֹת אַחַת. יג. שֶׁהוֹסִיף אֲפִלּוּ אוֹת אַחַת. יד. שֶׁנָּגְעָה אוֹת בְּאוֹת. טו. שֶׁנִּפְסְדָה צוּרַת אוֹת אַחַת עַד שֶׁלֹּא תִּקָּרֵא כָּל עִקָּר אוֹ תִּדְמֶה לְאוֹת אַחֶרֶת. בֵּין בְּעִקַּר הַכְּתִיבָה בֵּין בְּנֶקֶב בֵּין בְּקֶרַע בֵּין בְּטִשְׁטוּשׁ. טז. שֶׁהִרְחִיק אוֹ שֶׁהִקְרִיב בֵּין אוֹת לְאוֹת עַד שֶׁתֵּרָאֶה הַתֵּבָה כִּשְׁתֵּי תֵּבוֹת אוֹ שְׁתֵּי תֵּבוֹת כְּתֵבָה אַחַת. יז. שֶׁשִּׁנָּה צוּרַת הַפָּרָשִׁיּוֹת. יח. שֶׁשִּׁנָּה צוּרַת הַשִּׁירוֹת. יט. שֶׁכָּתַב בִּשְׁאָר הַכְּתָב כְּשִׁירָה. כ. שֶׁתָּפַר הַיְרִיעוֹת בְּלֹא גִּידֵי טְהוֹרָה. וּשְׁאָר הַדְּבָרִים לְמִצְוָה לֹא לְעַכֵּב:","סֵפֶר תּוֹרָה כָּשֵׁר נוֹהֲגִין בּוֹ קְדֻשָּׁה יְתֵרָה וְכָבוֹד גָּדוֹל. וְאָסוּר לָאָדָם לִמְכֹּר סֵפֶר תּוֹרָה אֲפִלּוּ אֵין לוֹ מַה יֹּאכַל. וַאֲפִלּוּ הָיוּ לוֹ סְפָרִים רַבִּים. וַאֲפִלּוּ יָשָׁן לִקַּח בּוֹ חָדָשׁ. לְעוֹלָם אֵין מוֹכְרִין סֵפֶר תּוֹרָה אֶלָּא לִשְׁנֵי דְּבָרִים. שֶׁיִּלְמֹד תּוֹרָה בְּדָמָיו אוֹ שֶׁיִּשָּׂא אִשָּׁה בְּדָמָיו. וְהוּא שֶׁלֹּא יִהְיֶה לוֹ דָּבָר אַחֵר לִמְכֹּר:","סֵפֶר תּוֹרָה שֶׁבָּלָה אוֹ שֶׁנִּפְסַל נוֹתְנִין אוֹתוֹ בִּכְלִי חֶרֶשׂ וְקוֹבְרִין אוֹתוֹ אֵצֶל תַּלְמִידֵי חֲכָמִים וְזוֹ הִיא גְּנִיזָתוֹ. מִטְפְּחוֹת סְפָרִים שֶׁבָּלוּ עוֹשִׂין אוֹתָן תַּכְרִיכִין לְמֵת מִצְוָה וְזוֹ הִיא גְּנִיזָתָן:","תִּיק שֶׁהוּכַן לְסֵפֶר תּוֹרָה וְהֻנַּח בּוֹ וְכֵן הַמִּטְפָּחוֹת וְהָאָרוֹן וְהַמִּגְדָּל שֶׁמַּנִּיחִין בּוֹ סֵפֶר תּוֹרָה אַף עַל פִּי שֶׁהַסֵּפֶר בְּתוֹךְ הַתִּיק וְכֵן הַכִּסֵּא שֶׁהוּכַן לְהַנִּיחַ עָלָיו סֵפֶר תּוֹרָה וְהֻנַּח עָלָיו סֵפֶר תּוֹרָה הַכּל תַּשְׁמִישֵׁי קְדֻשָּׁה הֵן וְאָסוּר לְזָרְקָן אֶלָּא כְּשֶׁיִּבְלוּ אוֹ כְּשֶׁיִּשָּׁבְרוּ נִגְנָזִין. אֲבָל הַבִּימוֹת שֶׁעוֹמֵד עֲלֵיהֶן שְׁלִיחַ צִבּוּר וְאוֹחֵז הַסֵּפֶר וְהַלּוּחוֹת שֶׁכּוֹתְבִין בָּהֶן לְתִינוֹק לְהִתְלַמֵּד אֵין בָּהֶן קְדֻשָּׁה. וְכֵן רִמּוֹנֵי כֶּסֶף וְזָהָב וְכַיּוֹצֵא בָּהֶן שֶׁעוֹשִׂין לְסֵפֶר תּוֹרָה לְנוֹי תַּשְׁמִישֵׁי קְדֻשָּׁה הֵן וְאָסוּר לְהוֹצִיאָן לְחל אֶלָּא אִם כֵּן מָכַר אוֹתָן לִקְנוֹת בִּדְמֵיהֶן סֵפֶר תּוֹרָה אוֹ חֻמָּשׁ:","וּמֻתָּר לְהַנִּיחַ סֵפֶר תּוֹרָה עַל גַּבֵּי סֵפֶר תּוֹרָה וְאֵין צָרִיךְ לוֹמַר עַל גַּבֵּי חֻמָּשׁים. וּמְנִיחִין הַחֻמָּשִׁין עַל גַּבֵּי נְבִיאִים וּכְתוּבִים. אֲבָל אֵין מַנִּיחִין נְבִיאִים וּכְתוּבִים עַל גַּבֵּי חֻמָּשִׁים וְלֹא חֻמָּשִׁים עַל גַּבֵּי סֵפֶר תּוֹרָה. וְכָל כִּתְבֵי הַקֹּדֶשׁ אֲפִלּוּ הֲלָכוֹת וְאַגָּדוֹת אָסוּר לְזָרְקָן. הַקְּמֵעִין שֶׁיֵּשׁ בָּהֶם עִנְיָנִים שֶׁל כִּתְבֵי הַקֹּדֶשׁ אֵין נִכְנָסִין בָּהֶן לְבֵית הַכִּסֵּא אֶלָּא אִם כֵּן הָיוּ מְחֻפּוֹת עוֹר:","לֹא יֹאחַז אָדָם סֵפֶר תּוֹרָה בִּזְרוֹעוֹ וְיִכָּנֵס בּוֹ לְבֵית הַמֶּרְחָץ אוֹ לְבֵית הַכִּסֵּא אוֹ לְבֵית הַקְּבָרוֹת אַף עַל פִּי שֶׁהוּא כָּרוּךְ בְּמִטְפָּחוֹת וְנָתוּן בְּתוֹךְ הַתִּיק שֶׁלּוֹ. וְלֹא יִקְרָא בּוֹ עַד שֶׁיַּרְחִיק אַרְבַּע אַמּוֹת מִן הַמֵּת (אוֹ מִבֵּית הַמֶּרְחָץ) אוֹ מִבֵּית הַכִּסֵּא. וְלֹא יֹאחַז אֶת סֵפֶר תּוֹרָה כְּשֶׁהוּא עָרֹם. וְאָסוּר לֵישֵׁב עַל מִטָּה שֶׁסֵּפֶר תּוֹרָה עָלֶיהָ:","בַּיִת שֶׁיֵּשׁ בּוֹ סֵפֶר תּוֹרָה אָסוּר לְשַׁמֵּשׁ מִטָּתוֹ בּוֹ עַד שֶׁיּוֹצִיאֶנּוּ אוֹ עַד שֶׁיַּנִּיחֶנּוּ בִּכְלִי וְיִתֵּן הַכְּלִי בִּכְלִי אַחֵר שֶׁאֵינוֹ מְזֻמָּן לוֹ. אֲבָל אִם הָיָה מְזֻמָּן לוֹ אֲפִלּוּ עֲשָׂרָה כֵּלִים זֶה בְּתוֹךְ זֶה כִּכְלִי אֶחָד הֵם. אוֹ עַד שֶׁיַּעֲשֶׂה לוֹ מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים אִם לֹא הָיָה לוֹ בַּיִת אַחֵר. אֲבָל אִם יֵשׁ לוֹ בַּיִת אַחֵר אָסוּר לְשַׁמֵּשׁ עַד שֶׁיּוֹצִיאֶנּוּ:","כָּל הַטְּמֵאִין וַאֲפִלּוּ נִדּוֹת וַאֲפִלּוּ כּוּתִי מֻתָּר לֶאֱחֹז סֵפֶר תּוֹרָה וְלִקְרוֹת בּוֹ. שֶׁאֵין דִּבְרֵי תּוֹרָה מְקַבְּלִין טֻמְאָה. וְהוּא שֶׁלֹּא יִהְיוּ יָדָיו מְטֻנָּפוֹת אוֹ מְלֻכְלָכוֹת בְּטִיט אֶלָּא יִרְחֲצוּ יְדֵיהֶם וְאַחַר כָּךְ יִגְּעוּ בּוֹ:","כָּל הָרוֹאֶה סֵפֶר תּוֹרָה כְּשֶׁהוּא מְהַלֵּךְ חַיָּב לַעֲמֹד מִפָּנָיו. וְיִהְיוּ הַכּל עוֹמְדִים עַד שֶׁיַּעֲמֹד זֶה שֶׁהוּא מְהַלֵּךְ בּוֹ כְּשֶׁיַּגִּיעֶנּוּ לִמְקוֹמוֹ אוֹ עַד שֶׁיִּתְכַּסֶּה מֵעֵינֵיהֶם וְאַחַר כָּךְ יִהְיוּ מֻתָּרִין לֵישֵׁב:","מִצְוָה לְיַחֵד לְסֵפֶר תּוֹרָה מָקוֹם וּלְכַבְּדוֹ וּלְהַדְּרוֹ יוֹתֵר מִדַּאי. דְּבָרִים שֶׁבְּלוּחוֹת הַבְּרִית הֵן הֵן שֶׁבְּכָל סֵפֶר וְסֵפֶר. לֹא יָרֹק אָדָם כְּנֶגֶד סֵפֶר תּוֹרָה וְלֹא יְגַלֶּה עֶרְוָתוֹ כְּנֶגְדּוֹ וְלֹא יַפְשִׁיט רַגְלָיו כְּנֶגְדּוֹ וְלֹא יַנִּיחֶנּוּ עַל רֹאשׁוֹ כְּמַשּׂאוֹי וְלֹא יַחֲזִיר אֲחוֹרָיו לְסֵפֶר תּוֹרָה אֶלָּא אִם כֵּן הָיָה גָּבוֹהַּ מִמֶּנּוּ עֲשָׂרָה טְפָחִים:","הָיָה מְהַלֵּךְ מִמָּקוֹם לְמָקוֹם וְסֵפֶר תּוֹרָה עִמּוֹ לֹא יַנִּיחַ סֵפֶר תּוֹרָה בְּתוֹךְ הַשַּׂק וְיַנִּיחֶנּוּ עַל גַּבֵּי הַחֲמוֹר וְיִרְכַּב עָלָיו. וְאִם הָיָה מִתְפַּחֵד מִן הַגַּנָּבִים מֻתָּר. וְאִם אֵין שָׁם פַּחַד מַנִּיחוֹ בְּחֵיקוֹ כְּנֶגֶד לִבּוֹ וְהוּא רוֹכֵב עַל הַבְּהֵמָה וְהוֹלֵךְ. כָּל מִי שֶׁיּוֹשֵׁב לִפְנֵי סֵפֶר תּוֹרָה יֵשֵׁב בְּכֹבֶד רֹאשׁ בְּאֵימָה וָפַחַד. שֶׁהוּא הָעֵד הַנֶּאֱמָן לְכָל בָּאֵי עוֹלָם שֶׁנֶּאֱמַר (דברים לא כו) ״וְהָיָה שָׁם בְּךָ לְעֵד״. וִיכַבְּדֵהוּ כְּפִי כֹּחוֹ. אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים כָּל הַמְחַלֵּל אֶת הַתּוֹרָה גּוּפוֹ מְחֻלָּל עַל הַבְּרִיּוֹת וְכָל הַמְכַבֵּד אֶת הַתּוֹרָה גּוּפוֹ מְכֻבָּד עַל הַבְּרִיּוֹת:נִגְמְרוּ הִלְכוֹת סֵפֶר תּוֹרָה בְּרַחֲמֵי שְׁמַיָּא"],"Mishneh Torah, Testimony 12":["כָּל הַנִּפְסָל בַּעֲבֵרָה אִם הֵעִידוּ עָלָיו שְׁנֵי עֵדִים שֶׁעָשָׂה עֲבֵרָה פְּלוֹנִית אַף עַל פִּי שֶׁלֹּא הִתְרוּ בּוֹ שֶׁהֲרֵי אֵינוֹ לוֹקֶה הֲרֵי זֶה פָּסוּל לְעֵדוּת. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁעָבַר עַל דְּבָרִים שֶׁפָּשַׁט בְּיִשְׂרָאֵל שֶׁהֵן עֲבֵרָה. כְּגוֹן שֶׁנִּשְׁבַּע לַשֶּׁקֶר אוֹ לַשָּׁוְא אוֹ גָּזַל אוֹ גָּנַב אוֹ אָכַל נְבֵלָה וְכַיּוֹצֵא בּוֹ. אֲבָל אִם רָאוּהוּ עֵדִים עוֹבֵר עַל דָּבָר שֶׁקָּרוֹב הָעוֹשֶׂה לִהְיוֹת שׁוֹגֵג צְרִיכִין לְהַזְהִירוֹ וְאַחַר כָּךְ יִפָּסֵל. כֵּיצַד. רָאוּהוּ קוֹשֵׁר אוֹ מַתִּיר בְּשַׁבָּת צְרִיכִין לְהוֹדִיעוֹ שֶׁזֶּה חִלּוּל שַׁבָּת מִפְּנֵי שֶׁרֹב הָעָם אֵינָן יוֹדְעִין זֶה. וְכֵן אִם רָאוּהוּ עוֹשֶׂה מְלָאכָה בְּשַׁבָּת אוֹ בַּיּוֹם טוֹב צְרִיכִין לְהוֹדִיעוֹ שֶׁהַיּוֹם שַׁבָּת שֶׁמָּא שׁוֹכֵחַ הוּא. וְכֵן הַמְשַׂחֵק בְּקֻבִּיָּא תָּמִיד אוֹ מִי שֶׁנַּעֲשָׂה מוֹכֵס אוֹ גַּבַּאי שֶׁמּוֹסִיף לְעַצְמוֹ צְרִיכִין הָעֵדִים לְהוֹדִיעוֹ שֶׁהָעוֹשֶׂה דָּבָר זֶה פָּסוּל לְעֵדוּת. שֶׁרֹב הָעָם אֵינָן יוֹדְעִים דְּבָרִים אֵלּוּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. כְּלָלוֹ שֶׁל דָּבָר כָּל עֲבֵרָה שֶׁהַדְּבָרִים מַרְאִים לָעֵדִים שֶׁזֶּה יָדַע שֶׁהוּא רָשָׁע וְעָבַר בְּזָדוֹן אַף עַל פִּי שֶׁלֹּא הִתְרוּ בּוֹ הֲרֵי זֶה פָּסוּל לְעֵדוּת וְאֵינוֹ לוֹקֶה:","אֵין אָדָם נִפְסָל בַּעֲבֵרָה עַל פִּי עַצְמוֹ. כֵּיצַד. הֲרֵי שֶׁבָּא לְבֵית דִּין וְאָמַר שֶׁגָּנַב אוֹ גָּזַל אוֹ הִלְוָה בְּרִבִּית. אַף עַל פִּי שֶׁמְּשַׁלֵּם עַל פִּי עַצְמוֹ אֵינוֹ נִפְסָל. וְכֵן אִם אָמַר שֶׁאָכַל נְבֵלָה אוֹ בָּעַל אֲסוּרָה אֵינוֹ נִפְסָל עַד שֶׁיִּהְיוּ שָׁם שְׁנֵי עֵדִים שֶׁאֵין אָדָם מֵשִׂים אֶת עַצְמוֹ רָשָׁע. לְפִיכָךְ רְאוּבֵן שֶׁהֵעִיד עָלָיו שִׁמְעוֹן שֶׁהִלְוָה בְּרִבִּית וְהֵעִיד לֵוִי וְאָמַר לִי הִלְוָה בְּרִבִּית. הֲרֵי רְאוּבֵן נִפְסָל בְּעֵדוּת שִׁמְעוֹן וְלֵוִי אַף עַל פִּי שֶׁהֲרֵי הוֹדָה לֵוִי שֶׁלָּוָה בְּרִבִּית אֵינוֹ מֵשִׂים עַצְמוֹ רָשָׁע וְנֶאֱמָן עַל רְאוּבֵן וְאֵינוֹ נֶאֱמָן עַל עַצְמוֹ. וְכֵן מִי שֶׁהֵעִיד שֶׁפְּלוֹנִי רְבָעוֹ בֵּין בְּאָנְסוֹ שֶׁל נִרְבָּע בֵּין בִּרְצוֹנוֹ הוּא וְאַחֵר מִצְטָרְפִין לְהָרְגוֹ. פְּלוֹנִי בָּא עַל אִשְׁתִּי הוּא וְאַחֵר מִצְטָרְפִין לְהָרְגוֹ אֲבָל לֹא לְהָרְגָהּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. פְּלוֹנִי רָבַע אֶת שׁוֹרִי הוּא וְאַחֵר מִצְטָרְפִין לְהָרְגוֹ שֶׁאֵין אָדָם קָרוֹב אֵצֶל מָמוֹנוֹ:","שְׁנַיִם שֶׁהֵעִידוּ עַל אֶחָד שֶׁהוּא פָּסוּל בַּעֲבֵרָה מֵאֵלּוּ הָעֲבֵרוֹת וּבָאוּ שְׁנַיִם וְהֵעִידוּ שֶׁעָשָׂה תְּשׁוּבָה וְחָזַר בּוֹ אוֹ שֶׁלָּקָה הֲרֵי זֶה כָּשֵׁר. אֲבָל אִם בָּאוּ שְׁנַיִם וְהִכְחִישׁוּם וְאָמְרוּ לֹא עָשָׂה עֲבֵרָה זוֹ וְלֹא נִפְסַל הֲרֵי זֶה סָפֵק פָּסוּל. לְפִיכָךְ לֹא יָעִיד וְאֵין מוֹצִיאִין מָמוֹן בְּעֵדוּתוֹ וְלֹא יָדוּן עַד שֶׁיִּוָּדַע שֶׁעָשָׂה תְּשׁוּבָה:","כָּל מִי שֶׁנִּתְחַיֵּב מַלְקוֹת בֵּין שֶׁעָשָׂה תְּשׁוּבָה בֵּין שֶׁלָּקָה בְּבֵית דִּין חוֹזֵר לְכַשְׁרוּתוֹ. אֲבָל שְׁאָר פְּסוּלֵי עֵדוּת שֶׁהֵן פְּסוּלִין מִשּׁוּם מָמוֹן שֶׁחָמְסוּ אוֹ שֶׁגָּזְלוּ אַף עַל פִּי שֶׁשִּׁלְּמוּ צְרִיכִין תְּשׁוּבָה וַהֲרֵי הֵן פְּסוּלִין עַד שֶׁיִּוָּדַע שֶׁחָזְרוּ בָּהֶן מִדַּרְכָּן הָרַע:","מֵאֵימָתַי חֲזָרַת מַלְוִים בְּרִבִּית מִשֶּׁיִּקְרְעוּ שִׁטְרוֹתֵיהֶן מֵעַצְמָן. וְיַחְזְרוּ בָּהֶן חֲזָרָה גְּמוּרָה שֶׁלֹּא יַלְווּ בְּרִבִּית אֲפִלּוּ לְעַכּוּ\"ם:","מֵאֵימָתַי חֲזָרַת הַמְשַׂחֲקִין בְּקֻבִּיָּא מִשֶּׁיִּשְׁבְּרוּ אֶת פַּסִיפְסֵיהֶם. וְיַחְזְרוּ בָּהֶן חֲזָרָה גְּמוּרָה שֶׁלֹּא יַעֲשׂוּ אֲפִלּוּ בְּחִנָּם:","מֵאֵימָתַי חֲזָרַת מַפְרִיחֵי יוֹנִים מִשֶּׁיִּשְׁבְּרוּ אֶת הַכֵּלִים שֶׁצָּדִין בָּהֶן. וְיַחְזְרוּ בָּהֶן חֲזָרָה גְּמוּרָה שֶׁאֲפִלּוּ בַּמִּדְבָּר לֹא יַעֲשׂוּ:","מֵאֵימָתַי חֲזָרַת סוֹחֲרֵי שְׁבִיעִית מִשֶּׁתַּגִּיעַ שְׁבִיעִית וְיִבָּדְקוּ. וְלֹא חֲזָרַת דְּבָרִים בִּלְבַד אֶלָּא כּוֹתֵב אֲנִי פְּלוֹנִי בֶּן פְּלוֹנִי כָּנַסְתִּי מָאתַיִם זוּז מִפֵּרוֹת שְׁבִיעִית וַהֲרֵי הֵם נְתוּנִים בְּמַתָּנָה לָעֲנִיִּים:","מֵאֵימָתַי חֲזָרַת הַמּוֹעֵל בִּשְׁבוּעָה מִשֶּׁיָּבוֹא לְבֵית דִּין שֶׁאֵין מַכִּירִין אוֹתוֹ וְיֹאמַר לָהֶם חָשׁוּד אֲנִי אוֹ יִתְחַיֵּב שְׁבוּעָה בְּבֵית דִּין שֶׁאֵין מַכִּירִין אוֹתוֹ בְּמָמוֹן חָשׁוּב יְשַׁלֵּם וְלֹא יִרְצֶה לְהִשָּׁבַע. וְכֵן טַבָּח שֶׁהָיָה בּוֹדֵק לְעַצְמוֹ וּמוֹכֵר וְיָצָאת טְרֵפָה מִתַּחַת יָדוֹ שֶׁהֲרֵי הוּא בִּכְלַל אוֹכְלֵי טְרֵפָה שֶׁהֵן פְּסוּלִין לְעֵדוּת. הֲרֵי זֶה פָּסוּל לְעֵדוּת עַד שֶׁיֵּרָאֶה מִמַּעֲשָׂיו שֶׁנִּחָם עַל רָעָתוֹ. וְיִלְבַּשׁ שְׁחוֹרִים וִיכַסֶּה שְׁחוֹרִים וְיֵלֵךְ לְמָקוֹם שֶׁאֵין מַכִּירִין אוֹתוֹ וְיַחְזִיר אֲבֵדָה בְּמָמוֹן חָשׁוּב. אוֹ יוֹצִיא טְרֵפָה מִתַּחַת יָדוֹ בְּדָבָר חָשׁוּב:","וְכֵן עֵד זוֹמֵם שֶׁהָלַךְ לְמָקוֹם שֶׁאֵין מַכִּירִין אוֹתוֹ וְנָתְנוּ לוֹ מָמוֹן חָשׁוּב לְהָעִיד בְּשֶׁקֶר וְלֹא רָצָה הֲרֵי זֶה עָשָׂה תְּשׁוּבָה וְחָזַר לְכַשְׁרוּתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Testimony 3":["אֶחָד דִּינֵי מָמוֹנוֹת וְאֶחָד דִּינֵי נְפָשׁוֹת בִּדְרִישָׁה וַחֲקִירָה. שֶׁנֶּאֱמַר (ויקרא כד כב) \"מִשְׁפַּט אֶחָד יִהְיֶה לָכֶם\". אֲבָל אָמְרוּ חֲכָמִים כְּדֵי שֶׁלֹּא תִּנְעל דֶּלֶת בִּפְנֵי לוִֹין אֵין עֵדֵי מָמוֹן צְרִיכִין דְּרִישָׁה וַחֲקִירָה. כֵּיצַד. אָמְרוּ הָעֵדִים בְּפָנֵינוּ הִלְוָה זֶה אֶת זֶה מָנֶה בְּשָׁנָה פְּלוֹנִית. אַף עַל פִּי שֶׁלֹּא כִּוְּנוּ אֶת הַחֹדֶשׁ וְלֹא אֶת הַמָּקוֹם שֶׁהִלְוָה בּוֹ וְלֹא אֶת הַמָּנֶה אִם הָיָה מִמַּטְבֵּעַ פְּלוֹנִי אוֹ מִמַּטְבֵּעַ פְּלוֹנִי עֵדוּתָן קַיֶּמֶת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּהוֹדָאוֹת וְהַלְוָאוֹת מַתָּנוֹת וּמְכִירוֹת וְכַיּוֹצֵא בָּהֶן. אֲבָל בְּדִינֵי קְנָסוֹת צְרִיכִין דְּרִישָׁה וַחֲקִירָה וְאֵין צָרִיךְ לוֹמַר בְּמַלְקוֹת וּבְגָלוּת. וְכֵן אִם רָאָה הַדַּיָּן שֶׁהַדִּין מְרֻמֶּה וְחָשַׁשׁ לוֹ צָרִיךְ דְּרִישָׁה וַחֲקִירָה:","אַף עַל פִּי שֶׁאֵין עֵדֵי מָמוֹנוֹת צְרִיכִין דְּרִישָׁה וַחֲקִירָה אִם הִכְחִישׁוּ הָעֵדִים זֶה אֶת זֶה בִּדְרִישׁוֹת אוֹ בַּחֲקִירוֹת עֵדוּתָן בְּטֵלָה. וְאִם הִכְחִישׁוּ הָעֵדִים זֶה אֶת זֶה בִּבְדִיקוֹת עֵדוּתָן קַיֶּמֶת. כֵּיצַד. אֶחָד אוֹמֵר בְּנִיסָן לָוָה מִמֶּנּוּ וְהַשֵּׁנִי אוֹמֵר לֹא כִּי אֶלָּא בְּאִיָּר אוֹ שֶׁאָמַר הָאֶחָד בִּירוּשָׁלַיִם וְהַשֵּׁנִי אוֹמֵר לֹא כִּי אֶלָּא בְּלוֹד הָיִינוּ עֵדוּתָן בְּטֵלָה. וְכֵן אִם אָמַר הָאֶחָד חָבִית שֶׁל יַיִן הִלְוָהוּ וְהַשֵּׁנִי אוֹמֵר שֶׁל שֶׁמֶן הָיְתָה עֵדוּתָן בְּטֵלָה שֶׁהֲרֵי הִכְחִישׁוֹ בִּדְרִישָׁה. אֲבָל אִם אָמַר הָאֶחָד מָנֶה שָׁחוֹר וְהַשֵּׁנִי אוֹמֵר מָנֶה לָבָן הָיָה. זֶה אוֹמֵר בַּדְּיוֹטָא הָעֶלְיוֹנָה הָיוּ כְּשֶׁהִלְוָהוּ וְהַשֵּׁנִי אוֹמֵר בַּדְּיוֹטָא הַתַּחְתּוֹנָה הָיוּ. עֵדוּתָן קַיֶּמֶת. אֲפִלּוּ אָמַר הָאֶחָד מָנֶה הִלְוָהוּ וְהַשֵּׁנִי אוֹמֵר מָאתַיִם חַיָּב לְשַׁלֵּם מָנֶה שֶׁיֵּשׁ בִּכְלַל מָאתַיִם מָנֶה. וְכֵן אִם אָמַר הָאֶחָד דְּמֵי חָבִית שֶׁל יַיִן יֵשׁ לוֹ בְּיָדוֹ וְזֶה אוֹמֵר דְּמֵי חָבִית שֶׁל שֶׁמֶן מְשַׁלֵּם בַּפָּחוּת שֶׁבְּדָמִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","דִּין תּוֹרָה שֶׁאֵין מְקַבְּלִין עֵדוּת לֹא בְּדִינֵי מָמוֹנוֹת וְלֹא בְּדִינֵי נְפָשׁוֹת אֶלָּא מִפִּי הָעֵדִים שֶׁנֶּאֱמַר (דברים יז ו) \"עַל פִּי שְׁנַיִם עֵדִים\" מִפִּיהֶם וְלֹא מִכְּתַב יָדָן. אֲבָל מִדִּבְרֵי סוֹפְרִים שֶׁחוֹתְכִין דִּינֵי מָמוֹנוֹת בְּעֵדוּת שֶּׁבַּשְּׁטָר אַף עַל פִּי שֶׁאֵין הָעֵדִים קַיָּמִים כְּדֵי שֶׁלֹּא תִּנְעל דֶּלֶת בִּפְנֵי לוִֹין. וְאֵין דָּנִין בְּעֵדוּת שֶׁבַּשְּׁטָר בְּדִינֵי קְנָסוֹת וְאֵין צָרִיךְ לוֹמַר בְּמַכּוֹת וּבְגָלוּת אֶלָּא מִפִּיהֶן וְלֹא מִכְּתַב יָדָן:","כָּל עֵד שֶׁנֶּחְקְרָה עֵדוּתוֹ בְּבֵית דִּין בֵּין בְּדִינֵי מָמוֹנוֹת בֵּין בְּדִינֵי נְפָשׁוֹת אֵין יָכוֹל לַחְזֹר בּוֹ. כֵּיצַד. אָמַר מֻטְעֶה הָיִיתִי שׁוֹגֵג הָיִיתִי וְנִזְכַּרְתִּי שֶׁאֵין הַדָּבָר כֵּן. לְפַחְדוֹ עָשִׂיתִי. אֵין שׁוֹמְעִין לוֹ אֲפִלּוּ נָתַן טַעַם לִדְבָרָיו. וְכֵן אֵינוֹ יָכוֹל לְהוֹסִיף בְּעֵדוּתוֹ תְּנַאי. כְּלָלוֹ שֶׁל דָּבָר כָּל דְּבָרִים שֶׁיֹּאמַר הָעֵד אַחַר שֶׁנֶּחְקְרָה עֵדוּתוֹ שֶׁיָּבוֹא מִכְּלָלָן בִּטּוּל הָעֵדוּת אוֹ הוֹסָפַת תְּנַאי בָּהּ אֵין שׁוֹמְעִין לוֹ:","עֵדִים הַחֲתוּמִים עַל הַשְּׁטָר הֲרֵי הֵן כְּמִי שֶׁנֶּחְקְרָה עֵדוּתָן בְּבֵית דִּין וְאֵין יְכוֹלִין לַחְזֹר בָּהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁאֶפְשָׁר לְקַיֵּם הַשְּׁטָר שֶׁלֹּא מִפִּיהֶן כְּגוֹן שֶׁהָיוּ שָׁם עֵדִים שֶׁזֶּה כְּתַב יָדָן אוֹ שֶׁהָיָה כְּתַב יָדָן יוֹצֵא מִמָּקוֹם אַחֵר. אֲבָל אִם אִי אֶפְשָׁר לְקַיֵּם אֶת הַשְּׁטָר אֶלָּא מִפִּיהֶן וְאָמְרוּ כְּתַב יָדֵינוּ הוּא זֶה אֲבָל אֲנוּסִים הָיִינוּ קְטַנִּים הָיִינוּ קְרוֹבִים הָיִינוּ מֻטְעִים הָיִינוּ הֲרֵי אֵלּוּ נֶאֱמָנִים וִיבַטֵּל הַשְּׁטָר:","אָמְרוּ פְּסוּלֵי עֵדוּת הָיִינוּ בַּעֲבֵרָה אוֹ שֹׁחַד לָקַחְנוּ עַל עֵדוּת זוֹ אֵין נֶאֱמָנִים שֶׁאֵין אָדָם מֵשִׂים עַצְמוֹ רָשָׁע עַד שֶׁיָּעִידוּ עָלָיו עֵדִים שֶׁהוּא רָשָׁע. וְכֵן אִם אָמְרוּ אֲמָנָה הָיוּ דְּבָרֵינוּ אֵין נֶאֱמָנִים שֶׁהַמֵּעִיד עַל שְׁטַר אֲמָנָה כְּמֵעִיד בְּשֶׁקֶר:","אָמְרוּ הָעֵדִים שְׁטַר מֶכֶר זֶה מוֹדָעָה נִמְסְרָה לָנוּ עָלָיו אַף עַל פִּי שֶׁכְּתַב יָדָן יוֹצֵא מִמָּקוֹם אַחֵר הֲרֵי אֵלּוּ נֶאֱמָנִין:","אָמְרוּ עַל תְּנַאי הָיָה שְׁטָר זֶה. אִם הָיָה כְּתַב יָדָן יוֹצֵא מִמָּקוֹם אַחֵר אֵין נֶאֱמָנִין וְאִם אֵין הַשְּׁטָר מִתְקַיֵּם אֶלָּא מִפִּיהֶם נֶאֱמָנִים. וְאוֹמֵר לְבַעֲלֵי הַדִּין קַיְּמוּ הַתְּנַאי וּבוֹאוּ לָדוּן:","אָמַר אֶחָד מִן הָעֵדִים עַל תְּנַאי הָיוּ הַדְּבָרִים וְהַשֵּׁנִי אוֹמֵר לֹא הָיָה שָׁם תְּנַאי הֲרֵי כָּאן עֵד אֶחָד:","גַּם בְּדִינֵי מָמוֹנוֹת אֵין מְקַבְּלִין עֵדוּת אֶלָּא בִּפְנֵי בַּעַל דִּין. אִם הָיָה בַּעַל דִּין חוֹלֶה אוֹ שֶׁהָיוּ הָעֵדִים מְבַקְּשִׁים לֵילֵךְ לִמְדִינַת הַיָּם וְשָׁלְחוּ לְבַעַל דִּין וְלֹא בָּא הֲרֵי אֵלּוּ מְקַבְּלִים עֵדִים שֶׁלֹּא בְּפָנָיו. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעֵדוּת עַל פֶּה. אֲבָל בִּשְׁטָר מְקַיְּמִין בֵּית דִּין אֶת עֵדָיו שֶׁלֹּא בִּפְנֵי בַּעַל דִּין. וַאֲפִלּוּ הָיָה עוֹמֵד וְצוֹוֵחַ וְאוֹמֵר שְׁטָר מְזֻיָּף הוּא עֵדֵי שֶׁקֶר הֵן פְּסוּלֵי עֵדוּת הֵן אֵין מַשְׁגִּיחִין בּוֹ אֶלָּא מְקַיְּמִין אֶת הַשְּׁטָר וְאִם יֵשׁ לוֹ רְאָיָה לִפְסל יִפְסל:","כָּל מִי שֶׁיֵּשׁ לוֹ רְאָיָה בְּעֵדִים מְטַפֵּל בָּעֵדִים עַד שֶׁיְּבִיאֵם לְבֵית דִּין. וְאִם יָדְעוּ בֵּית דִּין שֶׁבַּעַל דִּינוֹ אַלָּם וְטָעַן הַתּוֹבֵעַ שֶׁהָעֵדִים מִתְפַּחֲדִים מִבַּעַל דִּינוֹ שֶׁיָּבוֹאוּ וְיָעִידוּ לוֹ הֲרֵי בֵּית דִּין כּוֹפִין אֶת בַּעַל דִּינוֹ שֶׁיָּבִיא הוּא הָעֵדִים. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ דָּנִין בָּהֶן לְאַלָּם:"],"Mishneh Torah, The Chosen Temple 6":["הַמִּקְדָשׁ כֻּלּוֹ לֹא הָיָה בְּמִישׁוֹר אֶלָּא בְּמַעֲלֵה הָהָר. כְּשֶׁאָדָם נִכְנָס מִשַּׁעַר מִזְרָחִי שֶׁל הַר הַבַּיִת מְהַלֵּךְ עַד סוֹף הַחֵיל בְּשָׁוֶה. וְעוֹלֶה מִן הַחֵיל לְעֶזְרַת הַנָּשִׁים בִּשְׁתֵּים עֶשְׂרֵה מַעֲלוֹת רוּם כָּל מַעֲלָה חֲצִי אַמָּה וְשִׁלְחָהּ חֲצִי אַמָּה:","וּמְהַלֵּךְ כָּל עֶזְרַת הַנָּשִׁים בְּשָׁוֶה. וְעוֹלֶה מִמֶּנָּה לְעֶזְרַת יִשְׂרָאֵל שֶׁהוּא תְּחִלַּת הָעֲזָרָה בַּחֲמֵשׁ עֶשְׂרֵה מַעֲלוֹת. רוּם כָּל מַעֲלָה חֲצִי אַמָּה וְשִׁלְחָהּ חֲצִי אַמָּה:","וּמְהַלֵּךְ כָּל עֶזְרַת יִשְׂרָאֵל בְּשָׁוֶה וְעוֹלֶה מִמֶּנּוּ לְעֶזְרַת הַכֹּהֲנִים בְּמַעֲלָה גְּבוֹהָה אַמָּה וְעָלֶיהָ דּוּכָן יֵשׁ בּוֹ שָׁלֹשׁ מַעֲלוֹת. רוּם כָּל מַעְלָה חֲצִי אַמָּה וְשִׁלְחָהּ חֲצִי אַמָּה. נִמְצֵאת עֶזְרַת הַכֹּהֲנִים גְּבוֹהָה עַל שֶׁל יִשְׂרָאֵל שְׁתֵּי אַמּוֹת וּמֶחֱצָה:","וּמְהַלֵּךְ כָּל עֶזְרַת הַכֹּהֲנִים וְהַמִּזְבֵּחַ. וּבֵין הָאוּלָם וְלַמִּזְבֵּחַ בְּשָׁוֶה. וְעוֹלֶה מִשָּׁם לָאוּלָם בִּשְׁתֵּים עֶשְׂרֵה מַעֲלוֹת. רוּם כָּל מַעְלָה חֲצִי אַמָּה וְשִׁלְחָהּ חֲצִי אַמָּה וְהָאוּלָם וְהַהֵיכָל כֻּלּוֹ בְּשָׁוֶה:","נִמְצָא גֹּבַהּ קַרְקַע הַהֵיכָל עַל קַרְקַע שַׁעַר הַמִּזְרָח שֶׁל הַר הַבַּיִת שְׁתַּיִם וְעֶשְׂרִים אַמּוֹת. וְגֹבַהּ שַׁעַר הַר הַבַּיִת עֶשְׂרִים אַמָּה. לְפִיכָךְ הָעוֹמֵד כְּנֶגֶד שַׁעַר הַמִּזְרָח אֵינוֹ רוֹאֶה פֶּתַח הַהֵיכָל. וּמִפְּנֵי זֶה עָשׂוּ כֹּתֶל שֶׁעַל גַּבֵּי שַׁעַר זֶה נָמוּךְ. כְּדֵי שֶׁיְּהֵא כֹּהֵן הָעוֹמֵד בְּהַר הַמִּשְׁחָה רוֹאֶה פֶּתַח הַהֵיכָל בְּשָׁעָה שֶׁמַּזֶּה מִדַּם הַפָּרָה נֹכַח הַהֵיכָל:","וּלְשָׁכוֹת הָיוּ שָׁם תַּחַת עֶזְרַת יִשְׂרָאֵל פְּתוּחוֹת לְעֶזְרַת הַנָּשִׁים. שֶׁשָּׁם הַלְוִיִּם נוֹתְנִין הַכִּנּוֹרוֹת וְהַנְּבָלִים וְהַמְּצִלְתַּיִם וְכָל כְּלֵי הַשִּׁיר. וְעַל הַדּוּכָן הָעוֹלֶה מֵעֶזְרַת יִשְׂרָאֵל לְעֶזְרַת הַכֹּהֲנִים הָיוּ הַלְוִיִּם עוֹמְדִים בְּשָׁעָה שֶׁאוֹמְרִים שִׁירָה עַל הַקָּרְבָּן:","הַלְּשָׁכוֹת הַבְּנוּיוֹת בַּקֹּדֶשׁ וּפְתוּחוֹת לַחל אִם הָיוּ גַּגּוֹתֵיהֶן שָׁוִין עִם קַרְקַע הָעֲזָרָה תּוֹכָן חֹל וְגַגּוֹתֵיהֶן קֹדֶשׁ וְאִם אֵינָן שָׁוִין אַף גַּגּוֹתֵיהֶן חֹל שֶׁהַגַּגּוֹת וְהָעֲלִיּוֹת לֹא נִתְקַדְּשׁוּ. לְפִיכָךְ גַּגִּים אֵלּוּ אֵין אוֹכְלִין שָׁם קָדְשֵׁי קָדָשִׁים וְלֹא שׁוֹחֲטִין קָדָשִׁים קַלִּים:","הָיוּ בְּנוּיוֹת לַחל וּפְתוּחוֹת לַקֹּדֶשׁ תּוֹכָן קֹדֶשׁ לַאֲכִילַת קָדְשֵׁי קָדָשִׁים אֲבָל אֵין שׁוֹחֲטִין שָׁם קָדָשִׁים קַלִּים וְהַנִּכְנָס לְשָׁם בְּטֻמְאָה פָּטוּר. וְגַגּוֹתֵיהֶן חֹל לְכָל דָּבָר:","הַמְּחִלּוֹת הַפְּתוּחוֹת לָעֲזָרָה קֹדֶשׁ וְהַפְּתוּחוֹת לְהַר הַבַּיִת חֹל. הַחַלּוֹנוֹת וָעֳבִי הַחוֹמָה כְּלִפְנִים בֵּין לַאֲכִילַת קָדְשֵׁי קָדָשִׁים בֵּין לְטֻמְאָה:","בֵּית דִּין שֶׁרָצוּ לְהוֹסִיף עַל יְרוּשָׁלַיִם אוֹ לְהוֹסִיף עַל הָעֲזָרָה מוֹסִיפִין. וְיֵשׁ לָהֶם לִמְשֹׁךְ הָעֲזָרָה עַד הַמָּקוֹם שֶׁיִּרְצוּ מֵהַר הַבַּיִת וְלִמְשֹׁךְ חוֹמַת יְרוּשָׁלַיִם עַד מָקוֹם שֶׁיִּרְצוּ:","אֵין מוֹסִיפִין עַל הָעִיר אוֹ עַל הָעֲזָרוֹת אֶלָּא עַל פִּי הַמֶּלֶךְ וְעַל פִּי נָבִיא וּבְאוּרִים וְתֻמִּים וְעַל פִּי סַנְהֶדְרִין שֶׁל שִׁבְעִים וְאֶחָד זְקֵנִים שֶׁנֶּאֱמַר (שמות כה ט) \"כְּכל אֲשֶׁר אֲנִי מַרְאֶה אוֹתְךָ\" וְכֵן תַּעֲשׂוּ לְדוֹרוֹת. וּמשֶׁה רַבֵּנוּ מֶלֶךְ הָיָה:","וְכֵיצַד מוֹסִיפִין עַל הָעִיר. עוֹשִׂין בֵּית דִּין שְׁתֵּי תּוֹדוֹת וְלוֹקְחִין לֶחֶם חָמֵץ שֶׁבָּהֶם וְהוֹלְכִים בֵּית דִּין אַחַר שְׁתֵּי הַתּוֹדוֹת וּשְׁתֵּי הַתּוֹדוֹת זוֹ אַחַר זוֹ וְעוֹמְדִין בְּכִנּוֹרוֹת וּבִנְבָלִים וּבְצִלְצָל עַל כָּל פִּנָּה וּפִנָּה וְעַל כָּל אֶבֶן (וְאֶבֶן) שֶׁבִּירוּשָׁלַיִם וְאוֹמֵר (תהילים ל ב) \"אֲרוֹמִמְךָ ה' כִּי דִלִּיתָנִי\" וְגוֹ'. עַד שֶׁמַּגִּיעִין לְסוֹף הַמָּקוֹם שֶׁמְּקַדְּשִׁין אוֹתוֹ וְעוֹמְדִין שָׁם. וְאוֹכְלִים שָׁם לֶחֶם תּוֹדָה אַחַת מִשְּׁתֵי הַתּוֹדוֹת וְהַשְּׁנִיָּה נִשְׂרֶפֶת. וְעַל פִּי הַנָּבִיא שׂוֹרְפִין אֶת זוֹ וְאוֹכְלִין אֶת זוֹ:","וְכֵן אִם הוֹסִיפוּ עַל הָעֲזָרָה מְקַדְּשִׁין אוֹתָהּ בִּשְׁיָרֵי הַמִּנְחָה. מַה יְּרוּשָׁלַיִם הַתּוֹדָה שֶׁנֶּאֱכֶלֶת בָּהּ מְקַדַּשְׁתָּהּ אַף הָעֲזָרָה שְׁיָרֵי הַמְּנָחוֹת שֶׁאֵין נֶאֱכָלִין אֶלָּא בָּהּ הֵן שֶׁמְּקַדְּשִׁין אוֹתָהּ בָּהֶן. וְאוֹכְלִין אוֹתָן בְּסוֹף הַמָּקוֹם שֶׁקִּדְּשׁוּ:","כָּל מָקוֹם שֶׁלֹּא נַעֲשָׂה בְּכָל אֵלּוּ וְכַסֵּדֶר הַזֶּה אֵין קָדוֹשׁ גָּמוּר. וְזֶה שֶׁעָשָׂה עֶזְרָא שְׁתֵּי תּוֹדוֹת זִכָּרוֹן הוּא שֶׁעָשָׂה לֹא בְּמַעֲשָׂיו נִתְקַדֵּשׁ הַמָּקוֹם שֶׁלֹּא הָיָה שָׁם לֹא מֶלֶךְ וְלֹא אוּרִים וְתֻמִּים. וּבְמַה נִּתְקַדְּשָׁה בִּקְדֻשָּׁה רִאשׁוֹנָה שֶׁקִּדְּשָׁהּ שְׁלֹמֹה שֶׁהוּא קִדֵּשׁ הָעֲזָרָה וִירוּשָׁלַיִם לִשְׁעָתָן וְקִדְּשָׁן לֶעָתִיד לָבוֹא:","לְפִיכָךְ מַקְרִיבִין הַקָּרְבָּנוֹת כֻּלָּן אַף עַל פִּי שֶׁאֵין שָׁם בַּיִת בָּנוּי. וְאוֹכְלִין קָדְשֵׁי קָדָשִׁים בְּכָל הָעֲזָרָה אַף עַל פִּי שֶׁהִיא חֲרֵבָה וְאֵינָהּ מֻקֶּפֶת בִּמְחִצָּה וְאוֹכְלִין קָדָשִׁים קַלִּים וּמַעֲשֵׂר שֵׁנִי בְּכָל יְרוּשָׁלַיִם אַף עַל פִּי שֶׁאֵין שָׁם חוֹמוֹת שֶׁהַקְּדֻשָּׁה רִאשׁוֹנָה קָדְשָׁה לִשְׁעָתָהּ וְקָדְשָׁה לֶעָתִיד לָבוֹא:","וְלָמָּה אֲנִי אוֹמֵר בַּמִּקְדָּשׁ וִירוּשָׁלַיִם קְדֻשָּׁה רִאשׁוֹנָה קָדְשָׁה לֶעָתִיד לָבוֹא. וּבִקְדֻשַּׁת שְׁאָר אֶרֶץ יִשְׂרָאֵל לְעִנְיַן שְׁבִיעִית וּמַעַשְׂרוֹת וְכַיּוֹצֵא בָּהֶן לֹא קָדְשָׁה לֶעָתִיד לָבוֹא. לְפִי שֶׁקְּדֻשַּׁת הַמִּקְדָּשׁ וִירוּשָׁלַיִם מִפְּנֵי הַשְּׁכִינָה וּשְׁכִינָה אֵינָהּ בְּטֵלָה. וַהֲרֵי הוּא אוֹמֵר (ויקרא כו לא) \"וַהֲשִׁמּוֹתִי אֶת מִקְדְּשֵׁיכֶם\" וְאָמְרוּ חֲכָמִים אַף עַל פִּי שֶׁשּׁוֹמְמִין בִּקְדֻשָּׁתָן הֵן עוֹמְדִים אֲבָל חִיּוּב הָאָרֶץ בִּשְׁבִיעִית וּבְמַעַשְׂרוֹת אֵינוֹ אֶלָּא מִפְּנֵי שֶׁהוּא כִּבּוּשׁ רַבִּים וְכֵיוָן שֶׁנִּלְקְחָה הָאָרֶץ מִידֵיהֶם בָּטַל הַכִּבּוּשׁ וְנִפְטְרָה מִן הַתּוֹרָה מִמַּעַשְׂרוֹת וּמִשְּׁבִיעִית שֶׁהֲרֵי אֵינָהּ מִן אֶרֶץ יִשְׂרָאֵל. וְכֵיוָן שֶׁעָלָה עֶזְרָא וְקִדְּשָׁהּ לֹא קִדְּשָׁהּ בְּכִבּוּשׁ אֶלָּא בַּחֲזָקָה שֶׁהֶחְזִיקוּ בָּהּ וּלְפִיכָךְ כָּל מָקוֹם שֶׁהֶחְזִיקוּ בָּהּ עוֹלֵי בָּבֶל וְנִתְקַדֵּשׁ בִּקְדֻשַּׁת עֶזְרָא הַשְּׁנִיָּה הוּא מְקֻדָּשׁ הַיּוֹם וְאַף עַל פִּי שֶׁנִּלְקַח הָאָרֶץ מִמֶּנּוּ וְחַיָּב בִּשְׁבִיעִית וּבְמַעַשְׂרוֹת עַל הַדֶּרֶךְ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת תְּרוּמָה:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 13":["מִי שֶׁנִּגְמַר דִּינוֹ לְמִיתָה מוֹצִיאִין אוֹתוֹ מִבֵּית דִּין וְאֶחָד עוֹמֵד עַל פֶּתַח בֵּית דִּין וְהַסּוּדָרִין בְּיָדוֹ וְהַסּוּס רָחוֹק מִמֶּנּוּ. וְהַכָּרוֹז יוֹצֵא לְפָנָיו פְּלוֹנִי יוֹצֵא לֵהָרֵג בְּמִיתָה פְּלוֹנִית עַל שֶׁעָבַר עֲבֵרָה פְּלוֹנִית בְּמָקוֹם פְּלוֹנִי בִּזְמַן פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי עֵדָיו מִי שֶׁיּוֹדֵעַ לוֹ זְכוּת יָבוֹא וִילַמֵּד עָלָיו. אָמַר אֶחָד יֵשׁ לִי לְלַמֵּד עָלָיו זְכוּת זֶה מֵנִיף בַּסּוּדָרִין וְזֶה הָרוֹכֵב עַל הַסּוּס רָץ וּמַחֲזִיר אֶת הַנִּדּוֹן לְבֵית דִּין. אִם נִמְצָא לוֹ זְכוּת פּוֹטְרִין אוֹתוֹ וְאִם לֹא יַחְזֹר וְיֵצֵא לַהֲרִיגָה. אָמַר הוּא בְּעַצְמוֹ יֵשׁ לִי לְלַמֵּד עַל עַצְמִי זְכוּת אַף עַל פִּי שֶׁאֵין מַמָּשׁ בִּדְבָרָיו מַחֲזִירִין אוֹתוֹ פַּעַם רִאשׁוֹנָה וּשְׁנִיָּה. שֶׁמָּא מִפְּנֵי הַפַּחַד נִסְתַּתְּמוּ טַעֲנוֹתָיו וּכְשֶׁיַּחֲזֹר לְבֵית דִּין תִּתְיַשֵּׁב דַּעְתּוֹ וְיֹאמַר טַעַם. הֶחְזִירוּהוּ וְלֹא נִמְצָא מַמָּשׁ בִּדְבָרָיו מוֹצִיאִין אוֹתוֹ פַּעַם שְׁלִישִׁית. אָמַר בַּשְּׁלִישִׁית יֵשׁ לִי לְלַמֵּד עַל עַצְמִי זְכוּת אִם יֵשׁ מַמָּשׁ בִּדְבָרָיו מַחֲזִירִין אוֹתוֹ אֲפִלּוּ כַּמָּה פְּעָמִים. לְפִיכָךְ מוֹסְרִין לוֹ שְׁנֵי תַּלְמִידֵי חֲכָמִים שֶׁשּׁוֹמְעִין דְּבָרָיו בַּדֶּרֶךְ אִם יֵשׁ מַמָּשׁ בִּדְבָרָיו מַחֲזִירִין אוֹתוֹ וְאִם לָאו אֵין מַחֲזִירִין אוֹתוֹ. אִם לֹא נִמְצָא לוֹ זְכוּת מוֹצִיאִין אוֹתוֹ. וְעֵדָיו הֵם הַהוֹרְגִין אוֹתוֹ בְּכָל מִיתָה שֶׁיִּתְחַיֵּב בָּהּ. וְרוֹצֵחַ שֶׁלֹּא הֲרָגוּהוּ עֵדָיו חַיָּבִין לַהֲמִיתוֹ בְּיַד כָּל אָדָם. רָחוֹק מִמְּקוֹם הַהֲרִיגָה כְּעֶשֶׂר אַמּוֹת אוֹמֵר לוֹ הִתְוַדֶּה שֶׁכֵּן דֶּרֶךְ כָּל הַמּוּמָתִין מִתְוַדִּין וְכָל הַמִּתְוַדֶּה יֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. אִם אֵינוֹ יוֹדֵעַ לְהִתְוַדּוֹת אוֹמְרִים לוֹ אֱמֹר תְּהֵא מִיתָתִי כַּפָּרָה עַל כָּל עֲוֹנוֹתַי. אֲפִלּוּ יָדַע בְּעַצְמוֹ שֶׁשֶּׁקֶר הֵעִידוּ עָלָיו כָּךְ הוּא מִתְוַדֶּה:","וְאַחַר שֶׁמִּתְוַדֶּה מַשְׁקִין אוֹתוֹ קֹרֶט שֶׁל לְבוֹנָה בְּכוֹס שֶׁל יַיִן כְּדֵי שֶׁתִּטָּרֵף דַּעְתּוֹ עָלָיו וְיִשְׁתַּכֵּר. וְאַחַר כָּךְ יֵהָרֵג בַּמִּיתָה שֶׁהוּא חַיָּב בָּהּ:","זֶה הַיַּיִן וְהַלְּבוֹנָה וְהָאֶבֶן שֶׁיִּסָּקֵל בָּהּ הַנִּסְקָל. וְהַסַּיִף שֶׁיֵּהָרֵג בּוֹ הַנֶּהֱרָג. וְהַסּוּדָר שֶׁחוֹנְקִין בּוֹ הַנֶּחְנָק. וְהָעֵץ שֶׁתּוֹלִין עָלָיו הַנִּתְלֶה. וְהַסּוּדָרִין שֶׁמְּנִיפִין בָּהּ לִפְנֵי הֲרוּגֵי בֵּית דִּין. וְהַסּוּס שֶׁרָץ לְהַצִּילוֹ. הַכּל בָּאִין מִשֶּׁל צִבּוּר. וּמִי שֶׁיִּרְצֶה לְהִתְנַדֵּב יָבוֹא וְיִתְנַדֵּב:","אֵין בֵּית דִּין יוֹצְאִין אַחַר הַנֶּהֱרָג. וְכָל בֵּית דִּין שֶׁהָרְגוּ נֶפֶשׁ אֲסוּרִים לֶאֱכל כָּל אוֹתוֹ הַיּוֹם הֲרֵי זֶה בִּכְלַל לֹא תֹאכְלוּ עַל הַדָּם. וְאֵין מַבְרִין הַקְּרוֹבִים עַל הֲרוּגֵי בֵּית דִּין מִשּׁוּם לֹא תֹאכְלוּ עַל הַדָּם. וּדְבָרִים אֵלּוּ אֲסוּרִין וְאֵין בָּהֶן מַלְקוֹת:","מִי שֶׁנִּתְחַיֵּב מִיתָה בְּחֻלּוֹ שֶׁל מוֹעֵד מְעַיְּנִין בְּדִינוֹ וְאוֹכְלִין בֵּית דִּין וְשׁוֹתִין וְאַחַר כָּךְ גּוֹמְרִין אֶת דִּינוֹ סָמוּךְ לִשְׁקִיעַת הַחַמָּה וְהוֹרְגִין אוֹתוֹ:","הֲרוּגֵי בֵּית דִּין אֵין מִתְאַבְּלִין עֲלֵיהֶן. וּבָאִין קְרוֹבֵיהֶן וְשׁוֹאֲלִים אֶת שְׁלוֹם הָעֵדִים וְאֶת שְׁלוֹם הַדַּיָּנִים לְהוֹדִיעַ שֶׁאֵין בְּלִבָּם עֲלֵיהֶן כְּלוּם שֶׁדִּין אֱמֶת דָּנוּ. וְאַף עַל פִּי שֶׁאֵין נוֹהֲגִין אֲבֵלוּת הֲרֵי הֵן אוֹנְנִים עֲלֵיהֶם שֶׁאֵין אֲנִינוּת אֶלָּא בַּלֵּב:","מִי שֶׁנִּגְמַר דִּינוֹ וּבָרַח וּבָא לְבֵית דִּין אַחֵר אֵין סוֹתְרִין אֶת דִּינוֹ אֶלָּא כָּל מָקוֹם שֶׁיַּעַמְדוּ שְׁנַיִם וְיֹאמְרוּ מְעִידִין אָנוּ אֶת אִישׁ פְּלוֹנִי שֶׁנִּגְמַר דִּינוֹ בְּבֵית דִּין פְּלוֹנִי וּפְלוֹנִי וּפְלוֹנִי עֵדָיו הֲרֵי זֶה יֵהָרֵג. בַּמֶּה דְּבָרִים אֲמוּרִים בְּרוֹצֵחַ. אֲבָל שְׁאָר חַיָּבֵי מִיתוֹת עַד שֶׁיָּבוֹאוּ עֵדָיו הָרִאשׁוֹנִים וְיָעִידוּ שֶׁנִּגְמַר דִּינוֹ וְיַהַרְגוּהוּ בְּיָדָם. וְהוּא שֶׁיָּעִידוּ בְּבֵית דִּין שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה:","מִי שֶׁנִּגְמַר דִּינוֹ בְּבֵית דִּין שֶׁהָיָה בְּחוּצָה לָאָרֶץ וּבָרַח לְבֵית דִּין שֶׁבְּאֶרֶץ יִשְׂרָאֵל סוֹתְרִין אֶת דִּינוֹ עַל כָּל פָּנִים. וְאִם הָיוּ אוֹתָן בֵּית דִּין עַצְמָן שֶׁנִּגְמַר דִּינוֹ בִּפְנֵיהֶם אֵין סוֹתְרִין אֶת דִּינוֹ אַף עַל פִּי שֶׁגְּמָרוּהוּ בְּחוּצָה לָאָרֶץ וְהֵם עַתָּה בְּאֶרֶץ יִשְׂרָאֵל:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 24":["יֵשׁ לַדַּיָּן לָדוּן בְּדִינֵי מָמוֹנוֹת עַל פִּי הַדְּבָרִים שֶׁדַּעְתּוֹ נוֹטָה לָהֶן שֶׁהֵן אֱמֶת וְהַדָּבָר חָזָק בְּלִבּוֹ שֶׁהוּא כֵּן אַף עַל פִּי שֶׁאֵין שָׁם רְאָיָה בְּרוּרָה וְאֵין צָרִיךְ לוֹמַר אִם הָיָה יוֹדֵעַ בְּוַדַּאי שֶׁהַדָּבָר כֵּן הוּא שֶׁהוּא דָּן כְּפִי מַה שֶּׁיּוֹדֵעַ. כֵּיצַד. הֲרֵי שֶׁנִּתְחַיֵּב אָדָם שְׁבוּעָה בְּבֵית דִּין וְאָמַר לַדַּיָּן אָדָם שֶׁהוּא נֶאֱמָן אֶצְלוֹ וְשֶׁדַּעְתּוֹ סוֹמֶכֶת עַל דְּבָרָיו שֶׁזֶּה הָאִישׁ חָשׁוּד עַל הַשְּׁבוּעָה יֵשׁ לַדַּיָּן לַהֲפֹךְ הַשְּׁבוּעָה עַל שֶׁכְּנֶגְדוֹ וְיִשָּׁבַע וְיִטּל הוֹאִיל וְסָמְכָה דַּעְתּוֹ שֶׁל דַּיָּן עַל דִּבְרֵי זֶה. אֲפִלּוּ הָיְתָה אִשָּׁה אוֹ עֶבֶד נֶאֱמָנִים אֶצְלוֹ הוֹאִיל וּמָצָא הַדָּבָר חָזָק וְנָכוֹן בְּלִבּוֹ סוֹמֵךְ עָלָיו וְדָן. וְאֵין צָרִיךְ לוֹמַר אִם יָדַע הוּא עַצְמוֹ שֶׁזֶּה חָשׁוּד. וְכֵן אִם יָצָא שְׁטַר חוֹב לְפָנָיו וְאָמַר לוֹ אָדָם שֶׁסָּמַךְ עָלָיו אֲפִלּוּ אִשָּׁה אוֹ קָרוֹב זֶה פָּרוּעַ הוּא אִם סָמְכָה דַּעְתּוֹ עַל דְּבָרָיו יֵשׁ לוֹ לוֹמַר לָזֶה לֹא תִּפָּרַע אֶלָּא בִּשְׁבוּעָה. אוֹ אִם הָיָה עָלָיו שְׁטַר חוֹב לְאַחֵר יִתֵּן לְזֶה שֶׁלֹּא נִפְגַּם שְׁטָרוֹ כְּלָל וְיַנִּיחַ זֶה שֶׁנִּפְגַּם שְׁטָרוֹ בְּדִבְרֵי הָאֶחָד אוֹ יַשְׁלִיךְ הַשְּׁטָר בְּפָנָיו וְלֹא יָדוּן בּוֹ כְּפִי מַה שֶּׁיִּרְאֶה. וְכֵן מִי שֶׁבָּא וְטָעַן שֶׁיֵּשׁ לוֹ פִּקָּדוֹן אֵצֶל פְּלוֹנִי שֶׁמֵּת בְּלֹא צַוָּאָה וְנָתַן סִימָנִין מֻבְהָקִין וְלֹא הָיָה זֶה הַטּוֹעֵן רָגִיל לְהִכָּנֵס בְּבֵית זֶה הָאִישׁ שֶׁמֵּת. אִם יָדַע הַדַּיָּן שֶׁזֶּה הַמֵּת אֵינוֹ אָמוּד לִהְיוֹת לוֹ חֵפֶץ זֶה וְסָמְכָה דַּעְתּוֹ שֶׁאֵין זֶה הַחֵפֶץ שֶׁל מֵת מוֹצִיאוֹ מִן הַיּוֹרְשִׁין וְנוֹתְנוֹ לְזֶה הָאָמוּד בּוֹ וְנָתַן סִימָנִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה שֶׁאֵין הַדָּבָר מָסוּר אֶלָּא לְלִבּוֹ שֶׁל דַּיָּן לְפִי מַה שֶּׁיֵּרָאֶה לוֹ שֶׁהוּא דִּין הָאֱמֶת. אִם כֵּן לָמָּה הִצְרִיכָה תּוֹרָה שְׁנֵי עֵדִים שֶׁבִּזְמַן שֶׁיָּבוֹאוּ לִפְנֵי הַדַּיָּן שְׁנֵי עֵדִים יָדוּן עַל פִּי עֵדוּתָן אַף עַל פִּי שֶׁאֵינוֹ יוֹדֵעַ אִם בֶּאֱמֶת הֱעִידוּ אוֹ בְּשֶׁקֶר:","כָּל אֵלּוּ הַדְּבָרִים הֵן עִקַּר הַדִּין. אֲבָל מִשֶּׁרַבּוּ בָּתֵּי דִּינִין שֶׁאֵינָן הֲגוּנִים וַאֲפִלּוּ הָיוּ הֲגוּנִים בְּמַעֲשֵׂיהֶם אֵינָן חֲכָמִים כָּרָאוּי וּבַעֲלֵי בִּינָה הִסְכִּימוּ רֹב בָּתֵּי דִּינֵי יִשְׂרָאֵל שֶׁלֹּא יְהַפְּכוּ שְׁבוּעָה אֶלָּא בִּרְאָיָה בְּרוּרָה. וְלֹא יִפְגְּמוּ שְׁטָר וְיַפְסִידוּ חֶזְקָתוֹ בְּעֵדוּת אִשָּׁה אוֹ פָּסוּל וְכֵן בִּשְׁאָר כָּל הַדִּינִין וְלֹא יָדוּן הַדַּיָּן בִּסְמִיכַת דַּעְתּוֹ וְלֹא בִּידִיעָתוֹ כְּדֵי שֶׁלֹּא יֹאמַר כָּל הֶדְיוֹט לִבִּי מַאֲמִין לְדִבְרֵי זֶה וְדַעְתִּי סוֹמֶכֶת עַל זֶה. וְכֵן אֵין מוֹצִיאִין מִן הַיְתוֹמִים אֶלָּא בִּרְאָיָה בְּרוּרָה לֹא בְּדַעַת הַדַּיָּן וְלֹא בְּאֻמְדַּן הַמֵּת אוֹ הַטּוֹעֵן. וְאַף עַל פִּי כֵן אִם הֵעִיד אָדָם נֶאֱמָן בְּדָבָר מִכָּל הַדְּבָרִים וְנָטְתָה דַּעַת הַדַּיָּן שֶׁאֱמֶת הוּא אוֹמֵר מַמְתִּין בַּדִּין וְאֵינוֹ דּוֹחֶה עֵדוּתוֹ וְנוֹשֵׂא וְנוֹתֵן עִם בַּעֲלֵי דִּינִין עַד שֶׁיּוֹדוּ לְדִבְרֵי הָעֵד אוֹ יַעֲשׂוּ פְּשָׁרָה אוֹ יִסְתַּלֵּק מִן הַדִּין:","וּמִנַּיִן לְדַיָּן שֶׁהוּא יוֹדֵעַ בְּדִין שֶׁהוּא מְרֻמֶּה שֶׁלֹּא יֹאמַר אֶחְתְּכֶנּוּ וְיִהְיֶה הַקּוֹלָר תָּלוּי בְּצַוְּארֵי הָעֵדִים. תַּלְמוּד לוֹמַר (שמות כג ז) \"מִדְּבַר שֶׁקֶר תִּרְחָק\". כֵּיצַד יַעֲשֶׂה. יִדְרשׁ בּוֹ וְיַחְקֹר הַרְבֵּה בִּדְרִישָׁה וּבַחֲקִירָה שֶׁל דִּינֵי נְפָשׁוֹת אִם נִרְאֶה לוֹ לְפִי דַּעְתּוֹ [שֶׁאֵין בּוֹ רַמָּאוּת חוֹתֵךְ אֶת הַדִּין עַל פִּי הָעֵדוּת אֲבָל אִם הָיָה לִבּוֹ נוֹקְפוֹ] שֶׁיֵּשׁ בּוֹ רַמָּאוּת אוֹ שֶׁאֵין דַּעְתּוֹ סוֹמֶכֶת עַל דִּבְרֵי הָעֵדִים אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לְפָסְלָן אוֹ שֶׁדַּעְתּוֹ נוֹטָה שֶׁבַּעַל דִּין זֶה רַמַּאי וּבַעַל עָרְמָה וְהִשִּׁיא אֶת הָעֵדִים אַף עַל פִּי שֶׁהֵם כְּשֵׁרִים וּלְפִי תֻּמָּם הֵעִידוּ וְזֶה הַטַּעַם אוֹ שֶׁנִּרְאֶה לוֹ מִכְּלַל הַדְּבָרִים שֶׁיֵּשׁ שָׁם דְּבָרִים אֲחֵרִים מְסֻתָּרִין וְאֵינָן רוֹצִים לְגַלּוֹתָם. כָּל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן אָסוּר לוֹ לַחְתֹּךְ אוֹתוֹ הַדִּין אֶלָּא יְסַלֵּק עַצְמוֹ מִדִּין זֶה וִידִינֶנּוּ מִי שֶׁלִּבּוֹ שָׁלֵם בַּדָּבָר. וַהֲרֵי הַדְּבָרִים מְסוּרִים לַלֵּב וְהַכָּתוּב אוֹמֵר (דברים א יז) \"כִּי הַמִּשְׁפָּט לֵאלֹהִים הוּא\":","יֵשׁ לְבֵית דִּין לְהַלְקוֹת מִי שֶׁאֵינוֹ מְחֻיַּב מַלְקוֹת וְלַהֲרֹג מִי שֶׁאֵינוֹ מְחֻיַּב מִיתָה וְלֹא לַעֲבֹר עַל דִּבְרֵי תּוֹרָה אֶלָּא לַעֲשׂוֹת סְיָג לַתּוֹרָה. וְכֵיוָן שֶׁרוֹאִים בֵּית דִּין שֶׁפָּרְצוּ הָעָם בַּדָּבָר יֵשׁ לָהֶן לִגְדֹּר וּלְחַזֵּק הַדָּבָר כְּפִי מַה שֶּׁיֵּרָאֶה לָהֶם הַכּל הוֹרָאַת שָׁעָה לֹא שֶׁיִּקְבַּע הֲלָכָה לְדוֹרוֹת. מַעֲשֶׂה וְהִלְקוּ אָדָם שֶׁבָּעַל אִשְׁתּוֹ תַּחַת אִילָן. וּמַעֲשֶׂה בְּאֶחָד שֶׁרָכַב עַל סוּס בְּשַׁבָּת בִּימֵי יְוָנִים וֶהֱבִיאוּהוּ לְבֵית דִּין וּסְקָלוּהוּ. וּמַעֲשֶׂה וְתָלָה שִׁמְעוֹן בֶּן שֶׁטַח שְׁמוֹנִים נָשִׁים בְּיוֹם אֶחָד בְּאַשְׁקְלוֹן וְלֹא הָיוּ שָׁם כָּל דַּרְכֵי הַדְּרִישָׁה וַחֲקִירָה וְהַהַתְרָאָה וְלֹא בְּעֵדוּת בְּרוּרָה אֶלָּא הוֹרָאַת שָׁעָה כְּפִי מַה שֶּׁרָאָה:","וְכֵן יֵשׁ לְבֵית דִּין בְּכָל מָקוֹם וּבְכָל זְמַן לְהַלְקוֹת אָדָם שֶׁשְּׁמוּעָתוֹ רָעָה וְהָעָם מְרַנְּנִים עָלָיו שֶׁהוּא עוֹבֵר עַל הָעֲרָיוֹת וְהוּא שֶׁיִּהְיֶה קוֹל שֶׁאֵינוֹ פּוֹסֵק כְּמוֹ שֶׁבֵּאַרְנוּ וְלֹא יִהְיוּ אֵלּוּ אוֹיְבִים יְדוּעִים שֶׁמּוֹצִיאִין עָלָיו שְׁמוּעָה רָעָה. וְכֵן מְבַזִּין אֶת זֶה שֶׁשְּׁמוּעָתוֹ רָעָה וּמְחָרְפִין אֶת יוֹלַדְתּוֹ בְּפָנָיו:","וְכֵן יֵשׁ לַדַּיָּן תָּמִיד לְהַפְקִיר מָמוֹן שֶׁיֵּשׁ לוֹ בְּעָלִים וּמְאַבֵּד וְנוֹתֵן כְּפִי מַה שֶּׁיִּרְאֶה לִגְדֹּר פְּרָצוֹת הַדָּת וּלְחַזֵּק הַבֶּדֶק אוֹ לִקְנֹס אַלָּם זֶה וַהֲרֵי הוּא אוֹמֵר בְּעֶזְרָא (עזרא י ח) \"וְכל אֲשֶׁר לֹא יָבוֹא לִשְׁלֹשֶׁת הַיָּמִים כַּעֲצַת הַשָּׂרִים וְהַזְּקֵנִים יָחֳרַם כָּל רְכוּשׁוֹ\" מִכָּאן שֶׁהֶפְקֵר בֵּית דִּין הֶפְקֵר:","וְכֵן יֵשׁ לַדַּיָּן לְנַדּוֹת וּלְהַחֲרִים מִי שֶׁאֵינוֹ בֶּן נִדּוּי כְּדֵי לִגְדֹּר פֶּרֶץ כְּפִי מַה שֶּׁיֵּרָאֶה לוֹ וְהַשָּׁעָה צְרִיכָה לְכָךְ וְיֹאמַר שֶׁנִּדָּהוּ וְהֶחְרִימָהוּ עַל דַּעְתּוֹ וִיפַרְסֵם חֶטְאוֹ בָּרַבִּים שֶׁנֶּאֱמַר (שופטים ה כג) \"אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ ה' אֹרוּ אָרוֹר ישְׁבֶיהָ כִּי לֹא בָאוּ לְעֶזְרַת ה'\":","וְכֵן יֵשׁ לַדַּיָּן לַעֲשׂוֹת מְרִיבָה עִם הָרָאוּי לָרִיב עִמּוֹ וּלְקַלְּלוֹ וּלְהַכּוֹתוֹ וְלִתְלֹשׁ שְׂעָרוֹ וּלְהַשְׁבִּיעַ בֵּאלֹהִים בְּעַל כָּרְחוֹ שֶׁלֹּא יַעֲשֶׂה אוֹ שֶׁלֹּא עָשָׂה. שֶׁנֶּאֱמַר (נחמיה יג כה) \"וָאָרִיב עִמָּם וָאֲקַלְלֵם וָאַכֶּה מֵהֶם אֲנָשִׁים וָאֶמְרְטֵם וָאַשְׁבִּיעֵם בֵּאלֹהִים\":","וְכֵן יֵשׁ לוֹ לִכְפּוֹת יָדַיִם וְרַגְלַיִם וְלֶאֱסֹר בְּבֵית הָאֲסוּרִים וְלִדְחֹף וְלִסְחֹב עַל הָאָרֶץ שֶׁנֶּאֱמַר (עזרא ז כו) \"הֵן לְמוֹת הֵן לִשְׁרשִׁי הֵן לַעֲנָשׁ נִכְסִין וְלֶאֱסוּרִין\":","כָּל אֵלּוּ הַדְּבָרִים לְפִי מַה שֶּׁיִּרְאֶה הַדַּיָּן שֶׁזֶּה רָאוּי לְכָךְ וְשֶׁהַשָּׁעָה צְרִיכָה. וּבַכּל יִהְיוּ מַעֲשָׂיו לְשֵׁם שָׁמַיִם וְאַל יִהְיֶה כְּבוֹד הַבְּרִיּוֹת קַל בְּעֵינָיו שֶׁהֲרֵי הוּא דּוֹחֶה אֶת לֹא תַּעֲשֶׂה שֶׁל דִּבְרֵיהֶם וְכָל שֶׁכֵּן כְּבוֹד בְּנֵי אַבְרָהָם יִצְחָק וְיַעֲקֹב הַמַּחֲזִיקִין בְּתוֹרַת הָאֱמֶת שֶׁיִּהְיֶה זָהִיר שֶׁלֹּא יַהֲרֹס כְּבוֹדָם אֶלָּא לְהוֹסִיף בִּכְבוֹד הַמָּקוֹם בִּלְבַד שֶׁכָּל הַמְבַזֶּה אֶת הַתּוֹרָה גּוּפוֹ מְחֻלָּל עַל הַבְּרִיּוֹת וְהַמְכַבֵּד אֶת הַתּוֹרָה גּוּפוֹ מְכֻבָּד עַל הַבְּרִיּוֹת. וְאֵין כְּבוֹד הַתּוֹרָה אֶלָּא לַעֲשׂוֹת עַל פִּי חֻקֶּיהָ וּמִשְׁפָּטֶיהָ:"],"Mishneh Torah, Theft 3":["כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת נַעֲרָה שֶׁכָּל הָעוֹשֶׂה עֲבֵרָה שֶׁיֵּשׁ בָּהּ עֲוֹן מִיתַת בֵּית דִּין וְתַשְׁלוּמִין אֵינוֹ מְשַׁלֵּם אַף עַל פִּי שֶׁהָיָה שׁוֹגֵג. וְהָעוֹשֶׂה עֲבֵרָה שֶׁנִּתְחַיֵּב בָּהּ מַלְקוֹת וְתַשְׁלוּמִין לוֹקֶה וְאֵינוֹ מְשַׁלֵּם שֶׁאֵין אָדָם לוֹקֶה וּמְשַׁלֵּם. לְפִיכָךְ אִם הָיָה שׁוֹגֵג אוֹ לֹא הִתְרוּ בּוֹ מְשַׁלֵּם וְאֵינוֹ לוֹקֶה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּתְחַיֵּב בְּתַשְׁלוּמִין עִם עֲוֹן מִיתַת בֵּית דִּין כְּאַחַת אוֹ שֶׁנִּתְחַיֵּב תַּשְׁלוּמִין וּמַלְקוֹת בְּבַת אַחַת. אֲבָל אִם נִתְחַיֵּב בְּתַשְׁלוּמִין וְאַחַר כָּךְ נִתְחַיֵּב בְּמִיתַת בֵּית דִּין אוֹ בְּמַלְקוֹת אוֹ שֶׁנִּתְחַיֵּב מַלְקוֹת אוֹ מִיתַת בֵּית דִּין וְאַחַר כָּךְ נִתְחַיֵּב בְּתַשְׁלוּמִין הֲרֵי זֶה לוֹקֶה וּמְשַׁלֵּם וּמֵת וּמְשַׁלֵּם:","כֵּיצַד. זָרַק חֵץ בְּשַׁבָּת מִתְּחִלַּת אַרְבַּע לְסוֹף אַרְבַּע וְקָרַע בֶּגֶד חֲבֵרוֹ בַּהֲלִיכָתוֹ אוֹ שֶׁהִדְלִיק גְּדִישׁ חֲבֵרוֹ בְּשַׁבָּת אוֹ שֶׁגָּנַב כִּיס בְּשַׁבָּת וְהָיָה מְגָרְרוֹ עַד שֶׁהוֹצִיאוֹ מֵרְשׁוּת הַבְּעָלִים שֶׁהִיא רְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים וְאִבְּדוֹ שָׁם הֲרֵי זֶה פָּטוּר מִן הַתַּשְׁלוּמִין שֶׁאִסּוּר שַׁבָּת וְאִסּוּר גְּנֵבָה וְהֶזֵּק בָּאִין כְּאֶחָד. אֲבָל אִם גָּנַב כִּיס בְּשַׁבָּת וְהִגְבִּיהוֹ שָׁם בִּרְשׁוּת הַיָּחִיד וְאַחַר כָּךְ הוֹצִיאוֹ לִרְשׁוּת הָרַבִּים וְהִשְׁלִיכוֹ לַנָּהָר חַיָּב לְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל שֶׁהֲרֵי נִתְחַיֵּב בְּאִסּוּר גְּנֵבָה קֹדֶם שֶׁיִּתְחַיֵּב בְּאִסּוּר סְקִילָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן אִם קָצַץ אִילַן חֲבֵרוֹ בַּיּוֹם טוֹב וְהִתְרוּ בּוֹ אוֹ שֶׁהִדְלִיק אֶת הַגָּדִישׁ בְּיוֹם הַכִּפּוּרִים וְהִתְרוּ בּוֹ אוֹ גָּנַב וְטָבַח בְּיוֹם הַכִּפּוּרִים וְהִתְרוּ בּוֹ פָּטוּר מִן הַתַּשְׁלוּמִין אֲבָל אִם לֹא הִתְרוּ בּוֹ חַיָּב בְּתַשְׁלוּמִין וּמְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה:","גָּנַב וְטָבַח בְּשַׁבָּת אוֹ לַעֲבוֹדָה זָרָה אֲפִלּוּ בִּשְׁגָגָה פָּטוּר מִתַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיְתָה פָּרָה שְׁאוּלָה אֶצְלוֹ וּטְבָחָהּ בְּשַׁבָּת דֶּרֶךְ גְּנֵבָה פָּטוּר אַף מִן הַכֶּפֶל שֶׁהֲרֵי אִסּוּר שַׁבָּת וְאִסּוּר גְּנֵבָה בָּאִין כְּאַחַת וְאִם אֵין גְּנֵבָה אֵין טְבִיחָה וְאֵין מְכִירָה:","גָּנַב וּמָכַר בְּשַׁבָּת אוֹ שֶׁמָּכַר לַעֲבוֹדָה זָרָה חַיָּב לְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה שֶׁאֵין בַּמְּכִירָה מִיתָה. וְאִם נַעֲשֵׂית מְלָאכָה בְּשַׁבָּת בְּעֵת הַמְּכִירָה פָּטוּר מִתַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. כֵּיצַד. כְּגוֹן שֶׁלֹּא הִקְנָה לוֹ עַד שֶׁתָּנוּחַ בַּחֲצַר הַלּוֹקֵחַ שֶׁנִּמְצָא כְּשֶׁהוֹצִיא מֵרְשׁוּת לִרְשׁוּת אִסּוּר שַׁבָּת וּמְכִירָה בָּאִין כְּאַחַת:","עָשָׂה שָׁלִיחַ לִשְׁחֹט לוֹ וְשָׁחַט לוֹ הַשָּׁלִיחַ בְּשַׁבָּת הֲרֵי הַגַּנָּב חַיָּב בְּתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. שֶׁהֲרֵי זֶה הַגַּנָּב לֹא עָשָׂה עֲוֹן מִיתַת בֵּית דִּין. וּכְבָר בֵּאַרְנוּ שֶׁהַשּׁוֹחֵט עַל יְדֵי שָׁלִיחַ חַיָּב בְּתַשְׁלוּמִין:","הָיוּ שְׁנַיִם מְעִידִים שֶׁגָּנַב בֵּין שֶׁהֵעִידוּ הֵן עַצְמָן שֶׁטָּבַח אוֹ מָכַר בֵּין שֶׁהֵעִידוּ אֲחֵרִים שֶׁטָּבַח אוֹ מָכַר מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. הָיוּ שְׁנַיִם מְעִידִים שֶׁגָּנַב וְעֵד אֶחָד מֵעִיד שֶׁטָּבַח אוֹ מָכַר אוֹ שֶׁהוֹדָה מֵעַצְמוֹ שֶׁטָּבַח אוֹ מָכַר מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְאֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה שֶׁהַמּוֹדֶה בִּקְנָס פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁהוֹדָה בִּקְנָס וְאַחַר כָּךְ בָּאוּ עֵדִים. אִם הוֹדָה בַּתְּחִלָּה בִּפְנֵי בֵּית דִּין וּבְבֵית דִּין פָּטוּר. אֲבָל אִם הוֹדָה חוּץ לְבֵית דִּין אוֹ שֶׁהוֹדָה בִּפְנֵי שְׁנַיִם בִּלְבַד וְאַחַר כָּךְ בָּאוּ עֵדִים הֲרֵי זֶה מְשַׁלֵּם קְנָס עַל פִּיהֶם:","כֵּיצַד. הוֹדָה בְּבֵית דִּין שֶׁגָּנַב וְאַחַר כָּךְ בָּאוּ עֵדִים שֶׁגָּנַב פָּטוּר מִן הַכֶּפֶל שֶׁהֲרֵי חִיֵּב עַצְמוֹ בְּקֶרֶן קֹדֶם שֶׁיָּבוֹאוּ עֵדִים. אֲבָל אִם אָמַר לֹא גָּנַבְתִּי שֶׁפָּטַר עַצְמוֹ מִן הַכּל וּבָאוּ עֵדִים שֶׁגָּנַב וְחָזַר וְאָמַר בְּבֵית דִּין טָבַחְתִּי אוֹ מָכַרְתִּי אִם בָּאוּ עֵדִים אַחַר כָּךְ שֶׁטָּבַח אוֹ מָכַר מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. לְפִי שֶׁפָּטַר עַצְמוֹ תְּחִלָּה מִכְּלוּם עַד שֶׁבָּאוּ הָעֵדִים:","הַגּוֹנֵב שׁוֹר שֶׁל שְׁנֵי שֻׁתָּפִין וּטְבָחוֹ אוֹ מְכָרוֹ וְהוֹדָה בְּבֵית דִּין לְאֶחָד מֵהֶן וְכָפַר בָּאַחֵר וְאַחַר כָּךְ בָּאוּ עֵדִים שֶׁגָּנַב וְטָבַח אוֹ מָכַר מְשַׁלֵּם לְזֶה שֶׁכָּפַר לוֹ חֲמִשָּׁה חֲצָאֵי בָּקָר וְאַרְבָּעָה חֲצָאֵי צֹאן:","דִּין הַגַּנָּב לְשַׁלֵּם הַקֶּרֶן וְהַכֶּפֶל אוֹ תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה מִן הַמִּטַּלְטְלִין שֶׁלּוֹ. אִם לֹא נִמְצְאוּ לוֹ מִטַּלְטְלִין בֵּית דִּין יוֹרְדִין לִנְכָסָיו וְגוֹבִין הַכּל מִן הַיָּפֶה שֶׁבִּנְכָסָיו כִּשְׁאָר הַנִּזָּקִין שֶׁנֶּאֱמַר בָּהֶן (שמות כב ד) \"מֵיטַב שָׂדֵהוּ\". וְאִם אֵין לוֹ קַרְקַע וְלֹא מִטַּלְטְלִין בֵּית דִּין מוֹכְרִין אוֹתוֹ וְנוֹתְנִין דָּמָיו לַנִּזָּק שֶׁנֶּאֱמַר (שמות כב ב) \"אִם אֵין לוֹ וְנִמְכַּר בִּגְנֵבָתוֹ\":","הָאִישׁ נִמְכָּר בִּגְנֵבָתוֹ אֲבָל לֹא הָאִשָּׁה. וְדָבָר זֶה מִפִּי הַקַּבָּלָה. וְאֵין הַגַּנָּב נִמְכָּר אֶלָּא בְּקֶרֶן אֲבָל בְּכֶפֶל אוֹ בְּתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה אֵינוֹ נִמְכָּר אֶלָּא הֲרֵי זֶה עָלָיו חוֹב עַד שֶׁיַּעֲשִׁיר:","גָּנַב אֶת הָעַכּוּ\"ם אוֹ אֶת הַהֶקְדֵּשׁ אֵינוֹ נִמְכָּר עַל הַקֶּרֶן אֶלָּא הֲרֵי זֶה עָלָיו חוֹב עַד שֶׁיַּעֲשִׁיר:","הָיָה קֶרֶן הַגְּנֵבָה שָׁוֶה מֵאָה וְאֵין הַגַּנָּב שָׁוֶה אֶלָּא חֲמִשִּׁים הֲרֵי זֶה נִמְכָּר וּשְׁאָר הַקֶּרֶן עִם הַכֶּפֶל עָלָיו חוֹב עַד שֶׁיֵּצֵא בַּשְּׁבִיעִית וְיַעֲשִׁיר וִישַׁלֵּם. הָיָה הַגַּנָּב שָׁוֶה מֵאָה וְאֶחָד אֵינוֹ נִמְכָּר שֶׁנֶּאֱמַר (שמות כב ב) \"וְנִמְכַּר בִּגְנֵבָתוֹ\" עַד שֶׁיִּהְיוּ דָּמָיו כֻּלָּן מֻבְלָעִין בִּגְנֵבָתוֹ:","גָּנַב וְנִמְכַּר וְחָזַר וְגָנַב. אִם לַשֵּׁנִי גָּנַב הֲרֵי זֶה נִמְכָּר פַּעַם שְׁנִיָּה. וַאֲפִלּוּ גָּנַב לְמֵאָה אֲנָשִׁים נִמְכָּר מֵאָה פְּעָמִים. וְאִם לָרִאשׁוֹן גָּנַב פַּעַם שְׁנִיָּה אֵינוֹ נִמְכָּר שְׁנִיָּה אֶלָּא יִשָּׁאֵר עָלָיו הַכּל חוֹב:","גָּנַב לָזֶה וְחָזַר וְגָנַב לָזֶה וְחָזַר וְגָנַב לָזֶה כֻּלָּם שֻׁתָּפִין בּוֹ. אִם הָיוּ דָּמָיו כְּנֶגֶד הַקֶּרֶן שֶׁל שְׁלָשְׁתָּן אוֹ פָּחוֹת מִן הַקֶּרֶן נִמְכָּר וּמְחַלְּקִין בֵּינֵיהֶן וּשְׁאָר הַכְּפֵלוֹת חוֹב עָלָיו. וְאִם הָיוּ דָּמָיו יֶתֶר אֵינוֹ נִמְכָּר וְהַכּל חוֹב עָלָיו עַד שֶׁיַּעֲשִׁיר:","שֻׁתָּפִין שֶׁגָּנְבוּ כְּאֶחָד מְשַׁלְּשִׁין בֵּינֵיהֶן וְכָל אֶחָד מֵהֶן נִמְכָּר בְּחֶלְקוֹ מִן הַקֶּרֶן. וְכָל מִי שֶׁדָּמָיו יֶתֶר עַל חֵלֶק הַקֶּרֶן שֶׁנִּתְחַיֵּב בּוֹ אֵינוֹ נִמְכָּר:"],"Mishneh Torah, Things Forbidden on the Altar 6":["כְּשֵׁם שֶׁמִּצְוָה לִהְיוֹת כָּל קָרְבָּן תָּמִים וְנִבְחָר כָּךְ הַנְּסָכִין יִהְיוּ תְּמִימִים וְנִבְחָרִים שֶׁנֶּאֱמַר (במדבר כ״ח:ל״א) \"תְּמִימִם יִהְיוּ לָכֶם וְנִסְכֵּיהֶם\" שֶׁיִּהְיוּ הַנְּסָכִים תְּמִימִים שֶׁלֹּא יָבִיא נְסָכִים לֹא מִיַּיִן מְעֵשָּׁן וְלֹא סלֶת שֶׁהִתְלִיעָה וְלֹא יִבְלל בְּשֶׁמֶן שֶׁרֵיחוֹ אוֹ טַעְמוֹ רַע:","וְכֵן עֲצֵי הַמַּעֲרָכָה לֹא יִהְיוּ אֶלָּא נִבְחָרִים וְלֹא יִהְיֶה בָּהֶם תּוֹלַעַת. וְכָל עֵץ שֶׁהִתְלִיעַ כְּשֶׁהוּא לַח פָּסוּל לַמִּזְבֵּחַ. הִתְלִיעַ יָבֵשׁ גּוֹרֵר אֶת הַמָּקוֹם שֶׁהִתְלִיעַ. וַעֲצֵי סְתִירָה פְּסוּלִין לְעוֹלָם לֹא יָבִיאוּ אֶלָּא חֲדָשִׁים:","הַמַּקְדִּישׁ יַיִן פָּסוּל אוֹ סלֶת אוֹ שֶׁמֶן פָּסוּל אוֹ עֵצִים פְּסוּלִים לַמִּזְבֵּחַ הֲרֵי הַדָּבָר סָפֵק אִם דּוֹמִים לְבַעַל מוּם כִּבְהֵמָה וְלוֹקֶה אוֹ אֵינָן כְּבַעַל מוּם לְפִיכָךְ אֵינוֹ לוֹקֶה וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","הַסּלֶת וְהַיַּיִן וְהַשֶּׁמֶן וְהַלְּבוֹנָה וְהָעוֹפוֹת וְהָעֵצִים וּכְלֵי שָׁרֵת שֶׁנִּפְסְלוּ אוֹ שֶׁנִּטְמְאוּ אֵין פּוֹדִין אוֹתָן שֶׁנֶּאֱמַר (ויקרא כז-יא) \"וְהֶעֱמִיד\" (ויקרא כז-יב) \"וְהֶעֱרִיךְ\". כָּל שֶׁיֶּשְׁנוֹ בְּהַעֲמָדָה נֶעֱרָךְ וְאֵלּוּ אֵינָן בִּכְלַל הַעֲמָדָה. לְפִיכָךְ אֵין נִפְדִּין לְעוֹלָם:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנִּפְסְלוּ אוֹ שֶׁנִּטְמְאוּ אַחַר שֶׁנִּתְקַדְּשׁוּ בִּכְלִי שָׁרֵת. אֲבָל קֹדֶם שֶׁיִּתְקַדְּשׁוּ בִּכְלִי אִם נִטְמְאוּ אוֹ נִפְסְלוּ פּוֹדִין אוֹתָן. אֲבָל טְהוֹרִין אַף עַל פִּי שֶׁעֲדַיִן לֹא קָדְשׁוּ בִּכְלִי אֵין פּוֹדִין אוֹתָן חוּץ מִמִּנְחַת חוֹטֵא שֶׁנֶּאֱמַר בָּהּ (ויקרא ה-י) \"מֵחַטָּאתוֹ\" (ויקרא ה-יג) \"עַל חַטָּאתוֹ\" לוֹמַר שֶׁמֵּבִיא חַטָּאתוֹ מִדְּמֵי חַטָּאתוֹ. לְפִיכָךְ קֹדֶם שֶׁתִּתְקַדֵּשׁ בִּכְלִי שָׁרֵת הֲרֵי הִיא כִּקְדֻשַּׁת דָּמִים וּפוֹדִין אוֹתָהּ אַף עַל פִּי שֶׁהִיא טְהוֹרָה. וְכָל הַנְּסָכִים שֶׁנִּטְמְאוּ עוֹשֶׂה לָהֶם מַעֲרָכָה בִּפְנֵי עַצְמָן וְשׂוֹרְפָן בַּמִּזְבֵּחַ:","מֵי הֶחָג שֶׁנִּטְמְאוּ וְהִשִּׁיקָן וְטִהֲרָן [כְּמוֹ שֶׁיִּתְבָּאֵר בְּטָהֳרוֹת]. אִם טִהֲרָן וְאַחַר כָּךְ הִקְדִּישָׁן הֲרֵי אֵלּוּ מִתְנַסְּכִין. וְאִם הִקְדִּישָׁן וְאַחַר כָּךְ נִטְמְאוּ הוֹאִיל וְנִדְחוּ יִדָּחוּ:","זֵיתִים וַעֲנָבִים שֶׁנִּטְמְאוּ דּוֹרְכָן פָּחוֹת מִכַּבֵּיצָה. וְהַמַּשְׁקִין הַיּוֹצְאִין מֵהֶן כְּשֵׁרִים לִנְסָכִים. שֶׁהַמַּשְׁקֶה מֻפְקָד הוּא בָּאֹכֶל וּכְאִלּוּ אֵינוֹ מִגּוּפוֹ:","מַעֲלָה יְתֵרָה עָשׂוּ חֲכָמִים בְּקָדָשִׁים שֶׁזְּרָעִים שֶׁנִּטְמְאוּ אֲפִלּוּ זְרָעָן הַיּוֹצֵא מֵהֶן פְּסוּלִין לִנְסָכִים שֶׁאֵין זְרִיעָה מוֹעֶלֶת בְּקָדָשִׁים. וְכֵן הָעֵצִים וְהַלְּבוֹנָה אַף עַל פִּי שֶׁאֵינָן אֳכָלִין הֲרֵי הֵן מִתְטַמְּאִין כְּאֹכֶל לְעִנְיַן הַקָּרְבָּנוֹת וְיִפָּסְלוּ הָעֵצִים וְהַלְּבוֹנָה בְּטֻמְאָה זוֹ לַמִּזְבֵּחַ וְאֵין מַקְרִיבִין אוֹתָן:","וְאֵלּוּ הֵן הַיֵּינוֹת הַפְּסוּלִין לְגַבֵּי הַמִּזְבֵּחַ. הַמָּתוֹק וְהַמְעֵשָּׁן וְהַמְבֻשָּׁל בְּאֵשׁ אוֹ בַּשֶּׁמֶשׁ אוֹ שֶׁנִּשְׁתַּנָּה טַעְמוֹ בְּבִשּׁוּל. אֲבָל יַיִן שֶׁמְּחַמְּמִין אוֹתוֹ בַּשֶּׁמֶשׁ וְלֹא נָתְנָה בּוֹ טַעַם בִּשּׁוּל. וְכֵן יֵין צִמּוּקִין וְיַיִן מִגִּתּוֹ שֶׁלֹּא שָׁהָה אַרְבָּעִים יוֹם. וְיֵין הַדָּלִיּוֹת וְיֵין כֶּרֶם הַנָּטוּעַ בְּבֵית הַשְּׁלָחִין אוֹ בְּבֵית הַזְּבָלִים. אוֹ יֵין גְּפָנִים שֶׁנִּזְרַע זֶרַע בֵּינֵיהֶן. אוֹ יֵין כֶּרֶם שֶׁלֹּא נֶעֱבַד. כָּל אֵלּוּ הַיֵּינוֹת לֹא יָבִיא לְכַתְּחִלָּה וְאִם הֵבִיא כָּשֵׁר:","יַיִן שֶׁנִּתְגַּלָּה פָּסוּל לְגַבֵּי הַמִּזְבֵּחַ. הִדְלָה גֶפֶן עַל גַּבֵּי תְּאֵנָה יֵינָהּ פָּסוּל לִנְסָכִים מִפְּנֵי שֶׁנִּשְׁתַּנָּה רֵיחוֹ. הֲרֵי הוּא אוֹמֵר (ויקרא כג-לז) \"זֶבַח וּנְסָכִים\" מָה זֶבַח שֶׁלֹּא נִשְׁתַּנָּה אַף נְסָכִים שֶׁלֹּא נִשְׁתַּנּוּ:","סלֶת שֶׁהִתְלִיעָה רֻבָּהּ אוֹ הִתְלִיעוּ רֹב הַחִטִּים שֶׁנַּעֲשֵׂית מֵהֶן פְּסוּלָה. הִתְלִיעַ רֹב חִטָּה אַחַת הֲרֵי זֶה סָפֵק. וְכָל סלֶת שֶׁנִּשְׁאַר בָּהּ קֶמַח פְּסוּלָה:","כֵּיצַד בּוֹדְקִים. מַכְנִיס הַגִּזְבָּר יָדוֹ לְתוֹךְ הַסּלֶת אִם עָלָה בָּהּ אָבָק פְּסוּלָה עַד שֶׁיַּחֲזֹר וִינַפֶּה אוֹתָהּ. אֲבָל סלֶת חִטִּים שֶׁנִּזְרְעוּ בְּבֵית הַשְּׁלָחִין אוֹ בְּבֵית הַזְּבָלִים אוֹ בְּבֵית הָאִילָן אוֹ בְּאֶרֶץ שֶׁלֹּא נָרָהּ וְלֹא עֲבָדָהּ לֹא יָבִיא לְכַתְּחִלָּה וְאִם הֵבִיא כְּשֵׁרָה:","חִטִּים שֶׁלְּקָטָן מִגְּלָלֵי הַבָּקָר וּזְרָעָם הֲרֵי אֵלּוּ סָפֵק אִם עָבְרָה מֵאוּסָן בַּזְּרִיעָה אוֹ עֲדַיִן הֵן מְאוּסִין. לְפִיכָךְ לֹא יָבִיא מֵהֶן מְנָחוֹת וְאִם הֵבִיא כָּשֵׁר:","וְאֵלּוּ הֵן הַשְּׁמָנִים הַפְּסוּלִין. שֶׁמֶן שֶׁל גַּרְגְּרִים שֶׁנִּשְׁרוּ בְּמַיִם אוֹ שֶׁל זֵיתִים כְּבוּשִׁין אוֹ שְׁלוּקִים אוֹ שֶׁמֶן שֶׁל שְׁמָרִים אוֹ שֶׁמֶן שֶׁרֵיחוֹ רַע כָּל אֵלּוּ פְּסוּלִין. אֲבָל שֶׁמֶן זַיִת שֶׁנְּטָעוֹ בְּבֵית הַזְּבָלִים אוֹ בְּבֵית הַשְּׁלָחִין אוֹ שֶׁנִּזְרַע זֶרַע בֵּינֵיהֶן. אוֹ שֶׁמֶן שֶׁהוֹצִיאוֹ מִזֵּיתִים שֶׁלֹּא בָּשְׁלוּ אֶלָּא עֲדַיִן הֵם פַּגִּין כָּל אֵלּוּ לֹא יָבִיא. וְאִם הֵבִיא כָּשֵׁר:","כָּל הַמְּנָחוֹת וְהַנְּסָכִים כְּשֵׁרִים מֵהָאָרֶץ וּמִחוּצָה לָאָרֶץ מִן הֶחָדָשׁ וּמִן הַיָּשָׁן וּבִלְבַד שֶׁיָּבִיאוּ מִן הַמֻּבְחָר. חוּץ מִן הָעֹמֶר וּשְׁתֵּי הַלֶּחֶם שֶׁאֵינָן בָּאִין אֶלָּא מִן הֶחָדָשׁ וּמֵאֶרֶץ יִשְׂרָאֵל:"],"Mishneh Torah, Those Who Defile Bed or Seat 7":["הַזָּב מְטַמֵּא אֶת הַמִּשְׁכָּב וְהַמּוֹשָׁב וְהַמֶּרְכָּב בַּחֲמִשָּׁה דְּרָכִים. עוֹמֵד. יוֹשֵׁב. שׁוֹכֵב. נִתְלֶה. וְנִשְׁעָן. כֵּיצַד. כְּלִי הֶעָשׂוּי לְמִשְׁכָּב אוֹ לְמוֹשָׁב אוֹ לְמֶרְכָּב אֲפִלּוּ הָיָה תַּחַת הָאֶבֶן אִם עָמַד אֶחָד מִמְּטַמְּאֵי מִשְׁכָּב עַל הָאֶבֶן אוֹ יָשַׁב עָלֶיהָ אוֹ שָׁכַב אוֹ נִשְׁעַן עָלֶיהָ אוֹ נִתְלָה בָּהּ הוֹאִיל וְנִתְנַשֵּׂא עַל הַכְּלִי הַזֶּה מִכָּל מָקוֹם נִטְמָא וְנַעֲשָׂה אַב טֻמְאָה. וְכָל אֶחָד מֵחֲמִשָּׁה דְּרָכִים אֵלּוּ הוּא הַנִּקְרָא מִדְרָס בְּכָל מָקוֹם:","וְכֵן הַמִּשְׁכָּב וְהַמֶּרְכָּב מְטַמְּאִין אֶת הָאָדָם בְּשִׁבְעָה דְּרָכִים. בַּחֲמִשָּׁה דְּרָכִים אֵלּוּ שֶׁמָּנִינוּ. וּבְמַגָּע וּבְמַשָּׂא. כֵּיצַד. מִשְׁכָּב אוֹ מֶרְכָּב שֶׁדָּרַס עָלָיו הַזָּב וְנִטְמָא בְּמִדְרָסוֹ. הַנּוֹגֵעַ בּוֹ אוֹ הַנּוֹשְׂאוֹ טָמֵא. וְכֵן הַיּוֹשֵׁב עָלָיו אוֹ הָעוֹמֵד אוֹ הַשּׁוֹכֵב אוֹ הַנִּתְלֶה אוֹ הַנִּשְׁעָן אַף עַל פִּי שֶׁהָיְתָה אֶבֶן מַבְדֶּלֶת בֵּין הַטָּהוֹר וּבֵין הַמִּדְרָס הֲרֵי זֶה נִטְמָא שֶׁנֶּאֱמַר (ויקרא טו ו) \"וְהַיּשֵׁב עַל הַכְּלִי אֲשֶׁר יֵשֵׁב עָלָיו הַזָּב\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁמָּקוֹם שֶׁהַזָּב יוֹשֵׁב וּמְטַמֵּא אִם יָשַׁב שָׁם הַטָּהוֹר נִטְמָא. מָה הַזָּב מְטַמֵּא מֶרְכָּב וּמוֹשָׁב שֶׁתַּחַת הָאֶבֶן אַף הַטָּהוֹר מִתְטַמֵּא מִן הַמִּשְׁכָּב אוֹ הַמֶּרְכָּב שֶׁהוּא מִתַּחַת הָאֶבֶן אַף עַל פִּי שֶׁאֵין הַזָּב שָׁם עַל הַמִּשְׁכָּב וְאָדָם זֶה שֶׁהוּא לְמַעְלָה מִן הַמִּדְרָס מְטַמֵּא בְּגָדִים כָּל זְמַן שֶׁלֹּא פֵּרַשׁ מִמְּטַמְּאָיו כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵין הַזָּב מְטַמֵּא אֶת הַמִּשְׁכָּב עַד שֶׁיִּנָּשֵׂא רֻבּוֹ עַל הַמִּשְׁכָּב אוֹ עַל הַמּוֹשָׁב אוֹ עַל הַמֶּרְכָּב. וְכֵן הַטָּהוֹר שֶׁדָּרַס עַל מִדְרַס הַזָּב אֵינוֹ מִתְטַמֵּא מֵחֲמַת הַמִּדְרָס עַד שֶׁיִּנָּשֵׂא רֻבּוֹ עָלָיו. אֲבָל אִם נִשָּׂא מִעוּטוֹ הוֹאִיל וְלֹא נָגַע הֲרֵי זֶה טָהוֹר. כֵּיצַד. מִקְצָת טָמֵא עַל הַמִּשְׁכָּב וּמִקְצָת הַטָּהוֹר עַל אוֹתוֹ מִשְׁכָּב הַמִּשְׁכָּב טָהוֹר וְהַטָּהוֹר שֶׁנָּשָׂא מִקְצָתוֹ עָלָיו טְהוֹרִין. הַטָּמֵא שֶׁנִּשָּׂא רֻבּוֹ עַל מִקְצָת הַמִּשְׁכָּב אוֹ הַמֶּרְכָּב נִטְמָא הַמִּשְׁכָּב כֻּלּוֹ אוֹ הַמֶּרְכָּב כֻּלּוֹ. וְכֵן הַטָּהוֹר שֶׁנִּשָּׂא רֻבּוֹ עַל מִקְצָת הַמִּדְרָס נִטְמָא וְאַף עַל פִּי שֶׁלֹּא נָשָׂא אֶלָּא עַל מִקְצָת הַמּוֹשָׁב:","זָב שֶׁהָיָה מֻטָּל עַל חֲמִשָּׁה סַפְסָלִין שֶׁהֵן מֻנָּחִין לְאָרְכָּן טְמֵאִים שֶׁהֲרֵי נִשָּׂא רֻבּוֹ עַל כָּל אֶחָד מֵהֶן. הָיוּ מֻנָּחִין לְרָחְבָּן טְהוֹרִין שֶׁהֲרֵי לֹא נִשָּׂא רֻבּוֹ עַל כָּל אֶחָד מֵהֶן. וְאִם יָשַׁן עֲלֵיהֶם בֵּין כָּךְ וּבֵין כָּךְ טְמֵאִים שֶׁמָּא נִתְהַפֵּךְ עֲלֵיהֶם וְנִמְצָא רֻבּוֹ עַל כָּל אֶחָד. הָיָה מֻטָּל עַל שִׁשָּׁה כֵּלִים הָעֲשׂוּיִים לְמִשְׁכָּב. שְׁתֵּי יָדָיו עַל שְׁנַיִם. וּשְׁנֵי רַגְלָיו עַל שְׁנַיִם. וְרֹאשׁוֹ עַל אֶחָד. וְגוּפוֹ עַל אֶחָד. אֵין טָמֵא מִשּׁוּם מִשְׁכָּב אֶלָּא זֶה שֶׁתַּחַת גּוּפוֹ שֶׁהֲרֵי נִשָּׂא רֻבּוֹ עָלָיו. עָמַד עַל שְׁנֵי מִשְׁכָּבוֹת רַגְלוֹ אַחַת עַל אֶחָד וְרַגְלוֹ שְׁנִיָּה עַל הַשֵּׁנִי שְׁנֵיהֶן טְמֵאִין:","הָיָה יוֹשֵׁב עַל גַּבֵּי הַמִּטָּה וְאַרְבָּעָה מִשְׁכָּבוֹת תַּחַת אַרְבַּע רַגְלֵי הַמִּטָּה כֻּלָּן טְמֵאוֹת מִפְּנֵי שֶׁאֵינָהּ יְכוֹלָה לַעֲמֹד עַל שָׁלֹשׁ:","הָיָה רוֹכֵב עַל גַּבֵּי בְּהֵמָה וְאַרְבָּעָה מִשְׁכָּבוֹת תַּחַת אַרְבַּע רַגְלֶיהָ כֻּלָּן טְהוֹרוֹת. מִפְּנֵי שֶׁהַבְּהֵמָה יְכוֹלָה לַעֲמֹד עַל שָׁלֹשׁ וְנִמְצֵאת הָרְבִיעִית מְסַיֵּעַ וּמְסַיֵּעַ אֵין בּוֹ מַמָּשׁ. וְהוֹאִיל וְכָל אַחַת רְאוּיָה לִהְיוֹת מְסַיֵּעַ וְאֵין אָנוּ יוֹדְעִים אֵי זוֹ יָד וְאֵי זוֹ רֶגֶל הִיא שֶׁלֹּא הָיְתָה נִשְׁעֶנֶת עָלֶיהָ הֲרֵי לֹא הֻחְזְקָה טֻמְאָה בְּאַחַת מֵהֶן וּלְפִיכָךְ כֻּלָּן טְהוֹרוֹת. לְפִיכָךְ אִם הָיָה מִשְׁכָּב אֶחָד תַּחַת שְׁתֵּי יְדֵי הַבְּהֵמָה אוֹ תַּחַת שְׁתֵּי רַגְלֶיהָ אוֹ תַּחַת יָדָהּ וְרַגְלָהּ הֲרֵי זֶה טָמֵא שֶׁהֲרֵי וַדַּאי נִשָּׂא הַזָּב עַל מִשְׁכָּב זֶה. שֶׁאֵין הַבְּהֵמָה יְכוֹלָה לַעֲמֹד עַל שְׁתַּיִם:","יָשַׁב הַטָּמֵא עַל קוֹרַת בֵּית הַבַּד כָּל הַכֵּלִים שֶׁבָּעֵקֶל טְמֵאִים. שֶׁהֲרֵי הֵם רְצוּצִים תַּחַת הַקּוֹרָה. אֲבָל אִם יָשַׁב עַל מַכְבֵּשׁ שֶׁל כּוֹבֵס הֲרֵי הַכֵּלִים שֶׁתַּחַת לוּחַ הַמַּכְבֵּשׁ טְהוֹרִים. מִפְּנֵי שֶׁהוּא רָפוּי וְנִמְצֵאת מִשְׁעֶנֶת הַמַּכְבֵּשׁ עַל רַגְלָיו לֹא עַל הַכֵּלִים שֶׁתַּחְתָּיו. שֶׁאִם יִרְצֶה אָדָם לְהַכְנִיס סַכִּין וְכַיּוֹצֵא בָּהּ בֵּין הַכֵּלִים שֶׁתַּחַת הַמַּכְבֵּשׁ וּבֵין הַמַּכְבֵּשׁ מַכְנִיס אַף עַל פִּי שֶׁהוּא קָשׁוּר:","זָב שֶׁדָּרַס עַל כְּלִי שֶׁלֹּא נַעֲשָׂה לְמִשְׁכָּב אוֹ לְמוֹשָׁב אוֹ לְמֶרְכָּב אַף עַל פִּי שֶׁהוּא רָאוּי לְמִשְׁכָּב הוֹאִיל וְלֹא נָגַע בּוֹ הֲרֵי זֶה טָהוֹר. שֶׁהֲרֵי אוֹמְרִים לוֹ עֲמֹד וְנַעֲשֶׂה מְלַאכְתֵּנוּ בִּכְלִי זֶה. כֵּיצַד. כָּפָה סְאָה וְיָשַׁב עָלֶיהָ כָּפָה עֲרֵבָה וְיָשַׁב עָלֶיהָ אוֹ שֶׁיָּשַׁב עַל פָּרֹכֶת אוֹ עַל קֶלַע שֶׁל סְפִינָה וְכַיּוֹצֵא בָּהֶן. הֲרֵי אֵלּוּ טְהוֹרִים. שֶׁנֶּאֱמַר (ויקרא טו ד) \"אֲשֶׁר יֵשֵׁב עָלָיו\" הַמְיֻחָד לִישִׁיבָה לֹא שֶׁאוֹמְרִים לוֹ עֲמֹד וְנַעֲשֶׂה מְלַאכְתֵּנוּ. מִפְּנֵי שֶׁכְּלִי זֶה לֹא נַעֲשָׂה לִישִׁיבָה. הָיָה הַכְּלִי מְשַׁמֵּשׁ לִישִׁיבָה עִם מְלַאכְתּוֹ שֶׁעוֹשֶׂה לָהּ הֲרֵי זֶה מִתְטַמֵּא בְּמִדְרָס. כְּגוֹן הָרְדִיד. וְהֶחָלוּק. וְהַטַּלִּית. וְהַתּוּרְמָל. וְהַחֵמֶת. אַף עַל פִּי שֶׁכָּל אֶחָד מֵהֶן לֹא נַעֲשָׂה מִתְּחִלָּה לְמִשְׁכָּב הֲרֵי הוּא מְשַׁמֵּשׁ אֶת הַמִּשְׁכָּב עִם מְלַאכְתּוֹ. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ. וּבְהִלְכוֹת כֵּלִים אֲבָאֵר כָּל הַכֵּלִים הַמִּטַּמְּאִין בְּמִדְרָס וְכֵלִים שֶׁאֵין מִטַּמְּאִין בְּמִדְרָס. וְאֵי זֶה כְּלִי רָאוּי לִישִׁיבָה. וְאֵי זֶה רָאוּי לִשְׁכִיבָה. וְאֵי זֶה רָאוּי לִרְכִיבָה:"],"Mishneh Torah, Tithes 5":["הַלוֹקֵחַ פֵּרוֹת תְּלוּשִׁין לְאָכְלָן נִקְבְּעוּ לְמַעֲשֵׂר מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ. וּמֵאֵימָתַי יִקָבְעוּ. מִשֶּׁיִּתֵּן אֶת הַדָּמִים אַף עַל פִּי שֶׁלֹּא מָשַׁךְ. הֲרֵי שֶׁלֹּא נָתַן דָּמִים וְהָיָה בּוֹרֵר וּמַנִּיחַ בּוֹרֵר וּמַנִּיחַ אֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ וְאַף עַל פִּי שֶׁגָּמַר בְּלִבּוֹ לִקַּח לֹא נִתְחַיֵּב לְעַשֵּׂר. וְאִם הָיָה יְרֵא שָׁמַיִם מִשֶּׁגָּמַר בְּלִבּוֹ מְעַשֵּׂר וְאַחַר כָּךְ יַחֲזִיר לַמּוֹכֵר אִם רָצָה לְהַחֲזִיר:","הַלּוֹקֵחַ בִּמְחֻבָּר לַקַּרְקַע אוֹ שֶׁלָּקַח תָּלוּשׁ לִשְׁלֹחַ לַחֲבֵרוֹ לֹא נִקְבְּעוּ וְיֵשׁ לוֹ לֶאֱכל מֵהֶן עַרְאַי:","הָאוֹמֵר לַחֲבֵרוֹ הֵא לְךָ אִיסָר זֶה וְתֵן לִי בּוֹ חֲמֵשׁ תְּאֵנִים הֲרֵי זֶה אוֹכֵל אַחַת אַחַת וּפָטוּר. וְאִם צֵרֵף חַיָּב לְעַשֵּׂר. הֵא לְךָ אִיסָר זֶה בְּעֶשְׂרִים תְּאֵנִים שֶׁאָבֹר לִי. בּוֹרֵר אַחַת אַחַת וְאוֹכֵל. בְּאֶשְׁכּוֹל שֶׁאָבֹר לִי מְגַרְגֵּר מִמֶּנּוּ בָּאִילָן וְאוֹכֵל. בְּרִמֹּן שֶׁאָבֹר לִי פּוֹרְטוֹ בָּאִילָן וְאוֹכֵל. בַּאֲבַטִּיחַ שֶׁאָבֹר לִי כּוֹפֵת בַּקַּרְקַע וְאוֹכֵל. וְאִם קָצַץ אֶת הַתְּאֵנִים וְצֵרְפָם אוֹ שֶׁקִּצֵּץ הָאֶשְׁכּוֹל אוֹ הָאֲבַטִּיחַ. חַיָּב לְעַשֵּׂר. שֶׁהֲרֵי לֹא קָנָה אֶלָּא הַנִּתְלָשׁ. אֲבָל אִם אָמַר לוֹ הֵא לְךָ אִיסָר בִּשְׁתֵּי תְּאֵנִים אֵלּוּ בִּשְׁנֵי אֶשְׁכּוֹלוֹת אֵלּוּ בִּשְׁנֵי רִמּוֹנִים אֵלּוּ בִּשְׁנֵי אֲבַטִּיחִים אֵלּוּ קוֹצֵץ כְּדַרְכּוֹ וְאוֹכֵל עַרְאַי וּפָטוּר שֶׁלֹּא נִקְבְּעוּ בְּמִקָּח שֶׁהֲרֵי לְקָחָן בִּמְחֻבָּר:","הַמַּחֲלִיף עִם חֲבֵרוֹ זֶה לֶאֱכל וְזֶה לֶאֱכל שְׁנֵיהֶן נִקְבְּעוּ לְמַעַשְׂרוֹת שֶׁהֲרֵי לָקְחוּ בְּתָלוּשׁ. זֶה לִקְצוֹת וְזֶה לִקְצוֹת שְׁנֵיהֶן לֹא נִקְבְּעוּ שֶׁאֵין הַמֶּכֶר קוֹבֵעַ דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. לָקַח הָאֶחָד פֵּרוֹת שֶׁהֶחֱלִיף לַאֲכִילָה וְלָקַח הָאַחֵר חֲלִיפֵיהֶן לְהַקְצוֹתָן. זֶה שֶׁלָּקַח לַאֲכִילָה חַיָּב לְעַשֵּׂר. וְזֶה שֶׁלָּקַח לְהַקְצוֹתָן לֹא נִקְבַּע לַמַּעֲשֵׂר:","הָאוֹמֵר לַחֲבֵרוֹ צֵא וְלַקֵּט לְךָ עֶשְׂרִים תְּאֵנִים מִשֶּׁלִּי וַאֲנִי אֲמַלֵּא אֶת כְּרֵסִי מִשֶּׁלְּךָ שְׁנֵיהֶם פְּטוּרִים שֶׁאֵין זֶה חֲלִיפִין כְּדֵי שֶׁיִּהְיֶה מֶכֶר. וְאִם צֵרֵף וְאָכַל חַיָּב:","וְהַמַּתָּנָה אֵינָהּ קוֹבַעַת כְּמֶכֶר. עַם הָאָרֶץ שֶׁהָיָה עוֹבֵר בַּשּׁוּק וְאָמַר טְלוּ לָכֶם תְּאֵנִים אוֹכְלִים וּפְטוּרִין שֶׁאֵין הַמַּתָּנָה קוֹבַעַת. וְאִם הִכְנִיסוּ לְבָתֵּיהֶן אִם רֹב הָעָם מַכְנִיסִים לַבָּתִּים מְעַשְּׂרִים וַדַּאי. וְאִם רֹב הָעָם מַכְנִיסִים לַשּׁוּק אֵין מְתַקְּנִים אֶלָּא דְּמַאי שֶׁמָּא עִשֵּׂר וְאַחַר כָּךְ הֵבִיא לַשּׁוּק. וְאִם אָמַר טְלוּ לָכֶם וְהַכְנִיסוּ לַבָּתִּים כְּשֶׁמַּכְנִיס לַבַּיִת מְעַשֵּׂר דְּמַאי. נָתַן לוֹ דָּבָר מְרֻבֶּה אֲפִלּוּ אָמַר לוֹ טֹל וֶאֱכל הֲרֵי זֶה כְּמִי שֶׁאָמַר לוֹ טֹל וְהַכְנֵס שֶׁאֵינוֹ אוֹכֵל עַד שֶׁיְּתַקֵּן דְּמַאי. וְכֵן אִם נָתַן לוֹ דָּבָר שֶׁאֵין דַּרְכּוֹ לְהֵאָכֵל חַי אוֹ שֶׁהָיָה אָדָם גָּדוֹל שֶׁאֵין דַּרְכּוֹ לֶאֱכל בַּשּׁוּק הֲרֵי זֶה מְתַקֵּן דְּמַאי:","הָיוּ שְׁנַיִם אָמַר לְאֶחָד טֹל וֶאֱכל וְאָמַר לְשֵׁנִי טֹל וְהַכְנֵס זֶה אוֹכֵל וּפָטוּר וְזֶה אוֹכֵל וְחַיָּב:","וְכֵן אֲנָשִׁים שֶׁהָיוּ יוֹשְׁבִים בַּשַּׁעַר אוֹ בַּחֲנוּת וְאָמַר לָהֶם טְלוּ וְאִכְלוּ הֲרֵי אֵלּוּ אוֹכְלִין וּפְטוּרִין. וּבַעַל הַשַּׁעַר אוֹ בַּעַל הַחֲנוּת לֹא יֹאכַל עַד שֶׁיְּעַשְּׂרוּ דְּמַאי. שֶׁנִּמְצָא כְּאוֹמֵר לְאֵלּוּ טְלוּ וְהַכְנִיסוּ לְבָתֵּיכֶם שֶׁהֲרֵי הֵם כְּבָתֵּיהֶם. וּכְבָר בֵּאַרְנוּ שֶׁאֵין הַבַּיִת שֶׁאֵינוֹ שֶׁלּוֹ קוֹבֵעַ לוֹ כְּשֶׁיַּעַבְרוּ הַפֵּרוֹת בְּתוֹכוֹ:","הַשּׂוֹכֵר אֶת הַפּוֹעֲלִים לַעֲשׂוֹת עִמּוֹ בְּפֵרוֹת בֵּין בִּתְלוּשִׁין בֵּין בִּמְחֻבָּרִין הוֹאִיל וְיֵשׁ לָהֶם לֶאֱכל מִן הַתּוֹרָה בְּמַה שֶּׁהֵן עוֹשִׂין הֲרֵי אֵלּוּ אוֹכְלִין וּפְטוּרִים מִן הַמַּעֲשֵׂר. וְאִם הִתְנָה עִמָּהֶן שֶׁיֹּאכְלוּ מַה שֶּׁלֹּא זָכְתָה לָהֶן תּוֹרָה כְּגוֹן שֶׁהִתְנָה עִמָּהֶן הַפּוֹעֵל שֶׁיֹּאכְלוּ בָּנָיו עִמּוֹ אוֹ שֶׁיֹּאכַל בְּנוֹ בִּשְׂכָרוֹ אוֹ שֶׁיֹּאכַל אַחַר גְּמַר מְלַאכְתּוֹ בְּתָלוּשׁ הֲרֵי זֶה אָסוּר לֶאֱכל עַד שֶׁיְּעַשֵּׂר הוֹאִיל וְאוֹכֵל מִפְּנֵי הַתְּנַאי הֲרֵי זֶה כְּלוֹקֵחַ:","שְׂכָרוֹ לְנַכֵּשׁ עִמּוֹ בְּזֵיתִים וְהִתְנָה הַפּוֹעֵל שֶׁיֹּאכַל בְּזֵיתִים הֲרֵי זֶה אוֹכֵל מִן הָאִילָן אַחַת אַחַת וּפָטוּר וְאִם צֵרֵף חַיָּב:","שְׂכָרוֹ לְנַכֵּשׁ בִּבְצָלִים וְהִתְנָה לֶאֱכל יָרָק מְקַרְסֵם עָלֶה עָלֶה וְאוֹכֵל וְאִם צֵרֵף חַיָּב. קָצַץ הַפּוֹעֵל שֶׁיֹּאכַל לִיטְרָא שֶׁל זֵיתִים אוֹכֵל אַחַת אַחַת וְאִם צֵרֵף חַיָּב לְעַשֵּׂר הוֹאִיל וְהוּא אוֹכֵל דָּבָר קָצוּב הֲרֵי זֶה כְּלוֹקֵחַ שֶׁאִם צֵרֵף נִקְבַּע. לֹא קִצֵּץ אֶלָּא הָיָה אוֹכֵל כְּדִין תּוֹרָה. מְצָרֵף וְאוֹכֵל כָּל מַה שֶּׁיִּרְצֶה וְהוּא שֶׁלֹּא יִסְפּוֹת בְּמֶלַח. אֲבָל אִם סָפַת בְּמֶלַח אַחַת אַחַת מֻתָּר שְׁתַּיִם שְׁתַּיִם אָסוּר שֶׁהֲרֵי נִקְבְּעוּ [בְּמֶלַח]:","פּוֹעֵל שֶׁהָיָה עוֹשֶׂה בִּלְבָסִין לֹא יֹאכַל בִּבְנוֹת שֶׁבַע. בִּבְנוֹת שֶׁבַע לֹא יֹאכַל בַּלְּבָסִין עַד שֶׁיְּעַשֵּׂר. אֲבָל יֵשׁ לוֹ לִמְנֹעַ עַצְמוֹ עַד שֶׁיַּגִּיעַ לִמְקוֹם הַיָּפוֹת:","הַמּוֹצִיא פּוֹעֲלִים לַעֲשׂוֹת לוֹ מְלָאכָה בַּשָּׂדֶה בִּזְמַן שֶׁאֵין לָהֶן עָלָיו מְזוֹנוֹת אוֹכְלִין מִפֵּרוֹת שֶׁבַּשָּׂדֶה וּפְטוּרִין מִן הַמַּעֲשֵׂר וְהוּא שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן. אֲבָל אִם יֵשׁ לָהֶן עָלָיו מְזוֹנוֹת לֹא יֹאכְלוּ וְאַף עַל פִּי שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן שֶׁאֵין פּוֹרְעִין חוֹב מִן הַטֶּבֶל. אֲבָל אוֹכְלִין אַחַת אַחַת מִן הַתְּאֵנָה אֲבָל לֹא מִן הַסַּל וְלֹא מִן הקֻפָּה וְלֹא מִן הַמֻּקְצֶה:","אֶחָד הַמְבַשֵּׁל וְאֶחָד הַשּׁוֹלֵק וְאֶחָד הַכּוֹבֵשׁ קוֹבֵעַ לְמַעֲשֵׂר. אֲבָל הַמְעַשֵּׁן אֶת הַפֵּרוֹת עַד שֶׁהִכְשִׁירָן הֲרֵי זֶה סָפֵק:","הַטּוֹמֵן פֵּרוֹת בַּאֲדָמָה אוֹ בַּתֶּבֶן אוֹ בַּזֶּבֶל עַד שֶׁהִכְשִׁירָן לַאֲכִילָה לֹא נִקְבְּעוּ לְמַעֲשֵׂר:","הַנּוֹתֵן יַיִן לְתַבְשִׁיל חַם אוֹ שֶׁנָּתַן שֶׁמֶן לִקְדֵרָה בְּאִלְפַס כְּשֶׁהֵן מְרֻתָּחִין נִקְבְּעוּ לְמַעֲשֵׂר. מָזַג יַיִן בְּמַיִם חַמִּים נִקְבַּע. וְאֵין צָרִיךְ לוֹמַר אִם בִּשֵּׁל הַיַּיִן וַאֲפִלּוּ בְּגַת שֶׁאָסוּר לִשְׁתּוֹת מִמֶּנּוּ עַד שֶׁיְּעַשֵּׂר:","הַשּׁוּם וְהַשַּׁחֲלִים וְהַחַרְדָּל שֶׁשְּׁחָקָן בַּשָּׂדֶה בְּשֶׁמֶן נִטְבְּלוּ לְמַעֲשֵׂר. וְכֵן הַסּוֹחֵט אֶשְׁכּוֹל לְתוֹךְ הַכּוֹס נִקְבַּע. לְתוֹךְ הַתַּמְחוּי אֵינוֹ נִקְבָּע:","הַמּוֹלֵחַ פֵּרוֹת בַּשָּׂדֶה נִקְבְּעוּ. טָבַל הַזֵּיתִים אֶחָד אֶחָד בְּמֶלַח וְאָכַל פָּטוּר. הַפּוֹצֵעַ זֵיתִים כְּדֵי שֶׁיֵּצֵא הַשָּׂרָף מֵהֶם פָּטוּר. הַנּוֹטֵל זֵיתִים מִן הַמַּעֲטָן טוֹבֵל אֶחָד אֶחָד בְּמֶלַח וְאוֹכֵל. וְאִם מָלַח וְנָתַן לְפָנָיו חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַתּוֹרֵם פֵּרוֹתָיו תְּרוּמָה שֶׁצָּרִיךְ לִתְרֹם אַחֲרֶיהָ שְׁנִיָּה נִקְבְּעוּ לְמַעֲשֵׂר. וְלֹא יֹאכַל מֵהֶן עַרְאַי עַד שֶׁיּוֹצִיא הַתְּרוּמָה הַשְּׁנִיָּה וִיעַשֵּׂר:","פֵּרוֹת שֶׁנִּגְמְרָה מְלַאכְתָּן וְחָשְׁכָה עֲלֵיהֶן לֵילֵי שַׁבָּת נִקְבְּעוּ וְלֹא יֹאכַל מֵהֶן אֲפִלּוּ לְאַחַר הַשַּׁבָּת עַד שֶׁיְּעַשֵּׂר:","תִּינוֹקוֹת שֶׁטָּמְנוּ תְּאֵנִים לְשַׁבָּת וְשָׁכְחוּ לְעַשְּׂרָן לֹא יֵאָכְלוּ לְמוֹצָאֵי שַׁבָּת עַד שֶׁיְּעַשְּׂרוּ:","תְּאֵנָה שֶׁהָיְתָה מְיֻחֶדֶת לוֹ לֶאֱכל פֵּרוֹתֶיהָ בְּשַׁבָּת וְלִקֵּט מִמֶּנָּה כַּלְכָּלָה לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר הוֹאִיל וּפֵרוֹת אֵלּוּ מְיֻחָדִין לְשַׁבָּת וְהַשַּׁבָּת קוֹבַעַת:","הָיָה אוֹכֵל בְּאֶשְׁכּוֹל וְחָשְׁכָה עָלָיו לֵילֵי שַׁבָּת לֹא יִגְמֹר אֲכִילָתוֹ בְּשַׁבָּת עַד שֶׁיְּעַשֵּׂר. וְאִם הִנִּיחָן לְאַחַר שַׁבָּת הֲרֵי זֶה גּוֹמְרוֹ:"],"Mishneh Torah, Transmission of the Oral Law 1":["אָז לֹא אֵבוֹשׁ, בְּהַבִּיטִי אֶל כָּל מִצְו‍ֹתֶיךָ:כָּל הַמִּצְווֹת שֶׁנִּתְּנוּ לוֹ לְמֹשֶׁה בְּסִינַי – בְּפֵרוּשָׁן נִתְּנוּ, שֶׁנֶּאֱמָר \"וְאֶתְּנָה לְךָ אֶת־לֻחֹת הָאֶבֶן, וְהַתּוֹרָה וְהַמִּצְוָה\" (שמות כד, יב): \"תּוֹרָה\", זוֹ תּוֹרָה שֶׁבִּכְתָב; וּ\"מִצְוָה\", זֶה פֵּרוּשָׁהּ. וְצִוָּנוּ לַעֲשׂוֹת הַתּוֹרָה, עַל פִּי הַמִּצְוָה. וּמִצְוָה זוֹ, הִיא הַנִּקְרֵאת תּוֹרָה שֶׁבְּעַל פֶּה."],"Mishneh Torah, Transmission of the Oral Law 20":["וּמִכְּלַל הַחֲכָמִים שֶׁקִּבְּלוּ מֵרָב הוּנָא וּמֵרָב יְהוּדָה, רַבָּה וְרָב יוֹסֵף. וּמִכְּלַל הַחֲכָמִים שֶׁקִּבְּלוּ מֵרַבָּה וְרָב יוֹסֵף, אַבַּיֵי וְרַבָּא; וּשְׁנֵיהֶם קִבְּלוּ גַּם מֵרָב נַחְמָן. וּמִכְּלַל הַחֲכָמִים שֶׁקִּבְּלוּ מֵרַבָּא, רָב אַשֵׁי וְרַבִּינָא; וּמָר בַּר רָב אַשֵׁי קִבַּל מֵאָבִיו וּמֵרַבִּינָא."],"Mishneh Torah, Transmission of the Oral Law 31":["אֵלָא מִתְקַבְּצִים יְחִידִים הַשְּׂרִידִים אֲשֶׁר ה' קוֹרֶא בְּכָל עִיר וְעִיר וּבְכָל מְדִינָה וּמְדִינָה, וְעוֹסְקִים בַּתּוֹרָה, וּמְבִינִים בְּחִבּוּרֵי הַחֲכָמִים כֻּלָּם, וְיוֹדְעִים מֵהֶם דֶּרֶךְ הַמִּשְׁפָּט הֵיאַךְ הוּא."],"Mishneh Torah, Transmission of the Oral Law 42":["עַד שֶׁיִּהְיוּ כָּל הַדִּינִין גְּלוּיִין לַקָּטָן וְלַגָּדוֹל בְּדִין כָּל מִצְוָה וּמִצְוָה, וּבְדִין כָּל הַדְּבָרִים שֶׁתִּקְּנוּ חֲכָמִים וּנְבִיאִים: כְּלָלוֹ שֶׁלַּדָּבָר, כְּדֵי שֶׁלֹּא יְהֶא אָדָם צָרִיךְ לְחִבּוּר אַחֵר בָּעוֹלָם בְּדִין מִדִּינֵי יִשְׂרָאֵל; אֵלָא יִהְיֶה חִבּוּר זֶה מְקַבֵּץ לְתוֹרָה שֶׁבְּעַל פֶּה כֻּלָּהּ, עִם הַתַּקָּנוֹת וְהַמִּנְהָגוֹת וְהַגְּזֵרוֹת שֶׁנַּעֲשׂוּ מִיְּמוֹת מֹשֶׁה רַבֵּנוּ וְעַד חִבּוּר הַתַּלְמוּד, וּכְמוֹ שֶׁפֵּרְשׁוּ לָנוּ הַגְּאוֹנִים בְּכָל חִבּוּרֵיהֶן, שֶׁחִבְּרוּ אַחַר הַתַּלְמוּד. לְפִיכָּךְ קָרָאתִי שֵׁם חִבּוּר זֶה מִשְׁנֵה תּוֹרָה – לְפִי שֶׁאָדָם קוֹרֶא תּוֹרָה שֶׁבִּכְתָב תְּחִלָּה, וְאַחַר כָּךְ קוֹרֶא בְּזֶה, וְיוֹדֵעַ מִמֶּנּוּ תּוֹרָה שֶׁבְּעַל פֶּה כֻּלָּהּ, וְאֵינוּ צָרִיךְ לִקְרוֹת סֵפֶר אַחֵר בֵּינֵיהֶם."],"Mishneh Torah, Trespass 4":["הַמַּפְרִישׁ מָעוֹת לְחַטָּאתוֹ לְעוֹלָתוֹ וּלַאֲשָׁמוֹ וּלְתוֹרִין וּבְנֵי יוֹנָה מוֹעֲלִין בָּהֶן מִשָּׁעָה שֶׁהִפְרִישׁ. הִפְרִישׁ לִשְׁלָמִים אֵין מוֹעֲלִין בָּהֶם:","הִקְדִּישׁ אֵיבָר אֶחָד לְדָמָיו לַמִּזְבֵּחַ. הֲרֵי זֶה סָפֵק אִם פָּשְׁטָה קְדֻשָּׁה בְּכֻלָּן אוֹ לֹא פָּשְׁטָה לְפִיכָךְ תִּקָּרֵב וְלֹא יִפָּדֶה. וְאִם נִפְדָּה אֵין מוֹעֲלִין בְּפִדְיוֹנוֹ:","הַמַּפְרִישׁ מָעוֹת לִנְזִירוּתוֹ אָסוּר לֵהָנוֹת בָּהֶן וְאִם נֶהֱנָה לֹא מָעַל מִפְּנֵי שֶׁהֵן רְאוּיִין לָבוֹא כֻּלָּם שְׁלָמִים וְאֵין בִּשְׁלָמִים מְעִילָה אֶלָּא בְּאֵימוּרֵיהֶן אַחַר זְרִיקַת דָּמִים. מֵת יִפְּלוּ לִנְדָבָה. הָיוּ מְפֹרָשִׁים דְּמֵי חַטָּאת יֵלְכוּ לְיָם הַמֶּלַח וְלֹא נֶהֱנִין וְלֹא מוֹעֲלִין. דְּמֵי עוֹלָה יָבִיאוּ עוֹלָה וּמוֹעֲלִין בָּהֶן. אָמַר אֵלּוּ לְחַטָּאתִי וְהַשְּׁאָר לִנְזִירוּתִי אִם נֶהֱנָה בְּכָל הַשְּׁאָר מָעַל נֶהֱנָה בְּמִקְצָתוֹ לֹא מָעַל. וְכֵן אִם אָמַר אֵלּוּ לְעוֹלָתִי וְהַשְּׁאָר לִנְזִירוּתִי וְנֶהֱנָה בְּכֻלָּן מָעַל נֶהֱנָה בְּמִקְצָתָן לֹא מָעַל שֶׁאֵין בִּדְמֵי שְׁלָמִים מְעִילָה. הִפְרִישׁ מָעוֹת וְאָמַר אֵלּוּ לְעוֹלָתִי וְאֵלּוּ לְחַטָּאתִי וְאֵלּוּ לִשְׁלָמִים וְנִתְעָרְבוּ מוֹעֲלִין בְּכֻלָּן וּמוֹעֲלִין בְּמִקְצָתָן. וְכֵיצַד יַעֲשֶׂה. יִקַּח שָׁלֹשׁ בְּהֵמוֹת וּמְחַלֵּל דְּמֵי חַטָּאת בְּכָל מָקוֹם שֶׁהוּא עַל הַחַטָּאת. וּדְמֵי עוֹלָה עַל הָעוֹלָה. וּדְמֵי שְׁלָמִים עַל שְׁלָמִים:","אֶחָד מִמְּחֻיְּבֵי קִינִין שֶׁהִפְרִישׁ מָעוֹת וְאָמַר אֵלּוּ לְחוֹבָתִי מוֹעֲלִין בְּכֻלָּן וּמוֹעֲלִין בְּמִקְצָתָן וְאִם מֵת יִפְּלוּ לִנְדָבָה כְּמוֹ שֶׁבֵּאַרְנוּ בִּנְזִירוּת וּמוֹעֲלִין בָּהֶן:","הַמַּפְרִישׁ חַטָּאת עַל אֲכִילַת חֵלֶב וֶהֱבִיאָהּ עַל אֲכִילַת דָּם הֲרֵי זֶה לֹא כִּפֵּר לְפִיכָךְ לֹא מָעַל. הִפְרִישׁ מָעוֹת לְחַטַּאת חֵלֶב וְקָנָהּ בָּהֶן חַטַּאת דָּם. בְּשׁוֹגֵג כִּפֵּר לְפִיכָךְ מָעַל. בְּמֵזִיד לֹא כִּפֵּר לְפִיכָךְ לֹא מָעַל:","הַמַּפְרִישׁ שְׁתֵּי סְלָעִים לְאָשָׁם וְלָקַח בָּהֶן שְׁנֵי אֵילִים לְחֻלִּין הוֹאִיל וְקָנָהּ חֻלִּין בִּדְמֵי אָשָׁם מָעַל. וְחַיָּב לְשַׁלֵּם עֲשָׂרָה דִּינָרִים שֶׁהֵן שְׁתֵּי סְלָעִים וְחֹמֶשׁ וְיָבִיא בָּהֶן אָשָׁם וְיָבִיא קָרְבַּן אָשָׁם עַל מְעִילָתוֹ. לְפִיכָךְ אִם הָיָה אֶחָד מִשְּׁנֵי הָאֵילִים שֶׁקָּנָה יָפֶה שְׁתֵּי סְלָעִים וְהַשֵּׁנִי יָפֶה עֲשָׂרָה דִּינָרִין יָבִיא הַשָּׁוֶה עֲשָׂרָה אָשָׁם תַּחַת הַמְּעִילָה עִם הַחֹמֶשׁ וְיָבִיא הַשָּׁוֶה שְׁתֵּי סְלָעִים אָשָׁם עַל מְעִילָתוֹ. לָקַח אֶחָד לְאָשָׁם וְאֶחָד לְחֻלִּין אִם הָיָה שֶׁל אָשָׁם יָפֶה שְׁתֵּי סְלָעִים יָבִיא אוֹתוֹ לַאֲשָׁמוֹ הָרִאשׁוֹן. וְכֵן אִם הָיָה זֶה הַחֻלִּין יָפֶה שְׁתַּיִם יָבִיא אוֹתוֹ אָשָׁם מְעִילָתוֹ שֶׁהֲרֵי מָעַל בְּסֶלַע אַחַת מִדְּמֵי הָאָשָׁם וִישַׁלֵּם חֲמִשָּׁה דִּינָרִים וְיִפְּלוּ לִנְדָבָה:","הַנֶּהֱנֶה מִדְּמֵי חַטָּאת עַד שֶׁלֹּא קָרְבָה חַטָּאתוֹ יוֹסִיף חֹמֶשׁ עַל מַה שֶּׁנֶּהֱנָה וְיָבִיא בְּדָמָיו חַטָּאתוֹ וְיָבִיא קָרְבַּן אָשָׁם עַל מְעִילָתוֹ. וְכֵן אִם נֶהֱנָה מִדְּמֵי אָשָׁם עַד שֶׁלֹּא קָרַב אֲשָׁמוֹ יוֹסִיף חֹמֶשׁ וְיָבִיא בְּדָמָיו אֲשָׁמוֹ וְיָבִיא אָשָׁם אַחֵר לִמְעִילָתוֹ. שֶׁקָּרְבְּנוֹת הַמִּזְבֵּחַ מְעִילָתָן לְקָרְבְּנוֹת הַמִּזְבֵּחַ וְקָדְשֵׁי בֶּדֶק הַבַּיִת מְעִילָתָן לְבֶדֶק הַבַּיִת. נוֹדַע לוֹ שֶׁמָּעַל וְאַחַר כָּךְ קָרְבָה חַטָּאתוֹ וַעֲדַיִן לֹא הִפְרִישׁ מְעִילָתוֹ אוֹ שֶׁהִפְרִישָׁהּ וְלֹא כְּלָלָהּ בִּדְמֵי חַטָּאתוֹ יוֹלִיךְ הַמְּעִילָה וְחֻמְשָׁהּ לְיָם הַמֶּלַח. נוֹדַע לוֹ שֶׁמָּעַל אַחַר שֶׁקָּרְבָה חַטָּאתוֹ יִפְּלוּ מְעוֹת הַמְּעִילָה וְחֻמְשָׁהּ לִנְדָבָה שֶׁאֵין מַפְרִישִׁין בַּתְּחִלָּה לְאִבּוּד. וּבֵין כָּךְ וּבֵין כָּךְ יָבִיא אֲשַׁם מְעִילָתוֹ. וּבְאָשָׁם בֵּין שֶׁנּוֹדַע לוֹ שֶׁמָּעַל קֹדֶם שֶׁקָּרַב אֲשָׁמוֹ אוֹ אַחַר שֶׁקָּרַב תִּפּל מְעִילָתוֹ וְחֻמְשָׁהּ לִנְדָבָה מִפְּנֵי שֶׁהוּא כְּמוֹתַר אָשָׁם וְיָבִיא אֲשַׁם מְעִילָתוֹ:","הַמּוֹכֵר עוֹלָתוֹ וּשְׁלָמָיו לֹא עָשָׂה כְּלוּם. וְדִין תּוֹרָה שֶׁיַּחְזְרוּ הַמָּעוֹת חֻלִּין כְּמוֹ שֶׁהָיוּ. וְקָנְסוּ אוֹתוֹ חֲכָמִים שֶׁיִּפְּלוּ הַמָּעוֹת לִנְדָבָה אֲפִלּוּ הָיְתָה הַבְּהֵמָה שָׁוָה אַרְבָּעָה וּמְכָרָהּ בַּחֲמִשָּׁה הַחֲמִשָּׁה כֻּלָּן יִפְּלוּ לִנְדָבָה וְאֵין כָּאן מְעִילָה לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים:","יֵשׁ מְעִילָה בִּנְדָרִים. כֵּיצַד. הָאוֹמֵר כִּכָּר זוֹ עָלַי קָרְבָּן אוֹ הֶקְדֵּשׁ וַאֲכָלָהּ מָעַל אַף עַל פִּי שֶׁהִיא מֻתֶּרֶת לַאֲחֵרִים. לְפִיכָךְ אֵין לָהּ פִּדְיוֹן שֶׁהֲרֵי אֵינָהּ קֹדֶשׁ אֶלָּא לָזֶה בִּלְבַד. אָמַר כִּכָּר זוֹ קֹדֶשׁ אוֹ קָרְבָּן וַאֲכָלָהּ בֵּין הוּא בֵּין אַחֵר מָעַל לְפִיכָךְ יֵשׁ לָהּ פִּדְיוֹן. הָיְתָה לְפָנָיו כִּכָּר שֶׁל הֶפְקֵר וְאָמַר כִּכָּר זוֹ הֶקְדֵּשׁ נְטָלָהּ עַל מְנָת לְאָכְלָהּ מָעַל לְפִי כֻּלָּהּ. עַל מְנָת לְהוֹרִישָׁהּ מָעַל לְפִי טוֹבַת הֲנָיָה שֶׁבָּהּ:","הָאוֹמֵר לַחֲבֵרוֹ כִּכָּרִי עָלֶיךָ הֶקְדֵּשׁ וְחָזַר וּנְתָנָהּ לוֹ. הַמְקַבֵּל מַתָּנָה זוֹ מָעַל לִכְשֶׁיּוֹצִיא. שֶׁהֲרֵי הַנּוֹתֵן אֵינָהּ אֲסוּרָה עָלָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִשְּׁאָר הַקּוֹנָמוֹת יֵשׁ בָּהֶן מְעִילָה לַנֶּאֱסָר בָּהֶן. וְכָל דְּבָרִים הַנֶּאֱסָרִין עָלָיו מִנֶּדֶר כָּזֶה מִצְטָרְפִין וְאִם נֶהֱנָה מִכֻּלָּם בִּשְׁוֵה פְּרוּטָה מָעַל:","הָאוֹמֵר הַנְּטִיעוֹת הָאֵלּוּ קָרְבָּן אִם אֵינָן נִקְצָצוֹת הַיּוֹם וְטַלִּית זֶה קָרְבָּן אִם לֹא תִּשָּׂרֵף הַיּוֹם. וְעָבַר הַיּוֹם וְלֹא נִקְצְצוּ וְלֹא נִשְׂרְפָה הַטַּלִּית. הֲרֵי הֵם הֶקְדֵּשׁ וְיִפָּדוּ כִּשְׁאָר הַהֶקְדֵּשׁוֹת וְאַחַר כָּךְ יֵהָנֶה בָּהֶן. אֲבָל אִם אָמַר הֲרֵי הַנְּטִיעוֹת הָאֵלּוּ קָרְבָּן עַד שֶׁיִּקָּצְצוּ אֵינוֹ יָכוֹל לִפְדּוֹתָן. שֶׁבְּכָל עֵת שֶׁיִּפָּדוּ יַחְזְרוּ הֶקְדֵּשׁ עַד שֶׁיִּקָּצְצוּ וְכֵיוָן שֶׁנִּקְצְצוּ אֵינָן צְרִיכִין פִּדְיוֹן אֶלָּא נֶהֱנִין בָּהֶן מִיָּד. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁפְּדָאָן הַמַּקְדִּישׁ. אֲבָל אִם פְּדָאָן אַחֵר הֲרֵי אֵלּוּ יוֹצְאִין לְחֻלִּין אַף עַל פִּי שֶׁעֲדַיִן לֹא נִקְצְצוּ וְיִהְיוּ מֻתָּרִין אַף לַמַּקְדִּישׁ:"],"Mishneh Torah, Vessels 16":["תַּנּוּר גָּדוֹל שְׁיָרָיו אַרְבָּעָה טְפָחִים וְהַקָּטָן שְׁיָרָיו רֻבּוֹ. כֵּיצַד. אִם נִשְׁבַּר בַּגָּדוֹל אַרְבָּעָה וּבַקָּטָן רֻבּוֹ מְקַבֵּל טֻמְאָה פָּחוֹת מִכָּאן אֵינוֹ מְקַבֵּל טֻמְאָה. וְכֵן אִם נִטְמָא וְנִתְּצוֹ עַד שֶׁשִּׁיֵּר בּוֹ פָּחוֹת מֵאַרְבָּעָה בַּגָּדוֹל אוֹ בְּפָחוֹת מֵרֹב בַּקָּטָן טָהוֹר. נִשְׁאַר בּוֹ אַרְבָּעָה אוֹ רֹב בַּקָּטָן עֲדַיִן הוּא בְּטֻמְאָתוֹ. וְהַכִּירָה שְׁיָרֶיהָ שָׁלֹשׁ אֶצְבָּעוֹת. הַכֻּפָּח שֶׁעֲשָׂאָהוּ לַאֲפִיָּה שִׁעוּרוֹ כְּתַנּוּר. לְבִשּׁוּל שִׁעוּרוֹ כְּכִירָה:","תַּנּוּר שֶׁנִּטְמָא וְלֹא רָצָה לְכַתְּתוֹ כֵּיצַד מְטַהֲרִין אוֹתוֹ. חוֹלְקוֹ לִשְׁלֹשָׁה חֲלָקִים וְגוֹרֵר אֶת הַטְּפֵלָה שֶׁעַל הַחֲרָסִים עַד שֶׁנִּמְצָא כָּל חֶרֶס מֵהֶן עוֹמֵד עַל הָאָרֶץ בְּלֹא טִיט עַל גַּבָּיו. חִלְּקוֹ לִשְׁנַיִם אֶחָד גָּדוֹל וְאֶחָד קָטָן הַגָּדוֹל טָמֵא וְהַקָּטָן טָהוֹר. חִלְּקוֹ לִשְׁנַיִם בְּשָׁוֶה כָּל אֶחָד מֵהֶן טָמֵא לְפִי שֶׁאִי אֶפְשָׁר לְכַוֵּן. אֲבָל טַבְלָא שֶׁל חֶרֶס שֶׁיֵּשׁ לָהּ דֹּפֶן שֶׁנֶּחְלְקָה לִשְׁנַיִם טְהוֹרָה. וְאִם הָיָה אֶחָד גָּדוֹל וְאֶחָד קָטָן הַגָּדוֹל טָמֵא:","תַּנּוּר שֶׁחִלְּקוֹ לִשְׁלֹשָׁה וְאֶחָד גָּדוֹל כִּשְׁנַיִם הַגָּדוֹל טָמֵא וְהַשְּׁנַיִם הַקְּטַנִּים טְהוֹרִין. חֲתָכוֹ חֻלְיוֹת לְרָחְבּוֹ אִם הָיָה גֹּבַהּ כָּל חֻלְיָא וְחֻלְיָא פָּחוֹת מֵאַרְבָּעָה טְפָחִים טָהוֹר. חָזַר וְסִדֵּר הַחֻלְיוֹת זוֹ עַל גַּבֵּי זוֹ וְהִמְרִיחַ עֲלֵיהֶם בְּטִיט וְהֶחֱזִירוֹ תַּנּוּר כְּשֶׁהָיָה הֲרֵי זוֹ כְּמוֹ שֶׁעָשָׂה תַּנּוּר אַחֵר וְאֵינוֹ מְקַבֵּל טֻמְאָה אֶלָּא מִכָּאן וּלְהַבָּא וְהוּא שֶׁיַּסִּיקֶנּוּ כְּדֵי לֶאֱפוֹת בּוֹ סֻפְגָּנִין אַחַר שֶׁמֵּרְחוֹ. הִרְחִיק מִמֶּנּוּ אֶת הַטְּפֵלָה וְנָתַן חוֹל אוֹ צְרוֹרוֹת בֵּין הַחֻלְיוֹת וּבֵין הַטְּפֵלָה אֵינוֹ מְקַבֵּל טֻמְאָה לְעוֹלָם וְזֶהוּ שֶׁאָמְרוּ הַנִּדָּה וְהַטְּהוֹרָה אוֹפוֹת בּוֹ וְהוּא טָהוֹר. הָיְתָה בּוֹ חֻלְיָא אַחַת שֶׁיֵּשׁ בָּהּ אַרְבָּעָה טְפָחִים הִיא מִתְטַמְּאָה בְּמַגָּע וְלֹא מִתְטַמֵּאת בַּאֲוִיר וּשְׁאָר הַחֻלְיוֹת טְהוֹרוֹת:","תַּנּוּר שֶׁבָּא מְחֻתָּךְ מִבֵּית הָאֻמָּן וְעָשָׂה לוֹ סְמוֹכִין שֶׁמְּקַבְּצִין אוֹתוֹ לִהְיוֹת כְּאֶחָד וּנְתָנָם עָלָיו וְהוּא טָהוֹר וְנִטְמָא כְּשֶׁיָּסִיר אֶת הַסּוֹמְכִין אוֹתוֹ יִטְהַר וַאֲפִלּוּ הֶחְזִירָן הֲרֵי הוּא טָהוֹר. מֵרְחוֹ בְּטִיט מְקַבֵּל טֻמְאָה לְהַבָּא וְאֵינוֹ צָרִיךְ לְהַסִּיקוֹ שֶׁכְּבָר הֻסַּק:","תַּנּוּר שֶׁחֲתָכוֹ חֻלְיוֹת וְנָתַן חוֹל בֵּין חֻלְיָא לְחֻלְיָא וְטָח בְּטִיט עַל הַכּל מִבַּחוּץ הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","יוֹרַת הָעַרְבִיִּים שֶׁהוּא חוֹפֵר בָּאָרֶץ וְטָח בְּטִיט אִם יוּכַל הַטִּיט לַעֲמֹד בִּפְנֵי עַצְמוֹ מְקַבֶּלֶת טֻמְאָה וְאִם לָאו טָהוֹר:","הַמֵּבִיא שִׁבְרֵי חֶרֶס וְדִבְּקָן זֶה בָּזֶה וַעֲשָׂאָן תַּנּוּר וְעָשָׂה לוֹ טְפֵלָה מִבַּיִת וּמִבַּחוּץ וְהִסִּיקוֹ הֲרֵי זֶה מְקַבֵּל טֻמְאָה אַף עַל פִּי שֶׁאֵין בְּכָל אֶחָד מֵהֶן כַּשִּׁעוּר:","פִּטָּם שֶׁקִּרְזְלוֹ וַעֲשָׂאַהוּ תַּנּוּר וְעָשָׂה לוֹ טְפֵלָה מִחוּץ אַף עַל פִּי שֶׁמְּקַבֵּל עַל דָּפְנוֹתָיו כַּשִּׁעוּר הֲרֵי זֶה טָהוֹר שֶׁכְּלִי חֶרֶס שֶׁטָּהַר אֵין לוֹ טֻמְאָה לְעוֹלָם אֶלָּא אִם כֵּן עֲשָׂאָהוּ תַּנּוּר וְעָשָׂה לוֹ טְפֵלָה מִבַּיִת וּמִבַּחוּץ:","תַּנּוּר שֶׁל סְדָקִין שֶׁעָשָׂה טְפֵלָה לְכָל אֶחָד וְאֶחָד וּמְקוֹם הַסְּדָקִין מְגֻלֶּה אֵינוֹ מְקַבֵּל טֻמְאָה. נָתַן טִיט אוֹ סִיד אוֹ גַּפְסִיס עַל גַּבֵּי הַסְּדָקִין הֲרֵי זֶה מִתְטַמֵּא. נָתַן עֲלֵיהֶן חַרְסִית אוֹ זֶפֶת וְגָפְרִית שַׁעֲוָה וּשְׁמָרִים בָּצֵק אוֹ גְּלָלִים טָהוֹר. זֶה הַכְּלָל דָּבָר שֶׁאֵין עוֹשִׂין מִמֶּנּוּ תַּנּוּר אֵינוֹ מְחַבֵּר אֶת הַסְּדָקִין:","סֶדֶק תַּנּוּר שֶׁנְּתָנוֹ כְּלַפֵּי זָוִית וּמֵרֵחַ בְּטִיט מִן הַצְּדָדִין טָהוֹר:","דַּף שֶׁל תַּנּוּר שֶׁנְּתָנוֹ בְּזָוִית לִהְיוֹת אוֹפֶה בּוֹ טָהוֹר. וְאִם יֵשׁ בּוֹ רֹב תַּנּוּר מְקַבֵּל טֻמְאָה:","תַּנּוּר שֶׁנָּתַן בּוֹ עָפָר עַד חֶצְיוֹ אִם נִטְמָא מֵאֲוִירוֹ בִּלְבַד אֵינוֹ מִתְטַמֵּא אֶלָּא מֵעָפָר וּלְמַעְלָה וְאִם נִטְמָא בְּמַגָּע וְנָגְעָה טֻמְאָה בּוֹ מִתּוֹכוֹ נִטְמָא כֻּלּוֹ אַף מֵעָפָר וּלְמַטָּה:","הַכִּירָה מְקוֹם שְׁפִיתַת שְׁתֵּי קְדֵרוֹת וְהַכֻּפָּח מְקוֹם שְׁפִיתַת קְדֵרָה אַחַת. לְפִיכָךְ כִּירָה שֶׁנֶּחְלְקָה לְאָרְכָּהּ טְהוֹרָה לְרָחְבָּהּ עֲדַיִן מְקַבֶּלֶת טֻמְאָה. הַכֻּפָּח שֶׁנֶּחְלַק בֵּין לְאָרְכּוֹ בֵּין לְרָחְבּוֹ טָהוֹר:","הַקְּלָתוֹת שֶׁל בַּעֲלֵי בָּתִּים שֶׁנִּפְחֲתָה קַרְקָעִיתָהּ אִם הָיָה עֹמֶק הַפְּחָת פָּחוֹת מִשְּׁלֹשָׁה טְפָחִים הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה שֶׁאִם יַסִּיק בַּפְּחָת מִלְּמַטָּה תִּתְבַּשֵּׁל הַקְּדֵרָה מִלְּמַעְלָה. הָיָה הַפְּחָת עָמֹק שְׁלֹשָׁה אוֹ יֶתֶר אֵינָהּ מְקַבֶּלֶת טֻמְאָה שֶׁהֲרֵי הָאֵשׁ רְחוֹקָה מִן הַקְּדֵרָה וְאֵינָהּ בְּשֵׁלָה. נָתַן אֶבֶן אוֹ צְרוֹר עַל פִּי הַפְּחָת עֲדַיִן הִיא בְּטָהֳרָתָהּ. מֵרְחוֹ בְּטִיט נַעֲשֵׂת הָאֶבֶן קַרְקַע הַכִּירָה וּמְקַבֶּלֶת טֻמְאָה מִכָּאן וּלְהַבָּא:"],"Mishneh Torah, Vessels 27":["שָׁלֹשׁ תֵּבוֹת הֵן. תֵּבָה שֶׁנִּפְחֲתָה מִצִּדָּהּ טְמֵאָה מִדְרָס. מִלְּמַעְלָה טְמֵאָה טְמֵא מֵת. וְהַבָּאָה בְּמִדָּה טְהוֹרָה מִכְּלוּם:","שָׁלֹשׁ עֲרֵבוֹת הֵן. עֲרֵבָה מִשְּׁנֵי לוֹגִין וְעַד תִּשְׁעָה קַבִּין שֶׁנִּסְדְּקָה טְמֵאָה מִדְרָס. שְׁלֵמָה טְמֵאָה טְמֵא מֵת. וְהַבָּאָה בְּמִדָּה טְהוֹרָה מִכְּלוּם:","שָׁלֹשׁ עֲגָלוֹת הֵן. הָעֲשׂוּיָה כְּקָתֵדְרָה טְמֵאָה מִדְרָס. כְּמִטָּה טְמֵאָה טְמֵא מֵת. וְשֶׁל אֲבָנִים טְהוֹרָה מִכְּלוּם:","שְׁלֹשָׁה תְּרִיסִין הֵן. תְּרִיס הַכָּפוּף טָמֵא מִדְרָס. וְשֶׁמְּשַׂחֲקִין בּוֹ בְּקֻמְפּוֹן טָמֵא טְמֵא מֵת. וְדִיצַת הָעַרְבִיִּים טְהוֹרָה מִכְּלוּם. לְפִי שֶׁהִיא עֲשׂוּיָה לְצוּרָה בִּלְבַד וְאֵינָהּ מִמְּשַׁמְּשֵׁי אָדָם וְכָל כְּלִי שֶׁאֵינוֹ מִמְּשַׁמְּשֵׁי אָדָם אֵינוֹ מְקַבֵּל טֻמְאָה כָּל עִקֵּר:","שְׁלֹשָׁה תַּרְבּוּסִין שֶׁל עוֹר הֵן. שֶׁל סְפָרִים טָמֵא מִדְרָס. וְשֶׁאוֹכְלִין עָלָיו טָמֵא טְמֵא מֵת. וְשֶׁשּׁוֹטְחִים עָלָיו אֶת הַזֵּיתִים טָהוֹר מִכְּלוּם לְפִי שֶׁאֵינוֹ מִמְּשַׁמְּשֵׁי אָדָם:","שְׁלֹשָׁה בְּסִיסָאוֹת הֵן. שֶׁלִּפְנֵי הַמִּטָּה וְשֶׁלִּפְנֵי הַסּוֹפְרִים טָמֵא מִדְרָס. שֶׁל שֻׁלְחָן טָמֵא טְמֵא מֵת. וְשֶׁל מִגְדָּל טָהוֹר מִכְּלוּם לְפִי שֶׁהוּא מִקְצָת מִגְדָּל וְצוּרָתוֹ מוֹכַחַת עָלָיו:","שָׁלֹשׁ מִטּוֹת הֵן. הָעֲשׂוּיָה לִשְׁכִיבָה טְמֵאָה מִדְרָס. וְשֶׁל זַגָּגִים שֶּׁנּוֹתְנִין בָּהּ כְּלֵי זְכוּכִית טְמֵאָה טֻמְאַת מֵת. וְשֶׁל סָרָגִין שֶׁמְּסָרְגִין עָלֶיהָ אֶת הַסְּבָכוֹת טְהוֹרָה מִכְּלוּם לְפִי שֶׁאֵינָהּ מִמְּשַׁמְּשֵׁי אָדָם:","שָׁלֹשׁ מִשְׁפָּלוֹת הֵן. שֶׁל זֶבֶל טְמֵאָה מִדְרָס. שֶׁל תֶּבֶן טְמֵאָה טְמֵא מֵת. וְהַפֻּחְלָץ שֶׁל גְּמַלִּים טָהוֹר מִכְּלוּם לְפִי שֶׁהַחֲבָלִים שֶׁלּוֹ קָשִׁים בְּיוֹתֵר וְעָבִים וְאֵינוֹ רָאוּי לְקַבֵּל תֶּבֶן וְכַיּוֹצֵא בּוֹ וְנִמְצָא שֶׁאֵין עָלָיו תּוֹרַת כְּלֵי אֶלָּא חֲבָלִים בִּלְבַד:","שְׁלֹשָׁה מַפָּצִין הֵן. הֶעָשׂוּי לִישִׁיבָה טָמֵא מִדְרָס. וְשֶׁל צַבָּעִים שֶׁמַּנִּיחִין בּוֹ אֶת הַכֵּלִים טָמֵא טְמֵא מֵת. וְשֶׁל גִּתּוֹת שֶׁנּוֹתְנִין עָלָיו עֲנָבִים וּמְחַפִּין בּוֹ טָהוֹר מִכְּלוּם לְפִי שֶׁאֵינוֹ מִמְּשַׁמְּשֵׁי אָדָם:","שָׁלֹשׁ חֲמָתוֹת הֵן וּשְׁלֹשָׁה תּוּרְמְלִין הֵן. הַמְקַבְּלִין כְּשִׁעוּר טְמֵאִין מִדְרָס. וְכַמָּה שִׁעוּרָן הַחֵמֶת אַרְבָּעָה קַבִּין וְהַתּוּרְמִיל חֲמִשָּׁה. וְשֶׁאֵינָן מְקַבְּלִין כְּשִׁעוּר טְמֵאִים טְמֵא מֵת. וְשֶׁל עוֹרוֹת הַדָּג טָהוֹר מִכְּלוּם:","שְׁלֹשָׁה עוֹרוֹת הֵן. הֶעָשׂוּי לְשָׁטִיחַ טְמֵא מִדְרָס. וְהֶעָשׂוּי לְתַכְרִיךְ כֵּלִים טָמֵא טְמֵא מֵת. וְשֶׁל רְצוּעוֹת וְשֶׁל סַנְדָּלִין טָהוֹר מִכְּלוּם לְפִי שֶׁאֵין עָלָיו צוּרַת כְּלִי:","שְׁלֹשָׁה סְדִינִין הֵן. הֶעָשׂוּי לִשְׁכִיבָה טָמֵא מִדְרָס. וְהֶעָשׂוּי לְפָרֹכֶת טָמֵא טְמֵא מֵת. וְשֶׁל צוּרוֹת שֶׁעוֹשִׂין אוֹתוֹ כְּדֵי שֶׁיִּתְלַמֵּד מִמֶּנּוּ הָרוֹקֵם טָהוֹר מִכְּלוּם לְפִי שֶׁאֵינוֹ מִמְּשַׁמְּשֵׁי אָדָם:","שָׁלֹשׁ מִטְפָּחוֹת הֵן. שֶׁל יָדַיִם טְמֵאָה מִדְרָס. וְשֶׁל סְפָרִים טְמֵאָה טְמֵא מֵת. וְשֶׁל תַּכְרִיכֵי הַמֵּת וְשֶׁל נִבְלֵי בְּנֵי לֵוִי טְהוֹרָה מִכְּלוּם לְפִי שֶׁאֵינָן מִמְּשַׁמְּשֵׁי אָדָם:","עוֹר הֶעָשׂוּי כְּמוֹ יָד שֶׁמַּכְנִיסִין בּוֹ הַיָּד וְהָאֶצְבָּעוֹת מִפְּנֵי הַצִּנָּה וְכַיּוֹצֵא בָּהֶן הוּא הַנִּקְרָא פְּרַקְלִינִין. וּשְׁלֹשָׁה פְּרַקְלִינִין הֵן. שֶׁל צַיָּדֵי חַיָּה וְעוֹף טָמֵא מִדְרָס שֶׁהֲרֵי נִשְׁעָן עָלָיו. וְשֶׁל חֲגָבִים טָמֵא טְמֵא מֵת שֶּׁנּוֹתְנִין בּוֹ הַחֲגָבִים. וְשֶׁל קַיָיצִים שֶׁבּוֹ מְקַיְּצִין פֵּרוֹת טָהוֹר מִכְּלוּם לְפִי שֶׁאֵינוֹ מִמְּשַׁמְּשֵׁי אָדָם:","שָׁלֹשׁ סְבָכוֹת הֵן. שֶׁל יַלְדָּה טְמֵאָה מִדְרָס. וְשֶׁל זְקֵנָה טְמֵאָה טְמֵא מֵת. וְשֶׁעוֹשִׂין לְשַׂחֵק בָּהּ לְשׁוֹתֵי שֵׁכָר טְהוֹרָה מִכְּלוּם לְפִי שֶׁאֵינָהּ מִמְּשַׁמְּשֵׁי אָדָם:","שְׁלֹשָׁה סַנְדָּלִין הֵן. שֶׁל אָדָם טָמֵא מִדְרָס. שֶׁל מַתָּכוֹת שֶׁל בְּהֵמָה טָמֵא טְמֵא מֵת. שֶׁל שַׁעַם וְשֶׁל צְפִירָה טְהוֹרָה מִכְּלוּם. כְּלָלוֹ שֶׁל דָּבָר כָּל כְּלִי שֶׁאֵינוֹ רָאוּי לְמִשְׁכָּב אוֹ לְמֶרְכָּב אוֹ שֶׁהוּא רָאוּי וְלֹא נַעֲשָׂה [לְכָךְ] אֶלָּא לִמְלָאכָה אַחֶרֶת הֲרֵי הוּא טָהוֹר מִן הַמִּדְרָס. נַעֲשָׂה לִמְלָאכָה אַחֶרֶת וּמְשַׁמֵּשׁ עִמָּהּ אֶת הַיְשִׁיבָה כְּגוֹן הַטַּלִּית וְהָרְדִיד מִתְטַמֵּא בְּמִדְרָס. וְכָל הַמִּתְטַמֵּא בְּמִדְרָס מִתְטַמֵּא בְּמֵת וְיֵשׁ מִתְטַמֵּא בְּמֵת וְאֵינוֹ מִתְטַמֵּא בְּמִדְרָס כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָל הַמִּתְטַמֵּא בְּמֵת מִתְטַמֵּא בִּשְׁאָר אֲבוֹת הַטֻּמְאוֹת בֵּין אָבוֹת שֶׁל תּוֹרָה בֵּין שֶׁל דִּבְרֵיהֶם וּמִתְטַמְּאִין בְּמַשְׁקִין:","שָׁלֹשׁ קֻפּוֹת הֵן. מְהוּהָה שֶׁטְּלָאָהּ עַל הַבְּרִיאָה הוֹלְכִין אַחַר הַבְּרִיאָה. קְטַנָּה עַל הַגְּדוֹלָה הוֹלְכִין אַחַר הַגְּדוֹלָה. הָיוּ שָׁווֹת הוֹלְכִין אַחַר הַפְּנִימִית. כֵּיצַד הוֹלְכִין אַחֲרֶיהָ. שֶׁאִם נִקְּבָה בְּמוֹצִיא רִמּוֹן שְׁתֵּיהֶן טְהוֹרוֹת:","שְׁלֹשָׁה פִּנְקָסוֹת הֵן. הָאַפִּיפְיוֹרִין שֶׁמַּנִּיחִין עָלָיו הַסְּפָרִים טְמֵא מִדְרָס. וְשֶׁיֵּשׁ בּוֹ בֵּית קִבּוּל שַׁעֲוָה טָמֵא טְמֵא מֵת. חִלְּקָהּ טְהוֹרָה מִכְּלוּם לְפִי שֶׁאֵין עָלָיו צוּרַת כְּלִי וְאֵינוֹ רָאוּי לְמִדְרָס:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 3":["זֶרַע לֵוִי כֻּלּוֹ מֻבְדָּל לַעֲבוֹדַת הַמִּקְדָּשׁ שֶׁנֶּאֱמַר (דברים י ח) \"בָּעֵת הַהִיא הִבְדִּיל ה' אֶת שֵׁבֶט הַלֵּוִי\". וּמִצְוַת עֲשֵׂה לִהְיוֹת הַלְוִיִּם פְּנוּיִין וּמוּכָנִין לַעֲבוֹדַת הַמִּקְדָּשׁ בֵּין רָצוּ בֵּין שֶׁלֹּא רָצוּ שֶׁנֶּאֱמַר (במדבר יח כג) \"וְעָבַד הַלֵּוִי הוּא אֶת עֲבֹדַת אֹהֶל מוֹעֵד\". וּבֶן לֵוִי שֶׁקִּבֵּל עָלָיו כָּל מִצְוֹת לְוִיָּה חוּץ מִדָּבָר אֶחָד אֵין מְקַבְּלִין אוֹתוֹ עַד שֶׁיְּקַבֵּל אֶת כֻּלָּן:","עֲבוֹדָה שֶׁלָּהֶן הִיא שֶׁיִּהְיוּ שׁוֹמְרִין אֶת הַמִּקְדָּשׁ. וְיִהְיוּ מֵהֶן שׁוֹעֲרִין לִפְתֹּחַ שַׁעֲרֵי הַמִּקְדָּשׁ וּלְהָגִיף דַּלְתוֹתָיו. וְיִהְיוּ מֵהֶן מְשׁוֹרְרִין לְשׁוֹרֵר עַל הַקָּרְבָּן בְּכָל יוֹם. שֶׁנֶּאֱמַר (דברים יח ז) \"וְשֵׁרֵת בְּשֵׁם ה' אֱלֹהָיו כְּכָל אֶחָיו הַלְוִיִּם\". אֵי זֶהוּ שֵׁרוּת שֶׁהוּא בְּשֵׁם ה' הֱוֵי אוֹמֵר זוֹ שִׁירָה. וּמָתַי אוֹמֵר שִׁירָה עַל כָּל עוֹלוֹת הַצִּבּוּר הַחוֹבָה וְעַל שַׁלְמֵי עֲצֶרֶת בְּעֵת נִסּוּךְ הַיַּיִן. אֲבָל עוֹלוֹת נְדָבָה שֶׁמַּקְרִיבִין הַצִּבּוּר לְקַיִץ לַמִּזְבֵּחַ. וְכֵן הַנְּסָכִין הַבָּאִין בִּפְנֵי עַצְמָן. אֵין אוֹמְרִין עֲלֵיהֶן שִׁירָה:","לֵוִי הָאוֹנֵן מֻתָּר לַעֲבֹד וּלְשׁוֹרֵר. וְאֵין פּוֹחֲתִין מִשְּׁנֵים עָשָׂר לְוִיִּם עוֹמְדִים עַל הַדּוּכָן בְּכָל יוֹם לוֹמַר שִׁירָה עַל הַקָּרְבָּן וּמוֹסִיפִין עַד לְעוֹלָם וְאֵין אוֹמְרִין שִׁירָה אֶלָּא בַּפֶּה בְּלֹא כְּלִי שֶׁעִקַּר הַשִּׁירָה שֶׁהִיא עֲבוֹדָתָם בַּפֶּה. וַאֲחֵרִים הָיוּ עוֹמְדִים שָׁם מְנַגְּנִין בִּכְלֵי שִׁיר. מֵהֶן לְוִיִּם וּמֵהֶן יִשְׂרְאֵלִים מְיֻחָסִין הַמַּשִּׂיאִין לִכְהֻנָּה. שֶׁאֵין עוֹלֶה עַל הַדּוּכָן אֶלָּא מְיֻחָס. וְאֵין אֵלּוּ הַמְשׁוֹרְרִים עַל פִּי הַכֵּלִים עוֹלִין לְמִנְיַן הַשְּׁנֵים עָשָׂר:","וּבַמֶּה הֵם מְנַגְּנִין. בִּנְבָלִים וַחֲלִילִים וְכִנּוֹרוֹת וַחֲצוֹצְרוֹת וְהַצִּלְצָל. וְאֵין פּוֹחֲתִין מִשְּׁנֵי נְבָלִים וְלֹא מוֹסִיפִין עַל שִׁשָּׁה. וְאֵין פּוֹחֲתִין מִשְּׁנֵי חֲלִילִים וְלֹא מוֹסִיפִין עַל שְׁנֵים עָשָׂר. וְאֵין פּוֹחֲתִין מִשְּׁתֵי חֲצוֹצְרוֹת וְלֹא מוֹסִיפִין עַל עֶשְׂרִים וּמֵאָה. וְאֵין פּוֹחֲתִין מִתִּשְׁעָה כִּנּוֹרוֹת וּמוֹסִיפִין עַד לְעוֹלָם. וְהַצִּלְצָל אֶחָד בִּלְבַד:","בִּימֵי הַמּוֹעֲדוֹת כֻּלָּם וּבְרָאשֵׁי חֳדָשִׁים הָיוּ הַכֹּהֲנִים תּוֹקְעִים בַּחֲצוֹצְרוֹת בִּשְׁעַת הַקָּרְבָּן וְהַלְוִיִּם אוֹמְרִין שִׁירָה שֶׁנֶּאֱמַר (במדבר י י) \"וּבְיוֹם שִׂמְחַתְכֶם וּבְמוֹעֲדֵיכֶם וּבְרָאשֵׁי חָדְשֵׁיכֶם וּתְקַעְתֶּם בַּחֲצֹצְרוֹת\". הַחֲצוֹצְרָה הָיְתָה נַעֲשֵׂית מִן עֶשֶׁת שֶׁל כֶּסֶף. עָשָׂה אוֹתָהּ מִן הַגְּרוּטָאוֹת שֶׁל כֶּסֶף כְּשֵׁרָה. מִשְּׁאָר מִינֵי מַתָּכוֹת פְּסוּלָה. וְהַחֲלִילִין שֶׁהָיוּ מְנַגְּנִין בָּהֶן הָיָה אַבּוּב שֶׁלָּהֶן שֶׁל קָנֶה. מִפְּנֵי שֶׁקּוֹלוֹ עָרֵב. וְלֹא הָיָה מְחַלֵּק אֶלָּא בְּאַבּוּב יְחִידִי מִפְּנֵי שֶׁהוּא מְחַלֵּק יָפֶה:","בִּשְׁנֵים עָשָׂר יוֹם בַּשָּׁנָה הֶחָלִיל מַכֶּה לִפְנֵי הַמִּזְבֵּחַ. בִּשְׁחִיטַת פֶּסַח רִאשׁוֹן. וּבִשְׁחִיטַת פֶּסַח שֵׁנִי. וּבְיוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח. וּבַיּוֹם הָרִאשׁוֹן שֶׁל עֲצֶרֶת. וּבִשְׁמוֹנָה יְמֵי הֶחָג. וְחָלִיל זֶה דּוֹחֶה שַׁבָּת מִפְּנֵי שֶׁהוּא חָלִיל שֶׁל קָרְבָּן וְחָלִיל שֶׁל קָרְבַּן עֲבוֹדָה הִיא וְדוֹחָה אֶת הַשַּׁבָּת:","אֵין בֶּן לֵוִי נִכְנַס לַעֲזָרָה לַעֲבוֹדָתוֹ עַד שֶׁיְּלַמְּדוּהוּ חָמֵשׁ שָׁנִים תְּחִלָּה. שֶׁנֶּאֱמַר (במדבר ח כד) \"זֹאת אֲשֶׁר לַלְוִיִּם מִבֶּן חָמֵשׁ וְעֶשְׂרִים שָׁנָה\" וְכָתוּב אֶחָד אוֹמֵר (במדבר ד ג) \"מִבֶּן שְׁלֹשִׁים שָׁנָה\". הָא כֵּיצַד. חָמֵשׁ לִלְמֹד. וְאֵינוֹ נִכְנָס לַעֲבוֹדָה עַד שֶׁיַּגְדִּיל וְיִהְיֶה (במדבר ד יט) (במדבר ד מט) אִישׁ שֶׁנֶּאֱמַר \"אִישׁ אִישׁ עַל עֲבֹדָתוֹ\":","זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה בַּלְוִיִּם (במדבר ח כה) \"וּמִבֶּן חֲמִשִּׁים שָׁנָה יָשׁוּב מִצְּבָא הָעֲבֹדָה\" אֵינוֹ אֶלָּא בִּזְמַן שֶׁהָיוּ נוֹשְׂאִין הַמִּקְדָּשׁ מִמָּקוֹם לְמָקוֹם. וְאֵינוֹ מִצְוָה נוֹהֶגֶת לְדוֹרוֹת. אֲבָל לְדוֹרוֹת אֵין הַלֵּוִי נִפְסָל בְּשָׁנִים וְלֹא בְּמוּמִין אֶלָּא בְּקוֹל שֶׁיִּתְקַלְקֵל קוֹלוֹ מֵרֹב הַזִּקְנָה יִפָּסֵל לַעֲבוֹדָתוֹ בַּמִּקְדָּשׁ. וְיֵרָאֶה לִי שֶׁאֵינוֹ נִפְסָל אֶלָּא לוֹמַר שִׁירָה אֲבָל יִהְיֶה מִן הַשּׁוֹעֲרִים:","שְׁמוּאֵל הָרוֹאֶה וְדָוִד הַמֶּלֶךְ חִלְּקוּ הַלְוִיִּם לְאַרְבָּעָה וְעֶשְׂרִים מִשְׁמָרוֹת. וְעוֹבֵד מִשְׁמָר בְּכָל שַׁבָּת. וְכָל אַנְשֵׁי מִשְׁמָר מְחַלֵּק אוֹתָם רֹאשׁ הַמִּשְׁמָר לְבָתֵּי אָבוֹת. וְכָל יוֹם מִימֵי הַשַּׁבָּת עוֹבְדִים בּוֹ אֲנָשִׁים יְדוּעִים. וְרָאשֵׁי הָאָבוֹת מְחַלְּקִין אֵלּוּ הָעוֹבְדִים בַּיּוֹם שֶׁלָּהֶן אִישׁ אִישׁ עַל עֲבוֹדָתוֹ. וְכָל הַלְוִיִּם מֻזְהָרִין עַל עֲבוֹדַת הַמִּזְבֵּחַ שֶׁנֶּאֱמַר (במדבר יח ג) \"אַךְ אֶל כְּלֵי הַקֹּדֶשׁ וְאֶל הַמִּזְבֵּחַ לֹא יִקְרָבוּ וְלֹא יָמֻתוּ\" לֹא יִקְרָבוּ לַעֲבוֹדָה אֲבָל לִגַּע מֻתָּרִין:","וּכְשֵׁם שֶׁהַלְוִיִּם מֻזְהָרִין שֶׁלֹּא לַעֲבֹד עֲבוֹדַת הַכֹּהֲנִים. כָּךְ הַכֹּהֲנִים מֻזְהָרִין שֶׁלֹּא לַעֲבֹד עֲבוֹדַת הַלְוִיִּם שֶׁנֶּאֱמַר (במדבר יח ג) \"גַם הֵם\" (במדבר יח ג) \"גַּם אַתֶּם\". וְכֵן הַלְוִיִּם עַצְמָם מֻזְהָרִים שֶׁלֹּא יַעֲשֶׂה אֶחָד מְלֶאכֶת חֲבֵרוֹ. שֶׁלֹּא יְסַיֵּעַ הַמְשׁוֹרֵר לַשּׁוֹעֵר וְלֹא הַשּׁוֹעֵר לַמְשׁוֹרֵר שֶׁנֶּאֱמַר (במדבר ד יט) \"אִישׁ אִישׁ עַל עֲבוֹדָתוֹ וְאֶל מַשָּׂאוֹ\":","לְוִיִּם שֶׁעָבְדוּ עֲבוֹדַת הַכֹּהֲנִים אוֹ שֶׁסִּיֵּעַ לֵוִי בִּמְלָאכָה שֶׁאֵינָהּ מְלַאכְתּוֹ חַיָּבִין מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (במדבר יח ג) \"וְלֹא יָמֻתוּ\". אֲבָל כֹּהֵן שֶׁעָבַד עֲבוֹדַת לֵוִי אֵינוֹ בְּמִיתָה אֶלָּא בְּלֹא תַּעֲשֶׂה:"],"Mishneh Torah, Vows 11":["קָטָן בֶּן שְׁתֵּים עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד וּקְטַנָּה בַּת אַחַת עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד שֶׁנִּשְׁבְּעוּ אוֹ נָדְרוּ בֵּין נִדְרֵי אִסָּר בֵּין נִדְרֵי הֶקְדֵּשׁ בּוֹדְקִין אוֹתָן וְשׁוֹאֲלִין אוֹתָן. אִם יוֹדְעִין לְשֵׁם מִי נָדְרוּ וּלְשֵׁם מִי הִקְדִּישׁוּ וְנִשְׁבְּעוּ נִדְרֵיהֶן קַיָּמִים וְהֶקְדֵּשָׁן הֶקְדֵּשׁ. וְאִם לֹא יָדְעוּ אֵין בְּנִדְרֵיהֶם וּבְדִבְרֵיהֶם כְּלוּם. וּצְרִיכִין בְּדִיקָה כָּל הַשָּׁנָה כֻּלָּהּ שֶׁהִיא שְׁנַת י\"ב לִקְטַנָּה. וּשְׁנַת י\"ג לְקָטָן:","כֵּיצַד. הֲרֵי שֶׁנָּדְרוּ אוֹ הִקְדִּישׁוּ בִּתְחִלַּת שָׁנָה זוֹ וְשָׁאֲלוּ אוֹתָן וְנִמְצְאוּ יוֹדְעִין וְנִתְקַיֵּם נִדְרָן וְנָדְרוּ נֵדֶר אַחֵר אֲפִלּוּ בְּסוֹף שָׁנָה זוֹ צְרִיכִין בְּדִיקָה וְאַחַר כָּךְ יִתְקַיֵּם. וְאֵין אוֹמְרִין הוֹאִיל וְנִמְצְאוּ יוֹדְעִין בִּתְחִלַּת הַשָּׁנָה אֵין צְרִיכִין בְּדִיקָה אֶלָּא בּוֹדְקִין אוֹתָן אֶת כָּל הַשָּׁנָה הַזּוֹ כֻּלָּהּ:","קֹדֶם הַזְּמַן הַזֶּה אַף עַל פִּי שֶׁאָמְרוּ יוֹדְעִין אָנוּ לְשֵׁם מִי נָדַרְנוּ וּלְשֵׁם מִי הִקְדַּשְׁנוּ אֵין נִדְרֵיהֶן נֵדֶר וְאֵין הֶקְדֵּשָׁן הֶקְדֵּשׁ. וְאַחַר הַזְּמַן הַזֶּה שֶׁנִּמְצָא הַבֵּן בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד וְהַבַּת בַּת י\"ב שָׁנָה וְיוֹם אֶחָד אַף עַל פִּי שֶׁאָמְרוּ אֵין אָנוּ יוֹדְעִין לְשֵׁם מִי נָדַרְנוּ וּלְשֵׁם מִי הִקְדַּשְׁנוּ דִּבְרֵיהֶן קַיָּמִין וְהֶקְדֵּשָׁן הֶקְדֵּשׁ וְנִדְרֵיהֶן נְדָרִים וְאַף עַל פִּי שֶׁלֹּא הֵבִיאוּ שְׁתֵּי שְׂעָרוֹת. וְזוֹ הִיא עוֹנַת נְדָרִים הָאֲמוּרָה בְּכָל מָקוֹם:","הוֹאִיל וְהִגִּיעוּ לִשְׁנֵי הַגְּדוֹלִים נִדְרֵיהֶן קַיָּמִין. אַף עַל פִּי שֶׁלֹּא הֵבִיאוּ סִימָנִין וַעֲדַיִן לֹא נַעֲשׂוּ גְּדוֹלִים לְכָל דָּבָר. וְדָבָר זֶה מִדִּבְרֵי תּוֹרָה שֶׁהַמֻּפְלָא הַסָּמוּךְ לְאִישׁ הֶקְדֵּשׁוֹ וְנִדְרוֹ נֵדֶר. אַף עַל פִּי שֶׁנִּדְרֵיהֶן קַיָּמִין אִם חִלְּלוּ נִדְרָן אוֹ נִשְׁבְּעוּ וְהֶחְלִיפוּ אֵינָן לוֹקִין עַד שֶׁיַּגְדִּילוּ וְיָבִיאוּ שְׁתֵּי שְׂעָרוֹת:","הִקְדִּישׁוּ וּבָא הַגָּדוֹל וְנֶהֱנָה מִן הַהֶקְדֵּשׁ שֶׁהִקְדִּישׁוּ לוֹקֶה מִשּׁוּם שֶׁנִּדְרֵיהֶם נְדָרִים מִן הַתּוֹרָה כְּמוֹ שֶׁבֵּאַרְנוּ:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁבַּת י\"ב שָׁנָה וְיוֹם אֶחָד נְדָרֶיהָ קַיָּמִין. בְּשֶׁלֹּא הָיְתָה בִּרְשׁוּת הָאָב אוֹ בִּרְשׁוּת הַבַּעַל. אֲבָל אִם הָיְתָה בִּרְשׁוּת הָאָב אֲפִלּוּ הִגְדִּילָה וַהֲרֵי הִיא נַעֲרָה. אָבִיהָ מֵפֵר כָּל נְדָרֶיהָ וְכָל שְׁבוּעוֹת שֶׁתִּשָּׁבַע בְּיוֹם שָׁמְעוֹ שֶׁנֶּאֱמַר (במדבר ל ו) \"כָּל נְדָרֶיהָ וֶאֱסָרֶיהָ\" וְגוֹ' (במדבר ל ו) \"כִּי הֵנִיא אָבִיהָ אֹתָהּ\" וְגוֹ':","וְעַד מָתַי אָבִיהָ מֵפֵר עַד שֶׁתִּבְגַּר. בָּגְרָה אֵינוֹ מֵפֵר לָהּ וַהֲרֵי כָּל נְדָרֶיהָ וּשְׁבוּעוֹתֶיהָ כְּנֵדֶר אַלְמָנָה וּגְרוּשָׁה שֶׁנֶּאֱמַר בָּהֶן (במדבר ל י) \"כּל אֲשֶׁר אָסְרָה עַל נַפְשָׁהּ\" וְגוֹ':","וּמֵאֵימָתַי מֵפֵר הַבַּעַל נִדְרֵי אִשְׁתּוֹ וּשְׁבוּעוֹתֶיהָ מִשֶּׁתִּכָּנֵס לַחֻפָּה. וְהוּא מֵפֵר לְעוֹלָם עַד שֶׁיְּגָרְשֶׁנָּה וְיַגִּיעַ הַגֵּט לְיָדָהּ. הָיְתָה מְגֹרֶשֶׁת מִסָּפֵק לֹא יָפֵר לָהּ. נָתַן לָהּ גֵּט עַל תְּנַאי אוֹ לְאַחַר זְמַן לֹא יָפֵר בַּיָּמִים שֶׁבֵּינְתַיִם. וְכֵן מִי שֶׁשָּׁמְעָה שֶׁמֵּת בַּעְלָהּ וְנִשֵּׂאת וַהֲרֵי בַּעְלָהּ קַיָּם וְכַיּוֹצֵא בָּהּ אֵין הַבַּעַל הָרִאשׁוֹן וְלֹא הָאַחֲרוֹן מְפֵרִין נְדָרֶיהָ. הָיְתָה מֵחַיָּבֵי לָאוִין וְאֵין צָרִיךְ לוֹמַר מֵחַיָּבֵי עֲשֵׂה וְהֵפֵר נְדָרֶיהָ הֲרֵי אֵלּוּ מוּפָרִין:","נַעֲרָה מְאֹרָסָה אֵין מֵפֵר נְדָרֶיהָ אֶלָּא הָאָב עִם הַבַּעַל כְּאַחַד. וְאִם הֵפֵר הָאֶחָד לְבַדּוֹ אֵינוֹ מוּפָר. הֵפֵר הַבַּעַל לְבַדּוֹ וְעָבְרָה עַל נִדְרָהּ קֹדֶם שֶׁיָּפֵר הָאָב אֵינָהּ לוֹקָה:","מֵת הָאָרוּס חָזְרָה לִרְשׁוּת אָבִיהָ. וְכָל שֶׁתִּדֹּר הָאָב מֵפֵר כְּשֶׁהָיָה קֹדֶם שֶׁתִּתְאָרֵס. מֵת הָאָב אַחַר שֶׁנִּתְאָרְסָה וְנָדְרָה אַחַר מוֹתוֹ אֵין הַבַּעַל מֵפֵר שֶׁאֵין הַבַּעַל מֵפֵר נִדְרֵי אִשְׁתּוֹ עַד שֶׁתִּכָּנֵס לַחֻפָּה:","נַעֲרָה אֲרוּסָה שֶׁנָּדְרָה וְשָׁמַע אָבִיהָ וְלֹא שָׁמַע אֲרוּסָהּ וְנִתְגָרְשָׁה בּוֹ בַּיּוֹם וְנִתְאָרְסָה לְאַחֵר בּוֹ בַּיּוֹם אֲפִלּוּ לְמֵאָה אָבִיהָ וּבַעְלָהּ הָאַחֲרוֹן מְפֵרִין נְדָרֶיהָ שֶׁנָּדְרָה בִּפְנֵי אָרוּס רִאשׁוֹן. מִפְּנֵי שֶׁלֹּא יָצָאתָה לִרְשׁוּת עַצְמָהּ שָׁעָה אַחַת שֶׁעֲדַיִן הִיא בִּרְשׁוּת הָאָב מִפְּנֵי שֶׁהִיא נַעֲרָה:","אֲבָל הָאִשָּׁה הַנְּשׂוּאָה שֶׁנָּדְרָה וְלֹא הֵפֵר לָהּ בַּעְלָהּ וְגֵרְשָׁהּ בּוֹ בַּיּוֹם וְהֶחֱזִירָהּ בּוֹ בַּיּוֹם אֵינוֹ יָכוֹל לְהָפֵר שֶׁהֲרֵי יָצָאתָה לִרְשׁוּת עַצְמָהּ אַחַר שֶׁנָּדְרָה. אַף עַל פִּי שֶׁנָּדְרָה בִּרְשׁוּתוֹ וְהִיא עַתָּה בִּרְשׁוּתוֹ הוֹאִיל וְיָצְתָה בִּרְשׁוּת עַצְמָהּ בֵּינְתַיִם נִתְקַיְּמוּ נְדָרֶיהָ:","נַעֲרָה מְאֹרָסָה שֶׁנָּדְרָה וְלֹא שָׁמַע אָבִיהָ וְלֹא בַּעְלָהּ וְנִתְגָרְשָׁה וְנִתְאָרְסָה לַאֲחֵרִים. אֲפִלּוּ לְאַחַר כַּמָּה יָמִים כְּשֶׁיִּשְׁמַע הָאָב וְהַבַּעַל הָאַחֲרוֹן מְפֵרִין נְדָרֶיהָ שֶׁנָּדְרָה בִּפְנֵי אָרוּס הָרִאשׁוֹן הוֹאִיל וְלֹא שָׁמַע אוֹתָם הָאָרוּס הָרִאשׁוֹן:","נַעֲרָה מְאֹרָסָה שֶׁנָּדְרָה וְשָׁמַע אָבִיהָ לְבַדּוֹ וְהֵפֵר לָהּ וּמֵת הָאָרוּס קֹדֶם שֶׁיִּשְׁמַע וְנִתְאָרְסָה בּוֹ בַּיּוֹם אֲפִלּוּ לְמֵאָה אָבִיהָ וַאֲרוּסָהּ הָאַחֲרוֹן מְפֵרִין נְדָרֶיהָ שֶׁנָּדְרָה בִּפְנֵי אָרוּס רִאשׁוֹן שֶׁמֵּת קֹדֶם שֶׁיִּשְׁמַע:","שָׁמַע אָרוּס רִאשׁוֹן וְהֵפֵר וּמֵת וְאַחַר כָּךְ שָׁמַע הָאָב וְנִתְאָרְסָה לְאַחֵר בּוֹ בַּיּוֹם אָבִיהָ עִם הָאָרוּס הָאַחֲרוֹן מְפֵרִין נְדָרֶיהָ:","שָׁמַע אָבִיהָ וְלֹא שָׁמַע הָאָרוּס וּמֵת בּוֹ בַּיּוֹם הָאָרוּס אוֹ שֶׁשָּׁמַע גַּם הָאָרוּס וְהֵפֵר אוֹ שֶׁשָּׁתַק וּמֵת בּוֹ בַּיּוֹם נִתְרוֹקְנָה רְשׁוּת לָאָב וְהָאָב יָכוֹל לְהָפֵר. שָׁמַע הָאָרוּס וְקִיֵּם וּמֵת בּוֹ בַּיּוֹם אוֹ שֶׁשָּׁמַע וְשָׁתַק וּמֵת בַּיּוֹם שֶׁלְּאַחֲרָיו אֵין הָאָב יָכוֹל לְהָפֵר:","גֵּרְשָׁהּ הָאָרוּס אַחַר שֶׁשָּׁמַע. הֲרֵי זֶה סָפֵק אִם הַגֵּרוּשִׁין כִּשְׁתִיקָה וְיָפֵר הָאָב עִם הַבַּעַל הָאַחֲרוֹן שֶׁיְּאָרֵס בּוֹ בַּיּוֹם אוֹ הַגֵּרוּשִׁין כְּמוֹ שֶׁקִּיֵּם אָרוּס רִאשׁוֹן שֶׁכְּבָר נִתְקַיְּמוּ הַנְּדָרִים:","שָׁמַע הָאָב וְהֵפֵר לָהּ וּמֵת הָאָב וְאַחַר כָּךְ שָׁמַע הַבַּעַל אֲפִלּוּ שָׁמַע הַבַּעַל קֹדֶם שֶׁיָּמוּת הָאָב לֹא נִתְרוֹקְנָה רְשׁוּת לַבַּעַל וְאֵינוֹ יָכוֹל לְהָפֵר לְעוֹלָם אַחַר מוֹת הָאָב. שֶׁאֵין הָאָרוּס מֵפֵר אֶלָּא בְּשֻׁתָּפוּת:","שָׁמַע אָרוּס וְהֵפֵר לָהּ וּמֵת וְאַחַר כָּךְ שָׁמַע הָאָב. אוֹ שֶׁשָּׁמַע הָאָב וְהֵפֵר לָהּ וּמֵת הַבַּעַל קֹדֶם שֶׁיִּשְׁמַע. אֵין הָאָב לְבַדּוֹ יָכוֹל לְהָפֵר נְדָרִים אֵלּוּ שֶׁנִּרְאוּ לְאָרוּס רִאשׁוֹן אֶלָּא בְּשֻׁתָּפוּת אָרוּס הָאַחֲרוֹן אִם נִתְאָרְסָה בּוֹ בַּיּוֹם כְּמוֹ שֶׁבֵּאַרְנוּ:","נָדְרָה וְהֵפֵר לָהּ אָבִיהָ לְבַדּוֹ וְלֹא שָׁמַע הָאָרוּס עַד שֶׁנִּכְנְסָה לִרְשׁוּתוֹ אֵינוֹ יָכוֹל לְהָפֵר שֶׁאֵין הַבַּעַל מֵפֵר נִדְרֵי אֲרוּסָתוֹ אַחַר שֶׁנִּשֵּׂאת אֶלָּא קֹדֶם שֶׁתִּכָּנֵס לִרְשׁוּתוֹ הוּא שֶׁמֵּפֵר בְּשֻׁתָּפוּת הָאָב. לְפִיכָךְ הָיָה דֶּרֶךְ תַּלְמִידֵי חֲכָמִים עַד שֶׁלֹּא תֵּצֵא בִּתּוֹ מֵרְשׁוּתוֹ אוֹמֵר לָהּ כָּל נְדָרִים שֶׁנָּדַרְתְּ בְּתוֹךְ בֵּיתִי הֲרֵי הֵן מוּפָרִין:","וְכֵן הַבַּעַל עַד שֶׁלֹּא תִּכָּנֵס לִרְשׁוּתוֹ אוֹמֵר לָהּ כָּל נְדָרִים שֶׁנָּדַרְתְּ מִשֶּׁאֵרַסְתִּיךְ עַד שֶׁלֹּא תִּכָּנְסִי בְּתוֹךְ בֵּיתִי הֲרֵי הֵן מוּפָרִין שֶׁהַבַּעַל מֵפֵר נִדְרֵי אִשְׁתּוֹ אַף עַל פִּי שֶׁלֹּא שָׁמַע אוֹתָם:","הָלַךְ הָאָב עִם שְׁלוּחֵי הַבַּעַל אוֹ שֶׁהָלְכוּ שְׁלוּחֵי הָאָב עִם שְׁלוּחֵי הַבַּעַל עֲדַיִן אָבִיהָ וּבַעְלָהּ מְפֵרִין נְדָרֶיהָ. מָסַר הָאָב לִשְׁלוּחֵי הַבַּעַל אוֹ שֶׁמָּסְרוּ שְׁלוּחֵי הָאָב לִשְׁלוּחֵי הַבַּעַל אֵין הָאָב יָכוֹל לְהָפֵר שֶׁהֲרֵי יָצָאת מֵרְשׁוּתוֹ וְלֹא הַבַּעַל יָכוֹל לְהָפֵר שֶׁאֵין הַבַּעַל מֵפֵר בְּקוֹדְמִין כְּמוֹ שֶׁבֵּאַרְנוּ:","שׁוֹמֶרֶת יָבָם אֲפִלּוּ עָשָׂה בָּהּ יְבָמָהּ מַאֲמָר וַאֲפִלּוּ יָבָם אֶחָד לִיבָמָה אַחַת אֵינוֹ מֵפֵר נִדְרֵי יְבִמְתּוֹ עַד שֶׁיָּבוֹא עָלֶיהָ:","הָיְתָה יְבִמְתּוֹ נַעֲרָה מְאֹרָסָה לְאָחִיו וְאָבִיהָ קַיָּם אֵין הַיָּבָם וְאָבִיהָ מְפֵרִים נְדָרֶיהָ כְּאַחַת אֶלָּא הָאָב לְבַדּוֹ הוּא שֶׁמֵּפֵר כָּל שֶׁתִּדֹּר וַאֲפִלּוּ עָשָׂה בָּהּ הַיָּבָם מַאֲמָר אֵינָהּ כְּנַעֲרָה מְאֹרָסָה. שֶׁאֵין הַמַּאֲמָר קוֹנֶה בִּיבָמָה קִנְיָן גָּמוּר כְּמוֹ שֶׁבֵּאַרְנוּ:","נַעֲרָה שֶׁהִשִּׂיאָהּ אָבִיהָ וְנִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה מִן הַנִּשּׂוּאִין הֲרֵי זוֹ כִּיתוֹמָה בְּחַיֵּי הָאָב. וְאֵין אָבִיהָ מֵפֵר נְדָרֶיהָ וְאַף עַל פִּי שֶׁעֲדַיִן הִיא נַעֲרָה:","נַעֲרָה מְאֹרָסָה שֶׁנָּדְרָה וְלֹא שָׁמְעוּ נְדָרֶיהָ אָבִיהָ וּבַעְלָהּ עַד שֶׁבָּגְרָה אוֹ עַד שֶׁנַּעֲשֵׂית יְתוֹמָה בְּחַיֵּי הָאָב הֲרֵי נְדָרֶיהָ קַיָּמִים וְאֵין הַבַּעַל יָכוֹל לְהָפֵר שֶׁהֲרֵי יָצָאת מֵרְשׁוּת אָבִיהָ שֶׁהוּא מֵפֵר עִמּוֹ בְּשֻׁתָּפוּת וַעֲדַיִן לֹא נִכְנְסָה לִרְשׁוּת הַבַּעַל:"],"Mishneh Torah, Woman Suspected of Infidelity 2":["אִשָׁה שֶׁקִּנֵּא לָהּ וְנִסְתְּרָה אֵין כּוֹפִין אוֹתָהּ לִשְׁתּוֹת. אֶלָּא אִם רָצְתָה וְאָמְרָה הֵן נִטְמֵאתִי תֵּצֵא בְּלֹא כְּתֻבָּה וְנֶאֶסְרָה עַל בַּעְלָהּ לְעוֹלָם וְאֵינָהּ שׁוֹתָה. וְכֵן אִם אָמְרָה אֵינִי טְמֵאָה וְאֵינִי שׁוֹתָה אֵין כּוֹפִין אוֹתָהּ לִשְׁתּוֹת וְתֵצֵא בְּלֹא כְּתֻבָּה. וְכֵן אִם אָמַר בַּעְלָהּ אֵינִי רוֹצֶה לְהַשְׁקוֹתָהּ אוֹ שֶׁבְּעָלָהּ בַּעְלָהּ אַחַר שֶׁנִּסְתְּרָה הֲרֵי זוֹ אֵינָהּ שׁוֹתָה וְנוֹטֶלֶת כְּתֻבָּתָהּ וְיוֹצְאָה וְהִיא אֲסוּרָה [עָלָיו] לְעוֹלָם:","וְאֵלּוּ הֵן הַנָּשִׁים שֶׁאֵינָן רְאוּיוֹת לִשְׁתּוֹת אַף עַל פִּי שֶׁהֵן רוֹצוֹת לִשְׁתּוֹת וּבַעְלֵיהֶן רוֹצִים לְהַשְׁקוֹתָן אֶלָּא יוֹצְאוֹת בְּלֹא כְּתֻבָּה מִשֶּׁיָּבוֹאוּ עֵדֵי סְתִירָה אַחַר עֵדֵי קִנּוּי וְיֵאָסְרוּ עַל בַּעְלֵיהֶן לְעוֹלָם. וַחֲמֵשׁ עֶשְׂרֵה נָשִׁים הֵן. וְאֵלּוּ הֵן. אֲרוּסָה. וְשׁוֹמֶרֶת יָבָם. וּקְטַנָּה אֵשֶׁת הַגָּדוֹל. וּגְדוֹלָה אֵשֶׁת הַקָּטָן. וְאֵשֶׁת אַנְדְּרוֹגִינוּס. וְאֵשֶׁת הַסּוּמָא. וְאֵשֶׁת הַחִגֵּר אוֹ הָאִלֵּם. אוֹ מִי שֶׁאֵינוֹ שׁוֹמֵעַ. אוֹ שֶׁהוּא כְּרוּת יָד. וְכֵן הַחִגֶּרֶת. וְהָאִלֶּמֶת. וְהַסּוּמָא. וּכְרוּתַת יָד. וְשֶׁאֵינָהּ שׁוֹמַעַת. כָּל אַחַת מֵאֵלּוּ אֵינָהּ רְאוּיָה לִשְׁתּוֹת:","וּמִנַּיִן שֶׁאֵינָהּ רְאוּיָה לִשְׁתּוֹת שֶׁנֶּאֱמַר (במדבר ה כט) \"אֲשֶׁר תִּשְׂטֶה אִשָּׁה תַּחַת אִישָׁהּ\". תַּחַת פְּרָט לַאֲרוּסָה וְשׁוֹמֶרֶת יָבָם שֶׁאֵינָהּ תַּחַת אִישָׁהּ. אִשָּׁה פְּרָט לִקְטַנָּה. תַּחַת אִישָׁהּ פְּרָט לְאֵשֶׁת קָטָן וְאֵשֶׁת אַנְדְּרוֹגִינוּס שֶׁאֵינוֹ אִישׁ. (במדבר ה יג) \"וְנֶעֱלָם מֵעֵינֵי אִישָׁהּ\" פְּרָט לְאֵשֶׁת סוּמָא. (במדבר ה יח) \"וְהֶעֱמִיד הַכֹּהֵן אֶת הָאִשָּׁה\" פְּרָט לְחִגֶּרֶת. (במדבר ה יח) \"וְנָתַן עַל כַּפֶּיהָ\" פְּרָט לְמִי שֶׁאֵין לָהּ כַּף אוֹ שֶׁהָיְתָה עֲקֻמָּה אוֹ יְבֵשָׁה שֶׁאֵינָהּ יְכוֹלָה לִקַּח בָּהּ. וַאֲפִלּוּ כַּפָּהּ אַחַת שֶׁנֶּאֱמַר כַּפֶּיהָ. וְאָמְרָה הָאִשָּׁה פְּרָט לְאִלֶּמֶת. (במדבר ה יט) \"וְאָמַר אֶל הָאִשָּׁה\" פְּרָט לְמִי שֶׁאֵינָהּ שׁוֹמַעַת. וַהֲרֵי הוּא אוֹמֵר אֲשֶׁר תִּשְׂטֶה אִשָּׁה תַּחַת אִישָׁהּ עַד שֶׁתִּהְיֶה שְׁלֵמָה כָּמוֹהוּ וְהוּא שָׁלֵם כְּמוֹתָהּ. הָא לָמַדְתָּ שֶׁכָּל דָּבָר שֶׁמְּעַכֵּב אוֹתָהּ מִלִּשְׁתּוֹת מְעַכֵּב אֶת בַּעְלָהּ מִלְּהַשְׁקוֹתָהּ. וְכָל הַמְעַכֵּב אֶת הַבַּעַל מִלְּהַשְׁקוֹתָהּ מוּם כָּמוֹהוּ מְעַכֵּב אוֹתָהּ מִלִּשְׁתּוֹת:","קְטַנָּה שֶׁהִשִּׂיאָהּ אָבִיהָ אִם זִנְּתָה בִּרְצוֹנָהּ נֶאֶסְרָה עַל בַּעְלָהּ. לְפִיכָךְ מְקַנִּין לָהּ לֹא לְהַשְׁקוֹתָהּ אֶלָּא לְפָסְלָהּ מִכְּתֻבָּתָהּ כְּמוֹ שֶׁאָמַרְנוּ. אֲבָל קְטַנָּה בַּת מֵאוּן אֵין מְקַנִּין לָהּ שֶׁאֵין לָהּ רָצוֹן לְהֵאָסֵר עַל בַּעְלָהּ. וַאֲפִלּוּ הָיָה כֹּהֵן לֹא נֶאֶסְרָה עָלָיו:","קִנֵּא לַאֲרוּסָתוֹ אוֹ לִזְקוּקָתוֹ וְנִסְתְּרָה אַחַר שֶׁנִּשְּׂאָה הֲרֵי זוֹ שׁוֹתָה כִּשְׁאָר כָּל הַנָּשִׁים. נְשׂוּאָה שֶׁקִּנֵּא לָהּ וְנִסְתְּרָה קֹדֶם שֶׁיִּבְעל אוֹתָהּ בַּעְלָהּ אֵינָהּ שׁוֹתָה וְיוֹצְאָה בְּלֹא כְּתֻבָּה וַאֲסוּרָה עָלָיו לְעוֹלָם שֶׁנֶּאֱמַר (במדבר ה כ) \"וַיִּתֵּן אִישׁ בָּךְ אֶת שְׁכָבְתּוֹ מִבַּלְעֲדֵי אִישֵׁךְ\" שֶׁקָּדְמָה שְׁכִיבַת בַּעַל לִשְׁכִיבַת בּוֹעֵל:","הַגִּיֹּרֶת וְהַמְשֻׁחְרֶרֶת וְאֵשֶׁת הַגֵּר וְאֵשֶׁת עֶבֶד מְשֻׁחְרָר וּמַמְזֶרֶת וְאֵשֶׁת מַמְזֵר וְאֵשֶׁת סְרִיס חַמָּה אוֹ סְרִיס אָדָם הַמֻּתָּרוֹת לְבַעְלֵיהֶן הֲרֵי הֵן כְּכָל הַנָּשִׁים וְשׁוֹתוֹת:","מְעֻבֶּרֶת וּמֵינִיקָה מְקַנֵּא לָהּ וּמַשְׁקֶה אוֹתָהּ כְּמוֹת שֶׁהִיא. אִשָּׁה הָעוֹמֶדֶת לִשְׁתּוֹת וּמֵת בַּעְלָהּ קֹדֶם שֶׁתִּשְׁתֶּה אֵינָהּ שׁוֹתָה וְלֹא נוֹטֶלֶת כְּתֻבָּתָהּ:","כָּל אִישׁ שֶׁבָּא בִּיאָה אֲסוּרָה מִיָּמָיו אַחַר שֶׁהִגְדִּיל אֵין הַמַּיִם הַמְאָרְרִים בּוֹדְקִין אֶת אִשְׁתּוֹ. וַאֲפִלּוּ בָּא עַל אֲרוּסָתוֹ בְּבֵית חָמִיו שֶׁאָסוּר מִדִּבְרֵי סוֹפְרִים אֵין הַמַּיִם בּוֹדְקִין אֶת אִשְׁתּוֹ שֶׁנֶּאֱמַר (במדבר ה לא) \"וְנִקָּה הָאִישׁ מֵעָוֹן וְהָאִשָּׁה הַהִיא תִּשָּׂא אֶת עֲוֹנָהּ\". בִּזְמַן שֶׁהָאִישׁ מְנֻקֶּה מֵעָוֹן אִשָּׁה נוֹשְׂאָה אֶת עֲוֹנָהּ:","לְפִיכָךְ אִם הָיְתָה אִשְׁתּוֹ אֲסוּרָה עָלָיו מֵחַיָּבֵי לָאוִין אוֹ מֵחַיָּבֵי עֲשֵׂה אֲפִלּוּ שְׁנִיָּה וְקִנֵּא לָהּ וְנִסְתְּרָה אֵינָהּ שׁוֹתָה אֶלָּא תֵּצֵא בְּלֹא כְּתֻבָּה וְתִהְיֶה אֲסוּרָה עָלָיו אַף מִשּׁוּם זֶה. עָבַר וְנָשָׂא מְעֻבֶּרֶת חֲבֵרוֹ וּמֵינֶקֶת חֲבֵרוֹ הֲרֵי זוֹ שׁוֹתָה שֶׁאֵין כָּאן עֲבֵרָה:","מִי שֶׁאֵין לוֹ אִשָּׁה הָרְאוּיָה לֵילֵד וְלֹא בָּנִים וְנָשָׂא עֲקָרָה אוֹ זְקֵנָה אוֹ אַיְלוֹנִית אֵינָהּ שׁוֹתָה וְלֹא נוֹטֶלֶת כְּתֻבָּה. הָיוּ לוֹ בָּנִים אוֹ אִשָּׁה אַחֶרֶת רְאוּיָה לֵילֵד הֲרֵי זֶה מַשְׁקֶה אוֹתָהּ אַף עַל פִּי שֶׁהִיא זְקֵנָה אוֹ עֲקָרָה אוֹ אַיְלוֹנִית וְאֵינָהּ רְאוּיָה לֵילֵד שֶׁלֹּא נֶאֱמַר בַּתּוֹרָה (במדבר ה כח) \"וְנִזְרְעָה זָרַע\" אֶלָּא בִּרְאוּיָה לֵילֵד שֶׁאִם הָיְתָה יוֹלֶדֶת בְּצַעַר תֵּלֵד בְּרֶוַח. הָיָה דַּרְכָּהּ לֵילֵד נְקֵבוֹת תֵּלֵד זְכָרִים:","הָיוּ לוֹ אִשָּׁה וּבָנִים וּמֵתוּ בֵּין קִנּוּי לִסְתִירָה כְּבָר נִרְאֵית לִשְׁתּוֹת וּמַשְׁקֶה אוֹתָהּ. לֹא הָיוּ לוֹ בָּנִים וְלֹא אִשָּׁה הָרְאוּיָה לֵילֵד אֶלָּא זוֹ הָאַיְלוֹנִית וְכַיּוֹצֵא בָּהּ וְנוֹלַד לוֹ בֵּן מִגְּרוּשָׁתוֹ בֵּין קִנּוּי לִסְתִירָה כְּבָר נִדְחֵית הָאַיְלוֹנִית מִלִּשְׁתּוֹת:","כָּל אִשָּׁה שֶׁהָיָה לָהּ קִנּוּי וּסְתִירָה וְלֹא שָׁתְתָה מֵי הַמָּרִים בֵּין שֶׁלֹּא רָצָה בַּעְלָהּ לְהַשְׁקוֹתָהּ בֵּין שֶׁלֹּא רָצְתָה הִיא וּבֵין שֶׁבָּא לָהּ עֵד טֻמְאָה אוֹ הוֹדֵית אוֹ הָיְתָה מֵאֵלּוּ הַנָּשִׁים שֶׁאֵינָן רְאוּיוֹת לִשְׁתּוֹת אוֹ שֶׁקִּנְּאוּ לָהּ בֵּית דִּין. הוֹאִיל וְנֶאֶסְרָה עַל בַּעְלָהּ מִכָּל מָקוֹם הֲרֵי הִיא אֲסוּרָה עַל זֶה שֶׁנִּתְיַחֲדָה עִמּוֹ לְעוֹלָם כְּדֶרֶךְ שֶׁהִיא אֲסוּרָה עַל בַּעְלָהּ. וְאִם עָבַר וּנְשָׂאָהּ מוֹצִיאִין אוֹתָהּ מִתַּחְתָּיו בְּגֵט אֲפִלּוּ הָיוּ לָהּ כַּמָּה בָּנִים מִמֶּנּוּ. מִפִּי הַשְּׁמוּעָה לָמְדוּ כְּשֵׁם שֶׁאֲסוּרָה לַבַּעַל כָּךְ אֲסוּרָה לַבּוֹעֵל:","אֲבָל אִם לֹא קָדַם קִנּוּי וּבָאוּ עָלֶיהָ עֵדִים שֶׁנִּסְתְּרָה עִם אִישׁ זֶה וּבָאוּ וּמָצְאוּ דָּבָר מְכֹעָר כְּגוֹן שֶׁנִּכְנְסוּ אַחֲרָיו וּמְצָאוּהָ חוֹגֶרֶת חֲגוֹרָה. אוֹ מָצְאוּ רֹק לְמַעְלָה מִן הַכִּילָה וְכַיּוֹצֵא בָּזֶה. אִם הוֹצִיאָהּ בַּעְלָהּ בְּדָבָר מְכֹעָר כָּזֶה הֲרֵי זוֹ לֹא תִּנָּשֵׂא לַנִּטְעָן אֶלָּא אֲסוּרָה עָלָיו. וְאִם עָבַר וּנְשָׂאָהּ וְהָיוּ לָהּ בָּנִים מִמֶּנּוּ לֹא תֵּצֵא. וְאִם לֹא הָיוּ לָהּ בָּנִים מִמֶּנּוּ תֵּצֵא:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁרִנְּנוּ הָעִיר עָלֶיהָ וְעַל הַנִּטְעָן יוֹם וּמֶחֱצָה אוֹ יוֹתֵר. וְאָמְרוּ פְּלוֹנִי זִנָּה עִם פְּלוֹנִית וְלֹא פָּסַק הַקּוֹל. וְהוּא שֶׁלֹּא הָיוּ לָהּ אוֹ לוֹ אוֹיְבִים שֶׁמַּעֲבִירִין אֶת הַקּוֹל. אֲבָל אִם לֹא הָיְתָה שָׁם רִנָּה לְדָבָר זֶה בָּעִיר אוֹ שֶׁפָּסַק הַקּוֹל שֶׁלֹּא מֵחֲמַת יִרְאָה. אִם נִשֵּׂאת לַנִּטְעָן לֹא תֵּצֵא אַף עַל פִּי שֶׁאֵין לָהּ בָּנִים. אֲפִלּוּ בָּא עֵד אֶחָד שֶׁזִּנְּתָה עִמּוֹ לֹא תֵּצֵא:","מִי שֶׁהוֹצִיאָהּ בַּעְלָהּ בְּעֵדֵי דָּבָר מְכֹעָר וְנִשֵּׂאת לְאַחֵר וְגֵרְשָׁהּ הֲרֵי זוֹ אֲסוּרָה לְהִנָּשֵׂא לַנִּטְעָן שֶׁיָּצָאתָה מִתַּחַת בַּעְלָהּ בִּגְלָלוֹ. וְאִם נִשֵּׂאת לֹא תֵּצֵא אַף עַל פִּי שֶׁאֵין לָהּ בָּנִים:","כָּל אִשָּׁה שֶׁבָּאוּ שְׁנֵי עֵדִים וְהֵעִידוּ שֶׁזִּנְּתָה עִם זֶה כְּשֶׁהָיְתָה תַּחַת בַּעְלָהּ הָרִאשׁוֹן הֲרֵי זוֹ תֵּצֵא מִזֶּה. וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ מִמֶּנּוּ כַּמָּה בָּנִים. וְכָל מָקוֹם שֶׁאָמַרְנוּ תֵּצֵא תֵּצֵא בְּלֹא כְּתֻבָּה:"]} as Record<string, string[]>;
